// Hyperrealism in p5.brush — Frozen Ice Disc, Gloved Hand, Steel Dog Bowl & 22° Solar Halo

const SX = 695, SY = 360, HR = 238; // Sun & 22° Halo center and radius
const IX = 490, IY = 635, IR = 240; // Lifted Ice Disc center and radius
const BX = 770, BY = 1055, BRX = 258, BRY = 66; // Steel Dog Bowl rim center and radii

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);

  // Register custom hyperreal pencils, frost needles, and soft pastel brushes
  brush.add("micro_2H", {
    type: "default",
    weight: 0.22,
    scatter: 0.05,
    sharpness: 0.88,
    grain: 0.35,
    opacity: 165,
    spacing: 0.15,
    pressure: [0.3, 1.0, 0.25],
    noise: 0.35
  });

  brush.add("fine_HB", {
    type: "default",
    weight: 0.35,
    scatter: 0.08,
    sharpness: 0.72,
    grain: 0.5,
    opacity: 175,
    spacing: 0.18,
    pressure: [0.4, 1.0, 0.3],
    noise: 0.45
  });

  brush.add("frost_needle", {
    type: "default",
    weight: 0.28,
    scatter: 0.04,
    sharpness: 0.94,
    grain: 0.2,
    opacity: 235,
    spacing: 0.12,
    pressure: [0.95, 0.7, 0.15],
    noise: 0.25
  });

  brush.add("soft_pastel", {
    type: "default",
    weight: 2.2,
    scatter: 0.8,
    sharpness: 0.18,
    grain: 0.65,
    opacity: 42,
    spacing: 0.35,
    pressure: [0.4, 1.0, 0.4],
    noise: 0.6
  });

  brush.add("sky_spray", {
    type: "spray",
    weight: 11,
    scatter: 5.2,
    opacity: 24,
    spacing: 0.65,
    pressure: [0.6, 1.0, 0.6]
  });

  randomSeed(7319);
  noiseSeed(7319);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Pure icy winter paper ground (serves as white-reserved highlights)
  background("#f7f9fb");
  brush.noField();

  // 1. PALE WINTER SKY & MILKY CERULEAN SPRAY GRADATION
  drawWinterSky();

  // 2. OVERHEAD 22° SOLAR HALO (INNER RUSSET, CRISP RING, OUTER LAVENDER)
  drawSolarHalo();

  // 3. BACK FINGERS OF GLOVED HAND (SEEN REFRACTED BEHIND THE ICE RIM)
  drawRefractedBackFingers();

  // 4. HYPERREAL FROZEN ICE DISC (REFRACTION, FRACTURE FEATHERS, BUBBLES, FUR STRAND, RIME)
  drawIceDisc();

  // 5. STEEL DOG BOWL AT BOTTOM (LOW ANGLE, SPECULAR REFLECTIONS & RESIDUAL ICE)
  drawSteelDogBowl();

  // 6. FALLING ICE SPLINTERS & FROZEN DROPLETS BETWEEN DISC AND BOWL
  drawFallingIceShards();

  // 7. GLOVED HAND LIFTING THE ICE DISC (FOREGROUND THUMB, CUFF & CURLED FINGERTIPS)
  drawGlovedHandForeground();

  noLoop();
}

// =============================================================================
// GEOMETRY & SAFE DRAWING HELPERS
// =============================================================================

function safeLine(x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) < 0.6) return;
  brush.line(x1, y1, x2, y2);
}

function safeSpline(pts, curv = 0.5) {
  let clean = [];
  for (let i = 0; i < pts.length; i++) {
    if (clean.length === 0 || dist(pts[i][0], pts[i][1], clean[clean.length - 1][0], clean[clean.length - 1][1]) > 0.8) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curv);
  } else if (clean.length === 2) {
    safeLine(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

function drawPolyWash(pts, col, opac) {
  if (pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opac);
  brush.beginShape(0);
  for (let p of pts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();
}

function makeCirclePoly(cx, cy, r, steps = 64) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  return pts;
}

function makeEllipsePoly(cx, cy, rx, ry, rotDeg = 0, steps = 64) {
  let pts = [];
  let c = cos(rotDeg), s = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let ex = cos(a) * rx;
    let ey = sin(a) * ry;
    pts.push([cx + ex * c - ey * s, cy + ex * s + ey * c]);
  }
  return pts;
}

function makeRingBandPoly(cx, cy, rIn, rOut, aStart, aEnd, steps = 36) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rOut, cy + sin(a) * rOut]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rIn, cy + sin(a) * rIn]);
  }
  return pts;
}

// Draws line segments clipped outside a protected circle so white-reserved paper stays pure
function drawLineOutsideCircle(x1, y1, x2, y2, cx, cy, r, steps = 28) {
  let inSeg = false;
  let sx = 0, sy = 0;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let px = lerp(x1, x2, t);
    let py = lerp(y1, y2, t);
    let outside = dist(px, py, cx, cy) > r;
    if (outside && !inSeg) {
      sx = px;
      sy = py;
      inSeg = true;
    } else if (!outside && inSeg) {
      let prevT = (i - 1) / steps;
      safeLine(sx, sy, lerp(x1, x2, prevT), lerp(y1, y2, prevT));
      inSeg = false;
    } else if (outside && i === steps && inSeg) {
      safeLine(sx, sy, px, py);
    }
  }
}

// =============================================================================
// 1. PALE WINTER SKY & MILKY CERULEAN SPRAY GRADATION
// =============================================================================

function drawWinterSky() {
  // Subtle horizontal bands of milky cerulean wash from zenith to low horizon
  const skyBands = [
    { y1: 0,   y2: 220, col: "#b4cfe4", op: 52 },
    { y1: 160, y2: 420, col: "#bfd7e9", op: 46 },
    { y1: 360, y2: 660, col: "#cce0ef", op: 40 },
    { y1: 580, y2: 900, col: "#dae9f4", op: 34 },
    { y1: 820, y2: 1200, col: "#e7f1f8", op: 28 }
  ];

  for (let b of skyBands) {
    drawPolyWash([
      [0, b.y1], [1200, b.y1], [1200, b.y2], [0, b.y2]
    ], b.col, b.op);
  }

  // Alexander's dark band inside the 22° halo (sky inside a solar halo is optically deeper cerulean)
  drawPolyWash(makeRingBandPoly(SX, SY, 68, HR - 8, 0, 360, 64), "#9bbcd6", 38);
  drawPolyWash(makeRingBandPoly(SX, SY, 110, HR - 12, 0, 360, 64), "#8db0cc", 28);

  // Soft spray gradation of milky cerulean across the sky, reserving the ice disc & sun core
  const sprayColors = ["#8eb3cf", "#9fc1da", "#b1cfe4", "#c3dced", "#d6e8f4", "#e6f1f8"];
  for (let i = 0; i < 165; i++) {
    let t = i / 164;
    let y = lerp(15, 1150, pow(t, 1.08)) + random(-12, 12);
    let colIdx = constrain(floor(t * sprayColors.length), 0, sprayColors.length - 1);
    let w = map(t, 0, 1, 1.15, 0.65);

    brush.set("sky_spray", sprayColors[colIdx], w);

    // Slight atmospheric arch across the dome of the sky
    let x1 = -20;
    let x2 = 1220;
    let yLeft = y + 18;
    let yRight = y + 12;

    // Protect the ice disc highlight core and sun glare from heavy sky spray
    drawLineOutsideCircle(x1, yLeft, x2, yRight, IX, IY, IR - 12, 32);
  }

  // Fine pastel cross-grain in the upper sky for velvety atmospheric airiness
  for (let i = 0; i < 75; i++) {
    let y = random(0, 820);
    let x1 = random(-30, 900);
    let len = random(180, 420);
    let col = y < 400 ? "#a7c6de" : "#c7deed";
    brush.set("soft_pastel", col, random(0.6, 1.1));
    drawLineOutsideCircle(x1, y, x1 + len, y + random(-14, 14), IX, IY, IR - 6, 20);
  }
}

// =============================================================================
// 2. OVERHEAD 22° SOLAR HALO & WINTER SUN
// =============================================================================

function drawSolarHalo() {
  // Outer Lavender Halo Ring (r = 248 to 282)
  for (let a = 0; a < 360; a += 60) {
    drawPolyWash(makeRingBandPoly(SX, SY, HR + 8, HR + 38, a, a + 62, 16), "#cfc7e6", 34);
  }

  // Inner Russet Halo Ring (r = 222 to 237)
  for (let a = 0; a < 360; a += 60) {
    drawPolyWash(makeRingBandPoly(SX, SY, HR - 15, HR - 1, a, a + 62, 16), "#dfb0a3", 38);
  }

  // Crisp Luminous White-Cream Halo Peak (r = 236 to 249)
  for (let a = 0; a < 360; a += 45) {
    drawPolyWash(makeRingBandPoly(SX, SY, HR - 2, HR + 10, a, a + 46, 14), "#fbfcfe", 110);
  }

  // Parhelic Circle (faint horizontal ice-crystal light beam passing through the sun)
  for (let i = 0; i < 18; i++) {
    let yOff = random(-14, 14);
    let py = SY + yOff;
    brush.set("soft_pastel", abs(yOff) < 5 ? "#fafcfe" : "#dce6f2", map(abs(yOff), 0, 14, 1.1, 0.4));
    drawLineOutsideCircle(80, py + 12, 1160, py - 8, IX, IY, IR, 28);
  }

  // Concentric fine pastel and colored-pencil arcs building the halo's optical crispness
  // 1) Inner Russet edge (sharpest color boundary in a real 22° halo)
  const russetTones = ["#c98574", "#d69888", "#e1ada0", "#ebd6cd"];
  for (let i = 0; i < 68; i++) {
    let r = random(HR - 16, HR - 1);
    let a1 = random(0, 360);
    let span = random(28, 85);
    let a2 = a1 + span;

    // Skip arcs that fall deeply inside the ice disc (those will be drawn refracted!)
    let midA = (a1 + a2) * 0.5;
    let mx = SX + cos(midA) * r;
    let my = SY + sin(midA) * r;
    if (dist(mx, my, IX, IY) < IR - 8) continue;

    let col = russetTones[floor(map(r, HR - 16, HR - 1, 0, russetTones.length - 0.01))];
    brush.set(i % 2 === 0 ? "cpencil" : "soft_pastel", col, i % 2 === 0 ? 0.45 : 0.75);
    brush.arc(SX, SY, r, a1, a2);
  }

  // 2) Crisp White-Reserved / Ice-Cream Peak Ring
  for (let i = 0; i < 65; i++) {
    let r = random(HR - 2, HR + 10);
    let a1 = random(0, 360);
    let a2 = a1 + random(30, 95);
    let midA = (a1 + a2) * 0.5;
    if (dist(SX + cos(midA) * r, SY + sin(midA) * r, IX, IY) < IR - 8) continue;

    brush.set("frost_needle", i % 3 === 0 ? "#ffffff" : "#f7fafd", random(0.8, 1.5));
    brush.arc(SX, SY, r, a1, a2);
  }

  // 3) Outer Lavender Dispersion Ring
  const lavenderTones = ["#dcd5ed", "#cec5e4", "#bfb4da", "#d5d3eb"];
  for (let i = 0; i < 75; i++) {
    let r = random(HR + 9, HR + 40);
    let a1 = random(0, 360);
    let a2 = a1 + random(28, 90);
    let midA = (a1 + a2) * 0.5;
    if (dist(SX + cos(midA) * r, SY + sin(midA) * r, IX, IY) < IR - 8) continue;

    let col = lavenderTones[floor(random(lavenderTones.length))];
    brush.set(i % 2 === 0 ? "cpencil" : "soft_pastel", col, i % 2 === 0 ? 0.42 : 0.85);
    brush.arc(SX, SY, r, a1, a2);
  }

  // Left & Right Sundogs (Parhelia thickenings at 3 o'clock and 9 o'clock on the halo)
  const sundogAngles = [0, 180];
  for (let sa of sundogAngles) {
    for (let i = 0; i < 24; i++) {
      let aSpread = random(-11, 11);
      let r = random(HR - 12, HR + 22);
      let col = r < HR - 2 ? "#d89280" : (r < HR + 8 ? "#ffffff" : "#c2b6de");
      brush.set("cpencil", col, random(0.45, 0.85));
      brush.arc(SX, SY, r, sa + aSpread - 6, sa + aSpread + 6);
    }
  }

  // Faint Upper Tangent Arc at the top of the halo (270 degrees)
  for (let i = 0; i < 26; i++) {
    let pts = [];
    let yShift = random(-4, 6);
    for (let xOff = -125; xOff <= 125; xOff += 25) {
      let px = SX + xOff;
      let py = (SY - HR + yShift) - pow(abs(xOff) / 95, 1.8) * 14 + pow(abs(xOff) / 60, 2) * 4;
      pts.push([px, py]);
    }
    let col = yShift > 2 ? "#d99b8b" : (yShift > -1 ? "#ffffff" : "#cbc1e3");
    brush.set("cpencil", col, 0.4);
    safeSpline(pts, 0.5);
  }

  // Winter Sun Core & Ciliary Glare Rays at (SX, SY)
  drawPolyWash(makeCirclePoly(SX, SY, 82, 48), "#f5f6f4", 65);
  drawPolyWash(makeCirclePoly(SX, SY, 54, 48), "#fffcf5", 130);
  drawPolyWash(makeCirclePoly(SX, SY, 30, 36), "#ffffff", 235);

  // Delicate solar corona spikes in fine pencil & white needle
  for (let i = 0; i < 110; i++) {
    let a = random(360);
    let r1 = random(14, 34);
    let r2 = r1 + random(25, 115) * (i % 5 === 0 ? 1.5 : 0.8);
    let col = i % 3 === 0 ? "#ffffff" : (i % 3 === 1 ? "#f3e5d8" : "#d8e4ee");
    brush.set(i % 3 === 0 ? "frost_needle" : "micro_2H", col, random(0.4, 0.95));
    safeLine(SX + cos(a) * r1, SY + sin(a) * r1, SX + cos(a) * r2, SY + sin(a) * r2);
  }
}

// =============================================================================
// 3. BACK FINGERS OF GLOVED HAND (REFRACTED THROUGH LEFT ICE RIM)
// =============================================================================

function drawRefractedBackFingers() {
  // The index, middle, and ring fingers grip behind the left edge of the ice disc.
  // Seen through 24mm of frosted ice, they appear softened, slightly displaced, and tinted glacial blue.
  const backFingers = [
    // Index finger behind upper-left rim
    [[245, 595], [315, 578], [348, 595], [342, 622], [260, 635]],
    // Middle finger behind mid-left rim
    [[242, 645], [332, 635], [362, 652], [355, 682], [255, 692]],
    // Ring finger behind lower-left rim
    [[265, 705], [348, 698], [372, 718], [362, 746], [282, 752]],
    // Little finger supporting lower rim
    [[305, 765], [375, 758], [395, 778], [380, 804], [322, 808]]
  ];

  for (let fPts of backFingers) {
    drawPolyWash(fPts, "#9aa3ad", 65);
    drawPolyWash(fPts, "#8da4b5", 45);
  }
}

// =============================================================================
// 4. HYPERREAL FROZEN ICE DISC
// =============================================================================

function drawIceDisc() {
  // 4A. 3D Beveled Under-Rim of the Ice Slab (seen from low angle)
  // Because the bowl is tapered, the bottom edge of the frozen slab is offset toward (IX+13, IY+17)
  const BX_ICE = IX + 13;
  const BY_ICE = IY + 17;
  const BR_ICE = IR - 5;

  // Build the crescent bevel polygon along the lower-right & bottom edge (-45° to 155°)
  let bevelPts = [];
  for (let a = -45; a <= 155; a += 4) {
    bevelPts.push([IX + cos(a) * IR, IY + sin(a) * IR]);
  }
  for (let a = 155; a >= -45; a -= 4) {
    bevelPts.push([BX_ICE + cos(a) * BR_ICE, BY_ICE + sin(a) * BR_ICE]);
  }
  drawPolyWash(bevelPts, "#8aa4b8", 85);
  drawPolyWash(bevelPts, "#c2d6e4", 55);

  // 4B. Pure White-Reserved Paper Base inside the Ice Disc + Translucent Glacial Pockets
  // First restore luminous white paper in the highlight & frost zones of the disc
  drawPolyWash(makeCirclePoly(IX, IY, IR, 72), "#f7f9fb", 165);

  // Translucent glacial blue-grey internal shadows (leaving white reserves between them)
  const iceTonePockets = [
    { a1: -15, a2: 45,  r1: 55,  r2: 205, col: "#b6cede", op: 52 },
    { a1: 50,  a2: 118, r1: 40,  r2: 215, col: "#9fbcd0", op: 58 },
    { a1: 125, a2: 195, r1: 65,  r2: 205, col: "#a7c2d6", op: 48 },
    { a1: 205, a2: 265, r1: 50,  r2: 195, col: "#bfd4e3", op: 42 },
    { a1: 275, a2: 340, r1: 45,  r2: 185, col: "#cde0ec", op: 36 }
  ];
  for (let p of iceTonePockets) {
    drawPolyWash(makeRingBandPoly(IX, IY, p.r1, p.r2, p.a1, p.a2, 20), p.col, p.op);
  }

  // 4C. Refracted Solar Halo Passing Through the Upper-Right Quadrant of the Ice Disc!
  // The halo arc centered at (SX, SY) intersects the ice disc between angles 112° and 172° around the sun.
  // Ice refraction (n = 1.31) shifts and disperses the russet & lavender bands inside the disc.
  for (let i = 0; i < 52; i++) {
    let rHalo = random(HR - 24, HR + 28);
    // Refraction inward shift of ~14px inside the ice lens
    let rRefracted = rHalo - 14;
    let aStart = random(112, 148);
    let aEnd = aStart + random(14, 28);

    // Clip to inside of ice disc
    let pts = [];
    for (let a = aStart; a <= aEnd; a += 2) {
      let px = SX + cos(a) * rRefracted;
      let py = SY + sin(a) * rRefracted;
      if (dist(px, py, IX, IY) < IR - 6) {
        pts.push([px, py]);
      }
    }
    if (pts.length >= 3) {
      let col = rHalo < HR - 4 ? "#d99482" : (rHalo < HR + 8 ? "#ffffff" : "#bfb4dc");
      brush.set(rHalo >= HR - 4 && rHalo < HR + 8 ? "frost_needle" : "soft_pastel", col, 0.95);
      safeSpline(pts, 0.4);
    }
  }

  // 4D. Fine Pencil Tonal Shading of the Ice Matrix (2H & Micro_2H)
  // Carefully hatched around white-reserved channels so internal highlights gleam
  const hatchZones = [
    { cx: IX + 45, cy: IY + 35, rx: 85, ry: 55, ang: 28,  col: "#6e8ba1", spacing: 3.2 },
    { cx: IX - 35, cy: IY + 65, rx: 90, ry: 58, ang: -32, col: "#5d7b92", spacing: 3.0 },
    { cx: IX - 65, cy: IY - 35, rx: 82, ry: 62, ang: 52,  col: "#6b889e", spacing: 3.4 },
    { cx: IX + 25, cy: IY - 75, rx: 78, ry: 50, ang: -18, col: "#7c98ad", spacing: 3.6 },
    { cx: IX + 85, cy: IY - 10, rx: 68, ry: 65, ang: 68,  col: "#738fa5", spacing: 3.4 },
    { cx: IX - 15, cy: IY + 115, rx: 88, ry: 42, ang: 12, col: "#55738a", spacing: 2.8 }
  ];

  for (let z of hatchZones) {
    let ca = cos(z.ang), sa = sin(z.ang);
    for (let d = -z.ry; d <= z.ry; d += z.spacing) {
      let halfW = z.rx * sqrt(max(0, 1 - sq(d / z.ry)));
      // Break each hatch line around a white-reserved gap to mimic refractive ice facets
      let gapMid = sin(d * 8 + z.ang) * halfW * 0.35;
      let gapHalf = random(6, 16);

      let x1 = z.cx + (-halfW) * ca - d * sa;
      let y1 = z.cy + (-halfW) * sa + d * ca;
      let xm1 = z.cx + (gapMid - gapHalf) * ca - d * sa;
      let ym1 = z.cy + (gapMid - gapHalf) * sa + d * ca;

      let xm2 = z.cx + (gapMid + gapHalf) * ca - d * sa;
      let ym2 = z.cy + (gapMid + gapHalf) * sa + d * ca;
      let x2 = z.cx + (halfW) * ca - d * sa;
      let y2 = z.cy + (halfW) * sa + d * ca;

      brush.set("micro_2H", z.col, random(0.65, 1.05));
      if (dist(x1, y1, IX, IY) < IR - 10 && dist(xm1, ym1, IX, IY) < IR - 10) {
        safeLine(x1, y1, xm1, ym1);
      }
      if (dist(xm2, ym2, IX, IY) < IR - 10 && dist(x2, y2, IX, IY) < IR - 10) {
        safeLine(xm2, ym2, x2, y2);
      }
    }
  }

  // 4E. Radiating Fracture Feathers (Internal Cleavage Plumes with White-Reserved Ribs)
  drawAllFractureFeathers();

  // 4F. Central Freeze Core & Radial Tubular "Ice Worm" Bubbles
  drawTubularBubblesAndCore();

  // 4G. Crystalline Frost Rime & Outer Meniscus Dendrites
  drawFrostRimeAndEdge(BX_ICE, BY_ICE, BR_ICE);

  // 4H. Trapped Spherical Air Bubbles (Deep Out-of-Focus + Crisp Focal Plane)
  drawTrappedSphericalBubbles();

  // 4I. Trapped Dog Fur Strand (with Refractive White Sheath & Nucleated Micro-Bubbles)
  drawTrappedFurStrand();
}

function drawAllFractureFeathers() {
  // Primary radiating fracture plumes from the central freeze-stress node (IX-12, IY+12)
  // and from the thumb-pressure point (IX-135, IY+32)
  const feathers = [
    { sx: IX - 12, sy: IY + 12, ang: -68, len: 205, curv: 26,  barbs: 58, side: 1,  bLen: 34, tint: "#d69888" },
    { sx: IX - 12, sy: IY + 12, ang: -24, len: 215, curv: -22, barbs: 62, side: -1, bLen: 38, tint: "#c2b6dc" },
    { sx: IX - 12, sy: IY + 12, ang: 18,  len: 210, curv: 28,  barbs: 56, side: 1,  bLen: 32, tint: "#7a98ae" },
    { sx: IX - 12, sy: IY + 12, ang: 64,  len: 198, curv: -24, barbs: 52, side: -1, bLen: 35, tint: "#6c899f" },
    { sx: IX - 12, sy: IY + 12, ang: 112, len: 192, curv: 22,  barbs: 50, side: 1,  bLen: 30, tint: "#5b788e" },
    { sx: IX - 12, sy: IY + 12, ang: 154, len: 188, curv: -18, barbs: 48, side: -1, bLen: 28, tint: "#68859b" },
    { sx: IX - 12, sy: IY + 12, ang: 205, len: 195, curv: 24,  barbs: 52, side: 1,  bLen: 32, tint: "#7996ac" },
    { sx: IX - 12, sy: IY + 12, ang: 248, len: 208, curv: -20, barbs: 55, side: -1, bLen: 34, tint: "#c7bedf" },
    // Secondary stress feathers radiating inward from the thumb grip on the lower-left rim
    { sx: IX - 142, sy: IY + 28, ang: -12, len: 145, curv: 18,  barbs: 42, side: -1, bLen: 24, tint: "#5a768c" },
    { sx: IX - 142, sy: IY + 28, ang: 34,  len: 135, curv: -16, barbs: 38, side: 1,  bLen: 22, tint: "#4e6a80" },
    { sx: IX - 142, sy: IY + 28, ang: -48, len: 130, curv: -15, barbs: 36, side: 1,  bLen: 22, tint: "#6e8a9f" }
  ];

  for (let f of feathers) {
    drawSingleFractureFeather(f);
  }
}

function drawSingleFractureFeather(f) {
  let spinePts = [];
  let spineShadowPts = [];
  let steps = 20;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let curAng = f.ang + sin(t * 180) * f.curv;
    let r = t * f.len;
    let px = f.sx + cos(curAng) * r;
    let py = f.sy + sin(curAng) * r;

    if (dist(px, py, IX, IY) < IR - 8) {
      spinePts.push([px, py]);
      let nx = -sin(curAng) * 1.6 * f.side;
      let ny = cos(curAng) * 1.6 * f.side;
      spineShadowPts.push([px + nx, py + ny]);
    }
  }

  // 1) Crisp dark graphite cleavage line along the fracture spine
  brush.set("micro_2H", "#395165", 1.05);
  safeSpline(spineShadowPts, 0.5);

  // 2) Pure white-reserved highlight ridge immediately beside the graphite spine
  brush.set("frost_needle", "#ffffff", 1.25);
  safeSpline(spinePts, 0.5);

  // 3) Feathery hackle barbs curving off the main spine
  for (let b = 2; b < f.barbs; b++) {
    let t = b / f.barbs;
    let curAng = f.ang + sin(t * 180) * f.curv;
    let r = t * f.len;
    let bx = f.sx + cos(curAng) * r;
    let by = f.sy + sin(curAng) * r;

    if (dist(bx, by, IX, IY) > IR - 14) continue;

    // Envelope of feather width: swells in the middle, tapers at root and tip
    let env = sin(t * 180) * (0.65 + 0.35 * noise(b * 0.25, f.ang));
    let barbLen = f.bLen * env;
    if (barbLen < 4) continue;

    let barbAng = curAng + f.side * (38 + t * 24);
    let midAng = barbAng + f.side * 14;
    let tipAng = barbAng + f.side * 28;

    let mx = bx + cos(midAng) * (barbLen * 0.52);
    let my = by + sin(midAng) * (barbLen * 0.52);
    let tx = bx + cos(tipAng) * barbLen;
    let ty = by + sin(tipAng) * barbLen;

    if (dist(tx, ty, IX, IY) > IR - 10) continue;

    // Offset vector for pairing pencil shadow + white reserve
    let ox = -sin(midAng) * 1.25;
    let oy = cos(midAng) * 1.25;

    // Fine pencil shadow side of the feather barb
    let darkCol = b % 4 === 0 ? "#374f63" : (b % 2 === 0 ? "#516c82" : f.tint);
    brush.set("micro_2H", darkCol, random(0.65, 1.0));
    safeSpline([[bx + ox, by + oy], [mx + ox, my + oy], [tx + ox, ty + oy]], 0.45);

    // White-reserved highlight rib of the feather barb
    brush.set("frost_needle", "#ffffff", random(0.85, 1.3));
    safeSpline([[bx, by], [mx, my], [tx, ty]], 0.45);
  }
}

function drawTubularBubblesAndCore() {
  // Cloudy last-to-freeze central core around (IX + 8, IY - 4)
  const coreX = IX + 8, coreY = IY - 4;
  drawPolyWash(makeCirclePoly(coreX, coreY, 44, 36), "#ffffff", 130);

  // Dense micro-crystalline cross-striae in the central freeze core
  for (let i = 0; i < 95; i++) {
    let a = random(360);
    let d = random(2, 46);
    let len = random(6, 22);
    let px = coreX + cos(a) * d;
    let py = coreY + sin(a) * d;
    let strokeA = a + random(-35, 35);

    brush.set("micro_2H", i % 2 === 0 ? "#5a758a" : "#7c96aa", 0.65);
    safeLine(px, py, px + cos(strokeA) * len, py + sin(strokeA) * len);

    brush.set("frost_needle", "#ffffff", 0.95);
    safeLine(px + 1, py - 1, px + 1 + cos(strokeA) * len, py - 1 + sin(strokeA) * len);
  }

  // Radial Tubular "Ice Worm" Bubbles (elongated air tracks pushed inward during freezing)
  for (let i = 0; i < 82; i++) {
    let a = (i / 82) * 360 + random(-2.2, 2.2);
    let rOuter = random(95, 202);
    let tubeLen = random(14, 38);
    let rInner = rOuter - tubeLen;

    let xOut = coreX + cos(a) * rOuter;
    let yOut = coreY + sin(a) * rOuter;
    let xIn = coreX + cos(a) * rInner;
    let yIn = coreY + sin(a) * rInner;

    if (dist(xOut, yOut, IX, IY) > IR - 18) continue;

    // Perpendicular vector for tubular thickness (~2.2px)
    let nx = -sin(a) * 1.15;
    let ny = cos(a) * 1.15;

    // Shadow edge (away from sun at upper-right)
    brush.set("micro_2H", "#344c60", 0.85);
    safeLine(xOut - nx, yOut - ny, xIn - nx, yIn - ny);

    // Translucent interior line
    brush.set("micro_2H", "#7c98ad", 0.7);
    safeLine(xOut, yOut, xIn, yIn);

    // White-reserved highlight edge + bright bulb head at inner end
    brush.set("frost_needle", "#ffffff", 1.15);
    safeLine(xOut + nx, yOut + ny, xIn + nx, yIn + ny);
    brush.set("micro_2H", "#2c4356", 0.75);
    brush.circle(xIn, yIn, 1.8, 0.1);
  }
}

function drawFrostRimeAndEdge(BX_ICE, BY_ICE, BR_ICE) {
  // 1) 3D Beveled Rim Flutes (vertical freeze striations connecting top and bottom rims of the slab)
  for (let a = -42; a <= 152; a += 1.8) {
    let x1 = IX + cos(a) * IR;
    let y1 = IY + sin(a) * IR;
    let x2 = BX_ICE + cos(a) * BR_ICE;
    let y2 = BY_ICE + sin(a) * BR_ICE;

    // Alternate dark refractive flutes and bright white-reserved specular ribs
    if (floor((a + 50) * 1.5) % 3 === 0) {
      brush.set("frost_needle", "#ffffff", 1.15);
    } else if (floor((a + 50) * 1.5) % 3 === 1) {
      let col = (a > -25 && a < 45) ? "#cfa094" : "#445e73";
      brush.set("micro_2H", col, 0.85);
    } else {
      brush.set("micro_2H", "#6e899e", 0.75);
    }
    safeLine(x1, y1, x2, y2);
  }

  // Outer contour of the beveled bottom edge
  for (let a = -42; a < 150; a += 18) {
    brush.set("fine_HB", "#354c60", 0.85);
    brush.arc(BX_ICE, BY_ICE, BR_ICE, a, a + 19);
  }

  // 2) Dendritic Frost Rime & Acicular Ice Needles around the Perimeter Meniscus (r = 206..240)
  for (let i = 0; i < 240; i++) {
    let a = (i / 240) * 360 + random(-0.8, 0.8);
    let needleLen = random(12, 36) * (0.65 + 0.55 * noise(cos(a) * 2, sin(a) * 2));
    let r1 = IR - random(1, 5);
    let r2 = r1 - needleLen;

    let x1 = IX + cos(a) * r1;
    let y1 = IY + sin(a) * r1;
    let aIn = a + random(-8, 8);
    let x2 = IX + cos(aIn) * r2;
    let y2 = IY + sin(aIn) * r2;

    // Graphite crevice between frost needles
    if (i % 2 === 0) {
      brush.set("micro_2H", "#486277", random(0.6, 0.95));
      safeLine(x1 + 1.2, y1 + 1.2, x2 + 1.2, y2 + 1.2);
    }

    // Crisp white frost needle
    brush.set("frost_needle", "#ffffff", random(0.9, 1.4));
    safeLine(x1, y1, x2, y2);

    // Fern-like side barbs on larger frost dendrites
    if (needleLen > 24 && i % 3 === 0) {
      for (let k = 1; k <= 3; k++) {
        let bt = k / 4;
        let bx = lerp(x1, x2, bt);
        let by = lerp(y1, y2, bt);
        let bSide = (k % 2 === 0 ? 1 : -1) * 38;
        let bLen = (1 - bt) * 11;
        brush.set("frost_needle", "#ffffff", 0.9);
        safeLine(bx, by, bx + cos(aIn + 180 + bSide) * bLen, by + sin(aIn + 180 + bSide) * bLen);
      }
    }
  }

  // 3) Surface Frost Rime Patches (feathery hoarfrost blooms across the face of the disc)
  const rimeCenters = [
    { x: IX - 115, y: IY - 125, r: 42 },
    { x: IX + 135, y: IY - 95,  r: 38 },
    { x: IX + 145, y: IY + 75,  r: 44 },
    { x: IX - 45,  y: IY + 155, r: 40 },
    { x: IX - 155, y: IY - 15,  r: 36 }
  ];

  for (let rc of rimeCenters) {
    for (let j = 0; j < 34; j++) {
      let a = random(360);
      let d1 = random(0, rc.r * 0.45);
      let d2 = d1 + random(10, rc.r * 0.75);
      let x1 = rc.x + cos(a) * d1;
      let y1 = rc.y + sin(a) * d1;
      let x2 = rc.x + cos(a + random(-12, 12)) * d2;
      let y2 = rc.y + sin(a + random(-12, 12)) * d2;
      if (dist(x2, y2, IX, IY) < IR - 4) {
        brush.set("micro_2H", "#637f94", 0.55);
        safeLine(x1 + 1, y1 + 1, x2 + 1, y2 + 1);
        brush.set("frost_needle", "#ffffff", 1.05);
        safeLine(x1, y1, x2, y2);
      }
    }
  }

  // 4) Main Circular Rim Contour of the Ice Disc (sharp graphite shadow + dazzling sunlit upper-right edge)
  for (let a = 0; a < 360; a += 15) {
    let isSunward = (a > 245 || a < 55);
    brush.set("micro_2H", isSunward ? "#587389" : "#2d4356", isSunward ? 0.85 : 1.15);
    brush.arc(IX, IY, IR, a, a + 15.5);

    brush.set("frost_needle", "#ffffff", isSunward ? 1.65 : 1.1);
    brush.arc(IX, IY, IR - 1.8, a, a + 15.5);
  }
}

function drawTrappedSphericalBubbles() {
  // Layer 1: 115 Deep Out-of-Focus Bubbles suspended lower in the ice slab
  for (let i = 0; i < 115; i++) {
    let a = random(360);
    let d = pow(random(), 0.72) * (IR - 24);
    let bx = IX + cos(a) * d;
    let by = IY + sin(a) * d;
    let br = random(1.8, 6.5);

    brush.set("2H", "#7c97ac", 0.5);
    brush.circle(bx, by, br, 0.15);
    brush.set("frost_needle", "#f5f9fc", 0.7);
    brush.arc(bx, by, max(1.2, br * 0.7), 270, 360);
  }

  // Layer 2: 95 Hyper-Sharp Focal-Plane Spherical & Coalesced Disc Bubbles
  for (let i = 0; i < 95; i++) {
    let a = random(360);
    // Cluster bubbles more densely near the central freeze zone and along spiral eddies
    let d = pow(random(), 0.88) * (IR - 22);
    let bx = IX + cos(a) * d;
    let by = IY + sin(a) * d;

    // Avoid overlapping right on top of the fur strand window
    if (bx > IX + 35 && bx < IX + 145 && by > IY - 35 && by < IY + 65 && i % 3 !== 0) continue;

    let br = i < 14 ? random(7.5, 13.5) : (i < 42 ? random(4.0, 7.2) : random(1.8, 3.8));

    // Pure white-reserved interior core on larger bubbles
    if (br > 4.5) {
      drawPolyWash(makeCirclePoly(bx + br * 0.15, by - br * 0.15, br * 0.75, 18), "#ffffff", 180);
      drawPolyWash(makeCirclePoly(bx - br * 0.2, by + br * 0.2, br * 0.65, 18), "#5a768c", 85);
    }

    // Crisp outer dark refraction ring
    brush.set("micro_2H", "#293e50", br > 6 ? 0.95 : 0.75);
    brush.circle(bx, by, br, 0.08);

    // Internal dark crescent shadow on the lower-left (away from overhead-right sun)
    if (br > 3.0) {
      brush.set("micro_2H", "#3d566b", 0.85);
      brush.arc(bx, by, br * 0.78, 105, 255);
    }

    // Dazzling white-reserved highlight crescent facing the sun (285° to 75°)
    brush.set("frost_needle", "#ffffff", br > 6 ? 1.35 : 0.95);
    brush.arc(bx, by, max(1.2, br * 0.82), 285, 425);

    // Pinpoint specular catchlight dot inside
    if (br > 4.0) {
      let gx = bx + cos(-38) * (br * 0.45);
      let gy = by + sin(-38) * (br * 0.45);
      brush.set("frost_needle", "#ffffff", 1.5);
      safeLine(gx, gy, gx + 1.2, gy - 1.0);
    }
  }
}

function drawTrappedFurStrand() {
  // A single coarse dog guard hair trapped mid-depth in a clear window of the ice disc
  // Curves gracefully from (IX + 42, IY + 58) up-right to (IX + 138, IY - 28)
  const hairPts = [
    [IX + 42,  IY + 58],
    [IX + 64,  IY + 44],
    [IX + 88,  IY + 22],
    [IX + 108, IY - 4],
    [IX + 125, IY - 19],
    [IX + 138, IY - 28]
  ];

  // 1) Faint blurry shadow of the hair cast 5.5px deeper onto an internal ice plane
  let shadowPts = hairPts.map(p => [p[0] + 4.5, p[1] + 5.5]);
  brush.set("2H", "#688399", 0.65);
  safeSpline(shadowPts, 0.5);

  // 2) Crisp white-reserved refractive air-sheath around the frozen hair shaft
  let sheathUpper = hairPts.map(p => [p[0] - 1.3, p[1] - 1.3]);
  let sheathLower = hairPts.map(p => [p[0] + 1.3, p[1] + 1.3]);
  brush.set("frost_needle", "#ffffff", 1.45);
  safeSpline(sheathUpper, 0.5);
  safeSpline(sheathLower, 0.5);

  // 3) Warm russet-ochre edge of the guard hair catching transmitted sunlight
  let warmPts = hairPts.map(p => [p[0] - 0.5, p[1] - 0.5]);
  brush.set("micro_2H", "#8f583e", 0.85);
  safeSpline(warmPts, 0.5);

  // 4) Razor-sharp dark sepia/umber core of the dog hair (tapering toward the tip)
  brush.set("micro_2H", "#241914", 1.1);
  safeSpline(hairPts, 0.5);

  // Tiny pale keratin root bulb at the base of the shed dog hair (IX + 42, IY + 58)
  brush.set("micro_2H", "#4a382e", 0.9);
  brush.circle(IX + 41, IY + 59, 1.9, 0.05);
  brush.set("frost_needle", "#ffffff", 1.1);
  safeLine(IX + 40, IY + 58, IX + 42, IY + 57);

  // 5) 8 tiny nucleated air bubbles clinging directly like pearls along the fur strand
  const hairBubbles = [
    { t: 0.14, side: -1, r: 2.4 },
    { t: 0.26, side: 1,  r: 3.6 },
    { t: 0.38, side: -1, r: 2.1 },
    { t: 0.51, side: 1,  r: 4.1 },
    { t: 0.63, side: -1, r: 2.8 },
    { t: 0.74, side: 1,  r: 2.2 },
    { t: 0.85, side: -1, r: 3.1 },
    { t: 0.93, side: 1,  r: 1.7 }
  ];

  for (let hb of hairBubbles) {
    let idx = hb.t * (hairPts.length - 1);
    let i0 = floor(idx), i1 = min(hairPts.length - 1, i0 + 1);
    let frac = idx - i0;
    let hx = lerp(hairPts[i0][0], hairPts[i1][0], frac);
    let hy = lerp(hairPts[i0][1], hairPts[i1][1], frac);

    let bx = hx + hb.side * (hb.r * 0.85) * 0.7;
    let by = hy - hb.side * (hb.r * 0.85) * 0.7;

    brush.set("micro_2H", "#283c4f", 0.8);
    brush.circle(bx, by, hb.r, 0.05);
    brush.set("frost_needle", "#ffffff", 1.15);
    brush.arc(bx, by, max(1.0, hb.r * 0.75), 280, 410);
  }
}

// =============================================================================
// 5. STEEL DOG BOWL AT BOTTOM (LOW ANGLE PERSPECTIVE)
// =============================================================================

function drawSteelDogBowl() {
  // Seen from a low angle at the bottom-right:
  // Top rim ellipse at (BX, BY) with radii (BRX=258, BRY=66), tilted by -4 degrees.
  // Flared base ellipse at (BX + 8, BY + 145) with radii (338, 86), tilted by -4 degrees.
  const rot = -4;
  const c = cos(rot), s = sin(rot);
  const baseCX = BX + 8, baseCY = BY + 145;
  const baseRX = 338, baseRY = 86;

  function rimPt(angleDeg, rxScale = 1, ryScale = 1) {
    let ex = cos(angleDeg) * BRX * rxScale;
    let ey = sin(angleDeg) * BRY * ryScale;
    return [BX + ex * c - ey * s, BY + ex * s + ey * c];
  }

  function basePt(angleDeg, rxScale = 1, ryScale = 1) {
    let ex = cos(angleDeg) * baseRX * rxScale;
    let ey = sin(angleDeg) * baseRY * ryScale;
    return [baseCX + ex * c - ey * s, baseCY + ex * s + ey * c];
  }

  // 5A. Outer Flared Stainless Steel Wall (front half of cone from angle -8° to 188°)
  // Divide into vertical reflective zones for hyperreal cylindrical chrome/steel reflection
  const steelBands = [
    { a1: -8,  a2: 18,  col: "#647587", op: 195 },
    { a1: 16,  a2: 42,  col: "#b6cbe0", op: 195 },
    { a1: 40,  a2: 64,  col: "#e6eff6", op: 210 },
    { a1: 62,  a2: 92,  col: "#475666", op: 205 },
    { a1: 90,  a2: 116, col: "#7c8d9e", op: 195 },
    { a1: 114, a2: 138, col: "#eef5fa", op: 220 }, // Primary sunlit specular column
    { a1: 136, a2: 158, col: "#c5b9d4", op: 185 }, // Faint lavender/russet sky reflection
    { a1: 156, a2: 174, col: "#546373", op: 205 },
    { a1: 172, a2: 188, col: "#8da1b5", op: 195 }
  ];

  for (let sb of steelBands) {
    let pts = [];
    for (let a = sb.a1; a <= sb.a2; a += 3) pts.push(rimPt(a));
    for (let a = sb.a2; a >= sb.a1; a -= 3) pts.push(basePt(a));
    drawPolyWash(pts, sb.col, sb.op);
  }

  // Dense vertical frustum reflection strokes across the flared steel wall
  for (let a = -6; a <= 186; a += 0.9) {
    let pTop = rimPt(a);
    let pBot = basePt(a);

    // Determine metallic tone from cylindrical reflection function
    let col = "#6c7d8e";
    let bName = "fine_HB";
    let w = 0.85;

    if (a > 116 && a < 136) {
      col = (a > 122 && a < 131) ? "#ffffff" : "#e8f1f8";
      bName = "frost_needle";
      w = 1.3;
    } else if (a > 42 && a < 62) {
      col = (a > 48 && a < 56) ? "#ffffff" : "#dce8f2";
      bName = "frost_needle";
      w = 1.15;
    } else if ((a >= 64 && a <= 90) || (a >= 158 && a <= 173)) {
      col = (a > 72 && a < 84) ? "#313e4b" : "#495868";
      bName = "fine_HB";
      w = 0.95;
    } else if (a >= 136 && a < 158) {
      col = a < 147 ? "#cfb2a8" : "#beb6d2";
      bName = "cpencil";
      w = 0.75;
    } else {
      col = a % 2 < 1 ? "#8aa0b4" : "#a8bdd0";
      bName = "micro_2H";
      w = 0.85;
    }

    brush.set(bName, col, w);
    safeLine(pTop[0], pTop[1], pBot[0], pBot[1]);
  }

  // Horizontal spun-steel micro-brushing ellipses across the outer bowl wall
  for (let t = 0.06; t <= 0.92; t += 0.045) {
    let pts = [];
    for (let a = -4; a <= 184; a += 6) {
      let pr = rimPt(a);
      let pb = basePt(a);
      pts.push([lerp(pr[0], pb[0], t), lerp(pr[1], pb[1], t)]);
    }
    let col = (t * 20) % 3 < 1 ? "#ffffff" : ((t * 20) % 3 < 2 ? "#425160" : "#8094a8");
    brush.set(col === "#ffffff" ? "frost_needle" : "micro_2H", col, 0.65);
    safeSpline(pts, 0.4);
  }

  // Rubber Anti-Skid Base Ring at the bottom of the dog bowl
  let rubberPts = [];
  for (let a = -6; a <= 186; a += 4) rubberPts.push(basePt(a, 1.0, 0.95));
  for (let a = 186; a >= -6; a -= 4) rubberPts.push(basePt(a, 1.01, 1.12));
  drawPolyWash(rubberPts, "#2d343c", 220);

  for (let a = -4; a <= 184; a += 2.2) {
    let p1 = basePt(a, 1.0, 0.95);
    let p2 = basePt(a, 1.01, 1.12);
    brush.set("fine_HB", floor(a) % 4 === 0 ? "#525b66" : "#232930", 0.9);
    safeLine(p1[0], p1[1], p2[0], p2[1]);
  }

  // 5B. Concave Interior of the Dog Bowl (reversed metallic reflection)
  const innerBands = [
    { a1: 180, a2: 235, col: "#3d4b59", op: 210 },
    { a1: 230, a2: 280, col: "#6e8194", op: 195 },
    { a1: 275, a2: 325, col: "#c4d7e6", op: 205 },
    { a1: 320, a2: 360, col: "#e9f2f8", op: 215 }
  ];

  // Fill interior ellipse base
  drawPolyWash(makeEllipsePoly(BX, BY, BRX * 0.97, BRY * 0.92, rot, 56), "#5c6f82", 205);

  for (let ib of innerBands) {
    let pts = [];
    for (let a = ib.a1; a <= ib.a2; a += 4) pts.push(rimPt(a, 0.97, 0.92));
    for (let a = ib.a2; a >= ib.a1; a -= 4) {
      let p = rimPt(a, 0.72, 0.55);
      pts.push([p[0], p[1] + 28]);
    }
    drawPolyWash(pts, ib.col, ib.op);
  }

  // Interior vertical & curved reflection lines
  for (let a = 182; a <= 358; a += 1.6) {
    let p1 = rimPt(a, 0.97, 0.92);
    let p2 = rimPt(a, 0.65, 0.35);
    p2[1] += 26;
    if (p2[1] > BY + BRY * 0.85) p2[1] = BY + BRY * 0.85;

    let col = a > 305 ? "#ffffff" : (a > 265 ? "#b4c9dc" : (a < 225 ? "#2e3b48" : "#56687a"));
    brush.set(col === "#ffffff" ? "frost_needle" : "micro_2H", col, 0.8);
    safeLine(p1[0], p1[1], p2[0], p2[1]);
  }

  // 5C. Jagged Residual Shelf of Thin Edge-Ice Still Clinging Inside the Bowl Rim
  let shelfPts = [];
  for (let a = 205; a <= 335; a += 5) {
    shelfPts.push(rimPt(a, 0.95, 0.88));
  }
  for (let a = 335; a >= 205; a -= 5) {
    let jag = 0.72 + 0.14 * noise(a * 0.15);
    let p = rimPt(a, jag, jag * 0.75);
    shelfPts.push([p[0], p[1] + 8]);
  }
  drawPolyWash(shelfPts, "#e5f0f7", 175);

  for (let a = 208; a <= 332; a += 2.5) {
    let p1 = rimPt(a, 0.95, 0.88);
    let jag = 0.72 + 0.14 * noise(a * 0.15);
    let p2 = rimPt(a, jag, jag * 0.75);
    p2[1] += 8;
    brush.set(floor(a) % 2 === 0 ? "frost_needle" : "micro_2H", floor(a) % 2 === 0 ? "#ffffff" : "#567288", 0.9);
    safeLine(p1[0], p1[1], p2[0], p2[1]);
  }

  // 5D. Rolled Stainless Steel Top Lip (Torus Rim of the Dog Bowl)
  for (let pass = 0; pass < 4; pass++) {
    let ptsOuter = [];
    let ptsInner = [];
    let ptsHighlight = [];
    for (let a = 0; a <= 360; a += 5) {
      ptsOuter.push(rimPt(a, 1.015, 1.06));
      ptsInner.push(rimPt(a, 0.965, 0.91));
      ptsHighlight.push(rimPt(a, 0.99, 0.985));
    }
    brush.set("fine_HB", "#2d3a47", 0.95);
    safeSpline(ptsOuter, 0.5);
    brush.set("micro_2H", "#455566", 0.85);
    safeSpline(ptsInner, 0.5);
    brush.set("frost_needle", "#ffffff", 1.35);
    safeSpline(ptsHighlight, 0.5);
  }
}

