// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function catmullRomPoint(p0, p1, p2, p3, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  const x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * t +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  const y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * t +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );
  return [x, y];
}

function sampleSpline(ctrlPts, numSamples) {
  const n = ctrlPts.length;
  const raw = [];
  for (let i = 0; i < numSamples; i++) {
    const u = (i / (numSamples - 1)) * (n - 1);
    const seg = min(floor(u), n - 2);
    const lt = u - seg;
    const p0 = ctrlPts[max(0, seg - 1)];
    const p1 = ctrlPts[seg];
    const p2 = ctrlPts[min(n - 1, seg + 1)];
    const p3 = ctrlPts[min(n - 1, seg + 2)];
    raw.push(catmullRomPoint(p0, p1, p2, p3, lt));
  }
  return raw;
}

function buildHoseSpine(ctrlPts, numSamples) {
  const pts = sampleSpline(ctrlPts, numSamples);
  const spine = [];
  let accLen = 0;

  for (let i = 0; i < pts.length; i++) {
    const prev = pts[max(0, i - 1)];
    const next = pts[min(pts.length - 1, i + 1)];
    if (i > 0) {
      accLen += dist(pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1]);
    }
    let dx = next[0] - prev[0];
    let dy = next[1] - prev[1];
    const m = hypot(dx, dy) || 1;
    dx /= m;
    dy /= m;
    const nx = -dy;
    const ny = dx;

    // Signed curvature estimate
    const prev2 = pts[max(0, i - 3)];
    const next2 = pts[min(pts.length - 1, i + 3)];
    const v1x = pts[i][0] - prev2[0], v1y = pts[i][1] - prev2[1];
    const v2x = next2[0] - pts[i][0], v2y = next2[1] - pts[i][1];
    const cross = (v1x * v2y - v1y * v2x) / (hypot(v1x, v1y) * hypot(v2x, v2y) || 1);

    const t = i / (pts.length - 1);
    // Perspective taper: thicker in foreground (26.5px), tapering to 16.5px at the coupling
    const r = lerp(26.5, 16.5, pow(t, 0.82));

    spine.push({
      x: pts[i][0],
      y: pts[i][1],
      tx: dx,
      ty: dy,
      nx: nx,
      ny: ny,
      r: r,
      t: t,
      s: accLen,
      kappa: cross
    });
  }
  return spine;
}

