function drawPaperGround() {
  brush.noStroke();
  brush.fillTexture(0.55, 0.25);
  brush.fillBleed(0.18, "out");

  // Subtle warm paper corner tones
  brush.fill(PAL.paperWarm, 65);
  drawPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]]);

  // Delicate paper fibers in outer margins
  brush.set("2H", PAL.paperShadow, 0.35);
  for (let i = 0; i < 160; i++) {
    const x = random(30, 1170);
    const y = random(30, 1170);
    if (x > PX1 + 10 && x < PX2 - 10 && y > PY1 + 10 && y < PY2 - 10) continue;
    const ang = random(-15, 15);
    const len = random(18, 55);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

function drawPanelUnderpainting() {
