  drawPoly([[PX1, 440], [PX2, 370], [PX2, 720], [PX1, 790]]);
  drawPoly([[PX1, 780], [PX2, 680], [PX2, 1020], [PX1, 1090]]);

  brush.fill(PAL.mustardMid, 90);
  drawPoly([[320, 480], [880, 410], [840, 620], [300, 670]]);
  drawPoly([[300, 830], [900, 740], [890, 950], [310, 1020]]);

  // Batch 4: Pastel Sage mid-lawn watercolor washes
  brush.fill(PAL.sageLight, 135);
  drawPoly([[PX1, 360], [PX2, 340], [PX2, 1135], [PX1, 1135]]);

  brush.fill(PAL.sageMid, 105);
  drawPoly([[PX1, 520], [PX2, 470], [PX2, 860], [PX1, 910]]);
  drawPoly([[PX1, 890], [PX2, 830], [PX2, 1135], [PX1, 1135]]);

  // Batch 5: Olive dappled lawn depth
  brush.fill(PAL.oliveLight, 95);
  drawPoly([[PX1, 610], [780, 560], [PX2, 760], [PX1, 820]]);
  drawPoly([[PX1, 960], [PX2, 910], [PX2, 1135], [PX1, 1135]]);

  brush.fill(PAL.oliveMid, 80);
  drawPoly([[PX1, 1020], [PX2, 975], [PX2, 1135], [PX1, 1135]]);

  // Soft out-of-focus distant garden hedge/meadow horizon puffs around y = 310..390
