function drawLawnUnderTurf() {
  brush.clip([PX1 + 3, PY1 + 3, PX2 - 3, PY2 - 3]);

  const turfColors = [
    PAL.sageMid, PAL.sageDark, PAL.oliveLight,
    PAL.oliveMid, PAL.mustardMid, PAL.celadonDeep
  ];

  // Fine dense base grass texture
  for (let c = 0; c < turfColors.length; c++) {
    brush.set("cpencil", turfColors[c], 0.42);
    for (let i = 0; i < 290; i++) {
      const t = pow(random(), 0.85);
      const y = lerp(335, 1130, t);
      const x = random(PX1 + 6, PX2 - 6);
      const persp = map(y, 335, 1130, 0.32, 1.0);
      const len = random(14, 34) * persp;
      const sway = (noise(x * 0.006, y * 0.006) - 0.48) * 48;
      const ang = -90 + sway + random(-14, 14);
      const x2 = x + cos(ang) * len;
      const y2 = y + sin(ang) * len;
      brush.line(x, y, x2, y2);
    }
  }

  brush.noClip();
}

function drawSingleGrassBlade(x, y, scaleFactor, forceHero = false) {
  const wind = (noise(x * 0.005, y * 0.005) - 0.45) * 52;
  const baseAng = -90 + wind + random(-18, 18);
  const bend = random(-28, 28) + (wind > 0 ? 12 : -12);
  const h = random(28, 66) * scaleFactor;

  const p0 = [x, y];
  const p1 = [
    x + cos(baseAng) * (h * 0.48),
    y + sin(baseAng) * (h * 0.48)
  ];
  const p2 = [
    p1[0] + cos(baseAng + bend * 0.65) * (h * 0.35),
    p1[1] + sin(baseAng + bend * 0.65) * (h * 0.35)
  ];
  const p3 = [
    p2[0] + cos(baseAng + bend) * (h * 0.25),
    p2[1] + sin(baseAng + bend) * (h * 0.25)
  ];

  // Sunlit vs shaded patch modulation
  const sunNoise = noise(x * 0.008 + 10, y * 0.008 + 10);
  let fillCol = PAL.sageMid;
  if (sunNoise > 0.62) fillCol = PAL.mustardMid;
  else if (sunNoise > 0.52) fillCol = PAL.celadonMid;
  else if (sunNoise < 0.36) fillCol = PAL.oliveMid;
  else if (sunNoise < 0.44) fillCol = PAL.sageDark;

  if (forceHero || (scaleFactor > 0.68 && random() < 0.28)) {
    // Full double-edged ribbon grass blade with wash fill, central vein, and brown-ink contour
    const wBase = random(2.2, 4.2) * scaleFactor;
    const wMid = wBase * 0.62;
    const wUpper = wBase * 0.28;

    const nx0 = -sin(baseAng), ny0 = cos(baseAng);
    const nx1 = -sin(baseAng + bend * 0.5), ny1 = cos(baseAng + bend * 0.5);

    const ribbon = [
      [p0[0] - nx0 * wBase * 0.5, p0[1] - ny0 * wBase * 0.5],
      [p1[0] - nx1 * wMid * 0.5, p1[1] - ny1 * wMid * 0.5],
      [p2[0] - nx1 * wUpper * 0.5, p2[1] - ny1 * wUpper * 0.5],
      [p3[0], p3[1]],
      [p2[0] + nx1 * wUpper * 0.5, p2[1] + ny1 * wUpper * 0.5],
      [p1[0] + nx1 * wMid * 0.5, p1[1] + ny1 * wMid * 0.5],
      [p0[0] + nx0 * wBase * 0.5, p0[1] + ny0 * wBase * 0.5]
    ];

    brush.noStroke();
    brush.wash(fillCol, 210);
    drawPoly(ribbon, 0.2);
    brush.noWash();

    // Sunlit midrib highlight
    brush.set("2H", sunNoise > 0.5 ? PAL.mustardPale : PAL.celadonPale, 0.35 * scaleFactor);
    brush.spline([
      [p0[0], p0[1], 0.5],
      [p1[0], p1[1], 0.8],
      [p2[0], p2[1], 0.5],
      [p3[0], p3[1], 0.15]
    ], 0.4);

    // Fine Art Nouveau brown-ink edge contour
    brush.set("crackPen", PAL.inkMid, 0.65 * scaleFactor);
    brush.spline([
      [ribbon[0][0], ribbon[0][1], 0.6],
      [ribbon[1][0], ribbon[1][1], 0.85],
      [ribbon[2][0], ribbon[2][1], 0.55],
      [p3[0], p3[1], 0.2]
    ], 0.4);
    brush.set("crackPen", PAL.inkDark, 0.75 * scaleFactor);
    brush.spline([
      [ribbon[6][0], ribbon[6][1], 0.7],
      [ribbon[5][0], ribbon[5][1], 0.9],
      [ribbon[4][0], ribbon[4][1], 0.6],
      [p3[0], p3[1], 0.2]
    ], 0.4);
  } else {
    // Tapered multi-stroke botanical blade
    brush.set("pen", fillCol, 0.72 * scaleFactor);
    brush.spline([
      [p0[0], p0[1], 1.15],
      [p1[0], p1[1], 0.95],
      [p2[0], p2[1], 0.55],
      [p3[0], p3[1], 0.15]
    ], 0.45);

    if (random() < 0.55) {
      brush.set("crackPen", PAL.inkMid, 0.55 * scaleFactor);
      brush.spline([
        [p0[0] + 0.7, p0[1], 0.85],
        [p1[0] + 0.5, p1[1], 0.7],
        [p2[0] + 0.3, p2[1], 0.4],
        [p3[0], p3[1], 0.15]
      ], 0.45);
    }
  }
}

function drawGrassBand(yMin, yMax, count) {
  brush.clip([PX1 + 3, PY1 + 3, PX2 - 3, PY2 - 3]);
  const blades = [];
  for (let i = 0; i < count; i++) {
    const y = random(yMin, yMax);
    const x = random(PX1 + 8, PX2 - 8);
    blades.push({ x, y });
  }
  blades.sort((a, b) => a.y - b.y);

  for (let i = 0; i < blades.length; i++) {
    const b = blades[i];
    const scaleFactor = map(b.y, 335, 1135, 0.28, 1.22);
    drawSingleGrassBlade(b.x, b.y, scaleFactor, false);
  }
  brush.noClip();
}

function drawHoseHuggingGrass(spineSlice, density = 0.4) {
  brush.clip([PX1 + 3, PY1 + 3, PX2 - 3, PY2 - 3]);
  for (let i = 2; i < spineSlice.length - 2; i += 2) {
    if (random() > density) continue;
    const pt = spineSlice[i];
    // Place grass blades rooted just below the lower edge of the hose so they curl up over the vinyl
    const side = pt.ny > 0 ? 1 : -1;
    const bx = pt.x + pt.nx * side * (pt.r + random(1, 7)) + random(-6, 6);
    const by = pt.y + pt.ny * side * (pt.r + random(1, 7)) + random(2, 10);
    if (bx < PX1 + 10 || bx > PX2 - 10 || by > PY2 - 6) continue;
    const scaleFactor = map(by, 335, 1135, 0.32, 1.15);
    drawSingleGrassBlade(bx, by, scaleFactor, true);
  }
  brush.noClip();
}

function drawCloverAndSeeds() {
  brush.clip([PX1 + 3, PY1 + 3, PX2 - 3, PY2 - 3]);
  // Delicate clover trefoils and sunlit lawn seed heads in foreground corners
  const spots = [
    [335, 1065], [380, 1095], [460, 1105], [760, 1045],
    [835, 1080], [875, 1020], [670, 1090], [325, 810], [865, 650]
  ];

  for (let s = 0; s < spots.length; s++) {
    const cx = spots[s][0], cy = spots[s][1];
    const sc = map(cy, 600, 1130, 0.65, 1.1);
    for (let k = 0; k < 4; k++) {
      const lx = cx + random(-24, 24) * sc;
      const ly = cy + random(-14, 14) * sc;
      const rLeaf = random(5.5, 9.0) * sc;
      const baseA = random(360);

      for (let leaf = 0; leaf < 3; leaf++) {
        const a = baseA + leaf * 120 + random(-10, 10);
        const ox = lx + cos(a) * rLeaf * 0.95;
        const oy = ly + sin(a) * rLeaf * 0.8;

        brush.noStroke();
        brush.wash(leaf % 2 === 0 ? PAL.sageLight : PAL.celadonMid, 215);
        const pts = [];
        for (let th = 0; th < 360; th += 45) {
          pts.push([ox + cos(th) * rLeaf * 0.75, oy + sin(th) * rLeaf * 0.62]);
        }
        drawPoly(pts, 0.3);
        brush.noWash();

        // Pale chevron mark on clover leaflet
        brush.set("2H", PAL.celadonPale, 0.35 * sc);
        brush.arc(ox, oy, rLeaf * 0.35, a - 40, a + 40);

        // Brown ink outline
        brush.set("crackPen", PAL.inkMid, 0.55 * sc);
        brush.circle(ox, oy, rLeaf * 0.7, 0.2);
      }
    }
  }
  brush.noClip();
}

