// 3. GARDEN HOSE: CRACKED GREEN VINYL, DUSTY SHEEN & BROWN-INK CONTOUR
// ============================================================================

function drawHoseCastShadow(spine, dx, dy) {
  brush.clip([PX1 + 3, PY1 + 3, PX2 - 3, PY2 - 3]);
  brush.noStroke();

  // Soft olive-umber cast shadow ribbon on the lawn
  const chunk = 16;
  for (let i = 0; i < spine.length - 1; i += chunk) {
    const end = min(spine.length - 1, i + chunk);
    const poly = [];
    for (let j = i; j <= end; j++) {
      const p = spine[j];
      poly.push([p.x + dx + p.nx * p.r * 1.05, p.y + dy + p.ny * p.r * 1.05]);
    }
    for (let j = end; j >= i; j--) {
      const p = spine[j];
      poly.push([p.x + dx - p.nx * p.r * 0.95, p.y + dy - p.ny * p.r * 0.95]);
    }
    brush.wash(PAL.oliveDark, 105);
    drawPoly(poly, 0.15);
    brush.noWash();
  }

  // Dark shadow grass blades inside the cast shadow footprint
  brush.set("pen", PAL.oliveShadow, 0.48);
  for (let i = 0; i < spine.length; i += 2) {
    const p = spine[i];
    for (let k = 0; k < 2; k++) {
      const u = random(-0.9, 0.9);
      const sx = p.x + dx + p.nx * p.r * u;
      const sy = p.y + dy + p.ny * p.r * u;
      const ang = -85 + random(-22, 22);
      const len = random(8, 18) * (p.r / 22);
      brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
    }
  }

  brush.noClip();
}

function drawCrossingOcclusionShadow(cx, cy, r, angleDeg) {
  push();
  translate(cx, cy);
  rotate(angleDeg);
  brush.noStroke();
  brush.wash(PAL.inkDark, 130);
  drawPoly([
    [-r * 1.25, -r * 0.95],
    [r * 1.25, -r * 0.95],
    [r * 1.35, r * 1.05],
    [-r * 1.35, r * 1.05]
  ], 0.2);
  brush.noWash();
  pop();
}

function renderHoseBody(spine, isOverpass) {
  // Clip to panel except allow the leftmost curve to gently kiss the inner border
  brush.clip([PX1 - 4, PY1 + 2, PX2 - 2, PY2 - 2]);

  const chunk = 14;

  // Step A: Base Watercolor & Wash Cylinder Shading using true 3D surface normals
  // We divide the cross-section parameter s in [-1, 1] into 6 strips and shade each by dot(N_3d, SUN)
  const strips = [
    [-1.0, -0.62],
    [-0.62, -0.22],
    [-0.22, 0.22],
    [0.22, 0.62],
    [0.62, 0.86],
    [0.86, 1.0]
  ];

  brush.noStroke();
  for (let i = 0; i < spine.length - 1; i += chunk) {
    const end = min(spine.length - 1, i + chunk);
    const midP = spine[floor((i + end) * 0.5)];

    for (let st = 0; st < strips.length; st++) {
      const s0 = strips[st][0];
      const s1 = strips[st][1];
      const sm = (s0 + s1) * 0.5;
      const nz = sqrt(max(0.01, 1 - sm * sm));
      const n3x = midP.nx * sm;
      const n3y = midP.ny * sm;

      const ndotl = n3x * SUN[0] + n3y * SUN[1] + nz * SUN[2];
      const bounce = max(0, n3x * 0.45 + n3y * 0.75 - nz * 0.15);

      let col = PAL.sageMid;
      let alpha = 210;

      if (ndotl > 0.62) {
        col = PAL.celadonPale;
        alpha = 225;
      } else if (ndotl > 0.36) {
        col = PAL.sageLight;
        alpha = 220;
      } else if (ndotl > 0.08) {
        col = PAL.sageMid;
        alpha = 220;
      } else if (bounce > 0.32) {
        // Warm mustard bounce light reflected from sunlit grass onto underside of hose
        col = PAL.mustardMid;
        alpha = 195;
      } else if (ndotl > -0.22) {
        col = PAL.oliveMid;
        alpha = 225;
      } else {
        col = PAL.oliveDark;
        alpha = 235;
      }

      const poly = [];
      for (let j = i; j <= end; j++) {
        const p = spine[j];
        poly.push([p.x + p.nx * p.r * s0, p.y + p.ny * p.r * s0]);
      }
      for (let j = end; j >= i; j--) {
        const p = spine[j];
        poly.push([p.x + p.nx * p.r * s1, p.y + p.ny * p.r * s1]);
      }

      brush.wash(col, alpha);
      drawPoly(poly, 0.05);
      brush.noWash();
    }
  }

  // Step B: Soft Watercolor Glazes along the hose for organic pigment granulation
  brush.fillTexture(0.55, 0.35);
  brush.fillBleed(0.06, "in");
  for (let i = 0; i < spine.length - 1; i += chunk * 2) {
    const end = min(spine.length - 1, i + chunk * 2);
    const poly = [];
    for (let j = i; j <= end; j++) {
      const p = spine[j];
      poly.push([p.x - p.nx * p.r * 0.85, p.y - p.ny * p.r * 0.85]);
    }
    for (let j = end; j >= i; j--) {
      const p = spine[j];
      poly.push([p.x + p.nx * p.r * 0.85, p.y + p.ny * p.r * 0.85]);
    }
    const glazeCol = (i / (chunk * 2)) % 2 === 0 ? PAL.sageMid : PAL.oliveLight;
    brush.fill(glazeCol, 55);
    drawPoly(poly, 0.08);
  }
  brush.noFill();

  // Step C: Longitudinal Vinyl Extrusion Ribs
  const ribOffsets = [-0.78, -0.52, -0.26, 0.0, 0.26, 0.52, 0.78];
  for (let rIdx = 0; rIdx < ribOffsets.length; rIdx++) {
    const s = ribOffsets[rIdx];
    const ribPts = [];
    for (let i = 0; i < spine.length; i += 3) {
      const p = spine[i];
      ribPts.push([
        p.x + p.nx * p.r * s,
        p.y + p.ny * p.r * s,
        0.5 + 0.3 * sin(i * 8)
      ]);
    }
    brush.set("2H", rIdx % 2 === 0 ? PAL.oliveMid : PAL.celadonMid, 0.38);
    brush.spline(ribPts, 0.35);
  }

  // Step D: Dusty Sheen on the sunlit upper ridge & outer curves
  for (let i = 0; i < spine.length - 4; i += 3) {
    const p = spine[i];
    const pNext = spine[i + 3];
    // Determine which side s in [-0.8, 0.8] faces the upper-left sun
    const sSun = constrain(p.nx * SUN[0] + p.ny * SUN[1], -0.68, 0.68);

    // Dry chalky vinyl sheen strokes
    brush.set("sheenDry", i % 2 === 0 ? PAL.dustLight : PAL.dustWarm, 0.9 * (p.r / 22));
    const sx1 = p.x + p.nx * p.r * (sSun + random(-0.18, 0.18));
    const sy1 = p.y + p.ny * p.r * (sSun + random(-0.18, 0.18));
    const sx2 = pNext.x + pNext.nx * pNext.r * (sSun + random(-0.18, 0.18));
    const sy2 = pNext.y + pNext.ny * pNext.r * (sSun + random(-0.18, 0.18));
    brush.line(sx1, sy1, sx2, sy2);

    // Fine specular vinyl highlight thread right along the peak ridge
    if (i % 6 === 0) {
      brush.set("2H", PAL.celadonPale, 0.52 * (p.r / 22));
      brush.line(
        p.x + p.nx * p.r * sSun * 0.85,
        p.y + p.ny * p.r * sSun * 0.85,
        pNext.x + pNext.nx * pNext.r * sSun * 0.85,
        pNext.y + pNext.ny * pNext.r * sSun * 0.85
      );
    }
  }

  // Fine dusty stipple along outer bends that scrape the dry ground
  brush.set("spray", PAL.dustWarm, 0.42);
  for (let i = 4; i < spine.length - 4; i += 5) {
    const p = spine[i];
    if (abs(p.kappa) > 0.08 || random() < 0.35) {
      brush.line(
        p.x - p.nx * p.r * 0.3,
        p.y - p.ny * p.r * 0.3,
        p.x + p.nx * p.r * 0.3,
        p.y + p.ny * p.r * 0.3
      );
    }
  }

  // Step E: Hyperreal Cracked Green Vinyl & Inner-Bend Compression Creases
  for (let i = 2; i < spine.length - 2; i++) {
    const p = spine[i];
    const scaleW = p.r / 22;

    // 1. Inner-bend compression wrinkles when curvature kappa is strong
    if (abs(p.kappa) > 0.09 && i % 2 === 0) {
      const innerSign = p.kappa > 0 ? 1 : -1;
      const sStart = innerSign * 0.96;
      const sMid = innerSign * 0.35;
      const sEnd = innerSign * -0.15;

      const c0 = [p.x + p.nx * p.r * sStart, p.y + p.ny * p.r * sStart];
      const c1 = [
        p.x + p.nx * p.r * sMid + p.tx * p.r * 0.18 * innerSign,
        p.y + p.ny * p.r * sMid + p.ty * p.r * 0.18 * innerSign
      ];
      const c2 = [p.x + p.nx * p.r * sEnd, p.y + p.ny * p.r * sEnd];

      // Dark buckle fold
      brush.set("crackPen", PAL.oliveShadow, 0.85 * scaleW);
      brush.spline([
        [c0[0], c0[1], 0.8],
        [c1[0], c1[1], 1.2],
        [c2[0], c2[1], 0.2]
      ], 0.45);

      // Sunlit crest of the vinyl buckle right beside the dark crease
      brush.set("crackPen", PAL.dustLight, 0.65 * scaleW);
      brush.spline([
        [c0[0] - p.tx * 1.4, c0[1] - p.ty * 1.4, 0.6],
        [c1[0] - p.tx * 1.6, c1[1] - p.ty * 1.6, 1.0],
        [c2[0] - p.tx * 1.2, c2[1] - p.ty * 1.2, 0.2]
      ], 0.45);
    }

    // 2. Weathered vinyl surface crazing & transverse tension cracks
    if (random() < 0.68) {
      const outerSign = p.kappa > 0 ? -1 : 1;
      const sCenter = constrain(outerSign * random(0.05, 0.72) + random(-0.25, 0.25), -0.85, 0.85);
      const halfSpan = random(0.18, 0.46);
      const sA = constrain(sCenter - halfSpan, -0.92, 0.92);
      const sB = constrain(sCenter + halfSpan, -0.92, 0.92);

      const jitter1 = random(-2.2, 2.2) * scaleW;
      const jitter2 = random(-2.2, 2.2) * scaleW;

      const k0 = [p.x + p.nx * p.r * sA, p.y + p.ny * p.r * sA];
      const k1 = [
        p.x + p.nx * p.r * ((sA + sB) * 0.5) + p.tx * jitter1,
        p.y + p.ny * p.r * ((sA + sB) * 0.5) + p.ty * jitter1
      ];
      const k2 = [
        p.x + p.nx * p.r * sB + p.tx * jitter2,
        p.y + p.ny * p.r * sB + p.ty * jitter2
      ];

      // Dark micro-fissure in the vinyl
      brush.set("crackPen", PAL.inkDark, 0.68 * scaleW);
      brush.spline([
        [k0[0], k0[1], 0.3],
        [k1[0], k1[1], 1.05],
        [k2[0], k2[1], 0.35]
      ], 0.35);

      // Microscopic sunlit lip along the lower-right edge of the crack
      brush.set("crackPen", PAL.celadonPale, 0.52 * scaleW);
      brush.spline([
        [k0[0] + p.tx * 0.9, k0[1] + p.ty * 0.9, 0.25],
        [k1[0] + p.tx * 1.1, k1[1] + p.ty * 1.1, 0.9],
        [k2[0] + p.tx * 0.9, k2[1] + p.ty * 0.9, 0.25]
      ], 0.35);

      // Occasional branching craze fork
      if (random() < 0.38) {
        const forkLen = random(4, 10) * scaleW;
        const forkX = k1[0] + p.tx * forkLen + p.nx * random(-3, 3);
        const forkY = k1[1] + p.ty * forkLen + p.ny * random(-3, 3);
        brush.set("crackPen", PAL.inkMid, 0.5 * scaleW);
        brush.line(k1[0], k1[1], forkX, forkY);
      }
    }
  }

  // Step F: Confident Brown-Ink Contour of Variable Weight (Art Nouveau Rhythm)
  const edgeA = [];
  const edgeB = [];
  for (let i = 0; i < spine.length; i += 2) {
    const p = spine[i];
    // Modulate calligraphic pressure by orientation relative to sun + curvature accent
    const sunDotA = (-p.nx) * SUN[0] + (-p.ny) * SUN[1];
    const curvBoost = min(0.55, abs(p.kappa) * 3.2);

    const pressA = constrain((sunDotA < 0 ? 1.25 : 0.68) + curvBoost, 0.45, 1.75) * (p.r / 22);
    const pressB = constrain((sunDotA > 0 ? 1.25 : 0.68) + curvBoost, 0.45, 1.75) * (p.r / 22);

    edgeA.push([p.x - p.nx * p.r, p.y - p.ny * p.r, pressA]);
    edgeB.push([p.x + p.nx * p.r, p.y + p.ny * p.r, pressB]);
  }

  brush.set("calligraphy", PAL.inkDark, 1.05);
  brush.spline(edgeA, 0.4);
  brush.spline(edgeB, 0.4);

  // Secondary warm brown-ink inner accent line on the shadow edge
  const shadowAccent = [];
  for (let i = 0; i < spine.length; i += 3) {
    const p = spine[i];
    const sShadow = (p.nx * SUN[0] + p.ny * SUN[1]) < 0 ? 0.88 : -0.88;
    shadowAccent.push([
      p.x + p.nx * p.r * sShadow,
      p.y + p.ny * p.r * sShadow,
      0.55 * (p.r / 22)
    ]);
  }
  brush.set("crackPen", PAL.inkMid, 0.75);
  brush.spline(shadowAccent, 0.35);

  brush.noClip();
}

// ============================================================================
// 4. MACHINED BRASS COUPLING & TWIST NOZZLE
// ============================================================================

function drawBrassNozzle(bx, by, angleDeg) {
  const ux = cos(angleDeg), uy = sin(angleDeg);
  const nx = -uy, ny = ux; // Points toward upper-left (sunlit side)

  function toWorld(s, rOff) {
    return [bx + ux * s + nx * rOff, by + uy * s + ny * rOff];
  }

  function fillBrassQuad(s0, s1, r0a, r0b, r1a, r1b, col, alpha = 230) {
    brush.noStroke();
    brush.wash(col, alpha);
    drawPoly([
      toWorld(s0, r0a),
      toWorld(s1, r1a),
      toWorld(s1, r1b),
      toWorld(s0, r0b)
    ], 0.02);
    brush.noWash();
  }

  function shadeBrassCylinder(s0, s1, rad0, rad1) {
    // High-contrast metallic reflection bands (sky celadon reflection, bright gold highlight, dark umber core, mustard bounce)
    const bands = [
      [-1.0, -0.72, PAL.mustardDeep],
      [-0.72, -0.38, PAL.brassBright],
      [-0.38, -0.08, PAL.celadonPale],
      [-0.08, 0.25, PAL.mustardMid],
      [0.25, 0.65, PAL.brassDark],
      [0.65, 0.88, PAL.mustardMid],
      [0.88, 1.0, PAL.brassUmber]
    ];
    for (let b = 0; b < bands.length; b++) {
      const f0 = bands[b][0], f1 = bands[b][1], col = bands[b][2];
      fillBrassQuad(s0, s1, rad0 * f0, rad0 * f1, rad1 * f0, rad1 * f1, col, 235);
    }
  }

  // Cast shadow of the brass nozzle onto the background grass
  brush.noStroke();
  brush.wash(PAL.oliveDark, 105);
  drawPoly([
    [bx + 10, by + 18],
    [bx + ux * 86 + 10, by + uy * 86 + 18],
    [bx + ux * 86 + nx * 14 + 10, by + uy * 86 + ny * 14 + 18],
    [bx + nx * 20 + 10, by + ny * 20 + 18]
  ], 0.15);
  brush.noWash();

  // 1. Crimped Brass Ferrule (s = -6 to 13, r = 17.2)
  shadeBrassCylinder(-6, 13, 17.2, 17.2);
  // Crimp grooves
  for (let s = -2; s <= 10; s += 4) {
    const pA = toWorld(s, -17.2);
    const pB = toWorld(s, 17.2);
    brush.set("crackPen", PAL.brassUmber, 0.85);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
    const pC = toWorld(s + 1.1, -15);
    const pD = toWorld(s + 1.1, 2);
    brush.set("glossTip", PAL.brassBright, 0.55);
    brush.line(pC[0], pC[1], pD[0], pD[1]);
  }

  // 2. Hexagonal Swivel Nut (s = 13 to 31, r = 20.5) with 3 flat machined facets
  // Top sunlit facet (-1.0 to -0.35)
  fillBrassQuad(13, 31, -20.5, -7.2, -20.5, -7.2, PAL.mustardPale, 240);
  fillBrassQuad(15, 29, -18.5, -10.0, -18.5, -10.0, PAL.brassBright, 240);
  // Middle flat facet (-0.35 to 0.38) with dark sky/horizon reflection
  fillBrassQuad(13, 31, -7.2, 7.8, -7.2, 7.8, PAL.mustardMid, 240);
  fillBrassQuad(13, 31, -2.5, 4.2, -2.5, 4.2, PAL.brassDark, 225);
  fillBrassQuad(14, 30, -6.5, -2.8, -6.5, -2.8, PAL.celadonPale, 210);
  // Bottom shadow facet (0.38 to 1.0)
  fillBrassQuad(13, 31, 7.8, 20.5, 7.8, 20.5, PAL.brassDark, 240);
  fillBrassQuad(14, 30, 12.0, 17.5, 12.0, 17.5, PAL.mustardDeep, 215);

  // Hex nut bevel highlights & facet ridges
  const f1a = toWorld(13, -7.2), f1b = toWorld(31, -7.2);
  const f2a = toWorld(13, 7.8), f2b = toWorld(31, 7.8);
  brush.set("glossTip", PAL.white, 0.85);
  brush.line(f1a[0], f1a[1], f1b[0], f1b[1]);
  brush.set("crackPen", PAL.inkDark, 0.95);
  brush.line(f2a[0], f2a[1], f2b[0], f2b[1]);

  // 3. Knurled Grip Collar (s = 31 to 46, r = 18.0)
  shadeBrassCylinder(31, 46, 18.0, 18.0);
  // Diamond knurling cross-hatch
  brush.set("crackPen", PAL.brassUmber, 0.65);
  for (let k = -16; k <= 16; k += 3.2) {
    const p1 = toWorld(31.5, constrain(k - 4, -17.5, 17.5));
    const p2 = toWorld(45.5, constrain(k + 4, -17.5, 17.5));
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    const p3 = toWorld(31.5, constrain(k + 4, -17.5, 17.5));
    const p4 = toWorld(45.5, constrain(k - 4, -17.5, 17.5));
    brush.line(p3[0], p3[1], p4[0], p4[1]);
  }
  // Specular pricks on knurl diamonds
  brush.set("glossTip", PAL.white, 0.65);
  for (let s = 33.5; s <= 44; s += 3.2) {
    const kp = toWorld(s, -9.5);
    brush.line(kp[0], kp[1], kp[0] + ux * 1.2, kp[1] + uy * 1.2);
  }

  // 4. Tapered Conical Brass Barrel (s = 46 to 76, r = 15.2 -> 9.6)
  shadeBrassCylinder(46, 76, 15.2, 9.6);
  // Gleaming white specular streak along the tapered barrel
  const sp0 = toWorld(47, -8.4), sp1 = toWorld(75, -5.3);
  brush.set("glossTip", PAL.white, 1.05);
  brush.line(sp0[0], sp0[1], sp1[0], sp1[1]);

  // 5. Flared Nozzle Tip Crown (s = 76 to 85, r = 10.6 -> 11.4)
  shadeBrassCylinder(76, 85, 10.6, 11.4);
  const cr0 = toWorld(77, -6.2), cr1 = toWorld(84, -6.6);
  brush.set("glossTip", PAL.white, 0.95);
  brush.line(cr0[0], cr0[1], cr1[0], cr1[1]);

  // Dark inner nozzle orifice ellipse at s = 85
  const tipCenter = toWorld(85, 0);
  const orifice = [];
  for (let a = 0; a < 360; a += 30) {
    const oa = cos(a) * 3.2;
    const ob = sin(a) * 9.5;
    orifice.push([tipCenter[0] + ux * oa + nx * ob, tipCenter[1] + uy * oa + ny * ob]);
  }
  brush.noStroke();
  brush.wash(PAL.inkDark, 245);
  drawPoly(orifice, 0.25);
  brush.noWash();

  // Confident brown-ink structural contours around all brass sections
  const sections = [
    [-6, 17.2], [13, 17.2], [13, 20.5], [31, 20.5],
    [31, 18.0], [46, 18.0], [46, 15.2], [76, 9.6],
    [76, 10.6], [85, 11.4]
  ];
  brush.set("calligraphy", PAL.inkDark, 0.95);
  for (let i = 0; i < sections.length - 1; i++) {
    const sA = sections[i][0], rA = sections[i][1];
    const sB = sections[i + 1][0], rB = sections[i + 1][1];
    const topA = toWorld(sA, -rA), topB = toWorld(sB, -rB);
    const botA = toWorld(sA, rA), botB = toWorld(sB, rB);
    brush.line(topA[0], topA[1], topB[0], topB[1]);
    brush.line(botA[0], botA[1], botB[0], botB[1]);
  }
  // Transverse ring dividers
  const rings = [-6, 13, 31, 46, 76, 85];
  const ringR = [17.2, 20.5, 20.5, 18.0, 10.6, 11.4];
  brush.set("crackPen", PAL.inkDark, 0.9);
  for (let i = 0; i < rings.length; i++) {
    const pTop = toWorld(rings[i], -ringR[i]);
    const pBot = toWorld(rings[i], ringR[i]);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }

  return { x: tipCenter[0], y: tipCenter[1] };
}

// ============================================================================
// 5. TALL ART NOUVEAU DECORATIVE PANEL BORDER
// ============================================================================

function drawArtNouveauPanelFrame() {
  const ox1 = PX1 - 24, oy1 = PY1 - 22, ox2 = PX2 + 24, oy2 = PY2 + 22;

  // Soft watercolor wash in the decorative frame band
  brush.noStroke();
  brush.wash(PAL.mustardPale, 115);
  drawPoly([[ox1, oy1], [ox2, oy1], [ox2, PY1], [ox1, PY1]]);
  drawPoly([[ox1, PY2], [ox2, PY2], [ox2, oy2], [ox1, oy2]]);
  drawPoly([[ox1, PY1], [PX1, PY1], [PX1, PY2], [ox1, PY2]]);
  drawPoly([[PX2, PY1], [ox2, PY1], [ox2, PY2], [PX2, PY2]]);
  brush.noWash();

  // Upper Art Nouveau spandrel arches inside top corners of the panel
  const archSpan = 128;
  for (let side of [-1, 1]) {
    const cornerX = side === -1 ? PX1 : PX2;
    const spandrel = [
      [cornerX, PY1],
      [cornerX - side * archSpan, PY1],
      [cornerX - side * (archSpan * 0.55), PY1 + 14],
      [cornerX - side * 22, PY1 + 52],
      [cornerX, PY1 + archSpan]
    ];
    brush.noStroke();
    brush.wash(PAL.paperWarm, 225);
    drawPoly(spandrel, 0.15);
    brush.wash(PAL.celadonMid, 110);
    drawPoly(spandrel, 0.15);
    brush.noWash();

    // Whiplash botanical scroll inside spandrel
    brush.set("calligraphy", PAL.inkDark, 0.95);
    brush.spline([
      [cornerX - side * archSpan, PY1, 0.5],
      [cornerX - side * 62, PY1 + 16, 1.15],
      [cornerX - side * 22, PY1 + 56, 1.25],
      [cornerX, PY1 + archSpan, 0.5]
    ], 0.45);

    brush.set("crackPen", PAL.inkMid, 0.8);
    brush.spline([
      [cornerX - side * 88, PY1, 0.4],
      [cornerX - side * 36, PY1 + 18, 0.95],
      [cornerX - side * 15, PY1 + 42, 0.85],
      [cornerX - side * 32, PY1 + 46, 0.6],
      [cornerX - side * 38, PY1 + 30, 0.3]
    ], 0.5);
  }

  // Outer double rule & inner panel molding in confident brown ink
  brush.set("calligraphy", PAL.inkDark, 1.25);
  brush.line(PX1, PY1, PX2, PY1);
  brush.line(PX2, PY1, PX2, PY2);
  brush.line(PX2, PY2, PX1, PY2);
  brush.line(PX1, PY2, PX1, PY1);

  brush.set("crackPen", PAL.inkMid, 0.85);
  brush.line(PX1 - 5, PY1 - 5, PX2 + 5, PY1 - 5);
  brush.line(PX2 + 5, PY1 - 5, PX2 + 5, PY2 + 5);
  brush.line(PX2 + 5, PY2 + 5, PX1 - 5, PY2 + 5);
  brush.line(PX1 - 5, PY2 + 5, PX1 - 5, PY1 - 5);

  brush.set("calligraphy", PAL.inkDark, 0.95);
  brush.line(ox1, oy1, ox2, oy1);
  brush.line(ox2, oy1, ox2, oy2);
  brush.line(ox2, oy2, ox1, oy2);
  brush.line(ox1, oy2, ox1, oy1);

  // Corner whiplash knots in the outer border
  const corners = [
    [ox1, oy1, 1, 1],
    [ox2, oy1, -1, 1],
    [ox1, oy2, 1, -1],
    [ox2, oy2, -1, -1]
  ];
  for (let c = 0; c < corners.length; c++) {
    const cx = corners[c][0], cy = corners[c][1];
    const sx = corners[c][2], sy = corners[c][3];
    brush.set("crackPen", PAL.inkMid, 0.85);
    brush.spline([
      [cx + sx * 65, cy + sy * 11, 0.3],
      [cx + sx * 22, cy + sy * 14, 1.0],
      [cx + sx * 12, cy + sy * 22, 1.0],
      [cx + sx * 11, cy + sy * 65, 0.3]
    ], 0.45);
  }
}

// ============================================================================
// 6. HYPERREAL WATER DROPLETS (WITH REFRACTED MINIATURE OF THE SKY)
// ============================================================================

function buildDropletContour(cx, cy, rx, ry, angleDeg, pinch = 0.35, nPts = 24) {
  const ca = cos(angleDeg), sa = sin(angleDeg);
  const pts = [];
  for (let i = 0; i < nPts; i++) {
    const th = (i / nPts) * 360;
    const c = cos(th), s = sin(th);
    // Teardrop profile: rounded leading head (+c), tapered trailing tail (-c)
    const tailFactor = c < 0 ? 1 - pinch * pow(-c, 1.35) : 1.0;
    const lx = rx * c;
    const ly = ry * s * tailFactor;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

function drawHyperrealDroplet(cx, cy, rx, ry, angleDeg, pinch = 0.35, onSurface = false) {
  if (rx < 4.2) {
    // Small bead / satellite droplet with sky dot, celadon rim, brown ink & white prick
    brush.noStroke();
    brush.wash(PAL.skyMid, 215);
    const tiny = buildDropletContour(cx, cy, rx, ry, angleDeg, pinch, 12);
    drawPoly(tiny, 0.25);
    brush.noWash();

    brush.set("crackPen", PAL.inkDark, 0.55);
    brush.circle(cx, cy, (rx + ry) * 0.48, 0.12);

    brush.set("glossTip", PAL.white, 0.72);
    brush.line(cx - rx * 0.3, cy - ry * 0.3, cx - rx * 0.1, cy - ry * 0.25);
    return;
  }

  // 1. Soft external shadow or sunlit caustic beneath the droplet
  if (onSurface) {
    const shPoly = buildDropletContour(cx + rx * 0.28, cy + ry * 0.38, rx * 0.95, ry * 0.88, angleDeg, pinch, 16);
    brush.noStroke();
    brush.wash(PAL.oliveShadow, 125);
    drawPoly(shPoly, 0.2);
    brush.wash(PAL.caustic, 175);
    const caustPoly = buildDropletContour(cx + rx * 0.32, cy + ry * 0.35, rx * 0.55, ry * 0.45, angleDeg, 0.1, 12);
    drawPoly(caustPoly, 0.2);
    brush.noWash();
  } else {
    const haloPoly = buildDropletContour(cx + 2.2, cy + 3.0, rx * 0.98, ry * 0.98, angleDeg, pinch, 16);
    brush.noStroke();
    brush.wash(PAL.celadonMid, 85);
    drawPoly(haloPoly, 0.2);
    brush.noWash();
  }

  // 2. Full Droplet Base Fill: Luminous Pale Sky & Celadon
  const bodyPoly = buildDropletContour(cx, cy, rx, ry, angleDeg, pinch, 24);
  brush.noStroke();
  brush.wash(PAL.skyPale, 235);
  drawPoly(bodyPoly, 0.2);

  // 3. Refracted Miniature of the Sky (Upper-Left Hemisphere — Inverted Horizon)
  // Upper sky dome in deep cerulean-slate (#3b5f75 & #588299)
  const skyDome = buildDropletContour(
    cx - rx * 0.12,
    cy - ry * 0.16,
    rx * 0.82,
    ry * 0.74,
    angleDeg,
    pinch * 0.8,
    20
  );
  brush.wash(PAL.skyMid, 225);
  drawPoly(skyDome, 0.2);

  const deepSky = buildDropletContour(
    cx - rx * 0.18,
    cy - ry * 0.24,
    rx * 0.64,
    ry * 0.52,
    angleDeg - 8,
    pinch * 0.5,
    18
  );
  brush.wash(PAL.skyDeep, 230);
  drawPoly(deepSky, 0.2);

  const zenithSky = buildDropletContour(
    cx - rx * 0.22,
    cy - ry * 0.3,
    rx * 0.44,
    ry * 0.32,
    angleDeg - 12,
    0.1,
    14
  );
  brush.wash(PAL.skyDark, 215);
  drawPoly(zenithSky, 0.2);

  // 4. Refracted Miniature Cumulus Cloud Band & Horizon Line inside the droplet
  if (rx >= 6.5) {
    const cloudBand = buildDropletContour(
      cx - rx * 0.04,
      cy - ry * 0.02,
      rx * 0.62,
      ry * 0.24,
      angleDeg * 0.3,
      0.1,
      14
    );
    brush.wash(PAL.paper, 220);
    drawPoly(cloudBand, 0.25);

    // Inverted green lawn/garden refraction sliver along the upper-right rim
    const lawnRim = buildDropletContour(
      cx + rx * 0.18,
      cy - ry * 0.28,
      rx * 0.48,
      ry * 0.2,
      angleDeg + 20,
      0.1,
      12
    );
    brush.wash(PAL.oliveMid, 165);
    drawPoly(lawnRim, 0.2);
  }

  // 5. Lower-Right Internal Caustic Crescent (Concentrated Sunlit Glow)
  const causticCrescent = buildDropletContour(
    cx + rx * 0.22,
    cy + ry * 0.25,
    rx * 0.66,
    ry * 0.56,
    angleDeg,
    pinch * 0.6,
    18
  );
  brush.wash(PAL.caustic, 235);
  drawPoly(causticCrescent, 0.2);

  const hotCore = buildDropletContour(
    cx + rx * 0.28,
    cy + ry * 0.32,
    rx * 0.42,
    ry * 0.32,
    angleDeg,
    0.15,
    14
  );
  brush.wash(PAL.white, 245);
  drawPoly(hotCore, 0.2);
  brush.noWash();

  // 6. Primary Curved Window Specular Highlight & Secondary Sparkle Dot
  const specW = constrain(rx / 12, 0.55, 1.5);
  brush.set("glossTip", PAL.white, specW * 1.15);
  const sx = cx - rx * 0.34;
  const sy = cy - ry * 0.32;
  brush.spline([
    [sx - rx * 0.18, sy + ry * 0.14, 0.4],
    [sx, sy - ry * 0.08, 1.3],
    [sx + rx * 0.24, sy - ry * 0.04, 0.45]
  ], 0.45);

  // Secondary pinpoint specular dot
  brush.set("glossTip", PAL.white, specW * 0.9);
  brush.line(
    sx + rx * 0.34,
    sy + ry * 0.05,
    sx + rx * 0.39,
    sy + ry * 0.09
  );

  // Bottom-right secondary internal rim reflection
  brush.set("glossTip", PAL.white, specW * 0.65);
  brush.spline([
    [cx + rx * 0.15, cy + ry * 0.68, 0.3],
    [cx + rx * 0.52, cy + ry * 0.45, 0.95],
    [cx + rx * 0.68, cy + ry * 0.1, 0.3]
  ], 0.4);

  // 7. Confident Art Nouveau Brown-Ink Contour around the Droplet
  const contourSpline = [];
  for (let i = 0; i <= bodyPoly.length; i++) {
    const pt = bodyPoly[i % bodyPoly.length];
    const isShadowSide = (pt[0] - cx) + (pt[1] - cy) > 0;
    const press = (isShadowSide ? 0.95 : 0.52) * constrain(rx / 13, 0.48, 1.15);
    contourSpline.push([pt[0], pt[1], press]);
  }
  brush.set("crackPen", PAL.inkDark, 0.85);
  brush.spline(contourSpline, 0.35);
}

function drawSurfaceDroplets(hoseSpine) {
