// 7. SWEEPING RIBBON-LIKE LOOPS OF WATER & SPRAY DROPLETS
// ============================================================================

function drawWaterRibbon(ctrlPts, wStart, wMid, wEnd, twistFreq = 2.5) {
  const pts = sampleSpline(ctrlPts, 110);
  const leftEdge = [];
  const rightEdge = [];
  const spineData = [];

  for (let i = 0; i < pts.length; i++) {
    const prev = pts[max(0, i - 1)];
    const next = pts[min(pts.length - 1, i + 1)];
    let tx = next[0] - prev[0];
    let ty = next[1] - prev[1];
    const m = hypot(tx, ty) || 1;
    tx /= m;
    ty /= m;
    const nx = -ty;
    const ny = tx;

    const t = i / (pts.length - 1);
    // Envelope width: starts narrow at nozzle, swells in the middle loops, pinches to 0.8px at the droplet tip
    let envW = t < 0.45
      ? lerp(wStart, wMid, sin((t / 0.45) * 90))
      : lerp(wMid, wEnd, pow((t - 0.45) / 0.55, 0.85));

    // 3D twisting ribbon modulation (edges cross or pinch as the flat liquid sheet twists in air)
    const twist = cos(t * 180 * twistFreq);
    const signedHalfW = envW * twist;

    const lx = pts[i][0] - nx * signedHalfW;
    const ly = pts[i][1] - ny * signedHalfW;
    const rx = pts[i][0] + nx * signedHalfW;
    const ry = pts[i][1] + ny * signedHalfW;

    leftEdge.push([lx, ly, 0.55 + 0.45 * (1 - t)]);
    rightEdge.push([rx, ry, 0.65 + 0.5 * (1 - t)]);
    spineData.push({ x: pts[i][0], y: pts[i][1], tx, ty, nx, ny, w: signedHalfW, t });
  }

  // 1. Translucent Pale Celadon & Sky-Blue Watercolor Ribbon Fill (in small segments so twists render cleanly)
  const segStep = 10;
  brush.noStroke();
  for (let i = 0; i < pts.length - 1; i += segStep) {
    const end = min(pts.length - 1, i + segStep);
    const poly = [];
    for (let j = i; j <= end; j++) poly.push([leftEdge[j][0], leftEdge[j][1]]);
    for (let j = end; j >= i; j--) poly.push([rightEdge[j][0], rightEdge[j][1]]);

    const col = (i / segStep) % 2 === 0 ? PAL.celadonPale : PAL.skyPale;
    brush.wash(col, 155);
    drawPoly(poly, 0.05);
    brush.noWash();
  }

  // 2. Internal Liquid Refraction Filaments & White Caustic Streaks
  const filamentOffsets = [-0.62, -0.2, 0.25, 0.68];
  for (let f = 0; f < filamentOffsets.length; f++) {
    const fOff = filamentOffsets[f];
    const filPts = [];
    for (let i = 0; i < spineData.length; i += 2) {
      const s = spineData[i];
      const wave = 0.18 * sin(s.t * 360 * 1.5 + f * 60);
      const frac = constrain(fOff + wave, -0.92, 0.92);
      filPts.push([
        s.x + s.nx * s.w * frac,
        s.y + s.ny * s.w * frac,
        (1 - s.t * 0.65) * 0.85
      ]);
    }
    if (f % 2 === 0) {
      brush.set("glossTip", PAL.white, 0.72);
    } else {
      brush.set("crackPen", PAL.skyMid, 0.65);
    }
    brush.spline(filPts, 0.4);
  }

  // 3. Calligraphic Brown-Ink & White Caustic Ribbon Edges
  brush.set("crackPen", PAL.inkDark, 0.82);
  brush.spline(leftEdge, 0.4);
  brush.set("crackPen", PAL.inkMid, 0.75);
  brush.spline(rightEdge, 0.4);

  // Crisp white rim highlight just inside the upper edge
  const highlightRim = [];
  for (let i = 0; i < spineData.length; i += 2) {
    const s = spineData[i];
    highlightRim.push([
      s.x - s.nx * s.w * 0.78,
      s.y - s.ny * s.w * 0.78,
      (1 - s.t * 0.5) * 0.9
    ]);
  }
  brush.set("glossTip", PAL.white, 0.85);
  brush.spline(highlightRim, 0.4);

  return spineData;
}

