// Hyperrealistic Rose-Pink Sandstone Jali & Rose-Ringed Parakeet
// Rendered with p5.js 2.x and p5.brush in WEBGL mode

const SEED = 7482;

// Lattice geometric parameters (scaled for 1200x1200 canvas)
const CX0 = 600;
const CY0 = 490;
const D_GRID = 436;                 // Center-to-center distance between 6-pointed stars
const R_TIP = D_GRID / 2;           // 218 px: centerline star tip radius
const R_IN = R_TIP / Math.sqrt(3);  // ~125.86 px: centerline star inner corner & hex radius
const W_BAR = 21.5;                 // Half-width of stone bar to opening mouth (43 px total bar)
const B_BEV = 8.5;                  // Width of carved chamfered stone bevel
const D1 = W_BAR - B_BEV;           // 13 px: half-width of flat front sandstone strap
const D2 = W_BAR;                   // 21.5 px: inset to opening mouth
const DX_DEPTH = 18;                // 3D stone slab thickness vector X
const DY_DEPTH = 23;                // 3D stone slab thickness vector Y

let stars = [];
let hexes = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Custom fine barb brush for hyperrealistic feather barbs and micro-chisel marks
  brush.add("barb", {
    type: "default",
