// =============================================================================
// GEOMETRY BUILDER: INTERLOCKING HEXAGONAL STAR LATTICE
// =============================================================================

function buildLatticeGeometry() {
  stars = [];
  hexes = [];

  const starMap = new Map();
  const hexMap = new Map();

  // Basis vectors for star centers (triangular lattice of pitch D_GRID at 30 deg + k*60 deg)
  const u1x = D_GRID * Math.cos(Math.PI / 6);
  const u1y = D_GRID * Math.sin(Math.PI / 6);
  const u2x = 0;
  const u2y = D_GRID;

  for (let i = -3; i <= 3; i++) {
    for (let j = -3; j <= 3; j++) {
      const sx = CX0 + i * u1x + j * u2x;
      const sy = CY0 + i * u1y + j * u2y;

      if (sx > -320 && sx < width + 320 && sy > -320 && sy < height + 320) {
        const key = `${Math.round(sx)},${Math.round(sy)}`;
        if (!starMap.has(key)) {
          const isHero = (i === 0 && j === 0);
          const sObj = createStarCell(sx, sy, isHero);
          starMap.set(key, sObj);
          stars.push(sObj);
        }
      }

      // Around each star center, 6 Voronoi vertices host the interlocking hexagons
      const rCell = (2 / Math.sqrt(3)) * R_TIP;
      for (let k = 0; k < 6; k++) {
        const ang = (60 + k * 60) * (Math.PI / 180);
        const hx = sx + rCell * Math.cos(ang);
        const hy = sy + rCell * Math.sin(ang);
        if (hx > -260 && hx < width + 260 && hy > -260 && hy < height + 260) {
          const hKey = `${Math.round(hx / 4)},${Math.round(hy / 4)}`;
          if (!hexMap.has(hKey)) {
            const hObj = createHexCell(hx, hy);
            hexMap.set(hKey, hObj);
            hexes.push(hObj);
          }
        }
      }
    }
  }
}

function getStarVerts(cx, cy, d) {
  const rTip = R_TIP - 2 * d;
  const rIn = R_IN - (2 / Math.sqrt(3)) * d;
  const pts = [];
  for (let k = 0; k < 6; k++) {
    const aTip = (30 + k * 60) * (Math.PI / 180);
    pts.push([cx + rTip * Math.cos(aTip), cy + rTip * Math.sin(aTip)]);
    const aIn = (60 + k * 60) * (Math.PI / 180);
    pts.push([cx + rIn * Math.cos(aIn), cy + rIn * Math.sin(aIn)]);
  }
  return pts;
}

function getHexVerts(hx, hy, d) {
  const rHex = R_IN - (2 / Math.sqrt(3)) * d;
  const pts = [];
  for (let k = 0; k < 6; k++) {
    const a = (k * 60) * (Math.PI / 180);
    pts.push([hx + rHex * Math.cos(a), hy + rHex * Math.sin(a)]);
  }
  return pts;
}

function createStarCell(cx, cy, isHero) {
  const v0 = getStarVerts(cx, cy, -0.35); // Slight overlap at centerline to prevent hairline seams
  const v0Exact = getStarVerts(cx, cy, 0);
  const v1 = getStarVerts(cx, cy, D1);
  const v2 = getStarVerts(cx, cy, D2);
  return { cx, cy, isHero, v0, v0Exact, v1, v2, n: 12, type: "star" };
}

function createHexCell(hx, hy) {
  const v0 = getHexVerts(hx, hy, -0.35);
  const v0Exact = getHexVerts(hx, hy, 0);
  const v1 = getHexVerts(hx, hy, D1);
  const v2 = getHexVerts(hx, hy, D2);
  return { cx: hx, cy: hy, isHero: false, v0, v0Exact, v1, v2, n: 6, type: "hex" };
}

// =============================================================================
// POLYGON & CLIPPING HELPERS
// =============================================================================

function isPolyOnScreen(pts, margin = 80) {
  for (let i = 0; i < pts.length; i++) {
    if (
      pts[i][0] >= -margin &&
      pts[i][0] <= width + margin &&
      pts[i][1] >= -margin &&
      pts[i][1] <= height + margin
    ) {
      return true;
    }
  }
  return false;
}

function drawShapePoly(pts, curvature = 0) {
  if (!pts || pts.length < 3 || !isPolyOnScreen(pts, 150)) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Clip polygon against the left side (inward side for CW polygon) of directed line A -> B
function clipPolyInwardCW(poly, A, B) {
  if (!poly || poly.length === 0) return [];
  const out = [];
  const dx = B[0] - A[0];
  const dy = B[1] - A[1];
  // For clockwise vertices in screen coordinates (Y down), inward normal is (-dy, dx)
  const inside = (P) => -(P[0] - A[0]) * dy + (P[1] - A[1]) * dx >= -0.001;
  const intersect = (P1, P2) => {
    const rx = P2[0] - P1[0];
    const ry = P2[1] - P1[1];
    const denom = -rx * dy + ry * dx;
    if (Math.abs(denom) < 1e-6) return P1;
    const t = ((P1[0] - A[0]) * dy - (P1[1] - A[1]) * dx) / denom;
    return [P1[0] + t * rx, P1[1] + t * ry];
  };

  for (let i = 0; i < poly.length; i++) {
    const cur = poly[i];
    const prev = poly[(i + poly.length - 1) % poly.length];
    const curIn = inside(cur);
    const prevIn = inside(prev);
    if (curIn) {
      if (!prevIn) out.push(intersect(prev, cur));
      out.push(cur);
    } else if (prevIn) {
      out.push(intersect(prev, cur));
    }
  }
  return out;
}

// Compute inward normal for CW edge A -> B in screen coords (Y down)
function edgeInwardNormal(A, B) {
  const dx = B[0] - A[0];
  const dy = B[1] - A[1];
  const len = Math.hypot(dx, dy) || 1;
  return [-dy / len, dx / len];
}

// =============================================================================
// 1. HAZY OCHRE COURTYARD IN DUSKY TWILIGHT WASHES
// =============================================================================

function drawCourtyardWashes() {
  brush.noStroke();
  brush.noHatch();

  // Broad atmospheric washes across canvas
  const skyBands = [
    { y: -40, h: 320, col: "#b57d6e", op: 110 },
    { y: 180, h: 340, col: "#cc9668", op: 115 },
    { y: 420, h: 380, col: "#dbab74", op: 120 },
    { y: 720, h: 340, col: "#c4885c", op: 115 },
    { y: 960, h: 280, col: "#9e6652", op: 125 }
  ];

  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.68, 0.28);
  for (let b of skyBands) {
    brush.fill(b.col, b.op);
    brush.rect(-40, b.y, width + 80, b.h, "corner");
  }

  // Hazy distant courtyard architectural hints (soft arches, colonnade shadows, warm ochre walls)
  const allCells = [...stars, ...hexes];
  for (let cell of allCells) {
    if (!isPolyOnScreen(cell.v2, 60)) continue;
    const cx = cell.cx;
    const cy = cell.cy;

    // Warm golden-ochre bloom inside each opening
    const ochrePalette = ["#e3b578", "#d6a065", "#c98b5b", "#cfa06e", "#bf8262"];
    const baseCol = ochrePalette[Math.floor(noise(cx * 0.005, cy * 0.005) * ochrePalette.length)];
    brush.fill(baseCol, 95);
    brush.fillBleed(0.38, "out");
    drawShapePoly(cell.v2, 0.08);

    // Distant twilight mauve-umber architectural shadow wash in upper/side portion of opening
    if (cy < 780) {
      const archCol = cy < 420 ? "#8c5c63" : "#996859";
      brush.fill(archCol, 72);
      brush.fillBleed(0.42, "out");
      const r = cell.type === "star" ? 88 : 65;
      brush.circle(cx + random(-22, 22), cy - r * 0.32, r * 0.72, 0.25);
    } else {
      // Lower courtyard warm terracotta flagstone wash
      brush.fill("#8f5547", 78);
      brush.fillBleed(0.35, "out");
      brush.circle(cx + random(-18, 18), cy + 20, 68, 0.22);
    }

    // Subtle olive-ochre distant courtyard foliage whisper in a few openings
    if (!cell.isHero && noise(cx * 0.01 + 10, cy * 0.01) > 0.56) {
      brush.fill("#7d7d58", 52);
      brush.fillBleed(0.45, "out");
      brush.circle(cx + random(-25, 25), cy + random(-15, 25), random(38, 64), 0.3);
    }

    // Luminous dusty twilight light-haze core
    brush.fill("#f0cba3", 62);
    brush.fillBleed(0.35, "in");
    brush.circle(cx - 12, cy - 10, cell.type === "star" ? 62 : 44, 0.2);
  }

  // Soft granulation stipple over the courtyard openings
  brush.set("spray", "#7d4e4d", 1.1);
  for (let i = 0; i < 65; i++) {
    const x = random(40, width - 40);
    const y = random(40, height - 40);
    brush.line(x, y, x + random(-35, 35), y + random(-15, 15));
  }
  brush.set("spray", "#ebd0a4", 0.9);
  for (let i = 0; i < 55; i++) {
    const x = random(40, width - 40);
    const y = random(40, height - 40);
    brush.line(x, y, x + random(-30, 30), y + random(-12, 12));
  }
  brush.noStroke();
}

// =============================================================================
// 2. 3D INNER THICKNESS WALLS (REVEALS) OF THE SANDSTONE SCREEN
// =============================================================================

function getClippedRevealQuad(cell, i) {
  const n = cell.n;
  const A = cell.v2[i];
  const B = cell.v2[(i + 1) % n];
  const norm = edgeInwardNormal(A, B);

  // Only edges whose inward normal has positive dot product with depth vector are visible reveals
  const dot = norm[0] * DX_DEPTH + norm[1] * DY_DEPTH;
  if (dot <= 0.5) return null;

  let quad = [
    [A[0], A[1]],
    [B[0], B[1]],
    [B[0] + DX_DEPTH, B[1] + DY_DEPTH],
    [A[0] + DX_DEPTH, A[1] + DY_DEPTH]
  ];

  if (cell.type === "hex") {
    // Hex opening is strictly convex: clip reveal quad against all 6 edges of the hex opening
    for (let k = 0; k < 6; k++) {
      quad = clipPolyInwardCW(quad, cell.v2[k], cell.v2[(k + 1) % 6]);
    }
  } else {
    // Star opening: clip at the convex 60-degree outer tips (even-indexed vertices)
    const prevIdx = (i + n - 1) % n;
    const nextIdx = (i + 1) % n;
    if (i % 2 === 0) {
      // Vertex i is an outer tip: clip against previous edge (prevIdx -> i)
      quad = clipPolyInwardCW(quad, cell.v2[prevIdx], cell.v2[i]);
    }
    if (nextIdx % 2 === 0) {
      // Vertex i+1 is an outer tip: clip against next edge (nextIdx -> nextIdx+1)
      quad = clipPolyInwardCW(quad, cell.v2[nextIdx], cell.v2[(nextIdx + 1) % n]);
    }
  }

  return quad && quad.length >= 3 ? { quad, norm, A, B } : null;
}

function drawStoneReveals() {
  brush.noStroke();
  brush.noHatch();

  const deepShadowReveals = [];
  const midPlumReveals = [];
  const warmBounceReveals = [];
  const allReveals = [];

  const allCells = [...stars, ...hexes];
  for (let cell of allCells) {
    if (!isPolyOnScreen(cell.v2, 80)) continue;
    for (let i = 0; i < cell.n; i++) {
      const rev = getClippedRevealQuad(cell, i);
      if (!rev) continue;
      allReveals.push(rev);

      // Classify reveal orientation for layered twilight shadow glazes
      // Light is from upper-left; reveals facing down-right (norm.y > 0.35) are in deepest plum shadow
      // Reveals facing more horizontally or catching courtyard bounce get warmer sienna-rose glazes
      if (rev.norm[1] > 0.45) {
        deepShadowReveals.push(rev.quad);
      } else if (rev.norm[0] > 0.65 && rev.norm[1] <= 0.45) {
        midPlumReveals.push(rev.quad);
      } else {
        warmBounceReveals.push(rev.quad);
      }
    }
  }

  // Base opaque wash so reveals cleanly occlude the courtyard behind them
  for (let q of deepShadowReveals) {
    brush.wash("#5c323b", 235);
    drawShapePoly(q, 0);
  }
  for (let q of midPlumReveals) {
    brush.wash("#6e3e45", 235);
    drawShapePoly(q, 0);
  }
  for (let q of warmBounceReveals) {
    brush.wash("#804b4c", 235);
    drawShapePoly(q, 0);
  }
  brush.noWash();

  // Layered watercolor shadow glazes on the reveals
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.65, 0.42);

  brush.fill("#47232d", 115);
  for (let q of deepShadowReveals) drawShapePoly(q, 0);

  brush.fill("#5e3139", 105);
  for (let q of midPlumReveals) drawShapePoly(q, 0);

  brush.fill("#94584e", 100);
  for (let q of warmBounceReveals) drawShapePoly(q, 0);

  brush.noFill();

  // Chisel striations & back-edge rim along each 3D inner reveal
  for (let rev of allReveals) {
    const A = rev.A;
    const B = rev.B;
    const len = Math.hypot(B[0] - A[0], B[1] - A[1]);
    const steps = Math.max(3, Math.floor(len / 9));

    // Fine chisel tool marks across the stone thickness
    brush.set("chisel", "#3d1d26", 0.55);
    for (let s = 1; s < steps; s++) {
      const t = s / steps + random(-0.02, 0.02);
      const px = lerp(A[0], B[0], t);
      const py = lerp(A[1], B[1], t);
      brush.line(
        px + DX_DEPTH * 0.15,
        py + DY_DEPTH * 0.15,
        px + DX_DEPTH * 0.85,
        py + DY_DEPTH * 0.85
      );
    }

    // Subtle back-rim line where reveal meets the courtyard space
    brush.set("2H", "#45222b", 0.5);
    const q = rev.quad;
    if (q.length >= 4) {
      brush.line(q[2][0], q[2][1], q[3][0], q[3][1]);
    }
  }
  brush.noStroke();
}

// =============================================================================
// 3. FLAT FRONT SANDSTONE STRAPS
// =============================================================================

function drawFlatStoneStraps() {
  brush.noStroke();
  brush.noHatch();

  const buckets = [[], [], []];
  const allCells = [...stars, ...hexes];

  for (let cell of allCells) {
    if (!isPolyOnScreen(cell.v0, 100)) continue;
    const n = cell.n;
    for (let i = 0; i < n; i++) {
      const ni = (i + 1) % n;
      const quad = [cell.v0[i], cell.v0[ni], cell.v1[ni], cell.v1[i]];
      if (!isPolyOnScreen(quad, 60)) continue;
      const mx = (cell.v0[i][0] + cell.v0[ni][0]) * 0.5;
      const my = (cell.v0[i][1] + cell.v0[ni][1]) * 0.5;
      const bIdx = Math.floor(noise(mx * 0.006, my * 0.006) * 3) % 3;
      buckets[bIdx].push(quad);
    }
  }

  // Solid sandstone under-wash (rose-pink twilight tones)
  const baseCols = ["#c4837b", "#ba7872", "#cf8f85"];
  for (let b = 0; b < 3; b++) {
    brush.wash(baseCols[b], 248);
    for (let q of buckets[b]) {
      drawShapePoly(q, 0);
    }
  }
  brush.noWash();

  // Layered translucent rose-pink & dusty twilight glazes on the front face
  const glazeCols = ["#d99b90", "#a66462", "#e0ab9e"];
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.62, 0.35);
  for (let b = 0; b < 3; b++) {
    brush.fill(glazeCols[b], 72);
    for (let i = 0; i < buckets[b].length; i += 2) {
      drawShapePoly(buckets[b][i], 0);
    }
  }
  brush.noFill();
}

// =============================================================================
// 4. CARVED CHAMFERED STONE BEVELS (LAYERED SHADOW GLAZES)
// =============================================================================

function drawCarvedBevels() {
  brush.noStroke();
  brush.noHatch();

  // Light direction from upper-left (-0.6, -0.8)
  // A bevel whose inward normal points toward (-0.6, -0.8) faces the light!
  const litBevels = [];
  const warmMidBevels = [];
  const coolMidBevels = [];
  const shadowBevels = [];
  const allBevelData = [];

  const allCells = [...stars, ...hexes];
  for (let cell of allCells) {
    if (!isPolyOnScreen(cell.v1, 90)) continue;
    const n = cell.n;
    for (let i = 0; i < n; i++) {
      const ni = (i + 1) % n;
      const quad = [cell.v1[i], cell.v1[ni], cell.v2[ni], cell.v2[i]];
      if (!isPolyOnScreen(quad, 60)) continue;

      const norm = edgeInwardNormal(cell.v1[i], cell.v1[ni]);
      // Dot product with light ray coming from upper-left (-0.58, -0.81)
      const lightCatch = norm[0] * -0.58 + norm[1] * -0.81;

      allBevelData.push({ quad, norm, lightCatch, p1: cell.v1[i], p2: cell.v1[ni], p3: cell.v2[ni], p4: cell.v2[i] });

      if (lightCatch > 0.35) {
        litBevels.push(quad);
      } else if (lightCatch > -0.05) {
        warmMidBevels.push(quad);
      } else if (lightCatch > -0.45) {
        coolMidBevels.push(quad);
      } else {
        shadowBevels.push(quad);
      }
    }
  }

  // Opaque base wash for each bevel group
  const groups = [
    { list: litBevels, washCol: "#dba193", glazeCol: "#ebbaa8", glazeOp: 95 },
    { list: warmMidBevels, washCol: "#bf7e76", glazeCol: "#cf8e82", glazeOp: 88 },
    { list: coolMidBevels, washCol: "#9e5e5e", glazeCol: "#8a4d52", glazeOp: 95 },
    { list: shadowBevels, washCol: "#82474c", glazeCol: "#6b363f", glazeOp: 110 }
  ];

  for (let g of groups) {
    brush.wash(g.washCol, 245);
    for (let q of g.list) drawShapePoly(q, 0);
  }
  brush.noWash();

  // Layered watercolor shadow/light glazes so depth reads through warm glazes
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.66, 0.4);
  for (let g of groups) {
    brush.fill(g.glazeCol, g.glazeOp);
    for (let q of g.list) drawShapePoly(q, 0);
  }
  brush.noFill();

  // Chisel tooling marks and weathered edges along every bevel
  for (let b of allBevelData) {
    const A1 = b.p1;
    const B1 = b.p2;
    const B2 = b.p3;
    const A2 = b.p4;
    const len = Math.hypot(B1[0] - A1[0], B1[1] - A1[1]);
    const steps = Math.max(4, Math.floor(len / 7.5));

    // Transverse chisel marks across the bevel width
    const markCol = b.lightCatch > 0.1 ? "#9e5f5a" : "#592d35";
    brush.set("chisel", markCol, 0.48);
    for (let s = 1; s < steps; s++) {
      const t = s / steps + random(-0.018, 0.018);
      const t2 = constrain(t + 0.025, 0.02, 0.98);
      const x1 = lerp(A1[0], B1[0], t);
      const y1 = lerp(A1[1], B1[1], t);
      const x2 = lerp(A2[0], B2[0], t2);
      const y2 = lerp(A2[1], B2[1], t2);
      brush.line(x1, y1, x2, y2);
    }

    // Dusty highlight catch-marks on sunlit bevels
    if (b.lightCatch > 0.15) {
      brush.set("2H", "#f5cfc0", 0.42);
      for (let s = 1; s < steps; s += 2) {
        const t = s / steps;
        const x1 = lerp(A1[0], B1[0], t);
        const y1 = lerp(A1[1], B1[1], t);
        const x2 = lerp(A2[0], B2[0], t);
        const y2 = lerp(A2[1], B2[1], t);
        brush.line(x1, y1, x2, y2);
      }
    }

    // Outer bevel arris (ridge between flat front face and chamfer)
    const ridgeCol = b.lightCatch > 0.1 ? "#f2c6b6" : "#874b4e";
    brush.set("2H", ridgeCol, 0.55);
    brush.line(A1[0], A1[1], B1[0], B1[1]);

    // Inner mouth edge (where chamfer meets the opening / 3D reveal)
    const mouthCol = b.lightCatch > 0.2 ? "#e8b4a2" : "#4f252e";
    brush.set("HB", mouthCol, 0.62);
    brush.line(A2[0], A2[1], B2[0], B2[1]);
  }
  brush.noStroke();
}

// =============================================================================
// 5. SANDSTONE CHISEL TOOLING, INTERLOCKING GROOVES, PITTING & WEATHERING
// =============================================================================

function drawSandstoneDetailAndWeathering() {
  // A. Carved median interlocking groove along the stone strap centerlines
  for (let star of stars) {
    if (!isPolyOnScreen(star.v0Exact, 90)) continue;
    const n = star.n;
    for (let i = 0; i < n; i++) {
      const A = star.v0Exact[i];
      const B = star.v0Exact[(i + 1) % n];
      if (!isPolyOnScreen([A, B], 40)) continue;

      const dx = B[0] - A[0];
      const dy = B[1] - A[1];
      const len = Math.hypot(dx, dy) || 1;
      const ux = dx / len;
      const uy = dy / len;
      const nx = -uy;
      const ny = ux;

      // Interlocking weave offset: alternate straps stop slightly short at the star tip
      const trimStart = i % 2 === 0 ? 11 : 2;
      const trimEnd = i % 2 === 1 ? 11 : 2;
      const sx = A[0] + ux * trimStart;
      const sy = A[1] + uy * trimStart;
      const ex = B[0] - ux * trimEnd;
      const ey = B[1] - uy * trimEnd;

      // Shadow side of carved median V-groove
      brush.set("2H", "#753f44", 0.58);
      brush.line(sx, sy, ex, ey);

      // Sunlit lip of carved median V-groove
      brush.set("2H", "#ebbfb0", 0.45);
      brush.line(sx + nx * 1.6, sy + ny * 1.6, ex + nx * 1.6, ey + ny * 1.6);

      // Over-under interlocking strap crossing line at the star tips
      if (i % 2 === 0) {
        brush.set("2H", "#6e393f", 0.52);
        brush.line(
          A[0] + ux * 11 - nx * D1 * 0.9,
          A[1] + uy * 11 - ny * D1 * 0.9,
          A[0] + ux * 11 + nx * D1 * 0.9,
          A[1] + uy * 11 + ny * D1 * 0.9
        );
      }

      // Parallel drove-chisel marks across the flat sandstone bar
      const steps = Math.floor(len / 6.5);
      for (let s = 2; s < steps - 1; s++) {
        const t = s / steps + random(-0.015, 0.015);
        const px = lerp(A[0], B[0], t);
        const py = lerp(A[1], B[1], t);
        const side = s % 2 === 0 ? 1 : -1;
        const dStart = random(2.2, 4.5) * side;
        const dEnd = random(8.5, 11.8) * side;

        brush.set("chisel", s % 3 === 0 ? "#854b4e" : "#9c5e5d", 0.42);
        brush.line(
          px + nx * dStart - ux * 1.5,
          py + ny * dStart - uy * 1.5,
          px + nx * dEnd + ux * 1.5,
          py + ny * dEnd + uy * 1.5
        );

        if (s % 4 === 0) {
          brush.set("2H", "#edd4c7", 0.34);
          brush.line(
            px + nx * dStart,
            py + ny * dStart,
            px + nx * dEnd,
            py + ny * dEnd
          );
        }
      }
    }
  }

  // B. Pitting, spalled edge nicks, and dusty mineral weathering on the stone
  const allCells = [...stars, ...hexes];
  for (let cell of allCells) {
    if (!isPolyOnScreen(cell.v1, 60)) continue;
    const n = cell.n;
    for (let i = 0; i < n; i++) {
      const A = cell.v1[i];
      const B = cell.v1[(i + 1) % n];
      const A2 = cell.v2[i];
      const B2 = cell.v2[(i + 1) % n];

      // 4 to 7 erosion pits & edge chips per stone bar segment
      const pitCount = cell.type === "star" ? 6 : 4;
      for (let p = 0; p < pitCount; p++) {
        const t = random(0.08, 0.92);
        const band = random();
        let px, py;
        if (band < 0.55) {
          // Pit on flat bar or outer bevel arris
          px = lerp(A[0], B[0], t) + random(-7, 7);
          py = lerp(A[1], B[1], t) + random(-7, 7);
        } else {
          // Chip right on the carved stone edge
          px = lerp(A2[0], B2[0], t) + random(-2.5, 2.5);
          py = lerp(A2[1], B2[1], t) + random(-2.5, 2.5);
        }

        if (px < 5 || px > width - 5 || py < 5 || py > height - 5) continue;
        const rPit = random(1.2, 3.8);

        // Dark eroded pit cavity (upper-left shadow inside pit)
        brush.set("cpencil", "#4f252d", random(0.55, 0.95));
        brush.line(px - rPit * 0.6, py - rPit * 0.4, px + rPit * 0.6, py - rPit * 0.1);
        brush.line(px - rPit * 0.4, py - rPit * 0.2, px + rPit * 0.3, py + rPit * 0.4);

        // Pale dusty catchlight along the bottom-right rim of the pit
        brush.set("2H", "#f2cfc0", random(0.4, 0.65));
        brush.line(px - rPit * 0.3, py + rPit * 0.55, px + rPit * 0.75, py + rPit * 0.25);
      }

      // Occasional hairline weathering fissure / masonry joint across a bar
      if (random() < 0.14) {
        const t = random(0.25, 0.75);
        const jx1 = lerp(cell.v0Exact[i][0], cell.v0Exact[(i + 1) % n][0], t);
        const jy1 = lerp(cell.v0Exact[i][1], cell.v0Exact[(i + 1) % n][1], t);
        const jx2 = lerp(A2[0], B2[0], t + random(-0.03, 0.03));
        const jy2 = lerp(A2[1], B2[1], t + random(-0.03, 0.03));
        brush.set("rotring", "#542830", 0.38);
        brush.line(jx1, jy1, jx2, jy2);
        brush.set("2H", "#ebcabd", 0.32);
        brush.line(jx1 + 1.2, jy1 + 1.2, jx2 + 1.2, jy2 + 1.2);
      }
    }
  }

  // C. Dusty twilight sandstone grain (fine spray passes in buff, rose, and umber)
  for (let cell of stars) {
    if (!isPolyOnScreen(cell.v0, 40)) continue;
    for (let i = 0; i < cell.n; i++) {
      const A = cell.v0[i];
      const B = cell.v1[(i + 1) % cell.n];
      brush.set("spray", i % 2 === 0 ? "#e8bfb0" : "#784146", 0.65);
      brush.line(A[0], A[1], B[0], B[1]);
    }
  }
  brush.noStroke();
}

// =============================================================================
// 6. CAST SHADOW OF THE PARAKEET ON THE SANDSTONE
// =============================================================================

function drawParakeetCastShadow() {
  brush.noStroke();
  brush.noHatch();

  // Soft dusky plum-violet shadow glaze cast by the parakeet's lower belly, feet, and tail onto the stone
  brush.fill("#4f2632", 92);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.6, 0.3);

  // Shadow under feet & lower belly on the lower-left bevel of the central star
  const footShadow = [
    [548, 576],
    [598, 632],
    [608, 668],
    [575, 650],
    [540, 594]
  ];
  drawShapePoly(footShadow, 0.2);

  // Long tail shadow glaze falling slightly down-right across the lower sandstone bars
  const tailShadow = [
    [618, 628],
    [640, 628],
    [690, 1062],
    [672, 1068]
  ];
  drawShapePoly(tailShadow, 0.1);
  brush.noFill();
}

// =============================================================================
// 7. HYPERREALISTIC ROSE-RINGED PARAKEET (WATERCOLOUR + BARB-BY-BARB PLUMAGE)
// =============================================================================

// Render a single feather with watercolour under-wash, central rachis, and individual barbs
function drawDetailedFeather(opts) {
  const {
    x,
    y,
    len,
    wid,
    ang,         // Degrees in screen space (0 = right, 90 = down)
    curve = 0,   // Slight curvature offset perpendicular to shaft
    washCol,
    washOp = 85,
    shaftCol = "#d9f08a",
    barbCols,    // Array of [viridian, lime, turquoise] hex strings
    barbDensity = 0.85,
    barbAngle = 32
  } = opts;

  const rad = ang * (Math.PI / 180);
  const ux = Math.cos(rad);
  const uy = Math.sin(rad);
  const nx = -uy;
  const ny = ux;

  // 1. Optional translucent watercolour drop-wash for the feather vane
  if (washCol) {
    const fPoly = [
      [x, y],
      [x + ux * len * 0.35 + nx * wid * 0.52, y + uy * len * 0.35 + ny * wid * 0.52],
      [x + ux * len * 0.78 + nx * (wid * 0.38 + curve * 0.7), y + uy * len * 0.78 + ny * (wid * 0.38 + curve * 0.7)],
      [x + ux * len + nx * curve, y + uy * len + ny * curve],
      [x + ux * len * 0.78 - nx * (wid * 0.38 - curve * 0.7), y + uy * len * 0.78 - ny * (wid * 0.38 - curve * 0.7)],
      [x + ux * len * 0.35 - nx * wid * 0.52, y + uy * len * 0.35 - ny * wid * 0.52]
    ];
    brush.noStroke();
    brush.fill(washCol, washOp);
    brush.fillBleed(0.18, "out");
    drawShapePoly(fPoly, 0.25);
    brush.noFill();
  }

  // 2. Individual feather barbs radiating from both sides of the rachis
  const steps = Math.max(6, Math.floor(len * barbDensity));
  const bRad = barbAngle * (Math.PI / 180);

  for (let s = 1; s <= steps; s++) {
    const t = s / steps;
    // Parabolic curve along shaft
    const cOff = curve * (t * t);
    const sx = x + ux * (len * t) + nx * cOff;
    const sy = y + uy * (len * t) + ny * cOff;

    // Envelope width of the feather at position t
    const env = Math.sin(Math.pow(t, 0.65) * Math.PI) * wid * 0.55;
    if (env < 0.6) continue;

    // Slight natural ruffling / separation between barbules
    const gapJitter = noise(x * 0.05 + s * 0.35, y * 0.05) - 0.48;
    const bLen = env / Math.sin(bRad);

    for (let side of [-1, 1]) {
      const barbDir = rad + side * bRad + gapJitter * 0.16;
      const bx = sx + Math.cos(barbDir) * bLen * (0.92 + 0.14 * noise(s, side + 5));
      const by = sy + Math.sin(barbDir) * bLen * (0.92 + 0.14 * noise(s, side + 5));

      // Select viridian, lime, or turquoise barb color based on side & position along shaft
      let cIdx;
      if (side === -1) {
        // Upper/outer web catches more sunlit lime & turquoise
        cIdx = t > 0.65 ? 1 : (s % 3 === 0 ? 2 : 1);
      } else {
        // Lower/inner web has deeper viridian & turquoise shadow tones
        cIdx = t < 0.45 ? 0 : (s % 2 === 0 ? 0 : 2);
      }
      const col = barbCols[cIdx % barbCols.length];

      brush.set("barb", col, 0.78 + 0.28 * (1 - t));
      brush.line(sx, sy, bx, by);
    }
  }

  // 3. Central rachis (feather shaft)
  brush.set("barb", shaftCol, 0.72);
  brush.spline(
    [
      [x, y, 0.9],
      [x + ux * len * 0.5 + nx * curve * 0.25, y + uy * len * 0.5 + ny * curve * 0.25, 0.65],
      [x + ux * len + nx * curve, y + uy * len + ny * curve, 0.2]
    ],
    0.35
  );
}

