function drawParakeetFeet() {
  // Right foot (upper-left on stone corner around 552, 577) & Left foot (lower-right on bevel around 578, 616)
  const toes = [
    // Upper foot gripping the horizontal/corner stone bevel edge
    { pts: [[560, 568], [550, 574], [540, 581]], claw: [[540, 581], [535, 589]] },
    { pts: [[564, 571], [555, 580], [548, 591]], claw: [[548, 591], [545, 600]] },
    { pts: [[566, 570], [568, 562], [566, 555]], claw: [[566, 555], [562, 551]] },
    // Lower foot gripping the angled 60-deg stone bevel
    { pts: [[584, 598], [576, 610], [567, 620]], claw: [[567, 620], [562, 629]] },
    { pts: [[588, 601], [582, 615], [576, 627]], claw: [[576, 627], [573, 637]] },
    { pts: [[590, 598], [595, 592], [596, 585]], claw: [[596, 585], [593, 580]] }
  ];

  for (let t of toes) {
    // Fleshy grey-ochre scaly toe base
    brush.set("marker", "#7d736a", 2.2);
    brush.spline(t.pts, 0.35);

    brush.set("cpencil", "#aba095", 1.1);
    brush.spline(t.pts, 0.35);

    // Transverse keratin scute rings along each toe
    brush.set("rotring", "#453e39", 0.48);
    for (let s = 0.2; s <= 0.85; s += 0.22) {
      const tx = lerp(t.pts[0][0], t.pts[2][0], s);
      const ty = lerp(t.pts[0][1], t.pts[2][1], s);
      brush.line(tx - 2.5, ty - 1.5, tx + 2.5, ty + 1.5);
    }

    // Curved dark horn claw gripping a chisel pit in the sandstone
    brush.set("pen", "#211c1b", 0.95);
    brush.line(t.claw[0][0], t.claw[0][1], t.claw[1][0], t.claw[1][1]);
    brush.set("2H", "#d4c8be", 0.38);
    brush.line(t.claw[0][0] - 0.6, t.claw[0][1], t.claw[1][0] - 0.6, t.claw[1][1]);
  }
  brush.noStroke();
}

function drawCoralBeakAndEye() {
