  brush.set("cpencil", "#592b31", 0.65);
  brush.line(547, 412, 565, 415);
  brush.noStroke();

  // 2. Upper Mandible (hooked coral-red / vermilion-crimson bill)
  const upperBeak = [
    [569, 381], // Top of culmen at cere
    [551, 382], // Upper culmen arch
    [537, 391], // Hook curve
    [531, 406], // Hook lower curve
