  ];

  // Solid coral-red wash
  brush.wash("#d93b2b", 252);
  drawShapePoly(upperBeak, 0.22);
  brush.noWash();

  // Layered crimson shadow at base & cutting edge, glowing coral-orange on upper ridge
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.55, 0.35);
  brush.fill("#8f1616", 110);
  drawShapePoly(
    [
      [554, 395],
      [569, 394],
      [569, 406],
      [541, 410],
      [532, 419],
      [535, 404]
    ],
    0.2
  );

  // Luminous coral-salmon highlight along culmen ridge
  brush.fill("#ff8570", 120);
  drawShapePoly(
    [
      [567, 382],
      [550, 383],
      [538, 392],
      [543, 396],
      [565, 389]
    ],
    0.25
  );
  brush.noFill();

  // Fine keratin texture & specular ridge on the coral beak
  brush.set("2H", "#ffb8a8", 0.65);
  brush.spline([[566, 384, 0.8], [550, 385, 1.0], [537, 395, 0.6], [533, 412, 0.3]], 0.4);

  brush.set("rotring", "#540d10", 0.52);
  brush.spline([[532, 419, 0.8], [541, 410, 0.7], [555, 406, 0.8], [569, 406, 0.6]], 0.3);

  // Fleshy cere & nostril at base of upper mandible
  brush.set("cpencil", "#b85c56", 0.85);
  brush.circle(568, 387, 3.2, 0.2);
  brush.set("rotring", "#3b1416", 0.55);
  brush.circle(568, 387, 1.2, 0.1);

  // 3. Inky Eye-Ring, Lore Line, Pale Cream-Yellow Iris & Specular Pupil
  const ex = 588;
  const ey = 392;

  // Fine dark loral line connecting cere to eye-ring
  brush.set("barb", "#181a22", 0.95);
  for (let i = -2; i <= 2; i++) {
    brush.line(570, 388 + i * 0.7, ex - 6, ey + i * 0.8);
  }

  // Outer inky periorbital eye-ring (layered charcoal-black wash + fine radial skin papillae)
  brush.noStroke();
  brush.wash("#14161e", 252);
  brush.circle(ex, ey, 8.2, 0.15);
  brush.noWash();

  brush.set("barb", "#0c0d12", 0.85);
  for (let a = 0; a < 360; a += 15) {
    const rad = a * (Math.PI / 180);
    brush.line(
      ex + Math.cos(rad) * 5.8,
      ey + Math.sin(rad) * 5.8,
      ex + Math.cos(rad) * 8.8,
      ey + Math.sin(rad) * 8.8
    );
  }
  // Subtle slate-grey catchlight on lower eyelid rim
  brush.set("2H", "#6c7385", 0.45);
  brush.arc(ex, ey, 7.6, 25, 155);
  brush.noStroke();

  // Luminous pale yellow-cream iris
  brush.wash("#f2de82", 252);
  brush.circle(ex, ey, 5.2, 0.1);
  brush.noWash();

  brush.set("rotring", "#d49b35", 0.42);
  brush.circle(ex, ey, 4.9, 0.1);

  // Velvety jet-black pupil
  brush.noStroke();
  brush.wash("#08090d", 255);
  brush.circle(ex - 0.4, ey, 3.1, 0.08);
  brush.noWash();

  // Crisp pinpoint twilight catchlight on upper-left of pupil
  brush.wash("#fffdf7", 255);
  brush.circle(ex - 1.6, ey - 1.4, 1.15, 0.05);
  brush.noWash();

  brush.set("2H", "#ffffff", 0.55);
  brush.line(ex - 2.1, ey - 1.5, ex - 1.0, ey - 1.3);
  brush.noStroke();
}

