  { y0: 1064, y1: 1125, dx: 14,   tear: true  },
  { y0: 1125, y1: 1200, dx: 0,    tear: false }
];

function getBand(y) {
  for (let i = 0; i < Y_BANDS.length; i++) {
    if (y >= Y_BANDS[i].y0 && y <= Y_BANDS[i].y1) return Y_BANDS[i];
  }
  return Y_BANDS[0];
}

function getDx(y) {
  let b = getBand(y);
  let wobble = Math.sin(y * 0.08) * 1.8 + Math.cos(y * 0.37) * 1.1;
  return b.dx + wobble;
}

// Clip a polygon to horizontal slab [yMin, yMax]
function clipPolySlab(pts, yMin, yMax) {
  if (!pts || pts.length < 3) return [];
  // Clip against y >= yMin
  let out1 = [];
  for (let i = 0; i < pts.length; i++) {
    let curr = pts[i];
    let prev = pts[(i + pts.length - 1) % pts.length];
    let cIn = curr[1] >= yMin;
    let pIn = prev[1] >= yMin;
    if (cIn !== pIn) {
      let t = (yMin - prev[1]) / (curr[1] - prev[1] || 1e-6);
      out1.push([prev[0] + t * (curr[0] - prev[0]), yMin]);
    }
    if (cIn) out1.push([curr[0], curr[1]]);
  }
  if (out1.length < 3) return [];
  // Clip against y <= yMax
  let out2 = [];
  for (let i = 0; i < out1.length; i++) {
    let curr = out1[i];
    let prev = out1[(i + out1.length - 1) % out1.length];
    let cIn = curr[1] <= yMax;
    let pIn = prev[1] <= yMax;
    if (cIn !== pIn) {
      let t = (yMax - prev[1]) / (curr[1] - prev[1] || 1e-6);
      out2.push([prev[0] + t * (curr[0] - prev[0]), yMax]);
    }
    if (cIn) out2.push([curr[0], curr[1]]);
  }
  return out2;
}

function emitShape(pts, curvature = 0.08) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Renders a polygon sliced across all horizontal VHS bands, with optional cyan/magenta chroma fringe
function drawSlicedWash(pts, col, opacity, opts = {}) {
  let curv = opts.curvature !== undefined ? opts.curvature : 0.08;
  let fringe = opts.fringe || 0;
  let fringeAlpha = opts.fringeAlpha || Math.min(opacity * 0.55, 85);

  // Optional Chroma Bleed Passes (Cyan left, Magenta right)
  if (fringe > 0) {
    brush.noStroke();
    brush.noFill();
    brush.wash(PAL.cyanFringe, fringeAlpha);
    for (let b of Y_BANDS) {
      let sub = clipPolySlab(pts, b.y0 - 0.5, b.y1 + 0.5);
      if (sub.length >= 3) {
        let extra = b.tear ? fringe * 1.45 : fringe;
        let shifted = sub.map(p => [p[0] + b.dx - extra, p[1]]);
        emitShape(shifted, curv);
      }
    }
    brush.wash(PAL.magentaFringe, fringeAlpha);
    for (let b of Y_BANDS) {
      let sub = clipPolySlab(pts, b.y0 - 0.5, b.y1 + 0.5);
      if (sub.length >= 3) {
        let extra = b.tear ? fringe * 1.45 : fringe;
        let shifted = sub.map(p => [p[0] + b.dx + extra, p[1]]);
        emitShape(shifted, curv);
      }
    }
  }

  // Main Wash Pass
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opacity);
  for (let b of Y_BANDS) {
    let sub = clipPolySlab(pts, b.y0 - 0.5, b.y1 + 0.5);
    if (sub.length >= 3) {
      let shifted = sub.map(p => [p[0] + b.dx, p[1]]);
      emitShape(shifted, curv);
    }
  }
  brush.noWash();
}

// Helper to create organic elliptical / sculpted blob polygons
function makeBlob(cx, cy, rx, ry, n = 24, deformFn = null) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * TWO_PI;
    let dx = Math.cos(a) * rx;
    let dy = Math.sin(a) * ry;
    if (deformFn) {
      let mod = deformFn(a, dx, dy);
      dx = mod[0];
      dy = mod[1];
    }
    pts.push([cx + dx, cy + dy]);
  }
  return pts;
}

// Draw a spline that obeys horizontal slice tearing and optional chroma bleed
function drawSlicedSpline(pts, brushName, col, weight, curv = 0.5, fringeOffset = 0) {
  if (pts.length < 2) return;
  // Subdivide dense points so tears are sharp
  let dense = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i];
    let p1 = pts[i + 1];
    let dist = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]);
    let steps = Math.max(2, Math.ceil(dist / 10));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let x = p0[0] + (p1[0] - p0[0]) * t;
      let y = p0[1] + (p1[1] - p0[1]) * t;
      let pr = p0[2] !== undefined ? p0[2] + ((p1[2] !== undefined ? p1[2] : 1) - p0[2]) * t : 1;
      dense.push([x, y, pr]);
    }
  }
  let last = pts[pts.length - 1];
  dense.push([last[0], last[1], last[2] !== undefined ? last[2] : 1]);

  // Group consecutive points that stay in the same Y_BAND
  let chunks = [];
  let curChunk = [];
  let curBand = null;
  for (let p of dense) {
    let b = getBand(p[1]);
    if (b !== curBand) {
      if (curChunk.length >= 2) chunks.push({ band: curBand, pts: curChunk });
      curChunk = [p];
      curBand = b;
    } else {
      curChunk.push(p);
    }
  }
  if (curChunk.length >= 2) chunks.push({ band: curBand, pts: curChunk });

  if (fringeOffset > 0) {
    brush.set(brushName, PAL.cyanFringe, weight * 0.85);
    for (let c of chunks) {
      let sh = c.pts.map(p => [p[0] + c.band.dx - fringeOffset, p[1], p[2]]);
      if (sh.length >= 2) brush.spline(sh, curv);
    }
    brush.set(brushName, PAL.magentaFringe, weight * 0.85);
    for (let c of chunks) {
      let sh = c.pts.map(p => [p[0] + c.band.dx + fringeOffset, p[1], p[2]]);
      if (sh.length >= 2) brush.spline(sh, curv);
    }
  }

  brush.set(brushName, col, weight);
  for (let c of chunks) {
    let sh = c.pts.map(p => [p[0] + c.band.dx, p[1], p[2]]);
    if (sh.length >= 2) brush.spline(sh, curv);
  }
}

// Layered spray cloud that respects horizontal band displacement
function sprayCloud(cx, cy, rx, ry, col, count, brushName = "videoGlow", weight = 1.2, fringe = 0) {
  if (fringe > 0) {
    brush.set(brushName, PAL.cyanFringe, weight * 0.85);
    for (let i = 0; i < Math.ceil(count * 0.4); i++) {
      let a = random(TWO_PI);
      let r = Math.pow(random(), 0.7) * 0.9;
      let y = cy + Math.sin(a) * ry * r;
      let dx = getDx(y) - fringe;
      let x = cx + Math.cos(a) * rx * r + dx;
      let len = random(18, 55);
      let ang = a + HALF_PI + random(-0.4, 0.4);
      brush.line(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len * 0.5);
    }
    brush.set(brushName, PAL.magentaFringe, weight * 0.85);
    for (let i = 0; i < Math.ceil(count * 0.4); i++) {
      let a = random(TWO_PI);
      let r = Math.pow(random(), 0.7) * 0.9;
      let y = cy + Math.sin(a) * ry * r;
      let dx = getDx(y) + fringe;
      let x = cx + Math.cos(a) * rx * r + dx;
      let len = random(18, 55);
      let ang = a + HALF_PI + random(-0.4, 0.4);
      brush.line(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len * 0.5);
    }
  }

  brush.set(brushName, col, weight);
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let r = Math.pow(random(), 0.65);
    let y = cy + Math.sin(a) * ry * r;
    let dx = getDx(y);
    let x = cx + Math.cos(a) * rx * r + dx;
    let len = random(20, 68) * (1.1 - r * 0.4);
    let ang = a + HALF_PI + random(-0.35, 0.35);
    brush.line(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len * 0.55);
  }
}

