// ---------------------------------------------------------------------------
// 8. BIRTHDAY CANDLES, TRANSLUCENT WAX DRIPS & FLAME HALOS
// ---------------------------------------------------------------------------
function drawCandlesAndFlames() {
  const candles = [
    { x: 315, topY: 755, botY: 1015, w: 34, blownOut: true,  stripeCol: PAL.tealLight },
    { x: 585, topY: 706, botY: 988,  w: 40, blownOut: false, stripeCol: PAL.magentaSoft, bend: 1.25 },
    { x: 765, topY: 682, botY: 1008, w: 48, blownOut: false, stripeCol: PAL.tealLight,   bend: 1.05, hero: true },
    { x: 948, topY: 728, botY: 1028, w: 42, blownOut: false, stripeCol: PAL.peachWarm,   bend: 0.85 }
  ];

  // --- A. CANDLE STEMS & SUBSURFACE WAX GLOW ---
  for (let c of candles) {
    let hw = c.w * 0.5;
    let stemPts = [
      [c.x - hw, c.topY], [c.x + hw, c.topY],
      [c.x + hw + 4, c.botY], [c.x - hw - 4, c.botY]
    ];
    // Lower cool teal-tinted wax body
    drawSlicedWash(stemPts, PAL.tealMid, 215, { fringe: 18, fringeAlpha: 105 });

    // Upper subsurface translucent tungsten/peach glow where flame heats the wax
    let glowH = (c.botY - c.topY) * (c.blownOut ? 0.25 : 0.58);
    let upperWax = [
      [c.x - hw, c.topY], [c.x + hw, c.topY],
      [c.x + hw + 1, c.topY + glowH], [c.x - hw - 1, c.topY + glowH]
    ];
    drawSlicedWash(upperWax, c.blownOut ? PAL.peachShadow : PAL.tungstenBright, 205, { fringe: 12 });

    let hotTopWax = [
      [c.x - hw, c.topY], [c.x + hw, c.topY],
      [c.x + hw, c.topY + glowH * 0.45], [c.x - hw, c.topY + glowH * 0.45]
    ];
    if (!c.blownOut) {
      drawSlicedWash(hotTopWax, PAL.flameYellow, 195);
    }

    // Diagonal spiral birthday stripes along candle stem
    let stripeSteps = 6;
    for (let s = 0; s < stripeSteps; s++) {
      let y1 = lerp(c.topY + 18, c.botY - 25, s / stripeSteps);
      let y2 = y1 + 26;
      drawSlicedSpline([
        [c.x - hw, y1, 0.8],
        [c.x, (y1 + y2) * 0.5, 1.2],
        [c.x + hw, y2, 0.8]
      ], "thinMarker", c.stripeCol, 1.3, 0.3, 8);
    }

    // Specular edge ridge down the left & right sides of each candle
    drawSlicedSpline([[c.x - hw + 4, c.topY, 0.9], [c.x - hw + 2, c.botY, 0.9]], "glossPen", PAL.peachHighlight, 1.9, 0.2, 10);
    drawSlicedSpline([[c.x + hw - 3, c.topY, 0.9], [c.x + hw - 1, c.botY, 0.9]], "charcoal", PAL.bgDeep, 1.6, 0.2);

    // Melted wax cup rim at top of candle
    drawSlicedWash(makeBlob(c.x, c.topY, hw + 4, 9, 18), PAL.flameCore, 210, { fringe: 9 });

    // --- B. EXACTING WAX DRIPS RUNNING DOWN CANDLE SIDES ---
    let dripCount = c.hero ? 7 : 4;
    for (let d = 0; d < dripCount; d++) {
      let dripX = c.x + random(-hw + 3, hw - 3);
      let dripLen = random(45, c.hero ? 225 : 155);
      let endY = Math.min(c.botY - 8, c.topY + dripLen);
      let midY = (c.topY + endY) * 0.5;
      let wiggleX = dripX + random(-6, 6);

      // Dark shadow track next to wax rivulet
      drawSlicedSpline([
        [dripX + 3, c.topY + 4, 0.6],
        [wiggleX + 3, midY, 1.1],
        [dripX + 3, endY + 3, 1.4]
      ], "cpencil", PAL.bgDeep, 1.6, 0.5);

      // Translucent peach-amber wax rivulet
      drawSlicedSpline([
        [dripX, c.topY + 2, 0.9],
        [wiggleX, midY, 1.3],
        [dripX, endY, 1.8]
      ], "thinMarker", PAL.peachWarm, 1.4, 0.5, 8);

      // Razor-sharp wet gloss line on the wax drip
      drawSlicedSpline([
        [dripX - 1.5, c.topY + 2, 0.7],
        [wiggleX - 1.5, midY, 1.1],
        [dripX - 1.5, endY, 1.5]
      ], "glossPen", PAL.flameCore, 1.5, 0.5);

      // Bulbous teardrop wax bead at bottom of drip
      let beadDx = getDx(endY);
      brush.set("glossPen", PAL.cyanFringe, 1.4);
      brush.circle(dripX + beadDx - 7, endY, 5.5);
      brush.set("glossPen", PAL.magentaFringe, 1.4);
      brush.circle(dripX + beadDx + 7, endY, 5.5);
      brush.set("glossPen", PAL.peachLight, 2.0);
      brush.circle(dripX + beadDx, endY, 5.8);
      brush.set("glossPen", PAL.flameCore, 1.8);
      brush.circle(dripX + beadDx - 1.5, endY - 1.5, 2.6);
    }

    // --- C. WICK, FLAME HALOS & WIND-BENT FLAMES ---
    // Curved dark wick
    drawSlicedSpline([
      [c.x, c.topY, 1.2],
      [c.x + 6, c.topY - 12, 1.0],
      [c.x + 14, c.topY - 18, 0.8]
    ], "pen", "#120907", 2.0, 0.4);

    if (c.blownOut) {
      // Glowing red-orange ember at tip of wick + curling smoke ribbon
      let emberX = c.x + 14 + getDx(c.topY - 18);
      brush.set("glossPen", PAL.tungstenBright, 2.4);
      brush.circle(emberX, c.topY - 18, 4.5);
      brush.set("glossPen", PAL.flameCore, 1.8);
      brush.circle(emberX, c.topY - 18, 2.0);

      let smokePts = [
        [c.x + 14, c.topY - 20, 0.5],
        [c.x + 55, c.topY - 68, 1.1],
        [c.x + 28, c.topY - 135, 1.3],
        [c.x + 88, c.topY - 210, 1.0],
        [c.x + 135, c.topY - 285, 0.3]
      ];
      drawSlicedSpline(smokePts, "videoGlow", PAL.tealWash, 1.2, 0.65, 16);
      drawSlicedSpline(smokePts.map(p => [p[0] + 8, p[1] - 4, p[2]]), "fineMist", PAL.peachLight, 0.9, 0.65);
    } else {
      // Concentric Flame Halos rendered in layered spray + translucent washes
      let fx = c.x + 48 * c.bend;
      let fy = c.topY - 46;

      // Outer magenta/teal/orange video halation rings
      sprayCloud(fx, fy, 155 * c.bend, 125, PAL.tungstenDeep, 55, "videoGlow", 1.7, 22);
      sprayCloud(fx, fy, 110 * c.bend, 92, PAL.tungstenBright, 60, "videoGlow", 1.5, 16);
      sprayCloud(fx, fy, 72 * c.bend, 62, PAL.flameYellow, 55, "fineMist", 1.3, 12);

      // Concentric halo ring strokes
      let haloDx = getDx(fy);
      brush.set("fineMist", PAL.cyanFringe, 1.1);
      brush.circle(fx + haloDx - 16, fy, 92 * c.bend, 0.25);
      brush.set("fineMist", PAL.magentaFringe, 1.1);
      brush.circle(fx + haloDx + 16, fy, 92 * c.bend, 0.25);
      brush.set("fineMist", PAL.amberGlow, 1.3);
      brush.circle(fx + haloDx, fy, 88 * c.bend, 0.2);

      // Tear-shaped wind-blown flame body leaning sharply to the right!
      let outerFlame = [
        [c.x + 10, c.topY - 16],
        [c.x + 24, c.topY - 54],
        [c.x + 68 * c.bend, c.topY - 82],
        [c.x + 118 * c.bend, c.topY - 68],
        [c.x + 142 * c.bend, c.topY - 42],
        [c.x + 95 * c.bend, c.topY - 22],
        [c.x + 42 * c.bend, c.topY - 12]
      ];
      drawSlicedWash(outerFlame, PAL.tungstenBright, 220, { fringe: 18, fringeAlpha: 125 });

      let midFlame = [
        [c.x + 12, c.topY - 18],
        [c.x + 28, c.topY - 46],
        [c.x + 64 * c.bend, c.topY - 66],
        [c.x + 105 * c.bend, c.topY - 54],
        [c.x + 76 * c.bend, c.topY - 26],
        [c.x + 34 * c.bend, c.topY - 15]
      ];
      drawSlicedWash(midFlame, PAL.flameYellow, 235, { fringe: 10 });

      let coreFlame = [
        [c.x + 14, c.topY - 19],
        [c.x + 28, c.topY - 38],
        [c.x + 58 * c.bend, c.topY - 50],
        [c.x + 82 * c.bend, c.topY - 42],
        [c.x + 54 * c.bend, c.topY - 24]
      ];
      drawSlicedWash(coreFlame, PAL.flameCore, 250);

      // Flickering flame tongues & crisp core highlight
      drawSlicedSpline([
        [c.x + 14, c.topY - 18, 0.8],
        [c.x + 56 * c.bend, c.topY - 48, 1.5],
        [c.x + 125 * c.bend, c.topY - 56, 0.4]
      ], "glossPen", PAL.flameCore, 2.5, 0.5, 14);
    }
  }
}

// ---------------------------------------------------------------------------
// 9. SPARKLING SALIVA DROPLETS & BREATH VAPOR JET
// ---------------------------------------------------------------------------
function drawSparklingSalivaAndBreath() {
  // Cone of breath & mist radiating from pursed lips (548, 656) toward candles (860, 645)
  let mouthX = 550;
  let mouthY = 656;

  // Fine breath vapor streaks
  for (let i = 0; i < 36; i++) {
    let ang = random(-0.26, 0.22);
    let d1 = random(12, 75);
    let d2 = d1 + random(45, 165);
    let x1 = mouthX + Math.cos(ang) * d1;
    let y1 = mouthY + Math.sin(ang) * d1;
    let x2 = mouthX + Math.cos(ang) * d2;
    let y2 = mouthY + Math.sin(ang) * d2;
    let col = i % 3 === 0 ? PAL.peachLight : (i % 2 === 0 ? PAL.tealWash : PAL.amberGlow);
    drawSlicedSpline([[x1, y1, 0.4], [(x1 + x2) * 0.5, (y1 + y2) * 0.5 - 4, 1.0], [x2, y2, 0.2]], "fineMist", col, 0.9, 0.4, i % 5 === 0 ? 10 : 0);
  }

  // Sparkling airborne saliva droplets & out-of-focus specular bokeh beads!
  for (let i = 0; i < 95; i++) {
    let t = Math.pow(random(), 0.72);
    let spread = lerp(8, 92, t);
    let sx = lerp(mouthX + 8, 920, t) + random(-12, 12);
    let sy = lerp(mouthY, 648, t) + random(-spread, spread);
    let dx = getDx(sy);
    let rx = sx + dx;

    let isBokeh = i < 16 && t > 0.25;
    if (isBokeh) {
      // Translucent out-of-focus saliva bokeh ring catching candlelight
      let br = random(7, 16);
      brush.set("glossPen", PAL.cyanFringe, 1.1);
      brush.circle(rx - 9, sy, br, 0.15);
      brush.set("glossPen", PAL.magentaFringe, 1.1);
      brush.circle(rx + 9, sy, br, 0.15);
      brush.set("glossPen", PAL.flameYellow, 1.4);
      brush.circle(rx, sy, br, 0.12);
      brush.set("glossPen", PAL.flameCore, 1.6);
      brush.circle(rx - br * 0.35, sy - br * 0.35, 2.2);
    } else {
      // Sharp sparkling micro-droplet with chromatic aberration fringe and cross-glint
      let r = random(1.4, 4.2);
      brush.set("glossPen", PAL.cyanFringe, 1.2);
      brush.circle(rx - 6, sy, r);
      brush.set("glossPen", PAL.magentaFringe, 1.2);
      brush.circle(rx + 6, sy, r);
      brush.set("glossPen", PAL.flameCore, 1.9);
      brush.circle(rx, sy, r);

      // Starburst / motion sparkle on brightest droplets
      if (i % 4 === 0) {
        let slen = random(7, 18);
        brush.set("glossPen", PAL.flameYellow, 1.2);
        brush.line(rx - slen, sy, rx + slen, sy);
        brush.line(rx, sy - slen * 0.7, rx, sy + slen * 0.7);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 10. MARKER BARS FOR DISPLACED SLICES & RAGGED LOWER-THIRD NOISE STRIP
// ---------------------------------------------------------------------------
function drawMarkerDisplacementBars() {
  // Horizontal marker bars across every torn displacement slice
  for (let b of Y_BANDS) {
    if (!b.tear) continue;

    let barCount = b.noise ? 28 : 14;
    for (let i = 0; i < barCount; i++) {
      let y = random(b.y0, b.y1);
      let xStart = random(0, 980);
      let barW = random(65, 360);
      let xEnd = Math.min(1200, xStart + barW);

      // Pick VHS signal colors depending on whether the bar crosses skin, flame, or twilight shadow
      let pick = random();
      let col;
      if (pick < 0.22) col = PAL.cyanFringe;
      else if (pick < 0.44) col = PAL.magentaFringe;
      else if (pick < 0.65) col = PAL.tungstenBright;
      else if (pick < 0.82) col = PAL.peachLight;
      else col = PAL.tealMid;

      let bName = random() < 0.55 ? "vhsMarker" : "thinMarker";
      let w = random(0.6, 1.45);
      brush.set(bName, col, w);
      brush.line(xStart, y, xEnd, y);
    }

    // Crisp horizontal tear-seam edge lines at y0 and y1
    for (let seamY of [b.y0, b.y1]) {
      for (let s = 0; s < 5; s++) {
        let sx = random(0, 900);
        let sw = random(110, 420);
        let seamCol = s % 2 === 0 ? PAL.cyanFringe : (s % 3 === 0 ? PAL.magentaFringe : PAL.flameCore);
        brush.set("thinMarker", seamCol, random(0.7, 1.3));
        brush.line(sx, seamY + random(-1.5, 1.5), Math.min(1200, sx + sw), seamY + random(-1.5, 1.5));
      }
    }

    // Left/Right edge blanking bars where the torn slice was shoved sideways
    if (b.dx > 15) {
      brush.set("vhsMarker", PAL.bgDeep, 1.4);
      brush.line(0, (b.y0 + b.y1) * 0.5, b.dx + 18, (b.y0 + b.y1) * 0.5);
      brush.set("thinMarker", PAL.cyanFringe, 1.2);
      brush.line(b.dx, b.y0 + 4, b.dx + 45, b.y0 + 4);
    } else if (b.dx < -15) {
      brush.set("vhsMarker", PAL.bgDeep, 1.4);
      brush.line(1200 + b.dx - 18, (b.y0 + b.y1) * 0.5, 1200, (b.y0 + b.y1) * 0.5);
      brush.set("thinMarker", PAL.magentaFringe, 1.2);
      brush.line(1200 + b.dx - 45, b.y1 - 4, 1200 + b.dx, b.y1 - 4);
    }
  }
}

function drawRaggedNoiseStrip() {
  // Ragged VHS head-switching / tracking static strip rolling through the lower third (y = 832..926)
  let yTop = 834;
  let yBot = 924;

  // 1. Jagged, torn top and bottom wave boundaries of the tracking strip
  let topEdge = [];
  let botEdge = [];
  let steps = 40;
  for (let i = 0; i <= steps; i++) {
    let x = (i / steps) * 1200;
    let ty = yTop + Math.sin(i * 0.9) * 9 + random(-11, 11);
    let by = yBot + Math.cos(i * 0.8) * 10 + random(-12, 12);
    topEdge.push([x, ty]);
    botEdge.push([x, by]);
  }
  let stripPoly = [...topEdge, ...botEdge.slice().reverse()];

  // Semi-transparent dark twilight/plum tracking band base
  brush.noStroke();
  brush.wash(PAL.bgDeep, 145);
  emitShape(stripPoly, 0.05);
  brush.noWash();

  // 2. Dense horizontal marker bars (cyan, magenta, tungsten orange, peach, deep teal) inside the strip
  for (let i = 0; i < 95; i++) {
    let y = random(yTop - 8, yBot + 8);
    let x1 = random(0, 1080);
    let len = random(35, 320);
    let x2 = Math.min(1200, x1 + len);

    let r = random();
    let col;
    if (r < 0.24) col = PAL.cyanFringe;
    else if (r < 0.48) col = PAL.magentaFringe;
    else if (r < 0.68) col = PAL.tungstenBright;
    else if (r < 0.84) col = PAL.peachLight;
    else col = PAL.tealLight;

    brush.set(random() < 0.45 ? "vhsMarker" : "thinMarker", col, random(0.55, 1.35));
    brush.line(x1, y, x2, y);
  }

  // 3. Layered static snow spray bursts & ragged white signal drop-out dashes
  for (let i = 0; i < 65; i++) {
    let sx = random(20, 1180);
    let sy = random(yTop - 6, yBot + 6);
    let slen = random(18, 95);
    let col = i % 3 === 0 ? PAL.flameCore : (i % 2 === 0 ? PAL.cyanSoft : PAL.magentaSoft);
    brush.set("fineMist", col, random(0.9, 1.6));
    brush.line(sx, sy, Math.min(1200, sx + slen), sy + random(-3, 3));
  }

  // Crisp white/cyan/magenta VHS dropout teeth & herringbones along the ragged strip
  for (let i = 0; i < 85; i++) {
    let dx = random(10, 1190);
    let dy = random(yTop - 10, yBot + 10);
    let dw = random(8, 52);
    let dCol = i % 4 === 0 ? PAL.cyanFringe : (i % 4 === 1 ? PAL.magentaFringe : PAL.flameCore);
    brush.set("glossPen", dCol, random(1.2, 2.4));
    brush.line(dx, dy, Math.min(1200, dx + dw), dy);
  }
}

function drawScanlineAndEdgeChromaFinish() {
  // Subtle horizontal scanlines and chroma-bleed bars across the full frame to unify the video texture
  for (let y = 12; y < 1200; y += 14) {
    if (random() < 0.45) {
      let x1 = random(0, 750);
      let x2 = Math.min(1200, x1 + random(180, 620));
      let col = y % 28 === 0 ? PAL.cyanFringe : (y % 42 === 0 ? PAL.magentaFringe : PAL.tealDeep);
      brush.set("cpencil", col, 0.55);
      brush.line(x1, y, x2, y);
    }
  }

  // Extra magenta & cyan fringe accents along high-contrast edges of cheeks, lips, and flames
  let edgeHighlights = [
    [[148, 515], [142, 605], PAL.cyanFringe],
    [[912, 510], [922, 608], PAL.magentaFringe],
    [[518, 468], [556, 495], PAL.cyanFringe],
    [[575, 650], [615, 690], PAL.magentaFringe],
    [[795, 610], [875, 645], PAL.magentaFringe],
    [[755, 615], [825, 650], PAL.cyanFringe]
  ];
  for (let eh of edgeHighlights) {
    drawSlicedSpline([
      [eh[0][0], eh[0][1], 0.6],
      [(eh[0][0] + eh[1][0]) * 0.5, (eh[0][1] + eh[1][1]) * 0.5, 1.3],
      [eh[1][0], eh[1][1], 0.6]
    ], "thinMarker", eh[2], 1.15, 0.4);
  }
}

// Hyperrealist Trompe-l'œil: Torn Paper Bag of Trail Mix on Polished Terrazzo
// p5.js 2.x + p5.brush (WEBGL)

const SEED = 7381;

const PALETTE = {
  puttyBase: "#d4cec3",
  puttyLight: "#e2ddd3",
  puttyDark: "#beb7aa",
  puttyWarm: "#cbbba6",

  // Terrazzo & Snack Monochrome-Stone Families + Terracotta Accent
  terracotta: ["#c44b31", "#9e341e", "#d9674e", "#b33f27"],
  slate: ["#2e3338", "#484f56", "#697178", "#22262a"],
  cream: ["#eee8da", "#dfd6c3", "#f6f2e8", "#cfc3ad"],
  verdigris: ["#647872", "#7e918b", "#4e615b", "#8fa19b"],

  // Paper Bag (Kraft / Putty monochrome harmony)
  bagLight: "#d8cbb8",
  bagMid: "#bfa98e",
  bagDark: "#9c8569",
  bagDeep: "#735f47",
  bagShadow: "#211f22",

  // Snack Specifics
  cashewBase: "#e6d8c0",
  cashewToast: "#bd9a6b",
  cashewUmber: "#876742",
  cashewHighlight: "#fbf7ef",

  raisinBase: "#241f24",
  raisinPlum: "#3d292e",
  raisinEdge: "#120e12",
  raisinRidge: "#6b5f66",

  seedHull: "#939c90",
  seedHullLight: "#b4bca9",
  seedHullDark: "#5b6358",
  seedShell: "#282c30",

  chocolateCore: "#2b1c17",
  white: "#ffffff"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);
  randomSeed(SEED);
  noiseSeed(SEED);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Putty Ground & Mineral Matrix
  drawPuttyGround();

  // 2. Generate Spatial Layout (All-over, edge-to-edge, no center)
  const layout = generateLayout();

  // 3. Flat Marker Terrazzo Chips (Embedded in floor plane)
  drawTerrazzoChips(layout.chips);

  // 4. Brass/Zinc Terrazzo Divider Strips
  drawDividerStrips();

  // 5. Diagonal Ceiling Reflection Streaking Across Polished Surface
  drawFloorReflection(false);

  // 6. Torn Paper Bag Pieces (Top-left splayed bag & bottom-right torn scrap)
  drawTornBag();

  // 7. Trail Mix Snacks (Layered Watercolor + Crisp Pen + Pinpoint Glints)
  drawTrailMix(layout.snacks);

  // 8. Micro-Crumbs, Salt Crystals, Seed Skins & Final Specular Polish
  drawCrumbsAndGlints(layout.crumbs);
  drawFloorReflection(true);

  noLoop();
}

// ============================================================================
// 1. PUTTY GROUND
// ============================================================================
function drawPuttyGround() {
  background(PALETTE.puttyBase);

  // Subtle tonal stone variation across the slab
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.2);

  brush.fill(PALETTE.puttyDark, 38);
  for (let i = 0; i < 7; i++) {
    let cx = random(-100, 1300);
    let cy = random(-100, 1300);
    drawOrganicBlob(cx, cy, random(240, 420), 8, 0.35, 0.7);
  }

  brush.fill(PALETTE.puttyLight, 45);
  for (let i = 0; i < 6; i++) {
    let cx = random(-100, 1300);
    let cy = random(-100, 1300);
    drawOrganicBlob(cx, cy, random(200, 380), 8, 0.35, 0.7);
  }
  brush.noFill();

  // Fine spray grain for cement/putty matrix
  brush.set("spray", "#9c9588", 0.9);
  for (let i = 0; i < 55; i++) {
    let x1 = random(-50, 1250);
    let y1 = random(-50, 1250);
    let ang = random(360);
    let len = random(120, 320);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }

  brush.set("spray", "#f2ece1", 0.8);
  for (let i = 0; i < 40; i++) {
    let x1 = random(-50, 1250);
    let y1 = random(-50, 1250);
    let ang = random(360);
    let len = random(100, 280);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }

  // Pinpoint sand speckles in the putty ground
  const speckColors = ["#54595e", "#8a8275", "#faf6ed", "#b84b34", "#6b7d77"];
  for (let cIdx = 0; cIdx < speckColors.length; cIdx++) {
    brush.set("rotring", speckColors[cIdx], 0.32);
    let count = cIdx === 3 ? 180 : 380;
    for (let i = 0; i < count; i++) {
      let x = random(-20, 1220);
      let y = random(-20, 1220);
      let l = random(0.8, 2.4);
      let a = random(360);
      brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
    }
  }
}

// ============================================================================
// 2. SPATIAL LAYOUT GENERATOR (All-over, edge-to-edge, non-central)
// ============================================================================
function generateLayout() {
  const chips = [];
  const snacks = [];
  const crumbs = [];

  // First, generate Trail Mix items along meandering, edge-to-edge streams
  // so there is no dead center, and items bleed off all four canvas edges.
  const targetSnacks = 162;
  let attempts = 0;

  while (snacks.length < targetSnacks && attempts < 6000) {
    attempts++;
    let x = random(-45, 1245);
    let y = random(-45, 1245);

    // Use multi-scale Perlin noise + diagonal spill ribbons to modulate density
    let n1 = noise(x * 0.0028, y * 0.0028);
    let n2 = noise(x * 0.007 + 50, y * 0.007 + 50);
    // Ribbon flowing from top-left torn bag across toward right & bottom edges
    let dRibbon1 = abs((x * 0.72 - y + 120) / 1200);
    let dRibbon2 = abs((x * 0.45 + y - 1080) / 1200);
    let streamProb = map(n1 * 0.65 + n2 * 0.35, 0.2, 0.8, 0.15, 0.95);
    if (dRibbon1 < 0.22 || dRibbon2 < 0.18) streamProb += 0.28;

    // Avoid placing too many snacks deep inside the opaque bag fold corner
    if (x < 160 && y < 190 && random() < 0.65) continue;
    if (random() > streamProb) continue;

    // Choose snack type
    let rType = random();
    let type, radius;
    if (rType < 0.23) {
      type = "cashew";
      radius = random(21, 29);
    } else if (rType < 0.46) {
      type = "candy";
      radius = random(16, 22);
    } else if (rType < 0.72) {
      type = "raisin";
      radius = random(13, 20);
    } else {
      type = "seed";
      radius = random(10, 15);
    }

    // Check collision against existing snacks
    let ok = true;
    for (let s of snacks) {
      let minDist = (radius + s.radius) * 0.84;
      if (dist(x, y, s.x, s.y) < minDist) {
        ok = false;
        break;
      }
    }
    if (!ok) continue;

    snacks.push(buildSnackData(type, x, y, radius));
  }

  // Next, generate ~740 Terrazzo Marble Chips across the entire floor
  // Echoing the exact scales and silhouettes of the snacks!
  const chipTargets = [
    { count: 165, minR: 17, maxR: 34 }, // Large marble chips (echo cashews/candies)
    { count: 270, minR: 10, maxR: 17 }, // Medium chips (echo raisins/seeds)
    { count: 320, minR: 5, maxR: 10 }   // Small stone shards
  ];

  for (let tier of chipTargets) {
    let cAttempts = 0;
    let added = 0;
    while (added < tier.count && cAttempts < tier.count * 16) {
      cAttempts++;
      let x = random(-55, 1255);
      let y = random(-55, 1255);
      let r = random(tier.minR, tier.maxR);

      // Avoid chip overlap so putty ground clearly frames each chip
      let ok = true;
      for (let c of chips) {
        if (dist(x, y, c.x, c.y) < (r + c.r) * 0.92 + 3) {
          ok = false;
          break;
        }
      }
      if (!ok) continue;

      chips.push(buildChipData(x, y, r));
      added++;
    }
  }

  // Generate micro-crumbs, salt crystals, and broken nut nibs
  for (let i = 0; i < 130; i++) {
    let refSnack = random(snacks);
    let ang = random(360);
    let d = random(refSnack.radius + 4, refSnack.radius + 65);
    crumbs.push({
      x: refSnack.x + cos(ang) * d,
      y: refSnack.y + sin(ang) * d,
      r: random(1.8, 5.2),
      angle: random(360),
      kind: random(["nut", "salt", "skin", "terracottaShard"])
    });
  }

  return { chips, snacks, crumbs };
}

function buildChipData(x, y, r) {
  // Color distribution: Monochrome stone (slate, cream, muted verdigris) + Terracotta accent
  let famRoll = random();
  let family, colorIdx;
  if (famRoll < 0.30) {
    family = "slate";
    colorIdx = floor(random(PALETTE.slate.length));
  } else if (famRoll < 0.58) {
    family = "cream";
    colorIdx = floor(random(PALETTE.cream.length));
  } else if (famRoll < 0.80) {
    family = "verdigris";
    colorIdx = floor(random(PALETTE.verdigris.length));
  } else {
    family = "terracotta";
    colorIdx = floor(random(PALETTE.terracotta.length));
  }

  let col = PALETTE[family][colorIdx];
  // Morphological echo: some chips are kidney-notched like cashews,
  // some teardrop like seeds, some polygonal-round like candies/raisins
  let morph = random(["angular", "kidney", "teardrop", "tabular"]);
  let rot = random(360);
  let pts = [];
  let nVerts = floor(random(5, 9));

  for (let i = 0; i < nVerts; i++) {
    let baseAng = (i / nVerts) * 360;
    let a = baseAng + random(-16, 16);
    let rad = r * random(0.68, 1.12);

    if (morph === "kidney") {
      // Echo cashew silhouette with angular stone facets
      if (i === 0) rad *= 0.48;
      if (i === floor(nVerts / 2)) rad *= 1.18;
    } else if (morph === "teardrop") {
      // Echo sunflower seed silhouette
      if (i === 0) rad *= 1.35;
      if (i === floor(nVerts / 2)) rad *= 0.72;
    } else if (morph === "tabular") {
      rad *= (i % 2 === 0) ? 1.1 : 0.82;
    }

    let px = x + cos(a + rot) * rad;
    let py = y + sin(a + rot) * rad;
    pts.push([px, py]);
  }

  return {
    x, y, r, family, colorIdx, col, pts,
    hatchAngle: rot + random(-25, 25),
    hasVein: r > 13 && random() < 0.55
  };
}

// ============================================================================
// 3. FLAT MARKER TERRAZZO CHIPS
// ============================================================================
function drawTerrazzoChips(chips) {
  // Group chips by exact color for fast batching
  const groups = {};
  for (let c of chips) {
    let key = c.family + "_" + c.colorIdx;
    if (!groups[key]) {
      groups[key] = {
        col: c.col,
        family: c.family,
        items: []
      };
    }
    groups[key].items.push(c);
  }

  // Pass A: Flat Wash + Marker Hatching inside every chip
  brush.noStroke();
  brush.noFill();

  for (let key in groups) {
    let grp = groups[key];
    // Slightly darker/richer marker tone for the flat marker strokes
    let markerCol = grp.col;

    for (let c of grp.items) {
      brush.wash(grp.col, 232);
      // Use marker hatching on medium & large chips for authentic flat marker feel
      if (c.r > 8.5) {
        let spacing = map(c.r, 8, 34, 4.5, 7.5);
        brush.hatchStyle("marker", markerCol, map(c.r, 8, 34, 0.55, 0.85));
        brush.hatch(spacing, c.hatchAngle, { rand: 0.04 });
      } else {
        brush.noHatch();
      }

      brush.beginShape(0);
      for (let p of c.pts) {
        brush.vertex(p[0], p[1]);
      }
      brush.endShape(true);
    }
  }
  brush.noWash();
  brush.noHatch();

  // Pass B: Flat Marker Chisel Facets & Mineral Veins inside chips (Strictly 2D/Flat)
  for (let c of chips) {
    if (c.r > 11) {
      // Internal flat marker stroke across a facet
      brush.set("marker", c.col, map(c.r, 11, 34, 0.45, 0.9));
      let p0 = c.pts[0];
      let pMid = c.pts[floor(c.pts.length / 2)];
      brush.line(
        lerp(p0[0], c.x, 0.35),
        lerp(p0[1], c.y, 0.35),
        lerp(pMid[0], c.x, 0.35),
        lerp(pMid[1], c.y, 0.35)
      );
    }

    if (c.hasVein) {
      // Crisp calcite or slate geological vein cutting flush across the marble chip
      let veinCol = (c.family === "cream") ? "#b5a892" : "#f0eadd";
      brush.set("2H", veinCol, 0.36);
      let i1 = floor(random(c.pts.length));
      let i2 = (i1 + 2) % c.pts.length;
      let n1 = c.pts[(i1 + 1) % c.pts.length];
      let a = [lerp(c.pts[i1][0], n1[0], 0.4), lerp(c.pts[i1][1], n1[1], 0.4)];
      let b = [lerp(c.pts[i2][0], c.x, 0.2), lerp(c.pts[i2][1], c.y, 0.2)];
      let mid = [
        (a[0] + b[0]) * 0.5 + random(-3, 3),
        (a[1] + b[1]) * 0.5 + random(-3, 3)
      ];
      brush.spline([a, mid, b], 0.3);
    }
  }

  // Pass C: Razor-thin flush cement joint around larger chips
  brush.set("2H", "#8f887c", 0.28);
  for (let c of chips) {
    if (c.r > 15 && random() < 0.6) {
      let p0 = c.pts[0];
      let p1 = c.pts[1];
      let p2 = c.pts[2];
      brush.line(p0[0], p0[1], p1[0], p1[1]);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

// ============================================================================
// 4. BRASS / ZINC TERRAZZO DIVIDER STRIPS
// ============================================================================
function drawDividerStrips() {
  // Architectural metal expansion strips set flush into the terrazzo floor
  const strips = [
    { x1: -60, y1: 310, x2: 1260, y2: 890 },
    { x1: 707, y1: 647, x2: 1015, y2: -50 }
  ];

  for (let s of strips) {
    let ang = atan2(s.y2 - s.y1, s.x2 - s.x1);
    let nx = -sin(ang);
    let ny = cos(ang);

    // Dark flush seam on both sides of the strip
    brush.set("rotring", "#3d3b37", 0.55);
    brush.line(s.x1 + nx * 2.2, s.y1 + ny * 2.2, s.x2 + nx * 2.2, s.y2 + ny * 2.2);
    brush.line(s.x1 - nx * 2.2, s.y1 - ny * 2.2, s.x2 - nx * 2.2, s.y2 - ny * 2.2);

    // Muted antique brass / zinc core
    brush.set("marker", "#a89878", 0.55);
    brush.line(s.x1, s.y1, s.x2, s.y2);

    // Specular metallic glint along strip edge
    brush.set("pen", "#f5efe2", 0.42);
    brush.line(s.x1 - nx * 0.7, s.y1 - ny * 0.7, s.x2 - nx * 0.7, s.y2 - ny * 0.7);
  }
}

// ============================================================================
// 5. DIAGONAL CEILING REFLECTION ON THE POLISHED SURFACE
// ============================================================================
function drawFloorReflection(isFinalVeil) {
  // Diagonal architectural skylight / ceiling light bay streaking at ~ -38 deg
  if (!isFinalVeil) {
    brush.noStroke();

    // Primary broad reflection streak
    brush.wash("#faf7f0", 36);
    drawQuad(-120, 740, 740, -120, 960, -120, -120, 960);

    // Brighter core inside the reflection band
    brush.wash("#ffffff", 28);
    drawQuad(-120, 800, 800, -120, 900, -120, -120, 900);

    // Secondary narrower parallel ceiling fixture reflection
    brush.wash("#faf7f0", 30);
    drawQuad(180, 1280, 1280, 180, 1390, 180, 180, 1390);
    brush.noWash();

    // Fine diagonal polish buffing streaks within the reflection bands
    brush.set("2H", "#ffffff", 0.35);
    for (let i = 0; i < 65; i++) {
      let t = random(-80, 850);
      let offset = random(-75, 75);
      let x1 = t + offset;
      let y1 = 830 - t + offset;
      let len = random(70, 220);
      brush.line(x1, y1, x1 + len * 0.707, y1 - len * 0.707);
    }
  } else {
    // Final subtle polish sheen over open terrazzo patches along the diagonal
    brush.set("pen", "#ffffff", 0.3);
    for (let i = 0; i < 35; i++) {
      let t = random(0, 820);
      let offset = random(-45, 45);
      let x1 = t + offset;
      let y1 = 840 - t + offset;
      let len = random(25, 65);
      brush.line(x1, y1, x1 + len * 0.707, y1 - len * 0.707);
    }
  }
}

function drawQuad(x1, y1, x2, y2, x3, y3, x4, y4) {
  brush.beginShape(0);
  brush.vertex(x1, y1);
  brush.vertex(x2, y2);
  brush.vertex(x3, y3);
  brush.vertex(x4, y4);
  brush.endShape(true);
}

// ============================================================================
// 6. TORN PAPER BAG (Top-Down Crumpled Kraft Paper at Edges)
// ============================================================================
function drawTornBag() {
  // Piece 1: Splayed torn paper bag entering from top-left edge
  const bagOutline = [
    [-60, -50], [340, -50], [375, 48], [320, 145],
    [388, 235], [295, 315], [250, 415], [140, 395],
    [72, 470], [-60, 435]
  ];

  // Piece 2: Torn corner scrap near bottom-right edge
  const scrapOutline = [
    [945, 1250], [915, 1085], [985, 1010], [1075, 955],
    [1155, 895], [1255, 920], [1255, 1250]
  ];

  // Cast shadows on the polished terrazzo floor
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.25);
  brush.fill(PALETTE.bagShadow, 68);

  drawOffsetPoly(bagOutline, 14, 18, 0.08);
  drawOffsetPoly(scrapOutline, 12, 15, 0.08);

