  brush.wash("#171518", 130);
  drawOffsetPoly(bagOutline, 4, 6, 0.05);
  drawOffsetPoly(scrapOutline, 4, 5, 0.05);
  brush.noWash();

  // Crumpled paper facets for Piece 1 (Top-Left Bag)
  const facets = [
    { pts: [[-60, -50], [190, -50], [165, 130], [-60, 170]], col: PALETTE.bagMid, op: 215 },
    { pts: [[190, -50], [340, -50], [375, 48], [320, 145], [165, 130]], col: PALETTE.bagLight, op: 220 },
    { pts: [[-60, 170], [165, 130], [235, 255], [95, 290], [-60, 280]], col: PALETTE.bagDark, op: 215 },
    { pts: [[165, 130], [320, 145], [388, 235], [295, 315], [235, 255]], col: PALETTE.bagLight, op: 225 },
    { pts: [[-60, 280], [95, 290], [140, 395], [72, 470], [-60, 435]], col: PALETTE.bagMid, op: 215 },
    { pts: [[95, 290], [235, 255], [295, 315], [250, 415], [140, 395]], col: PALETTE.bagDeep, op: 205 },
    // Interior curled flap showing inner kraft surface
    { pts: [[215, 140], [320, 145], [388, 235], [275, 240]], col: "#e3d8c6", op: 210 }
  ];

  // Crumpled facets for Piece 2 (Bottom-Right Scrap)
  const scrapFacets = [
    { pts: [[945, 1250], [915, 1085], [1075, 955], [1120, 1110], [1090, 1250]], col: PALETTE.bagMid, op: 215 },
    { pts: [[1075, 955], [1155, 895], [1255, 920], [1255, 1120], [1120, 1110]], col: PALETTE.bagLight, op: 220 },
    { pts: [[1090, 1250], [1120, 1110], [1255, 1120], [1255, 1250]], col: PALETTE.bagDark, op: 215 }
  ];

  // Opaque base wash so floor chips don't bleed through solid paper
  brush.wash(PALETTE.bagMid, 242);
  drawOffsetPoly(bagOutline, 0, 0, 0.02);
  drawOffsetPoly(scrapOutline, 0, 0, 0.02);
  brush.noWash();

  // Layered watercolor paper facets
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.65, 0.38);

  for (let f of facets.concat(scrapFacets)) {
    brush.fill(f.col, f.op);
    brush.beginShape(0.04);
    for (let p of f.pts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
  }

  // Translucent nut-oil absorption stains on the paper bag
  brush.fill("#786248", 55);
  drawOrganicBlob(195, 195, 58, 7, 0.25, 0.6);
  drawOrganicBlob(265, 285, 42, 7, 0.25, 0.6);
  drawOrganicBlob(1095, 1065, 48, 7, 0.25, 0.6);
  brush.noFill();

  // Paper grain & crease ridges
  brush.hatchStyle("cpencil", "#8c765c", 0.45);
  brush.hatch(7, 28, { rand: 0.08 });
  drawOffsetPoly(bagOutline, 0, 0, 0.02);
  drawOffsetPoly(scrapOutline, 0, 0, 0.02);
  brush.noHatch();

  // Sharp fold lines (dark crease + bright ridge highlight)
  const creases = [
    [[165, 130], [320, 145]],
    [[165, 130], [235, 255]],
    [[95, 290], [235, 255]],
    [[165, 130], [-40, 168]],
    [[235, 255], [295, 315]],
    [[1075, 955], [1120, 1110]],
    [[1120, 1110], [1250, 1120]]
  ];

  for (let cr of creases) {
    brush.set("2B", "#594735", 0.55);
    brush.line(cr[0][0], cr[0][1], cr[1][0], cr[1][1]);
    brush.set("pen", "#f5ede0", 0.5);
    brush.line(cr[0][0] - 1.5, cr[0][1] - 1.5, cr[1][0] - 1.5, cr[1][1] - 1.5);
  }

  // Printed Terracotta Bakery/Snack Stripe across the paper bag (tying into the accent!)
  brush.set("marker", PALETTE.terracotta[0], 1.1);
  brush.line(-40, 92, 162, 62);
  brush.line(164, 62, 355, 82);
  brush.set("marker", PALETTE.terracotta[1], 0.5);
  brush.line(-40, 104, 162, 74);
  brush.line(164, 74, 353, 94);

  // Torn fibrous white/cream pulp along the ripped edges
  const tearEdge1 = [
    [340, -50], [375, 48], [320, 145], [388, 235],
    [295, 315], [250, 415], [140, 395], [72, 470], [-60, 435]
  ];
  const tearEdge2 = [
    [945, 1250], [915, 1085], [985, 1010],
    [1075, 955], [1155, 895], [1255, 920]
  ];

  drawFibrousTear(tearEdge1);
  drawFibrousTear(tearEdge2);
}

function drawOffsetPoly(pts, dx, dy, curv) {
  brush.beginShape(curv);
  for (let p of pts) {
    brush.vertex(p[0] + dx, p[1] + dy);
  }
  brush.endShape(true);
}

function drawFibrousTear(edgePts) {
  for (let i = 0; i < edgePts.length - 1; i++) {
    let p1 = edgePts[i];
    let p2 = edgePts[i + 1];
    let segLen = dist(p1[0], p1[1], p2[0], p2[1]);
    let steps = floor(segLen / 3.5);

    // Jagged dark contour
    brush.set("rotring", "#453728", 0.42);
    for (let s = 0; s < steps; s++) {
      let t1 = s / steps;
      let t2 = (s + 1) / steps;
      let x1 = lerp(p1[0], p2[0], t1) + random(-2, 2);
      let y1 = lerp(p1[1], p2[1], t1) + random(-2, 2);
      let x2 = lerp(p1[0], p2[0], t2) + random(-2, 2);
      let y2 = lerp(p1[1], p2[1], t2) + random(-2, 2);
      brush.line(x1, y1, x2, y2);
    }

    // Tiny white/cream torn paper fibers fraying outward
    brush.set("pen", "#faf5eb", 0.45);
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let bx = lerp(p1[0], p2[0], t);
      let by = lerp(p1[1], p2[1], t);
      let a = random(-60, 120);
      let fl = random(3, 8);
      brush.line(bx, by, bx + cos(a) * fl, by + sin(a) * fl);
    }
  }
}

// ============================================================================
// 7. TRAIL MIX SNACKS (Layered Watercolor + Crisp Pen + Pinpoint Glints)
// ============================================================================
function buildSnackData(type, x, y, radius) {
  let rot = random(360);
  let poly = [];
  let innerPoly = [];
  let shadePoly = [];
  let baseCol, shadeCol, highlightCol, subtype;

  if (type === "cashew") {
    // Plump kidney-shaped cashew curve
    let bend = random(0.28, 0.42) * (random() < 0.5 ? 1 : -1);
    let n = 14;
    for (let i = 0; i < n; i++) {
      let a = (i / n) * 360;
      let lx = cos(a) * radius * 1.15;
      let ly = sin(a) * radius * 0.64;
      // Taper tail and indent concave belly
      let taper = map(cos(a), -1, 1, 0.72, 1.12);
      ly *= taper;
      ly += pow(cos(a), 2) * radius * bend;
      if (sin(a) * bend < 0 && abs(cos(a)) < 0.55) {
        ly *= 0.65; // Characteristic cashew cleft
      }
      let rx = x + lx * cos(rot) - ly * sin(rot);
      let ry = y + lx * sin(rot) + ly * cos(rot);
      poly.push([rx, ry]);

      // Inner plump highlight zone shifted toward top-left light
      let ix = x + (lx * 0.62) * cos(rot) - (ly * 0.62) * sin(rot) - 2.5;
      let iy = y + (lx * 0.62) * sin(rot) + (ly * 0.62) * cos(rot) - 2.5;
      innerPoly.push([ix, iy]);

      // Toasted underside shading zone
      let sx = x + (lx * 0.78) * cos(rot) - (ly * 0.78) * sin(rot) + 2.8;
      let sy = y + (lx * 0.78) * sin(rot) + (ly * 0.78) * cos(rot) + 2.8;
      shadePoly.push([sx, sy]);
    }
    baseCol = PALETTE.cashewBase;
    shadeCol = PALETTE.cashewToast;
    highlightCol = PALETTE.cashewHighlight;

  } else if (type === "candy") {
    // Candy-coated chocolate (oblate spheroid, mostly Terracotta Accent!)
    let cRoll = random();
    if (cRoll < 0.68) {
      subtype = "terracotta";
      baseCol = random([PALETTE.terracotta[0], PALETTE.terracotta[3]]);
      shadeCol = PALETTE.terracotta[1];
      highlightCol = PALETTE.terracotta[2];
    } else if (cRoll < 0.85) {
      subtype = "slate";
      baseCol = PALETTE.slate[1];
      shadeCol = PALETTE.slate[0];
      highlightCol = PALETTE.slate[2];
    } else {
      subtype = "verdigris";
      baseCol = PALETTE.verdigris[0];
      shadeCol = PALETTE.verdigris[2];
      highlightCol = PALETTE.verdigris[1];
    }

    let aspect = random(0.88, 1.0);
    let isChipped = subtype === "terracotta" && random() < 0.16;
    let n = 12;
    for (let i = 0; i < n; i++) {
      let a = (i / n) * 360;
      let rMod = radius * (isChipped && i < 3 ? 0.72 : 1.0);
      let lx = cos(a) * rMod;
      let ly = sin(a) * rMod * aspect;
      let rx = x + lx * cos(rot) - ly * sin(rot);
      let ry = y + lx * sin(rot) + ly * cos(rot);
      poly.push([rx, ry]);

      let ix = x + lx * 0.55 * cos(rot) - ly * 0.55 * sin(rot) - radius * 0.22;
      let iy = y + lx * 0.55 * sin(rot) + ly * 0.55 * cos(rot) - radius * 0.22;
      innerPoly.push([ix, iy]);

      let sx = x + lx * 0.82 * cos(rot) - ly * 0.82 * sin(rot) + radius * 0.16;
      let sy = y + lx * 0.82 * sin(rot) + ly * 0.82 * cos(rot) + radius * 0.16;
      shadePoly.push([sx, sy]);
    }
    subtype = isChipped ? "chipped" : subtype;

  } else if (type === "raisin") {
    // Lobed, wrinkled dark raisin
    let n = 12;
    for (let i = 0; i < n; i++) {
      let a = (i / n) * 360;
      let lobe = random(0.76, 1.12);
      let lx = cos(a) * radius * 1.15 * lobe;
      let ly = sin(a) * radius * 0.76 * lobe;
      let rx = x + lx * cos(rot) - ly * sin(rot);
      let ry = y + lx * sin(rot) + ly * cos(rot);
      poly.push([rx, ry]);

      let sx = x + lx * 0.7 * cos(rot) - ly * 0.7 * sin(rot);
      let sy = y + lx * 0.7 * sin(rot) + ly * 0.7 * cos(rot);
      shadePoly.push([sx, sy]);
    }
    baseCol = PALETTE.raisinBase;
    shadeCol = PALETTE.raisinPlum;
    highlightCol = PALETTE.raisinRidge;

  } else if (type === "seed") {
    // Pointed teardrop sunflower seed (hulled kernel or striped shell)
    subtype = random() < 0.74 ? "kernel" : "striped";
    let n = 10;
    for (let i = 0; i < n; i++) {
      let a = (i / n) * 360;
      // Pointed nose at a=0, rounded tail at a=180
      let widthProfile = sin(a) * (cos(a) > 0 ? map(cos(a), 0, 1, 1.0, 0.25) : 0.92);
      let lx = cos(a) * radius * 1.28;
      let ly = widthProfile * radius * 0.62;
      let rx = x + lx * cos(rot) - ly * sin(rot);
      let ry = y + lx * sin(rot) + ly * cos(rot);
      poly.push([rx, ry]);

      let sx = x + lx * 0.72 * cos(rot) - ly * 0.72 * sin(rot) + 1.5;
      let sy = y + lx * 0.72 * sin(rot) + ly * 0.72 * cos(rot) + 1.5;
      shadePoly.push([sx, sy]);
    }
    if (subtype === "kernel") {
      baseCol = PALETTE.seedHullLight;
      shadeCol = PALETTE.seedHull;
      highlightCol = "#f7f4eb";
    } else {
      baseCol = PALETTE.seedShell;
      shadeCol = "#181a1c";
      highlightCol = PALETTE.cream[0];
    }
  }

  // Check if snack lies inside the bright diagonal ceiling reflection band
  let inReflection = abs((x + y) - 820) < 160 || abs((x + y) - 1460) < 110;

  return {
    type, subtype, x, y, radius, rot,
    poly, innerPoly, shadePoly,
    baseCol, shadeCol, highlightCol,
    inReflection
  };
}

function drawTrailMix(snacks) {
  brush.noStroke();

  // --------------------------------------------------------------------------
  // PASS 1: Polished Floor Mirror Reflection + Soft Watercolor Cast Shadows
  // --------------------------------------------------------------------------
  // Faint downward mirror reflection on the polished floor
  for (let s of snacks) {
    brush.wash(s.baseCol, s.type === "candy" ? 42 : 26);
    drawOffsetPoly(s.poly, 3.5, 5.5, 0.2);
  }
  brush.noWash();

  // Batched soft watercolor cast shadow (Light from top-left -> shadow bottom-right)
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.42, 0.25);
  brush.fill("#1e1c21", 56);
  for (let s of snacks) {
    let off = map(s.radius, 10, 29, 5.5, 11.5);
    drawOffsetPoly(s.poly, off * 0.82, off, 0.25);
  }
  brush.noFill();

  // Tight dark ambient occlusion contact shadow directly beneath each snack
  brush.wash("#121014", 155);
  for (let s of snacks) {
    let off = map(s.radius, 10, 29, 2.2, 4.2);
    drawOffsetPoly(s.poly, off * 0.8, off, 0.2);
  }

  // Warm terracotta bounce-light glow on the putty floor next to terracotta candies!
  brush.wash(PALETTE.terracotta[0], 45);
  for (let s of snacks) {
    if (s.type === "candy" && (s.subtype === "terracotta" || s.subtype === "chipped")) {
      drawOffsetPoly(s.poly, 5, 6, 0.3);
    }
  }

  // Opaque silhouette backing so dark floor chips never bleed through light cashews
  for (let s of snacks) {
    brush.wash(s.baseCol, 225);
    drawOffsetPoly(s.poly, 0, 0, 0.25);
  }
  brush.noWash();

  // --------------------------------------------------------------------------
  // PASS 2: Layered Watercolor Bodies (Batched by Color for Speed & Bleed)
  // --------------------------------------------------------------------------
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.58, 0.38);

  const baseGroups = {};
  const shadeGroups = {};
  for (let s of snacks) {
    if (!baseGroups[s.baseCol]) baseGroups[s.baseCol] = [];
    baseGroups[s.baseCol].push(s);

    if (!shadeGroups[s.shadeCol]) shadeGroups[s.shadeCol] = [];
    shadeGroups[s.shadeCol].push(s);
  }

  // Layer 2A: Primary Watercolor Wash
  for (let col in baseGroups) {
    brush.fill(col, 175);
    for (let s of baseGroups[col]) {
      drawOffsetPoly(s.poly, 0, 0, s.type === "candy" ? 0.45 : 0.3);
    }
  }

  // Layer 2B: Secondary Shaded / Toasted Watercolor Wash
  brush.fillBleed(0.18, "in");
  for (let col in shadeGroups) {
    brush.fill(col, 135);
    for (let s of shadeGroups[col]) {
      drawOffsetPoly(s.shadePoly, 0, 0, 0.3);
    }
  }

  // Layer 2C: Luminous Inner Crown Wash on Cashews & Candies
  brush.fill(PALETTE.cashewHighlight, 115);
  for (let s of snacks) {
    if (s.type === "cashew") {
      drawOffsetPoly(s.innerPoly, 0, 0, 0.35);
    }
  }
  brush.fill(PALETTE.terracotta[2], 110);
  for (let s of snacks) {
    if (s.type === "candy" && (s.subtype === "terracotta" || s.subtype === "chipped")) {
      drawOffsetPoly(s.innerPoly, 0, 0, 0.4);
    }
  }
  brush.noFill();

  // --------------------------------------------------------------------------
  // PASS 3: Crisp Pen Contours, Anatomical Details & Pinpoint Specular Glints
  // --------------------------------------------------------------------------
  for (let s of snacks) {
    if (s.type === "cashew") {
      drawCashewDetails(s);
    } else if (s.type === "candy") {
      drawCandyDetails(s);
    } else if (s.type === "raisin") {
      drawRaisinDetails(s);
    } else if (s.type === "seed") {
      drawSeedDetails(s);
    }
  }
}

function drawCashewDetails(s) {
  // Subtle toasted umber contour on shadow side
  brush.set("2B", PALETTE.cashewUmber, 0.52);
  let n = s.poly.length;
  for (let i = 0; i < floor(n * 0.55); i++) {
    let p1 = s.poly[i];
    let p2 = s.poly[(i + 1) % n];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Characteristic inner cleft dimple & roasted surface pores
  let cleftPt = s.poly[floor(n * 0.75)];
  brush.set("rotring", "#6e5232", 0.42);
  brush.line(cleftPt[0], cleftPt[1], lerp(cleftPt[0], s.x, 0.38), lerp(cleftPt[1], s.y, 0.38));

  // Tiny roasted pores along the cashew nose
  for (let i = 0; i < 5; i++) {
    let px = s.x + cos(s.rot + random(-35, 35)) * s.radius * random(0.3, 0.75);
    let py = s.y + sin(s.rot + random(-35, 35)) * s.radius * random(0.2, 0.45);
    brush.line(px, py, px + 1.2, py + 0.8);
  }

  // Crisp white pen highlight along upper-left ridge + pinpoint oil glint
  brush.set("pen", "#fffdf7", 0.72);
  let hStart = floor(n * 0.55);
  for (let i = hStart; i < hStart + 4; i++) {
    let p1 = s.innerPoly[i % n];
    let p2 = s.innerPoly[(i + 1) % n];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Pinpoint specular glint on the plump crown
  brush.set("pen", PALETTE.white, 0.95);
  let gx = s.x - s.radius * 0.25;
  let gy = s.y - s.radius * 0.22;
  brush.line(gx, gy, gx + 2.5, gy - 1.2);
}

function drawCandyDetails(s) {
  let n = s.poly.length;

  // If chipped, expose the dark chocolate core and crisp white sugar shell rim!
  if (s.subtype === "chipped") {
    brush.noStroke();
    brush.wash(PALETTE.chocolateCore, 235);
    brush.beginShape(0.1);
    brush.vertex(s.poly[0][0], s.poly[0][1]);
    brush.vertex(s.poly[1][0], s.poly[1][1]);
    brush.vertex(s.poly[2][0], s.poly[2][1]);
    brush.vertex(lerp(s.poly[1][0], s.x, 0.45), lerp(s.poly[1][1], s.y, 0.45));
    brush.endShape(true);
    brush.noWash();

    // Thin white sugar coating fracture rim
    brush.set("pen", "#faf6f0", 0.65);
    brush.line(s.poly[0][0], s.poly[0][1], lerp(s.poly[1][0], s.x, 0.45), lerp(s.poly[1][1], s.y, 0.45));
    brush.line(lerp(s.poly[1][0], s.x, 0.45), lerp(s.poly[1][1], s.y, 0.45), s.poly[2][0], s.poly[2][1]);
  }

  // Crisp lower-right shadow contour
  brush.set("rotring", "#24120d", 0.42);
  for (let i = 1; i < 6; i++) {
    let p1 = s.poly[i % n];
    let p2 = s.poly[(i + 1) % n];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Reflected floor bounce-light arc along the bottom-right rim
  brush.set("pen", "#e8dfd0", 0.5);
  let b1 = s.shadePoly[2];
  let b2 = s.shadePoly[3];
  brush.line(b1[0], b1[1], b2[0], b2[1]);

  // Razor-sharp glossy sugar shell specular window reflection & pinpoint glints!
  let gx = s.x - s.radius * 0.28;
  let gy = s.y - s.radius * 0.28;

  brush.noStroke();
  brush.wash(PALETTE.white, s.inReflection ? 250 : 225);
  brush.circle(gx, gy, s.radius * 0.14, 0.1);
  brush.noWash();

  brush.set("pen", PALETTE.white, s.inReflection ? 1.05 : 0.85);
  // Curved specular arc
  brush.arc(s.x, s.y, s.radius * 0.62, 200, 252);
  // Secondary pinpoint glint dot
  brush.line(gx + s.radius * 0.22, gy - s.radius * 0.08, gx + s.radius * 0.26, gy - s.radius * 0.06);
}

function drawRaisinDetails(s) {
  // Deep angular wrinkle canyons across the raisin
  brush.set("rotring", PALETTE.raisinEdge, 0.52);
  for (let i = 0; i < 4; i++) {
    let pA = s.poly[(i * 3) % s.poly.length];
    let pB = s.poly[(i * 3 + 5) % s.poly.length];
    let midX = s.x + random(-s.radius * 0.35, s.radius * 0.35);
    let midY = s.y + random(-s.radius * 0.35, s.radius * 0.35);
    brush.spline([
      [lerp(pA[0], s.x, 0.25), lerp(pA[1], s.y, 0.25)],
      [midX, midY],
      [lerp(pB[0], s.x, 0.25), lerp(pB[1], s.y, 0.25)]
    ], 0.4);
  }

  // Glossy plum-slate wrinkle ridges catching the light
  brush.set("pen", PALETTE.raisinRidge, 0.5);
  for (let i = 0; i < 3; i++) {
    let a = s.rot + i * 55;
    let rx = s.x + cos(a) * s.radius * 0.35;
    let ry = s.y + sin(a) * s.radius * 0.25;
    brush.line(rx - 3, ry - 2, rx + 3, ry + 1);
  }

  // Pinpoint specular glints on the sticky sugar-crusted raisin peaks!
  brush.set("pen", "#fffdf7", s.inReflection ? 0.9 : 0.72);
  for (let i = 0; i < 3; i++) {
    let gx = s.x + random(-s.radius * 0.45, s.radius * 0.25);
    let gy = s.y + random(-s.radius * 0.35, s.radius * 0.15);
    brush.line(gx, gy, gx + 1.8, gy - 0.8);
  }
}

function drawSeedDetails(s) {
  let tip = s.poly[0];
  let tail = s.poly[5];

  if (s.subtype === "kernel") {
    // Hulled sunflower kernel: central longitudinal groove + crisp highlight edge
    brush.set("2H", PALETTE.seedHullDark, 0.42);
    brush.line(
      lerp(tip[0], s.x, 0.22),
      lerp(tip[1], s.y, 0.22),
      lerp(tail[0], s.x, 0.25),
      lerp(tail[1], s.y, 0.25)
    );

    // Crisp rim highlight & pinpoint tip glint
    brush.set("pen", "#fffdf7", 0.62);
    let p8 = s.poly[8];
    let p9 = s.poly[9];
    brush.line(p8[0], p8[1], p9[0], p9[1]);
    brush.line(p9[0], p9[1], tip[0], tip[1]);

  } else {
    // Striped in-shell sunflower seed: bold cream stripes on dark slate shell
    brush.set("pen", PALETTE.cream[0], 0.65);
    brush.line(tip[0], tip[1], tail[0], tail[1]);
    let s1 = s.poly[2];
    let s2 = s.poly[4];
    brush.line(lerp(tip[0], s1[0], 0.3), lerp(tip[1], s1[1], 0.3), s2[0], s2[1]);
    let s3 = s.poly[8];
    let s4 = s.poly[6];
    brush.line(lerp(tip[0], s3[0], 0.3), lerp(tip[1], s3[1], 0.3), s4[0], s4[1]);

    // Pinpoint specular glint on the ridge
    brush.set("pen", PALETTE.white, 0.8);
    brush.line(s.x - 1.5, s.y - 1.5, s.x + 1, s.y - 1);
  }
}

// ============================================================================
// 8. MICRO-CRUMBS, SALT CRYSTALS & PINPOINT GLINTS
// ============================================================================
function drawCrumbsAndGlints(crumbs) {
  for (let c of crumbs) {
    // Tiny contact shadow for every 3D crumb (distinguishing it from 2D floor specks!)
    brush.set("rotring", "#171519", 0.45);
    brush.line(c.x + 1.4, c.y + 1.8, c.x + 1.4 + c.r, c.y + 1.8);

    if (c.kind === "salt") {
      // Crystalline salt grain with bright white facet
      brush.set("pen", PALETTE.white, 0.78);
      brush.line(c.x, c.y, c.x + c.r * 0.85, c.y - c.r * 0.3);
    } else if (c.kind === "nut") {
      // Toasted cashew crumb
      brush.set("marker", PALETTE.cashewBase, 0.55);
      brush.line(c.x, c.y, c.x + cos(c.angle) * c.r, c.y + sin(c.angle) * c.r);
      brush.set("pen", "#fffdf7", 0.45);
      brush.line(c.x, c.y, c.x + 1.2, c.y - 0.8);
    } else if (c.kind === "terracottaShard") {
      // Tiny chipped candy shell fleck
      brush.set("marker", PALETTE.terracotta[0], 0.52);
      brush.line(c.x, c.y, c.x + cos(c.angle) * c.r, c.y + sin(c.angle) * c.r);
      brush.set("pen", PALETTE.white, 0.5);
      brush.line(c.x, c.y, c.x + 1, c.y - 1);
    } else {
      // Papery seed hull / raisin stem fleck
      brush.set("2B", PALETTE.slate[1], 0.48);
      brush.line(c.x, c.y, c.x + cos(c.angle) * c.r * 1.2, c.y + sin(c.angle) * c.r * 1.2);
    }
  }
}

// ============================================================================
// GEOMETRY HELPERS
// ============================================================================
function drawOrganicBlob(cx, cy, rad, nVerts, varMin, varMax) {
  brush.beginShape(0.45);
  for (let i = 0; i < nVerts; i++) {
    let a = (i / nVerts) * 360;
    let r = rad * random(varMin, varMax);
    brush.vertex(cx + cos(a) * r, cy + sin(a) * r);
  }
  brush.endShape(true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4289);
  noiseSeed(4289);
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#dedad0");

  // ---------------------------------------------------------------------------
  // 1. GEOMETRY, 3D DRAPE SURFACE & RAKING LIGHT MODEL
  // ---------------------------------------------------------------------------
  const hookX = 575;
  const hookY = 76;

  // Apron boundary helper
  function getApronBounds(y) {
    let leftX, rightX;
    if (y < 250) {
      return { valid: false, leftX: 575, rightX: 575 };
    } else if (y < 575) {
      // Bib flaring out to waist via curved underarm cut
      let t = (y - 250) / (575 - 250);
      let curve = pow(t, 1.65);
      leftX = lerp(332, 128, curve) + sin(t * 180) * 6;
      rightX = lerp(812, 1052, curve) - sin(t * 180) * 6;
    } else if (y <= 1182) {
      // Skirt hanging down from waist to hem
      let t = (y - 575) / (1182 - 575);
      leftX = lerp(128, 92, t) + sin(t * 240) * 8 + (noise(y * 0.015, 1) - 0.5) * 10;
      rightX = lerp(1052, 1088, t) + cos(t * 210) * 8 + (noise(y * 0.015, 2) - 0.5) * 10;
    } else {
      return { valid: false, leftX: 0, rightX: 0 };
    }
    return { valid: true, leftX, rightX };
  }

  function isInsideApron(x, y) {
    if (y < 248 || y > 1184) return false;
    let b = getApronBounds(y);
    if (!b.valid) return false;
    // Top bib sag
    if (y < 272 && x >= 325 && x <= 820) {
      let sag = 250 + sin(((x - 332) / (812 - 332)) * 180) * 18;
      if (y < sag) return false;
    }
    // Bottom hem wave
    if (y > 1155) {
      let hem = 1172 + sin((x - 90) * 0.95) * 8 + cos((x - 200) * 0.55) * 5;
      if (y > hem) return false;
    }
    return x >= b.leftX && x <= b.rightX;
  }

  // Major vertical/radiating drape folds of the heavy quilted cotton
  const folds = [
    { x0: 338, y0: 252, x1: 270, y1: 1180, w: 58, amp: 28 }, // Left bib suspension pillar
    { x0: 435, y0: 268, x1: 428, y1: 1180, w: 52, amp: 17 }, // Inner left pipe fold
    { x0: 572, y0: 275, x1: 582, y1: 1180, w: 68, amp: 21 }, // Central deep fold ridge
    { x0: 705, y0: 266, x1: 735, y1: 1180, w: 56, amp: 19 }, // Inner right fold
    { x0: 806, y0: 250, x1: 895, y1: 1180, w: 64, amp: 30 }, // Right bib suspension pillar
    { x0: 148, y0: 575, x1: 132, y1: 1180, w: 48, amp: 22 }, // Left waist gather fold
    { x0: 1032, y0: 568, x1: 1028, y1: 1180, w: 52, amp: 23 } // Right waist gather fold
  ];

  // Heightmap of the cloth (0..50 units)
  function getClothHeight(x, y) {
    let h = 10;
    for (let i = 0; i < folds.length; i++) {
      let f = folds[i];
      if (y >= f.y0 - 40) {
        let t = constrain((y - f.y0) / (f.y1 - f.y0), 0, 1);
        let fx = lerp(f.x0, f.x1, t);
        let fw = f.w * (0.75 + 0.45 * t);
        let dx = x - fx;
        if (abs(dx) < fw * 2.2) {
          let env = y < f.y0 ? constrain((y - (f.y0 - 40)) / 40, 0, 1) : 1;
          h += f.amp * env * exp(-(dx * dx) / (fw * fw));
        }
      }
    }
    // Diagonal tension creases from pocket corners and bib
    let c1 = sin((x * 0.65 + y * 0.35) * 1.1) * 2.5;
    let c2 = cos((x * 0.4 - y * 0.7) * 0.9) * 2.0;
    // Pocket layer step-up
    if (x > 342 && x < 836 && y > 568 && y < 918) {
      let pSag = 568 + sin(((x - 342) / 494) * 180) * 18;
      if (y > pSag) h += 5.5;
    }
    return h + c1 + c2 + (noise(x * 0.012, y * 0.012) - 0.5) * 6;
  }

  // Window raking light beam intensity (upper-left to lower-right shaft)
  function getWindowBeam(x, y) {
    let diag = (x * 0.52 + y * 0.85) - 520;
    let beam = exp(-(diag * diag) / (460 * 460));
    // Subtle window mullion shadow bar in upper right & far lower left
    let mullion = 1.0 - 0.32 * exp(-pow((x * 0.58 + y * 0.81 - 180) / 55, 2));
    return constrain(0.28 + 0.82 * beam * mullion, 0.15, 1.15);
  }

  // Full lighting & normal query at (x, y)
  function getClothLight(x, y) {
    let hC = getClothHeight(x, y);
    let hR = getClothHeight(x + 3, y);
    let hL = getClothHeight(x - 3, y);
    let hD = getClothHeight(x, y + 3);
    let hU = getClothHeight(x, y - 3);
    let dHx = (hR - hL) / 6.0; // Positive on left flank of a ridge
    let dHy = (hD - hU) / 6.0; // Positive on top flank of a ridge
    // Grazing raking light from left-upper-left
    let raking = 0.52 + dHx * 0.95 + dHy * 0.32;
    let beam = getWindowBeam(x, y);
    let val = constrain(raking * beam, 0.04, 1.25);
    return { val, dHx, dHy, h: hC, beam };
  }

  // Displace 2D pattern coordinates slightly according to 3D cloth drape
  function warpPt(x, y) {
    let st = getClothLight(x, y);
    let sagY = 0;
    if (x > 300 && x < 860) {
      sagY = sin(((x - 300) / 560) * 180) * 10;
    }
    return [x - st.dHx * 4.5, y + sagY * 0.45 - st.dHy * 3.0];
  }

  // Helper to build organic polygons for watercolor fills
  function makeContourPoly(pts, col, op, bleed = 0.18, tex = 0.7) {
    let p = new brush.Polygon(pts);
    p.fill(col, op, bleed, tex);
  }

  function makeWashPoly(pts, col, op) {
    let p = new brush.Polygon(pts);
    p.wash(col, op);
  }

  // ---------------------------------------------------------------------------
  // 2. WHITEWASHED PLANK WALL & RAKING SUNLIGHT
  // ---------------------------------------------------------------------------
  const plankX = [0, 258, 575, 912, 1200];

  // Base warm whitewash washes modulated by the raking window light
  makeWashPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], "#d8d3c8", 220);

  // Sunlit diagonal window zone on the wall
  makeContourPoly(
    [[0, 0], [880, 0], [1200, 520], [1200, 1080], [320, 1200], [0, 780]],
    "#f2efe6", 150, 0.25, 0.65
  );
  makeContourPoly(
    [[0, 60], [640, 0], [1200, 640], [1200, 960], [540, 1200], [0, 620]],
    "#fbf9f2", 120, 0.22, 0.55
  );

  // Shadowed wall corners (upper right & lower left outside main raking shaft)
  makeContourPoly(
    [[680, 0], [1200, 0], [1200, 520], [920, 260]],
    "#94928b", 130, 0.28, 0.75
  );
  makeContourPoly(
    [[0, 740], [380, 1200], [0, 1200]],
    "#9c9991", 125, 0.28, 0.75
  );

  // Peeling/weathered wood-tone patches showing through whitewash
  const wallPatches = [
    [[45, 110], [210, 120], [225, 380], [50, 360]],
    [[610, 40], [860, 55], [850, 230], [600, 210]],
    [[945, 290], [1160, 310], [1150, 680], [955, 650]],
    [[25, 680], [140, 700], [120, 1120], [20, 1100]],
    [[980, 820], [1180, 840], [1175, 1170], [990, 1150]]
  ];
  for (let wp of wallPatches) {
    makeContourPoly(wp, "#b8b1a2", 75, 0.25, 0.82);
  }

  // Vertical plank grain, flaky whitewash texture, and deep plank joints
  for (let p = 0; p < 4; p++) {
    let xStart = plankX[p];
    let xEnd = plankX[p + 1];

    // Vertical wood grain & chalky brush marks on visible wall areas
    for (let i = 0; i < 95; i++) {
      let gx = random(xStart + 6, xEnd - 6);
      let gy1 = random(0, 1120);
      let gy2 = gy1 + random(45, 210);
      // Skip strokes deep inside the apron silhouette to save budget
      if (isInsideApron(gx, (gy1 + gy2) * 0.5) && gx > 170 && gx < 1010 && gy1 > 290) continue;

      let beam = getWindowBeam(gx, gy1);
      if (random() < 0.55) {
        brush.set("2H", beam > 0.7 ? "#c4bfb2" : "#8f8b80", random(0.4, 0.9));
      } else {
        brush.set("cpencil", beam > 0.75 ? "#ffffff" : "#eae6dc", random(0.6, 1.3));
      }
      let drift = (noise(gx * 0.02, gy1 * 0.01) - 0.5) * 8;
      brush.line(gx, gy1, gx + drift, min(1200, gy2));
    }
  }

  // Plank gaps (deep dark vertical seams with sunlit left edge & highlighted right lip)
  for (let p = 1; p <= 3; p++) {
    let sx = plankX[p];
    for (let y = 0; y < 1200; y += 36) {
      if (isInsideApron(sx, y + 18) && y > 280 && y < 1140) continue;
      let y2 = min(1200, y + 38);
      let jx1 = sx + (noise(p * 10, y * 0.02) - 0.5) * 3.5;
      let jx2 = sx + (noise(p * 10, y2 * 0.02) - 0.5) * 3.5;

      // Shadowed gap
      brush.set("charcoal", "#2b2823", 1.8);
      brush.line(jx1, y, jx2, y2);
      brush.set("rotring", "#12100e", 1.1);
      brush.line(jx1 - 0.5, y, jx2 - 0.5, y2);

      // Raking light catching the right plank's left-facing edge
      let beam = getWindowBeam(sx, y);
      brush.set("cpencil", beam > 0.65 ? "#ffffff" : "#dedad0", 1.2);
      brush.line(jx1 + 3.2, y, jx2 + 3.2, y2);
    }
  }

  // ---------------------------------------------------------------------------
  // 3. CAST SHADOW OF APRON, STRAPS & HOOK ON THE PLANK WALL
  // ---------------------------------------------------------------------------
  // Because raking light comes from upper-left, the apron casts a strong, crisp-yet-softened
  // shadow shifted to the right (+34px) and downward (+22px)
  let rightShadowPts = [];
  for (let y = 250; y <= 1180; y += 22) {
    let b = getApronBounds(y);
    rightShadowPts.push([b.rightX - 15, y]);
  }
  for (let y = 1180; y >= 250; y -= 22) {
    let b = getApronBounds(y);
    let loft = (y > 550 && y < 620) ? 48 : 38 + sin(y * 0.8) * 8;
    rightShadowPts.push([b.rightX + loft, y + 24]);
  }
  makeContourPoly(rightShadowPts, "#4a4e54", 145, 0.28, 0.65);

  let coreShadowPts = [];
  for (let y = 250; y <= 1180; y += 25) {
    let b = getApronBounds(y);
    coreShadowPts.push([b.rightX - 8, y]);
  }
  for (let y = 1180; y >= 250; y -= 25) {
    let b = getApronBounds(y);
    coreShadowPts.push([b.rightX + 22, y + 15]);
  }
  makeContourPoly(coreShadowPts, "#1e232b", 180, 0.15, 0.75);

  // Shadow under neck strap & bib top
  makeContourPoly(
    [[575, 82], [608, 96], [848, 274], [805, 265], [580, 102]],
    "#252a33", 170, 0.2, 0.6
  );
  makeContourPoly(
    [[572, 85], [368, 268], [335, 260], [558, 82]],
    "#323842", 145, 0.2, 0.6
  );

  // Dangling waist ties on left & right sides (plus their wall shadows)
  // Left waist tie
  makeContourPoly(
    [[138, 578], [156, 588], [122, 895], [104, 888]],
    "#262b34", 150, 0.18, 0.6
  );
  makeContourPoly(
    [[125, 570], [144, 576], [106, 882], [86, 875]],
    "#182e4a", 220, 0.1, 0.7
  );
  // Right waist tie
  makeContourPoly(
    [[1055, 572], [1082, 584], [1136, 945], [1110, 940]],
    "#222730", 165, 0.2, 0.65
  );
  makeContourPoly(
    [[1045, 562], [1068, 570], [1116, 932], [1092, 926]],
    "#102238", 230, 0.1, 0.7
  );

  // ---------------------------------------------------------------------------
  // 4. NECK STRAPS & HAND-FORGED IRON HOOK
  // ---------------------------------------------------------------------------
  // Iron wall backplate (diamond-oval forged plate above the neck loop)
  makeContourPoly(
    [[578, 34], [610, 74], [578, 122], [548, 74]],
    "#23262b", 180, 0.15, 0.7
  );
  makeWashPoly(
    [[575, 30], [602, 70], [575, 116], [548, 70]],
    "#1a1816", 240
  );

  // Neck strap loop hanging from hook to bib corners
  // Left strap
  const leftStrapPts = [
    [568, 66], [584, 76], [366, 266], [332, 258], [450, 155]
  ];
  makeWashPoly(leftStrapPts, "#162d4c", 235);
  makeContourPoly(leftStrapPts, "#3e5c7d", 155, 0.12, 0.7);

  // Right strap
  const rightStrapPts = [
    [572, 66], [590, 74], [814, 256], [780, 266], [685, 168]
  ];
  makeWashPoly(rightStrapPts, "#0b1a30", 245);
  makeContourPoly(rightStrapPts, "#233c59", 165, 0.12, 0.7);

  // Strap stitch details & faded edges
  for (let t = 0; t <= 1; t += 0.025) {
    let lx = lerp(568, 336, t);
    let ly = lerp(70, 256, t) + sin(t * 180) * 6;
    brush.set("cpencil", "#9ab2c9", 1.1);
    brush.line(lx, ly, lx - 5, ly + 4);
    brush.set("rotring", "#060e1a", 0.8);
    brush.line(lx + 24, ly + 8, lx + 19, ly + 12);

    let rx = lerp(582, 808, t);
    let ry = lerp(70, 252, t) + sin(t * 180) * 5;
    brush.set("cpencil", "#7892ad", 1.0);
    brush.line(rx - 22, ry + 8, rx - 16, ry + 13);
    brush.set("rotring", "#050b14", 0.9);
    brush.line(rx, ry, rx + 5, ry + 4);
  }

  // Iron hook curving up in front of the strap apex
  for (let i = 0; i < 18; i++) {
    let a = map(i, 0, 18, 15, 165);
    let hx = 575 + cos(a) * 14;
    let hy = 72 + sin(a) * 18;
    brush.set("charcoal", "#121110", 2.2);
    brush.line(hx - 2, hy, hx + 2, hy + 3);
  }
  // Forged hook stem & ball tip catching bright raking window light
  brush.set("pen", "#0d0c0b", 3.5);
  brush.line(575, 44, 575, 92);
  brush.set("pen", "#2e3136", 2.2);
  brush.line(572, 52, 572, 88);
  brush.set("cpencil", "#d8e0e8", 1.5);
  brush.line(570, 56, 570, 84);
  brush.set("rotring", "#ffffff", 1.0);
  brush.line(569, 60, 569, 76);
  // Nail heads on iron plate
  brush.set("pen", "#0e0d0c", 2.4);
  brush.circle(575, 44, 4, 0.2);
  brush.set("cpencil", "#ced6de", 1.1);
  brush.arc(575, 44, 4, 160, 290);

  // ---------------------------------------------------------------------------
  // 5. APRON BASE WATERCOLOR WASHES (DEEP PRUSSIAN & SLATE-BLUE)
  // ---------------------------------------------------------------------------
  // Build full apron outline polygon
  let apronPoly = [];
  for (let x = 332; x <= 812; x += 24) {
    let sag = 250 + sin(((x - 332) / (812 - 332)) * 180) * 18;
    apronPoly.push([x, sag]);
  }
  for (let y = 260; y <= 1172; y += 24) {
    apronPoly.push([getApronBounds(y).rightX, y]);
  }
  for (let x = 1085; x >= 95; x -= 24) {
    let hem = 1172 + sin((x - 90) * 0.95) * 8 + cos((x - 200) * 0.55) * 5;
    apronPoly.push([x, hem]);
  }
  for (let y = 1172; y >= 260; y -= 24) {
    apronPoly.push([getApronBounds(y).leftX, y]);
  }

  // Solid base wash so wall doesn't bleed through dark cloth
  makeWashPoly(apronPoly, "#17304f", 242);

  // Watercolor wash layer 1: Overall rich slate-indigo body
  makeContourPoly(apronPoly, "#213f63", 175, 0.15, 0.78);

  // Watercolor wash layer 2: Sun-struck raking light zones (slate-blue & faded indigo)
  const sunlitZones = [
    [[325, 255], [640, 265], [590, 620], [135, 580], [240, 410]],
    [[135, 580], [560, 610], [640, 960], [110, 920]],
    [[340, 565], [760, 580], [740, 880], [350, 860]]
  ];
  for (let z of sunlitZones) {
    makeContourPoly(z, "#3e5f82", 125, 0.28, 0.72);
  }

  // Watercolor wash layer 3: Deep Prussian blue fold valleys (batched for performance)
  for (let f of folds) {
    let valleyPts = [];
    for (let y = f.y0; y <= f.y1; y += 45) {
      let t = (y - f.y0) / (f.y1 - f.y0);
      let fx = lerp(f.x0, f.x1, t) + f.w * 0.62; // Right shadow flank of fold
      valleyPts.push([fx - f.w * 0.38, y]);
    }
    for (let y = f.y1; y >= f.y0; y -= 45) {
      let t = (y - f.y0) / (f.y1 - f.y0);
      let fx = lerp(f.x0, f.x1, t) + f.w * 0.62;
      valleyPts.push([fx + f.w * 0.52, y]);
    }
    makeContourPoly(valleyPts, "#091930", 175, 0.22, 0.75);
  }

  // Deepest Prussian-black shadows in lower-right & core fold troughs
  const deepPrussianZones = [
