  // Frayed warp & weft threads around every Boro patch perimeter
  function drawPatchEdgeAndFray(x1, y1, x2, y2, steps, isSunlitEdge) {
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let bx = lerp(x1, x2, t) + (noise(t * 8, x1 * 0.1) - 0.5) * 4;
      let by = lerp(y1, y2, t) + (noise(t * 8, y1 * 0.1) - 0.5) * 4;
      let p = warpPt(bx, by);
      let st = getClothLight(bx, by);

      // Cast shadow under raw patch edge
      brush.set("rotring", "#040a14", 1.15);
      brush.line(p[0] + 1.8, p[1] + 2.0, p[0] + 4.5, p[1] + 3.2);

      // Raw frayed short threads poking out
      if (i % 2 === 0) {
        let ang = atan2(y2 - y1, x2 - x1) + 90 + random(-25, 25);
        let flen = random(4, 11);
        let fCol = (st.val > 0.65 || isSunlitEdge) ? "#b8cadb" : "#5a748f";
        brush.set("2H", fCol, random(0.55, 0.95));
        brush.line(p[0], p[1], p[0] + cos(ang) * flen, p[1] + sin(ang) * flen);
      }
    }
  }

  // Patch 1 frayed borders
