  // ---------------------------------------------------------------------------
  // 8. HYPERREALISTIC SASHIKO STITCH ENGINE
  // ---------------------------------------------------------------------------
  // "Every stitch is a separate short pen dash with a slight thread twist and a tiny shadow.
  //  Raking light from a window catches the ridges of the quilting."
  function drawStitch(x1, y1, x2, y2, quiltRidge = true) {
    let p1 = warpPt(x1, y1);
    let p2 = warpPt(x2, y2);
    let mx = (x1 + x2) * 0.5;
    let my = (y1 + y2) * 0.5;
    let st = getClothLight(mx, my);

    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len = sqrt(dx * dx + dy * dy);
    if (len < 1.5) return;
    let nx = -dy / len;
    let ny = dx / len;

    // 1. Quilted fabric ridge highlight & groove caught by raking window light
    if (quiltRidge && st.val > 0.45) {
      let ridgeCol = st.val > 0.85 ? "#8ea8c2" : "#526f8c";
      brush.set("cpencil", ridgeCol, 0.85);
      brush.line(
        p1[0] - 2.4 + nx * 1.8, p1[1] - 1.5 + ny * 1.8,
        p2[0] - 2.4 + nx * 1.8, p2[1] - 1.5 + ny * 1.8
      );
      // Tension pucker trough on the shadow side of the stitch
      brush.set("2B", "#051020", 0.75);
      brush.line(
        p1[0] + 2.2 - nx * 1.5, p1[1] + 2.0 - ny * 1.5,
        p2[0] + 2.2 - nx * 1.5, p2[1] + 2.0 - ny * 1.5
      );
    }

    // 2. Tiny needle-hole dimples & cast shadow directly beneath the thick cotton thread
    brush.set("rotring", "#030811", 0.95);
    brush.line(p1[0] + 1.4, p1[1] + 1.7, p2[0] + 1.5, p2[1] + 1.8);

    // 3. Thread color based on raking light & fold shadow (high contrast values)
    let threadBase, threadHi;
    if (st.val > 0.90) {
      threadBase = "#ede9df";
      threadHi = "#ffffff";
    } else if (st.val > 0.68) {
      threadBase = "#d4d0c5";
      threadHi = "#f7f5ee";
    } else if (st.val > 0.44) {
      threadBase = "#9aa6b2";
      threadHi = "#bfc9d4";
    } else {
      threadBase = "#5e6e80";
      threadHi = "#7c8ea1";
    }

    // 4. Two slightly twisted ply dashes to emulate spun Sashiko cotton thread
    let midX = (p1[0] + p2[0]) * 0.5;
    let midY = (p1[1] + p2[1]) * 0.5;
    let twist = 0.65;

    brush.set("pen", threadBase, 1.05);
    brush.line(p1[0], p1[1], midX + nx * twist, midY + ny * twist);
    brush.line(midX - nx * twist, midY - ny * twist, p2[0], p2[1]);

    // Specular crest on the sun-facing twist of the thread
    brush.set("rotring", threadHi, st.val > 0.75 ? 0.85 : 0.6);
    brush.line(
      p1[0] + dx * 0.12 - nx * 0.35,
      p1[1] + dy * 0.12 - ny * 0.35,
      p2[0] - dx * 0.15 + nx * 0.25,
      p2[1] - dy * 0.15 + ny * 0.25
    );
  }

  // Helper: Check if a point is occluded by the front utility pocket
  function isUnderPocket(x, y) {
    if (x < 343 || x > 837 || y > 914) return false;
    let py = 567 + sin(((x - 345) / 490) * 180) * 18;
    return y >= py;
  }

  // ---------------------------------------------------------------------------
  // 9. PATTERN 1: PERSIMMON-FLOWER (KAKINOHANA - 柿の花) SASHIKO PATCHES
  // ---------------------------------------------------------------------------
  function renderPersimmonFlowerPatch(xmin, ymin, xmax, ymax, gridStep, maskPocket) {
    let cols = floor((xmax - xmin) / gridStep);
    let rows = floor((ymax - ymin) / gridStep);
    let margin = gridStep * 0.17; // Gap between running stitches

    // First pass: Raking light catching the miniature quilted pillows inside each flower cell
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        let cx = xmin + (c + 0.5) * gridStep;
        let cy = ymin + (r + 0.5) * gridStep;
        if (maskPocket && isUnderPocket(cx, cy)) continue;
        if (!isInsideApron(cx, cy)) continue;

        let st = getClothLight(cx, cy);
        let p = warpPt(cx, cy);
        // Flower centers at (c % 4 === 0, r % 4 === 0) and (c % 4 === 2, r % 4 === 2)
        let isFlowerCore = ((c % 4 === 0 && r % 4 === 0) || (c % 4 === 2 && r % 4 === 2));
        if (st.val > 0.52) {
          brush.set("cpencil", st.val > 0.82 ? "#96b0c9" : "#607d99", isFlowerCore ? 1.25 : 0.85);
          brush.line(p[0] - 3.5, p[1] - 2.5, p[0] + 1.5, p[1] - 0.5);
          brush.set("2B", "#08182e", 0.85);
          brush.line(p[0] - 0.5, p[1] + 2.5, p[0] + 3.5, p[1] + 3.2);
        }
      }
    }

    // Second pass: Horizontal running stitches of Kakinohana
    for (let r = 0; r <= rows; r++) {
      let y = ymin + r * gridStep;
      let rMod = ((r % 4) + 4) % 4;
      for (let c = 0; c < cols; c++) {
        let cMod = ((c % 4) + 4) % 4;
        // Authentic Kakinohana step rule forming 4-petal persimmon flowers & inner crosses
        let active =
          ((rMod === 0 || rMod === 3) && (cMod === 1 || cMod === 2)) ||
          ((rMod === 1 || rMod === 2) && (cMod === 0 || cMod === 3));

        if (!active) continue;
        let x1 = xmin + c * gridStep + margin;
        let x2 = xmin + (c + 1) * gridStep - margin;
        let mx = (x1 + x2) * 0.5;
        if (maskPocket && isUnderPocket(mx, y)) continue;
        if (!isInsideApron(mx, y)) continue;
        // Occasional worn/missing stitch near ragged edges
        if (noise(c * 0.3, r * 0.3) < 0.04) continue;

        let jitY = (noise(c * 0.7, r * 1.3) - 0.5) * 1.1;
        drawStitch(x1, y + jitY, x2, y - jitY, false);
      }
    }

    // Third pass: Vertical running stitches of Kakinohana
    for (let c = 0; c <= cols; c++) {
      let x = xmin + c * gridStep;
      let cMod = ((c % 4) + 4) % 4;
      for (let r = 0; r < rows; r++) {
        let rMod = ((r % 4) + 4) % 4;
        let active =
          ((cMod === 0 || cMod === 3) && (rMod === 1 || rMod === 2)) ||
          ((cMod === 1 || cMod === 2) && (rMod === 0 || rMod === 3));

        if (!active) continue;
        let y1 = ymin + r * gridStep + margin;
        let y2 = ymin + (r + 1) * gridStep - margin;
        let my = (y1 + y2) * 0.5;
        if (maskPocket && isUnderPocket(x, my)) continue;
        if (!isInsideApron(x, my)) continue;
        if (noise(c * 0.35 + 10, r * 0.35) < 0.04) continue;

        let jitX = (noise(c * 1.3, r * 0.7 + 20) - 0.5) * 1.1;
        drawStitch(x + jitX, y1, x - jitX, y2, false);
      }
    }
  }

  // Render Upper-Right Chest Persimmon-Flower Patch
  renderPersimmonFlowerPatch(564, 280, 822, 534, 13.5, true);

  // Render Lower-Right Skirt Persimmon-Flower Patch
  renderPersimmonFlowerPatch(648, 845, 1012, 1135, 14.5, false);

  // ---------------------------------------------------------------------------
  // 10. PATTERN 2: WAVE (SEIGAIHA - 青海波) SASHIKO PATCH
  // ---------------------------------------------------------------------------
  function renderWavePatch(xmin, ymin, xmax, ymax, R) {
    let dx = R * 1.78;
    let dy = R * 0.50;
    let rows = floor((ymax - ymin + R) / dy);
    let cols = floor((xmax - xmin + dx) / dx) + 1;

    // Precompute all wave centers
    let centers = [];
    for (let r = 0; r <= rows; r++) {
      let rowArr = [];
      let cy = ymin + r * dy;
      let xOff = (r % 2 === 1) ? dx * 0.5 : 0;
      for (let c = -1; c <= cols; c++) {
        rowArr.push({ cx: xmin + c * dx + xOff, cy, r });
      }
      centers.push(rowArr);
    }

    // For each wave arch, draw 5 concentric stitched arcs, clipped by lower overlapping rows
    const numRings = 5;
    for (let r = 0; r < centers.length; r++) {
      for (let c = 0; c < centers[r].length; c++) {
        let w = centers[r][c];

        for (let k = 1; k <= numRings; k++) {
          let rad = R * (k / numRings);
          let stitchPitch = 12.5; // Arc length of one stitch + gap
          let totalArc = PI * rad * 0.85;
          let numStitches = max(3, floor(totalArc / stitchPitch));
          let aStart = -164;
          let aEnd = -16;

          for (let s = 0; s < numStitches; s++) {
            let a1 = lerp(aStart, aEnd, (s + 0.14) / numStitches);
            let a2 = lerp(aStart, aEnd, (s + 0.78) / numStitches);
            let am = (a1 + a2) * 0.5;

            let mx = w.cx + cos(am) * rad;
            let my = w.cy + sin(am) * rad;

            // Clip to patch bounds & pocket occlusion
            if (mx < xmin + 8 || mx > xmax - 8 || my < ymin + 8 || my > ymax - 8) continue;
            if (isUnderPocket(mx, my)) continue;
            if (!isInsideApron(mx, my)) continue;

            // Check occlusion against wave crests in rows r+1 and r+2
            let occluded = false;
            for (let nr = r + 1; nr <= min(centers.length - 1, r + 2); nr++) {
              for (let nc = 0; nc < centers[nr].length; nc++) {
                let nw = centers[nr][nc];
                if (my < nw.cy + 4) {
                  let d = dist(mx, my, nw.cx, nw.cy);
                  if (d < R + 2.5) {
                    occluded = true;
                    break;
                  }
                }
              }
              if (occluded) break;
            }
            if (occluded) continue;

            // Worn thread gap near heavily rubbed pocket corner
            if (dist(mx, my, 345, 578) < 34 && random() < 0.35) continue;

            let x1 = w.cx + cos(a1) * rad;
            let y1 = w.cy + sin(a1) * rad;
            let x2 = w.cx + cos(a2) * rad;
            let y2 = w.cy + sin(a2) * rad;

            drawStitch(x1, y1, x2, y2, true);
          }
        }
      }
    }
  }

  // Render Left/Center Body Wave (Seigaiha) Patch
  renderWavePatch(154, 504, 524, 968, 52);

  // ---------------------------------------------------------------------------
  // 11. VERTICAL & HORIZONTAL RUNNING QUILT STITCHES + POCKET STITCHING
  // ---------------------------------------------------------------------------
  // Upper-Left Bib Patch (Patch 1): Dense vertical running stitches with raking-light ridges
  for (let x = 336; x <= 542; x += 11.5) {
    // Continuous raking-light ridge along the quilted channel between stitch columns
    for (let y = 276; y < 486; y += 16) {
      if (!isInsideApron(x, y)) continue;
      let st = getClothLight(x - 4, y);
      let p1 = warpPt(x - 4.5, y);
      let p2 = warpPt(x - 4.5, y + 14);
      if (st.val > 0.55) {
        brush.set("cpencil", st.val > 0.85 ? "#8da7c2" : "#4b6987", 1.15);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
      brush.set("2B", "#050f1e", 0.9);
      brush.line(p1[0] + 5.5, p1[1], p2[0] + 5.5, p2[1]);
    }
    // The running stitches themselves
    for (let y = 274; y < 484; y += 13) {
      if (!isInsideApron(x, y)) continue;
      if (noise(x * 0.1, y * 0.1) < 0.06) continue;
      drawStitch(x + random(-0.4, 0.4), y, x + random(-0.4, 0.4), y + 8.2, false);
    }
  }

  // Lower-Left Hem Patch (Patch 5): Dense horizontal running reinforcement stitches
  for (let y = 956; y <= 1150; y += 11) {
    for (let x = 118; x < 402; x += 14) {
      if (!isInsideApron(x, y)) continue;
      if (noise(x * 0.08, y * 0.08) < 0.05) continue;
      drawStitch(x, y + random(-0.4, 0.4), x + 9.0, y + random(-0.4, 0.4), true);
    }
  }

  // Vertical quilting stitches along the central and right apron body around patches
  for (let x = 440; x <= 1040; x += 18) {
    for (let y = 550; y < 1155; y += 15) {
      if (!isInsideApron(x, y)) continue;
      if (isUnderPocket(x, y)) continue;
      if (x < 530 && y < 975) continue; // Wave patch zone
      if (x > 640 && x < 1020 && y > 835 && y < 1145) continue; // Lower right patch
      if (noise(x * 0.05, y * 0.05) < 0.25) continue;
      drawStitch(x, y, x, y + 9.2, true);
    }
  }

  // WORK POCKET STITCHING: Double-row hem at top mouth, perimeter reinforcement, & center divider
  // Top mouth double running stitch
  for (let row = 0; row < 2; row++) {
    let yOff = 9 + row * 7;
    for (let x = 358; x < 824; x += 12.5) {
      let py1 = 568 + sin(((x - 345) / 490) * 180) * 18 + yOff;
      let py2 = 568 + sin(((x + 8 - 345) / 490) * 180) * 18 + yOff;
      // Worn away near the loose thread snag at x ~ 525..545
      if (row === 0 && x > 516 && x < 548) continue;
      drawStitch(x, py1, x + 8, py2, true);
    }
  }

  // Pocket left, right, bottom & center-divider double stitch lines
  for (let y = 592; y < 904; y += 13) {
    // Left pocket seam
    drawStitch(353, y, 353, y + 8.2, true);
    drawStitch(361, y + 3, 361, y + 11.2, false);
    // Right pocket seam
    drawStitch(827, y, 827, y + 8.2, true);
    drawStitch(819, y + 3, 819, y + 11.2, false);
    // Center pocket vertical compartment divider
    drawStitch(586, y + 12, 586, y + 20.2, true);
    drawStitch(594, y + 15, 594, y + 23.2, true);
  }
  for (let x = 356; x < 824; x += 13) {
    let by1 = 904 + sin(((x - 345) / 490) * 180) * 10;
    let by2 = 904 + sin(((x + 8.5 - 345) / 490) * 180) * 10;
    drawStitch(x, by1, x + 8.5, by2, true);
    drawStitch(x + 2, by1 - 7, x + 10.5, by2 - 7, false);
  }

  // Decorative diamond/persimmon-bud sashiko reinforcement on the left pocket compartment
  renderPersimmonFlowerPatch(386, 636, 554, 864, 14.0, false);

  // ---------------------------------------------------------------------------
  // 12. INCIDENT 1: CHALK SMUDGE ON THE RIGHT POCKET COMPARTMENT
  // ---------------------------------------------------------------------------
  // A dusty tailor's chalk smudge rubbed diagonally across the weave & fold ridges
  const chalkX = 706;
  const chalkY = 718;

  // Soft translucent chalk dust cloud in the cloth valleys
  let chalkPoly1 = [
    warpPt(642, 682), warpPt(758, 668), warpPt(786, 735),
    warpPt(725, 772), warpPt(635, 745)
  ];
  makeContourPoly(chalkPoly1, "#dce3eb", 55, 0.38, 0.88);

  let chalkPoly2 = [
    warpPt(665, 694), warpPt(742, 685), warpPt(755, 728), warpPt(672, 742)
  ];
  makeContourPoly(chalkPoly2, "#f5f7fa", 70, 0.32, 0.85);

  // Dry chalk pigment catching ONLY the high warp/weft crowns and fold ridges
  for (let i = 0; i < 240; i++) {
    let a = random(-32, -12);
    let r1 = randomGaussian(0, 42);
    let r2 = randomGaussian(0, 22);
    let sx = chalkX + r1 * cos(a) - r2 * sin(a);
    let sy = chalkY + r1 * sin(a) + r2 * cos(a);
    let p = warpPt(sx, sy);

    let distFactor = exp(-(r1 * r1) / (52 * 52) - (r2 * r2) / (26 * 26));
    if (random() > distFactor * 1.15) continue;

    // Smudge follows the diagonal wipe + skips tiny dark cloth pores
    let strokeLen = random(4, 16) * distFactor;
    if (random() < 0.65) {
      brush.set("charcoal", distFactor > 0.55 ? "#ffffff" : "#cfdbe6", random(0.5, 1.25));
      brush.line(p[0], p[1], p[0] + cos(a) * strokeLen, p[1] + sin(a) * strokeLen);
    } else {
      // Chalk catching vertical warp thread crowns
      brush.set("cpencil", "#f2f5f8", random(0.6, 1.1));
      brush.line(p[0], p[1] - 3, p[0], p[1] + 3);
    }
  }
  // Tiny dark indigo weave pores peeking through the dense chalk center for hyperrealism
  for (let i = 0; i < 55; i++) {
    let px = chalkX + random(-36, 36);
    let py = chalkY + random(-18, 18);
    let p = warpPt(px, py);
    brush.set("rotring", "#152c4a", 0.75);
    brush.line(p[0], p[1], p[0] + 1.8, p[1] + 0.5);
  }
  // Faint secondary finger-smudge trail below right
  for (let i = 0; i < 65; i++) {
    let sx = 745 + random(-22, 28);
    let sy = 768 + random(-12, 14);
    let p = warpPt(sx, sy);
    brush.set("cpencil", "#cad7e3", random(0.45, 0.85));
    brush.line(p[0], p[1], p[0] + random(4, 10), p[1] + random(-2, 3));
  }

  // ---------------------------------------------------------------------------
  // 13. INCIDENT 2: BRASS RIVET AT UPPER-LEFT POCKET CORNER
  // ---------------------------------------------------------------------------
  const rivPt = warpPt(358, 578);
  const rx = rivPt[0];
  const ry = rivPt[1];
  const rivR = 11.5;

  // Radial fabric tension puckers pulled into the rivet
  for (let a = 0; a < 360; a += 24) {
    let rad1 = rivR + 2;
    let rad2 = rivR + random(10, 22);
    let c = cos(a), s = sin(a);
    brush.set("2B", "#050e1c", 0.85);
    brush.line(rx + c * rad1, ry + s * rad1, rx + c * rad2, ry + s * rad2);
    if (a > 120 && a < 290) {
      brush.set("cpencil", "#9ab2c9", 0.8);
      brush.line(rx + c * (rad1 + 1), ry + s * (rad1 + 1) - 1.2, rx + c * (rad2 - 3), ry + s * (rad2 - 3) - 1.2);
    }
  }

  // Subtle verdigris oxidation halo stained into the faded cotton around the brass
  let verdPts = [];
  for (let a = 0; a < 360; a += 30) {
    let r = rivR + random(2.5, 6.5);
    verdPts.push([rx + cos(a) * r, ry + sin(a) * r]);
  }
  makeContourPoly(verdPts, "#4d8072", 110, 0.25, 0.7);

  // Crisp cast shadow of the raised brass burr washer to the lower-right
  let rivShadowPts = [];
  for (let a = 0; a < 360; a += 20) {
    rivShadowPts.push([rx + 3.2 + cos(a) * (rivR + 0.8), ry + 3.0 + sin(a) * (rivR + 0.8)]);
  }
  makeWashPoly(rivShadowPts, "#03070f", 235);

  // Brass washer base disc (rich antique bronze/brass)
  let rivBasePts = [];
  for (let a = 0; a < 360; a += 18) {
    rivBasePts.push([rx + cos(a) * rivR, ry + sin(a) * rivR]);
  }
  makeWashPoly(rivBasePts, "#735118", 248);

  // Metallic radial shading across the flanged brass washer
  for (let a = 0; a < 360; a += 6) {
    let c = cos(a), s = sin(a);
    // Upper-left quadrant catches warm golden sunlight; lower-right is deep umber bronze
    let isLit = (a >= 135 && a <= 305);
    let col = isLit ? (a > 185 && a < 255 ? "#f0cf78" : "#c79938") : "#3d2808";
    brush.set("pen", col, 1.15);
    brush.line(rx + c * 4.2, ry + s * 4.2, rx + c * (rivR - 0.8), ry + s * (rivR - 0.8));
  }

  // Outer bevel rim & inner stamped groove
  brush.set("rotring", "#241604", 1.1);
  brush.circle(rx, ry, rivR, 0.08);
  brush.circle(rx, ry, 4.6, 0.08);

  // Verdigris patina crust tucked in the shadow crevice of the central post
  brush.set("pen", "#5c9c88", 1.2);
  brush.arc(rx, ry, 5.2, 320, 110);

  // Central peened copper/brass mandrel post
  brush.set("pen", "#8c5820", 2.0);
  brush.circle(rx, ry, 2.5, 0.1);
  brush.set("rotring", "#1f1103", 1.1);
  brush.arc(rx, ry, 2.8, 300, 120);

  // Razor-sharp raking specular highlights on the upper-left brass rim & central post
  brush.set("rotring", "#fffbe6", 1.25);
  brush.arc(rx, ry, rivR - 1.2, 175, 255);
  brush.set("rotring", "#ffffff", 1.4);
  brush.arc(rx, ry, rivR - 1.2, 200, 232);
  brush.line(rx - 2.2, ry - 2.2, rx - 0.8, ry - 2.8);

  // ---------------------------------------------------------------------------
  // 14. INCIDENT 3: LOOSE HANGING THREADS WITH CAST SHADOWS
  // ---------------------------------------------------------------------------
  // Primary loose hanging Sashiko thread snagged from the worn top pocket mouth (x = 532, y = 587)
  // It arches outward from the cloth and hangs down 145px in a crimped catenary curve.
  const snagOrigin = warpPt(532, 587);
  const sx0 = snagOrigin[0];
  const sy0 = snagOrigin[1];

  const threadPts = [
    [sx0, sy0],
    [sx0 - 6, sy0 + 14],
    [sx0 - 2, sy0 + 34],
    [sx0 - 9, sy0 + 58],
    [sx0 - 4, sy0 + 84],
    [sx0 - 11, sy0 + 112],
    [sx0 - 6, sy0 + 136],
    [sx0 - 13, sy0 + 154]
  ];

  // 1. Distinct thin cast shadow of the hanging thread projected onto the pocket below-right
  // Notice how the shadow offset starts at (0,0) right at the snag hole and widens as the thread hangs free!
  let shadowSpline = [];
  for (let i = 0; i < threadPts.length; i++) {
    let t = i / (threadPts.length - 1);
    let loftX = lerp(1.2, 13.5, pow(t, 0.75)) + sin(t * 360) * 1.5;
    let loftY = lerp(1.0, 9.0, pow(t, 0.75));
    shadowSpline.push([threadPts[i][0] + loftX, threadPts[i][1] + loftY, 0.85]);
  }
  brush.set("rotring", "#02060d", 1.05);
  brush.spline(shadowSpline, 0.55);
  brush.set("2B", "#071326", 1.3);
  brush.spline(shadowSpline, 0.55);

  // 2. Tiny dark snag hole where the thread pulled out of the pocket lip
  brush.set("rotring", "#02050a", 1.5);
  brush.line(sx0 - 1.5, sy0 - 1, sx0 + 2, sy0 + 1.5);

  // 3. The hanging white cotton thread itself (with subtle 2-ply kink & bright raking illumination)
  let mainThreadSpline = threadPts.map(pt => [pt[0], pt[1], 1.0]);
  brush.set("pen", "#d6d2c7", 1.15);
  brush.spline(mainThreadSpline, 0.55);

  let hiThreadSpline = threadPts.map((pt, idx) => [
    pt[0] - 0.6 + (idx % 2 === 0 ? 0.4 : -0.4),
    pt[1],
    0.9
  ]);
  brush.set("rotring", "#ffffff", 0.85);
  brush.spline(hiThreadSpline, 0.55);

  // Unraveled frayed twin-ply tip at the very bottom of the hanging thread
  let tip = threadPts[threadPts.length - 1];
  brush.set("rotring", "#f5f2ea", 0.65);
  brush.line(tip[0], tip[1], tip[0] - 3.5, tip[1] + 6.5);
  brush.line(tip[0], tip[1], tip[0] + 2.2, tip[1] + 7.2);

  // Secondary smaller loose thread tail at the lower-left wave patch corner (x = 518, y = 885)
  const snag2 = warpPt(518, 885);
  const thread2Pts = [
    [snag2[0], snag2[1]],
    [snag2[0] + 5, snag2[1] + 15],
    [snag2[0] + 2, snag2[1] + 34],
    [snag2[0] + 7, snag2[1] + 52]
  ];
  let shadow2Spline = thread2Pts.map((pt, i) => [
    pt[0] + lerp(1, 8.5, i / 3),
    pt[1] + lerp(1, 6.0, i / 3),
    0.8
  ]);
  brush.set("rotring", "#030812", 0.95);
  brush.spline(shadow2Spline, 0.5);
  brush.set("pen", "#e6e2d8", 1.0);
  brush.spline(thread2Pts.map(pt => [pt[0], pt[1], 0.95]), 0.5);
  brush.set("rotring", "#ffffff", 0.75);
  brush.spline(thread2Pts.map(pt => [pt[0] - 0.5, pt[1], 0.8]), 0.5);

  // ---------------------------------------------------------------------------
  // 15. FINAL RAKING LIGHTGRAZE & EDGE CRISP PASS
  // ---------------------------------------------------------------------------
  // Crisp raking sunlight catching the left silhouette edge of the hanging apron
  for (let y = 258; y < 1168; y += 10) {
    let b = getApronBounds(y);
    let bNext = getApronBounds(y + 10);
    if (!b.valid || !bNext.valid) continue;
    let beam = getWindowBeam(b.leftX, y);
    brush.set("cpencil", beam > 0.65 ? "#dce6f0" : "#8ea4ba", random(1.0, 1.6));
    brush.line(b.leftX + 1.5, y, bNext.leftX + 1.5, y + 10);

    // Deep core edge along the right shadow silhouette
    brush.set("rotring", "#040a14", 1.15);
    brush.line(b.rightX - 1.5, y, bNext.rightX - 1.5, y + 10);
  }

  noLoop();
}

