// ============================================================================
// CORE DRAWING HELPERS (Safe state management for p5.brush)
// ============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawWashPoly(pts, col, opacity = 235, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  resetBrushState();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function drawWatercolorPoly(pts, col, opacity = 150, bleed = 0.08, tex = 0.35, border = 0.25, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  resetBrushState();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function drawStrokeSpline(pts, brushName, col, weight = 1, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  resetBrushState();
  brush.set(brushName, col, weight);
  brush.spline(pts, curvature);
  resetBrushState();
}

function drawStrokeLine(x1, y1, x2, y2, brushName, col, weight = 1) {
  resetBrushState();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
  resetBrushState();
}

function makeClayEllipse(cx, cy, rx, ry, n = 44, wobble = 2.0, seedOffset = 0, rotDeg = 0) {
  let pts = [];
  let cr = cos(rotDeg);
  let sr = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let nVal = noise(cos(a) * 1.4 + 10 + seedOffset, sin(a) * 1.4 + 10 + seedOffset);
    let harmonic = sin(a * 5 + seedOffset * 37) * 0.35 + cos(a * 9 - seedOffset * 23) * 0.25;
    let dr = (nVal - 0.5) * 2.0 * wobble + harmonic * wobble;
    let lx = (rx + dr) * cos(a);
    let ly = (ry + dr) * sin(a);
    let gx = cx + lx * cr - ly * sr;
    let gy = cy + lx * sr + ly * cr;
    pts.push([gx, gy]);
  }
  return pts;
}

function offsetPoly(pts, dx, dy, scaleX = 1.0, scaleY = 1.0, cx = 0, cy = 0) {
  return pts.map(p => [
    cx + (p[0] - cx) * scaleX + dx,
    cy + (p[1] - cy) * scaleY + dy
  ]);
}

// ============================================================================
// DOUBLED HARD TABLETOP LAMP SHADOW ENGINE
// Lamp A (Primary warm key from upper-left): casts shadow (+36*h, +42*h)
// Lamp B (Secondary cool lamp from upper-right): casts shadow (-24*h, +48*h)
// Overlap Umbra: (+6*h, +30*h)
// ============================================================================

function drawDoubledShadow(pts, h, colA = "#57483B", colB = "#4B4554", colUmbra = "#2E2522", alphaScale = 1.0, curv = 0.25) {
  let dxA = 36 * h;
  let dyA = 42 * h;
  let dxB = -24 * h;
  let dyB = 47 * h;
  let dxU = 6 * h;
  let dyU = 27 * h;

  let ptsA = offsetPoly(pts, dxA, dyA);
  let ptsB = offsetPoly(pts, dxB, dyB);
  let ptsU = offsetPoly(pts, dxU, dyU);

  // Lamp A shadow
  drawWashPoly(ptsA, colA, Math.min(255, Math.round(92 * alphaScale)), curv);
  drawStrokeSpline([...ptsA, ptsA[0]], "clayBlend", colA, 0.85, curv);

  // Lamp B shadow
  drawWashPoly(ptsB, colB, Math.min(255, Math.round(86 * alphaScale)), curv);
  drawStrokeSpline([...ptsB, ptsB[0]], "clayBlend", colB, 0.85, curv);

  // Overlapping deep umbra core
  drawWashPoly(ptsU, colUmbra, Math.min(255, Math.round(140 * alphaScale)), curv);
  drawStrokeSpline([...ptsU, ptsU[0]], "2B", colUmbra, 0.65, curv);
}

// ============================================================================
// LAYER 1: CHUNKY CHECKED TABLECLOTH (SCULPTED GINGHAM SLABS)
// ============================================================================

function drawCheckedTablecloth() {
  // Warm ivory watercolor paper & clay base
  background("#FFF7E5");

  let angle = -10.5;
  let ca = cos(angle);
  let sa = sin(angle);
  let cx = 600;
  let cy = 600;
  let cell = 116;

  function gridToWorld(gx, gy) {
    return [
      cx + gx * ca - gy * sa,
      cy + gx * sa + gy * ca
    ];
  }

  // Draw chunky gingham grid from -8 to +8 in rotated space
  for (let row = -7; row <= 7; row++) {
    for (let col = -7; col <= 7; col++) {
      let x0 = col * cell;
      let y0 = row * cell;
      let x1 = (col + 1) * cell;
      let y1 = (row + 1) * cell;

      let p0 = gridToWorld(x0, y0);
      let p1 = gridToWorld(x1, y0);
      let p2 = gridToWorld(x1, y1);
      let p3 = gridToWorld(x0, y1);

      // Clip check outside canvas bounds with margin
      let minX = Math.min(p0[0], p1[0], p2[0], p3[0]);
      let maxX = Math.max(p0[0], p1[0], p2[0], p3[0]);
      let minY = Math.min(p0[1], p1[1], p2[1], p3[1]);
      let maxY = Math.max(p0[1], p1[1], p2[1], p3[1]);
      if (maxX < -40 || minX > 1240 || maxY < -40 || minY > 1240) continue;

      let isBlueCol = ((col % 2) + 2) % 2 === 1;
      let isBlueRow = ((row % 2) + 2) % 2 === 1;

      let quad = [p0, p1, p2, p3];

      if (isBlueCol && isBlueRow) {
        // Deep saturated cobalt-navy intersection check
        drawWashPoly(quad, "#0E3382", 242, 0.05);
        // Subtle diagonal twill hatch in dark ultramarine
        resetBrushState();
        brush.hatchStyle("2B", "#071C4F", 0.75);
        brush.hatch(9, angle + 42, { rand: 0.06 });
        brush.beginShape(0);
        quad.forEach(p => brush.vertex(p[0], p[1]));
        brush.endShape(true);
        resetBrushState();
      } else if (isBlueCol || isBlueRow) {
        // Mid cerulean-cobalt check with woven texture
        let baseCol = isBlueCol ? "#246EE0" : "#2E79EB";
        drawWashPoly(quad, baseCol, 228, 0.05);
        let stripeAngle = isBlueCol ? angle + 90 : angle;
        resetBrushState();
        brush.hatchStyle("cpencil", "#1349A8", 0.65);
        brush.hatch(8.5, stripeAngle, { rand: 0.05 });
        brush.beginShape(0);
        quad.forEach(p => brush.vertex(p[0], p[1]));
        brush.endShape(true);
        resetBrushState();
      } else {
        // Warm cream plasticine check with subtle clay sheen and thin red/yellow toy pin-checks
        drawWashPoly(quad, "#FDF3DC", 220, 0.05);
        // Subtle bevel highlight on top-left edge of clay tile
        drawStrokeLine(p0[0], p0[1], p1[0], p1[1], "satin", "#FFFFFF", 0.7);
        drawStrokeLine(p0[0], p0[1], p3[0], p3[1], "satin", "#FFFFFF", 0.6);

        // Crisp cadmium red & yellow woven pin-stripe through center of cream check
        let midTop = gridToWorld((x0 + x1) * 0.5, y0);
        let midBot = gridToWorld((x0 + x1) * 0.5, y1);
        let midLeft = gridToWorld(x0, (y0 + y1) * 0.5);
        let midRight = gridToWorld(x1, (y0 + y1) * 0.5);
        drawStrokeLine(midTop[0], midTop[1], midBot[0], midBot[1], "cpencil", "#FF3B1F", 0.65);
        drawStrokeLine(midLeft[0], midLeft[1], midRight[0], midRight[1], "cpencil", "#FFAE00", 0.65);
      }

      // Sculpted seam groove between tablecloth clay tiles
      drawStrokeLine(p0[0], p0[1], p1[0], p1[1], "2H", "#1A3366", 0.45);
      drawStrokeLine(p0[0], p0[1], p3[0], p3[1], "2H", "#1A3366", 0.45);

      // Smeared clay joints at random tile corners
      if (random() < 0.45) {
        let smCol = (isBlueCol || isBlueRow) ? "#1F62CC" : "#F7EBD0";
        let ang = angle + random(-25, 25);
        let sx = p0[0] + random(-12, 12);
        let sy = p0[1] + random(-12, 12);
        drawStrokeLine(
          sx, sy,
          sx + cos(ang) * random(10, 22),
          sy + sin(ang) * random(10, 22),
          "smear", smCol, 0.65
        );
      }
    }
  }
}

// ============================================================================
// LAYER 2: THE SCULPTED PLASTICINE PLATE & ITS DOUBLED TABLE SHADOWS
// ============================================================================

function drawPlasticinePlate() {
  let cx = 602;
  let cy = 602;
  let rx = 472;
  let ry = 420;

  let outerPts = makeClayEllipse(cx, cy, rx, ry, 64, 3.2, 1.1, -3);

  // Doubled cast shadow of the heavy plate across the checked tablecloth
  drawDoubledShadow(outerPts, 1.35, "#0E1D42", "#1E1438", "#060B1E", 1.12, 0.25);

  // Outer rim base: thick creamy-white plasticine
  drawWashPoly(outerPts, "#F5EFE2", 252, 0.25);

  // Shaded lower-right crescent of the outer rim
  let rimShadePts = [];
  for (let a = -25; a <= 155; a += 6) {
    let radX = rx * cos(a);
    let radY = ry * sin(a);
    rimShadePts.push([cx + radX, cy + radY]);
  }
  for (let a = 155; a >= -25; a -= 6) {
    let radX = (rx - 44) * cos(a);
    let radY = (ry - 40) * sin(a);
    rimShadePts.push([cx + radX, cy + radY]);
  }
  drawWashPoly(rimShadePts, "#DDD3C0", 190, 0.2);

  // Luminous upper-left rim arc catching both studio lamps
  let rimLightPts = [];
  for (let a = 160; a <= 335; a += 6) {
    let radX = (rx - 4) * cos(a);
    let radY = (ry - 4) * sin(a);
    rimLightPts.push([cx + radX, cy + radY]);
  }
  drawStrokeSpline(rimLightPts, "satin", "#FFFFFF", 1.8, 0.4);

  // Toy cobalt-blue & cadmium-yellow inlaid clay stripe around the plate rim
  let blueRingOuter = makeClayEllipse(cx, cy, rx * 0.915, ry * 0.915, 64, 2.4, 2.3, -3);
  let blueRingInner = makeClayEllipse(cx, cy, rx * 0.875, ry * 0.875, 64, 2.4, 2.5, -3);
  drawStrokeSpline([...blueRingOuter, blueRingOuter[0]], "gouache", "#1650B8", 1.05, 0.35);
  drawStrokeSpline([...blueRingInner, blueRingInner[0]], "cpencil", "#0B2E75", 0.9, 0.35);

  // Warm cadmium-yellow inner pinstripe on plate rim
  let yellowRing = makeClayEllipse(cx, cy, rx * 0.842, ry * 0.842, 60, 2.0, 3.1, -3);
  drawStrokeSpline([...yellowRing, yellowRing[0]], "gouache", "#FFB700", 0.52, 0.35);

  // Smeared colour seams where the blue & yellow clay strips were thumb-pressed into the white rim
  for (let i = 0; i < 42; i++) {
    let a = random(360);
    let rMid = 0.91 * (1 + random(-0.02, 0.02));
    let sx = cx + rx * rMid * cos(a);
    let sy = cy + ry * rMid * sin(a);
    let smAng = a + random(-35, 35);
    let isBlueSmear = random() < 0.6;
    let col = isBlueSmear ? "#2968D9" : "#F5EFE2";
    drawStrokeLine(
      sx, sy,
      sx + cos(smAng) * random(9, 19),
      sy + sin(smAng) * random(9, 19),
      "smear", col, random(0.45, 0.85)
    );
  }

  // Inner recessed well of the plate
  let wellRx = rx * 0.755;
  let wellRy = ry * 0.755;
  let wellPts = makeClayEllipse(cx, cy + 4, wellRx, wellRy, 60, 2.2, 4.2, -3);

  // Doubled rim shadow cast inside the upper well from Lamp A and Lamp B
  let wellShadowA = offsetPoly(wellPts, 18, 22);
  let wellShadowB = offsetPoly(wellPts, -14, 25);
  drawWashPoly(wellPts, "#CFC4B0", 230, 0.25); // Shadow base in well
  drawWashPoly(wellShadowA, "#DED5C3", 190, 0.25);
  drawWashPoly(wellShadowB, "#E8E0D0", 210, 0.25);

  // Lit center-bottom floor of the plate well
  let wellFloorPts = makeClayEllipse(cx + 4, cy + 16, wellRx * 0.93, wellRy * 0.91, 56, 2.0, 5.0, -3);
  drawWashPoly(wellFloorPts, "#F4EEE0", 235, 0.25);

  // Crisp pencil contour along the inner well ridge & outer plate rim
  drawStrokeSpline([...wellPts, wellPts[0]], "2B", "#9E917B", 0.75, 0.35);
  drawStrokeSpline([...outerPts, outerPts[0]], "2B", "#6E6252", 0.95, 0.35);

  // Satin sheen reflections on the lower-right sloped rim wall
  for (let k = 0; k < 2; k++) {
    let startA = k === 0 ? 22 : 58;
    let endA = k === 0 ? 48 : 78;
    let sheenPts = [];
    for (let a = startA; a <= endA; a += 4) {
      sheenPts.push([cx + rx * 0.81 * cos(a), cy + ry * 0.81 * sin(a)]);
    }
    drawStrokeSpline(sheenPts, "satin", "#FFFFFF", 1.5, 0.4);
  }
}

// ============================================================================
// ITEM 1: SCULPTED PLASTICINE BUTTON MUSHROOMS (UPPER CENTER-LEFT)
// ============================================================================

function drawPlasticineMushrooms() {
  let mushrooms = [
    { x: 545, y: 340, rx: 46, ry: 38, rot: -15, upturned: true },
    { x: 625, y: 325, rx: 48, ry: 40, rot: 18, upturned: false },
    { x: 480, y: 382, rx: 42, ry: 35, rot: -28, upturned: false }
  ];

  // First pass: cast doubled shadows onto the plate
  for (let m of mushrooms) {
    let capPts = makeClayEllipse(m.x, m.y, m.rx, m.ry, 32, 1.8, m.x * 0.1, m.rot);
    drawDoubledShadow(capPts, 0.48, "#948470", "#877B7D", "#5E5044", 0.95, 0.3);
  }

  // Second pass: sculpt each mushroom
  for (let m of mushrooms) {
    let capPts = makeClayEllipse(m.x, m.y, m.rx, m.ry, 32, 1.8, m.x * 0.1, m.rot);

    if (m.upturned) {
      // Upturned mushroom cap showing dark gills and cut stalk
      drawWashPoly(capPts, "#917D69", 245, 0.3);
      let gillPts = makeClayEllipse(m.x + 2, m.y + 2, m.rx * 0.76, m.ry * 0.74, 28, 1.2, m.y, m.rot);
      drawWashPoly(gillPts, "#3D2618", 248, 0.25);

      // Knife-scored radial gill slits
      for (let i = 0; i < 28; i++) {
        let a = (i / 28) * 360;
        let rIn = 12;
        let rOut = m.rx * 0.74;
        let x1 = m.x + 2 + rIn * cos(a);
        let y1 = m.y + 2 + (rIn * 0.85) * sin(a);
        let x2 = m.x + 2 + rOut * cos(a);
        let y2 = m.y + 2 + (rOut * 0.85) * sin(a);
        drawStrokeLine(x1, y1, x2, y2, "rotring", "#1F1008", 0.65);
        if (i % 2 === 0) {
          drawStrokeLine(x1 + 1, y1, x2 + 1, y2, "cpencil", "#6E4E3A", 0.45);
        }
      }

      // Cut plasticine stem stub in the center
      let stemPts = makeClayEllipse(m.x + 5, m.y - 4, 18, 15, 22, 1.1, 9.2, m.rot);
      drawDoubledShadow(stemPts, 0.22, "#24130B", "#1F1214", "#120804", 0.9, 0.25);
      drawWashPoly(stemPts, "#E6D2B5", 250, 0.25);
      drawStrokeSpline([...stemPts, stemPts[0]], "2B", "#6B533B", 0.65, 0.3);
      drawStrokeLine(m.x, m.y - 9, m.x + 9, m.y - 6, "satin", "#FFFDF7", 0.9);
    } else {
      // Domed mushroom cap with faceted thumb marks
      drawWashPoly(capPts, "#7D6A56", 248, 0.3);
      let shadePts = makeClayEllipse(m.x + 7, m.y + 7, m.rx * 0.82, m.ry * 0.78, 26, 1.5, m.x, m.rot);
      drawWashPoly(shadePts, "#5C4B3B", 185, 0.3);
      let midPts = makeClayEllipse(m.x - 5, m.y - 5, m.rx * 0.72, m.ry * 0.68, 26, 1.4, m.y, m.rot);
      drawWashPoly(midPts, "#998570", 215, 0.3);

      // Dual studio lamp satin highlights
      let hlA = makeClayEllipse(m.x - 13, m.y - 11, m.rx * 0.32, m.ry * 0.24, 16, 0.6, 1.0, m.rot - 10);
      let hlB = makeClayEllipse(m.x + 8, m.y - 13, m.rx * 0.18, m.ry * 0.14, 14, 0.4, 2.0, m.rot + 15);
      drawWashPoly(hlA, "#C9B8A3", 190, 0.3);
      drawWashPoly(hlB, "#D9C9B4", 180, 0.3);
      drawStrokeLine(m.x - 17, m.y - 12, m.x - 8, m.y - 14, "satin", "#FFF8EB", 1.1);
      drawStrokeLine(m.x + 5, m.y - 14, m.x + 12, m.y - 12, "satin", "#FFFFFF", 0.85);
    }

    // Crisp pencil rim & smeared clay seams
    drawStrokeSpline([...capPts, capPts[0]], "2B", "#3B2C20", 0.8, 0.3);
  }
}

// ============================================================================
// ITEM 2: THICK PLASTICINE TOAST SCORED WITH MODELLING-TOOL MARKS & BUTTER
// ============================================================================

function drawScoredToastSlice(topPts, thickness, seedVal, hasButter) {
  // Construct 3D extruded bottom contour for thick slab of plasticine bread
  let botPts = offsetPoly(topPts, 10, thickness);

  // Doubled cast shadow onto the plate
  drawDoubledShadow(botPts, 0.55, "#8C7B65", "#7D7378", "#4D3E32", 1.0, 0.2);

  // Draw roasted chestnut-brown crust coil along the 3D side wall
  let crustWall = [
    topPts[0], topPts[1], topPts[2],
    botPts[2], botPts[1], botPts[0]
  ];
  drawWashPoly(botPts, "#7A3611", 252, 0.22);
  drawWashPoly(crustWall, "#8F4116", 245, 0.2);

  // Outer crust rim wrapped around top face
  let crustRimPts = offsetPoly(topPts, 0, 0, 1.04, 1.04, 360, 500);
  drawWashPoly(crustRimPts, "#9E491B", 248, 0.22);

  // Shaded side of the crust coil
  drawStrokeSpline([crustRimPts[1], crustRimPts[2], crustRimPts[0]], "gouache", "#592208", 0.85, 0.25);
  // Satin highlight along upper-left crust roll
  drawStrokeSpline([crustRimPts[2], crustRimPts[0], crustRimPts[1]], "satin", "#D98A4E", 1.1, 0.25);

  // Main bread-tan plasticine crumb face
  drawWashPoly(topPts, "#EDA958", 250, 0.2);

  // Warm toasted amber-ochre watercolour patch in the center of the slice
  let cx = 0, cy = 0;
  topPts.forEach(p => { cx += p[0]; cy += p[1]; });
  cx /= topPts.length;
  cy /= topPts.length;

  let toastPatch1 = offsetPoly(topPts, 0, 0, 0.78, 0.78, cx, cy);
  let toastPatch2 = offsetPoly(topPts, 4, 4, 0.54, 0.54, cx, cy);
  drawWatercolorPoly(toastPatch1, "#D6822B", 160, 0.12, 0.45, 0.3, 0.25);
  drawWatercolorPoly(toastPatch2, "#B86214", 130, 0.15, 0.5, 0.35, 0.25);

  // Smeared colour seams where the dark crust coil joins the bread-tan crumb
  for (let s = 0; s < topPts.length; s++) {
    let pA = topPts[s];
    let pB = topPts[(s + 1) % topPts.length];
    for (let t = 0.08; t < 0.95; t += 0.09) {
      let px = lerp(pA[0], pB[0], t);
      let py = lerp(pA[1], pB[1], t);
      let dirX = (cx - px);
      let dirY = (cy - py);
      let len = sqrt(dirX * dirX + dirY * dirY) || 1;
      dirX /= len;
      dirY /= len;
      let smLen = random(9, 20);
      let isDarkToLight = random() < 0.55;
      let smCol = isDarkToLight ? "#8C3D14" : "#F5BE73";
      drawStrokeLine(
        px - dirX * 3, py - dirY * 3,
        px + dirX * smLen + random(-4, 4), py + dirY * smLen + random(-4, 4),
        "smear", smCol, random(0.45, 0.8)
      );
    }
  }

  // Point-in-triangle check for scoring marks inside the toast face
  function inTriangle(px, py, A, B, C) {
    let v0x = C[0] - A[0], v0y = C[1] - A[1];
    let v1x = B[0] - A[0], v1y = B[1] - A[1];
    let v2x = px - A[0], v2y = py - A[1];
    let dot00 = v0x * v0x + v0y * v0y;
    let dot01 = v0x * v1x + v0y * v1y;
    let dot02 = v0x * v2x + v0y * v2y;
    let dot11 = v1x * v1x + v1y * v1y;
    let dot12 = v1x * v2x + v1y * v2y;
    let invDenom = 1 / (dot00 * dot11 - dot01 * dot01);
    let u = (dot11 * dot02 - dot01 * dot12) * invDenom;
    let v = (dot00 * dot12 - dot01 * dot02) * invDenom;
    return (u >= 0.06) && (v >= 0.06) && (u + v <= 0.92);
  }

  // OBSESSIVE MODELLING-TOOL SCORE MARKS ACROSS THE TOAST SURFACE
  // Parallel diagonal gouge grooves + cross-scored chisel indentations
  let minX = Math.min(topPts[0][0], topPts[1][0], topPts[2][0]);
  let maxX = Math.max(topPts[0][0], topPts[1][0], topPts[2][0]);
  let minY = Math.min(topPts[0][1], topPts[1][1], topPts[2][1]);
  let maxY = Math.max(topPts[0][1], topPts[1][1], topPts[2][1]);

  for (let i = 0; i < 165; i++) {
    let tx = random(minX, maxX);
    let ty = random(minY, maxY);
    if (!inTriangle(tx, ty, topPts[0], topPts[1], topPts[2])) continue;

    // Two primary scoring directions from a wooden modelling tool
    let baseAng = (i % 3 === 0) ? -32 : 48;
    let ang = baseAng + random(-12, 12);
    let markLen = random(7, 17);
    let x2 = tx + cos(ang) * markLen;
    let y2 = ty + sin(ang) * markLen;

    // Deep recessed tool groove
    let distCenter = dist(tx, ty, cx, cy);
    let grooveCol = distCenter < 55 ? "#5C2406" : "#823B0E";
    drawStrokeLine(tx, ty, x2, y2, "rotring", grooveCol, random(0.55, 0.9));

    // Displaced clay ridge highlight immediately alongside the tool gouge
    let nx = -sin(ang) * 1.8;
    let ny = cos(ang) * 1.8;
    drawStrokeLine(tx + nx, ty + ny, x2 + nx, y2 + ny, "cpencil", "#FFE299", random(0.5, 0.8));
  }

  // Short chisel-tool jab marks (crumb pores)
  for (let i = 0; i < 65; i++) {
    let tx = random(minX, maxX);
    let ty = random(minY, maxY);
    if (!inTriangle(tx, ty, topPts[0], topPts[1], topPts[2])) continue;
    drawStrokeLine(tx, ty, tx + random(3, 6), ty + random(-2, 3), "chisel", "#6B2B07", 0.55);
    drawStrokeLine(tx - 1, ty - 1.5, tx + 3, ty - 1, "cpencil", "#FFF0BD", 0.5);
  }

  // Crisp graphite contour around the crust & crumb boundary
  drawStrokeSpline([...crustRimPts, crustRimPts[0]], "2B", "#3B1503", 0.85, 0.22);
  drawStrokeSpline([...topPts, topPts[0]], "2B", "#6E2E0B", 0.7, 0.2);

  // Sculpted pat of cadmium-yellow plasticine butter smeared onto the top slice
  if (hasButter) {
    let bx = cx - 8;
    let by = cy - 6;

    // Thumb-smeared yellow butter streaks radiating from the pat
    for (let k = 0; k < 14; k++) {
      let sa = random(360);
      let r1 = random(16, 26);
      let r2 = random(38, 62);
      drawStrokeLine(
        bx + cos(sa) * r1, by + sin(sa) * r1,
        bx + cos(sa) * r2, by + sin(sa) * r2,
        "smear", (k % 2 === 0) ? "#FFD900" : "#FFF078", random(0.8, 1.35)
      );
    }

    let butterPts = [
      [bx - 28, by - 22],
      [bx + 24, by - 28],
      [bx + 32, by + 18],
      [bx - 20, by + 26]
    ];
    drawDoubledShadow(butterPts, 0.18, "#8C4808", "#7A3E12", "#4F2302", 0.85, 0.3);
    drawWashPoly(butterPts, "#FFD000", 248, 0.3);

    let butterTop = offsetPoly(butterPts, -3, -3, 0.82, 0.82, bx, by);
    drawWashPoly(butterTop, "#FFEA47", 240, 0.3);

    // Tool-pressed butter dimples & twin studio lamp catchlights
    drawStrokeSpline([...butterPts, butterPts[0]], "2B", "#B57800", 0.65, 0.3);
    drawStrokeLine(bx - 16, by - 14, bx + 8, by - 18, "satin", "#FFFFEB", 1.3);
    drawStrokeLine(bx + 12, by - 12, bx + 18, by - 4, "satin", "#FFFFFF", 1.0);
  }
}

function drawPlasticineToast() {
  // Lower toast triangle (tucked under upper slice on the left side of the plate)
  let slice1 = [
    [205, 455],
    [475, 325],
    [355, 650]
  ];
  drawScoredToastSlice(slice1, 22, 11.4, false);

  // Upper toast triangle with smeared cadmium-yellow butter pat
  let slice2 = [
    [258, 412],
    [548, 385],
    [342, 682]
  ];
  drawScoredToastSlice(slice2, 24, 27.8, true);
}

// ============================================================================
// ITEM 3: STREAKY BACON ROLLED INTO STRIPES (UPPER RIGHT)
// ============================================================================

function drawBaconRasher(startX, startY, endX, endY, waveAmp, seedVal) {
  let steps = 38;
  let dx = endX - startX;
  let dy = endY - startY;
  let len = sqrt(dx * dx + dy * dy);
  let ux = dx / len;
  let uy = dy / len;
  let nx = -uy;
  let ny = ux;

  // Build spine of wavy rolled plasticine ribbon
  let spine = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let wave = sin(t * 540 + seedVal) * waveAmp + cos(t * 270 - seedVal) * (waveAmp * 0.4);
    // Arch lift in 3D (pushes rasher upward-left on crests)
    let archLift = Math.max(0, sin(t * 540 + seedVal)) * 12;
    let px = startX + dx * t + nx * wave - archLift * 0.4;
    let py = startY + dy * t + ny * wave - archLift * 0.85;
    spine.push({ x: px, y: py, t: t, arch: archLift, wave: wave });
  }

  let halfW = 34;
  let outlinePts = [];
  for (let i = 0; i <= steps; i++) {
    let wScale = 1.0 - 0.18 * Math.pow((spine[i].t - 0.5) * 2, 2);
    outlinePts.push([spine[i].x + nx * halfW * wScale, spine[i].y + ny * halfW * wScale]);
  }
  for (let i = steps; i >= 0; i--) {
    let wScale = 1.0 - 0.18 * Math.pow((spine[i].t - 0.5) * 2, 2);
    outlinePts.push([spine[i].x - nx * halfW * wScale, spine[i].y - ny * halfW * wScale]);
  }

  // Doubled cast shadow of the undulating bacon ribbon
  drawDoubledShadow(outlinePts, 0.46, "#877562", "#786E78", "#47382B", 0.98, 0.25);

  // Base rasher slab in deep cured crimson-mahogany
  drawWashPoly(outlinePts, "#9E2126", 250, 0.25);

  // Rolled streaky stripes: alternating bands of deep crimson, vivid SALMON, and creamy fat!
  // Each stripe is a polygon band running the full length of the rasher
  let bands = [
    { s0: -1.00, s1: -0.78, col: "#7D161A" }, // Dark crispy mahogany edge
    { s0: -0.78, s1: -0.42, col: "#FF6B63" }, // Vivid saturated SALMON meat stripe
    { s0: -0.42, s1: -0.12, col: "#FFEBC2" }, // Rolled creamy-yellow fat stripe
    { s0: -0.12, s1:  0.24, col: "#B8252B" }, // Rich lean red-crimson stripe
    { s0:  0.24, s1:  0.58, col: "#FF7B70" }, // Bright SALMON pink stripe
    { s0:  0.58, s1:  0.84, col: "#FAE0AC" }, // Second streaky cream fat stripe
    { s0:  0.84, s1:  1.00, col: "#8C271E" }  // Browned outer rind
  ];

  for (let b of bands) {
    let bandPts = [];
    for (let i = 0; i <= steps; i++) {
      let wScale = 1.0 - 0.18 * Math.pow((spine[i].t - 0.5) * 2, 2);
      let pinch = sin(spine[i].t * 720 + b.s0 * 90) * 2.2;
      let off = (b.s0 * halfW + pinch) * wScale;
      bandPts.push([spine[i].x + nx * off, spine[i].y + ny * off]);
    }
    for (let i = steps; i >= 0; i--) {
      let wScale = 1.0 - 0.18 * Math.pow((spine[i].t - 0.5) * 2, 2);
      let pinch = sin(spine[i].t * 720 + b.s1 * 90) * 2.2;
      let off = (b.s1 * halfW + pinch) * wScale;
      bandPts.push([spine[i].x + nx * off, spine[i].y + ny * off]);
    }
    drawWashPoly(bandPts, b.col, 245, 0.2);
  }

  // Smeared colour seams along the boundaries between salmon, crimson, and cream stripes
  for (let b of bands) {
    for (let i = 2; i < steps - 2; i += 2) {
      let wScale = 1.0 - 0.18 * Math.pow((spine[i].t - 0.5) * 2, 2);
      let off = b.s1 * halfW * wScale;
      let sx = spine[i].x + nx * off;
      let sy = spine[i].y + ny * off;
      let smAng = atan2(dy, dx) + random(-35, 35);
      let smLen = random(10, 22);
      drawStrokeLine(
        sx, sy,
        sx + cos(smAng) * smLen,
        sy + sin(smAng) * smLen,
        "smear", b.col, random(0.45, 0.75)
      );
    }
  }

  // 3D wave trough shadows & crest satin highlights from the twin tabletop lamps
  for (let i = 3; i < steps - 2; i++) {
    let wScale = 1.0 - 0.18 * Math.pow((spine[i].t - 0.5) * 2, 2);
    let pTop = [spine[i].x - nx * halfW * 0.85 * wScale, spine[i].y - ny * halfW * 0.85 * wScale];
    let pBot = [spine[i].x + nx * halfW * 0.85 * wScale, spine[i].y + ny * halfW * 0.85 * wScale];

    let wavePhase = sin(spine[i].t * 540 + seedVal);
    if (wavePhase > 0.55) {
      // Crest catching studio lamps
      drawStrokeLine(pTop[0], pTop[1], pBot[0], pBot[1], "satin", "#FFFDF7", 1.35);
    } else if (wavePhase < -0.55) {
      // Deep trough shadow
      drawStrokeLine(pTop[0], pTop[1], pBot[0], pBot[1], "clayBlend", "#590E12", 1.25);
    }
  }

  // Crisp pencil definition around the rolled rasher and stripe seams
  drawStrokeSpline([...outlinePts, outlinePts[0]], "2B", "#4A0B0E", 0.8, 0.25);
}

function drawPlasticineBacon() {
  drawBaconRasher(595, 355, 915, 455, 16, 15);
  drawBaconRasher(570, 425, 895, 535, 18, 125);
}

// ============================================================================
// ITEM 4: PLUMP SCULPTED PLASTICINE SAUSAGES / BANGERS (RIGHT / LOWER-RIGHT)
// ============================================================================

function drawSingleSausage(p0, p1, p2, radius, seedVal) {
  let steps = 32;
  let spine = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let it = 1 - t;
    let x = it * it * p0[0] + 2 * it * t * p1[0] + t * t * p2[0];
    let y = it * it * p0[1] + 2 * it * t * p1[1] + t * t * p2[1];
    let tx = 2 * it * (p1[0] - p0[0]) + 2 * t * (p2[0] - p1[0]);
    let ty = 2 * it * (p1[1] - p0[1]) + 2 * t * (p2[1] - p1[1]);
    let tLen = sqrt(tx * tx + ty * ty) || 1;
    spine.push({
      x: x, y: y, t: t,
      ux: tx / tLen, uy: ty / tLen,
      nx: -ty / tLen, ny: tx / tLen
    });
  }

  let bodyPts = [];
  for (let i = 0; i <= steps; i++) {
    let profile = Math.pow(sin(spine[i].t * 180), 0.38);
    let wob = (noise(i * 0.25 + seedVal) - 0.5) * 3.5;
    let r = radius * profile + wob;
    bodyPts.push([spine[i].x + spine[i].nx * r, spine[i].y + spine[i].ny * r]);
  }
  for (let i = steps; i >= 0; i--) {
    let profile = Math.pow(sin(spine[i].t * 180), 0.38);
    let wob = (noise(i * 0.25 + seedVal + 50) - 0.5) * 3.5;
    let r = radius * profile + wob;
    bodyPts.push([spine[i].x - spine[i].nx * r, spine[i].y - spine[i].ny * r]);
  }

  // Doubled cast shadow of the plump cylindrical sausage
  drawDoubledShadow(bodyPts, 0.65, "#87735E", "#756B75", "#423124", 1.05, 0.25);

  // Rich roasted terracotta-brown base wash
  drawWashPoly(bodyPts, "#9E4220", 252, 0.25);

  // Shaded underside of cylinder
  let shadePts = [];
  for (let i = 2; i <= steps - 2; i++) {
    let profile = Math.pow(sin(spine[i].t * 180), 0.38);
    let r = radius * profile;
    shadePts.push([spine[i].x + spine[i].nx * r * 0.15, spine[i].y + spine[i].ny * r * 0.15]);
  }
  for (let i = steps - 2; i >= 2; i--) {
    let profile = Math.pow(sin(spine[i].t * 180), 0.38);
    let r = radius * profile * 0.96;
    shadePts.push([spine[i].x + spine[i].nx * r, spine[i].y + spine[i].ny * r]);
  }
  drawWashPoly(shadePts, "#66210B", 210, 0.25);

  // Warm midtone salmon-terracotta upper belly
  let midPts = [];
  for (let i = 2; i <= steps - 2; i++) {
    let profile = Math.pow(sin(spine[i].t * 180), 0.38);
    let r = radius * profile;
    midPts.push([spine[i].x - spine[i].nx * r * 0.85, spine[i].y - spine[i].ny * r * 0.85]);
  }
  for (let i = steps - 2; i >= 2; i--) {
    let profile = Math.pow(sin(spine[i].t * 180), 0.38);
    let r = radius * profile * 0.1;
    midPts.push([spine[i].x + spine[i].nx * r, spine[i].y + spine[i].ny * r]);
  }
  drawWashPoly(midPts, "#BD5530", 215, 0.25);

  // Smeared grill-char patches across the sausage skin
  for (let c = 0; c < 4; c++) {
    let idx = Math.floor(map(c, 0, 3, 6, steps - 6));
    let s = spine[idx];
    let charPts = makeClayEllipse(
      s.x - s.nx * radius * 0.15,
      s.y - s.ny * radius * 0.15,
      14, 24, 16, 2.2, seedVal + c * 7,
      atan2(s.ny, s.nx)
    );
    drawWashPoly(charPts, "#421305", 195, 0.3);
    drawStrokeLine(
      s.x - s.nx * 18, s.y - s.ny * 18,
      s.x + s.nx * 14, s.y + s.ny * 14,
      "smear", "#2E0B02", 0.9
    );
  }

  // Embedded flecks of pale fat and dark herb clay pellets inside the sausage
  for (let f = 0; f < 55; f++) {
    let idx = Math.floor(random(3, steps - 3));
    let s = spine[idx];
    let off = random(-0.78, 0.78) * radius * Math.pow(sin(s.t * 180), 0.38);
    let fx = s.x + s.nx * off + random(-4, 4);
    let fy = s.y + s.ny * off + random(-4, 4);
    let isLightFleck = random() < 0.58;
    let fCol = isLightFleck ? "#F2C49B" : "#3B1206";
    drawStrokeLine(fx, fy, fx + random(2, 4.5), fy + random(-2, 3), "gouache", fCol, 0.22);
  }

  // Dual tabletop lamp satin highlight bands running along the upper cylinder ridge
  let hlBandA = [];
  let hlBandB = [];
  for (let i = 4; i <= steps - 4; i++) {
    let profile = Math.pow(sin(spine[i].t * 180), 0.38);
    let r = radius * profile;
    hlBandA.push([spine[i].x - spine[i].nx * r * 0.52, spine[i].y - spine[i].ny * r * 0.52]);
    hlBandB.push([spine[i].x - spine[i].nx * r * 0.28, spine[i].y - spine[i].ny * r * 0.28]);
  }
  drawStrokeSpline(hlBandA, "satin", "#FFDFC2", 1.55, 0.4);
  drawStrokeSpline(hlBandB, "satin", "#FFF7EB", 0.95, 0.4);

  // Pinched/twisted plasticine knots at both ends of the sausage
  for (let endIdx of [0, steps]) {
    let s = spine[endIdx];
    let dir = endIdx === 0 ? -1 : 1;
    for (let k = -2; k <= 2; k++) {
      let ang = atan2(s.uy * dir, s.ux * dir) + k * 24;
      drawStrokeLine(
        s.x, s.y,
        s.x - cos(ang) * 16, s.y - sin(ang) * 16,
        "rotring", "#330D03", 0.7
      );
    }
  }

  drawStrokeSpline([...bodyPts, bodyPts[0]], "2B", "#3B1105", 0.85, 0.25);
}

function drawPlasticineSausages() {
  drawSingleSausage([705, 495], [855, 520], [975, 645], 39, 101);
