}

// ============================================================================
// ITEM 5: BAKED BEANS AS LUMPY PELLETS IN TOMATO SAUCE (LOWER-RIGHT LAGOON)
// ============================================================================

function drawPlasticineBeans() {
  // Thick scalloped puddle of saturated tomato-orange sauce on the plate well
  let sauceCenter = [625, 735];
  let saucePts = [];
  let nSauce = 48;
  for (let i = 0; i < nSauce; i++) {
    let a = (i / nSauce) * 360;
    let lobe = sin(a * 4 + 25) * 18 + cos(a * 7 - 40) * 11 + sin(a * 11) * 6;
    let rx = 175 + lobe;
    let ry = 148 + lobe * 0.85;
    // Flatten slightly against the sausages on the upper-right
    if (a > -45 && a < 45) rx *= 0.86;
    saucePts.push([
      sauceCenter[0] + rx * cos(a - 12),
      sauceCenter[1] + ry * sin(a - 12)
    ]);
  }

  // Sauce lip casts a subtle doubled shadow on the plate well
  drawDoubledShadow(saucePts, 0.14, "#947D64", "#857678", "#573B26", 0.85, 0.3);

  // Vivid tomato-orange base wash for the sauce pool
  drawWashPoly(saucePts, "#E33714", 248, 0.3);
  let innerSauce = offsetPoly(saucePts, -3, -3, 0.9, 0.9, sauceCenter[0], sauceCenter[1]);
  drawWatercolorPoly(innerSauce, "#FF5429", 170, 0.1, 0.35, 0.25, 0.3);

  // Satin meniscus highlight along the upper-left rolled edge of the sauce puddle
  drawStrokeSpline(saucePts.slice(18, 38), "satin", "#FFA382", 1.25, 0.35);
  drawStrokeSpline([...saucePts, saucePts[0]], "2B", "#8C1A05", 0.7, 0.3);

  // Generate 54 lumpy hand-rolled plasticine bean pellets packed in the sauce pool
  let beans = [];
  let ringRadii = [
    { r: 0, count: 1 },
    { r: 30, count: 6 },
    { r: 62, count: 12 },
    { r: 94, count: 16 },
    { r: 126, count: 19 }
  ];

  let beanIdx = 0;
  for (let ring of ringRadii) {
    for (let k = 0; k < ring.count; k++) {
      let a = (k / ring.count) * 360 + ring.r * 0.7 + random(-10, 10);
      let bx = sauceCenter[0] + ring.r * 1.08 * cos(a) + random(-7, 7);
      let by = sauceCenter[1] + ring.r * 0.88 * sin(a) + random(-7, 7);
      beans.push({
        x: bx,
        y: by,
        rx: random(17.5, 22.5),
        ry: random(13.0, 16.5),
        rot: random(-65, 65),
        seed: beanIdx * 3.7,
        hueVar: beanIdx % 4
      });
      beanIdx++;
    }
  }

  // Sort beans top-to-bottom for natural 3D overlapping
  beans.sort((a, b) => a.y - b.y);

  let beanBaseCols = ["#F24918", "#FF5B26", "#E0380E", "#FA6832"];

  for (let b of beans) {
    // Lumpy pellet contour (noticeable high-frequency wobble so it looks rolled between fingers)
    let bPts = makeClayEllipse(b.x, b.y, b.rx, b.ry, 18, 2.3, b.seed, b.rot);

    // Doubled shadow cast by each lumpy bean pellet onto the sauce & neighboring beans
    let shA = offsetPoly(bPts, 6, 7.5);
    let shB = offsetPoly(bPts, -4.5, 8.5);
    let shU = offsetPoly(bPts, 1, 5);
    drawWashPoly(shA, "#8F1804", 130, 0.3);
    drawWashPoly(shB, "#78131A", 120, 0.3);
    drawWashPoly(shU, "#4F0802", 165, 0.3);

    // Opaque base pellet in vivid tomato/cadmium orange-red
    let baseCol = beanBaseCols[b.hueVar];
    drawWashPoly(bPts, baseCol, 252, 0.32);

    // Shaded bottom-right belly of the pellet
    let shadePts = makeClayEllipse(b.x + 3.5, b.y + 3.5, b.rx * 0.72, b.ry * 0.68, 14, 1.4, b.seed + 1, b.rot);
    drawWashPoly(shadePts, "#B31E04", 190, 0.3);

    // Warm salmon-orange midtone crown on the upper-left
    let crownPts = makeClayEllipse(b.x - 3, b.y - 3, b.rx * 0.65, b.ry * 0.58, 14, 1.2, b.seed + 2, b.rot);
    drawWashPoly(crownPts, "#FF8552", 215, 0.3);

    // Pinched hilum scar / smeared clay seam on each bean pellet
    let cr = cos(b.rot);
    let sr = sin(b.rot);
    drawStrokeLine(
      b.x - cr * 6, b.y - sr * 6,
      b.x + cr * 6, b.y + sr * 6,
      "smear", "#9E1903", 0.55
    );

    // Crisp pencil edge around the pellet
    drawStrokeSpline([...bPts, bPts[0]], "2B", "#610D02", 0.58, 0.32);

    // TWIN TABLETOP LAMP CATCHLIGHTS on the satin bean surface!
    // Lamp A reflection (upper-left)
    drawStrokeLine(
      b.x - 6.5, b.y - 5.5,
      b.x - 2.0, b.y - 6.5,
      "satin", "#FFF3E0", 0.95
    );
    // Lamp B reflection (upper-right pinpoint)
    drawStrokeLine(
      b.x + 3.5, b.y - 5.0,
      b.x + 5.5, b.y - 4.0,
      "rotring", "#FFFFFF", 0.75
    );
  }
}

// ============================================================================
// ITEM 6: GRILLED PLASTICINE TOMATO HALF (LOWER LEFT-CENTER)
// ============================================================================

function drawPlasticineTomato() {
  let tx = 418;
  let ty = 778;
  let rx = 78;
  let ry = 68;

  // Rounded scarlet outer dome beneath the flat cut top
  let bodyPts = makeClayEllipse(tx + 4, ty + 14, rx * 1.04, ry * 1.05, 36, 2.2, 44.1, 8);

  // Doubled cast shadow on the plate well
  drawDoubledShadow(bodyPts, 0.62, "#87745E", "#756973", "#402B1F", 1.02, 0.28);

  // Outer tomato dome in saturated scarlet-crimson
  drawWashPoly(bodyPts, "#BF0B0B", 252, 0.3);
  let domeShade = makeClayEllipse(tx + 12, ty + 20, rx * 0.92, ry * 0.9, 32, 1.8, 45.0, 8);
  drawWashPoly(domeShade, "#820404", 215, 0.3);

  // Flat sliced top face of the tomato
  let topPts = makeClayEllipse(tx, ty, rx, ry, 36, 2.0, 46.2, 8);
  drawWashPoly(topPts, "#F2221B", 252, 0.28);

  // Inner salmon-pink fleshy ring smeared into the scarlet outer wall
  let fleshRing = makeClayEllipse(tx, ty, rx * 0.82, ry * 0.82, 32, 1.8, 47.3, 8);
  drawWashPoly(fleshRing, "#FF6E5E", 230, 0.28);

  // Smeared clay radial seams between salmon core and scarlet rim
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * 360;
    let r1 = 0.68;
    let r2 = 0.92;
    drawStrokeLine(
      tx + rx * r1 * cos(a), ty + ry * r1 * sin(a),
      tx + rx * r2 * cos(a + 8), ty + ry * r2 * sin(a + 8),
      "smear", (i % 2 === 0) ? "#FF8375" : "#E01B14", 0.65
    );
  }

  // Four recessed dark-crimson seed chambers (locules) with cadmium-yellow clay seeds
  for (let c = 0; c < 4; c++) {
    let baseA = c * 90 + 25;
    let locPts = [];
    locPts.push([tx + rx * 0.22 * cos(baseA), ty + ry * 0.22 * sin(baseA)]);
    for (let a = baseA - 28; a <= baseA + 28; a += 9) {
      locPts.push([tx + rx * 0.72 * cos(a), ty + ry * 0.72 * sin(a)]);
    }
    drawWashPoly(locPts, "#7A0404", 242, 0.25);
    drawStrokeSpline([...locPts, locPts[0]], "2B", "#450101", 0.65, 0.25);

    // Sculpted cadmium-yellow seed pellets tucked inside each chamber
    for (let s = -1; s <= 1; s++) {
      let sa = baseA + s * 15;
      let sr = 0.48 + (abs(s) * 0.08);
      let sx = tx + rx * sr * cos(sa);
      let sy = ty + ry * sr * sin(sa);
      let seedPts = makeClayEllipse(sx, sy, 6.5, 4.2, 10, 0.6, c * 10 + s, sa);
      drawWashPoly(seedPts, "#FFBF00", 250, 0.3);
      drawStrokeLine(sx - 2, sy - 1, sx + 1, sy - 1.5, "rotring", "#FFFCE6", 0.6);
    }
  }

  // Central salmon-cream columella core
  let corePts = makeClayEllipse(tx, ty, rx * 0.24, ry * 0.24, 18, 1.5, 49.0, 8);
  drawWashPoly(corePts, "#FF9B8A", 240, 0.3);

  // Scored knife striations & char specks on the grilled cut face
  for (let k = -4; k <= 4; k++) {
    let yOff = k * 11;
    let xSpan = sqrt(Math.max(0, 1 - (yOff / ry) * (yOff / ry))) * rx * 0.88;
    drawStrokeLine(tx - xSpan, ty + yOff - 4, tx + xSpan, ty + yOff + 4, "chisel", "#B8140E", 0.4);
  }

  // Pinched green clay calyx stub on the upper-left edge
  let calyxPts = makeClayEllipse(tx - rx * 0.78, ty - ry * 0.42, 14, 11, 14, 1.8, 52.0, -25);
  drawWashPoly(calyxPts, "#238A29", 248, 0.3);
  drawStrokeSpline([...calyxPts, calyxPts[0]], "2B", "#0E4712", 0.65, 0.3);

  // Satin sheen on the cut rim & outer tomato dome
  drawStrokeSpline(topPts.slice(18, 30), "satin", "#FFD6CF", 1.3, 0.35);
  drawStrokeSpline([...topPts, topPts[0]], "2B", "#6E0505", 0.75, 0.28);
  drawStrokeSpline([...bodyPts, bodyPts[0]], "2B", "#470202", 0.85, 0.28);
}

// ============================================================================
// ITEM 7: FRIED EGG WITH OBSESSIVE FINGERPRINT WHORL ON CADMIUM YELLOW YOLK
// ============================================================================

function drawPlasticineEgg() {
  let ex = 458;
  let ey = 568;

  // Organic lobed plasticine egg white (albumen) slab
  let whitePts = [];
  let nWhite = 56;
  for (let i = 0; i < nWhite; i++) {
    let a = (i / nWhite) * 360;
    let lobe = sin(a * 3 - 20) * 18 + cos(a * 5 + 45) * 12 + sin(a * 8) * 5;
    let rx = 158 + lobe;
    let ry = 132 + lobe * 0.85;
    whitePts.push([
      ex + rx * cos(a - 14),
      ey + ry * sin(a - 14)
    ]);
  }

  // Doubled cast shadow of the thick egg white slab onto plate and toast edge
  drawDoubledShadow(whitePts, 0.32, "#8F7F6A", "#7D747A", "#4A3C2E", 0.96, 0.28);

  // Crispy golden-browned plasticine frill rolled along the outer-left & lower rim
  let frillPts = offsetPoly(whitePts, -3, 3, 1.03, 1.03, ex, ey);
  drawWashPoly(frillPts, "#C97826", 242, 0.28);
  drawStrokeSpline(frillPts.slice(10, 42), "gouache", "#8F470B", 0.75, 0.3);

  // Milky-cream plasticine egg white body
  drawWashPoly(whitePts, "#FAF6EB", 252, 0.28);

  // Subtle sculpted thumb depressions in the egg white around the yolk
  let dip1 = makeClayEllipse(ex - 65, ey + 28, 48, 36, 24, 1.5, 61.1, -20);
  let dip2 = makeClayEllipse(ex + 62, ey - 24, 52, 38, 24, 1.5, 62.2, 15);
  let dip3 = makeClayEllipse(ex + 35, ey + 55, 58, 34, 24, 1.5, 63.3, -10);
  drawWashPoly(dip1, "#E8E0CE", 185, 0.3);
  drawWashPoly(dip2, "#EAE2D0", 175, 0.3);
  drawWashPoly(dip3, "#E3DAC6", 195, 0.3);

  // Smeared amber-into-white seams along the crispy edge
  for (let i = 12; i < 44; i += 2) {
    let p = whitePts[i];
    let dirX = ex - p[0];
    let dirY = ey - p[1];
    let d = sqrt(dirX * dirX + dirY * dirY) || 1;
    drawStrokeLine(
      p[0], p[1],
      p[0] + (dirX / d) * random(10, 20),
      p[1] + (dirY / d) * random(10, 20),
      "smear", (i % 4 === 0) ? "#D18332" : "#FFFDF7", 0.65
    );
  }

  // Satin clay sheen on the raised lobes of the egg white
  drawStrokeSpline(whitePts.slice(32, 46), "satin", "#FFFFFF", 1.6, 0.35);
  drawStrokeLine(ex - 85, ey - 35, ex - 45, ey - 52, "satin", "#FFFFFF", 1.4);
  drawStrokeSpline([...whitePts, whitePts[0]], "2B", "#78644E", 0.75, 0.28);

  // ==========================================================================
  // THE CADMIUM YELLOW YOLK DOME WITH OBSESSIVE FINGERPRINT WHORL
  // ==========================================================================
  let yx = ex - 6;
  let yy = ey - 6;
  let yRx = 74;
  let yRy = 66;

  let yolkPts = makeClayEllipse(yx, yy, yRx, yRy, 44, 1.4, 70.1, -6);

  // Doubled cast shadow of the high yolk dome onto the white albumen
  drawDoubledShadow(yolkPts, 0.38, "#C9B99B", "#BDB3A8", "#968264", 0.92, 0.3);

  // Rich cadmium-yellow base dome
  drawWashPoly(yolkPts, "#FFB300", 254, 0.3);

  // Deep cadmium-orange crescent on the lower-right shaded slope
  let yolkShadePts = makeClayEllipse(yx + 10, yy + 10, yRx * 0.84, yRy * 0.82, 36, 1.1, 71.2, -6);
  drawWashPoly(yolkShadePts, "#F27900", 215, 0.3);

  let yolkDeepShade = makeClayEllipse(yx + 18, yy + 16, yRx * 0.64, yRy * 0.62, 32, 1.0, 72.3, -6);
  drawWashPoly(yolkDeepShade, "#D95600", 175, 0.3);

  // Luminous lemon-cadmium upper-left dome face
  let yolkCrown = makeClayEllipse(yx - 8, yy - 8, yRx * 0.78, yRy * 0.76, 36, 1.0, 73.4, -6);
  drawWashPoly(yolkCrown, "#FFCC00", 235, 0.3);

  let yolkBright = makeClayEllipse(yx - 16, yy - 14, yRx * 0.52, yRy * 0.48, 28, 0.8, 74.5, -6);
  drawWashPoly(yolkBright, "#FFE033", 220, 0.3);

  // Smeared colour seam around the base of the yolk where yellow clay meets white clay
  for (let i = 0; i < 36; i++) {
    let a = (i / 36) * 360;
    let px = yx + yRx * 0.98 * cos(a);
    let py = yy + yRy * 0.98 * sin(a);
    let smAng = a + random(-28, 28);
    let smCol = (i % 3 === 0) ? "#FFF5C2" : "#FFBF1F";
    drawStrokeLine(
      px - cos(a) * 4, py - sin(a) * 4,
      px + cos(smAng) * random(8, 16), py + sin(smAng) * random(8, 16),
      "smear", smCol, 0.65
    );
  }

  // FINGERPRINT WHORL SCULPTED INTO THE CADMIUM YELLOW YOLK
  // Concentric dermatoglyphic spiral/whorl ridges with minutiae (bifurcations, endings)
  // and 3D lighting (dark amber furrow + bright lemon crest + broken specular glints)
  let whorlCx = yx - 4;
  let whorlCy = yy - 2;
  let whorlRot = -18;
  let cRot = cos(whorlRot);
  let sRot = sin(whorlRot);

  // Draw 15 concentric whorl rings + outer arch sweeps
  for (let ring = 1; ring <= 16; ring++) {
    let rBase = ring * 4.3;
    // Break each ring into 2-4 realistic ridge segments (creating ridge endings & bifurcations)
    let nSegs = ring < 4 ? 1 : (ring < 10 ? 2 : 3);
    let gapOffset = (ring * 67) % 360;

    for (let s = 0; s < nSegs; s++) {
      let aStart = gapOffset + s * (360 / nSegs) + 8;
      let aEnd = gapOffset + (s + 1) * (360 / nSegs) - 10;

      let furrowPts = [];
      let crestPts = [];

      for (let a = aStart; a <= aEnd; a += 8) {
        // Whorl elongation & lower delta pinch
        let pinch = 1.0 + 0.14 * sin(a * 2 + 30) + 0.08 * cos(a * 3);
        let spiralShift = (a - aStart) * 0.008;
        let lx = (rBase + spiralShift) * 0.92 * pinch * cos(a);
        let ly = (rBase + spiralShift) * 1.08 * pinch * sin(a);

        let gx = whorlCx + lx * cRot - ly * sRot;
        let gy = whorlCy + lx * sRot + ly * cRot;

        // Keep strictly inside yolk boundary
        let normDist = sq((gx - yx) / (yRx * 0.91)) + sq((gy - yy) / (yRy * 0.91));
        if (normDist < 1.0) {
          furrowPts.push([gx, gy]);
          // Raised clay ridge crest offset toward the upper-left light source
          crestPts.push([gx - 1.3, gy - 1.3]);
        }
      }

      if (furrowPts.length >= 3) {
        // Determine whether this ridge segment is on the lit side, midtone, or shaded side
        let midPt = furrowPts[Math.floor(furrowPts.length / 2)];
        let isShaded = (midPt[0] - yx) + (midPt[1] - yy) > 15;
        let furrowCol = isShaded ? "#8C2D00" : "#B84700";
        let crestCol = isShaded ? "#FFA600" : "#FFF078";

        drawStrokeSpline(furrowPts, "rotring", furrowCol, 0.62, 0.45);
        drawStrokeSpline(crestPts, "cpencil", crestCol, 0.58, 0.45);
      }

      // Add fingerprint bifurcation (Y-fork) at selected segment starts
      if (ring > 4 && ring < 14 && s === 0 && furrowPts.length >= 4) {
        let forkStart = furrowPts[1];
        let forkEnd = [
          forkStart[0] + cos(aStart + 35) * 7,
          forkStart[1] + sin(aStart + 35) * 7
        ];
        drawStrokeLine(forkStart[0], forkStart[1], forkEnd[0], forkEnd[1], "rotring", "#AD3E00", 0.55);
      }
    }
  }

  // Dual hard studio lamp specular catchlights stepped across the fingerprint ridges!
  // Lamp A catchlight cluster (upper-left of yolk dome)
  for (let r = 3; r <= 9; r++) {
    let rad = r * 4.3;
    let hlPts = [];
    for (let a = 195; a <= 248; a += 7) {
      let lx = rad * 0.92 * cos(a);
      let ly = rad * 1.08 * sin(a);
      let gx = whorlCx + lx * cRot - ly * sRot;
      let gy = whorlCy + lx * sRot + ly * cRot;
      hlPts.push([gx, gy]);
    }
    drawStrokeSpline(hlPts, "satin", "#FFFFEB", 1.15, 0.4);
    drawStrokeSpline(hlPts, "rotring", "#FFFFFF", 0.65, 0.4);
  }

  // Lamp B catchlight cluster (upper-right-center of yolk dome)
  for (let r = 4; r <= 8; r++) {
    let rad = r * 4.3;
    let hlPtsB = [];
    for (let a = 285; a <= 322; a += 7) {
      let lx = rad * 0.92 * cos(a);
      let ly = rad * 1.08 * sin(a);
      let gx = whorlCx + lx * cRot - ly * sRot;
      let gy = whorlCy + lx * sRot + ly * cRot;
      hlPtsB.push([gx, gy]);
    }
    drawStrokeSpline(hlPtsB, "satin", "#FFFFFF", 0.95, 0.4);
    drawStrokeSpline(hlPtsB, "rotring", "#FFFFFF", 0.55, 0.4);
  }

  drawStrokeSpline([...yolkPts, yolkPts[0]], "2B", "#9E3B00", 0.72, 0.3);
}

