// LAYER 6: HYPERREAL MICRO-INCIDENTS (STRAY CLAY CRUMBS, DUST SPECKS & LINT)
// ============================================================================

function drawMicroDustAndClayCrumbs() {
  // 1. Tiny stray plasticine crumbs stuck to the plate rim and tablecloth
  let crumbColors = ["#FFD000", "#FF6B63", "#F23814", "#EDA958", "#1852B8", "#8F4116"];
  for (let i = 0; i < 42; i++) {
    let cx = random(80, 1120);
    let cy = random(80, 1120);
    let r = random(2.2, 4.8);
    let col = crumbColors[i % crumbColors.length];
    let cPts = makeClayEllipse(cx, cy, r, r * 0.8, 8, 0.6, i * 2.1, random(360));
    // Tiny shadow under crumb
    drawStrokeLine(cx + 1.5, cy + 2, cx + 3.5, cy + 3, "2B", "#2B211B", 0.55);
    drawWashPoly(cPts, col, 245, 0.3);
    drawStrokeLine(cx - 1, cy - 1, cx + 0.5, cy - 1, "rotring", "#FFFFFF", 0.45);
  }

  // 2. Microscopic studio dust specks and tiny curved lint fibers caught in the tacky clay
  for (let i = 0; i < 195; i++) {
    // Concentrate dust specks across the breakfast and plate
    let rad = Math.pow(random(), 0.7) * 520;
    let ang = random(360);
    let dx = 600 + rad * cos(ang);
    let dy = 600 + rad * sin(ang);

    if (i % 5 === 0) {
      // Tiny curved studio lint fiber (3-8px long) stuck to the plasticine
      let lAng = random(360);
      let lLen = random(3.5, 8.0);
      let midX = dx + cos(lAng + 25) * (lLen * 0.5);
      let midY = dy + sin(lAng + 25) * (lLen * 0.5);
      let endX = dx + cos(lAng) * lLen;
      let endY = dy + sin(lAng) * lLen;
      let isLightFiber = random() < 0.45;
      let fCol = isLightFiber ? "#FFFDF5" : "#2E231C";
      drawStrokeSpline([[dx, dy], [midX, midY], [endX, endY]], "2H", fCol, 0.38, 0.5);
    } else {
      // Pinpoint dust speck (dark or bright mineral mote)
      let isWhiteSpeck = random() < 0.52;
      let sCol = isWhiteSpeck ? "#FFFFFF" : "#33241B";
      drawStrokeLine(dx, dy, dx + random(0.8, 1.8), dy + random(-0.8, 1.2), "rotring", sCol, 0.35);
    }
  }
}

