// ============================================================================
// 1. GLEAMING GOLDEN-OCHRE LACQUER TRAY
// ============================================================================
function drawLacquerTray() {
  resetBrushState();

  // Deep twilight corners outside the raised tray rim
  brush.noStroke();
  brush.wash(PAL.blackDeep, 255);
  brush.rect(0, 0, width, height, "corner");

  // Tray center & tilted elliptical geometry
  const cx = 620, cy = 620;

  // Outer bevelled rim of the large lacquer platter
  drawEllipseWash(cx, cy, 665, 595, -14, PAL.blackLamp, 240);
  drawEllipseWash(cx, cy, 645, 576, -14, PAL.goldShadow, 190);
  drawEllipseWash(cx, cy, 632, 564, -14, PAL.goldAntique, 160);
  drawEllipseWash(cx, cy, 620, 552, -14, PAL.blackSoot, 230);

  // Recessed lacquer bed: layered golden-ochre washes from dusky edge to glowing center
  const bedLayers = [
    { rx: 605, ry: 538, ox: 0, oy: 0, col: PAL.twilightUmber, op: 220 },
    { rx: 575, ry: 510, ox: -10, oy: -5, col: PAL.goldShadow, op: 190 },
    { rx: 535, ry: 472, ox: -20, oy: -15, col: PAL.goldAntique, op: 175 },
    { rx: 485, ry: 425, ox: -25, oy: -25, col: PAL.goldBronze, op: 165 },
    { rx: 430, ry: 375, ox: -30, oy: -30, col: PAL.goldOchre, op: 155 },
    { rx: 365, ry: 315, ox: -35, oy: -35, col: PAL.goldGleam, op: 135 },
    { rx: 285, ry: 240, ox: -45, oy: -45, col: PAL.goldBright, op: 105 },
    { rx: 195, ry: 165, ox: -55, oy: -55, col: PAL.goldLuminous, op: 75 }
  ];

  for (let l of bedLayers) {
    drawEllipseWash(cx + l.ox, cy + l.oy, l.rx, l.ry, -14, l.col, l.op);
  }

  // Wet watercolour bleed passes to give organic depth to the antique gold ground
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.3);
  brush.fill(PAL.goldOchre, 75);
  drawRotatedPoly(cx - 25, cy - 20, 440, 380, -14, 28);

  brush.fill(PAL.goldGleam, 65);
  drawRotatedPoly(cx - 55, cy - 50, 310, 265, -18, 26);

  brush.fill(PAL.goldShadow, 60);
  drawRotatedPoly(cx + 150, cy + 165, 340, 260, -10, 24);
  resetBrushState();

  // Hand-burnished lacquer grain & directional twilight sheen
  for (let i = 0; i < 160; i++) {
    let t = i / 160;
    let angle = -18 + sin(t * 180) * 4;
    let px = random(80, 1120);
    let py = random(80, 1120);
    let d = dist(px, py, cx - 35, cy - 35);
    let col = d < 280 ? PAL.goldBright : (d < 460 ? PAL.goldOchre : PAL.goldShadow);
    if (random() < 0.28) col = d < 350 ? PAL.goldLuminous : PAL.blackSoot;

    brush.set("lacquer_glaze", col, random(0.6, 1.6));
    let len = random(90, 260);
    let dx = cos(angle) * len * 0.5;
    let dy = sin(angle) * len * 0.5;
    brush.spline([
      [px - dx, py - dy, 0.2],
      [px, py + random(-8, 8), 1.0],
      [px + dx, py + dy, 0.2]
    ], 0.3);
  }

  // Diagonal window light reflection bands across the glossy lacquer surface
  for (let i = 0; i < 42; i++) {
    let sx = map(i, 0, 41, 180, 880) + random(-20, 20);
    let sy = map(i, 0, 41, 680, 180) + random(-20, 20);
    let len = random(180, 420);
    let ang = -24 + random(-1.5, 1.5);
    let col = i % 3 === 0 ? PAL.birchPale : PAL.goldLuminous;
    brush.set("lacquer_glaze", col, random(0.4, 1.0));
    brush.line(
      sx - cos(ang) * len * 0.5,
      sy - sin(ang) * len * 0.5,
      sx + cos(ang) * len * 0.5,
      sy + sin(ang) * len * 0.5
    );
  }

  // Fine antique lacquer crazing & golden dust micro-Lines
  for (let i = 0; i < 95; i++) {
    let rx = random(100, 1100);
    let ry = random(100, 1100);
    let d = dist(rx, ry, cx, cy);
    if (d < 560) {
      brush.set("2H", d < 360 ? PAL.goldBronze : PAL.blackLamp, 0.28);
      let a = random(-35, 15);
      let l = random(25, 85);
      brush.line(rx, ry, rx + cos(a) * l, ry + sin(a) * l);
    }
  }

  // Raised tray rim specular gold double-line & deep groove shadow
  drawTrayRimBorders(cx, cy);
}

function drawTrayRimBorders(cx, cy) {
  const rings = [
    { rx: 636, ry: 568, col: PAL.goldGleam, w: 0.7, brushName: "calligraphy", start: 0, end: 360 },
    { rx: 634, ry: 566, col: PAL.birchPale, w: 0.45, brushName: "pen", start: 110, end: 310 },
    { rx: 612, ry: 545, col: PAL.blackDeep, w: 0.9, brushName: "calligraphy", start: 0, end: 360 },
    { rx: 604, ry: 537, col: PAL.cinnabar, w: 0.45, brushName: "rotring", start: 0, end: 360 },
    { rx: 596, ry: 530, col: PAL.goldBright, w: 0.35, brushName: "rotring", start: 0, end: 360 }
  ];

  for (let r of rings) {
    let pts = [];
    for (let a = r.start; a <= r.end; a += 5) {
      let x = cx + cos(a) * r.rx;
      let y = cy + sin(a) * r.ry;
      let rotX = cx + (x - cx) * cos(-14) - (y - cy) * sin(-14);
      let rotY = cy + (x - cx) * sin(-14) + (y - cy) * cos(-14);
      let p = 0.6 + 0.4 * sin(a * 2);
      pts.push([rotX, rotY, p]);
    }
    brush.set(r.brushName, r.col, r.w);
    brush.spline(pts, 0.4);
  }
}

