    { x: 488, y: 778, r: 25, shade: 0.10 },
    { x: 556, y: 808, r: 24, shade: 0.11 },
    { x: 618, y: 834, r: 25, shade: 0.12 },
    { x: 688, y: 818, r: 23, shade: 0.14 },
    { x: 758, y: 786, r: 24, shade: 0.14 },
    { x: 768, y: 724, r: 22, shade: 0.12 },
    { x: 822, y: 752, r: 21, shade: 0.16 },
    { x: 742, y: 618, r: 24, shade: 0.09 },
    { x: 798, y: 652, r: 22, shade: 0.14 },
    { x: 678, y: 508, r: 23, shade: 0.08 },
    { x: 734, y: 538, r: 21, shade: 0.11 },
    { x: 632, y: 448, r: 22, shade: 0.10 },
    { x: 572, y: 398, r: 21, shade: 0.12 },
    { x: 545, y: 886, r: 21, shade: 0.18 },
