  ];

  for (let b of ladleBerries) {
    berries.push(enrichBerry(b));
  }
  for (let b of spillBerries) {
    b.tier = "spill";
    berries.push(enrichBerry(b));
  }

  // Painter's sort: back-to-front along view direction
  berries.sort((a, b) => (a.y * 0.88 + a.x * 0.12) - (b.y * 0.88 + b.x * 0.12));
}

function enrichBerry(b) {
  let ang = random(0, 360);
  // Position calyx predominantly on the visible outer hemisphere or side profile
  let calyxDist = random(0.22, 0.68) * b.r;
  // Avoid placing calyx directly over the upper-left window highlight (-135 deg)
  if (ang > 190 && ang < 265) ang += 95;
  return {
    x: b.x,
    y: b.y,
    r: b.r,
    tier: b.tier,
    shade: b.shade || 0,
    calyxAng: ang,
    calyxDist: calyxDist,
    showCalyx: random() < 0.86,
    rotHighlight: random(-18, -8),
    warmth: random(0, 1)
  };
}

// ============================================================================
// 3. PAINTED CURLING GRASS MOTIFS (CINNABAR, SCARLET, GOLD & LAMP BLACK)
// ============================================================================
function drawLacquerGrassMotifs(isOverlayer) {
  resetBrushState();

  // Sweeping S-curved master vines flowing around the ladle & berry spill
  const vines = [
    // Vine 1: Left arc sweeping under the ladle and cradling the lower spill
    {
      pts: [[220, 465], [195, 610], [250, 770], [395, 895], [595, 965], [815, 935], [965, 815]],
      col: PAL.blackLamp,
      accent: PAL.cinnabar,
      side: 1
    },
    // Vine 2: Upper-right flourish curving down around the cascade
    {
      pts: [[515, 225], [690, 215], [865, 290], [975, 445], [965, 635], [885, 785]],
      col: PAL.cinnabar,
      accent: PAL.blackLamp,
      side: -1
    },
    // Vine 3: Central decorative stream weaving directly through the spilled fruit
    {
      pts: [[495, 465], [610, 480], [725, 565], [785, 705], [730, 855], [585, 930]],
      col: PAL.blackLamp,
      accent: PAL.scarletBright,
      side: 1
    },
    // Vine 4: Inner counter-scroll from ladle rim toward lower left
    {
      pts: [[385, 505], [305, 585], [295, 710], [385, 815], [520, 855]],
      col: PAL.cinnabar,
      accent: PAL.blackLamp,
      side: -1
    },
    // Vine 5: Upper-right inner spiral
    {
      pts: [[575, 335], [715, 330], [835, 415], [855, 545], [785, 630]],
      col: PAL.blackLamp,
      accent: PAL.vermilion,
      side: 1
    },
    // Vine 6: Lower-right curling flourish
    {
      pts: [[795, 895], [925, 890], [1025, 785], [1030, 645]],
      col: PAL.cinnabar,
      accent: PAL.blackLamp,
      side: -1
    }
  ];

  if (!isOverlayer) {
    // Faint watercolour cinnabar & lamp-black blooms in the lacquer under-layer
    brush.noStroke();
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.5, 0.35);
    const blooms = [
      { x: 255, y: 685, rx: 65, ry: 45, col: PAL.cinnabar, op: 42 },
      { x: 795, y: 365, rx: 75, ry: 50, col: PAL.scarletCore, op: 38 },
      { x: 915, y: 695, rx: 68, ry: 48, col: PAL.cinnabar, op: 40 },
      { x: 465, y: 875, rx: 72, ry: 45, col: PAL.crimsonRich, op: 42 },
      { x: 665, y: 245, rx: 60, ry: 40, col: PAL.goldShadow, op: 55 }
    ];
    for (let bl of blooms) {
      brush.fill(bl.col, bl.op);
      drawRotatedPoly(bl.x, bl.y, bl.rx, bl.ry, random(-30, 30), 16);
    }
    resetBrushState();
  }

  for (let vIdx = 0; vIdx < vines.length; vIdx++) {
    let v = vines[vIdx];

    // Draw main vine stem on the base pass
    if (!isOverlayer) {
      let splinePts = v.pts.map((p, idx) => {
        let pr = map(sin((idx / (v.pts.length - 1)) * 180), 0, 1, 0.35, 1.15);
        return [p[0], p[1], pr];
      });
      brush.set("calligraphy", v.col, 0.85);
      brush.spline(splinePts, 0.55);

      // Parallel fine gold/cinnabar echo line
      let offsetPts = v.pts.map((p, idx) => [p[0] + 4, p[1] + 4, 0.4]);
      brush.set("rotring", v.accent, 0.38);
      brush.spline(offsetPts, 0.55);
    }

    // Sprout curling grass blades ("travka") along the vine
    let bladeCount = isOverlayer ? 10 : 22;
    for (let i = 1; i < bladeCount; i++) {
      let t = i / bladeCount;
      let pt = samplePolyline(v.pts, t);
      let tang = sampleTangent(v.pts, t);
      let side = (i % 2 === 0 ? 1 : -1) * v.side;

      // On overlayer, only draw blades that weave close to the berries
      let nearBerry = isNearAnyBerry(pt.x, pt.y, 135);
      if (isOverlayer && !nearBerry) continue;

      let bladeLen = isOverlayer ? random(42, 78) : random(58, 125);
      let curlDir = side * random(0.8, 1.35);
      let baseAng = tang + side * random(28, 62);

      let bladeCol = (i + vIdx) % 3 === 0 ? PAL.cinnabar :
                     ((i + vIdx) % 3 === 1 ? PAL.blackLamp : PAL.scarletBright);

      drawCurlingGrassBlade(
        pt.x, pt.y,
        baseAng,
        bladeLen,
        curlDir,
        bladeCol,
        isOverlayer ? 0.65 : random(0.75, 1.25)
      );

      // Add a delicate contrasting inner vein or shadow stroke
      if (!isOverlayer && i % 2 === 0) {
        let veinCol = bladeCol === PAL.blackLamp ? PAL.goldBright : PAL.blackLamp;
        drawCurlingGrassBlade(
          pt.x + 2, pt.y + 2,
          baseAng + side * 4,
          bladeLen * 0.72,
          curlDir * 0.9,
          veinCol,
          0.35
        );
      }
    }
  }

  // Ornate painted feather-scroll rosettes in the open corners of the tray
  if (!isOverlayer) {
    const scrollCenters = [
      { x: 235, y: 645, ang: 45, scale: 1.05 },
      { x: 855, y: 355, ang: 135, scale: 1.1 },
      { x: 925, y: 695, ang: 215, scale: 1.0 },
      { x: 355, y: 845, ang: 15, scale: 0.95 },
      { x: 645, y: 245, ang: 95, scale: 0.9 }
    ];
    for (let sc of scrollCenters) {
      drawPaintedScrollCluster(sc.x, sc.y, sc.ang, sc.scale);
    }
  }
}

function drawCurlingGrassBlade(x, y, startAngle, length, curlDir, col, weightMult) {
  let pts = [];
  let cx = x, cy = y;
  let ang = startAngle;
  let steps = 14;
  let stepLen = length / steps;

  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    // Swell in the belly of the grass blade, taper to razor tip at end
    let pressure = u < 0.35
      ? map(u, 0, 0.35, 0.18, 1.45)
      : map(pow(1 - u, 1.3), 0, 1, 0.08, 1.45);
    pts.push([cx, cy, pressure]);
    // Curvature tightens exponentially at the tip into a signature Khokhloma curl
    let deltaAng = (4 + pow(u, 2.2) * 34) * curlDir;
    ang += deltaAng;
    cx += cos(ang) * stepLen * (1 - u * 0.35);
    cy += sin(ang) * stepLen * (1 - u * 0.35);
  }

  brush.set("calligraphy", col, weightMult);
  brush.spline(pts, 0.5);

  // Tiny droplet bead at the curled tip
  if (random() < 0.72) {
    let tip = pts[pts.length - 1];
    let dotCol = col === PAL.blackLamp ? PAL.cinnabar : PAL.blackLamp;
    drawPaintedDot(tip[0] + cos(ang) * 5, tip[1] + sin(ang) * 5, random(2.2, 4.2), dotCol);
  }
}

function drawPaintedScrollCluster(cx, cy, baseAng, sc) {
  // Alternating cinnabar and lamp-black plume blades radiating from a coiled stem
  for (let i = -4; i <= 4; i++) {
    let a = baseAng + i * 22;
    let len = (95 - abs(i) * 12) * sc;
    let col = i % 2 === 0 ? PAL.cinnabar : PAL.blackLamp;
    let curl = i >= 0 ? 1.1 : -1.1;
    drawCurlingGrassBlade(cx, cy, a, len, curl, col, 0.9 * sc);
  }

  // Arc of diminishing painted lacquer dots framing the scroll
  for (let i = -5; i <= 5; i++) {
    let a = baseAng + 180 + i * 16;
    let rad = 36 * sc;
    let dx = cx + cos(a) * rad;
    let dy = cy + sin(a) * rad;
    let r = map(abs(i), 0, 5, 5.2, 1.8) * sc;
    let col = i % 2 === 0 ? PAL.cinnabar : PAL.goldBright;
    drawPaintedDot(dx, dy, r, col);
  }
}

function drawPaintedDot(x, y, r, col) {
  resetBrushState();
  brush.noStroke();
  brush.wash(col, 225);
  brush.circle(x, y, r, 0.12);
  if (r > 3.2) {
    brush.wash(PAL.goldLuminous, 120);
    brush.circle(x - r * 0.25, y - r * 0.25, r * 0.35, 0.08);
  }
  resetBrushState();
}

// ============================================================================
// 4. CAST SHADOWS & WARM WATERCOLOUR REFLECTIONS ON THE LACQUER
// ============================================================================
function drawLadleShadow() {
  resetBrushState();
  // Deep ambient shadow cast by the tilted birch ladle onto the lacquer tray
  const shX = 435, shY = 445;
  drawEllipseWash(shX + 18, shY + 28, 195, 138, 28, PAL.blackDeep, 175);
  drawEllipseWash(shX + 5, shY + 18, 165, 115, 28, PAL.blackLamp, 210);
  drawEllipseWash(shX - 8, shY + 10, 135, 92, 28, PAL.blackDeep, 235);

  // Cast shadow of the arched wooden handle
  let handleShadowPts = [];
  let handleReturnPts = [];
  for (let t = 0; t <= 1; t += 0.1) {
    let x = lerp(85, 335, t) + 22;
    let y = lerp(175, 365, t) + sin(t * 180) * 18 + 38;
    handleShadowPts.push([x, y]);
    handleReturnPts.unshift([x - 36, y + 28]);
  }
  brush.noStroke();
  brush.wash(PAL.blackLamp, 165);
  drawCustomShape(handleShadowPts.concat(handleReturnPts));
  resetBrushState();
}

function drawBerryShadowsAndReflections() {
  resetBrushState();

  // Warm crimson/cinnabar watercolour pools where berries reflect into the glossy lacquer
  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.55, 0.3);

  for (let i = 0; i < berries.length; i += 2) {
    let b = berries[i];
    if (b.tier === "ladle_back") continue;
    let col = i % 4 === 0 ? PAL.crimsonRich : PAL.cinnabar;
    brush.fill(col, 48);
    drawRotatedPoly(b.x + 12, b.y + 16, b.r * 1.45, b.r * 1.15, 22, 14);
  }
  resetBrushState();

  // Crisp cast shadows and contact occlusion beneath each spilled berry
  for (let b of berries) {
    if (b.tier === "ladle_back") continue;

    // Soft cast shadow shifted lower-right (away from upper-left studio window)
    drawEllipseWash(b.x + b.r * 0.42, b.y + b.r * 0.52, b.r * 1.05, b.r * 0.78, 25, PAL.blackLamp, 165);
    // Warm scarlet caustic edge inside the shadow
    drawEllipseWash(b.x + b.r * 0.62, b.y + b.r * 0.68, b.r * 0.65, b.r * 0.45, 25, PAL.crimsonDeep, 115);
    // Tight lamp-black contact shadow directly under the berry
    drawEllipseWash(b.x + b.r * 0.15, b.y + b.r * 0.25, b.r * 0.72, b.r * 0.52, 20, PAL.blackDeep, 225);
  }
  resetBrushState();
}

// ============================================================================
// 5 & 7. HAND-CARVED BIRCH LADLE (BOWL, HOLLOW, RIM & SCULPTED HANDLE)
// ============================================================================
function getLadleRimPoint(angleDeg, rx, ry, cx, cy, rotDeg) {
  let lx = cos(angleDeg) * rx;
  let ly = sin(angleDeg) * ry;
  return {
    x: cx + lx * cos(rotDeg) - ly * sin(rotDeg),
    y: cy + lx * sin(rotDeg) + ly * cos(rotDeg)
  };
}

function drawBirchLadleBackAndInterior() {
  resetBrushState();
  const cx = 425, cy = 382;
  const rx = 152, ry = 108;
  const rot = 28;

  // 1. Outer carved wooden belly of the tilted ladle (visible around left & bottom-left)
  let outerBelly = [];
  for (let a = 95; a <= 315; a += 8) {
    let bulge = sin(map(a, 95, 315, 0, 180));
    let p = getLadleRimPoint(a, rx + 42 * bulge, ry + 54 * bulge, cx - 18, cy + 16, rot);
    outerBelly.push([p.x, p.y]);
  }
  for (let a = 315; a >= 95; a -= 10) {
    let p = getLadleRimPoint(a, rx, ry, cx, cy, rot);
    outerBelly.push([p.x, p.y]);
  }

  // Base wood fill for outer ladle belly
  brush.noStroke();
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.45, 0.35);
  brush.fill(PAL.goldBronze, 235);
  drawCustomShape(outerBelly);
  resetBrushState();

  // Shaded lower belly & warm reflected lacquer gold along the bottom curve
  for (let band = 0; band < 14; band++) {
    let f = band / 13;
    let pts = [];
    for (let a = 105; a <= 305; a += 10) {
      let bulge = sin(map(a, 95, 315, 0, 180)) * f;
      let p = getLadleRimPoint(a, rx + 40 * bulge, ry + 52 * bulge, cx - 16 * f, cy + 15 * f, rot);
      pts.push([p.x, p.y, 0.6 + 0.5 * sin(map(a, 105, 305, 0, 180))]);
    }
    let col = f < 0.35 ? PAL.goldBright :
              (f < 0.68 ? PAL.goldOchre :
              (f < 0.88 ? PAL.goldShadow : PAL.goldGleam)); // Reflected gold rim at very bottom!
    brush.set("wood_gouge", col, 1.3);
    brush.spline(pts, 0.45);
  }

  // Fine birch wood grain & hand-carved gouge facets on the outer bowl
  for (let i = 0; i < 48; i++) {
    let a1 = random(110, 285);
    let a2 = a1 + random(18, 42);
    let f = random(0.12, 0.92);
    let b1 = sin(map(a1, 95, 315, 0, 180)) * f;
    let b2 = sin(map(a2, 95, 315, 0, 180)) * f;
    let p1 = getLadleRimPoint(a1, rx + 40 * b1, ry + 52 * b1, cx - 16 * f, cy + 15 * f, rot);
    let p2 = getLadleRimPoint(a2, rx + 40 * b2, ry + 52 * b2, cx - 16 * f, cy + 15 * f, rot);
    let col = f > 0.6 ? PAL.twilightUmber : (random() < 0.5 ? PAL.goldAntique : PAL.birchPale);
    brush.set("2B", col, random(0.35, 0.65));
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // 2. Deep Carved Interior Hollow of the Bowl
  drawEllipseWash(cx, cy, rx - 8, ry - 8, rot, PAL.twilightUmber, 245);
  drawEllipseWash(cx - 14, cy - 10, rx - 22, ry - 20, rot, PAL.blackSoot, 230);
  drawEllipseWash(cx + 18, cy + 16, rx - 28, ry - 24, rot, PAL.goldShadow, 195);
  drawEllipseWash(cx + 34, cy + 26, rx - 48, ry - 40, rot, PAL.goldAntique, 165);
  drawEllipseWash(cx + 48, cy + 32, rx - 72, ry - 58, rot, PAL.goldOchre, 130);

  // Carved horizontal gouge rings inside the wooden hollow
  for (let rStep = 0.25; rStep <= 0.92; rStep += 0.08) {
    let pts = [];
    for (let a = 155; a <= 375; a += 12) {
      let p = getLadleRimPoint(a, (rx - 10) * rStep, (ry - 10) * rStep, cx + (1 - rStep) * 14, cy + (1 - rStep) * 10, rot);
      pts.push([p.x, p.y, 0.5]);
    }
    let col = rStep < 0.55 ? PAL.goldAntique : PAL.blackLamp;
    brush.set("2B", col, 0.45);
    brush.spline(pts, 0.4);
  }

  // Back/upper arc of the carved wooden rim (from 175 deg to 360 deg)
  drawCarvedRimArc(cx, cy, rx, ry, rot, 170, 365);
}

function drawBirchLadleRimAndHandle() {
  resetBrushState();
  const cx = 425, cy = 382;
  const rx = 152, ry = 108;
  const rot = 28;

  // Front-left and lower rim arc of the ladle bowl (where berries spill over the right side)
  drawCarvedRimArc(cx, cy, rx, ry, rot, 55, 185);
  // Subtle pouring lip visible on the upper-right edge
  drawCarvedRimArc(cx, cy, rx, ry, rot, -15, 22);

  // Sculpted Birch Handle extending from the upper-left of the bowl (around angle 195..225)
  // Construct 3D top face, bevelled side face, and hooked Nordic finial
  const topEdge = [
    [312, 292], [255, 232], [192, 168], [132, 112], [86, 82], [52, 86], [38, 114]
  ];
  const midRidge = [
    [295, 314], [238, 252], [174, 188], [116, 132], [74, 104], [48, 112], [44, 136]
  ];
  const botEdge = [
    [282, 336], [224, 274], [158, 210], [102, 156], [64, 132], [48, 146], [56, 162]
  ];

  // Fill sunlit top face of the handle
  let topPoly = topEdge.concat([...midRidge].reverse());
  brush.noStroke();
  brush.wash(PAL.goldGleam, 235);
  drawCustomShape(topPoly);
  brush.wash(PAL.birchPale, 140);
  drawCustomShape(topPoly);

  // Fill shaded side bevel of the handle
  let sidePoly = midRidge.concat([...botEdge].reverse());
  brush.wash(PAL.goldShadow, 240);
  drawCustomShape(sidePoly);
  brush.wash(PAL.twilightUmber, 155);
  drawCustomShape(sidePoly);
  resetBrushState();

  // Wood grain & chisel facets along the handle length
  for (let i = 0; i <= 12; i++) {
    let f = i / 12;
    let pts = [];
    for (let j = 0; j < topEdge.length; j++) {
      let x = f < 0.5
        ? lerp(topEdge[j][0], midRidge[j][0], f * 2)
        : lerp(midRidge[j][0], botEdge[j][0], (f - 0.5) * 2);
      let y = f < 0.5
        ? lerp(topEdge[j][1], midRidge[j][1], f * 2)
        : lerp(midRidge[j][1], botEdge[j][1], (f - 0.5) * 2);
      pts.push([x, y, 0.7]);
    }
    let col = f < 0.22 ? PAL.birchCream :
              (f < 0.48 ? PAL.goldBright :
              (f < 0.56 ? PAL.goldLuminous :
              (f < 0.82 ? PAL.goldShadow : PAL.blackLamp)));
    brush.set(f === 0.5 ? "calligraphy" : "2B", col, f === 0.5 ? 0.55 : 0.42);
    brush.spline(pts, 0.45);
  }

  // Carved neck transition where the handle swells into the ladle rim
  for (let i = 0; i < 18; i++) {
    let t = i / 17;
    let sx = lerp(282, 315, t);
    let sy = lerp(336, 290, t);
    let ex = lerp(305, 348, t);
    let ey = lerp(362, 312, t);
    let col = t > 0.55 ? PAL.birchPale : (t > 0.25 ? PAL.goldOchre : PAL.goldShadow);
    brush.set("wood_gouge", col, 0.65);
    brush.line(sx, sy, ex, ey);
  }

  // Crisp silhouette & highlight lines on the handle
  brush.set("rotring", PAL.birchCream, 0.45);
  brush.spline(topEdge.map(p => [p[0], p[1], 0.8]), 0.45);
  brush.set("rotring", PAL.blackLamp, 0.55);
  brush.spline(botEdge.map(p => [p[0], p[1], 0.9]), 0.45);
}

function drawCarvedRimArc(cx, cy, rx, ry, rot, startAng, endAng) {
  let outerPts = [];
  let innerPts = [];
  let midPts = [];

  for (let a = startAng; a <= endAng; a += 6) {
    let thick = 14 + 4 * cos(a - 190);
    let pOut = getLadleRimPoint(a, rx + thick * 0.5, ry + thick * 0.5, cx, cy, rot);
    let pIn = getLadleRimPoint(a, rx - thick * 0.5, ry - thick * 0.5, cx, cy, rot);
    let pMid = getLadleRimPoint(a, rx, ry, cx, cy, rot);
    outerPts.push([pOut.x, pOut.y]);
    innerPts.push([pIn.x, pIn.y]);
    midPts.push([pMid.x, pMid.y, 0.9]);
  }

  let rimPoly = outerPts.concat([...innerPts].reverse());
  resetBrushState();
  brush.noStroke();
  brush.wash(PAL.goldGleam, 235);
  drawCustomShape(rimPoly);
  brush.wash(PAL.birchPale, 155);
  drawCustomShape(rimPoly);
  resetBrushState();

  // Chisel facet marks along the wooden rim lip
  brush.set("wood_gouge", PAL.birchCream, 0.85);
  brush.spline(midPts, 0.4);

  brush.set("2B", PAL.goldShadow, 0.45);
  brush.spline(innerPts.map(p => [p[0], p[1], 0.7]), 0.4);
  brush.set("2B", PAL.goldAntique, 0.4);
  brush.spline(outerPts.map(p => [p[0], p[1], 0.7]), 0.4);
}

// ============================================================================
// 8. REAL LINGONBERRY LEAVES & STEMS TUCKED INTO THE HARVEST
// ============================================================================
function drawTuckedLeavesAndStems() {
  // Tucked dark bronze-black & crimson-gold leathery oval lingonberry leaves
  const leaves = [
    { x: 418, y: 482, ang: 145, len: 46, wid: 21 },
    { x: 562, y: 452, ang: -28, len: 44, wid: 19 },
    { x: 468, y: 642, ang: 118, len: 50, wid: 22 },
    { x: 695, y: 568, ang: 22, len: 45, wid: 20 },
    { x: 582, y: 762, ang: 72, len: 48, wid: 21 },
    { x: 735, y: 748, ang: -15, len: 40, wid: 18 },
    { x: 375, y: 318, ang: -125, len: 42, wid: 19 }
  ];

  for (let lf of leaves) {
    resetBrushState();
    let pts = [];
    let steps = 16;
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * 360;
      let lx = cos(a) * lf.len * 0.5;
      let ly = sin(a) * lf.wid * 0.5;
      let rx = lf.x + lx * cos(lf.ang) - ly * sin(lf.ang);
      let ry = lf.y + lx * sin(lf.ang) + ly * cos(lf.ang);
      pts.push([rx, ry]);
    }
    // Shadow
    brush.noStroke();
    brush.wash(PAL.blackDeep, 175);
    drawCustomShape(pts.map(p => [p[0] + 5, p[1] + 7]));

    // Leaf body in dusky lamp-black & antique bronze-gold (strictly within palette)
    brush.wash(PAL.blackSoot, 235);
    drawCustomShape(pts);
    brush.wash(PAL.goldShadow, 145);
    drawCustomShape(pts);
    resetBrushState();

    // Central leaf vein & glossy golden-ochre rim highlight
    let tipX = lf.x + cos(lf.ang) * lf.len * 0.48;
    let tipY = lf.y + sin(lf.ang) * lf.len * 0.48;
    let baseX = lf.x - cos(lf.ang) * lf.len * 0.48;
    let baseY = lf.y - sin(lf.ang) * lf.len * 0.48;
    brush.set("rotring", PAL.goldBright, 0.4);
    brush.line(baseX, baseY, tipX, tipY);
    brush.set("2B", PAL.blackLamp, 0.5);
    brush.spline(pts.concat([pts[0]]).map(p => [p[0], p[1], 0.6]), 0.4);
  }
}

// ============================================================================
// 6 & 9. HYPERREALISTIC WET WATERCOLOUR LINGONBERRY SPHERES
// ============================================================================
function drawSingleBerry(b) {
  const { x, y, r, shade } = b;
  resetBrushState();

  // 1. Wet Watercolour Base Sphere (crimson & scarlet with organic bleed)
  brush.noStroke();
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.48, 0.35);
  let baseCol = shade > 0.3 ? PAL.crimsonDeep : PAL.scarletCore;
  brush.fill(baseCol, 225);
  brush.circle(x, y, r, 0.06);
  resetBrushState();

  // 2. Upper-left glowing Vermilion / Cinnabar lit hemisphere
  brush.noStroke();
  let litOp = map(shade, 0, 0.6, 210, 120);
  drawEllipseWash(x - r * 0.16, y - r * 0.18, r * 0.82, r * 0.78, -35, PAL.cinnabar, litOp);
  drawEllipseWash(x - r * 0.24, y - r * 0.26, r * 0.62, r * 0.56, -35, PAL.vermilion, litOp * 0.95);
  drawEllipseWash(x - r * 0.30, y - r * 0.32, r * 0.40, r * 0.36, -35, PAL.vermilionGlow, litOp * 0.8);

  // 3. Deep Crimson & Lamp-Black Spherical Core Shadow Crescent
  // Curves through the middle-lower belly of the sphere, leaving room at bottom for reflected gold
  let corePts = [];
  for (let a = -25; a <= 155; a += 15) {
    let rad = r * map(sin(map(a, -25, 155, 0, 180)), 0, 1, 0.78, 0.56);
    let px = x + cos(a) * rad;
    let py = y + sin(a) * rad;
    let pr = 0.4 + 0.9 * sin(map(a, -25, 155, 0, 180));
    corePts.push([px, py, pr]);
  }
  brush.set("berry_shader", PAL.crimsonDark, r * 0.048);
  brush.spline(corePts, 0.45);

  let deepCorePts = [];
  for (let a = -5; a <= 135; a += 15) {
    let rad = r * 0.62;
    let px = x + cos(a) * rad;
    let py = y + sin(a) * rad;
    let pr = 0.3 + 0.85 * sin(map(a, -5, 135, 0, 180));
    deepCorePts.push([px, py, pr]);
  }
  brush.set("berry_shader", PAL.blackLamp, r * 0.038);
  brush.spline(deepCorePts, 0.45);

  // 4. WARM REFLECTED GOLD FLUSH ON THE UNDERSIDE OF EACH BERRY
  // Bouncing up from the gleaming golden-ochre lacquer tray onto the lower crescent
  let goldArc1 = [];
  let goldArc2 = [];
  for (let a = 12; a <= 138; a += 14) {
    let u = sin(map(a, 12, 138, 0, 180));
    let px1 = x + cos(a) * (r * 0.84);
    let py1 = y + sin(a) * (r * 0.84);
    goldArc1.push([px1, py1, 0.35 + 0.85 * u]);

    let px2 = x + cos(a) * (r * 0.91);
    let py2 = y + sin(a) * (r * 0.91);
    goldArc2.push([px2, py2, 0.25 + 0.75 * u]);
  }
  brush.set("berry_shader", PAL.goldGleam, r * 0.036);
  brush.spline(goldArc1, 0.45);

  brush.set("calligraphy", PAL.goldLuminous, r * 0.025);
  brush.spline(goldArc2, 0.45);

  // Subtle vermilion-gold transition between the gold underside and crimson core
  brush.set("berry_shader", PAL.vermilion, r * 0.028);
  brush.spline(goldArc1.map(p => [p[0] - 1.5, p[1] - 2.2, p[2] * 0.8]), 0.45);

  // 5. Crisp wet contour edge around the berry sphere
  brush.set("rotring", PAL.crimsonDark, 0.35);
  brush.arc(x, y, r * 0.98, -20, 165);
  brush.set("rotring", PAL.scarletCore, 0.28);
  brush.arc(x, y, r * 0.98, 165, 340);

  // 6. TINY DARK CALYX (4-pointed indented blossom crown of Vaccinium vitis-idaea)
  if (b.showCalyx) {
    let cx = x + cos(b.calyxAng) * b.calyxDist;
    let cy = y + sin(b.calyxAng) * b.calyxDist;
    let cSize = r * 0.19;
    // Foreshorten calyx along the radial surface normal
    let foreshorten = map(b.calyxDist, 0, r * 0.75, 0.95, 0.52);

    // Indented calyx rim shadow
    drawEllipseWash(cx, cy, cSize * 1.15, cSize * 1.15 * foreshorten, b.calyxAng + 90, PAL.crimsonDark, 210);
    drawEllipseWash(cx, cy, cSize * 0.72, cSize * 0.72 * foreshorten, b.calyxAng + 90, PAL.blackDeep, 245);

    // 4 tiny pointed dark sepals with a touch of warm bronze-gold on the lit sepal tips
    for (let s = 0; s < 4; s++) {
      let sAng = b.calyxAng + s * 90 + 45;
      let sx = cx + cos(sAng) * cSize * 1.25;
      let sy = cy + sin(sAng) * cSize * 1.25 * foreshorten;
      let b1x = cx + cos(sAng - 28) * cSize * 0.55;
      let b1y = cy + sin(sAng - 28) * cSize * 0.55 * foreshorten;
      let b2x = cx + cos(sAng + 28) * cSize * 0.55;
      let b2y = cy + sin(sAng + 28) * cSize * 0.55 * foreshorten;

      resetBrushState();
      brush.noStroke();
      brush.wash(PAL.blackLamp, 240);
      drawCustomShape([[b1x, b1y], [sx, sy], [b2x, b2y]]);
      resetBrushState();

      brush.set("rotring", s < 2 ? PAL.goldBright : PAL.blackDeep, 0.28);
      brush.line(b1x, b1y, sx, sy);
    }
    // Tiny central pistil dot
    drawPaintedDot(cx, cy, cSize * 0.22, PAL.goldOchre);
  }

  // 7. SHARP WHITE WINDOW HIGHLIGHT (Curved studio window reflection on upper-left dome)
  drawWindowHighlight(x, y, r, b.rotHighlight, shade);
}

function drawWindowHighlight(bx, by, r, rotOffset, shade) {
  resetBrushState();
  // Upper-left specular zone at ~222 degrees
  let baseAng = 222 + rotOffset * 0.4;
  let hDist = r * 0.48;

  // Soft warm glow halo behind the crisp window panes
  let hx = bx + cos(baseAng) * hDist;
  let hy = by + sin(baseAng) * hDist;
  drawEllipseWash(hx, hy, r * 0.34, r * 0.22, baseAng + 90, PAL.vermilionGlow, 110);

  // Draw a 2x2 curved window-pane reflection warped to the sphere's curvature
  let paneAngles = [
    { a1: baseAng - 18, a2: baseAng - 2, r1: r * 0.58, r2: r * 0.44 },
    { a1: baseAng + 3,  a2: baseAng + 18, r1: r * 0.58, r2: r * 0.44 },
    { a1: baseAng - 16, a2: baseAng - 2, r1: r * 0.40, r2: r * 0.30 },
    { a1: baseAng + 3,  a2: baseAng + 16, r1: r * 0.40, r2: r * 0.30 }
  ];

  let op = shade > 0.35 ? 215 : 250;
  for (let i = 0; i < paneAngles.length; i++) {
    let p = paneAngles[i];
    let poly = [
      [bx + cos(p.a1) * p.r1, by + sin(p.a1) * p.r1],
      [bx + cos(p.a2) * p.r1, by + sin(p.a2) * p.r1],
      [bx + cos(p.a2) * p.r2, by + sin(p.a2) * p.r2],
      [bx + cos(p.a1) * p.r2, by + sin(p.a1) * p.r2]
    ];
    brush.noStroke();
    brush.wash(i < 2 ? PAL.windowWhite : PAL.windowWarm, i < 2 ? op : op * 0.78);
    drawCustomShape(poly);
  }
  resetBrushState();

  // Razor-sharp wet specular edge stroke on the top window pane
  let topArc = [
    [bx + cos(baseAng - 17) * r * 0.56, by + sin(baseAng - 17) * r * 0.56, 0.9],
    [bx + cos(baseAng - 3) * r * 0.57, by + sin(baseAng - 3) * r * 0.57, 1.1],
    [bx + cos(baseAng + 16) * r * 0.55, by + sin(baseAng + 16) * r * 0.55, 0.8]
  ];
  brush.set("window_gloss", PAL.windowWhite, r * 0.026);
  brush.spline(topArc, 0.35);

  // Secondary pinpoint wet catchlight near the upper rim
  let px = bx + cos(baseAng + 28) * r * 0.62;
  let py = by + sin(baseAng + 28) * r * 0.62;
  brush.noStroke();
  brush.wash(PAL.windowWhite, 235);
  brush.circle(px, py, max(1.6, r * 0.065), 0.05);
  resetBrushState();
}

// ============================================================================
// 10. WEAVING FINE PEN TENDRILS & DROPLET DOTS (DECORATION MEETS HARVEST)
// ============================================================================
function drawWeavingTendrilsAndDroplets() {
  resetBrushState();

  // Fine pen tendrils in lamp black, cinnabar, and burnished gold weaving between the berries
  for (let i = 0; i < berries.length; i++) {
    let b = berries[i];
    if (b.tier === "ladle_back") continue;

    // Selectively sprout delicate calligraphic tendrils from the gaps around spilled berries
    if (i % 2 === 0) {
      let startAng = random(-75, 165);
      let sx = b.x + cos(startAng) * (b.r + 5);
      let sy = b.y + sin(startAng) * (b.r + 5);
      let tendrilLen = random(55, 135);
      let curl = random() < 0.5 ? 1 : -1;

      let col = i % 6 === 0 ? PAL.cinnabar :
                (i % 6 === 2 ? PAL.goldBright : PAL.blackLamp);

      drawSpiralPenTendril(sx, sy, startAng + curl * 35, tendrilLen, curl, col);
    }

    // Rhythmic chains of droplet dots weaving around the fruit contour
    if (i % 3 === 1) {
      let baseAng = random(-40, 140);
      let curl = random() < 0.5 ? 1 : -1;
      for (let d = 0; d < 6; d++) {
        let a = baseAng + d * 18 * curl;
        let rad = b.r + 12 + d * 9;
        let dx = b.x + cos(a) * rad;
        let dy = b.y + sin(a) * rad;
        if (!isInsideAnyBerry(dx, dy, 4)) {
          let dotR = map(d, 0, 5, 5.5, 1.6);
          let isWetJuiceDrop = d < 2 && i % 2 === 1;
          if (isWetJuiceDrop) {
            drawGlossyJuiceDroplet(dx, dy, dotR);
          } else {
            let dotCol = d % 2 === 0 ? PAL.cinnabar : PAL.blackLamp;
            drawPaintedDot(dx, dy, dotR, dotCol);
          }
        }
      }
    }
  }

  // Extra sweeping S-curve pen flourishes & berry-juice splashes around the cascade edges
  const extraFlourishes = [
    { x: 355, y: 525, ang: 155, len: 145, curl: 1.2, col: PAL.blackLamp },
    { x: 645, y: 415, ang: -25, len: 155, curl: -1.1, col: PAL.cinnabar },
    { x: 785, y: 585, ang: 15, len: 165, curl: 1.15, col: PAL.blackLamp },
    { x: 455, y: 815, ang: 115, len: 150, curl: 1.2, col: PAL.cinnabar },
    { x: 715, y: 865, ang: 45, len: 160, curl: -1.2, col: PAL.blackLamp },
    { x: 855, y: 745, ang: 25, len: 135, curl: 1.1, col: PAL.scarletBright },
    { x: 315, y: 695, ang: 135, len: 140, curl: -1.15, col: PAL.blackLamp }
  ];

  for (let fl of extraFlourishes) {
    drawSpiralPenTendril(fl.x, fl.y, fl.ang, fl.len, fl.curl, fl.col);
    drawSpiralPenTendril(fl.x + 6, fl.y + 5, fl.ang + 12, fl.len * 0.72, -fl.curl * 0.9, PAL.goldBright);
  }

  // Scattered glossy scarlet juice droplets & tiny lamp-black ink dots across the tray
  for (let i = 0; i < 65; i++) {
    let angle = random(0, 360);
    let distFromSpill = random(40, 390);
    let dx = 595 + cos(angle) * distFromSpill;
    let dy = 625 + sin(angle) * distFromSpill * 0.85;
    if (!isInsideAnyBerry(dx, dy, 8)) {
      if (i % 3 === 0) {
        drawGlossyJuiceDroplet(dx, dy, random(2.5, 6.2));
      } else {
        let col = i % 3 === 1 ? PAL.cinnabar : (random() < 0.7 ? PAL.blackLamp : PAL.goldLuminous);
        drawPaintedDot(dx, dy, random(1.5, 4.5), col);
      }
    }
  }
}

function drawSpiralPenTendril(x, y, startAng, length, curlDir, col) {
  let pts = [];
  let cx = x, cy = y;
  let ang = startAng;
  let steps = 18;
  let stepLen = length / steps;

  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    if (isInsideAnyBerry(cx, cy, -2) && i > 2) break;
    let pr = map(1 - u, 0, 1, 0.15, 0.95);
    pts.push([cx, cy, pr]);
    ang += (3 + pow(u, 1.8) * 32) * curlDir;
    cx += cos(ang) * stepLen * (1 - u * 0.3);
    cy += sin(ang) * stepLen * (1 - u * 0.3);
  }

  if (pts.length >= 3) {
    brush.set("rotring", col, 0.48);
    brush.spline(pts, 0.5);

    // Whisker offshoot at mid-tendril
    let midIdx = floor(pts.length * 0.5);
    let mp = pts[midIdx];
    let wPts = [
      [mp[0], mp[1], 0.6],
      [mp[0] + cos(ang - 45 * curlDir) * 18, mp[1] + sin(ang - 45 * curlDir) * 18, 0.4],
      [mp[0] + cos(ang - 85 * curlDir) * 28, mp[1] + sin(ang - 85 * curlDir) * 28, 0.15]
    ];
    brush.set("pen", col, 0.32);
    brush.spline(wPts, 0.45);
  }
}

function drawGlossyJuiceDroplet(x, y, r) {
  resetBrushState();
  brush.noStroke();
  // Tiny cast shadow
  brush.wash(PAL.blackDeep, 180);
  brush.circle(x + r * 0.35, y + r * 0.42, r * 0.95, 0.08);
  // Crimson-vermilion droplet body
  brush.wash(PAL.crimsonRich, 235);
  brush.circle(x, y, r, 0.08);
  brush.wash(PAL.vermilion, 195);
  brush.circle(x - r * 0.2, y - r * 0.2, r * 0.65, 0.06);
  // Gold underside reflection
  brush.wash(PAL.goldLuminous, 165);
  brush.circle(x + r * 0.22, y + r * 0.28, r * 0.45, 0.05);
  // Tiny white window highlight dot
  brush.wash(PAL.windowWhite, 245);
  brush.circle(x - r * 0.32, y - r * 0.32, max(1.1, r * 0.28), 0.04);
  resetBrushState();
}

// ============================================================================
// 11. FINAL STUDIO SPECULAR SHEEN & DUSKY TWILIGHT VIGNETTE
// ============================================================================
function drawFinalGlazeAndVignette() {
  resetBrushState();

  // Subtle twilight corner darkening to focus the eye on the gleaming golden-ochre center
  const corners = [
    { x: 60, y: 1120, rx: 280, ry: 220, a: 35 },
    { x: 1140, y: 80, rx: 290, ry: 230, a: 35 },
    { x: 1140, y: 1140, rx: 260, ry: 210, a: -35 }
  ];
  for (let c of corners) {
    drawEllipseWash(c.x, c.y, c.rx, c.ry, c.a, PAL.blackDeep, 145);
  }

  // Fine golden-ochre & vermilion atmospheric dust motes catching the window light
  brush.set("spray", PAL.goldLuminous, 0.45);
  brush.line(360, 360, 740, 720);
  brush.set("spray", PAL.cinnabar, 0.35);
  brush.line(460, 480, 680, 660);

  resetBrushState();
}

// ============================================================================
// GEOMETRY & BRUSH UTILITY FUNCTIONS
// ============================================================================
function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
}

function drawEllipseWash(cx, cy, rx, ry, rotDeg, col, opacity) {
  resetBrushState();
  brush.noStroke();
  brush.wash(col, opacity);
  drawRotatedPoly(cx, cy, rx, ry, rotDeg, 28);
  resetBrushState();
}

function drawRotatedPoly(cx, cy, rx, ry, rotDeg, steps) {
  brush.beginShape(0.35);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let lx = cos(a) * rx;
    let ly = sin(a) * ry;
    let x = cx + lx * cos(rotDeg) - ly * sin(rotDeg);
    let y = cy + lx * sin(rotDeg) + ly * cos(rotDeg);
    brush.vertex(x, y);
  }
  brush.endShape(true);
}

function drawCustomShape(pts) {
  brush.beginShape(0.25);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

function samplePolyline(pts, t) {
  let totalSegs = pts.length - 1;
  let scaled = constrain(t, 0, 0.9999) * totalSegs;
  let idx = floor(scaled);
  let frac = scaled - idx;
  return {
    x: lerp(pts[idx][0], pts[idx + 1][0], frac),
    y: lerp(pts[idx][1], pts[idx + 1][1], frac)
  };
}

function sampleTangent(pts, t) {
  let totalSegs = pts.length - 1;
  let idx = constrain(floor(t * totalSegs), 0, totalSegs - 1);
  return atan2(pts[idx + 1][1] - pts[idx][1], pts[idx + 1][0] - pts[idx][0]);
}

function isNearAnyBerry(x, y, maxDist) {
  for (let b of berries) {
    if (dist(x, y, b.x, b.y) < b.r + maxDist) return true;
  }
  return false;
}

function isInsideAnyBerry(x, y, margin) {
  for (let b of berries) {
    if (dist(x, y, b.x, b.y) < b.r + margin) return true;
  }
  return false;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(8319);

  // Custom brushes for forensic detail, leatherette grain, and optical glare
  brush.add("pebble", {
    type: "custom",
    weight: 2.2,
    scatter: 0.35,
    opacity: 140,
    spacing: 0.85,
    pressure: [0.7, 1.3, 0.7],
    tip: (_m) => {
      _m.rotate(30);
      _m.ellipse(0, 0, 2.2, 1.6);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.8
  });

  brush.add("flatPoster", {
    type: "marker",
    weight: 18,
    scatter: 0.08,
    opacity: 42,
    spacing: 0.25,
    pressure: [0.95, 1.0, 0.95],
    markerTip: false,
    noise: 0.2
  });

  brush.add("microInk", {
    type: "default",
    weight: 0.32,
    scatter: 0.03,
    sharpness: 0.92,
    grain: 0.25,
    opacity: 210,
    spacing: 0.12,
    pressure: [0.4, 1.1, 0.3],
    noise: 0.35
  });

  brush.add("glaze", {
    type: "spray",
    weight: 9,
    scatter: 2.8,
    opacity: 28,
    spacing: 0.4,
    pressure: [0.5, 1.2, 0.5],
    noise: 0.5
  });

  background("#efe3cc");
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. VINTAGE CREAM PAPER GROUND & STACKED POSTER BANDS (MARKER + SPRAY)
  // =========================================================================
  drawPosterBackground();

  // =========================================================================
  // 2. GRAPHIC & AMBIENT SHADOW CAST ONTO THE POSTER BANDS
  // =========================================================================
  drawCastShadows();

  // =========================================================================
  // 3. RANGER'S WRISTS, FIELD CUFFS & VINTAGE WATCH
  // =========================================================================
  drawWristsAndCuffs();

  // =========================================================================
  // 4. HYPERREAL BINOCULARS: CHASSIS, PRISM HOUSINGS, BRIDGE & LEATHERETTE
  // =========================================================================
  drawBinocularBody();

  // =========================================================================
  // 5. SCUFFED BRASS BEZELS, BAFFLES & SUNSET CANYON LENS REFLECTIONS
  // =========================================================================
  drawObjectiveLensAssembly(415, 585, -1); // Left lens
  drawObjectiveLensAssembly(785, 585, 1);  // Right lens

  // =========================================================================
  // 6. RANGER'S WEATHERED HANDS GRIPPING THE BARRELS
  // =========================================================================
  drawWeatheredHand(-1); // Left hand
  drawWeatheredHand(1);  // Right hand

  // =========================================================================
  // 7. FRAYED CANVAS & LEATHER STRAP
  // =========================================================================
  drawFrayedStrap();

  // =========================================================================
  // 8. POSTER BORDER TRIM & FINAL OPTICAL SPECULARS
  // =========================================================================
  drawFinalHighlightsAndBorder();

  noLoop();
}

// ===========================================================================
// HELPER: POLY SHAPE FILL + WASH + HATCH
// ===========================================================================
function drawPolyShape(pts, curvature = 0.08, closeShape = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape ? CLOSE : undefined);
}

// ===========================================================================
// 1. POSTER BACKGROUND: STACKED FLAT BANDS OF TEAL, CREAM, MUSTARD & SIENNA
// ===========================================================================
function drawPosterBackground() {
  const px1 = 96;
  const px2 = 1104;
  const pw = px2 - px1;

  // Paper grain across entire sheet
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("spray", "#d6c3a3", 1.4);
  for (let i = 0; i < 45; i++) {
    let y = map(i, 0, 44, 20, 1180);
    brush.line(20, y + random(-8, 8), 1180, y + random(-8, 8));
  }

  // Band definitions: [yStart, yEnd, baseHex, markerHex1, markerHex2, sprayHex]
  const bands = [
    [68, 225, "#1f3f47", "#19353c", "#2c545e", "#3f6d75"],   // Deep slate teal sky
    [225, 345, "#365f66", "#2c5157", "#4b777d", "#7a9c99"],  // Muted canyon teal
    [345, 455, "#e8d8b9", "#dfd0b0", "#f2e5cb", "#d49b3d"],  // High desert cream
    [455, 620, "#d49535", "#c48325", "#e0a648", "#9e4324"],  // Mustard ochre sun band
    [620, 795, "#9e4224", "#8a3419", "#b35130", "#592011"],  // Upper burnt sienna band
    [795, 955, "#782d18", "#662310", "#8f3920", "#c98932"],  // Deep sienna / terracotta
    [955, 1045, "#b8792c", "#a36820", "#cc8a3b", "#4f2213"], // Narrow lower mustard strata
    [1045, 1132, "#21363b", "#18292e", "#2d474d", "#6e2e19"] // Base deep teal-umber band
  ];

  // Base washes for each band
  brush.noStroke();
  for (let b of bands) {
    let [y1, y2, baseCol] = b;
    brush.wash(baseCol, 235);
    brush.rect(px1, y1, pw, y2 - y1, "corner");
  }
  brush.noWash();

  // Layered opaque marker passes inside each band
  for (let b of bands) {
    let [y1, y2, , mCol1, mCol2, spCol] = b;
    let bh = y2 - y1;

    // Horizontal flat marker sweeps
    brush.set("flatPoster", mCol1, 1.15);
    for (let y = y1 + 10; y < y2 - 6; y += 18) {
      let jitterY = random(-2.5, 2.5);
      brush.line(px1 + 4, y + jitterY, px2 - 4, y - jitterY);
    }

    brush.set("marker", mCol2, 1.4);
    for (let y = y1 + 14; y < y2 - 8; y += 26) {
      brush.line(px1 + random(4, 30), y, px2 - random(4, 30), y + random(-2, 2));
    }

    // Layered spray grain along band transitions
    brush.set("spray", spCol, 1.1);
    for (let i = 0; i < 10; i++) {
      let sy = lerp(y2 - 24, y2 + 12, i / 9);
      brush.line(px1 + 10, sy + random(-4, 4), px2 - 10, sy + random(-4, 4));
    }
  }

  // Graphic stepped mesa & solar arch inside the cream/mustard bands (above horizon)
  brush.noStroke();
  brush.wash("#e8b65a", 190);
  brush.circle(600, 480, 195, 0.04);
  brush.noWash();

  brush.set("marker", "#ede0c4", 1.2);
  for (let r = 30; r < 180; r += 16) {
    brush.arc(600, 480, r, 185, 355);
  }

  // Flat poster mesa silhouettes sitting on the horizon line (y = 620)
  const mesaLeft = [
    [98, 620], [98, 520], [185, 520], [215, 558], [310, 558], [335, 620]
  ];
  const mesaRight = [
    [865, 620], [890, 545], [965, 545], [990, 505], [1102, 505], [1102, 620]
  ];
  brush.noStroke();
  brush.wash("#7d3019", 230);
  drawPolyShape(mesaLeft, 0.02);
  drawPolyShape(mesaRight, 0.02);
  brush.noWash();

  brush.hatchStyle("marker", "#5e2110", 0.7);
  brush.hatch(9, 0, { rand: 0.03 });
  drawPolyShape(mesaLeft, 0.02);
  drawPolyShape(mesaRight, 0.02);
  brush.noHatch();

  // BOLD HORIZON LINE cutting behind the hands at y = 620
  brush.noStroke();
  brush.wash("#26130d", 250);
  brush.rect(px1 - 6, 613, pw + 12, 16, "corner");
  brush.noWash();

  brush.set("marker", "#1c0d09", 1.5);
  brush.line(px1 - 6, 617, px2 + 6, 617);
  brush.line(px1 - 6, 624, px2 + 6, 624);

  brush.set("marker", "#f0dfc0", 0.8);
  brush.line(px1, 611, px2, 611);
  brush.set("marker", "#c97b28", 0.7);
  brush.line(px1, 631, px2, 631);
}

