// Helper for pebble-grain worn leatherette texture on flat/curved prism zones
function drawLeatherettePatch(x, y, w, h, side) {
  // Base subtle cross-hatch
  brush.hatchStyle("2B", "#262c30", 0.45);
  brush.hatch(5, 35, { rand: 0.12 });
  brush.noStroke();
  brush.rect(x, y, w, h, "corner");
  brush.noHatch();

  // Pebble grain strokes
  for (let row = 0; row < h; row += 6.5) {
    let py = y + row;
    brush.set("pebble", row % 13 < 6 ? "#30383d" : "#0b0d0f", 0.55);
    brush.line(x + 6, py + random(-1.5, 1.5), x + w - 6, py + random(-1.5, 1.5));
  }

  // Worn scuffs exposing brownish vulcanite and raw brass at edges
  brush.set("microInk", "#8a6832", 0.55);
  for (let i = 0; i < 14; i++) {
    let sx = x + (side === -1 ? random(4, 32) : w - random(4, 32));
    let sy = y + random(8, h - 8);
    brush.line(sx, sy, sx + random(-10, 10), sy + random(-4, 4));
  }
}

// Helper for cylindrical leatherette around objective barrels
function drawLeatheretteCylinder(cx, cy, rMax, angStart, angEnd) {
  for (let a = angStart; a <= angEnd; a += 4.5) {
    let rad = rMax - random(2, 16);
    let x1 = cx + cos(a) * (rad + 8);
    let y1 = cy + sin(a) * (rad + 8) - 22;
    let x2 = cx + cos(a) * (rad - 4);
    let y2 = cy + sin(a) * (rad - 4);

    // Highlight near upper-left (225..265 deg)
    let isLit = a > 220 && a < 275;
    let col = isLit ? "#465259" : (a > 275 && a < 315 ? "#293036" : "#0e1114");
    brush.set("pebble", col, 0.5);
    brush.line(x1, y1, x2, y2);

    if (isLit && random() < 0.45) {
      brush.set("microInk", "#7f9199", 0.45);
      brush.line(x1, y1, (x1 + x2) * 0.5, (y1 + y2) * 0.5);
    }
  }
}

// ===========================================================================
// 5. OBJECTIVE LENS ASSEMBLY: SCUFFED BRASS, BAFFLES, CANYON & LENS FLARE
// ===========================================================================
function drawObjectiveLensAssembly(cx, cy, side) {
  const rOuter = 160;
  const rBrass = 148;
  const rBaffle = 134;
  const rGlass = 116;

  // 1. Cast drop-ring shadow of barrel
  brush.noStroke();
  brush.wash("#0d0b0a", 240);
  brush.circle(cx, cy + 8, rOuter + 4, 0.02);

  // 2. Outer vulcanite/leatherette armor ring (R = 148..160)
  brush.wash("#181b1f", 252);
  brush.circle(cx, cy, rOuter, 0.02);
  brush.noWash();

  // Pebble texture & specular rim on outer leatherette ring
  for (let a = 0; a < 360; a += 6) {
    let rMid = (rOuter + rBrass) * 0.5;
    let px = cx + cos(a) * rMid;
    let py = cy + sin(a) * rMid;
    let col = (a > 205 && a < 265) ? "#526069" : ((a > 45 && a < 135) ? "#3b2318" : "#0c0e11");
    brush.set("pebble", col, 0.45);
    brush.line(px, py, px + cos(a + 90) * 6, py + sin(a + 90) * 6);
  }

  // 3. SCUFFED BRASS BEZEL RING (R = 134..148)
  // Base tarnished bronze ring
  brush.noStroke();
  brush.wash("#241909", 252);
  brush.circle(cx, cy, rBrass, 0.015);
  brush.noWash();

  // Radial & circumferential metallic brass modulation + scuffs where black paint wore off
  for (let a = 0; a < 360; a += 2.5) {
    let r1 = rBaffle + 1;
    let r2 = rBrass - 1;
    let x1 = cx + cos(a) * r1;
    let y1 = cy + sin(a) * r1;
    let x2 = cx + cos(a) * r2;
    let y2 = cy + sin(a) * r2;

    // Determine whether this angle is exposed scuffed brass or remnant chipped black paint
    let wearNoise = noise(cx * 0.01 + cos(a) * 1.8, sin(a) * 1.8);
    let col;
    if (wearNoise < 0.34) {
      // Remaining black anodized paint patch
      col = (a > 210 && a < 265) ? "#333a40" : "#15181c";
    } else {
      // Exposed scuffed brass with anisotropic metallic reflection
      if (a > 205 && a < 255) col = "#fae096";       // Bright specular brass
      else if (a > 180 && a < 285) col = "#cf9f44";  // Warm gold brass
      else if (a > 35 && a < 95) col = "#e0b258";    // Secondary bounce highlight
      else if (a > 95 && a < 165) col = "#8f6322";   // Sienna bounce brass
      else col = "#4d3410";                          // Dark tarnished bronze
    }
    brush.set("microInk", col, 0.9);
    brush.line(x1, y1, x2, y2);
  }

  // Fine concentric lathe turn lines & sharp edge nicks on the brass bezel
  brush.set("microInk", "#fff3c4", 0.75);
  brush.arc(cx, cy, rBrass - 2, 200, 265);
  brush.arc(cx, cy, rBaffle + 3, 210, 255);
  brush.arc(cx, cy, rBrass - 5, 42, 88);

  // Tiny silver/gold edge dings & scratches across the bezel
  for (let i = 0; i < 28; i++) {
    let a = random(360);
    let r = random(rBaffle + 2, rBrass - 2);
    let sx = cx + cos(a) * r;
    let sy = cy + sin(a) * r;
    brush.set("microInk", random() < 0.5 ? "#ffe8a3" : "#211506", 0.55);
    brush.line(sx, sy, sx + random(-7, 7), sy + random(-7, 7));
  }

  // 4. DEEP THREADED INTERNAL SUN-BAFFLE (R = 116..134)
  brush.noStroke();
  brush.wash("#0d0f13", 254);
  brush.circle(cx, cy, rBaffle, 0.01);
  brush.noWash();

  // Concentric milled anti-reflection baffle threads
  for (let r = rGlass + 2; r < rBaffle; r += 3.2) {
    brush.set("microInk", "#1e242b", 0.65);
    brush.circle(cx, cy, r, 0.008);
    // Warm canyon bounce light caught on bottom-right baffle threads
    brush.set("microInk", "#734b29", 0.6);
    brush.arc(cx, cy, r, 25, 115);
    // Cool sky light caught on upper-left baffle threads
    brush.set("microInk", "#546b75", 0.55);
    brush.arc(cx, cy, r, 205, 260);
  }

  // 5. MINIATURE SUNSET CANYON REFLECTION INSIDE THE TWIN LENSES (R = 116)
  drawLensCanyonReflection(cx, cy, rGlass, side);

  // 6. COATED LENS FLARE IN AMBER & VIOLET + GLASS SPECULARITY
  drawLensOpticalCoatingAndFlare(cx, cy, rGlass, side);
}

function drawLensCanyonReflection(cx, cy, rGlass, side) {
  // Helper to get chord width at vertical offset dy inside circle of radius R
  const chordHalfWidth = (dy, rad = rGlass - 1) => {
    if (abs(dy) >= rad) return 0;
    return sqrt(rad * rad - dy * dy);
  };

  // Base deep optical cavity
  brush.noStroke();
  brush.wash("#140d1c", 255);
  brush.circle(cx, cy, rGlass, 0.008);
  brush.noWash();

  // ---- A. MINIATURE SUNSET SKY (Upper half of lens: dy from -rGlass to +10) ----
  for (let dy = -rGlass + 3; dy <= 12; dy += 2.6) {
    let hw = chordHalfWidth(dy);
    if (hw < 4) continue;
    let t = map(dy, -rGlass + 3, 12, 0, 1);

    // Spherical barrel-distortion curve: arch slightly upward in center
    let arch = (1 - abs(dy / rGlass)) * 14;
    let yLeft = cy + dy + arch * 0.35;
    let yMid = cy + dy - arch * 0.65;
    let yRight = cy + dy + arch * 0.35;

    let skyCol;
    if (t < 0.22) skyCol = "#264752";       // High zenith teal
    else if (t < 0.45) skyCol = "#5c7a78";  // Dusty horizon sage
    else if (t < 0.68) skyCol = "#e8cf9c";  // Glowing cream-gold
    else if (t < 0.86) skyCol = "#e39836";  // Radiant sunset mustard-amber
    else skyCol = "#c75824";                // Fiery vermilion-sienna horizon glow

    brush.set("marker", skyCol, 0.42);
    brush.spline([
      [cx - hw + 2, yLeft, 0.7],
      [cx, yMid, 1.0],
      [cx + hw - 2, yRight, 0.7]
    ], 0.35);
  }

  // Miniature setting sun orb reflected inside each lens
  let sunX = cx - side * 12;
  let sunY = cy - 22;
  brush.noStroke();
  brush.wash("#fff2c9", 220);
  brush.circle(sunX, sunY, 22, 0.03);
  brush.wash("#f5a638", 140);
  brush.circle(sunX, sunY, 36, 0.04);
  brush.noWash();

  // ---- B. MINIATURE CANYON BUTTES, MESAS & GORGE STRATA ----
  // Distant purple-sienna canyon rim (dy around -8 to +25)
  let distantRim = [];
  const rimProfile = [
    [-0.95, 2], [-0.78, 2], [-0.70, -18], [-0.46, -18], [-0.38, -4],
    [-0.18, -4], [-0.10, -28], [0.16, -28], [0.24, -6], [0.48, -6],
    [0.56, -22], [0.80, -22], [0.86, 0], [0.96, 2]
  ];
  for (let pt of rimProfile) {
    let px = cx + pt[0] * (rGlass - 4);
    let py = cy + pt[1];
    distantRim.push([px, py]);
  }
  // Close polygon along lower chord
  for (let a = 15; a <= 165; a += 15) {
    distantRim.push([cx + cos(a) * (rGlass - 3), cy + sin(a) * (rGlass - 3)]);
  }
  brush.noStroke();
  brush.wash("#592329", 235);
  drawPolyShape(distantRim, 0.03);
  brush.noWash();

  // Midground stratified burnt-sienna canyon cliffs with sunlit amber faces
  for (let dy = 2; dy < rGlass - 6; dy += 3.2) {
    let hw = chordHalfWidth(dy, rGlass - 3);
    if (hw < 8) continue;
    let t = map(dy, 2, rGlass - 6, 0, 1);

    // Canyon gorge V-cut in center where river winds
    let riverCenter = cx + sin(t * 180 + side * 20) * 16 * (1 - t * 0.4);
    let gorgeHalfWidth = lerp(8, 28, pow(t, 0.85));

    // Left cliff wall strata (curved by spherical lens)
    let leftEdge = cx - hw + 2;
    let leftCliffEnd = max(leftEdge + 4, riverCenter - gorgeHalfWidth);
    let strataColL = (int(dy / 6) % 2 === 0)
      ? (t < 0.5 ? "#b54926" : "#802918")
      : (t < 0.5 ? "#d97b2e" : "#4a1b24");

    if (leftCliffEnd > leftEdge + 5) {
      brush.set("rotring", strataColL, 1.3);
      brush.spline([
        [leftEdge, cy + dy + 5, 0.8],
        [(leftEdge + leftCliffEnd) * 0.5, cy + dy, 1.1],
        [leftCliffEnd, cy + dy + 3, 0.9]
      ], 0.3);
    }

    // Right cliff wall strata (shadowed teal-violet & deep sienna with sunlit rim)
    let rightEdge = cx + hw - 2;
    let rightCliffStart = min(rightEdge - 4, riverCenter + gorgeHalfWidth);
    let strataColR = (int(dy / 6) % 2 === 0)
      ? (t < 0.5 ? "#6e272c" : "#301729")
      : (t < 0.5 ? "#9c3e25" : "#1f2a38");

    if (rightEdge > rightCliffStart + 5) {
      brush.set("rotring", strataColR, 1.3);
      brush.spline([
        [rightCliffStart, cy + dy + 3, 0.9],
        [(rightCliffStart + rightEdge) * 0.5, cy + dy, 1.1],
        [rightEdge, cy + dy + 5, 0.8]
      ], 0.3);

      // Sunlit amber rim on the inner cliff edge facing the setting sun
      brush.set("microInk", "#f5a13b", 0.85);
      brush.line(rightCliffStart, cy + dy + 2, rightCliffStart + 9, cy + dy + 1);
    }

    // Glowing sunset river ribbon winding through bottom of canyon gorge
    if (leftCliffEnd < rightCliffStart - 2) {
      let rivCol = t < 0.45 ? "#ffdf94" : (t < 0.78 ? "#f09535" : "#9c4bc4");
      brush.set("microInk", rivCol, 1.0);
      brush.line(leftCliffEnd + 2, cy + dy + 3, rightCliffStart - 2, cy + dy + 3);
    }
  }

  // Vertical cliff fissures & rock spires inside the miniature canyon
  brush.set("microInk", "#2b0e17", 0.65);
  for (let kx = -85; kx <= 85; kx += 11) {
    let xPos = cx + kx;
    let yTop = cy - (abs(kx) > 30 ? 18 : 2);
    let yBot = cy + min(chordHalfWidth(kx, rGlass - 8), 75);
    if (yBot > yTop + 8) {
      brush.line(xPos, yTop + random(0, 12), xPos + random(-3, 3), yBot - random(4, 18));
    }
  }
}

function drawLensOpticalCoatingAndFlare(cx, cy, rGlass, side) {
  // ---- A. MULTI-COATED OPTICAL BLOOM: VIOLET & AMBER ----
  brush.noStroke();

  // Deep violet-magenta anti-reflective coating wash (lower-right & diagonal)
  brush.fill("#7329ab", 75);
  brush.fillBleed(0.3, "in");
  brush.fillTexture(0.35, 0.15);
  brush.circle(cx + 28, cy + 32, 74, 0.04);

  brush.fill("#a94be8", 62);
  brush.circle(cx + 42, cy + 44, 48, 0.05);

  // Warm amber-gold coating flare (upper-left & opposite diagonal)
  brush.fill("#f29422", 72);
  brush.circle(cx - 32, cy - 30, 72, 0.04);

  brush.fill("#ffd166", 65);
  brush.circle(cx - 46, cy - 42, 42, 0.04);
  brush.noFill();

  // Spray optical bloom along the flare axis (135 deg to 315 deg)
  brush.set("glaze", "#b35cf5", 1.1);
  for (let i = 0; i < 8; i++) {
    let a = random(20, 115);
    let r = random(35, rGlass - 14);
    brush.arc(cx, cy, r, a, a + 45);
  }

  brush.set("glaze", "#ffa72b", 1.1);
  for (let i = 0; i < 8; i++) {
    let a = random(195, 290);
    let r = random(35, rGlass - 14);
    brush.arc(cx, cy, r, a, a + 45);
  }

  // ---- B. INTERNAL APERTURE GHOST HEXAGONS / RINGS (Amber & Violet) ----
  const ghosts = [
    { off: -52, r: 28, col: "#ffd97d", w: 0.7 },
    { off: -24, r: 42, col: "#f59e2d", w: 0.6 },
    { off: 18,  r: 36, col: "#b668f7", w: 0.65 },
    { off: 48,  r: 22, col: "#e09eff", w: 0.75 },
    { off: 64,  r: 12, col: "#ffbe5c", w: 0.8 }
  ];

  for (let g of ghosts) {
    let gx = cx + cos(315) * g.off;
    let gy = cy + sin(315) * g.off;
    // Draw subtle hexagonal aperture ghost
    let hexPts = [];
    for (let k = 0; k < 6; k++) {
      let ang = k * 60 + 15;
      hexPts.push([gx + cos(ang) * g.r, gy + sin(ang) * g.r]);
    }
    brush.set("microInk", g.col, g.w);
    drawPolyShape(hexPts, 0.04, true);
  }

  // Diagonal lens flare streak across glass
  brush.set("microInk", "#ffe8a8", 0.65);
  brush.line(cx - 72, cy - 68, cx + 68, cy + 64);
  brush.set("microInk", "#d896ff", 0.65);
  brush.line(cx - 58, cy - 62, cx + 74, cy + 56);

  // ---- C. CURVED CONVEX GLASS SPECULAR WINDOW REFLECTION ----
  // Crisp curved cream/white sky highlight hugging upper-left rim
  for (let r = rGlass - 18; r <= rGlass - 6; r += 2.2) {
    brush.set("microInk", r > rGlass - 11 ? "#fff9eb" : "#f7d594", 0.95);
    brush.arc(cx, cy, r, 204, 258);
  }
  // Secondary violet-magenta internal bevel reflection on lower-right rim
  for (let r = rGlass - 10; r <= rGlass - 3; r += 2.2) {
    brush.set("microInk", "#c46eff", 0.85);
    brush.arc(cx, cy, r, 22, 82);
  }
  // Sharp amber rim glint at bottom-left
  brush.set("microInk", "#ffae36", 0.85);
  brush.arc(cx, cy, rGlass - 4, 110, 165);

  // Dark glass seating ring right at rGlass
  brush.set("rotring", "#08090c", 0.95);
  brush.circle(cx, cy, rGlass, 0.006);
}

