function drawWeatheredHand(side) {
  // side = -1 (Left hand gripping left barrel), side = 1 (Right hand gripping right barrel)
  // The hands wrap around the outer leatherette barrels from x ~ 150..325 (left) and 875..1050 (right)

  // 1. Dorsal hand / metacarpal palm wedge behind the fingers
  let palmPts = [
    [600 + side * 320, 445],
    [600 + side * 415, 495],
    [600 + side * 442, 645],
    [600 + side * 395, 795],
    [600 + side * 285, 775],
    [600 + side * 305, 580]
  ];
  brush.noStroke();
  brush.wash("#7d4329", 248);
  drawPolyShape(palmPts, 0.16);
  brush.noWash();

  // Warm sun-baked sienna/ochre grading across back of hand
  brush.hatchStyle("2B", "#592b17", 0.6);
  brush.hatch(5, side === -1 ? 40 : 140, { rand: 0.08 });
  drawPolyShape(palmPts, 0.16);
  brush.noHatch();

  // Raised tendons & prominent veins on the weathered back of hand
  brush.set("2B", "#472010", 0.7);
  for (let k = 0; k < 3; k++) {
    let tx1 = 600 + side * (365 + k * 20);
    let ty1 = 525 + k * 55;
    let tx2 = 600 + side * (340 + k * 14);
    let ty2 = 755 + k * 15;
    brush.spline([
      [tx1, ty1, 0.6],
      [(tx1 + tx2) * 0.5 + side * 12, (ty1 + ty2) * 0.5, 1.2],
      [tx2, ty2, 0.5]
    ], 0.35);

    // Sunlit ridge on tendon
    brush.set("microInk", "#d4966a", 0.65);
    brush.line(tx1 - side * 3, ty1 + 6, (tx1 + tx2) * 0.5 + side * 8, (ty1 + ty2) * 0.5);
    brush.set("2B", "#472010", 0.7);
  }

  // 2. THE THUMB (Resting high on the upper prism shoulder / barrel curve)
  let thumbPts = [
    [600 + side * 355, 465],
    [600 + side * 320, 395],
    [600 + side * 255, 378],
    [600 + side * 212, 398],
    [600 + side * 218, 434],
    [600 + side * 268, 438],
    [600 + side * 318, 488]
  ];
  drawForensicFinger(thumbPts, side, {
    nailX: 600 + side * 226,
    nailY: 408,
    nailW: 24,
    nailH: 17,
    nailAngle: side === -1 ? -15 : 15,
    knuckles: [
      [600 + side * 308, 412, 28],
      [600 + side * 260, 405, 24]
    ],
    isThumb: true
  });

  // 3. FOUR GRIPPING FINGERS WRAPPING THE BARREL EXTERIOR
  // Finger definitions from top (Index) to bottom (Pinky)
  const fingerSpecs = [
    { // Index finger
      yOuter: 495, yMid: 468, yTip: 482,
      xOuter: 422, xMid: 342, xTip: 262,
      thick: 54, nailW: 22, nailH: 18
    },
    { // Middle finger
      yOuter: 568, yMid: 542, yTip: 556,
      xOuter: 444, xMid: 350, xTip: 252,
      thick: 56, nailW: 23, nailH: 19
    },
    { // Ring finger
      yOuter: 644, yMid: 622, yTip: 635,
      xOuter: 434, xMid: 348, xTip: 262,
      thick: 52, nailW: 21, nailH: 17
    },
    { // Little finger (Pinky)
      yOuter: 716, yMid: 702, yTip: 712,
      xOuter: 405, xMid: 336, xTip: 278,
      thick: 44, nailW: 17, nailH: 14
    }
  ];

  for (let idx = 0; idx < fingerSpecs.length; idx++) {
    let f = fingerSpecs[idx];
