  }
}

function drawForensicFinger(pts, side, info) {
  // 1. Base weathered sienna skin wash
  brush.noStroke();
  brush.wash("#9e5d3c", 250);
  drawPolyShape(pts, 0.18);
  brush.noWash();

  // 2. Upper sunlit plane (ochre/peach-tan) & lower shadow plane (deep umber)
  let topStrip = [pts[0], pts[1], pts[2], pts[3], [pts[2][0], pts[2][1] + 18], [pts[1][0], pts[1][1] + 20]];
  brush.noStroke();
  brush.wash("#c98960", 215);
  drawPolyShape(topStrip, 0.15);

  let botStrip = [pts[3], pts[4], pts[5], pts[6], [pts[5][0], pts[5][1] - 18], [pts[4][0], pts[4][1] - 16]];
  brush.wash("#592b18", 230);
  drawPolyShape(botStrip, 0.15);
  brush.noWash();

  // 3. Cross-contour anatomical hatching for cylindrical volume and rough skin grain
  brush.hatchStyle("2B", "#4a2212", 0.5);
  brush.hatch(5, 85, { rand: 0.09 });
  drawPolyShape(pts, 0.18);
  brush.noHatch();

  brush.hatchStyle("2H", "#deab85", 0.45);
  brush.hatch(6.5, 15, { rand: 0.06 });
  drawPolyShape(topStrip, 0.15);
  brush.noHatch();

  // 4. Deep knuckle wrinkles, skin folds & sun-creases
  for (let kn of info.knuckles) {
    let [kx, ky, kw] = kn;
    for (let w = -2; w <= 2; w++) {
      let wy = ky + w * 4.5;
      let curveX = kx + side * random(-4, 4);
      brush.set("microInk", w < 0 ? "#421c0d" : "#6b341e", 0.75);
      brush.arc(curveX, wy, kw * 0.36, side === -1 ? 125 : 305, side === -1 ? 235 : 415);
      // Catchlight on wrinkle ridge
      brush.set("microInk", "#e8ba95", 0.55);
      brush.arc(curveX + side * 2, wy - 1.5, kw * 0.34, side === -1 ? 135 : 315, side === -1 ? 225 : 405);
    }
  }

  // 5. Realistic weathered fingernail with cuticle & pale lunula
  let nx = info.nailX;
  let ny = info.nailY;
  let nw = info.nailW;
  let nh = info.nailH;

  let nailPts = [
    [nx - side * (nw * 0.5), ny - nh * 0.48],
    [nx + side * (nw * 0.5), ny - nh * 0.54],
    [nx + side * (nw * 0.58), ny],
    [nx + side * (nw * 0.5), ny + nh * 0.54],
    [nx - side * (nw * 0.5), ny + nh * 0.48]
  ];
  brush.noStroke();
  brush.wash("#d6a589", 245);
  drawPolyShape(nailPts, 0.2);
  brush.noWash();

  // Nail bed shading & longitudinal ridges
  brush.set("microInk", "#9e6347", 0.55);
  for (let r = -0.35; r <= 0.35; r += 0.23) {
    brush.line(nx - side * nw * 0.42, ny + nh * r, nx + side * nw * 0.45, ny + nh * r);
  }

  // Pale lunula (half-moon at cuticle base) & worn free edge at tip
  brush.set("microInk", "#f5decb", 0.85);
  brush.arc(nx + side * (nw * 0.25), ny, nh * 0.42, side === -1 ? 290 : 110, side === -1 ? 430 : 250);
  brush.arc(nx - side * (nw * 0.35), ny, nh * 0.48, side === -1 ? 115 : 295, side === -1 ? 245 : 425);

  // Dark weathered crease around cuticle and under nail tip
  brush.set("rotring", "#38170b", 0.65);
  drawPolyShape(nailPts, 0.2);

  // 6. Crisp contour & sunset rim highlight along top of finger
  brush.set("rotring", "#2e1309", 0.75);
  drawPolyShape(pts, 0.18);

  brush.set("microInk", "#f2c299", 0.8);
  brush.spline([
    [pts[0][0], pts[0][1] + 2, 0.4],
    [pts[1][0], pts[1][1] + 2, 1.1],
    [pts[2][0], pts[2][1] + 2, 0.6]
  ], 0.35);

  // Fine pores, freckles & calluses
  brush.set("spray", "#4f2210", 0.45);
  brush.line(pts[0][0], pts[0][1] + 14, pts[2][0], pts[2][1] + 14);
}

