// 7. FRAYED CANVAS & LEATHER BINOCULAR STRAP
// ===========================================================================
function drawFrayedStrap() {
  // 1. Brass D-rings and stitched dark leather tabs at side lugs (299, 435) and (901, 435)
  for (let side of [-1, 1]) {
    let lx = 600 + side * 301;
    let ly = 435;

    // Brass D-ring loop
    brush.set("2B", "#d9ad55", 1.1);
    brush.arc(lx + side * 6, ly + 8, 20, 0, 180);
    brush.set("microInk", "#fff0ba", 0.7);
    brush.arc(lx + side * 6, ly + 8, 19, 25, 145);

    // Stitched leather tab connecting D-ring to upper strap behind hand
    let tabPts = [
      [lx - side * 8, ly + 14],
      [lx + side * 18, ly + 14],
      [lx + side * 26, ly + 52],
      [lx - side * 4, ly + 52]
    ];
    brush.noStroke();
    brush.wash("#3d1f10", 248);
    drawPolyShape(tabPts, 0.08);
    brush.noWash();
    brush.set("rotring", "#1a0b05", 0.65);
    drawPolyShape(tabPts, 0.08);
  }

  // 2. Main hanging canvas strap emerging below the hands and sweeping across lower poster
  const leftSpine = [
    [282, 745], [272, 835], [298, 935], [358, 1020],
    [452, 1078], [568, 1098], [678, 1084], [785, 1035],
    [868, 952], [916, 845], [912, 745]
  ];

  const strapHalfW = 23;
  let outerEdge = [];
  let innerEdge = [];

  for (let i = 0; i < leftSpine.length; i++) {
    let p = leftSpine[i];
    let pPrev = leftSpine[max(0, i - 1)];
    let pNext = leftSpine[min(leftSpine.length - 1, i + 1)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let ang = atan2(dy, dx);
    let nx = -sin(ang);
    let ny = cos(ang);

    // Slight natural twist near the bottom-right curve
    let twist = map(sin(i * 28), -1, 1, 0.62, 1.05);
    let w = strapHalfW * twist;

    outerEdge.push([p[0] + nx * w, p[1] + ny * w]);
    innerEdge.push([p[0] - nx * w, p[1] - ny * w]);
  }

  let strapPoly = outerEdge.concat(innerEdge.slice().reverse());

  // Drop shadow of strap onto poster bands
  let shadowPoly = strapPoly.map(pt => [pt[0] + 8, pt[1] + 14]);
  brush.noStroke();
  brush.fill("#140a06", 125);
  brush.fillBleed(0.15, "out");
  drawPolyShape(shadowPoly, 0.12);
  brush.noFill();

  // Base weathered olive-khaki canvas wash
  brush.noStroke();
  brush.wash("#786d4c", 250);
  drawPolyShape(strapPoly, 0.12);
  brush.noWash();

  // Forensic woven canvas texture (cross-hatched warp & weft)
  brush.hatchStyle("2B", "#4a422b", 0.55);
  brush.hatch(4.5, 32, { rand: 0.08 });
  drawPolyShape(strapPoly, 0.12);
  brush.noHatch();

  brush.hatchStyle("2H", "#9e9168", 0.45);
  brush.hatch(5, 122, { rand: 0.06 });
  drawPolyShape(strapPoly, 0.12);
  brush.noHatch();

  // Center red-brown heritage stripe woven down the canvas strap
  let centerStripe1 = [];
  let centerStripe2 = [];
  for (let i = 0; i < leftSpine.length; i++) {
    centerStripe1.push([
      lerp(outerEdge[i][0], innerEdge[i][0], 0.42),
      lerp(outerEdge[i][1], innerEdge[i][1], 0.42)
    ]);
    centerStripe2.push([
      lerp(outerEdge[i][0], innerEdge[i][0], 0.58),
      lerp(outerEdge[i][1], innerEdge[i][1], 0.58)
    ]);
  }
  brush.set("2B", "#6e2c18", 0.8);
  brush.spline(centerStripe1.map(p => [p[0], p[1], 0.9]), 0.35);
  brush.spline(centerStripe2.map(p => [p[0], p[1], 0.9]), 0.35);

  // Scuffed brass length-adjuster buckle on left side of strap around (315, 965)
  let bkx = 326, bky = 975;
  let bucklePts = [
    [bkx - 24, bky - 12], [bkx + 22, bky - 24],
    [bkx + 32, bky + 8], [bkx - 14, bky + 20]
  ];
  brush.noStroke();
  brush.wash("#a88038", 245);
  drawPolyShape(bucklePts, 0.05);
  brush.noWash();
  brush.set("rotring", "#2b1d08", 0.75);
  drawPolyShape(bucklePts, 0.05);
  brush.set("microInk", "#fff0bd", 0.85);
  brush.line(bkx - 20, bky - 10, bkx + 20, bky - 21);

  // Strap outlines
  brush.set("rotring", "#2b2517", 0.75);
  brush.spline(outerEdge.map(p => [p[0], p[1], 0.9]), 0.35);
  brush.spline(innerEdge.map(p => [p[0], p[1], 0.9]), 0.35);

  // 3. FORENSIC FRAYED THREADS curling off the worn canvas edges
  for (let i = 0; i < outerEdge.length - 1; i++) {
    for (let sub = 0; sub < 9; sub++) {
      let t = sub / 9;
      let ox = lerp(outerEdge[i][0], outerEdge[i + 1][0], t);
      let oy = lerp(outerEdge[i][1], outerEdge[i + 1][1], t);
      let ix = lerp(innerEdge[i][0], innerEdge[i + 1][0], t);
      let iy = lerp(innerEdge[i][1], innerEdge[i + 1][1], t);

      // Outer edge frayed threads
      if (random() < 0.75) {
        let len = random(8, 28);
        let a = random(20, 160);
        let mx = ox + cos(a) * len * 0.5 + random(-5, 5);
        let my = oy + sin(a) * len * 0.5 + random(-5, 5);
        let ex = ox + cos(a + random(-35, 35)) * len;
        let ey = oy + sin(a + random(-35, 35)) * len;
        let threadCol = random() < 0.55 ? "#d9c89e" : (random() < 0.5 ? "#9c8d63" : "#3d3520");
        brush.set("microInk", threadCol, random(0.45, 0.8));
        brush.spline([[ox, oy, 0.9], [mx, my, 0.7], [ex, ey, 0.2]], 0.5);
      }

      // Inner edge frayed threads
      if (random() < 0.65) {
        let len = random(7, 24);
        let a = random(200, 340);
        let mx = ix + cos(a) * len * 0.5 + random(-4, 4);
        let my = iy + sin(a) * len * 0.5 + random(-4, 4);
        let ex = ix + cos(a + random(-35, 35)) * len;
        let ey = iy + sin(a + random(-35, 35)) * len;
        let threadCol = random() < 0.6 ? "#e6d6ad" : "#574d33";
        brush.set("microInk", threadCol, random(0.45, 0.75));
        brush.spline([[ix, iy, 0.9], [mx, my, 0.7], [ex, ey, 0.2]], 0.5);
      }
    }
  }
}

