  brush.rect(0, py2, 1200, 1200 - py2, "corner");
  brush.rect(0, 0, px1, 1200, "corner");
  brush.rect(px2, 0, 1200 - px2, 1200, "corner");
  brush.noWash();

  // Double-ruled graphic poster border line in deep umber & muted ochre
  brush.set("rotring", "#2b1810", 0.95);
  brush.rect(px1, py1, px2 - px1, py2 - py1, "corner");

  brush.set("rotring", "#9e512b", 0.55);
  brush.rect(px1 - 8, py1 - 8, (px2 - px1) + 16, (py2 - py1) + 16, "corner");

  // Crisp pinpoint star glints on the twin lenses & scuffed brass hinge
  const glints = [
    [332, 505, 16], // Left lens upper-left glass highlight
    [702, 505, 16], // Right lens upper-left glass highlight
    [486, 658, 11], // Left lens violet-amber rim glint
    [856, 658, 11], // Right lens violet-amber rim glint
    [588, 524, 10], // Central brass hinge cap glint
    [575, 384, 9]   // Brass focus wheel glint
  ];

  for (let g of glints) {
    let [gx, gy, gr] = g;
    brush.set("microInk", "#fffdf5", 0.9);
    brush.line(gx - gr, gy, gx + gr, gy);
    brush.line(gx, gy - gr, gx, gy + gr);
    brush.set("microInk", "#ffd980", 0.65);
    brush.line(gx - gr * 0.6, gy - gr * 0.6, gx + gr * 0.6, gy + gr * 0.6);
    brush.line(gx - gr * 0.6, gy + gr * 0.6, gx + gr * 0.6, gy - gr * 0.6);
  }
}

