  // 1. Cracked Plaster Wall in Raking Low Light (Soft Pastel & Bone Undertones)
  drawPlasterWall();

  // 2. Hard Black Shadow Wedges & Jagged Diagonal Stripes from Unseen Low Source
  drawShadowWedges();

  // 3. Exposed Brick/Lath Spalling, Mortar Grit & Plaster Fissures
  drawWallCracksAndGrit();

  // 4. Upper Spiraling Iron Flight & Vertical Standpipe Column
  drawUpperSpiralAndColumn();

  // 5. Main Steeply Canted Wrought-Iron Fire Escape & S-Scroll Brackets
  drawForegroundFireEscape();

  // 6. The Abandoned Patent-Leather Shoe on the Hero Step
  drawPatentLeatherShoe();

  // 7. Final Erased White-Chalk Raking Highlights & Soot Atmosphere
  drawAtmosphericChalkAndSoot();

  noLoop();
