// ============================================================================
// GEOMETRY & PROJECTION HELPERS
// ============================================================================

function projectPoint(x, y, distScale) {
  let dx = x - LIGHT.x;
  let dy = y - LIGHT.y;
  return [x + dx * distScale, y + dy * distScale];
}

function polyWash(pts, col, alpha) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
  return p;
}

function polyFill(pts, col, alpha, bleed = 0.08, tex = 0.6) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  let p = new brush.Polygon(pts);
  p.fill(col, alpha, bleed, tex);
  return p;
}

function polyCharcoal(pts, col, spacing = 8, angle = -32, weight = 1.0, washAlpha = 190) {
  let p = new brush.Polygon(pts);
  if (washAlpha > 0) {
    p.wash(col, washAlpha);
  }
  brush.hatchStyle("charcoal", col, weight);
  p.hatch(spacing, angle, { rand: 0.12, gradient: 0.25 });
  brush.noHatch();
  return p;
}

function lerpPt(p1, p2, t) {
  return [lerp(p1[0], p2[0], t), lerp(p1[1], p2[1], t)];
}

// ============================================================================
// 1. PLASTER WALL WITH RAKING PASTEL & BONE TONALITIES
// ============================================================================

function drawPlasterWall() {
  // Deep soot and slate base
  polyWash([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], PAL.charcoalDark, 255);

  // Concentric raking light zones fanning up-right from LIGHT (110, 1130)
  const rakingZones = [
    { r: 1350, col: PAL.slateDark, a: 160, ang: -38, sp: 16 },
    { r: 1120, col: PAL.pastelSlate, a: 150, ang: -34, sp: 15 },
    { r: 940, col: PAL.pastelSage, a: 140, ang: -40, sp: 14 },
    { r: 780, col: PAL.pastelMauve, a: 145, ang: -30, sp: 13 },
    { r: 640, col: PAL.pastelRose, a: 155, ang: -36, sp: 12 },
    { r: 500, col: PAL.pastelPeach, a: 170, ang: -32, sp: 11 },
    { r: 360, col: PAL.boneMid, a: 185, ang: -28, sp: 10 },
    { r: 220, col: PAL.boneLight, a: 200, ang: -35, sp: 9 }
  ];

  for (let z of rakingZones) {
    let pts = [];
    pts.push([0, 1200]);
    for (let a = -95; a <= 15; a += 10) {
      let px = constrain(LIGHT.x + cos(a) * z.r, 0, 1200);
      let py = constrain(LIGHT.y + sin(a) * z.r, 0, 1200);
      pts.push([px, py]);
    }
    pts.push([1200, 1200]);
    let p = polyWash(pts, z.col, z.a);
    brush.hatchStyle("charcoal", z.col, 0.85);
    p.hatch(z.sp, z.ang, { rand: 0.18, gradient: 0.35 });
    brush.noHatch();
  }

  // Broad illuminated plaster corridor sweeping diagonally up-right (-36 deg)
  let beamPts = [
    [0, 960],
    [180, 720],
    [760, 120],
    [1200, 0],
    [1200, 760],
    [540, 1200],
    [0, 1200]
  ];
  polyFill(beamPts, PAL.pastelPeach, 95, 0.25, 0.75);

  let innerBeamPts = [
    [0, 1040],
    [260, 820],
    [880, 290],
    [1200, 190],
    [1200, 580],
    [420, 1200],
    [0, 1200]
  ];
  polyFill(innerBeamPts, PAL.boneMid, 110, 0.2, 0.8);

  // Compressed charcoal dry-media massing for plaster surface undulations
  const plasterPatches = [
    { pts: [[480, 260], [820, 180], [920, 380], [560, 460]], col: PAL.pastelMauve, str: 0.45 },
    { pts: [[260, 580], [640, 440], [720, 680], [340, 780]], col: PAL.pastelPeach, str: 0.5 },
    { pts: [[680, 420], [1120, 300], [1160, 580], [760, 680]], col: PAL.pastelRose, str: 0.45 },
    { pts: [[180, 820], [520, 740], [580, 1040], [140, 1120]], col: PAL.boneLight, str: 0.6 },
    { pts: [[60, 80], [540, 20], [460, 320], [40, 380]], col: PAL.charcoalMid, str: 0.55 },
    { pts: [[760, 760], [1180, 680], [1180, 1160], [720, 1160]], col: PAL.pastelSlate, str: 0.45 }
  ];

  for (let patch of plasterPatches) {
    brush.noStroke();
    brush.noFill();
    brush.noWash();
    brush.mass("charcoal", patch.col, {
      precision: 0.55,
      strength: patch.str,
      gradient: 0.4,
      outline: false
    });
    let p = new brush.Polygon(patch.pts);
    p.mass();
    brush.noMass();
  }

  // Canted architectural plaster joint lines (-16 deg Dutch tilt)
  brush.set("2B", PAL.slateDark, 0.55);
  for (let y = 120; y < 1250; y += 190) {
    let y2 = y - tan(16) * 1200;
    brush.line(0, y, 1200, y2);
  }
}

// ============================================================================
// 2. HARD BLACK SHADOW WEDGES ACROSS THE WALL
// ============================================================================

function drawShadowWedges() {
  // All shadows radiate as sharp, theatrical wedges from LIGHT (110, 1130)
  // Upper-left corner deep shadow hood
  polyCharcoal(
    [[0, 0], [820, 0], [420, 410], [0, 760]],
    PAL.sootDark, 7, -42, 1.1, 225
  );

  // Wedge 1: Shadow of the upper spiral landing cutting across the top wall
  polyCharcoal(
    [[210, 540], [740, 0], [1200, 0], [1200, 110], [280, 610]],
    PAL.sootDeep, 6, -36, 1.2, 240
  );

  // Jagged diagonal slat stripes from upper landing grating (fanning right)
  for (let i = 0; i < 9; i++) {
    let sy = 440 + i * 28;
    let sx = 240 + i * 22;
    let p1 = [sx, sy];
    let p2 = [sx + 18, sy + 14];
    let f1 = projectPoint(p1[0], p1[1], 2.2);
    let f2 = projectPoint(p2[0], p2[1], 2.2);
    polyWash([p1, f1, f2, p2], PAL.sootDeep, 225);
    brush.set("charcoal", PAL.sootDeep, 0.9);
    brush.line(p1[0], p1[1], f1[0], f1[1]);
  }

  // Wedge 2: Massive hard black diagonal wedge from the main stair stringer
  let mainWedge = [
    [220, 560],
    [1200, 85],
    [1200, 295],
    [290, 665]
  ];
  polyCharcoal(mainWedge, PAL.sootDeep, 5.5, -28, 1.25, 248);

  // Crisp razor edge on main shadow wedge with subtle pastel penumbra
  brush.set("charcoal", PAL.pastelMauve, 1.1);
  brush.line(220, 560, 1200, 85);
  brush.set("charcoal", PAL.sootDeep, 1.4);
  brush.line(220, 563, 1200, 88);
  brush.line(290, 665, 1200, 295);

  // Wedge 3: Jagged sawtooth step-shadow wedges fanning across mid-right wall
  const stepShadowSources = [
    { x1: 310, y1: 590, x2: 430, y2: 565 },
    { x1: 420, y1: 685, x2: 565, y2: 650 },
    { x1: 545, y1: 785, x2: 715, y2: 745 },
    { x1: 690, y1: 895, x2: 885, y2: 845 },
    { x1: 840, y1: 1015, x2: 1050, y2: 960 }
  ];

  for (let idx = 0; idx < stepShadowSources.length; idx++) {
    let s = stepShadowSources[idx];
    let q1 = projectPoint(s.x1, s.y1, 1.65);
    let q2 = projectPoint(s.x2, s.y2, 1.65);
    polyCharcoal([[s.x1, s.y1], q1, q2, [s.x2, s.y2]], PAL.sootDeep, 6.5, -24, 1.0, 235);

    // Individual iron slat stripes inside/between the step wedges
    for (let k = 1; k <= 4; k++) {
      let t = k / 5;
      let bx = lerp(s.x1, s.x2, t);
      let by = lerp(s.y1, s.y2, t) - 18;
      let tx = bx + 28;
      let ty = by - 8;
      let pb = projectPoint(bx, by, 1.4);
      let pt = projectPoint(tx, ty, 1.4);
      polyWash([[bx, by], pb, pt, [tx, ty]], PAL.sootDark, 215);
    }
  }

  // Wedge 4: Magnified distorted shadows of the twisted iron balusters on the wall
  for (let i = 0; i < 11; i++) {
    let bx = 260 + i * 74;
    let by = 460 + i * 56;
    let tx = bx + 38;
    let ty = by - 270;
    let sb = projectPoint(bx, by, 0.55);
    let st = projectPoint(tx, ty, 0.85);

    // Twisted bar shadow silhouette
    let w = 11 + i * 1.2;
    polyWash(
      [[sb[0] - w, sb[1]], [st[0] - w * 1.5, st[1]], [st[0] + w * 1.5, st[1]], [sb[0] + w, sb[1]]],
      PAL.sootDeep,
      210
    );

    // Top handrail shadow band connecting the baluster shadows
    if (i === 0) {
      let rStart = st;
      let rEnd = projectPoint(260 + 10 * 74 + 38, 460 + 10 * 56 - 270, 0.85);
      polyCharcoal(
        [
          [rStart[0], rStart[1] - 22],
          [rEnd[0] + 120, rEnd[1] - 32],
          [rEnd[0] + 120, rEnd[1] + 22],
          [rStart[0], rStart[1] + 18]
        ],
        PAL.sootDeep, 6, -22, 1.1, 235
      );
    }
  }

  // Wedge 5: Looming, elongated shadow of the Abandoned Shoe thrown high onto the wall!
  // Shoe sits around (715, 735); its projected shadow lands around (920, 560)
  let shoeShadowPts = [];
  const rawShoeSil = [
    [605, 755], [645, 725], [705, 718], [765, 680],
    [825, 650], [848, 668], [835, 720], [818, 775],
    [804, 778], [808, 722], [755, 735], [690, 768], [615, 770]
  ];
  for (let pt of rawShoeSil) {
    shoeShadowPts.push(projectPoint(pt[0], pt[1], 0.42));
  }
  polyCharcoal(shoeShadowPts, PAL.sootDeep, 5, -30, 1.1, 240);

  // Distorted S-scroll bracket shadow on the lower-right wall
  brush.set("charcoal", PAL.sootDeep, 5.5);
  let scrollWallPts = [];
  for (let t = 0; t <= 1; t += 0.1) {
    let sx = lerp(340, 620, t) + sin(t * 360) * 48;
    let sy = lerp(820, 790, t) - cos(t * 360) * 36;
    scrollWallPts.push(projectPoint(sx, sy, 0.38));
  }
  brush.spline(scrollWallPts, 0.6);
}

// ============================================================================
// 3. EXPOSED BRICK/LATH, CRACKED PLASTER & MORTAR GRIT
// ============================================================================

function drawWallCracksAndGrit() {
  // Spalled plaster patches exposing old crumbling brickwork & mortar grit
  const spallZones = [
    { cx: 510, cy: 360, rx: 95, ry: 58, brickCols: 3, brickRows: 3 },
    { cx: 880, cy: 470, rx: 115, ry: 72, brickCols: 4, brickRows: 3 },
    { cx: 360, cy: 870, rx: 85, ry: 64, brickCols: 3, brickRows: 3 }
  ];

  for (let sz of spallZones) {
    // Recessed dark mortar cavity
    let cavPts = [];
    for (let a = 0; a < 360; a += 20) {
      let rMod = 0.8 + 0.35 * noise(sz.cx * 0.02 + cos(a), sz.cy * 0.02 + sin(a));
      let px = sz.cx + cos(a) * sz.rx * rMod;
      let py = sz.cy + sin(a) * sz.ry * rMod - (px - sz.cx) * tan(16);
      cavPts.push([px, py]);
    }
    polyCharcoal(cavPts, PAL.sootMid, 6, -16, 0.9, 210);

    // Individual weathered bricks inside the spalled plaster cavity
    let bw = (sz.rx * 1.4) / sz.brickCols;
    let bh = (sz.ry * 1.3) / sz.brickRows;
    for (let r = 0; r < sz.brickRows; r++) {
      for (let c = 0; c < sz.brickCols; c++) {
        let bx = sz.cx - sz.rx * 0.65 + c * bw + (r % 2) * (bw * 0.45);
        let by = sz.cy - sz.ry * 0.55 + r * bh - (bx - sz.cx) * tan(16);
        if (dist(bx + bw * 0.4, by + bh * 0.4, sz.cx, sz.cy) < sz.rx * 0.85) {
          let bPts = [
            [bx + 3, by + 3],
            [bx + bw - 4, by + 3 - (bw - 7) * tan(16)],
            [bx + bw - 4, by + bh - 4 - (bw - 7) * tan(16)],
            [bx + 3, by + bh - 4]
          ];
          let brickTone = (r + c) % 2 === 0 ? PAL.rustDark : PAL.charcoalMid;
          polyWash(bPts, brickTone, 210);
          // Raking bottom-left mortar lip highlight on each brick
          brush.set("cpencil", PAL.pastelPeach, 0.9);
          brush.line(bPts[0][0], bPts[0][1], bPts[3][0], bPts[3][1]);
          brush.line(bPts[3][0], bPts[3][1], bPts[2][0], bPts[2][1]);
        }
      }
    }

    // Broken plaster rim around cavity: dark shadow on top-right, bright chalk on bottom-left
    for (let i = 0; i < cavPts.length; i++) {
      let p1 = cavPts[i];
      let p2 = cavPts[(i + 1) % cavPts.length];
      let midY = (p1[1] + p2[1]) * 0.5;
      if (midY > sz.cy) {
        // Facing low light -> thick bone-chalk plaster thickness edge
        brush.set("chalk_lift", PAL.boneLight, 1.15);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
        brush.set("2B", PAL.sootDeep, 0.8);
        brush.line(p1[0] + 2, p1[1] - 3, p2[0] + 2, p2[1] - 3);
      } else {
        // Overhanging lip -> deep soot shadow
        brush.set("charcoal", PAL.sootDeep, 1.4);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
        brush.set("cpencil", PAL.pastelRose, 0.7);
        brush.line(p1[0] - 2, p1[1] + 3, p2[0] - 2, p2[1] + 3);
      }
    }
  }

  // Major branching plaster cracks across the wall
  const mainCracks = [
    { start: [480, 320], dir: -65, len: 310, w: 1.5, depth: 3 },
    { start: [530, 395], dir: 25, len: 380, w: 1.4, depth: 3 },
    { start: [860, 430], dir: -52, len: 360, w: 1.5, depth: 3 },
    { start: [910, 505], dir: 48, len: 290, w: 1.3, depth: 2 },
    { start: [350, 840], dir: -35, len: 280, w: 1.4, depth: 3 },
    { start: [380, 900], dir: 68, len: 260, w: 1.2, depth: 2 },
    { start: [680, 180], dir: 115, len: 290, w: 1.3, depth: 2 },
    { start: [1040, 220], dir: 145, len: 320, w: 1.3, depth: 2 }
  ];

  for (let cr of mainCracks) {
    drawPlasterCrack(cr.start[0], cr.start[1], cr.dir, cr.len, cr.w, cr.depth);
  }

  // Mortar grit & granular wall tooth (thousands of tiny raking-lit grains)
  for (let i = 0; i < 520; i++) {
    let gx = random(60, 1180);
    let gy = random(40, 1160);
    let dLight = dist(gx, gy, LIGHT.x, LIGHT.y);
    let gritCol = dLight < 550 ? PAL.boneLight : (dLight < 880 ? PAL.pastelPeach : PAL.pastelSlate);

    // Dark speck + tiny offset chalk highlight
    brush.set("2B", PAL.sootDeep, random(0.4, 0.95));
    brush.line(gx, gy, gx + random(1.5, 4), gy - random(1, 3));

    if (random() < 0.65) {
      brush.set("cpencil", gritCol, random(0.45, 0.9));
      brush.line(gx - 1.5, gy + 1.5, gx + 1, gy + 2.5);
    }
  }

  // Fine spray stipple for powdery charcoal & mortar dust
  brush.set("spray", PAL.sootDeep, 0.8);
  for (let i = 0; i < 28; i++) {
    brush.line(random(100, 1100), random(80, 1100), random(100, 1100), random(80, 1100));
  }
  brush.set("spray", PAL.boneMid, 0.65);
  for (let i = 0; i < 18; i++) {
    let sx = random(80, 820);
    let sy = random(420, 1150);
    brush.line(sx, sy, sx + random(-90, 90), sy + random(-90, 90));
  }
}

function drawPlasterCrack(x, y, dir, len, weight, depth) {
  let steps = int(len / 16);
  let ptsDark = [[x, y]];
  let ptsLight = [[x - 2.2, y + 2.2]];
  let cx = x;
  let cy = y;
  let curDir = dir;

  for (let i = 0; i < steps; i++) {
    curDir += random(-24, 24);
    let stepLen = random(11, 21);
    cx += cos(curDir) * stepLen;
    cy += sin(curDir) * stepLen;
    ptsDark.push([cx, cy]);
    ptsLight.push([cx - 2.2, cy + 2.2]);

    if (depth > 1 && i > 2 && random() < 0.24) {
      let bDir = curDir + (random() < 0.5 ? random(28, 58) : random(-58, -28));
      drawPlasterCrack(cx, cy, bDir, len * 0.48, weight * 0.68, depth - 1);
    }
  }

  if (ptsDark.length > 2) {
    // Bright raking chalk edge on the side facing the low light
    brush.set("cpencil", PAL.boneLight, weight * 0.95);
    brush.spline(ptsLight, 0.25);

    // Deep soot fissure core
    brush.set("rotring", PAL.sootDeep, weight * 1.15);
    brush.spline(ptsDark, 0.25);

    // Soft charcoal crumble along crack
    brush.set("2B", PAL.charcoalDark, weight * 0.8);
    brush.line(ptsDark[0][0], ptsDark[0][1], ptsDark[int(ptsDark.length / 2)][0], ptsDark[int(ptsDark.length / 2)][1]);
  }
}

// ============================================================================
// IRONWORK HELPER PRIMITIVES (BEAMS, RIVETS, RUST SCALE, TWISTED BARS)
// ============================================================================

function drawIronBeam(x1, y1, x2, y2, thickness, depthOffset = 10, isLitBottom = true) {
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  // Main dark web of the channel iron
  let pWeb = [
    [x1, y1],
    [x2, y2],
    [x2 + nx * thickness, y2 + ny * thickness],
    [x1 + nx * thickness, y1 + ny * thickness]
  ];
  polyCharcoal(pWeb, PAL.sootDark, 5, ang, 1.0, 240);

  // Recessed channel groove in mid-slate / rust undertone
  let inset = thickness * 0.22;
  let pGroove = [
    [x1 + nx * inset, y1 + ny * inset],
    [x2 + nx * inset, y2 + ny * inset],
    [x2 + nx * (thickness - inset), y2 + ny * (thickness - inset)],
    [x1 + nx * (thickness - inset), y1 + ny * (thickness - inset)]
  ];
  polyWash(pGroove, PAL.charcoalMid, 185);

  // Bottom/left flange catching the low unseen light source
  let fThick = max(4, depthOffset);
  let pFlange = isLitBottom
    ? [
        [x1 + nx * thickness, y1 + ny * thickness],
        [x2 + nx * thickness, y2 + ny * thickness],
        [x2 + nx * (thickness + fThick), y2 + ny * (thickness + fThick)],
        [x1 + nx * (thickness + fThick), y1 + ny * (thickness + fThick)]
      ]
    : [
        [x1 - nx * fThick, y1 - ny * fThick],
        [x2 - nx * fThick, y2 - ny * fThick],
        [x2, y2],
        [x1, y1]
      ];
  polyWash(pFlange, PAL.pastelSlate, 210);

  // Flaking rust scale patches along the iron beam
  let len = dist(x1, y1, x2, y2);
  let numRust = int(len / 28);
  for (let i = 0; i < numRust; i++) {
    let t = random(0.05, 0.95);
    let rx = lerp(x1, x2, t) + nx * random(inset, thickness - inset);
    let ry = lerp(y1, y2, t) + ny * random(inset, thickness - inset);
    drawRustFlake(rx, ry, ang);
  }

  // Crisp structural outlines & erased white-chalk raking rim
  brush.set("rotring", PAL.sootDeep, 1.1);
  brush.line(x1, y1, x2, y2);
  brush.line(x1 + nx * thickness, y1 + ny * thickness, x2 + nx * thickness, y2 + ny * thickness);

  let rimX1 = isLitBottom ? x1 + nx * (thickness + fThick) : x1 - nx * fThick;
  let rimY1 = isLitBottom ? y1 + ny * (thickness + fThick) : y1 - ny * fThick;
  let rimX2 = isLitBottom ? x2 + nx * (thickness + fThick) : x2 - nx * fThick;
  let rimY2 = isLitBottom ? y2 + ny * (thickness + fThick) : y2 - ny * fThick;

  brush.set("chalk_lift", PAL.boneLight, 0.95);
  brush.line(rimX1, rimY1, rimX2, rimY2);
  brush.set("cpencil", PAL.chalkWhite, 0.85);
  brush.line(rimX1, rimY1, lerp(rimX1, rimX2, 0.65), lerp(rimY1, rimY2, 0.65));
}

function drawRustFlake(x, y, beamAng) {
  let w = random(7, 19);
  let h = random(4, 10);
  let ca = cos(beamAng);
  let sa = sin(beamAng);
  let pts = [
    [x, y],
    [x + ca * w - sa * 2, y + sa * w + ca * 2],
    [x + ca * (w * 0.8) - sa * h, y + sa * (w * 0.8) + ca * h],
    [x - sa * (h * 0.7), y + ca * (h * 0.7)]
  ];
  polyWash(pts, random() < 0.5 ? PAL.rustMid : PAL.rustLight, 195);

  // Curled blister shadow underneath flake
  brush.set("rotring", PAL.sootDeep, 0.95);
  brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);

  // Tiny lifted chalk edge on bottom of blister
  brush.set("cpencil", PAL.pastelPeach, 0.75);
  brush.line(pts[2][0], pts[2][1], pts[3][0], pts[3][1]);
}

function drawRivet(x, y, radius = 5.5) {
  // Cast shadow crescent pointing away from LIGHT (up-right)
  let angToLight = atan2(LIGHT.y - y, LIGHT.x - x);
  let sx = x - cos(angToLight) * (radius * 0.65);
  let sy = y - sin(angToLight) * (radius * 0.65);

  brush.noStroke();
  brush.wash(PAL.sootDeep, 245);
  brush.circle(sx, sy, radius * 1.05, 0.15);
  brush.noWash();

  // Rivet dome body
  brush.wash(PAL.charcoalMid, 235);
  brush.circle(x, y, radius, 0.12);
  brush.noWash();

  // Ring seating shadow
  brush.set("rotring", PAL.sootDeep, 0.85);
  brush.circle(x, y, radius, 0.1);

  // Raking pastel/chalk crescent on the side facing LIGHT
  let hx = x + cos(angToLight) * (radius * 0.42);
  let hy = y + sin(angToLight) * (radius * 0.42);
  brush.set("cpencil", PAL.boneLight, 1.15);
  brush.arc(x, y, radius * 0.72, angToLight - 55, angToLight + 55);

  // Specular white-chalk pinpoint
  brush.set("cpencil", PAL.chalkWhite, 1.3);
  brush.line(hx, hy, hx + 1.5, hy + 1.5);
}

function drawTwistedBar(x1, y1, x2, y2, barW = 8, twists = 6) {
  let steps = twists * 2;
  let dx = (x2 - x1) / steps;
  let dy = (y2 - y1) / steps;
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  for (let i = 0; i < steps; i++) {
    let sx = x1 + dx * i;
    let sy = y1 + dy * i;
    let ex = x1 + dx * (i + 1);
    let ey = y1 + dy * (i + 1);
    let mx = (sx + ex) * 0.5;
    let my = (sy + ey) * 0.5;

    let bulge = (i % 2 === 0 ? 1 : -0.75) * (barW * 0.65);
    let segPts = [
      [sx - nx * (barW * 0.35), sy - ny * (barW * 0.35)],
      [mx + nx * bulge, my + ny * bulge],
      [ex + nx * (barW * 0.35), ey + ny * (barW * 0.35)],
      [mx - nx * bulge, my - ny * bulge]
    ];

    polyWash(segPts, i % 2 === 0 ? PAL.sootDeep : PAL.charcoalMid, 235);

    // Dark core contour
    brush.set("rotring", PAL.sootDeep, 0.9);
    brush.line(segPts[0][0], segPts[0][1], segPts[1][0], segPts[1][1]);
    brush.line(segPts[1][0], segPts[1][1], segPts[2][0], segPts[2][1]);

    // Chalk twist edge facing left/down toward light
    brush.set("cpencil", i % 2 === 0 ? PAL.boneLight : PAL.pastelSlate, 0.95);
    brush.line(segPts[0][0], segPts[0][1], segPts[3][0], segPts[3][1]);
    brush.line(segPts[3][0], segPts[3][1], segPts[2][0], segPts[2][1]);
  }
}

// ============================================================================
// 4. UPPER SPIRALING FLIGHT & VERTICAL STANDPIPE COLUMN
// ============================================================================

function drawUpperSpiralAndColumn() {
  // Upper spiral stair flight canted across the top-left to upper-right
  // Seen steeply from underneath
  let uBack1 = [40, 390], uBack2 = [760, -30];
  let uFront1 = [90, 465], uFront2 = [860, 25];

  // Underside steps of upper spiral flight
  let numUpperSteps = 7;
  for (let i = 0; i < numUpperSteps; i++) {
    let t1 = i / numUpperSteps;
    let t2 = (i + 0.72) / numUpperSteps;
    let b1 = lerpPt(uBack1, uBack2, t1);
    let b2 = lerpPt(uBack1, uBack2, t2);
    let f1 = lerpPt(uFront1, uFront2, t1);
    let f2 = lerpPt(uFront1, uFront2, t2);

    // 4 slats per upper step
    for (let s = 0; s < 4; s++) {
      let st = s / 4;
      let st2 = (s + 0.62) / 4;
      let sl1 = lerpPt(b1, f1, st);
      let sl2 = lerpPt(b2, f2, st);
      let sl3 = lerpPt(b2, f2, st2);
      let sl4 = lerpPt(b1, f1, st2);
      polyWash([sl1, sl2, sl3, sl4], PAL.sootDeep, 235);
      brush.set("cpencil", PAL.pastelSlate, 0.75);
      brush.line(sl4[0], sl4[1], sl3[0], sl3[1]);
    }
  }

  // Upper stringer beams
  drawIronBeam(uBack1[0], uBack1[1], uBack2[0], uBack2[1], 18, 5, true);
  drawIronBeam(uFront1[0], uFront1[1], uFront2[0], uFront2[1], 24, 7, true);

  // Upper railing bars
  for (let i = 0; i <= 8; i++) {
    let t = i / 8;
    let bx = lerp(uFront1[0], uFront2[0], t);
    let by = lerp(uFront1[1], uFront2[1], t);
    drawTwistedBar(bx, by, bx - 42, by - 165, 6, 4);
  }

  // Massive Canted Central Standpipe / Support Column on the Left
  // Tilted from (70, -40) down to (280, 1240)
  let colTop = [70, -40];
  let colBot = [280, 1240];
  let colW = 62;
  let cAng = atan2(colBot[1] - colTop[1], colBot[0] - colTop[0]);
  let cnx = -sin(cAng);
  let cny = cos(cAng);

  // Column shadow side (right side, away from left edge/light)
  let colPoly = [
    [colTop[0] - cnx * (colW * 0.5), colTop[1] - cny * (colW * 0.5)],
    [colTop[0] + cnx * (colW * 0.5), colTop[1] + cny * (colW * 0.5)],
    [colBot[0] + cnx * (colW * 0.5), colBot[1] + cny * (colW * 0.5)],
    [colBot[0] - cnx * (colW * 0.5), colBot[1] - cny * (colW * 0.5)]
  ];
  polyCharcoal(colPoly, PAL.sootDeep, 6, cAng, 1.2, 245);

  // Cylindrical mid-tone & raking highlight along the left/bottom-facing side of the column
  let colMidPoly = [
    [colTop[0] + cnx * (colW * 0.05), colTop[1] + cny * (colW * 0.05)],
    [colTop[0] + cnx * (colW * 0.46), colTop[1] + cny * (colW * 0.46)],
    [colBot[0] + cnx * (colW * 0.46), colBot[1] + cny * (colW * 0.46)],
    [colBot[0] + cnx * (colW * 0.05), colBot[1] + cny * (colW * 0.05)]
  ];
  polyWash(colMidPoly, PAL.charcoalMid, 200);

  let colLitPoly = [
    [colTop[0] + cnx * (colW * 0.25), colTop[1] + cny * (colW * 0.25)],
    [colTop[0] + cnx * (colW * 0.44), colTop[1] + cny * (colW * 0.44)],
    [colBot[0] + cnx * (colW * 0.44), colBot[1] + cny * (colW * 0.44)],
    [colBot[0] + cnx * (colW * 0.25), colBot[1] + cny * (colW * 0.25)]
  ];
  polyWash(colLitPoly, PAL.pastelSlate, 185);

  // Bright chalk highlight strip along lower column closest to LIGHT
  brush.set("chalk_lift", PAL.boneLight, 1.3);
  brush.line(
    lerp(colTop[0], colBot[0], 0.35) + cnx * (colW * 0.42),
    lerp(colTop[1], colBot[1], 0.35) + cny * (colW * 0.42),
    colBot[0] + cnx * (colW * 0.42),
    colBot[1] + cny * (colW * 0.42)
  );

  // Heavy Riveted Pipe Collars & Gusset Flanges along the Standpipe
  for (let t = 0.14; t <= 0.88; t += 0.22) {
    let cx = lerp(colTop[0], colBot[0], t);
    let cy = lerp(colTop[1], colBot[1], t);
    let fw = colW * 0.72;
    let fh = 26;
    let dx = cos(cAng) * fh * 0.5;
    let dy = sin(cAng) * fh * 0.5;

    let flangePts = [
      [cx - dx - cnx * fw, cy - dy - cny * fw],
      [cx - dx + cnx * fw, cy - dy + cny * fw],
      [cx + dx + cnx * fw, cy + dy + cny * fw],
      [cx + dx - cnx * fw, cy + dy - cny * fw]
    ];
    polyWash(flangePts, PAL.sootDeep, 245);
    brush.set("rotring", PAL.sootDeep, 1.1);
    brush.line(flangePts[0][0], flangePts[0][1], flangePts[1][0], flangePts[1][1]);
    brush.line(flangePts[2][0], flangePts[2][1], flangePts[3][0], flangePts[3][1]);

    // Bottom edge of collar catches chalk highlight
    brush.set("chalk_lift", PAL.boneLight, 1.0);
    brush.line(flangePts[2][0], flangePts[2][1], flangePts[3][0], flangePts[3][1]);

    // 4 Rivets on each collar
    for (let r = -0.48; r <= 0.5; r += 0.32) {
      drawRivet(cx + cnx * (colW * r), cy + cny * (colW * r), 5.2);
    }
  }

  // Peeling rust blisters along the standpipe
  for (let i = 0; i < 28; i++) {
    let t = random(0.05, 0.95);
    let rx = lerp(colTop[0], colBot[0], t) + cnx * random(-colW * 0.35, colW * 0.35);
    let ry = lerp(colTop[1], colBot[1], t) + cny * random(-colW * 0.35, colW * 0.35);
    drawRustFlake(rx, ry, cAng);
  }
}

// ============================================================================
// 5. MAIN STEEPLY CANTED FIRE ESCAPE, STEPS & S-SCROLL BRACKET
// ============================================================================

function drawForegroundFireEscape() {
  // Large ornate Wrought-Iron S-Scroll Bracket supporting the stair flight from the column/wall
  drawSScrollBracket();

  // Main Stair Flight Geometry:
  // Sweeps from upper-left landing (around Standpipe) down-right to bottom-right corner
  // Back stringer (closer to wall, higher up-right in screen space)
  let backTop = [195, 290];
  let backBot = [1230, 965];
  // Front stringer (closer to viewer, lower-left in screen space)
  let frontTop = [85, 435];
  let frontBot = [980, 1190];

  // Draw the back stringer first (behind the steps)
  drawIronBeam(backTop[0], backTop[1], backBot[0], backBot[1], 34, 9, true);

  // Rivets along the back stringer
  for (let i = 0; i <= 14; i++) {
    let t = i / 14;
    drawRivet(lerp(backTop[0], backBot[0], t) - 8, lerp(backTop[1], backBot[1], t) + 14, 4.8);
  }

  // Far back wall-side safety rail & balusters
  let backRailTop = [235, 65];
  let backRailBot = [1250, 710];
  for (let i = 0; i <= 9; i++) {
    let t = i / 9;
    let bx = lerp(backTop[0], backBot[0], t);
    let by = lerp(backTop[1], backBot[1], t);
    let tx = lerp(backRailTop[0], backRailBot[0], t);
    let ty = lerp(backRailTop[1], backRailBot[1], t);
    if (i % 2 === 0) {
      drawTwistedBar(bx, by, tx, ty, 7, 5);
    } else {
      drawIronBeam(bx, by, tx, ty, 6, 3, false);
    }
  }
  drawIronBeam(backRailTop[0], backRailTop[1], backRailBot[0], backRailBot[1], 14, 5, true);

  // Define the 6 Canted Steps descending down-right
  // Step 3 (index 3) is the HERO STEP where the Patent-Leather Shoe sits!
  const stepParams = [
    { t: 0.08, depth: 75, slats: 5, isHero: false },
    { t: 0.22, depth: 88, slats: 5, isHero: false },
    { t: 0.37, depth: 102, slats: 6, isHero: false },
    { t: 0.54, depth: 128, slats: 6, isHero: true },  // HERO STEP (around x=530..880, y=670..830)
    { t: 0.73, depth: 138, slats: 6, isHero: false },
    { t: 0.92, depth: 145, slats: 6, isHero: false }
  ];

  for (let idx = 0; idx < stepParams.length; idx++) {
    let sp = stepParams[idx];
    // Anchor on front stringer and back stringer
    let fAnchor = lerpPt(frontTop, frontBot, sp.t);
    let bAnchor = lerpPt(backTop, backBot, sp.t + 0.035);

    // Step tread direction vector (going slightly down-right along stair pitch for step depth)
    let stepDirX = cos(24) * sp.depth;
    let stepDirY = sin(24) * sp.depth;

    let fl = fAnchor; // Front-left corner of step
    let bl = bAnchor; // Back-left corner of step
    let fr = [fl[0] + stepDirX, fl[1] + stepDirY]; // Front-right (leading nosing)
    let br = [bl[0] + stepDirX, bl[1] + stepDirY]; // Back-right (leading nosing)

    drawWroughtIronStep(fl, fr, br, bl, sp.slats, sp.isHero);
  }

  // Draw the Front Stringer in front of the step ends (with heavy bolted gusset plates!)
  drawIronBeam(frontTop[0], frontTop[1], frontBot[0], frontBot[1], 44, 12, true);

  // Bolted Gusset Plates & Double Rivet Rows on the Front Stringer for each step
  for (let idx = 0; idx < stepParams.length; idx++) {
    let sp = stepParams[idx];
    let fAnchor = lerpPt(frontTop, frontBot, sp.t);
    let gx = fAnchor[0] + 18;
    let gy = fAnchor[1] + 24;

    // Gusset plate polygon
    let gusset = [
      [gx - 28, gy - 18],
      [gx + 54, gy + 12],
      [gx + 38, gy + 44],
      [gx - 42, gy + 14]
    ];
    polyCharcoal(gusset, PAL.sootDeep, 4, 38, 1.0, 245);
    brush.set("rotring", PAL.sootDeep, 1.1);
    for (let k = 0; k < 4; k++) {
      let p1 = gusset[k];
      let p2 = gusset[(k + 1) % 4];
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
    // Chalk highlight on lower-left gusset edge facing low light
    brush.set("chalk_lift", PAL.boneLight, 1.15);
    brush.line(gusset[3][0], gusset[3][1], gusset[2][0], gusset[2][1]);
    brush.line(gusset[0][0], gusset[0][1], gusset[3][0], gusset[3][1]);

    // 4 Rivets on the gusset plate
    drawRivet(gx - 18, gy - 2, 6.2);
    drawRivet(gx + 4, gy + 8, 6.2);
    drawRivet(gx + 26, gy + 18, 6.2);
    drawRivet(gx - 8, gy + 18, 5.8);
  }

  // Foreground Balusters & Steeply Canted Handrail (Left/Foreground side)
  // Note: We leave a clear theatrical window around the Hero Step so the shoe is unobstructed,
  // placing dramatic twisted balusters just before and just after the Hero Step!
  const balusterTs = [0.06, 0.16, 0.26, 0.36, 0.45, 0.69, 0.81, 0.93];
  let fRailTop = [20, 120];
  let fRailBot = [960, 880];

  for (let i = 0; i < balusterTs.length; i++) {
    let t = balusterTs[i];
    let bx = lerp(frontTop[0], frontBot[0], t) - 6;
    let by = lerp(frontTop[1], frontBot[1], t) + 12;
    let tx = lerp(fRailTop[0], fRailBot[0], t);
    let ty = lerp(fRailTop[1], fRailBot[1], t);

    if (i % 2 === 0) {
      drawTwistedBar(bx, by, tx, ty, 9.5, 6);
    } else {
      drawIronBeam(bx, by, tx, ty, 8.5, 4, true);
    }
    // Base collar at stringer
    drawRivet(bx + 4, by + 6, 5.8);
  }

  // Heavy Foreground Handrail Bar slicing across the composition
  drawIronBeam(fRailTop[0], fRailTop[1], fRailBot[0], fRailBot[1], 20, 7, true);
}

function drawSScrollBracket() {
  // Structural wrought-iron bracket under the main stringer
  // Diagonal compression strut from standpipe (210, 860) up-right to stringer (520, 795)
  drawIronBeam(210, 860, 520, 795, 22, 7, true);
  // Horizontal tie bar from standpipe (185, 680) to stringer (415, 710)
  drawIronBeam(185, 680, 415, 710, 16, 5, true);

  // Ornate wrought-iron S-scroll forged between the strut, tie bar, and stringer
  let scrollPts1 = [
    [250, 815], [225, 765], [255, 720], [315, 725],
    [355, 765], [345, 810], [300, 815], [285, 780], [310, 760]
  ];
  let scrollPts2 = [
    [355, 765], [385, 725], [440, 725], [475, 755],
    [465, 795], [425, 800], [405, 775], [425, 755]
  ];

  for (let sPts of [scrollPts1, scrollPts2]) {
    // Thick dark forged iron band
    brush.set("charcoal", PAL.sootDeep, 4.2);
    brush.spline(sPts, 0.55);
    brush.set("rotring", PAL.sootDeep, 2.2);
    brush.spline(sPts, 0.55);

    // Offset chalk highlight along the bottom/left curve facing the low light
    let litPts = sPts.map((p) => [p[0] - 3.5, p[1] + 4.5]);
    brush.set("chalk_lift", PAL.boneLight, 1.15);
    brush.spline(litPts, 0.55);
    brush.set("cpencil", PAL.chalkWhite, 0.9);
    brush.spline(litPts.slice(0, 6), 0.55);
  }

  // Forged iron clamp rivets on scroll
  drawRivet(355, 765, 6.0);
  drawRivet(250, 815, 5.5);
  drawRivet(465, 795, 5.5);
}

function drawWroughtIronStep(fl, fr, br, bl, numSlats, isHero) {
  // End carrier plates on front and back stringers
  let plateThickness = isHero ? 26 : 18;
  let flBot = [fl[0], fl[1] + plateThickness];
  let frBot = [fr[0], fr[1] + plateThickness];
  let brBot = [br[0], br[1] + plateThickness];

  // Under-shadow of the entire step platform
  polyWash([flBot, frBot, brBot, bl], PAL.sootDeep, 215);

  // Draw each parallel wrought-iron slat bar from back (bl..br) to front (fl..fr)
  for (let i = 0; i < numSlats; i++) {
    let t1 = i / numSlats;
    let t2 = (i + 0.62) / numSlats; // 38% open air gap between slats!

    let sfl = lerpPt(fl, fr, t1);
    let sfr = lerpPt(fl, fr, t2);
    let sbr = lerpPt(bl, br, t2);
    let sbl = lerpPt(bl, br, t1);

    let barH = isHero ? 15 : 10;
    let sflB = [sfl[0], sfl[1] + barH];
    let sfrB = [sfr[0], sfr[1] + barH];
    let sbrB = [sbr[0], sbr[1] + barH];

    // 1. Vertical thickness face of slat (facing down-left toward low light!)
    polyWash([sfl, sfr, sfrB, sflB], PAL.pastelSlate, 225);
    polyWash([sfr, sbr, sbrB, sfrB], PAL.sootDeep, 245);

    // 2. Top horizontal face of slat (in deep raking charcoal/slate)
    let topCol = isHero ? (i % 2 === 0 ? PAL.charcoalDark : PAL.sootMid) : PAL.sootDark;
    polyCharcoal([sfl, sfr, sbr, sbl], topCol, isHero ? 4.5 : 6, -33, 0.9, 235);

    // 3. Flaking rust scale on Hero Step slats
    if (isHero) {
      for (let r = 0; r < 6; r++) {
        let rt = random(0.08, 0.92);
        let rx = lerp(sfl[0], sbl[0], rt) + random(2, 10);
        let ry = lerp(sfl[1], sbl[1], rt) + random(-2, 4);
        drawRustFlake(rx, ry, -33);
      }
      // Anti-slip diamond bosses stamped into the Hero Step iron bars
      for (let d = 0.15; d <= 0.88; d += 0.12) {
        let dx = lerp(sfl[0], sbl[0], d) + (sfr[0] - sfl[0]) * 0.45;
        let dy = lerp(sfl[1], sbl[1], d) + (sfr[1] - sfl[1]) * 0.45;
        brush.set("rotring", PAL.sootDeep, 0.9);
        brush.line(dx - 4, dy, dx + 4, dy - 2);
        brush.set("cpencil", PAL.boneLight, 0.85);
        brush.line(dx - 4, dy + 1.5, dx + 1, dy + 2.5);
      }
    }

    // 4. Crisp drafting edges & bright chalk highlight on the bottom/left edge facing LIGHT
    brush.set("rotring", PAL.sootDeep, 1.0);
    brush.line(sfl[0], sfl[1], sbl[0], sbl[1]);
    brush.line(sfr[0], sfr[1], sbr[0], sbr[1]);

    brush.set("chalk_lift", isHero ? PAL.chalkWhite : PAL.boneLight, isHero ? 1.15 : 0.85);
    brush.line(sflB[0], sflB[1], sfrB[0], sfrB[1]);
    brush.set("cpencil", PAL.boneLight, isHero ? 1.0 : 0.75);
    brush.line(sfl[0], sfl[1], sbl[0], sbl[1]);
  }

  // Front-right leading nosing bar (extra heavy with spacer bolts)
  let nfl = lerpPt(fl, fr, 0.92);
  let nbl = lerpPt(bl, br, 0.92);
  let nfrB = [fr[0], fr[1] + (isHero ? 18 : 12)];
  let nbrB = [br[0], br[1] + (isHero ? 18 : 12)];
  polyWash([fr, br, nbrB, nfrB], PAL.sootDeep, 245);
  brush.set("chalk_lift", PAL.boneLight, isHero ? 1.25 : 0.9);
  brush.line(nfl[0], nfl[1], nbl[0], nbl[1]);

  if (isHero) {
    // Spacer rod bolts visible between the hero slats
    for (let b = 0.25; b <= 0.78; b += 0.26) {
      let bx1 = lerp(fl[0], bl[0], b);
      let by1 = lerp(fl[1], bl[1], b);
      let bx2 = lerp(fr[0], br[0], b);
      let by2 = lerp(fr[1], br[1], b);
      brush.set("rotring", PAL.sootDeep, 1.6);
      brush.line(bx1, by1, bx2, by2);
      brush.set("cpencil", PAL.boneLight, 1.0);
      brush.line(bx1 - 1, by1 + 2, bx2 - 1, by2 + 2);
      drawRivet(bx2 + 3, by2 + 3, 5.2);
    }
  }
}

