function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function washPoly(pts, col, alpha = 230, curv = 0.18) {
  if (!pts || pts.length < 3) return;
  resetBrush();
  brush.wash(col, alpha);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrush();
}

function fillPoly(pts, col, alpha = 120, bleed = 0.2, tex = 0.55, border = 0.35, curv = 0.22) {
  if (!pts || pts.length < 3) return;
  resetBrush();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrush();
}

function strokePoly(pts, bName, col, weight = 1, curv = 0.22, close = true) {
  if (!pts || pts.length < 2) return;
  resetBrush();
  brush.set(bName, col, weight);
  if (close && pts.length >= 3) {
    brush.beginShape(curv);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
  } else {
    brush.spline(pts, curv);
  }
  resetBrush();
}

function makeEllipsePts(cx, cy, rx, ry, n = 20, rotDeg = 0, wobble = 0) {
  let pts = [];
  let ca = cos(rotDeg), sa = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let rMod = 1 + wobble * (noise(cx * 0.02 + cos(a), cy * 0.02 + sin(a)) - 0.5);
    let lx = cos(a) * rx * rMod;
    let ly = sin(a) * ry * rMod;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

