}

// ============================================================================
// 1. WEATHERED BLUE-GREY PLANK WALL
// ============================================================================
function drawPlankWall(seams) {
  // Batch pastel washes across planks
  for (let p = 0; p < seams.length - 1; p++) {
    let y0 = seams[p];
    let y1 = seams[p + 1];
    let h = y1 - y0;

    let baseCol = p % 2 === 0 ? PAL.wallBase : PAL.wallMid;
    washPoly([[0, y0], [1200, y0], [1200, y1], [0, y1]], baseCol, 180, 0.05);

    // Soft weathered patches
    for (let k = 0; k < 5; k++) {
      let px = random(40, 1160);
      let py = random(y0 + 15, y1 - 15);
      let pw = random(180, 420);
      let ph = random(25, h * 0.55);
      let col = k % 2 === 0 ? PAL.wallLight : PAL.wallDark;
      fillPoly(
        makeEllipsePts(px, py, pw * 0.5, ph * 0.5, 14, 0, 0.25),
        col,
        random(35, 65),
        0.3,
        0.5,
        0.2
      );
    }

    // Chalky distemper brush marks along the plank
    resetBrush();
    for (let m = 0; m < 28; m++) {
      let my = random(y0 + 6, y1 - 6);
      let mx0 = random(-20, 950);
      let mx1 = mx0 + random(120, 340);
      let col = random([PAL.wallLight, PAL.wallChalk, PAL.wallMid, PAL.wallDark]);
      brush.set("folk_gouache", col, random(0.6, 1.5));
      brush.line(mx0, my, min(1220, mx1), my + random(-2, 2));
    }

    // Horizontal wood grain lines with subtle knot waves
    let knotX = random(180, 1020);
    let knotY = y0 + h * random(0.32, 0.68);
    let grainRows = floor(h / 5.5);
    for (let g = 0; g < grainRows; g++) {
      let gy = y0 + 4 + g * 5.5 + random(-1.5, 1.5);
      let pts = [];
      for (let gx = 0; gx <= 1200; gx += 60) {
        let dx = gx - knotX;
        let dy = gy - knotY;
        let d2 = dx * dx * 0.35 + dy * dy * 2.2;
        let pushY = (dy / (1 + d2 * 0.00045)) * 14 * exp(-d2 * 0.00009);
        let nOff = (noise(gx * 0.006, gy * 0.04, p * 3) - 0.5) * 5;
        pts.push([gx, constrain(gy + pushY + nOff, y0 + 2, y1 - 2)]);
      }
      let gCol = g % 3 === 0 ? PAL.wallDark : g % 3 === 1 ? PAL.wallChalk : PAL.wallDeep;
      let gWeight = g % 3 === 0 ? random(0.25, 0.48) : random(0.18, 0.35);
      brush.set(g % 2 === 0 ? "2H" : "cpencil", gCol, gWeight);
      brush.spline(pts, 0.35);
    }

    // Subtle wood knot rings
    if (p !== 1 && p !== 2) {
      for (let r = 1; r <= 3; r++) {
        let kPts = makeEllipsePts(knotX, knotY, r * 14, r * 5.5, 16, 0, 0.15);
        strokePoly(kPts, "2H", PAL.wallDeep, 0.32, 0.3, true);
      }
    }
  }
  resetBrush();
}

// ============================================================================
// 2. HORIZONTAL FRIEZE OF FLAT STYLISED KURBITS GOURDS
// ============================================================================
function drawKurbitsFrieze(yTop, yBot) {
  const bTopH = 44;
  const bBotH = 44;
  const innerTop = yTop + bTopH; // 269
  const innerBot = yBot - bBotH; // 721
  const midY = (innerTop + innerBot) * 0.5; // 495

  // --- A. Top and Bottom Decorative Border Grounds ---
  washPoly([[0, yTop], [1200, yTop], [1200, innerTop], [0, innerTop]], PAL.friezeCream, 232, 0.05);
  washPoly([[0, innerBot], [1200, innerBot], [1200, yBot], [0, yBot]], PAL.friezeCream, 232, 0.05);

  // Subtle gouache uneven streaky pass on borders
  resetBrush();
  for (let x = 0; x < 1200; x += 140) {
    brush.set("folk_gouache", PAL.friezeWarm, 1.3);
    brush.line(x, yTop + 22, min(1200, x + 155), yTop + 22 + random(-1.5, 1.5));
    brush.line(x, innerBot + 22, min(1200, x + 155), innerBot + 22 + random(-1.5, 1.5));
  }

  // Cobalt trim stripes along border edges
  washPoly([[0, yTop], [1200, yTop], [1200, yTop + 10], [0, yTop + 10]], PAL.cobalt, 220, 0.05);
  washPoly([[0, innerTop - 9], [1200, innerTop - 9], [1200, innerTop], [0, innerTop]], PAL.leafGreen, 215, 0.05);
  washPoly([[0, innerBot], [1200, innerBot], [1200, innerBot + 9], [0, innerBot + 9]], PAL.leafGreen, 215, 0.05);
  washPoly([[0, yBot - 10], [1200, yBot - 10], [1200, yBot], [0, yBot]], PAL.cobalt, 220, 0.05);

  // Top & Bottom border folk wave & berry motifs
  let step = 48;
  for (let x = 24; x < 1200; x += step) {
    // Top border red-orange lozenges & cobalt/green berries
    let ty = yTop + 22;
    let lozTop = [[x - 15, ty], [x, ty - 8], [x + 15, ty], [x, ty + 8]];
    washPoly(lozTop, PAL.redOrange, 230, 0.15);
    strokePoly(lozTop, "folk_ink", PAL.folkBlack, 0.55, 0.15, true);

    let dotPts1 = makeEllipsePts(x + step * 0.5, ty - 4, 4.5, 4.5, 10);
    let dotPts2 = makeEllipsePts(x + step * 0.5, ty + 4, 4.5, 4.5, 10);
    washPoly(dotPts1, PAL.cobalt, 225, 0.2);
    washPoly(dotPts2, PAL.leafGreenDark, 225, 0.2);

    // Bottom border scalloped arches & red-orange berries
    let by = innerBot + 22;
    let lozBot = [[x - 15, by], [x, by - 8], [x + 15, by], [x, by + 8]];
    washPoly(lozBot, x % (step * 2) === 24 ? PAL.cobalt : PAL.redOrange, 230, 0.15);
    strokePoly(lozBot, "folk_ink", PAL.folkBlack, 0.55, 0.15, true);

    let bDot = makeEllipsePts(x + step * 0.5, by, 5.5, 5.5, 10);
    washPoly(bDot, PAL.leafGreen, 225, 0.2);
    strokePoly(bDot, "folk_ink", PAL.folkBlack, 0.45, 0.2, true);
  }

  // Confident black border framing lines
  let borderLines = [yTop, yTop + 10, innerTop - 9, innerTop, innerBot, innerBot + 9, yBot - 10, yBot];
  for (let ly of borderLines) {
    let lPts = [];
    for (let x = 0; x <= 1200; x += 80) {
      lPts.push([x, ly + (noise(x * 0.01, ly * 0.1) - 0.5) * 2.2]);
    }
    strokePoly(lPts, "folk_ink", PAL.folkBlack, 0.78, 0.2, false);
  }

  // --- B. Main Undulating Kurbits Vine Across the Band ---
  let vineTopPts = [];
  let vineBotPts = [];
  for (let x = -20; x <= 1220; x += 30) {
    let wave = sin((x - 110) * (360 / 490)) * 58;
    let vy = midY + wave;
    vineTopPts.push([x, vy - 5.5]);
    vineBotPts.unshift([x, vy + 5.5]);
  }
  let vinePoly = vineTopPts.concat(vineBotPts);
  washPoly(vinePoly, PAL.leafGreen, 235, 0.15);
  strokePoly(vineTopPts, "folk_ink", PAL.folkBlack, 0.8, 0.3, false);
  strokePoly(vineBotPts.slice().reverse(), "folk_ink", PAL.folkBlack, 0.75, 0.3, false);

  // --- C. Five Major Stylised Kurbits Gourd Clusters ---
  // Positioned across the horizontal band: x = 110, 355, 600, 845, 1090
  const gourdClusters = [
    { cx: 110, cy: 495, dir: -1, scale: 1.0, variant: 0 },
    { cx: 355, cy: 490, dir: 1, scale: 0.96, variant: 1 },
    { cx: 600, cy: 495, dir: -1, scale: 1.04, variant: 0 },
    { cx: 845, cy: 490, dir: 1, scale: 0.96, variant: 1 },
    { cx: 1090, cy: 495, dir: -1, scale: 1.0, variant: 0 }
  ];

  // First draw sweeping split-color kurbits leaves & secondary buds behind the main gourds
  for (let gc of gourdClusters) {
    drawKurbitsFoliageCluster(gc.cx, gc.cy, gc.dir, gc.scale, gc.variant);
  }

  // Secondary filler gourds and folk rosettes in the intervals (x = 232, 477, 722, 967)
  const fillerX = [232, 477, 722, 967];
  for (let i = 0; i < fillerX.length; i++) {
    let fx = fillerX[i];
    let topPositive = i % 2 === 0;
    drawSecondaryGourdAndRosette(fx, innerTop + 78, 1, topPositive);
    drawSecondaryGourdAndRosette(fx, innerBot - 78, -1, !topPositive);
  }

  // Now draw the 5 primary Kurbits Gourds with flat gouache segments & confident black outlines
  for (let gc of gourdClusters) {
    drawMainKurbitsGourd(gc.cx, gc.cy, gc.dir, gc.scale, gc.variant);
  }
}

function drawSplitFolkLeaf(x0, y0, angleDeg, len, wid, flipColors = false) {
  // Curved baroque folk leaf split along its central vein into dark & light green
  let n = 10;
  let spine = [];
  let leftSide = [];
  let rightSide = [];

  let bend = flipColors ? -22 : 22;
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    let curA = angleDeg + sin(t * 180) * bend * t;
    let r = t * len;
    let px = x0 + cos(curA) * r;
    let py = y0 + sin(curA) * r;
    spine.push([px, py]);

    // Serrated/scalloped width profile
    let profile = sin(t * 180) * wid * (1 + 0.22 * sin(t * 540));
    let nx = -sin(curA);
    let ny = cos(curA);
    leftSide.push([px + nx * profile, py + ny * profile]);
    rightSide.unshift([px - nx * profile, py - ny * profile]);
  }

  let half1 = spine.concat(leftSide.slice().reverse());
  let half2 = spine.concat(rightSide);

  let col1 = flipColors ? PAL.leafGreenLight : PAL.leafGreenDark;
  let col2 = flipColors ? PAL.leafGreenDark : PAL.leafGreen;

  washPoly(half1, col1, 232, 0.2);
  washPoly(half2, col2, 232, 0.2);

  let fullOutline = leftSide.concat(rightSide);
  strokePoly(fullOutline, "folk_ink", PAL.folkBlack, 0.72, 0.25, true);
  strokePoly(spine, "folk_ink", PAL.folkBlack, 0.62, 0.25, false);

  // Folk brush vein ticks on the light half
  resetBrush();
  brush.set("folk_ink", PAL.folkBlack, 0.48);
  for (let i = 2; i < n - 1; i += 2) {
    let sp = spine[i];
    let target = flipColors ? leftSide[i] : rightSide[n - i];
    brush.line(
      sp[0],
      sp[1],
      lerp(sp[0], target[0], 0.65),
      lerp(sp[1], target[1], 0.65)
    );
  }
  resetBrush();
}

function drawKurbitsFoliageCluster(cx, cy, dir, sc, variant) {
  // Four sweeping S-curved kurbits leaves radiating from behind the gourd
  drawSplitFolkLeaf(cx - 25 * sc, cy + 10 * dir, -145, 118 * sc, 26 * sc, false);
  drawSplitFolkLeaf(cx + 25 * sc, cy + 10 * dir, -35, 118 * sc, 26 * sc, true);
  drawSplitFolkLeaf(cx - 22 * sc, cy - 10 * dir, 145, 112 * sc, 24 * sc, true);
  drawSplitFolkLeaf(cx + 22 * sc, cy - 10 * dir, 35, 112 * sc, 24 * sc, false);

  // Curling black tendrils with triad berry dots
  let tendrilAngles = [-165, -15, 165, 15];
  for (let a of tendrilAngles) {
    let tPts = [];
    let tx = cx + cos(a) * 55 * sc;
    let ty = cy + sin(a) * 45 * sc;
    let curA = a;
    for (let s = 0; s < 8; s++) {
      tPts.push([tx, ty]);
      curA += (a < 0 ? 28 : -28);
      let stepL = (16 - s * 1.5) * sc;
      tx += cos(curA) * stepL;
      ty += sin(curA) * stepL;
    }
    strokePoly(tPts, "folk_ink", PAL.folkBlack, 0.6, 0.35, false);

    // Triad of tiny gouache berries near tendril base
    let bx = tPts[2][0], by = tPts[2][1];
    let bCol = variant === 0 ? PAL.redOrange : PAL.cobaltLight;
    for (let k = -1; k <= 1; k++) {
      let dPts = makeEllipsePts(bx + k * 7, by + abs(k) * 5 - 8, 4.2, 4.2, 8);
      washPoly(dPts, bCol, 230, 0.2);
      strokePoly(dPts, "folk_ink", PAL.folkBlack, 0.42, 0.2, true);
    }
  }
}

function drawSecondaryGourdAndRosette(cx, cy, vDir, isGourd) {
  // Stem connecting to main vine
  let stemPts = [
    [cx - 18, cy + vDir * 70],
    [cx - 6, cy + vDir * 35],
    [cx, cy]
  ];
  strokePoly(stemPts, "folk_ink", PAL.folkBlack, 0.7, 0.25, false);

  // Small side leaves
  drawSplitFolkLeaf(cx, cy + vDir * 22, vDir > 0 ? -150 : 150, 58, 14, false);
  drawSplitFolkLeaf(cx, cy + vDir * 22, vDir > 0 ? -30 : 30, 58, 14, true);

  if (isGourd) {
    // Hanging or upright pear-shaped secondary kurbits gourd
    let gDir = -vDir; // points toward border
    let cupPts = makeEllipsePts(cx, cy + gDir * 8, 16, 10, 12);
    washPoly(cupPts, PAL.cobalt, 235, 0.2);
    strokePoly(cupPts, "folk_ink", PAL.folkBlack, 0.65, 0.2, true);

    // Gourd bulb with 3 lobes
    let by = cy - vDir * 22;
    let leftLobe = makeEllipsePts(cx - 16, by, 18, 26, 14, gDir * 14);
    let rightLobe = makeEllipsePts(cx + 16, by, 18, 26, 14, -gDir * 14);
    let midLobe = makeEllipsePts(cx, by - vDir * 4, 20, 30, 16);

    washPoly(leftLobe, PAL.redOrange, 235, 0.2);
    washPoly(rightLobe, PAL.redOrange, 235, 0.2);
    washPoly(midLobe, PAL.redOrangeLight, 238, 0.2);

    // Crown petals at tip of secondary gourd
    for (let k = -1; k <= 1; k++) {
      let pPts = makeEllipsePts(cx + k * 14, by - vDir * 30 + abs(k) * vDir * 5, 9, 13, 12, k * 18);
      washPoly(pPts, k === 0 ? PAL.friezeCream : PAL.cobaltLight, 235, 0.2);
      strokePoly(pPts, "folk_ink", PAL.folkBlack, 0.58, 0.2, true);
    }

    strokePoly(leftLobe, "folk_ink", PAL.folkBlack, 0.68, 0.2, true);
    strokePoly(rightLobe, "folk_ink", PAL.folkBlack, 0.68, 0.2, true);
    strokePoly(midLobe, "folk_ink", PAL.folkBlack, 0.72, 0.2, true);

    // Folk accent dashes inside central lobe
    resetBrush();
    brush.set("folk_gouache", PAL.friezeCream, 0.75);
    brush.line(cx, by - 14, cx, by + 14);
    brush.set("folk_ink", PAL.folkBlack, 0.5);
    brush.line(cx - 5, by - 8, cx + 5, by - 8);
    brush.line(cx - 6, by, cx + 6, by);
    brush.line(cx - 5, by + 8, cx + 5, by + 8);
    resetBrush();
  } else {
    // 6-petalled Dalarna folk rosette in cobalt, cream, and red-orange
    for (let p = 0; p < 6; p++) {
      let a = p * 60;
      let px = cx + cos(a) * 20;
      let py = cy + sin(a) * 20;
      let pPts = makeEllipsePts(px, py, 14, 10, 12, a);
      let pCol = p % 2 === 0 ? PAL.cobalt : PAL.cobaltLight;
      washPoly(pPts, pCol, 235, 0.2);
      strokePoly(pPts, "folk_ink", PAL.folkBlack, 0.65, 0.2, true);
    }
    let center1 = makeEllipsePts(cx, cy, 14, 14, 14);
    let center2 = makeEllipsePts(cx, cy, 7, 7, 10);
    washPoly(center1, PAL.friezeCream, 240, 0.2);
    washPoly(center2, PAL.redOrange, 240, 0.2);
    strokePoly(center1, "folk_ink", PAL.folkBlack, 0.68, 0.2, true);
    strokePoly(center2, "folk_ink", PAL.folkBlack, 0.55, 0.2, true);
  }
}

function drawMainKurbitsGourd(cx, cy, dir, sc, variant) {
  // dir = -1 means gourd grows upward (crown at top, calyx at bottom)
  // dir = +1 means gourd grows downward (crown at bottom, calyx at top)
  // Let's draw a rich double-tiered Dalarna kurbits gourd!

  let baseY = cy - dir * 105 * sc;
  let bellyY = cy - dir * 20 * sc;
  let crownY = cy + dir * 75 * sc;
  let topTipY = cy + dir * 145 * sc;

  // 1. Upper Crown Fan of 5 Scalloped Folk Petals
  const fanOffsets = [-2, -1, 0, 1, 2];
  for (let idx = 0; idx < fanOffsets.length; idx++) {
    let k = fanOffsets[idx];
    let ang = -dir * 90 + k * 24 * dir;
    let dist = (62 - abs(k) * 6) * sc;
    let px = cx + k * 26 * sc;
    let py = crownY + dir * (38 - abs(k) * 9) * sc;
    let pPts = makeEllipsePts(px, py, 20 * sc, 36 * sc, 16, k * 18 * dir);

    let pCol =
      abs(k) === 2
        ? PAL.leafGreen
        : abs(k) === 1
        ? variant === 0 ? PAL.cobalt : PAL.redOrange
        : PAL.friezeCream;
    washPoly(pPts, pCol, 238, 0.2);

    // Inner contrasting teardrop inside each crown petal
    let inPts = makeEllipsePts(px, py + dir * 4 * sc, 9 * sc, 18 * sc, 12, k * 18 * dir);
    let inCol = abs(k) === 0 ? PAL.redOrange : abs(k) === 1 ? PAL.friezeCream : PAL.leafGreenDark;
    washPoly(inPts, inCol, 235, 0.2);

    strokePoly(pPts, "folk_ink", PAL.folkBlack, 0.75, 0.22, true);
    strokePoly(inPts, "folk_ink", PAL.folkBlack, 0.55, 0.22, true);
  }

  // 2. Decorative Crown Collar Band (scalloped arch between belly and fan)
  for (let k = -2; k <= 2; k++) {
    let sx = cx + k * 20 * sc;
    let sy = crownY - dir * 6 * sc + abs(k) * dir * 3 * sc;
    let sPts = makeEllipsePts(sx, sy, 13 * sc, 10 * sc, 12);
    washPoly(sPts, k % 2 === 0 ? PAL.cobaltLight : PAL.friezeCream, 238, 0.2);
    strokePoly(sPts, "folk_ink", PAL.folkBlack, 0.65, 0.2, true);
  }

  // 3. The Grand Bulbous Kurbits Gourd Belly (5 overlapping melon segments)
  const segOrder = [-2, 2, -1, 1, 0];
  for (let k of segOrder) {
    let sx = cx + k * 25 * sc;
    let sy = bellyY + abs(k) * dir * 5 * sc;
    let rx = (30 - abs(k) * 3) * sc;
    let ry = (64 - abs(k) * 5) * sc;
    let tilt = -k * 10 * dir;

    let segPts = makeEllipsePts(sx, sy, rx, ry, 20, tilt, 0.04);

    let segCol;
    if (variant === 0) {
      segCol =
        k === 0
          ? PAL.friezeCream
          : abs(k) === 1
          ? PAL.redOrange
          : PAL.redOrangeDark;
    } else {
      segCol =
        k === 0
          ? PAL.redOrangeLight
          : abs(k) === 1
          ? PAL.cobalt
          : PAL.cobaltDark;
    }

    washPoly(segPts, segCol, 240, 0.22);

    // Gouache highlight / inner stripe with folk_gouache marker
    resetBrush();
    let hlCol =
      k === 0
        ? PAL.redOrange
        : variant === 0
        ? PAL.redOrangeLight
        : PAL.cobaltLight;
    brush.set("folk_gouache", hlCol, 1.15 * sc);
    brush.line(sx - k * 2, sy - ry * 0.55, sx + k * 2, sy + ry * 0.55);

    // Confident black outline around segment
    strokePoly(segPts, "folk_ink", PAL.folkBlack, 0.85, 0.22, true);

    // Traditional folk-art black brush ticks & decorative central ladder
    resetBrush();
    brush.set("folk_ink", PAL.folkBlack, 0.55);
    if (k === 0) {
      for (let t = -3; t <= 3; t++) {
        let ty = sy + t * 11 * sc;
        brush.line(sx - 11 * sc, ty, sx + 11 * sc, ty);
      }
      // Small cobalt/red-orange dots inside central gourd lobe
      for (let t = -2; t <= 2; t += 2) {
        let dPts = makeEllipsePts(sx, sy + t * 11 * sc, 5 * sc, 5 * sc, 8);
        washPoly(dPts, variant === 0 ? PAL.cobalt : PAL.friezeCream, 235, 0.2);
        strokePoly(dPts, "folk_ink", PAL.folkBlack, 0.48, 0.2, true);
      }
    } else {
      // Curved hatching ticks along the outer edge of each lobe
      for (let t = -2; t <= 2; t++) {
        let ty = sy + t * 13 * sc;
        let side = k < 0 ? -1 : 1;
        brush.line(
          sx + side * rx * 0.35,
          ty,
          sx + side * rx * 0.82,
          ty + dir * 4 * sc
        );
      }
    }
  }

  // 4. Lower Calyx Cup & Stem Base
  let calyxY = baseY + dir * 24 * sc;
  for (let k = -1; k <= 1; k++) {
    let cxp = cx + k * 22 * sc;
    let cyp = calyxY + abs(k) * dir * 4 * sc;
    let cPts = makeEllipsePts(cxp, cyp, 18 * sc, 24 * sc, 14, -k * 16 * dir);
    let cCol =
      k === 0
        ? variant === 0 ? PAL.cobalt : PAL.leafGreen
        : variant === 0 ? PAL.cobaltLight : PAL.leafGreenDark;
    washPoly(cPts, cCol, 238, 0.2);
    strokePoly(cPts, "folk_ink", PAL.folkBlack, 0.78, 0.2, true);
  }

  // Base bulb knob connecting calyx to stem
  let knobPts = makeEllipsePts(cx, baseY - dir * 4 * sc, 18 * sc, 12 * sc, 14);
  washPoly(knobPts, PAL.redOrange, 238, 0.2);
  strokePoly(knobPts, "folk_ink", PAL.folkBlack, 0.75, 0.2, true);

  // Top finial blossom at topTipY
  let finialPts = makeEllipsePts(cx, topTipY - dir * 10 * sc, 14 * sc, 14 * sc, 12);
  washPoly(finialPts, PAL.redOrange, 235, 0.2);
  strokePoly(finialPts, "folk_ink", PAL.folkBlack, 0.68, 0.2, true);
  resetBrush();
}

// ============================================================================
// 3. PLANK SEAMS & WEATHERING OVER THE FOLK FRIEZE
// ============================================================================
function drawPlankSeamsAndWear(seams, friezeTop, friezeBot) {
  resetBrush();

  // Horizontal scrapes and weathered blue-grey paint showing through the folk frieze
  for (let i = 0; i < 65; i++) {
    let wx = random(15, 1185);
    let wy = random(friezeTop + 4, friezeBot - 4);
    let wLen = random(18, 85);
    let col = i % 3 === 0 ? PAL.wallLight : PAL.wallBase;
    brush.set(i % 4 === 0 ? "folk_gouache" : "2H", col, random(0.3, 0.75));
    brush.line(wx, wy, wx + wLen, wy + random(-1, 1));
  }

  // Deep physical plank seams at y = 215, 490, 775, 1045
  for (let i = 1; i < seams.length - 1; i++) {
    let sy = seams[i];

    // Soft bevel shadow above and below crack
    let shadowStrip = [
      [0, sy - 4],
      [1200, sy - 4],
      [1200, sy + 5],
      [0, sy + 5]
    ];
    fillPoly(shadowStrip, PAL.wallDeep, 75, 0.2, 0.4, 0.2, 0.05);

    // Chipped paint along the plank edge (especially along y = 490 inside the frieze!)
    for (let x = 10; x < 1190; x += random(22, 55)) {
      let chipW = random(12, 34);
      let chipH = random(3, 8);
      let chipPts = [
        [x, sy],
        [x + chipW * 0.5, sy + (random() < 0.5 ? -chipH : chipH)],
        [x + chipW, sy]
      ];
      washPoly(chipPts, PAL.wallDark, 185, 0.1);
    }

    // Crisp dark shadow crack of the plank joint
    let crackPts = [];
    let hlPts = [];
    for (let x = 0; x <= 1200; x += 50) {
      let dy = (noise(x * 0.015, i * 10) - 0.5) * 3.0;
      crackPts.push([x, sy + dy]);
      hlPts.push([x, sy + dy + 2.8]);
    }
    strokePoly(crackPts, "folk_ink", PAL.wallSeam, 1.05, 0.25, false);
    strokePoly(crackPts, "charcoal", "#1b242a", 0.75, 0.25, false);
    // Top edge bevel catch-light on the lower plank
    strokePoly(hlPts, "cpencil", PAL.wallChalk, 0.65, 0.25, false);
  }
  resetBrush();
}

// ============================================================================
// 4. DRIP STAINS DARKENING THE PAINT BELOW THE MITTENS
// ============================================================================
function drawDripStainsAndWetness(seams) {
  // Drip sources from Left Mitten (tip ~ x=448, y=812; thumb tip ~ x=352, y=652)
  // and Right Mitten (tip ~ x=752, y=824; thumb tip ~ x=848, y=664)
  const dripTracks = [
    // Left thumb drips
    { x: 352, y0: 645, y1: 1095, w: 9, pigment: "#5d7482" },
    { x: 363, y0: 655, y1: 930, w: 6, pigment: "#687f8d" },
    // Left main tip drips
    { x: 432, y0: 790, y1: 1185, w: 13, pigment: "#516876" },
    { x: 449, y0: 802, y1: 1198, w: 16, pigment: "#445a68" },
    { x: 466, y0: 792, y1: 1120, w: 11, pigment: "#586f7d" },
    { x: 482, y0: 775, y1: 985, w: 7, pigment: "#647b89" },
    // Right main tip drips
    { x: 722, y0: 785, y1: 1035, w: 8, pigment: "#607785" },
    { x: 738, y0: 805, y1: 1175, w: 13, pigment: "#4e6472" },
    { x: 754, y0: 814, y1: 1198, w: 16, pigment: "#425866" },
    { x: 771, y0: 800, y1: 1140, w: 11, pigment: "#556c7a" },
    // Right thumb drips
    { x: 846, y0: 658, y1: 1110, w: 10, pigment: "#5b7280" },
    { x: 835, y0: 665, y1: 945, w: 6, pigment: "#69808e" }
  ];

  // Broad damp watercolor halos directly beneath both mittens and along plank seams
  const dampHalos = [
    { cx: 450, cy: 825, rx: 64, ry: 75, a: 55 },
    { cx: 356, cy: 710, rx: 28, ry: 60, a: 45 },
    { cx: 752, cy: 838, rx: 64, ry: 78, a: 55 },
    { cx: 844, cy: 725, rx: 28, ry: 60, a: 45 },
    // Damp capillary spread where drips hit the plank seams at y = 775 and y = 1045
    { cx: 448, cy: 777, rx: 88, ry: 14, a: 68 },
    { cx: 752, cy: 777, rx: 88, ry: 14, a: 68 },
    { cx: 448, cy: 1047, rx: 75, ry: 12, a: 62 },
    { cx: 752, cy: 1047, rx: 75, ry: 12, a: 62 }
  ];

  for (let h of dampHalos) {
    let pts = makeEllipsePts(h.cx, h.cy, h.rx, h.ry, 18, 0, 0.25);
    fillPoly(pts, "#4c6270", h.a, 0.38, 0.65, 0.4);
  }

  // Vertical darkened drip tracks
  for (let tr of dripTracks) {
    let leftPts = [];
    let rightPts = [];
    let centerPts = [];
    let steps = 22;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = lerp(tr.y0, tr.y1, t);
      let wiggle = (noise(tr.x * 0.05, y * 0.018) - 0.5) * 9;
      // Slight pooling bulge at plank seams (775, 1045) and at the drip tip
      let seamBulge =
        exp(-pow((y - 775) * 0.12, 2)) * 6 +
        exp(-pow((y - 1045) * 0.12, 2)) * 5;
      let tipBulge = t > 0.9 ? sin(((t - 0.9) / 0.1) * 180) * 3.5 : 0;
      let hw = tr.w * 0.5 * (1 - t * 0.42) + seamBulge + tipBulge;

      let cx = tr.x + wiggle;
      centerPts.push([cx, y]);
      leftPts.push([cx - hw, y]);
      rightPts.unshift([cx + hw, y]);
    }

    let poly = leftPts.concat(rightPts);
    fillPoly(poly, tr.pigment, 82, 0.28, 0.6, 0.55, 0.2);

    // Slightly stained folk-pigment bleed where drips cross the lower frieze border (y < 830)
    if (tr.y0 < 765) {
      let stainPts = makeEllipsePts(tr.x, 768, tr.w * 1.3, 28, 12, 0, 0.2);
      fillPoly(stainPts, "#594c52", 52, 0.35, 0.5, 0.3);
    }

    // Darkened wet edge lines along the rivulet
    strokePoly(centerPts, "cpencil", "#394d59", 0.55, 0.3, false);
    strokePoly(leftPts, "2H", "#2e404b", 0.32, 0.3, false);
  }
  resetBrush();
}

// ============================================================================
// 5. CAST SHADOWS ON THE WALL BEHIND MITTENS, STRING & NAIL
// ============================================================================
function getMittenTransform(cfg) {
  let ca = cos(cfg.angle);
  let sa = sin(cfg.angle);
  return function (lx, ly) {
    return [cfg.cx + lx * ca - ly * sa, cfg.cy + lx * sa + ly * ca];
  };
}

function getMittenHalfWidth(v, sc = 1) {
  // v in [0, 1] from top of cuff (0) to rounded bottom tip (1)
  if (v < 0.25) {
    // Cuff: slightly flared at top, cinched at wrist (v = 0.25)
    let t = v / 0.25;
    return (72 * (1 - t) + 64 * t + sin(t * 180) * -3) * sc;
  } else if (v < 0.62) {
    // Palm / hand swell
    let t = (v - 0.25) / 0.37;
    return (64 + sin(t * 115) * 29) * sc;
  } else {
    // Nordic 2-point decrease crown tapering to rounded tip
    let t = (v - 0.62) / 0.38;
    return 89 * sc * pow(cos(t * 90), 0.78);
  }
}

function buildMittenBodyOutline(cfg, dx = 0, dy = 0, expand = 0) {
  let toWorld = getMittenTransform(cfg);
  let leftEdge = [];
  let rightEdge = [];
  let steps = 36;
  for (let i = 0; i <= steps; i++) {
    let v = i / steps;
    let ly = v * cfg.len;
    let hw = getMittenHalfWidth(v, cfg.scale) + expand;
    // Slight gravity curve along centerline
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    // Slight upward pull at the outer cuff corner where the string attaches
    let pullLeft = v < 0.12 && cfg.thumbSide === -1 ? -(1 - v / 0.12) * 14 : 0;
    let pullRight = v < 0.12 && cfg.thumbSide === 1 ? -(1 - v / 0.12) * 14 : 0;

    let pL = toWorld(bendX - hw, ly + pullLeft);
    let pR = toWorld(bendX + hw, ly + pullRight);
    leftEdge.push([pL[0] + dx, pL[1] + dy]);
    rightEdge.unshift([pR[0] + dx, pR[1] + dy]);
  }
  return leftEdge.concat(rightEdge);
}

function buildThumbOutline(cfg, dx = 0, dy = 0, expand = 0) {
  let toWorld = getMittenTransform(cfg);
  let side = cfg.thumbSide; // -1 for left side, +1 for right side
  let rootX = side * 46 * cfg.scale;
  let rootY = 0.36 * cfg.len;
  let thumbLen = 158 * cfg.scale;
  let thumbAng = side * 25; // angled outward, then drooping with gravity

  let leftPts = [];
  let rightPts = [];
  let steps = 20;
  for (let i = 0; i <= steps; i++) {
    let tv = i / steps;
    let curA = thumbAng * (1 - tv * 0.58);
    let cx = rootX + sin(curA) * (tv * thumbLen) + side * sin(tv * 180) * 8;
    let cy = rootY + cos(curA) * (tv * thumbLen);

    let thw =
      (tv < 0.25
        ? lerp(34, 30, tv / 0.25)
        : 30 * pow(cos(((tv - 0.25) / 0.75) * 90), 0.75)) *
        cfg.scale +
      expand;

    let nx = cos(curA * 0.5);
    let ny = -sin(curA * 0.5);
    let p1 = toWorld(cx - nx * thw, cy - ny * thw);
    let p2 = toWorld(cx + nx * thw, cy + ny * thw);
    leftPts.push([p1[0] + dx, p1[1] + dy]);
    rightPts.unshift([p2[0] + dx, p2[1] + dy]);
  }
  return leftPts.concat(rightPts);
}

const LEFT_MITTEN = {
  cx: 468,
  cy: 356,
  len: 446,
  scale: 1.0,
  angle: 3.5,
  thumbSide: -1,
  hasDarn: true
};

const RIGHT_MITTEN = {
  cx: 734,
  cy: 368,
  len: 448,
  scale: 1.0,
  angle: -3.5,
  thumbSide: 1,
  hasDarn: false
};

function drawCastShadows() {
  // Light from upper-left casts soft dark shadows down-right (+16, +20)
  const mittens = [LEFT_MITTEN, RIGHT_MITTEN];
  for (let m of mittens) {
    let shBody1 = buildMittenBodyOutline(m, 18, 22, 6);
    let shThumb1 = buildThumbOutline(m, 18, 22, 5);
    fillPoly(shBody1, "#25313a", 95, 0.35, 0.5, 0.25, 0.25);
    fillPoly(shThumb1, "#25313a", 95, 0.35, 0.5, 0.25, 0.25);

    let shBody2 = buildMittenBodyOutline(m, 9, 11, 1);
    let shThumb2 = buildThumbOutline(m, 9, 11, 1);
    fillPoly(shBody2, "#182128", 115, 0.22, 0.45, 0.35, 0.25);
    fillPoly(shThumb2, "#182128", 115, 0.22, 0.45, 0.35, 0.25);
  }

  // Cast shadow of the hanging string on the wall and upper frieze border
  resetBrush();
  let nailX = 598, nailY = 136;
  let leftAttach = getMittenTransform(LEFT_MITTEN)(-68, 4);
  let rightAttach = getMittenTransform(RIGHT_MITTEN)(68, 4);

  let shStrL = [
    [nailX + 12, nailY + 14],
    [lerp(nailX, leftAttach[0], 0.5) + 14, lerp(nailY, leftAttach[1], 0.5) + 32],
    [leftAttach[0] + 12, leftAttach[1] + 15]
  ];
  let shStrR = [
    [nailX + 12, nailY + 14],
    [lerp(nailX, rightAttach[0], 0.5) + 16, lerp(nailY, rightAttach[1], 0.5) + 34],
    [rightAttach[0] + 12, rightAttach[1] + 15]
  ];
  strokePoly(shStrL, "charcoal", "#243038", 1.35, 0.35, false);
  strokePoly(shStrR, "charcoal", "#243038", 1.35, 0.35, false);
  resetBrush();
}

// ============================================================================
// 6. HYPERREAL WET KNITTED WOOL MITTENS (WATERCOLOUR & DENSE PENCIL)
// ============================================================================
function drawMittenPair() {
  drawSingleMitten(LEFT_MITTEN);
  drawSingleMitten(RIGHT_MITTEN);
}

function drawSingleMitten(cfg) {
  let toWorld = getMittenTransform(cfg);
  let bodyPoly = buildMittenBodyOutline(cfg, 0, 0, 0);
  let thumbPoly = buildThumbOutline(cfg, 0, 0, 0);

  // --- A. Opaque Underpainting Base so the Folk Frieze Doesn't Bleed Through ---
  washPoly(bodyPoly, PAL.woolCream, 248, 0.22);
  washPoly(thumbPoly, PAL.woolCream, 248, 0.22);
  // Second solid pass over middle where dark kurbits lines sit
  washPoly(bodyPoly, PAL.woolMid, 165, 0.22);
  washPoly(thumbPoly, PAL.woolMid, 165, 0.22);

  // --- B. Layered Watercolor Modeling (3D Cylindrical Form & Wet Saturation) ---
  // 1. Warm upper-left sunlit wool wash
  let lightPoly = [];
  for (let v = 0.02; v <= 0.72; v += 0.07) {
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    lightPoly.push(toWorld(bendX - hw * 0.92, v * cfg.len));
  }
  for (let v = 0.72; v >= 0.02; v -= 0.07) {
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    lightPoly.push(toWorld(bendX + hw * 0.15, v * cfg.len));
  }
  fillPoly(lightPoly, PAL.woolCream, 135, 0.25, 0.55, 0.25, 0.25);

  // 2. Right-side cylindrical core shadow wash
  let shadePoly = [];
  for (let v = 0.02; v <= 0.95; v += 0.06) {
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    shadePoly.push(toWorld(bendX + hw * 0.05, v * cfg.len));
  }
  for (let v = 0.95; v >= 0.02; v -= 0.06) {
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    shadePoly.push(toWorld(bendX + hw * 0.96, v * cfg.len));
  }
  fillPoly(shadePoly, PAL.woolShadow, 115, 0.3, 0.65, 0.35, 0.25);

  // 3. Waterlogged Lower Half & Capillary Wet Tide-Line (v = 0.54 .. 1.0)
  let wetMidPoly = [];
  let wetSteps = 16;
  for (let i = 0; i <= wetSteps; i++) {
    let u = -1 + (2 * i) / wetSteps;
    // Irregular capillary tide line across the wool
    let vTide = 0.55 + 0.06 * sin(u * 180) + (noise(u * 2 + cfg.cx, 12) - 0.5) * 0.07;
    let hw = getMittenHalfWidth(vTide, cfg.scale);
    let bendX = sin(vTide * 180) * 6 * cfg.thumbSide;
    wetMidPoly.push(toWorld(bendX + u * hw * 0.96, vTide * cfg.len));
  }
  for (let v = 0.62; v <= 1.0; v += 0.05) {
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    wetMidPoly.push(toWorld(bendX + hw * 0.96, v * cfg.len));
  }
  for (let v = 1.0; v >= 0.62; v -= 0.05) {
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    wetMidPoly.push(toWorld(bendX - hw * 0.96, v * cfg.len));
  }
  fillPoly(wetMidPoly, PAL.woolWetMid, 125, 0.32, 0.72, 0.45, 0.25);

  // 4. Deeply soaked heavy bottom tip (v = 0.74 .. 1.0)
  let wetTipPoly = [];
  for (let i = 0; i <= 12; i++) {
    let u = -1 + (2 * i) / 12;
    let vTide = 0.74 + 0.04 * cos(u * 180) + (noise(u * 3, cfg.cy) - 0.5) * 0.05;
    let hw = getMittenHalfWidth(vTide, cfg.scale);
    let bendX = sin(vTide * 180) * 6 * cfg.thumbSide;
    wetTipPoly.push(toWorld(bendX + u * hw * 0.95, vTide * cfg.len));
  }
  for (let v = 0.78; v <= 1.0; v += 0.04) {
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    wetTipPoly.push(toWorld(bendX + hw * 0.95, v * cfg.len));
  }
  for (let v = 1.0; v >= 0.78; v -= 0.04) {
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;
    wetTipPoly.push(toWorld(bendX - hw * 0.95, v * cfg.len));
  }
  fillPoly(wetTipPoly, PAL.woolWetDark, 138, 0.28, 0.75, 0.5, 0.25);

  // Cool blue-grey reflection in the wet wool from the wall
  let wetReflectPts = makeEllipsePts(
    toWorld(18, 0.84 * cfg.len)[0],
    toWorld(18, 0.84 * cfg.len)[1],
    34,
    46,
    14,
    cfg.angle,
    0.2
  );
  fillPoly(wetReflectPts, PAL.woolWetCool, 75, 0.35, 0.5, 0.3);

  // --- C. Pastel Fair-Isle / Nordic Stripes on the Ribbed Cuff ---
  const cuffStripes = [
    { v0: 0.05, v1: 0.085, col: PAL.pastelRose },
    { v0: 0.115, v1: 0.145, col: PAL.pastelBlue },
    { v0: 0.175, v1: 0.205, col: PAL.pastelSage }
  ];
  for (let st of cuffStripes) {
    let sTop = [];
    let sBot = [];
    for (let i = 0; i <= 14; i++) {
      let u = -0.96 + (1.92 * i) / 14;
      let sag = (1 - u * u) * 0.018;
      let hw0 = getMittenHalfWidth(st.v0 + sag, cfg.scale);
      let hw1 = getMittenHalfWidth(st.v1 + sag, cfg.scale);
      sTop.push(toWorld(u * hw0, (st.v0 + sag) * cfg.len));
      sBot.unshift(toWorld(u * hw1, (st.v1 + sag) * cfg.len));
    }
    fillPoly(sTop.concat(sBot), st.col, 145, 0.18, 0.5, 0.3, 0.2);
  }

  // --- D. Dark 3D Cuff Opening at the Top Edge ---
  let cuffOpenPts = [];
  for (let i = 0; i < 20; i++) {
    let a = (i / 20) * 360;
    let ux = cos(a) * 65 * cfg.scale;
    let uy = sin(a) * 11 * cfg.scale + 4;
    let pull = (cfg.thumbSide === -1 && ux < -25) || (cfg.thumbSide === 1 && ux > 25) ? -7 : 0;
    cuffOpenPts.push(toWorld(ux, uy + pull));
  }
  washPoly(cuffOpenPts, PAL.woolWetDeep, 215, 0.22);
  fillPoly(cuffOpenPts, "#2c241e", 130, 0.15, 0.6, 0.4, 0.22);

  // --- E. Dense Pencil & Colored-Pencil Knitted Stitches Across the Hand & Cuff ---
  drawMittenKnitStitches(cfg);

  // --- F. Thumb Watercolor, Gusset Shadow & Knitted Stitches ---
  drawMittenThumbDetails(cfg);

  // --- G. The Woven Darn Patch (Hyperreal Mended Repair) ---
  if (cfg.hasDarn) {
    drawHyperrealDarn(cfg, -0.08, 0.52, 0.38, 0.11);
  } else {
    // Smaller secondary neat mend near lower palm on the right mitten
    drawSmallSecondaryMend(cfg, -0.22, 0.64);
  }

  // --- H. Felted Wool Fuzz & Backlit Fiber Halo ---
  drawFeltedWoolHalo(cfg, bodyPoly, thumbPoly);
}

function drawMittenKnitStitches(cfg) {
  let toWorld = getMittenTransform(cfg);
  const cols = 22;
  const rows = 54;

  resetBrush();

  // 1. Longitudinal Wale Groove Shadows (gives deep rib & knit column texture)
  for (let c = -cols / 2; c <= cols / 2; c++) {
    let u = c / (cols * 0.5 + 0.6);
    let walePts = [];
    for (let r = 0; r <= rows; r += 3) {
      let v = r / rows;
      let hw = getMittenHalfWidth(v, cfg.scale);
      let bendX = sin(v * 180) * 6 * cfg.thumbSide;
      let sag = (1 - u * u) * 7 * sin(v * 160);
      let jitterX = (noise(c * 0.4, v * 8, cfg.cx) - 0.5) * 2.2;
      let pt = toWorld(bendX + u * hw * 0.94 + jitterX, v * cfg.len + sag);
      walePts.push(pt);
    }
    let isDarkSide = u > 0.15;
    let wCol = isDarkSide ? PAL.woolWetDark : PAL.woolShadow;
    // In the cuff (v < 0.25), every 2nd column is a deeper purl rib trough
    let ribWeight = abs(c) % 2 === 0 ? 0.55 : 0.32;
    brush.set("2H", wCol, ribWeight);
    brush.spline(walePts, 0.3);
  }

  // 2. Individual V-Shaped Knitted Stitches (Courses & Wales)
  for (let r = 1; r < rows; r++) {
    let v = r / rows;
    let isCuff = v < 0.245;
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;

    // Fewer columns near the tapered bottom tip (Nordic crown decreases!)
    let activeCols = v > 0.68 ? max(5, round(cols * pow(1 - (v - 0.68) / 0.34, 0.65))) : cols;
    let stitchHalfW = (hw * 0.88) / activeCols;
    let stitchH = (cfg.len / rows) * 0.88;

    // Determine if this row falls on a pastel cuff stripe
    let stripeCol = null;
    let stripeDark = null;
    if (v >= 0.05 && v <= 0.088) {
      stripeCol = PAL.pastelRose;
      stripeDark = PAL.pastelRoseDark;
    } else if (v >= 0.115 && v <= 0.148) {
      stripeCol = PAL.pastelBlue;
      stripeDark = PAL.pastelBlueDark;
    } else if (v >= 0.175 && v <= 0.208) {
      stripeCol = PAL.pastelSage;
      stripeDark = PAL.pastelSageDark;
    }

    for (let ci = 0; ci < activeCols; ci++) {
      let u = -0.92 + (1.84 * (ci + 0.5)) / activeCols;

      // Skip stitches directly underneath the main darn patch so it sits cleanly
      if (cfg.hasDarn && v > 0.43 && v < 0.61 && u > -0.42 && u < 0.28) continue;

      let sag = (1 - u * u) * 6.5 * sin(v * 165);
      let pull =
        v < 0.12 &&
        ((cfg.thumbSide === -1 && u < -0.4) || (cfg.thumbSide === 1 && u > 0.4))
          ? -(1 - v / 0.12) * 10
          : 0;

      let sx = bendX + u * hw * 0.93 + (noise(ci * 0.7, r * 0.7, cfg.cx) - 0.5) * 1.8;
      let sy = v * cfg.len + sag + pull + (noise(r * 0.7, ci * 0.7, cfg.cy) - 0.5) * 1.5;

      // Foreshortening of stitch width near cylinder edges (|u| -> 1)
      let foreshorten = sqrt(max(0.18, 1 - u * u * 0.82));
      let sw = stitchHalfW * foreshorten * 0.92;

      // Choose yarn pencil color based on 3D lighting (u), wetness (v), and cuff stripes
      let isWet = v > 0.56 + (noise(u * 3, cfg.cx) - 0.5) * 0.08;
      let isVeryWet = v > 0.76;

      let leftLegCol, rightLegCol;
      if (stripeCol) {
        leftLegCol = u < 0.1 ? stripeCol : stripeDark;
        rightLegCol = stripeDark;
      } else if (isVeryWet) {
        leftLegCol = u < 0 ? PAL.woolWetMid : PAL.woolWetDark;
        rightLegCol = PAL.woolWetDeep;
      } else if (isWet) {
        leftLegCol = u < 0 ? PAL.woolShadow : PAL.woolWetMid;
        rightLegCol = PAL.woolWetDark;
      } else {
        leftLegCol = u < -0.15 ? PAL.woolCream : u < 0.25 ? PAL.woolWarm : PAL.woolShadow;
        rightLegCol = u < 0.1 ? PAL.woolShadow : PAL.woolWetDark;
      }

      // In a hanging mitten (cuff at top), the knit V loops point downward or upward:
      // Let's draw the two twisted yarn legs of each stitch!
      let pTopL = toWorld(sx - sw, sy - stitchH * 0.48);
      let pBotM = toWorld(sx, sy + stitchH * 0.52);
      let pTopR = toWorld(sx + sw, sy - stitchH * 0.48);

      // Left leg of stitch (catches upper-left light)
      brush.set(isCuff ? "cpencil" : "HB", leftLegCol, isVeryWet ? 0.68 : 0.58);
      brush.line(pTopL[0], pTopL[1], pBotM[0], pBotM[1]);

      // Right leg of stitch (in shadow)
      brush.set("2B", rightLegCol, isVeryWet ? 0.72 : 0.6);
      brush.line(pTopR[0], pTopR[1], pBotM[0], pBotM[1]);

      // Creamy highlight on sunlit stitches
      if (!isVeryWet && u < 0.05 && (ci + r) % 2 === 0) {
        let pHl1 = toWorld(sx - sw * 0.8, sy - stitchH * 0.35);
        let pHl2 = toWorld(sx - sw * 0.15, sy + stitchH * 0.3);
        brush.set("cpencil", stripeCol ? PAL.woolCream : "#faf6ef", 0.52);
        brush.line(pHl1[0], pHl1[1], pHl2[0], pHl2[1]);
      }
    }

    // Nordic crown decrease seam lines along the left & right edges for v > 0.62
    if (v > 0.62) {
      let decL1 = toWorld(bendX - hw * 0.88, v * cfg.len);
      let decL2 = toWorld(bendX - hw * 0.72, (v + 0.018) * cfg.len);
      let decR1 = toWorld(bendX + hw * 0.88, v * cfg.len);
      let decR2 = toWorld(bendX + hw * 0.72, (v + 0.018) * cfg.len);
      brush.set("2B", PAL.woolWetDeep, 0.65);
      brush.line(decL1[0], decL1[1], decL2[0], decL2[1]);
      brush.line(decR1[0], decR1[1], decR2[0], decR2[1]);
    }
  }
  resetBrush();
}

function drawMittenThumbDetails(cfg) {
  let toWorld = getMittenTransform(cfg);
  let side = cfg.thumbSide;
  let rootX = side * 46 * cfg.scale;
  let rootY = 0.36 * cfg.len;
  let thumbLen = 158 * cfg.scale;
  let thumbAng = side * 25;

  // 1. Deep shadow crease in the thumb gusset (where thumb meets palm)
  let creasePts = [];
  for (let i = 0; i <= 10; i++) {
    let t = i / 10;
    let gx = rootX - side * 14 + side * t * 18;
    let gy = rootY + 12 + t * 88;
    creasePts.push(toWorld(gx, gy));
  }
  // Watercolor shadow along gusset
  let gussetShade = creasePts.concat([
    toWorld(rootX - side * 22, rootY + 95),
    toWorld(rootX - side * 26, rootY + 25)
  ]);
  fillPoly(gussetShade, PAL.woolWetDark, 125, 0.28, 0.6, 0.4, 0.25);

  // Wet watercolor saturation at the lower half of the thumb
  let wetThumbPts = [];
  for (let tv = 0.45; tv <= 1.0; tv += 0.08) {
    let curA = thumbAng * (1 - tv * 0.58);
    let cx = rootX + sin(curA) * (tv * thumbLen) + side * sin(tv * 180) * 8;
    let cy = rootY + cos(curA) * (tv * thumbLen);
    let thw = 30 * pow(cos(((tv - 0.25) / 0.75) * 90), 0.75) * cfg.scale;
    wetThumbPts.push(toWorld(cx - thw, cy));
  }
  for (let tv = 1.0; tv >= 0.45; tv -= 0.08) {
    let curA = thumbAng * (1 - tv * 0.58);
    let cx = rootX + sin(curA) * (tv * thumbLen) + side * sin(tv * 180) * 8;
    let cy = rootY + cos(curA) * (tv * thumbLen);
    let thw = 30 * pow(cos(((tv - 0.25) / 0.75) * 90), 0.75) * cfg.scale;
    wetThumbPts.push(toWorld(cx + thw, cy));
  }
  fillPoly(wetThumbPts, PAL.woolWetDark, 135, 0.28, 0.7, 0.45, 0.25);

  // 2. Knitted Stitches on the Thumb
  resetBrush();
  const tRows = 20;
  const tCols = 8;
  for (let r = 1; r < tRows; r++) {
    let tv = r / tRows;
    let curA = thumbAng * (1 - tv * 0.58);
    let cx = rootX + sin(curA) * (tv * thumbLen) + side * sin(tv * 180) * 8;
    let cy = rootY + cos(curA) * (tv * thumbLen);
    let thw =
      (tv < 0.25
        ? lerp(33, 29, tv / 0.25)
        : 29 * pow(cos(((tv - 0.25) / 0.75) * 90), 0.75)) * cfg.scale;

    let nx = cos(curA * 0.5);
    let ny = -sin(curA * 0.5);

    let colsHere = tv > 0.7 ? max(3, round(tCols * (1 - (tv - 0.7) / 0.35))) : tCols;
    let sw = (thw * 0.85) / colsHere;
    let sh = (thumbLen / tRows) * 0.82;

    for (let c = 0; c < colsHere; c++) {
      let u = -0.88 + (1.76 * (c + 0.5)) / colsHere;
      let sx = cx + nx * u * thw;
      let sy = cy + ny * u * thw;

      let isWet = tv > 0.5;
      let c1 = isWet ? PAL.woolWetMid : u < 0 ? PAL.woolCream : PAL.woolWarm;
      let c2 = isWet ? PAL.woolWetDeep : PAL.woolShadow;

      let pL = toWorld(sx - nx * sw, sy - sh * 0.45);
      let pM = toWorld(sx, sy + sh * 0.48);
      let pR = toWorld(sx + nx * sw, sy - sh * 0.45);

      brush.set("HB", c1, 0.55);
      brush.line(pL[0], pL[1], pM[0], pM[1]);
      brush.set("2B", c2, 0.58);
      brush.line(pR[0], pR[1], pM[0], pM[1]);
    }
  }

  // Crisp gusset shadow line separating thumb from palm
  strokePoly(creasePts, "2B", PAL.woolWetDeep, 0.85, 0.3, false);
  strokePoly(creasePts, "charcoal", "#2d251e", 0.55, 0.3, false);
  resetBrush();
}

function drawHyperrealDarn(cfg, uCenter, vCenter, uHalfSpan, vHalfSpan) {
  // Woven warp-and-weft repair patch ("a darn") in soft pastel rose & powder blue yarn
  let toWorld = getMittenTransform(cfg);
  let hw = getMittenHalfWidth(vCenter, cfg.scale);
  let bendX = sin(vCenter * 180) * 6 * cfg.thumbSide;

  let cx = bendX + uCenter * hw;
  let cy = vCenter * cfg.len;
  let rx = uHalfSpan * hw;
  let ry = vHalfSpan * cfg.len;

  // Subtle recessed watercolor shadow under the darned area
  let basePts = makeEllipsePts(
    toWorld(cx, cy)[0],
    toWorld(cx, cy)[1],
    rx * 1.05,
    ry * 1.05,
    16,
    cfg.angle,
    0.15
  );
  fillPoly(basePts, PAL.woolShadow, 95, 0.2, 0.5, 0.4);

  resetBrush();

  const nWarp = 13; // Vertical darning threads
  const nWeft = 15; // Horizontal darning threads

  // 1. Vertical Warp Threads (anchored with irregular loop stitches into surrounding wool)
  for (let i = 0; i < nWarp; i++) {
    let t = -1 + (2 * i) / (nWarp - 1);
    let lx = cx + t * rx * 0.88;
    let colEdge = sqrt(max(0.25, 1 - t * t * 0.72));
    let topY = cy - ry * colEdge - random(4, 11);
    let botY = cy + ry * colEdge + random(4, 11);

    // Shadow under warp thread
    let sh1 = toWorld(lx + 1.4, topY);
    let sh2 = toWorld(lx + 1.4, botY);
    brush.set("2H", PAL.woolWetDeep, 0.45);
    brush.line(sh1[0], sh1[1], sh2[0], sh2[1]);

    // Main warp thread in pastel rose or ochre-cream
    let wCol = i % 3 === 0 ? PAL.pastelBlue : PAL.pastelRose;
    let p1 = toWorld(lx, topY);
    let p2 = toWorld(lx, cy);
    let p3 = toWorld(lx + random(-1.5, 1.5), botY);
    brush.set("cpencil", wCol, 0.92);
    brush.spline([p1, p2, p3], 0.25);

    // Tiny anchoring turnaround loop in the surrounding knit
    let loopTop = toWorld(lx + 2.5, topY - 2);
    let loopBot = toWorld(lx + 2.5, botY + 2);
    brush.set("HB", PAL.pastelRoseDark, 0.5);
    brush.line(p1[0], p1[1], loopTop[0], loopTop[1]);
    brush.line(p3[0], p3[1], loopBot[0], loopBot[1]);
  }

  // 2. Horizontal Weft Threads Weaving Over-and-Under the Warp Threads
  for (let j = 0; j < nWeft; j++) {
    let s = -1 + (2 * j) / (nWeft - 1);
    let ly = cy + s * ry * 0.88;
    let rowEdge = sqrt(max(0.25, 1 - s * s * 0.72));

    for (let i = 0; i < nWarp - 1; i++) {
      let t0 = -1 + (2 * i) / (nWarp - 1);
      let t1 = -1 + (2 * (i + 1)) / (nWarp - 1);
      if (abs(t0) > rowEdge * 1.08 && abs(t1) > rowEdge * 1.08) continue;

      let x0 = cx + t0 * rx * 0.92;
      let x1 = cx + t1 * rx * 0.92;
      let xm = (x0 + x1) * 0.5;

      let isOver = (i + j) % 2 === 0;
      if (isOver) {
        // Weft goes OVER warp: plump sunlit stitch segment
        let pA = toWorld(x0 - 1.2, ly);
        let pB = toWorld(xm, ly - 1.2);
        let pC = toWorld(x1 + 1.2, ly);
        let weftCol = j % 4 === 0 ? PAL.pastelBlueLight : PAL.pastelRoseLight;
        brush.set("cpencil", weftCol, 1.05);
        brush.spline([pA, pB, pC], 0.3);

        // Tiny shadow under the over-bridge
        let psA = toWorld(x0, ly + 1.8);
        let psC = toWorld(x1, ly + 1.8);
        brush.set("2B", PAL.pastelRoseDark, 0.42);
        brush.line(psA[0], psA[1], psC[0], psC[1]);
      } else {
        // Weft goes UNDER warp: recessed dark segment, and warp pops over top
        let pA = toWorld(x0 + 1.2, ly + 0.6);
        let pC = toWorld(x1 - 1.2, ly + 0.6);
        brush.set("2B", PAL.pastelRoseDark, 0.58);
        brush.line(pA[0], pA[1], pC[0], pC[1]);

        // Re-assert the vertical warp bridge crossing over this weft thread
        let wx = x0;
        let wp1 = toWorld(wx, ly - 3.2);
        let wp2 = toWorld(wx, ly + 3.2);
        let warpBridgeCol = i % 3 === 0 ? PAL.pastelBlueLight : PAL.pastelRose;
        brush.set("cpencil", warpBridgeCol, 0.95);
        brush.line(wp1[0], wp1[1], wp2[0], wp2[1]);
      }
    }

    // Left and right anchoring whip-stitches into the wool at ends of weft row
    let xLeft = cx - rowEdge * rx * 0.98 - random(3, 9);
    let xRight = cx + rowEdge * rx * 0.98 + random(3, 9);
    let pL1 = toWorld(xLeft, ly + random(-2, 2));
    let pL2 = toWorld(cx - rowEdge * rx * 0.85, ly);
    let pR1 = toWorld(cx + rowEdge * rx * 0.85, ly);
    let pR2 = toWorld(xRight, ly + random(-2, 2));
    brush.set("cpencil", PAL.pastelRose, 0.72);
    brush.line(pL1[0], pL1[1], pL2[0], pL2[1]);
    brush.line(pR1[0], pR1[1], pR2[0], pR2[1]);
  }
  resetBrush();
}

function drawSmallSecondaryMend(cfg, uCenter, vCenter) {
  // Neat diagonal darning stitches over a small worn spot on the second mitten
  let toWorld = getMittenTransform(cfg);
  let hw = getMittenHalfWidth(vCenter, cfg.scale);
  let cx = uCenter * hw;
  let cy = vCenter * cfg.len;

  resetBrush();
  for (let i = -3; i <= 3; i++) {
    let p1 = toWorld(cx + i * 5.5 - 6, cy - 12 + abs(i) * 2);
    let p2 = toWorld(cx + i * 5.5 + 6, cy + 12 - abs(i) * 2);
    brush.set("cpencil", PAL.pastelSage, 0.82);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    let p3 = toWorld(cx - 16 + abs(i) * 2, cy + i * 4);
    let p4 = toWorld(cx + 16 - abs(i) * 2, cy + i * 4);
    brush.set("HB", PAL.pastelSageDark, 0.55);
    brush.line(p3[0], p3[1], p4[0], p4[1]);
  }
  resetBrush();
}

function drawFeltedWoolHalo(cfg, bodyPoly, thumbPoly) {
  let toWorld = getMittenTransform(cfg);
  resetBrush();

  // 1. Interior felted wool fibers (matted curly diagonal micro-hairs blurring the stitches)
  for (let i = 0; i < 420; i++) {
    let v = random(0.03, 0.96);
    let u = random(-0.92, 0.92);
    let hw = getMittenHalfWidth(v, cfg.scale);
    let bendX = sin(v * 180) * 6 * cfg.thumbSide;

    let lx = bendX + u * hw;
    let ly = v * cfg.len;
    let p1 = toWorld(lx, ly);

    // Wet wool fibers cling downward; dry upper wool fibers curl in all directions
    let isWet = v > 0.58;
    let ang = isWet ? random(65, 115) : random(0, 360);
    let fLen = isWet ? random(6, 13) : random(5, 11);
    let p2 = [p1[0] + cos(ang) * fLen, p1[1] + sin(ang) * fLen];

    let fCol = isWet
      ? u < 0 ? PAL.woolWetMid : PAL.woolWetDeep
      : u < 0 ? "#fbf8f2" : PAL.woolShadow;
    brush.set("wool_fiber", fCol, isWet ? 0.35 : 0.3);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Backlit Fuzzy Halo Around the Outer Perimeter of Hand & Thumb
  const allContours = [bodyPoly, thumbPoly];
  for (let poly of allContours) {
    let n = poly.length;
    for (let i = 0; i < n; i++) {
      let pA = poly[i];
      let pB = poly[(i + 1) % n];
      let segLen = dist(pA[0], pA[1], pB[0], pB[1]);
      let steps = max(2, floor(segLen / 3.2));

      // Outward normal
      let dx = pB[0] - pA[0];
      let dy = pB[1] - pA[1];
      let nx = dy / (segLen + 0.001);
      let ny = -dx / (segLen + 0.001);

      for (let s = 0; s < steps; s++) {
        let t = (s + random()) / steps;
        let bx = lerp(pA[0], pB[0], t);
        let by = lerp(pA[1], pB[1], t);

        let isLowerWet = by > 610;
        let isLeftSunlit = nx < 0;

        // Wet fibers at the bottom mat down along the contour; upper dry fibers fluff outward
        let len = isLowerWet ? random(3, 7) : random(5, 13);
        let tipX = bx + nx * len + random(-2.5, 2.5);
        let tipY = by + ny * len + (isLowerWet ? random(3, 7) : random(-2.5, 2.5));

        let haloCol = isLeftSunlit
          ? isLowerWet ? PAL.woolWarm : "#fcfaf5"
          : isLowerWet ? PAL.woolWetDark : PAL.woolMid;

        brush.set("wool_fiber", haloCol, isLowerWet ? 0.36 : 0.42);
        brush.line(bx, by, tipX, tipY);
      }
    }
  }

  // 3. Rim-light & contour definition on the mitten silhouette
  strokePoly(bodyPoly, "2H", PAL.woolWetDeep, 0.42, 0.25, true);
  strokePoly(thumbPoly, "2H", PAL.woolWetDeep, 0.42, 0.25, true);
  resetBrush();
}

// ============================================================================
// 7. BRAIDED HANGING STRING & FORGED IRON NAIL
// ============================================================================
function drawStringAndNail() {
  let nailX = 598;
  let nailY = 136;

  let leftAttach = getMittenTransform(LEFT_MITTEN)(-66, 6);
  let rightAttach = getMittenTransform(RIGHT_MITTEN)(66, 6);

  // Build smooth catenary-like spline paths from nail to each cuff
  let leftCord = [];
  let rightCord = [];
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let sag = sin(t * 180) * 18;
    let lx = lerp(nailX - 3, leftAttach[0], t) - sin(t * 180) * 6;
    let ly = lerp(nailY + 2, leftAttach[1], t) + sag;
    leftCord.push([lx, ly]);

    let rx = lerp(nailX + 3, rightAttach[0], t) + sin(t * 180) * 6;
    let ry = lerp(nailY + 2, rightAttach[1], t) + sag;
    rightCord.push([rx, ry]);
  }

  // Draw 2-ply twisted yarn braid for both sides of the string
  const cords = [leftCord, rightCord];
  resetBrush();
  for (let cord of cords) {
    // Base dark cord core
    strokePoly(cord, "2B", PAL.woolWetDark, 1.35, 0.3, false);

    // Individual twisted yarn plies (cream, pastel rose, and slate-blue)
    for (let i = 0; i < cord.length - 1; i++) {
      let p0 = cord[i];
      let p1 = cord[i + 1];
      let dx = p1[0] - p0[0];
      let dy = p1[1] - p0[1];
      let l = sqrt(dx * dx + dy * dy) + 0.001;
      let nx = -dy / l;
      let ny = dx / l;

      let wave1 = sin(i * 55) * 2.6;
      let wave2 = -wave1;

      let plyCol1 = i % 3 === 0 ? PAL.pastelRoseLight : PAL.woolCream;
      let plyCol2 = i % 3 === 1 ? PAL.pastelBlue : PAL.woolShadow;

      brush.set("cpencil", plyCol1, 0.85);
      brush.line(p0[0] + nx * wave1, p0[1] + ny * wave1, p1[0] + nx * wave2, p1[1] + ny * wave2);

      brush.set("HB", plyCol2, 0.72);
      brush.line(p0[0] + nx * wave2, p0[1] + ny * wave2, p1[0] + nx * wave1, p1[1] + ny * wave1);

      // Fuzzy stray wool hairs sticking out from the wet braided cord
      if (i % 2 === 0) {
        let hx = p0[0] + nx * random(-7, 7);
        let hy = p0[1] + ny * random(-7, 7);
        brush.set("wool_fiber", "#f9f6f0", 0.32);
        brush.line(p0[0], p0[1], hx, hy);
      }
    }
  }

  // Whipped yarn knot / loop where string attaches to each cuff corner
  const attachPts = [leftAttach, rightAttach];
  for (let ap of attachPts) {
    for (let k = -2; k <= 2; k++) {
      brush.set("cpencil", k % 2 === 0 ? PAL.pastelRose : PAL.woolCream, 0.85);
      brush.line(ap[0] - 5, ap[1] + k * 2.2, ap[0] + 6, ap[1] + k * 2.2 + 2);
    }
  }

  // --- Forged Square-Headed Iron Nail / Pin Driven into the Wall at (598, 136) ---
  // Nail cast shadow on plank
  let nailShadow = [
    [nailX + 2, nailY + 2],
    [nailX + 24, nailY + 28],
    [nailX + 14, nailY + 34],
    [nailX - 4, nailY + 8]
  ];
  fillPoly(nailShadow, "#1c242b", 135, 0.2, 0.4, 0.3, 0.15);

  // Rust stain bleeding slightly into wood grain below nail
  let rustPts = makeEllipsePts(nailX + 1, nailY + 14, 7, 16, 10);
  fillPoly(rustPts, "#7c4b3a", 75, 0.35, 0.6, 0.3);

  // Iron nail shank & hand-forged faceted head
  let shankPts = [
    [nailX - 4, nailY - 2],
    [nailX + 5, nailY - 2],
    [nailX + 3, nailY + 11],
    [nailX - 3, nailY + 11]
  ];
  washPoly(shankPts, "#2b2624", 245, 0.1);

  let headPts = [
    [nailX - 11, nailY - 11],
    [nailX + 10, nailY - 12],
    [nailX + 12, nailY + 3],
    [nailX - 9, nailY + 4]
  ];
  washPoly(headPts, "#332a27", 250, 0.12);
  strokePoly(headPts, "folk_ink", "#161413", 0.7, 0.12, true);

  // Metallic top-left bevel catch-light on the forged iron head
  resetBrush();
  brush.set("cpencil", "#cad4dc", 0.8);
  brush.line(nailX - 9, nailY - 10, nailX + 7, nailY - 10);
  brush.line(nailX - 9, nailY - 10, nailX - 8, nailY + 1);
  brush.set("cpencil", "#8c5846", 0.65);
  brush.line(nailX - 4, nailY - 4, nailX + 6, nailY - 1);
  resetBrush();
}

// ============================================================================
// 8. GLISTENING WATER DROPLETS
// ============================================================================
function drawWaterDroplets() {
  // Compute exact tip coordinates of mittens & thumbs
  let leftTip = getMittenTransform(LEFT_MITTEN)(0, LEFT_MITTEN.len);
  let rightTip = getMittenTransform(RIGHT_MITTEN)(0, RIGHT_MITTEN.len);

  const drops = [
    // Hanging directly from the waterlogged mitten tips
    { x: leftTip[0] - 2, y: leftTip[1] + 7, r: 6.5, hanging: true },
    { x: leftTip[0] - 18, y: leftTip[1] - 3, r: 4.5, hanging: true },
    { x: rightTip[0] + 2, y: rightTip[1] + 7, r: 6.8, hanging: true },
    { x: rightTip[0] + 17, y: rightTip[1] - 4, r: 4.5, hanging: true },
    // Hanging from thumb tips
    { x: 352, y: 646, r: 5.5, hanging: true },
    { x: 846, y: 659, r: 5.5, hanging: true },
    // Sliding down the darkened drip tracks on the planks below
    { x: 449, y: 882, r: 4.8, hanging: false },
    { x: 432, y: 964, r: 4.2, hanging: false },
    { x: 451, y: 1085, r: 4.5, hanging: false },
    { x: 754, y: 905, r: 5.0, hanging: false },
    { x: 739, y: 1012, r: 4.2, hanging: false },
    { x: 755, y: 1122, r: 4.4, hanging: false },
    { x: 353, y: 815, r: 3.8, hanging: false },
    { x: 845, y: 832, r: 3.8, hanging: false }
  ];

  for (let d of drops) {
    // Teardrop silhouette
    let pts = [
      [d.x, d.y - d.r * 1.45],
      [d.x + d.r * 0.88, d.y + d.r * 0.15],
      [d.x + d.r * 0.55, d.y + d.r * 0.95],
      [d.x, d.y + d.r * 1.15],
      [d.x - d.r * 0.55, d.y + d.r * 0.95],
      [d.x - d.r * 0.88, d.y + d.r * 0.15]
    ];

    // Tiny dark shadow beneath droplet
    let shPts = makeEllipsePts(d.x + 2, d.y + d.r * 0.5, d.r * 0.8, d.r * 0.9, 10);
    fillPoly(shPts, "#23313b", 125, 0.15, 0.4, 0.3);

    // Translucent water body
    washPoly(pts, "#7a92a1", 165, 0.3);

    // Dark upper-left internal refraction
    resetBrush();
    brush.set("2B", "#26353f", 0.58);
    brush.arc(d.x, d.y + d.r * 0.15, d.r * 0.72, 195, 330);

    // Secondary lower-right caustic glow
    brush.set("cpencil", "#dce9f0", 0.65);
    brush.arc(d.x, d.y + d.r * 0.2, d.r * 0.65, 15, 125);

    // Crisp bright white specular highlight on upper-left of droplet
    brush.set("cpencil", "#ffffff", 0.95);
    brush.line(d.x - d.r * 0.38, d.y - d.r * 0.25, d.x - d.r * 0.22, d.y + d.r * 0.15);
    brush.set("pen", "#ffffff", 0.65);
    brush.line(d.x - d.r * 0.3, d.y - d.r * 0.1, d.x - d.r * 0.28, d.y - d.r * 0.02);
  }
  resetBrush();
}

// ============================================================================
// 9. FAINT STEAM RISING FROM THE WET MITTENS
// ============================================================================
function drawRisingSteam() {
  // Soft translucent plumes drifting upward from the damp wool mittens (y = 560 up to y = 75)
  const plumes = [
    { x0: 415, y0: 540, y1: 115, amp: 26, phase: 0 },
    { x0: 472, y0: 465, y1: 85, amp: 32, phase: 75 },
    { x0: 525, y0: 575, y1: 165, amp: 24, phase: 140 },
    { x0: 685, y0: 585, y1: 170, amp: 24, phase: 210 },
    { x0: 738, y0: 475, y1: 90, amp: 30, phase: 290 },
    { x0: 792, y0: 545, y1: 125, amp: 26, phase: 35 }
  ];

  // 1. Delicate low-opacity watercolor vapor blooms
  for (let pl of plumes) {
    for (let k = 0; k < 5; k++) {
      let t = (k + 0.5) / 5;
      let py = lerp(pl.y0, pl.y1, t);
      let px = pl.x0 + sin(t * 320 + pl.phase) * pl.amp * (0.4 + t * 0.8);
      let rx = lerp(18, 46, t);
      let ry = lerp(28, 56, t);
      let wPts = makeEllipsePts(px, py, rx, ry, 14, sin(t * 180) * 20, 0.3);
      fillPoly(wPts, "#f3f7fa", 19, 0.48, 0.35, 0.1, 0.35);
    }
  }

  // 2. Whisper-thin curling vapor filaments in spray & soft white colored pencil
  resetBrush();
  for (let pl of plumes) {
    for (let strand = -2; strand <= 2; strand++) {
      let pts = [];
      let steps = 16;
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let y = lerp(pl.y0, pl.y1, t);
        let spread = strand * lerp(5, 22, t);
        let wave =
          sin(t * 340 + pl.phase + strand * 28) * pl.amp * (0.35 + t * 0.75) +
          (noise(pl.x0 * 0.02 + strand, t * 3.5) - 0.5) * 18;
        pts.push([pl.x0 + spread + wave, y]);
      }

      brush.set("steam_wisp", "#f5f8fa", 0.85);
      brush.spline(pts, 0.45);

      if (abs(strand) <= 1) {
        brush.set("2H", "#eef3f6", 0.32);
        brush.spline(pts, 0.45);
      }
    }
  }
  resetBrush();
}

// Hyperrealism meets violent gestural expressionism:
// A black-and-tan dog mid-shake with a razor-sharp hyperreal eye, wet nose, and droplet-laden whiskers at dead centre.

const PAL = {
  paper: "#efe8da",
  paperWarm: "#e5dac6",
  paperShadow: "#d4c7b0",

  // Charcoal blacks & warm darks
  voidBlack: "#070708",
  charcoalDeep: "#121110",
  charcoal: "#1e1c1a",
  charcoalMid: "#33302c",
  charcoalSoft: "#4d4843",

  // Raw umber & black-and-tan markings
  umberDark: "#3b2210",
  umber: "#633a1b",
  umberRich: "#8a5224",
  umberWarm: "#b06d32",
  tanGlow: "#cfa56f",
  tanLight: "#e6c79c",

  // Cold greys (wet sheen, water arcs, rhinarium highlights)
  greyAbyss: "#1c2024",
  greyDark: "#384047",
  greyMid: "#5c6770",
  greyCold: "#83919c",
  greyLight: "#aebbc4",
  greyIce: "#d8e2e8",

  // Single burst of sky-blue in the spray
  skyDeep: "#1b6ca8",
  skyVivid: "#3399ff",
  skyBright: "#6ec2ff",
  skyPale: "#b8e2ff",

  // Specular white
  white: "#ffffff",
  ivory: "#f7f4eb"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88412);

  // Register custom brushes for both violent broad gestures and hyperreal micro-detail
  brush.add("broad_charcoal", {
    type: "default",
    weight: 16,
    scatter: 0.45,
    sharpness: 0.25,
    grain: 18,
    opacity: 155,
    spacing: 0.18,
    pressure: [0.3, 1.35, 0.2],
    rotate: "natural",
    noise: 0.85
  });

  brush.add("dragged_marker", {
    type: "custom",
    weight: 12,
    scatter: 0.12,
    opacity: 95,
    spacing: 0.12,
    pressure: [0.8, 1.2, 0.3],
    tip: (_m) => {
      _m.rotate(28);
      _m.rect(-4, -0.9, 8, 1.8);
      _m.rect(-3, 1.3, 6, 0.6);
    },
    rotate: "natural",
    markerTip: true,
    noise: 0.4
  });

  brush.add("micro_pen", {
    type: "default",
    weight: 0.28,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 2,
    opacity: 245,
    spacing: 0.08,
    pressure: [0.6, 1.0, 0.5],
    rotate: "none",
    noise: 0.08
  });

  brush.add("fine_hair", {
    type: "default",
    weight: 0.48,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 5,
    opacity: 210,
    spacing: 0.1,
    pressure: [0.2, 1.0, 0.1],
    rotate: "natural",
    noise: 0.2
  });

  brush.add("pebble_glaze", {
    type: "default",
    weight: 0.65,
    scatter: 0.05,
    sharpness: 0.75,
    grain: 6,
    opacity: 190,
    spacing: 0.12,
    pressure: [0.5, 1.1, 0.5],
    rotate: "natural",
    noise: 0.15
  });

  // Rotational vortex vector field for mid-shake centrifugal flow
  brush.addField("shake_vortex", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let x = map(col, 0, field.length - 1, 0, 1200);
        let y = map(row, 0, field[0].length - 1, 0, 1200);
        let dx = x - 600;
        let dy = y - 575;
        let radialAngle = atan2(dy, dx);
        let distNorm = constrain( sqrt(dx * dx + dy * dy) / 650, 0, 1 );
        // Spiral outward clockwise with turbulent whip
        let swirl = radialAngle + 68 - distNorm * 28 + (noise(col * 0.12, row * 0.12) - 0.5) * 35;
        field[col][row] = swirl;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // 1. Warm paper surface undertone & atmospheric watercolor washes
  renderPaperAndUnderwashes();

  // 2. Violent sweeping water arcs, dragged marker slashes & broad charcoal vortex
  renderGesturalWaterArcs();

  // 3. The single burst of sky-blue in the right-upper water spray
  renderSkyBlueSprayBurst();

  // 4. Blurred mid-shake head, flung ears, whipping jowls & neck torso
  renderBlurredHeadAndEars();

  // 5. Transition zone: sharp muzzle bridge, tan eyebrow spot & mystacial pads
  renderMuzzleAndFurBridge();

  // 6. DEAD CENTRE HYPERREAL ANCHOR I: The Wet Nose (Rhinarium, nostrils, cobblestone pebbles)
  renderHyperrealWetNose(638, 634);

  // 7. DEAD CENTRE HYPERREAL ANCHOR II: The One Eye (Iris fibers, eyelids, reflected window)
  renderHyperrealEye(528, 496);

  // 8. DEAD CENTRE HYPERREAL ANCHOR III: Whiskers & Clinging Water Droplets
  renderWhiskersAndDroplets();

  // 9. Foreground violent spatter, dark accents & high-speed water streaks
  renderForegroundSpatter();

  noLoop();
}

// ============================================================================
// 1. PAPER GROUND & ATMOSPHERIC UNDERWASHES
// ============================================================================
function renderPaperAndUnderwashes() {
  brush.noStroke();

  // Subtle warm paper grain hatches across the sheet
  brush.hatchStyle("2H", PAL.paperWarm, 0.4);
  brush.hatch(14, 18, { rand: 0.35, gradient: 0.4 });
  brush.rect(20, 20, 1160, 1160);
  brush.noHatch();

  // Batched watercolor washes for the dog's dark core and raw umber warmth
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.35);

  // Cold grey water vortex wash
  brush.fill(PAL.greyLight, 52);
  drawBlob(600, 560, 440, 390, 12, 0.35);
  drawBlob(820, 390, 260, 210, 9, 0.4);
  drawBlob(340, 420, 250, 190, 9, 0.4);

  // Warm raw umber washes around muzzle, brow, and flung ears
  brush.fill(PAL.umberWarm, 58);
  drawBlob(530, 440, 110, 85, 8, 0.25); // Sharp brow spot glow
  drawBlob(515, 650, 150, 130, 8, 0.3); // Left tan cheek
  drawBlob(755, 605, 145, 135, 8, 0.3); // Right tan cheek blur
  drawBlob(320, 390, 180, 110, 8, 0.4); // Left flung inner ear warmth
  drawBlob(620, 830, 260, 180, 9, 0.35); // Chest/neck tan warmth

  // Deep charcoal core shadow underwash
  brush.fill(PAL.charcoal, 88);
  drawBlob(605, 580, 240, 255, 10, 0.25);
  drawBlob(595, 790, 230, 210, 10, 0.35);

  brush.noFill();
}

function drawBlob(cx, cy, rx, ry, steps, irreg) {
  brush.beginShape(0.65);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let rMod = 1 + ( random(-irreg, irreg) );
    let x = cx + cos(a) * rx * rMod;
    let y = cy + sin(a) * ry * rMod;
    brush.vertex(x, y);
  }
  brush.endShape(true);
}

// ============================================================================
// 2. VIOLENT SWEEPING WATER ARCS (CHARCOAL & DRAGGED MARKER)
// ============================================================================
function renderGesturalWaterArcs() {
  let cx = 600;
  let cy = 570;

  // A. Dragged marker broad sweeping arcs (cold grey, slate, raw umber)
  const markerArcs = [
    // Huge upper-left to upper-right whip
    { startA: 155, endA: 335, r1: 210, r2: 530, col: PAL.greyCold, w: 1.5, brush: "dragged_marker" },
    { startA: 170, endA: 350, r1: 240, r2: 560, col: PAL.greyMid, w: 1.2, brush: "dragged_marker" },
    { startA: 195, endA: 315, r1: 180, r2: 430, col: PAL.umber, w: 1.1, brush: "dragged_marker" },
    // Right-side downward whip
    { startA: 290, endA: 445, r1: 200, r2: 540, col: PAL.greyDark, w: 1.4, brush: "dragged_marker" },
    { startA: 310, endA: 465, r1: 230, r2: 580, col: PAL.greyCold, w: 1.6, brush: "marker" },
    // Bottom-right to bottom-left jowl water sling
    { startA: 25,  endA: 175, r1: 190, r2: 510, col: PAL.greyMid, w: 1.3, brush: "dragged_marker" },
    { startA: 45,  endA: 195, r1: 220, r2: 550, col: PAL.umberDark, w: 1.2, brush: "dragged_marker" },
    // Left-side upward fling
    { startA: 110, endA: 265, r1: 175, r2: 495, col: PAL.greyCold, w: 1.5, brush: "dragged_marker" },
    { startA: 130, endA: 280, r1: 235, r2: 545, col: PAL.charcoalSoft, w: 1.3, brush: "marker" },
    // Outer violent tangential slashes reaching the sheet edges
    { startA: 210, endA: 305, r1: 310, r2: 640, col: PAL.greyLight, w: 1.8, brush: "dragged_marker" },
    { startA: 330, endA: 415, r1: 280, r2: 610, col: PAL.greyMid, w: 1.5, brush: "dragged_marker" },
    { startA: 65,  endA: 155, r1: 260, r2: 590, col: PAL.greyCold, w: 1.4, brush: "dragged_marker" }
  ];

  for (let arcDef of markerArcs) {
    brush.set(arcDef.brush, arcDef.col, arcDef.w);
    let pts = [];
    let steps = 14;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = lerp(arcDef.startA, arcDef.endA, t);
      let r = lerp(arcDef.r1, arcDef.r2, pow(t, 0.85)) + random(-14, 14);
      let x = cx + cos(a) * r * 1.06;
      let y = cy + sin(a) * r * 0.96;
      let p = sin(t * 180) * 1.2 + 0.25;
      pts.push([x, y, p]);
    }
    brush.spline(pts, 0.65);
  }

  // B. Broad violent charcoal slashes & vortex arcs
  const charcoalArcs = [
    { startA: 145, endA: 295, r1: 170, r2: 520, col: PAL.charcoal, w: 1.35 },
    { startA: 165, endA: 270, r1: 145, r2: 430, col: PAL.charcoalDeep, w: 1.15 },
    { startA: 255, endA: 385, r1: 185, r2: 530, col: PAL.charcoal, w: 1.25 },
    { startA: 285, endA: 410, r1: 160, r2: 460, col: PAL.umberDark, w: 1.1 },
    { startA: 15,  endA: 145, r1: 175, r2: 490, col: PAL.charcoal, w: 1.3 },
    { startA: 85,  endA: 215, r1: 165, r2: 510, col: PAL.charcoalDeep, w: 1.2 },
    { startA: 205, endA: 340, r1: 260, r2: 590, col: PAL.charcoalMid, w: 0.95 },
    { startA: 320, endA: 440, r1: 250, r2: 575, col: PAL.charcoalMid, w: 1.0 }
  ];

  for (let cArc of charcoalArcs) {
    brush.set("broad_charcoal", cArc.col, cArc.w);
    let pts = [];
    let steps = 12;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = lerp(cArc.startA, cArc.endA, t);
      let r = lerp(cArc.r1, cArc.r2, t) + random(-18, 18);
      let x = cx + cos(a) * r;
      let y = cy + sin(a) * r;
      pts.push([x, y, (1 - t * 0.55) * 1.3]);
    }
    brush.spline(pts, 0.7);
  }

  // C. Vector-field driven charcoal & cold-grey motion whip lines
  brush.field("shake_vortex");
  for (let i = 0; i < 160; i++) {
    let a = random(360);
    let r = random(175, 540);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let dir = a + 72 + random(-18, 18);
    let len = random(65, 220);

    let pick = random();
    if (pick < 0.42) {
      brush.set("charcoal", PAL.charcoal, random(0.5, 1.3));
    } else if (pick < 0.75) {
      brush.set("charcoal", PAL.greyDark, random(0.4, 1.1));
    } else {
      brush.set("2B", PAL.umber, random(0.5, 1.2));
    }
    brush.flowLine(x, y, len, dir);
  }
  brush.noField();

  // D. Sharp tangential dry-brush & marker whip lines slicing across the arcs
  for (let i = 0; i < 65; i++) {
    let a = random(360);
    let r = random(190, 480);
    let x1 = cx + cos(a) * r;
    let y1 = cy + sin(a) * r;
    let tang = a + 78 + random(-14, 14);
    let slashLen = random(90, 290);
    let x2 = x1 + cos(tang) * slashLen;
    let y2 = y1 + sin(tang) * slashLen;

    if (random() < 0.5) {
      brush.set("charcoal", random([PAL.charcoalDeep, PAL.charcoalMid, PAL.greyDark]), random(0.4, 0.95));
    } else {
      brush.set("rotring", random([PAL.charcoal, PAL.greyMid, PAL.umberDark]), random(0.35, 0.8));
    }
    brush.line(x1, y1, x2, y2);
  }
}

