    brush.set("2B", random([PAL.greyLight, PAL.greyIce, PAL.tanLight]), random(0.4, 0.8));
    let sx = random(460, 780);
    let sy = random(710, 780);
    let dir = sx < 620 ? random(135, 195) : random(-25, 45);
    let d = random(55, 165);
    brush.spline([
      [sx, sy, 0.9],
      [sx + cos(dir) * d * 0.5, sy + sin(dir) * d * 0.5 + 15, 0.7],
      [sx + cos(dir) * d, sy + sin(dir) * d + 5, 0.1]
    ], 0.6);
  }
}

// ============================================================================
// 5. SHARP MUZZLE BRIDGE, TAN EYEBROW SPOT & MYSTACIAL PADS
// ============================================================================
function renderMuzzleAndFurBridge() {
  // Now we transition from the peripheral motion blur into high-frequency hyperreal fur
  // around the focal eye (528, 496) and the wet nose (638, 634).

  // A. Sharp Tan Eyebrow Spot (Superciliary arch above the focal eye: centered ~ 532, 432)
  for (let i = 0; i < 160; i++) {
    let a = random(-165, -15);
    let r = random(4, 46);
    let fx = 534 + cos(a) * r * 1.15 + random(-8, 8);
    let fy = 442 + sin(a) * r * 0.75 + random(-6, 6);
    let hairAng = -115 + (fx - 534) * 0.6 + random(-12, 12);
    let hairLen = random(12, 28);
    let col = random([PAL.umberDark, PAL.umber, PAL.umberRich, PAL.umberWarm, PAL.tanGlow, PAL.tanLight]);
    brush.set("fine_hair", col, random(0.55, 1.1));
    brush.line(fx, fy, fx + cos(hairAng) * hairLen, fy + sin(hairAng) * hairLen);
  }

  // B. Left & Right Tan Mystacial (Whisker) Pads & Cheek Transitions
  // Left whisker pad (x: 455..580, y: 555..715)
  for (let i = 0; i < 320; i++) {
    let fx = random(450, 585);
    let fy = random(545, 720);
    // Keep outside the nose pad itself
    if (dist(fx, fy, 638, 634) < 82) continue;
    let dEye = dist(fx, fy, 528, 496);
    if (dEye < 46) continue;

    // Fur flows downward-left from under the eye and radially around the whisker pad
    let hairAng = atan2(fy - 510, fx - 575) + 25 + random(-10, 10);
    let hairLen = map(constrain(dist(fx, fy, 560, 600), 0, 160), 0, 160, 14, 38);

    // Classic Black-and-Tan pattern: rich raw umber/tan on the lower cheek & whisker pad, dark charcoal bridge
    let isBridge = (fx > 545 && fy < 605);
    let col;
    if (isBridge) {
      col = random([PAL.voidBlack, PAL.charcoalDeep, PAL.charcoal, PAL.greyDark]);
    } else {
      col = random([PAL.umberDark, PAL.umber, PAL.umberRich, PAL.umberWarm, PAL.tanGlow, PAL.charcoalDeep]);
    }
    brush.set("fine_hair", col, random(0.5, 1.15));
    brush.line(fx, fy, fx + cos(hairAng) * hairLen, fy + sin(hairAng) * hairLen);
  }

  // Right whisker pad (x: 685..795, y: 545..695)
  for (let i = 0; i < 220; i++) {
    let fx = random(680, 800);
    let fy = random(540, 700);
    if (dist(fx, fy, 638, 634) < 84) continue;
    let hairAng = atan2(fy - 520, fx - 620) - 10 + random(-12, 12);
    let hairLen = map(constrain(fx - 680, 0, 120), 0, 120, 15, 48);
    let col = random([PAL.umberDark, PAL.umber, PAL.umberRich, PAL.umberWarm, PAL.charcoalDeep, PAL.charcoal]);
    brush.set("fine_hair", col, random(0.55, 1.2));
    brush.line(fx, fy, fx + cos(hairAng) * hairLen, fy + sin(hairAng) * hairLen);
  }

  // C. Razor-sharp Nasal Bridge (Dorsum Nasi) connecting eye to wet nose
  // Rich wet charcoal-black short fur with glistening cold-grey sheen along the dorsal ridge
  for (let i = 0; i < 380; i++) {
    let t = random(0, 1);
    let spineX = lerp(572, 632, t);
    let spineY = lerp(485, 578, t);
    let spread = lerp(55, 68, t);
    let off = randomGaussian(0, spread * 0.45);
    let fx = spineX + off;
    let fy = spineY + random(-14, 14);

    // Direction fans outward from the nasal midline
    let baseAng = 62 + ( off / spread ) * 52 + random(-8, 8);
    let hairLen = random(9, 20);

    // Specular wet sheen along the center of the bridge
    let isHighlight = abs(off) < 18 && random() < 0.38;
    let col;
    if (isHighlight) {
      col = random([PAL.greyMid, PAL.greyCold, PAL.greyLight, PAL.greyIce]);
    } else if (abs(off) > 36 && random() < 0.35) {
      col = random([PAL.umberDark, PAL.umber, PAL.charcoal]);
    } else {
      col = random([PAL.voidBlack, PAL.charcoalDeep, PAL.charcoal, PAL.greyAbyss]);
    }

    brush.set("fine_hair", col, isHighlight ? random(0.4, 0.75) : random(0.55, 1.05));
    brush.line(fx, fy, fx + cos(baseAng) * hairLen, fy + sin(baseAng) * hairLen);
  }
}

// ============================================================================
// 6. DEAD CENTRE HYPERREAL ANCHOR I: THE WET NOSE (RHINARIUM)
// ============================================================================
function renderHyperrealWetNose(nx, ny) {
  // Nose dimensions: width ~ 156px, height ~ 124px, tilted ~ -7 deg with the shake pivot
  // 1. Deep foundational dark mass of the leathery rhinarium
  brush.noStroke();
  brush.wash(PAL.charcoalDeep, 240);
  drawNoseContour(nx, ny, 1.0);
  brush.noWash();

  // Soft internal shading layers for 3D spherical/lobed volume
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.4, 0.2);

  // Cold grey wet dorsal plane (top of nose)
  brush.fill(PAL.greyDark, 145);
  brush.beginShape(0.55);
  brush.vertex(nx - 66, ny - 34);
  brush.vertex(nx - 25, ny - 54);
  brush.vertex(nx + 28, ny - 56);
  brush.vertex(nx + 68, ny - 38);
  brush.vertex(nx + 52, ny - 8);
  brush.vertex(nx, ny - 2);
  brush.vertex(nx - 54, ny - 6);
  brush.endShape(true);

  // Warm raw-umber subsurface reflection underneath the nostrils & philtrum base
  brush.fill(PAL.umberDark, 120);
  brush.beginShape(0.5);
  brush.vertex(nx - 56, ny + 26);
  brush.vertex(nx, ny + 18);
  brush.vertex(nx + 56, ny + 22);
  brush.vertex(nx + 32, ny + 62);
  brush.vertex(nx, ny + 74);
  brush.vertex(nx - 34, ny + 64);
  brush.endShape(true);
  brush.noFill();

  // 2. Pebbled Cobblestone Texture (Rhinarium Dermatoglyphics)
  // Generate a dense jittered grid of ~440 polygonal/rounded skin pebbles across the nose pad
  let step = 5.4;
  for (let dy = -56; dy <= 68; dy += step) {
    for (let dx = -76; dx <= 76; dx += step) {
      let px = nx + dx + random(-1.6, 1.6);
      let py = ny + dy + random(-1.6, 1.6);

      if (!isInsideNose(px - nx, py - ny)) continue;

      // Exclude deep inside the left and right nostril openings
      let dLeftNostril = dist(px, py, nx - 41, ny - 6);
      let dRightNostril = dist(px, py, nx + 43, ny - 10);
      if (dLeftNostril < 18 || dRightNostril < 18) continue;

      // Pebble size tapers toward the edges and lower philtrum
      let pRadius = map(constrain(dy, -56, 68), -56, 68, 2.5, 1.4) * random(0.8, 1.18);

      // Dark crevice outline around each pebble
      brush.set("micro_pen", PAL.voidBlack, 0.75);
      brush.circle(px, py, pRadius, 0.22);

      // Compute surface lighting normal on the 3D nose dome
      // Light source is the bright window at upper-left (dir ~ -0.45, -0.75)
      let normX = dx / 76;
      let normY = (dy + 12) / 62;
      let lightDot = -0.38 * normX - 0.78 * normY + 0.45;

      // Wet highlight on upper dome and alar ridges
      if (lightDot > 0.42 && random() < 0.85) {
        let hCol = lightDot > 0.72 ? PAL.white : (lightDot > 0.56 ? PAL.greyIce : PAL.greyCold);
        brush.set("pebble_glaze", hCol, map(lightDot, 0.42, 1.0, 0.45, 1.05));
        brush.arc(px - 0.4, py - 0.5, pRadius * 0.65, 190, 340);
      } else if (dy > 20 && random() < 0.45) {
        // Subtle warm umber bounce light on lower pebbles
        brush.set("micro_pen", PAL.umber, 0.55);
        brush.arc(px, py + 0.4, pRadius * 0.55, 20, 160);
      } else {
        brush.set("micro_pen", PAL.greyDark, 0.5);
        brush.arc(px - 0.3, py - 0.3, pRadius * 0.55, 200, 320);
      }
    }
  }

  // 3. Deep Nostril Cavities (Naress) & THE MOIST NOSTRIL CREASES
  // Left Nostril (centered around nx - 41, ny - 6)
  renderNostrilAndCrease(nx - 41, ny - 6, -1);
  // Right Nostril (centered around nx + 43, ny - 10)
  renderNostrilAndCrease(nx + 43, ny - 10, 1);

  // 4. Central Philtrum Groove (sharp vertical cleft bisecting the lower nose & upper lip)
  for (let i = 0; i < 18; i++) {
    let offX = map(i, 0, 17, -4.5, 4.5);
    let col = abs(offX) < 1.6 ? PAL.voidBlack : (offX < 0 ? PAL.charcoalDeep : PAL.greyCold);
    brush.set("micro_pen", col, abs(offX) < 1.6 ? 1.15 : 0.75);
    brush.spline([
      [nx + offX * 0.5, ny + 4, 0.5],
      [nx + 1 + offX * 0.8, ny + 38, 1.1],
      [nx + 2 + offX, ny + 76, 0.8]
    ], 0.4);
  }
  // Glistening wet highlight thread along the right lip of the philtrum groove
  brush.set("micro_pen", PAL.white, 0.95);
  brush.spline([
    [nx + 2.2, ny + 10, 0.4],
    [nx + 3.0, ny + 38, 1.2],
    [nx + 3.4, ny + 68, 0.3]
  ], 0.4);

  // 5. Broad Glistening Window Glaze across the wet upper bridge of the nose
  for (let i = 0; i < 26; i++) {
    let y = ny - 46 + i * 1.15;
    let span = map(abs(i - 12), 0, 14, 42, 12);
    brush.set("micro_pen", i % 3 === 0 ? PAL.white : PAL.greyIce, random(0.55, 1.0));
    brush.spline([
      [nx - span - random(0, 8), y + 4, 0.2],
      [nx - span * 0.2, y - 3, 1.1],
      [nx + span * 0.7, y + 1, 0.3]
    ], 0.5);
  }

  // 6. Clinging liquid drops bulging at the bottom rim of the wet nose
  drawHyperrealDroplet(nx - 24, ny + 65, 6.5, 80, false);
  drawHyperrealDroplet(nx + 29, ny + 61, 5.2, 70, false);
  drawHyperrealDroplet(nx - 68, ny + 20, 4.8, 135, false);
}

function drawNoseContour(nx, ny, s) {
  brush.beginShape(0.6);
  brush.vertex(nx - 72 * s, ny - 22 * s);
  brush.vertex(nx - 42 * s, ny - 54 * s);
  brush.vertex(nx,          ny - 58 * s);
  brush.vertex(nx + 44 * s, ny - 56 * s);
  brush.vertex(nx + 74 * s, ny - 26 * s);
  brush.vertex(nx + 78 * s, ny + 8 * s);
  brush.vertex(nx + 54 * s, ny + 44 * s);
  brush.vertex(nx + 22 * s, ny + 70 * s);
  brush.vertex(nx,          ny + 74 * s);
  brush.vertex(nx - 24 * s, ny + 71 * s);
  brush.vertex(nx - 56 * s, ny + 46 * s);
  brush.vertex(nx - 76 * s, ny + 12 * s);
  brush.endShape(true);
}

function isInsideNose(dx, dy) {
  // Normalized heart/rhinarium implicit shape
  let topCheck = dy > -56 + (dx * dx) / 190;
  let botCheck = dy < 72 - abs(dx) * 0.78 - (dx * dx) / 180;
  let sideCheck = abs(dx) < 76 - pow(max(0, dy + 10) / 80, 1.6) * 38;
  return topCheck && botCheck && sideCheck;
}

function renderNostrilAndCrease(cx, cy, side) {
  // Deep velvet-black comma-shaped cavity
  brush.noStroke();
  brush.wash(PAL.voidBlack, 255);
  brush.beginShape(0.55);
  brush.vertex(cx - side * 12, cy - 16);
  brush.vertex(cx + side * 8,  cy - 18);
  brush.vertex(cx + side * 20, cy - 4);
  brush.vertex(cx + side * 24, cy + 14);
  brush.vertex(cx + side * 8,  cy + 20);
  brush.vertex(cx - side * 8,  cy + 10);
  brush.vertex(cx - side * 16, cy - 4);
  brush.endShape(true);
  brush.noWash();

  // Warm moist raw-umber inner mucosal transition inside the nostril floor
  for (let i = 0; i < 18; i++) {
    brush.set("micro_pen", i < 10 ? PAL.umberDark : PAL.charcoalDeep, 0.85);
    let r = map(i, 0, 17, 6, 17);
    brush.spline([
      [cx - side * 10, cy + 2 + i * 0.5, 0.5],
      [cx + side * 4,  cy + 10 + i * 0.5, 1.0],
      [cx + side * 18, cy + 8 + i * 0.3, 0.4]
    ], 0.5);
  }

  // THE MOIST NOSTRIL CREASE (Alar groove curving laterally outward and downward from the nostril)
  for (let j = -4; j <= 4; j++) {
    let col = abs(j) <= 1 ? PAL.voidBlack : (j < 0 ? PAL.charcoalDeep : PAL.umberDark);
    brush.set("micro_pen", col, abs(j) <= 1 ? 1.15 : 0.75);
    brush.spline([
      [cx + side * 10, cy + 8 + j * 0.6, 0.7],
      [cx + side * 24, cy + 16 + j * 0.8, 1.2],
      [cx + side * 34, cy + 28 + j * 0.9, 1.0],
      [cx + side * 30, cy + 44 + j * 0.7, 0.3]
    ], 0.6);
  }

  // Razor-sharp wet liquid meniscus highlight trapped right inside the nostril crease!
  brush.set("micro_pen", PAL.greyIce, 1.1);
  brush.spline([
    [cx + side * 8,  cy + 10.5, 0.5],
    [cx + side * 22, cy + 18.2, 1.3],
    [cx + side * 32, cy + 29.5, 1.0],
    [cx + side * 29, cy + 41.0, 0.2]
  ], 0.6);

  brush.set("micro_pen", PAL.white, 0.85);
  brush.spline([
    [cx + side * 11, cy + 11.2, 0.4],
    [cx + side * 23, cy + 18.8, 1.3],
    [cx + side * 30, cy + 27.5, 0.4]
  ], 0.6);

  // Glossy rim highlight on the upper medial scroll of the nostril
  brush.set("micro_pen", PAL.white, 0.9);
  brush.spline([
    [cx - side * 12, cy - 12, 0.3],
    [cx - side * 15, cy - 2, 1.2],
    [cx - side * 9,  cy + 9, 0.4]
  ], 0.55);
}

// ============================================================================
// 7. DEAD CENTRE HYPERREAL ANCHOR II: THE ONE EYE & REFLECTED WINDOW
// ============================================================================
function renderHyperrealEye(ex, ey) {
  let irisR = 35;
  let pupilR = 13.5;

  // 1. Periorbital shadow socket & leathery eyelids
  brush.noStroke();
  brush.wash(PAL.voidBlack, 250);
  // Almond aperture of the palpebral fissure (tilted slightly with the shake axis)
  brush.beginShape(0.6);
  brush.vertex(ex - 48, ey - 10); // Lateral canthus
  brush.vertex(ex - 22, ey - 36);
  brush.vertex(ex + 14, ey - 35);
  brush.vertex(ex + 44, ey + 14); // Medial canthus (with tear caruncle)
  brush.vertex(ex + 16, ey + 34);
  brush.vertex(ex - 20, ey + 33);
  brush.endShape(true);

  // 2. Iris Base Wash (Rich Raw Umber & Golden Amber)
  brush.wash(PAL.umberDark, 255);
  brush.circle(ex, ey, irisR, 0.04);

  brush.wash(PAL.umberRich, 225);
  brush.circle(ex + 1, ey + 2, irisR * 0.86, 0.04);
  brush.noWash();

  // 3. Detailed Radial Iris Stromal Fibers, Crypts & Collarette Ring
  let numFibers = 220;
  for (let i = 0; i < numFibers; i++) {
    let a = (i / numFibers) * 360 + random(-0.8, 0.8);
    // Upper third of iris is in cast shadow from the upper eyelid
    let inUpperShadow = (a > 195 && a < 345);
    let rInner = pupilR + random(-1, 2.5);
    let rMid = lerp(pupilR, irisR, random(0.42, 0.58)); // Collarette zone
    let rOuter = irisR - random(1.5, 4.5);

    let col1, col2;
    if (inUpperShadow) {
      col1 = random([PAL.umberDark, PAL.charcoalDeep, PAL.umber]);
      col2 = random([PAL.umberDark, PAL.umber]);
    } else {
      col1 = random([PAL.umberRich, PAL.umberWarm, PAL.tanGlow, PAL.umber]);
      col2 = random([PAL.umber, PAL.umberDark, PAL.umberRich, PAL.tanLight]);
    }

    // Inner pupillary zone fiber
    brush.set("micro_pen", col1, random(0.55, 0.95));
    brush.line(
      ex + cos(a) * rInner,
      ey + sin(a) * rInner,
      ex + cos(a + random(-3, 3)) * rMid,
      ey + sin(a + random(-3, 3)) * rMid
    );

    // Outer ciliary zone fiber
    brush.set("micro_pen", col2, random(0.5, 0.9));
    brush.line(
      ex + cos(a + random(-2, 2)) * rMid,
      ey + sin(a + random(-2, 2)) * rMid,
      ex + cos(a) * rOuter,
      ey + sin(a) * rOuter
    );
  }

  // Luminous golden-amber collarette ring highlights in the sun-lit lower-right iris
  for (let i = 0; i < 65; i++) {
    let a = random(-25, 175);
    let r = random(pupilR + 4, irisR - 8);
    let x = ex + cos(a) * r;
    let y = ey + sin(a) * r;
    brush.set("micro_pen", random([PAL.umberWarm, PAL.tanGlow, PAL.tanLight]), random(0.5, 0.9));
    brush.line(x, y, x + cos(a + 15) * 4.5, y + sin(a + 15) * 4.5);
  }

  // 4. Deep Dark Limbal Ring around outer iris & Velvet-Black Pupil
  for (let r = irisR - 3.5; r <= irisR + 1.5; r += 0.7) {
    brush.set("micro_pen", PAL.voidBlack, 1.15);
    brush.circle(ex, ey, r, 0.03);
  }

  brush.noStroke();
  brush.wash(PAL.voidBlack, 255);
  brush.circle(ex, ey, pupilR, 0.02);
  brush.noWash();

  // Crisp pupillary ruff (dark warm rim around the pupil)
  brush.set("micro_pen", PAL.umberDark, 0.8);
  brush.circle(ex, ey, pupilR + 0.8, 0.04);

  // Upper eyelid cast shadow across top of eyeball
  for (let yOff = -34; yOff <= -10; yOff += 1.1) {
    let halfW = sqrt(max(0, 36 * 36 - yOff * yOff));
    brush.set("micro_pen", PAL.voidBlack, map(yOff, -34, -10, 1.2, 0.35));
    brush.line(ex - halfW, ey + yOff, ex + halfW, ey + yOff);
  }

  // 5. THE REFLECTED WINDOW IN THE CORNEA (Spherical 4-Pane Window Reflection!)
  // Positioned across the upper-left curve of the cornea (overlapping pupil & iris)
  renderCornealWindowReflection(ex, ey);

  // 6. Wet Eyelid Rims (Palpebral Margins), Medial Caruncle & Tear Film Meniscus
  // Upper eyelid thick leathery rim & skin fold
  for (let i = -3; i <= 3; i++) {
    let col = abs(i) <= 1 ? PAL.voidBlack : PAL.charcoal;
    brush.set("micro_pen", col, 1.2);
    brush.spline([
      [ex - 52, ey - 10 + i, 0.6],
      [ex - 20, ey - 37 + i, 1.3],
      [ex + 16, ey - 35 + i, 1.2],
      [ex + 46, ey + 13 + i, 0.7]
    ], 0.6);
  }

  // Supraorbital eyelid crease just above upper lid
  for (let i = -2; i <= 2; i++) {
    brush.set("micro_pen", i === 0 ? PAL.voidBlack : PAL.charcoalMid, 0.9);
    brush.spline([
      [ex - 48, ey - 22 + i, 0.4],
      [ex - 16, ey - 46 + i, 1.1],
      [ex + 22, ey - 42 + i, 1.0],
      [ex + 46, ey - 2 + i, 0.4]
    ], 0.6);
  }

  // Lower eyelid wet margin (catching cold-grey and white wet glints)
  for (let i = -3; i <= 4; i++) {
    let col = i < 0 ? PAL.voidBlack : (i < 2 ? PAL.charcoalMid : PAL.greyDark);
    brush.set("micro_pen", col, 1.1);
    brush.spline([
      [ex - 50, ey - 8 + i, 0.6],
      [ex - 18, ey + 34 + i, 1.2],
      [ex + 18, ey + 35 + i, 1.2],
      [ex + 45, ey + 14 + i, 0.7]
    ], 0.6);
  }

  // Medial Canthus & Moist Caruncle (inner tear-duct corner at ex + 40, ey + 12)
  for (let r = 1; r <= 7; r += 1.0) {
    brush.set("micro_pen", r < 4 ? PAL.umberDark : PAL.voidBlack, 0.95);
    brush.circle(ex + 38, ey + 11, r, 0.25);
  }
  brush.set("micro_pen", PAL.white, 1.0);
  brush.arc(ex + 37, ey + 10, 3.2, 200, 340);

  // Glistening tear-film meniscus along the bottom rim of the cornea
  brush.set("micro_pen", PAL.greyIce, 1.05);
  brush.spline([
    [ex - 30, ey + 21, 0.3],
    [ex - 10, ey + 33, 1.2],
    [ex + 14, ey + 33, 1.2],
    [ex + 32, ey + 20, 0.3]
  ], 0.6);

  brush.set("micro_pen", PAL.white, 0.95);
  brush.spline([
    [ex - 16, ey + 31.5, 0.4],
    [ex,      ey + 34.2, 1.3],
    [ex + 16, ey + 32.0, 0.4]
  ], 0.6);

  // Fine upper eyelashes & wet periorbital guard hairs
  for (let i = 0; i < 28; i++) {
    let t = i / 27;
    let lx = lerp(ex - 44, ex + 26, t);
    let ly = lerp(ey - 14, ey - 28, sin(t * 180)) - 8;
    let ang = lerp(-155, -55, t) + random(-6, 6);
    let len = random(8, 17);
    brush.set("micro_pen", i % 5 === 0 ? PAL.greyCold : PAL.voidBlack, 0.85);
    brush.line(lx, ly, lx + cos(ang) * len, ly + sin(ang) * len);
  }
}

function renderCornealWindowReflection(ex, ey) {
  // Helper to warp normalized window coordinates (u, v in [0,1]) onto the convex corneal dome
  function windowToCornea(u, v) {
    let a = lerp(202, 266, u) - v * 8;
    let r = lerp(30.5, 9.5, v);
    return [ex + cos(a) * r, ey + sin(a) * r];
  }

  // Draw the 2x2 warped window panes with subtle sky-blue tint at top and pure white core
  const panes = [
    { u0: 0.00, u1: 0.44, v0: 0.00, v1: 0.44 }, // Top-left pane
    { u0: 0.56, u1: 1.00, v0: 0.00, v1: 0.44 }, // Top-right pane
    { u0: 0.00, u1: 0.44, v0: 0.56, v1: 1.00 }, // Bottom-left pane
    { u0: 0.56, u1: 1.00, v0: 0.56, v1: 1.00 }  // Bottom-right pane
  ];

  for (let p of panes) {
    let steps = 14;
    for (let s = 0; s <= steps; s++) {
      let v = lerp(p.v0, p.v1, s / steps);
      let pLeft = windowToCornea(p.u0, v);
      let pMid  = windowToCornea((p.u0 + p.u1) * 0.5, v);
      let pRight = windowToCornea(p.u1, v);

      // Top of top panes catches a hint of sky-blue & cold ice, bottom is blazing pure white
      let col = (v < 0.22 && s % 2 === 0) ? PAL.skyPale : (s % 3 === 0 ? PAL.greyIce : PAL.white);
      brush.set("micro_pen", col, 1.05);
      brush.spline([
        [pLeft[0], pLeft[1], 0.9],
        [pMid[0],  pMid[1],  1.2],
        [pRight[0], pRight[1], 0.9]
      ], 0.45);
    }
  }

  // Extra pinpoint brilliance on the inner corner of the bottom panes over the dark pupil
  let glint = windowToCornea(0.62, 0.82);
  brush.set("micro_pen", PAL.white, 1.3);
  brush.circle(glint[0], glint[1], 1.6, 0.1);
}

