    for (let d of w.drops) {
      let pt = evalBezier(w.p0, w.p1, w.p2, w.p3, d.t);
      let ptNext = evalBezier(w.p0, w.p1, w.p2, w.p3, min(1, d.t + 0.04));
      let tangAngle = atan2(ptNext[1] - pt[1], ptNext[0] - pt[0]);
      // Offset droplet slightly below the whisker shaft as gravity & centrifugal force pull on it
      let dropX = pt[0] + cos(tangAngle + 75) * (d.r * 0.42);
      let dropY = pt[1] + sin(tangAngle + 75) * (d.r * 0.42);
      drawHyperrealDroplet(dropX, dropY, d.r, tangAngle, d.sky || false);

      // Liquid meniscus collars wrapping the whisker at both ends of the bead
      let c1x = pt[0] - cos(tangAngle) * d.r * 0.85;
      let c1y = pt[1] - sin(tangAngle) * d.r * 0.85;
      let c2x = pt[0] + cos(tangAngle) * d.r * 0.85;
      let c2y = pt[1] + sin(tangAngle) * d.r * 0.85;
      brush.set("micro_pen", PAL.white, 0.9);
      brush.line(c1x, c1y, pt[0], pt[1]);
      brush.line(pt[0], pt[1], c2x, c2y);
    }
  }
}

function evalBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let b0 = u * u * u;
  let b1 = 3 * u * u * t;
  let b2 = 3 * u * t * t;
  let b3 = t * t * t;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1]
  ];
}

function drawHyperrealDroplet(x, y, r, angle, tintSkyBlue) {
  // 1. Cast shadow behind/below the droplet
  brush.noStroke();
  brush.wash(PAL.charcoalDeep, 210);
  brush.circle(x + 1.2, y + 1.8, r * 0.95, 0.12);

  // 2. Dark upper-left refractive body of the water sphere
  brush.wash(PAL.greyAbyss, 240);
  brush.circle(x, y, r, 0.08);
  brush.noWash();

  // 3. Internal refracted light crescent on the opposite (bottom-right) side
  let refractCol = tintSkyBlue ? PAL.skyBright : PAL.greyIce;
  let refractMid = tintSkyBlue ? PAL.skyVivid : PAL.greyCold;

  brush.set("micro_pen", refractMid, 0.95);
  brush.arc(x, y, r * 0.78, 15, 155);
  brush.arc(x, y, r * 0.62, 20, 145);

  brush.set("micro_pen", refractCol, 1.05);
  brush.arc(x, y, r * 0.70, 30, 135);

  // 4. Crisp dark outer meniscus rim
  brush.set("micro_pen", PAL.voidBlack, 0.85);
  brush.circle(x, y, r, 0.08);

  // 5. Razor-sharp primary window reflection highlight at upper-left of droplet
  let hx = x - r * 0.34;
  let hy = y - r * 0.34;
  brush.set("micro_pen", PAL.white, 1.35);
  brush.circle(hx, hy, max(0.9, r * 0.24), 0.05);
  brush.line(hx - r * 0.15, hy + r * 0.08, hx + r * 0.18, hy - r * 0.12);

  // Secondary micro-glint at bottom rim
  brush.set("micro_pen", PAL.white, 0.85);
  brush.arc(x, y, r * 0.82, 48, 95);
}

