function renderForegroundSpatter() {
  let cx = 600;
  let cy = 575;

  // A. Spattered dark accents across the sheet & water spray trajectories
  for (let i = 0; i < 420; i++) {
    let a = random(360);
    // Keep the immediate eye and nose core clean so hyperreal details remain pristine
    let minR = 135;
    let r = random(minR, 640);
    let x = cx + cos(a) * r + random(-20, 20);
    let y = cy + sin(a) * r + random(-20, 20);

    // Extra safety check around the focal eye (528, 496) and nose (638, 634)
    if (dist(x, y, 528, 496) < 72 || dist(x, y, 638, 634) < 88) continue;

    // Color selection: mostly dark charcoal & umber accents, cold grey, and sky-blue in upper-right
    let inSkyZone = (a > 290 && a < 360 && r > 200);
    let col;
    if (inSkyZone && random() < 0.48) {
      col = random([PAL.skyDeep, PAL.skyVivid, PAL.skyBright]);
    } else {
      let p = random();
      if (p < 0.52) col = random([PAL.voidBlack, PAL.charcoalDeep, PAL.charcoal]);
      else if (p < 0.78) col = random([PAL.greyDark, PAL.greyMid, PAL.greyCold]);
      else col = random([PAL.umberDark, PAL.umber, PAL.umberRich]);
    }

    let dropSize = random(1.0, 6.5) * map(r, 135, 640, 0.75, 1.35);

    if (random() < 0.38) {
      // High-speed stretched droplet streak along tangential shake vector
      let tang = a + 72 + random(-14, 14);
      let streakLen = dropSize * random(2.5, 6.5);
      brush.set("rotring", col, map(dropSize, 1, 8, 0.45, 1.35));
      brush.line(x, y, x + cos(tang) * streakLen, y + sin(tang) * streakLen);
    } else {
      // Spattered round/irregular droplet accent
      brush.set("charcoal", col, map(dropSize, 1, 8, 0.35, 1.1));
      brush.circle(x, y, dropSize, 0.45);
    }
  }

  // B. Fine spray mist clusters along the main swept arcs
  brush.set("spray", PAL.charcoal, 0.85);
  for (let k = 0; k < 18; k++) {
    let a = k * 20 + random(-8, 8);
    let r = random(240, 520);
    let x1 = cx + cos(a) * r;
    let y1 = cy + sin(a) * r;
    let x2 = cx + cos(a + 22) * (r + 55);
    let y2 = cy + sin(a + 22) * (r + 55);
    brush.line(x1, y1, x2, y2);
  }

  // C. Crisp mid-air refracting water drops flung just outside the sharp muzzle
  const midAirDrops = [
    { x: 405, y: 545, r: 6.2, sky: false },
    { x: 365, y: 588, r: 4.8, sky: false },
    { x: 432, y: 482, r: 5.0, sky: false },
    { x: 382, y: 665, r: 7.0, sky: false },
    { x: 465, y: 375, r: 5.4, sky: false },
    { x: 778, y: 508, r: 6.4, sky: true },
    { x: 825, y: 452, r: 7.2, sky: true },
    { x: 862, y: 392, r: 5.8, sky: true },
    { x: 812, y: 562, r: 5.2, sky: true },
    { x: 748, y: 722, r: 6.0, sky: false },
    { x: 588, y: 758, r: 5.5, sky: false }
  ];

  for (let md of midAirDrops) {
    drawHyperrealDroplet(md.x, md.y, md.r, 45, md.sky);
