function draw() {
  translate(-width / 2, -height / 2);

  // Base bone-vellum sheet ground
  background("#DFDBD2");

  const CX = 600;
  const CY = 600;
  const R_MEM = 486;      // Vibrating calfskin radius
  const R_HOOP_IN = 492;  // Inner rim bevel
  const R_HOOP_OUT = 554; // Outer wrapped skin collar

  // Raking light from upper-left (-165 deg), casting long shadows toward +15 deg
  const LIGHT_RAD = 15 * Math.PI / 180;
  const LX = Math.cos(LIGHT_RAD); //  0.9659
  const LY = Math.sin(LIGHT_RAD); //  0.2588
  const PX = -LY;                 // -0.2588
  const PY = LX;                  //  0.9659

  // Organic skin-tension warp function so Chladni figure feels alive on biological hide
  function warpCalfskin(r, theta) {
    let u = r / R_MEM;
    let nx = 10 + u * 2.4 * Math.cos(theta);
    let ny = 10 + u * 2.4 * Math.sin(theta);
    let dr = R_MEM * (
      0.008 * Math.cos(2 * theta - 0.45) * u +
      0.005 * Math.sin(4 * theta + 0.25) * u * u +
      0.011 * (noise(nx, ny) - 0.5) * Math.pow(u, 0.7)
    );
    let dth = 0.014 * Math.sin(3 * theta + 0.6) * u +
              0.019 * (noise(nx + 15, ny + 15) - 0.5) * Math.pow(u, 0.5);
    let nr = r + dr;
    let nth = theta + dth;
    return [CX + nr * Math.cos(nth), CY + nr * Math.sin(nth)];
  }

  // =========================================================================
  // 1. BUILD CHLADNI NODAL CURVES & 600x600 HEIGHT + RAKING SHADOW MAPS
  // =========================================================================
  const GSIZE = 600;
  const H = new Float32Array(GSIZE * GSIZE);
  const S = new Float32Array(GSIZE * GSIZE);
  const nodalCurves = [];

  function addNodalCurve(pts, baseWeight, baseWidth) {
    nodalCurves.push({ pts, baseWeight, baseWidth });
    for (let i = 0; i < pts.length; i++) {
      let [px, py] = pts[i];
      let gx = px * 0.5;
      let gy = py * 0.5;
      let t = i / Math.max(1, pts.length - 1);
      let nMod = 0.68 + 0.68 * noise(px * 0.018, py * 0.018) + 0.35 * noise(px * 0.06, py * 0.06);
      // Taper only if open curve
      let distEnds = Math.hypot(pts[0][0] - pts[pts.length - 1][0], pts[0][1] - pts[pts.length - 1][1]);
      let endTaper = distEnds > 8 ? Math.sin(t * Math.PI) * 0.45 + 0.55 : 1.0;

      let radG = (baseWidth * 0.5) * (0.78 + 0.44 * noise(px * 0.025 + 50, py * 0.025 + 50)) * endTaper;
      let amp = baseWeight * nMod * endTaper;

      let x0 = Math.max(1, Math.floor(gx - radG - 1));
      let x1 = Math.min(GSIZE - 2, Math.ceil(gx + radG + 1));
      let y0 = Math.max(1, Math.floor(gy - radG - 1));
      let y1 = Math.min(GSIZE - 2, Math.ceil(gy + radG + 1));

      for (let yy = y0; yy <= y1; yy++) {
        let dy = yy - gy;
        for (let xx = x0; xx <= x1; xx++) {
          let dx = xx - gx;
          let d = Math.hypot(dx, dy);
          if (d < radG) {
            let q = 1.0 - d / radG;
            // Granular crystal pile profile
            let grain = 0.72 + 0.55 * noise(xx * 0.45, yy * 0.45);
            let contrib = amp * Math.pow(q, 1.55) * grain;
            let idx = yy * GSIZE + xx;
            // Smooth max + additive junction buildup at intersections
            if (H[idx] > 0.05) {
              H[idx] = Math.max(H[idx], contrib) + Math.min(H[idx], contrib) * 0.42;
            } else {
              H[idx] = contrib;
            }
          }
        }
      }
    }
  }

  // --- A. Center Micro-Ring & First Nodal Ring ---
  {
    let pts0 = [];
    for (let i = 0; i <= 90; i++) {
      let th = (i / 90) * Math.PI * 2;
      let u = 0.027 + 0.003 * Math.cos(6 * th);
      pts0.push(warpCalfskin(u * R_MEM, th));
    }
    addNodalCurve(pts0, 0.85, 8.5);

    let pts1 = [];
    for (let i = 0; i <= 240; i++) {
      let th = (i / 240) * Math.PI * 2;
      let u = 0.104 - 0.010 * Math.cos(6 * th) + 0.004 * Math.cos(12 * th);
      pts1.push(warpCalfskin(u * R_MEM, th));
    }
    addNodalCurve(pts1, 1.15, 11.5);
  }

  // --- B. Inner 12-Petal Floral Rosette (6 Primary Petals + 6 Midribs + 6 Interstitial Petals) ---
  for (let k = 0; k < 6; k++) {
    let th0 = k * (Math.PI / 3);
    // Primary botanical/cymatic petal loop
    let petalPts = [];
    let steps = 160;
    for (let i = 0; i <= steps; i++) {
      let t = (i / steps) * Math.PI * 2;
      let u = 0.234 - 0.116 * Math.cos(t) + 0.012 * Math.cos(2 * t);
      let dth = Math.sin(t) * (0.158 + 0.042 * Math.pow(Math.sin(t * 0.5), 2)) * (1.0 - 0.16 * Math.cos(t));
      petalPts.push(warpCalfskin(u * R_MEM, th0 + dth));
    }
    addNodalCurve(petalPts, 1.12, 11.0);

    // Inner midrib spoke bisecting each primary petal
    let ribPts = [];
    for (let i = 0; i <= 50; i++) {
      let s = i / 50;
      let u = 0.135 + s * 0.185;
      let dth = 0.008 * Math.sin(s * Math.PI * 2) * (k % 2 === 0 ? 1 : -1);
      ribPts.push(warpCalfskin(u * R_MEM, th0 + dth));
    }
    addNodalCurve(ribPts, 0.72, 7.5);

    // Secondary slender interstitial petal
    let thSec = th0 + Math.PI / 6;
    let secPts = [];
    for (let i = 0; i <= 130; i++) {
      let t = (i / 130) * Math.PI * 2;
      let u = 0.246 - 0.095 * Math.cos(t);
      let dth = Math.sin(t) * 0.074 * (1.0 + 0.22 * Math.cos(t));
      secPts.push(warpCalfskin(u * R_MEM, thSec + dth));
    }
    addNodalCurve(secPts, 0.96, 9.5);
  }

  // --- C. Second Scalloped Nodal Ring ---
  {
    let pts2 = [];
    let steps = 420;
    for (let i = 0; i <= steps; i++) {
      let th = (i / steps) * Math.PI * 2;
      let u = 0.376 + 0.017 * Math.cos(6 * th) - 0.013 * Math.cos(12 * th);
      pts2.push(warpCalfskin(u * R_MEM, th));
    }
    addNodalCurve(pts2, 1.24, 12.8);
  }

  // --- D. 12 Primary Radiating Spokes (u = 0.376 to 0.955) ---
  for (let k = 0; k < 12; k++) {
    let th0 = k * (Math.PI / 6);
    let spokePts = [];
    let steps = 140;
    for (let i = 0; i <= steps; i++) {
      let s = i / steps;
      let u = 0.376 + s * (0.955 - 0.376);
      let wiggle = 0.007 * Math.sin((u - 0.376) * 15.0) * (k % 2 === 0 ? 1 : -1);
      spokePts.push(warpCalfskin(u * R_MEM, th0 + wiggle));
    }
    addNodalCurve(spokePts, 1.15, 11.2);
  }

  // --- E. 12 Outer Chalice Petals & Woven 3rd Ring (u = 0.40 to 0.73) ---
  for (let k = 0; k < 12; k++) {
    let th0 = (k + 0.5) * (Math.PI / 6);
    let chalicePts = [];
    let steps = 160;
    for (let i = 0; i <= steps; i++) {
      let t = (i / steps) * Math.PI * 2;
      let u = 0.566 - 0.158 * Math.cos(t) + 0.009 * Math.cos(3 * t);
      let dth = Math.sin(t) * 0.122 * (1.0 - 0.14 * Math.cos(2 * t));
      chalicePts.push(warpCalfskin(u * R_MEM, th0 + dth));
    }
    addNodalCurve(chalicePts, 1.04, 10.2);

    // Bridging nodal arcs at u ~ 0.566 creating the 3rd nodal ring weave across spokes
    let bridgePts = [];
    for (let i = 0; i <= 36; i++) {
      let s = (i / 36) - 0.5;
      let th = k * (Math.PI / 6) + s * 0.16;
      let u = 0.566 + 0.014 * Math.cos(s * Math.PI * 2);
      bridgePts.push(warpCalfskin(u * R_MEM, th));
    }
    addNodalCurve(bridgePts, 0.92, 9.5);
  }

  // --- F. 12 Secondary Radiating Spokes in Outer Zone (u = 0.728 to 0.955) ---
  for (let k = 0; k < 12; k++) {
    let th0 = (k + 0.5) * (Math.PI / 6);
    let secSpoke = [];
    for (let i = 0; i <= 65; i++) {
      let s = i / 65;
      let u = 0.728 + s * (0.955 - 0.728);
      let wiggle = 0.004 * Math.cos(s * Math.PI * 2);
      secSpoke.push(warpCalfskin(u * R_MEM, th0 + wiggle));
    }
    addNodalCurve(secSpoke, 0.95, 9.5);
  }

  // --- G. Fourth & Fifth Outer Nodal Rings ---
  {
    let pts4 = [];
    let steps4 = 520;
    for (let i = 0; i <= steps4; i++) {
      let th = (i / steps4) * Math.PI * 2;
      let u = 0.752 + 0.011 * Math.cos(12 * th) - 0.005 * Math.cos(24 * th);
      pts4.push(warpCalfskin(u * R_MEM, th));
    }
    addNodalCurve(pts4, 1.20, 12.0);

    let pts5 = [];
    let steps5 = 560;
    for (let i = 0; i <= steps5; i++) {
      let th = (i / steps5) * Math.PI * 2;
      let u = 0.892 - 0.007 * Math.cos(24 * th);
      pts5.push(warpCalfskin(u * R_MEM, th));
    }
    addNodalCurve(pts5, 1.06, 10.5);
  }

  // --- H. 48 Boundary Clamped-Edge Cymatic Whiskers (u = 0.892 to 0.975) ---
  for (let k = 0; k < 24; k++) {
    let thCenter = (k + 0.5) * (Math.PI / 12);
    for (let side of [-1, 1]) {
      let wPts = [];
      for (let i = 0; i <= 24; i++) {
        let s = i / 24;
        let u = 0.892 + s * 0.080;
        let th = thCenter + side * (0.022 + 0.028 * Math.pow(s, 1.4));
        wPts.push(warpCalfskin(u * R_MEM, th));
      }
      addNodalCurve(wPts, 0.68, 7.2);
    }
  }

  // --- Ray-March Raking Shadow Map S[gx, gy] across the 600x600 grid ---
  const MAX_SHADOW_STEPS = 24; // up to 48 canvas pixels of raking shade
  for (let gy = 1; gy < GSIZE - 1; gy++) {
    let py = gy * 2;
    for (let gx = 1; gx < GSIZE - 1; gx++) {
      let px = gx * 2;
      let r = Math.hypot(px - CX, py - CY);
      if (r > R_HOOP_IN + 4) continue;

      let h0 = H[gy * GSIZE + gx];
      let maxShade = 0;
      for (let step = 1; step <= MAX_SHADOW_STEPS; step++) {
        let sx = Math.round(gx - step * LX);
        let sy = Math.round(gy - step * LY);
        if (sx < 1 || sx >= GSIZE - 1 || sy < 1 || sy >= GSIZE - 1) break;
        let hs = H[sy * GSIZE + sx];
        // Low raking light elevation slope (~0.052 per grid step)
        let rayH = h0 + step * 0.052;
        if (hs > rayH) {
          let diff = (hs - rayH) * (1.0 - step / (MAX_SHADOW_STEPS + 2));
          if (diff > maxShade) maxShade = diff;
        }
      }
      S[gy * GSIZE + gx] = Math.min(1.0, maxShade * 1.45);
    }
  }

  function sampleH(px, py) {
    let gx = Math.max(1, Math.min(GSIZE - 2, Math.round(px * 0.5)));
    let gy = Math.max(1, Math.min(GSIZE - 2, Math.round(py * 0.5)));
    return H[gy * GSIZE + gx];
  }

  function sampleS(px, py) {
    let gx = Math.max(1, Math.min(GSIZE - 2, Math.round(px * 0.5)));
    let gy = Math.max(1, Math.min(GSIZE - 2, Math.round(py * 0.5)));
    return S[gy * GSIZE + gx];
  }

  function sampleGradDotL(px, py) {
    let gx = Math.max(2, Math.min(GSIZE - 3, Math.round(px * 0.5)));
    let gy = Math.max(2, Math.min(GSIZE - 3, Math.round(py * 0.5)));
    let dhdx = (H[gy * GSIZE + (gx + 1)] - H[gy * GSIZE + (gx - 1)]) * 0.5;
    let dhdy = (H[(gy + 1) * GSIZE + gx] - H[(gy - 1) * GSIZE + gx]) * 0.5;
    return dhdx * LX + dhdy * LY;
  }

  // Helper to draw a closed polygon with brush.beginShape
  function drawPolyShape(pts, curvature = 0.25) {
    if (pts.length < 3) return;
    brush.beginShape(curvature);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
  }

  // =========================================================================
  // 2. RECESSED CORNER VIGNETTES OUTSIDE THE DRUM RIM
  // =========================================================================
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.35);

  const cornerAngles = [45, 135, 225, 315];
  const cornerCoords = [
    [1200, 1200],
    [0, 1200],
    [0, 0],
    [1200, 0]
  ];

  // Dark cool charcoal-sepia washes in the 4 corners outside R_HOOP_OUT
  brush.fill("#23272D", 150);
  for (let c = 0; c < 4; c++) {
    let [cxCorner, cyCorner] = cornerCoords[c];
    let angCenter = cornerAngles[c] * Math.PI / 180;
    let poly = [[cxCorner, cyCorner]];
    for (let i = -8; i <= 8; i++) {
      let a = angCenter + (i / 8) * 0.52;
      poly.push([CX + (R_HOOP_OUT - 4) * Math.cos(a), CY + (R_HOOP_OUT - 4) * Math.sin(a)]);
    }
    drawPolyShape(poly, 0.1);
  }

  brush.fill("#16191D", 140);
  for (let c = 0; c < 4; c++) {
    let [cxCorner, cyCorner] = cornerCoords[c];
    let angCenter = cornerAngles[c] * Math.PI / 180;
    let poly = [[cxCorner, cyCorner]];
    for (let i = -6; i <= 6; i++) {
      let a = angCenter + (i / 6) * 0.42;
      poly.push([CX + (R_HOOP_OUT + 22) * Math.cos(a), CY + (R_HOOP_OUT + 22) * Math.sin(a)]);
    }
    drawPolyShape(poly, 0.1);
  }
  brush.noFill();

  // Dense archival cross-hatching in the outer corner shadows
  brush.set("2B", "#1A1D22", 0.55);
  for (let c = 0; c < 4; c++) {
    let angCenter = cornerAngles[c] * Math.PI / 180;
    for (let r = R_HOOP_OUT + 4; r < 840; r += 5.5) {
      let span = Math.acos(Math.min(0.99, 592 / r));
      if (span <= 0.02) continue;
      for (let pass = 0; pass < 2; pass++) {
        let a1 = angCenter - span * 0.95 + random(-0.02, 0.02);
        let a2 = angCenter + span * 0.95 + random(-0.02, 0.02);
        let steps = Math.max(4, Math.floor((a2 - a1) * r / 18));
        let pts = [];
        for (let s = 0; s <= steps; s++) {
          let a = a1 + (s / steps) * (a2 - a1);
          let rr = r + (pass === 0 ? 1 : -1) * (s % 2 === 0 ? 2.5 : -2.5);
          pts.push([CX + rr * Math.cos(a), CY + rr * Math.sin(a)]);
        }
        if (pts.length >= 3) brush.spline(pts, 0.3);
      }
    }
  }

  // =========================================================================
  // 3. CALFSKIN MOTTLED TRANSLUCENCY & RAKING LIGHT WASHES (BATCHED BY COLOR)
  // =========================================================================
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.65, 0.25);

  function makeOrganicBlob(cx, cy, rx, ry, rotRad, nPts = 14) {
    let pts = [];
    let c = Math.cos(rotRad), s = Math.sin(rotRad);
    for (let i = 0; i < nPts; i++) {
      let a = (i / nPts) * Math.PI * 2;
      let nv = 0.72 + 0.56 * noise(cx * 0.01 + Math.cos(a) * 1.3, cy * 0.01 + Math.sin(a) * 1.3);
      let lx = Math.cos(a) * rx * nv;
      let ly = Math.sin(a) * ry * nv;
      let px = cx + lx * c - ly * s;
      let py = cy + lx * s + ly * c;
      let d = Math.hypot(px - CX, py - CY);
      if (d > R_HOOP_IN - 6) {
        let ang = Math.atan2(py - CY, px - CX);
        px = CX + (R_HOOP_IN - 6) * Math.cos(ang);
        py = CY + (R_HOOP_IN - 6) * Math.sin(ang);
      }
      pts.push([px, py]);
    }
    return pts;
  }

  // Pass 3A: Warm bone illumination wash on the raking-lit right half of the skin
  brush.fill("#F4F0E6", 48);
  for (let i = 0; i < 10; i++) {
    let a = random(-75, 95) * Math.PI / 180;
    let r = random(80, 390);
    let bx = CX + r * Math.cos(a);
    let by = CY + r * Math.sin(a);
    drawPolyShape(makeOrganicBlob(bx, by, random(85, 165), random(65, 130), a), 0.4);
  }

  // Pass 3B: Cool translucent slate-grey mottling (thin calfskin showing dark acoustic cavity)
  brush.fill("#7C848D", 24);
  for (let i = 0; i < 22; i++) {
    let a = random(0, Math.PI * 2);
    let r = random(35, 445);
    let bx = CX + r * Math.cos(a);
    let by = CY + r * Math.sin(a);
    drawPolyShape(makeOrganicBlob(bx, by, random(48, 115), random(34, 85), a + 0.5), 0.45);
  }

  // Pass 3C: Deeper cool umber-slate subcutaneous mottling
  brush.fill("#5E656E", 20);
  for (let i = 0; i < 16; i++) {
    let a = random(0, Math.PI * 2);
    let r = random(60, 455);
    let bx = CX + r * Math.cos(a);
    let by = CY + r * Math.sin(a);
    drawPolyShape(makeOrganicBlob(bx, by, random(35, 82), random(25, 62), a + 1.1), 0.45);
  }

  // Pass 3D: Warm sepia & raw umber parchment mottling
  brush.fill("#A89682", 26);
  for (let i = 0; i < 20; i++) {
    let a = random(0, Math.PI * 2);
    let r = random(20, 450);
    let bx = CX + r * Math.cos(a);
    let by = CY + r * Math.sin(a);
    drawPolyShape(makeOrganicBlob(bx, by, random(45, 110), random(35, 80), a), 0.45);
  }

  // Pass 3E: Left-side crescent shadow cast by the raised calfskin hoop under low raking light
  brush.fill("#484E56", 38);
  {
    let crescent = [];
    for (let deg = 95; deg <= 295; deg += 5) {
      let rad = deg * Math.PI / 180;
      crescent.push([CX + (R_HOOP_IN - 2) * Math.cos(rad), CY + (R_HOOP_IN - 2) * Math.sin(rad)]);
    }
    for (let deg = 295; deg >= 95; deg -= 5) {
      let rad = deg * Math.PI / 180;
      let w = 44 * Math.pow(Math.max(0, -Math.cos(rad - LIGHT_RAD)), 1.3);
      let rIn = R_HOOP_IN - 6 - w - 8 * noise(deg * 0.08);
      crescent.push([CX + rIn * Math.cos(rad), CY + rIn * Math.sin(rad)]);
    }
    drawPolyShape(crescent, 0.25);
  }
  brush.noFill();

  // =========================================================================
  // 4. BARE CALFSKIN ANATOMY: FINE SUBCUTANEOUS VEINS, PORES & TENSION GRAIN
  // =========================================================================
  const veinSegmentsHalo = [];
  const veinSegmentsCore = [];
  const veinSegmentsCapillary = [];

  function growVeinTree(x, y, dir, len, depth) {
    if (depth > 4 || len < 10) return;
    let steps = Math.max(4, Math.floor(len / 8));
    let stepLen = len / steps;
    let pts = [[x, y]];
    let cx = x, cy = y, cdir = dir;

    for (let i = 0; i < steps; i++) {
      cdir += (noise(cx * 0.015, cy * 0.015, depth * 3) - 0.5) * 0.42;
      cx += Math.cos(cdir) * stepLen;
      cy += Math.sin(cdir) * stepLen;
      if (Math.hypot(cx - CX, cy - CY) > R_MEM - 8) break;
      pts.push([cx, cy]);
    }
    if (pts.length >= 3) {
      if (depth <= 1) veinSegmentsHalo.push(pts);
      if (depth <= 2) veinSegmentsCore.push(pts);
      else veinSegmentsCapillary.push(pts);

      // Fork branches at organic vascular angles
      let nBranches = depth === 0 ? 2 : (random() < 0.78 ? 2 : 1);
      for (let b = 0; b < nBranches; b++) {
        let side = b === 0 ? 1 : -1;
        let branchAng = cdir + side * random(0.28, 0.62);
        growVeinTree(cx, cy, branchAng, len * random(0.62, 0.78), depth + 1);
      }
      // Mid-segment collateral capillary twig
      if (pts.length > 5 && random() < 0.65) {
        let mid = pts[Math.floor(pts.length * 0.55)];
        growVeinTree(mid[0], mid[1], cdir + (random() < 0.5 ? 0.5 : -0.5), len * 0.48, depth + 2);
      }
    }
  }

  // Seed 18 subcutaneous vascular trees across the stretched calfskin
  for (let v = 0; v < 18; v++) {
    let ang = (v / 18) * Math.PI * 2 + random(-0.1, 0.1);
    let rStart = random(310, 470);
    let vx = CX + rStart * Math.cos(ang);
    let vy = CY + rStart * Math.sin(ang);
    let inwardDir = ang + Math.PI + random(-0.45, 0.45);
    growVeinTree(vx, vy, inwardDir, random(75, 130), 0);
  }

  // Render translucent subcutaneous vein halo
  brush.set("2H", "#8B7D76", 0.42);
  for (let pts of veinSegmentsHalo) brush.spline(pts, 0.45);

  // Render cool venous slate-sepia core
  brush.set("vein_quill", "#665A56", 0.85);
  for (let pts of veinSegmentsCore) brush.spline(pts, 0.45);

  // Render microscopic terminal capillaries
  brush.set("rotring", "#747980", 0.16);
  for (let pts of veinSegmentsCapillary) brush.spline(pts, 0.45);

  // Radial skin tension striations pulling taut toward the 8 perimeter lugs
  brush.set("2H", "#8A8279", 0.22);
  for (let i = 0; i < 320; i++) {
    let lugBias = Math.floor(random(8)) * (Math.PI / 4) + random(-0.28, 0.28);
    let r1 = random(390, 462);
    let r2 = r1 + random(16, 36);
    if (r2 > R_HOOP_IN - 2) r2 = R_HOOP_IN - 2;
    let x1 = CX + r1 * Math.cos(lugBias);
    let y1 = CY + r1 * Math.sin(lugBias);
    let x2 = CX + r2 * Math.cos(lugBias + random(-0.006, 0.006));
    let y2 = CY + r2 * Math.sin(lugBias + random(-0.006, 0.006));
    brush.line(x1, y1, x2, y2);
  }

  // Patient graphite stipple across the bare calfskin antinodes (dermal pores & vellum grain)
  brush.set("fine_stipple", "#6C6760", 0.85);
  for (let ring = 0; ring < 26; ring++) {
    let r = 24 + ring * 18;
    let segs = Math.max(8, Math.floor(r * 0.12));
    for (let s = 0; s < segs; s++) {
      let a1 = (s / segs) * Math.PI * 2 + random(-0.03, 0.03);
      let a2 = a1 + (0.65 / segs) * Math.PI * 2;
      let xm = CX + r * Math.cos((a1 + a2) * 0.5);
      let ym = CY + r * Math.sin((a1 + a2) * 0.5);
      // Only stipple bare skin or light shadow zones
      if (sampleH(xm, ym) < 0.25 && noise(xm * 0.012, ym * 0.012) > 0.36) {
        let p1 = [CX + r * Math.cos(a1), CY + r * Math.sin(a1)];
        let p2 = [xm + random(-3, 3), ym + random(-3, 3)];
        let p3 = [CX + r * Math.cos(a2), CY + r * Math.sin(a2)];
        brush.spline([p1, p2, p3], 0.35);
      }
    }
  }

  // =========================================================================
  // 5. LONG RAKING SHADOWS OF THE CHLADNI SALT RIDGES
  // =========================================================================
  // First: soft cool-slate & sepia shadow washes along the leeward side of every nodal curve
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.2);
  brush.fill("#3B4048", 34);

  for (let curve of nodalCurves) {
    let pts = curve.pts;
    let step = Math.max(3, Math.floor(pts.length / 28));
    for (let i = 0; i < pts.length - step; i += step) {
      let pA = pts[i];
      let pB = pts[Math.min(pts.length - 1, i + step)];
      let shLen = curve.baseWeight * 22 * (0.75 + 0.45 * noise(pA[0] * 0.03, pA[1] * 0.03));
      let poly = [
        [pA[0] + LX * 2, pA[1] + LY * 2],
        [pB[0] + LX * 2, pB[1] + LY * 2],
        [pB[0] + LX * shLen, pB[1] + LY * shLen],
        [pA[0] + LX * shLen, pA[1] + LY * shLen]
      ];
      drawPolyShape(poly, 0.15);
    }
  }
  brush.noFill();

  // Second: Raking grain-of-shade strokes & fine pen dotting guided by the ray-marched shadow map S
  const shadowGrainsDark = [];
  const shadowGrainsMid = [];
  const shadowDottingPaths = [];

  for (let gy = 6; gy < GSIZE - 6; gy += 2) {
    let py = gy * 2;
    for (let gx = 6; gx < GSIZE - 6; gx += 2) {
      let px = gx * 2;
      if (Math.hypot(px - CX, py - CY) > R_MEM + 4) continue;
      let sh = S[gy * GSIZE + gx];
      let h = H[gy * GSIZE + gx];
      if (sh > 0.12 && h < 0.42) {
        let jx = px + random(-1.8, 1.8);
        let jy = py + random(-1.8, 1.8);
        let grainLen = (4.5 + sh * 11.0) * random(0.7, 1.3);
        let ex = jx + LX * grainLen;
        let ey = jy + LY * grainLen;
        if (sh > 0.42) {
          shadowGrainsDark.push([jx, jy, ex, ey]);
        } else {
          shadowGrainsMid.push([jx, jy, ex, ey]);
        }
        if (random() < 0.28) {
          shadowDottingPaths.push([
            [jx, jy],
            [jx + LX * grainLen * 0.6 + PX * random(-1.2, 1.2), jy + LY * grainLen * 0.6 + PY * random(-1.2, 1.2)],
            [ex + LX * 3, ey + LY * 3]
          ]);
        }
      }
    }
  }

  // Render medium cool graphite raking shadow grains
  brush.set("2H", "#4A5058", 0.28);
  for (let l of shadowGrainsMid) brush.line(l[0], l[1], l[2], l[3]);

  // Render deep umbra raking shadow grains near ridge leeward bases
  brush.set("HB", "#282C32", 0.32);
  for (let l of shadowGrainsDark) brush.line(l[0], l[1], l[2], l[3]);

  // Render patient pen dotting along the raking shadow penumbra
  brush.set("pen_dotter", "#23262B", 0.55);
  for (let sp of shadowDottingPaths) brush.spline(sp, 0.2);

  // =========================================================================
  // 6. SCULPTED CHLADNI SALT RIDGE BODIES (OPAQUE BONE BASE, SHADED & LIT SLOPES)
  // =========================================================================
  // Opaque bone-white base along the nodal spines so salt covers the skin veins underneath
  brush.set("marker", "#EAE6DC", 1.35);
  for (let curve of nodalCurves) {
    let pts = curve.pts;
    if (pts.length >= 3) brush.spline(pts, 0.35);
  }

  // Leeward shaded slope of the salt ridges (cool mineral grey-sepia micro-crystals)
  brush.set("salt_micro", "#7B8188", 0.85);
  for (let curve of nodalCurves) {
    let pts = curve.pts;
    let off = curve.baseWidth * 0.22;
    let shifted = pts.map(p => [p[0] + LX * off, p[1] + LY * off]);
    if (shifted.length >= 3) brush.spline(shifted, 0.35);
  }

  // Deeper core shadow along the leeward base edge of each ridge
  brush.set("pen_dotter", "#353940", 0.72);
  for (let curve of nodalCurves) {
    let pts = curve.pts;
    let off = curve.baseWidth * 0.36;
    let shifted = pts.map(p => [p[0] + LX * off, p[1] + LY * off]);
    if (shifted.length >= 3) brush.spline(shifted, 0.35);
  }

  // Windward raking-lit slope of the salt ridges (warm bone & chalk highlights)
  brush.set("salt_micro", "#F2EFE7", 1.05);
  for (let curve of nodalCurves) {
    let pts = curve.pts;
    let off = -curve.baseWidth * 0.16;
    let shifted = pts.map(p => [p[0] + LX * off, p[1] + LY * off]);
    if (shifted.length >= 3) brush.spline(shifted, 0.35);
  }

  // Razor-bright crest of micro-crystals catching the raking beam
  brush.set("salt_micro", "#FAF8F3", 0.78);
  for (let curve of nodalCurves) {
    let pts = curve.pts;
    let off = -curve.baseWidth * 0.05;
    let shifted = pts.map(p => [p[0] + LX * off, p[1] + LY * off]);
    if (shifted.length >= 3) brush.spline(shifted, 0.35);
  }

  // =========================================================================
  // 7. THOUSANDS OF INDIVIDUAL 3D FACETED CUBIC SEA SALT CRYSTALS (BATCHED)
  // =========================================================================
  const crystals = [];

  function registerCrystal(x, y, sz, isStray = false) {
    if (Math.hypot(x - CX, y - CY) > R_MEM - 4) return;
    let rot = random(0, Math.PI * 0.5);
    let h = sampleH(x, y);
    let gradL = sampleGradDotL(x, y);
    // Determine if crystal sits on leeward shadow slope
    let inShade = gradL > 0.08 && h < 0.75;
    crystals.push({ x, y, sz, rot, h, inShade, isStray });
  }

  // A. Dense coarse crystals along all nodal curves & nodal intersections
  for (let curve of nodalCurves) {
    let pts = curve.pts;
    for (let i = 0; i < pts.length; i++) {
      let [px, py] = pts[i];
      let h = sampleH(px, py);
      // Higher crystal count & larger hopper cubes at nodal intersections (high h)
      let count = h > 1.15 ? 3 : (random() < 0.78 ? 2 : 1);
      for (let c = 0; c < count; c++) {
        let spread = curve.baseWidth * (h > 1.15 ? 0.58 : 0.42);
        let ang = random(0, Math.PI * 2);
        let dist = random(0, spread) * Math.pow(random(), 0.65);
        let cx = px + Math.cos(ang) * dist;
        let cy = py + Math.sin(ang) * dist;
        let sz = random(1.8, 3.8) * (h > 1.15 ? random(1.15, 1.75) : 1.0);
        if (random() < 0.09) sz *= random(1.4, 1.85); // Hero hopper crystal
        registerCrystal(cx, cy, sz, false);
      }
    }
  }

  // B. Acoustic Drift Filaments ("stilled mid-hum": chains of grains skittering into the nodes)
  const driftTickLines = [];
  for (let curve of nodalCurves) {
    let pts = curve.pts;
    for (let i = 3; i < pts.length - 3; i += 5) {
      if (random() < 0.42) {
        let [px, py] = pts[i];
        let tx = pts[i + 1][0] - pts[i - 1][0];
        let ty = pts[i + 1][1] - pts[i - 1][1];
        let tlen = Math.hypot(tx, ty) || 1;
        // Normal vector perpendicular to nodal ridge
        let side = random() < 0.5 ? 1 : -1;
        let nx = (-ty / tlen) * side;
        let ny = (tx / tlen) * side;

        let nGrains = Math.floor(random(3, 7));
        let startDist = curve.baseWidth * 0.48 + random(2, 6);
        for (let g = 0; g < nGrains; g++) {
          let d = startDist + g * random(4.2, 8.5);
          let gx = px + nx * d + random(-1.5, 1.5);
          let gy = py + ny * d + random(-1.5, 1.5);
          if (sampleH(gx, gy) < 0.35) {
            let sz = map(g, 0, nGrains, 3.2, 1.5) * random(0.8, 1.25);
            registerCrystal(gx, gy, sz, true);
            // Tiny graphite vibration wake behind bouncing grain
            driftTickLines.push([gx + nx * (sz + 1.2), gy + ny * (sz + 1.2), gx + nx * (sz + 4.5), gy + ny * (sz + 4.5)]);
          }
        }
      }
    }
  }

  // C. Solitary stray sea-salt cubes vibrating in the bare calfskin antinodes
  for (let i = 0; i < 340; i++) {
    let a = random(0, Math.PI * 2);
    let r = Math.sqrt(random()) * (R_MEM - 16);
    let sx = CX + r * Math.cos(a);
    let sy = CY + r * Math.sin(a);
    if (sampleH(sx, sy) < 0.18) {
      let sz = random() < 0.22 ? random(3.8, 6.4) : random(1.8, 3.6);
      registerCrystal(sx, sy, sz, true);
    }
  }

  // Sort crystals along the light direction (back-to-front relative to raking beam)
  crystals.sort((a, b) => (a.x * LX + a.y * LY) - (b.x * LX + b.y * LY));

  // Precompute batched geometry for all 3D faceted cubic crystals
  const batchCastShadows = [];
  const batchCastShadowsCore = [];
  const batchLitFaces = [];
  const batchTopFaces = [];
  const batchShadedFaces = [];
  const batchCubeEdges = [];
  const batchHopperSteps = [];
  const batchHairlineShadows = [];
  const batchPinpointGlints = [];

  for (let c of crystals) {
    let { x, y, sz, rot, inShade, isStray } = c;
    // Construct isometric/tilted 3D cube vertices oriented relative to light (LX, LY)
    let cRot = Math.cos(rot), sRot = Math.sin(rot);
    // Local axes in screen space aligned with light (LX, LY) and perpendicular (PX, PY)
    let u1x = (LX * cRot - PX * sRot) * sz * 0.58;
    let u1y = (LY * cRot - PY * sRot) * sz * 0.58;
    let u2x = (LX * sRot + PX * cRot) * sz * 0.58;
    let u2y = (LY * sRot + PY * cRot) * sz * 0.58;

    // Slight vertical/raking foreshortening offset for cube height
    let hOffX = -LX * sz * 0.42;
    let hOffY = -LY * sz * 0.42 - sz * 0.22;

    // Top square face corners: T0 (windward/left), T1 (top), T2 (leeward/right), T3 (bottom)
    let T0 = [x - u1x - u2x + hOffX, y - u1y - u2y + hOffY];
    let T1 = [x + u1x - u2x + hOffX, y + u1y - u2y + hOffY];
    let T2 = [x + u1x + u2x + hOffX, y + u1y + u2y + hOffY];
    let T3 = [x - u1x + u2x + hOffX, y - u1y + u2y + hOffY];

    // Base square corners on the drumhead surface
    let B0 = [x - u1x - u2x, y - u1y - u2y];
    let B1 = [x + u1x - u2x, y + u1y - u2y];
    let B2 = [x + u1x + u2x, y + u1y + u2y];
    let B3 = [x - u1x + u2x, y - u1y + u2y];

    // 1. Long raking cast shadow thrown by the cube along (LX, LY)
    let shMult = isStray ? random(3.6, 5.2) : random(2.4, 3.8);
    let shLen = sz * shMult;
    batchCastShadows.push([B1[0], B1[1], B1[0] + LX * shLen, B1[1] + LY * shLen]);
    batchCastShadows.push([B2[0], B2[1], B2[0] + LX * shLen * 1.1, B2[1] + LY * shLen * 1.1]);
    batchCastShadows.push([B3[0], B3[1], B3[0] + LX * shLen * 0.95, B3[1] + LY * shLen * 0.95]);
    if (sz > 2.4) {
      batchCastShadowsCore.push([B2[0], B2[1], B2[0] + LX * shLen * 0.55, B2[1] + LY * shLen * 0.55]);
      batchCastShadowsCore.push([
        (B1[0] + B2[0]) * 0.5, (B1[1] + B2[1]) * 0.5,
        (B1[0] + B2[0]) * 0.5 + LX * shLen * 0.65, (B1[1] + B2[1]) * 0.5 + LY * shLen * 0.65
      ]);
    }

    // 2. Shaded leeward side faces (T1-T2-B2-B1 and T2-T3-B3-B2)
    batchShadedFaces.push([
      (T1[0] + B1[0]) * 0.5, (T1[1] + B1[1]) * 0.5,
      (T2[0] + B2[0]) * 0.5, (T2[1] + B2[1]) * 0.5
    ]);
    batchShadedFaces.push([
      (T2[0] + B2[0]) * 0.5, (T2[1] + B2[1]) * 0.5,
      (T3[0] + B3[0]) * 0.5, (T3[1] + B3[1]) * 0.5
    ]);

    // 3. Top crystal face fill strokes (T0-T1-T2-T3)
    batchTopFaces.push([
      (T0[0] + T3[0]) * 0.5, (T0[1] + T3[1]) * 0.5,
      (T1[0] + T2[0]) * 0.5, (T1[1] + T2[1]) * 0.5
    ]);
    if (sz > 3.0) {
      batchTopFaces.push([T0[0], T0[1], T2[0], T2[1]]);
    }

    // 4. Raking-lit windward bevel/edge (T0-T1 and T0-T3 and B0-T0)
    if (!inShade) {
      batchLitFaces.push([T0[0], T0[1], T1[0], T1[1]]);
      batchLitFaces.push([T0[0], T0[1], T3[0], T3[1]]);
      batchLitFaces.push([B0[0], B0[1], T0[0], T0[1]]);
    }

    // 5. Crisp geometric facet edges of the cube (for medium & coarse crystals)
    if (sz > 2.2) {
      batchCubeEdges.push([T0[0], T0[1], T1[0], T1[1]]);
      batchCubeEdges.push([T1[0], T1[1], T2[0], T2[1]]);
      batchCubeEdges.push([T2[0], T2[1], T3[0], T3[1]]);
      batchCubeEdges.push([T3[0], T3[1], T0[0], T0[1]]);
      batchCubeEdges.push([T2[0], T2[1], B2[0], B2[1]]);
      batchCubeEdges.push([T1[0], T1[1], B1[0], B1[1]]);
      batchCubeEdges.push([T3[0], T3[1], B3[0], B3[1]]);
    }

    // Concentric hopper crystal steps on hero sea-salt cubes
    if (sz > 3.9) {
      let cxTop = (T0[0] + T2[0]) * 0.5;
      let cyTop = (T0[1] + T2[1]) * 0.5;
      let s1 = 0.52;
      let H0 = [cxTop + (T0[0] - cxTop) * s1, cyTop + (T0[1] - cyTop) * s1];
      let H1 = [cxTop + (T1[0] - cxTop) * s1, cyTop + (T1[1] - cyTop) * s1];
      let H2 = [cxTop + (T2[0] - cxTop) * s1, cyTop + (T2[1] - cyTop) * s1];
      let H3 = [cxTop + (T3[0] - cxTop) * s1, cyTop + (T3[1] - cyTop) * s1];
      batchHopperSteps.push([H0[0], H0[1], H1[0], H1[1]]);
      batchHopperSteps.push([H1[0], H1[1], H2[0], H2[1]]);
      batchHopperSteps.push([H2[0], H2[1], H3[0], H3[1]]);
      batchHopperSteps.push([H3[0], H3[1], H0[0], H0[1]]);
    }

    // 6. Hairline base contact shadow on the leeward base edges (B1-B2 and B2-B3)
    batchHairlineShadows.push([B1[0], B1[1], B2[0], B2[1]]);
    batchHairlineShadows.push([B2[0], B2[1], B3[0], B3[1]]);

    // 7. Pinpoint specular highlight on the windward corner T0
    if (!inShade || random() < 0.35) {
      batchPinpointGlints.push([T0[0], T0[1], T0[0] + (T1[0] - T0[0]) * 0.32, T0[1] + (T1[1] - T0[1]) * 0.32]);
      if (sz > 3.2) {
        batchPinpointGlints.push([T0[0], T0[1], T0[0] + (T3[0] - T0[0]) * 0.32, T0[1] + (T3[1] - T0[1]) * 0.32]);
      }
    }
  }

  // Execute Batched Crystal Passes
  // Drift wake vibration ticks on bare skin
  brush.set("2H", "#7A756D", 0.22);
  for (let l of driftTickLines) brush.line(l[0], l[1], l[2], l[3]);

  // Pass 7A: Long raking crystal shadows
  brush.set("HB", "#393E45", 0.30);
  for (let l of batchCastShadows) brush.line(l[0], l[1], l[2], l[3]);

  brush.set("2B", "#22262B", 0.34);
  for (let l of batchCastShadowsCore) brush.line(l[0], l[1], l[2], l[3]);

  // Pass 7B: Shaded leeward cube faces (cool translucent mineral slate)
  brush.set("marker", "#848A92", 0.45);
  for (let l of batchShadedFaces) brush.line(l[0], l[1], l[2], l[3]);

  // Pass 7C: Top cube faces (warm-cool bone)
  brush.set("marker", "#DFDBD1", 0.52);
  for (let l of batchTopFaces) brush.line(l[0], l[1], l[2], l[3]);

  // Pass 7D: Raking-lit windward cube faces (luminous chalk-bone)
  brush.set("marker", "#F6F4EC", 0.48);
  for (let l of batchLitFaces) brush.line(l[0], l[1], l[2], l[3]);

  // Pass 7E: Crisp cubic facet edges & hopper steps
  brush.set("rotring", "#5A6068", 0.18);
  for (let l of batchCubeEdges) brush.line(l[0], l[1], l[2], l[3]);

  brush.set("rotring", "#484D54", 0.20);
  for (let l of batchHopperSteps) brush.line(l[0], l[1], l[2], l[3]);

  // Pass 7F: Razor-sharp hairline base contact shadows
  brush.set("rotring", "#14161A", 0.25);
  for (let l of batchHairlineShadows) brush.line(l[0], l[1], l[2], l[3]);

  // Pass 7G: Pinpoint crystal highlights
  brush.set("rotring", "#FFFFFF", 0.48);
  for (let l of batchPinpointGlints) brush.line(l[0], l[1], l[2], l[3]);

  // =========================================================================
  // 8. TACKED CALFSKIN RIM & TARNISHED BRASS LUGS CROPPED AT THE CORNERS
  // =========================================================================
  // --- A. Wrapped Calfskin Collar & Flesh Hoop (r = 492 to 554) ---
  brush.noStroke();
  brush.fillBleed(0.15, "out");
  brush.fillTexture(0.55, 0.35);

  // Shaded hoop sectors vs raking-lit hoop sectors
  const hoopSectors = 36;
  for (let pass = 0; pass < 2; pass++) {
    // pass 0: warm parchment-bone rim base; pass 1: cool slate shadow on outer-right & inner-left
    brush.fill(pass === 0 ? "#C4B7A4" : "#4B5058", pass === 0 ? 75 : 58);
    for (let s = 0; s < hoopSectors; s++) {
      let a1 = (s / hoopSectors) * Math.PI * 2;
      let a2 = ((s + 1.02) / hoopSectors) * Math.PI * 2;
      let am = (a1 + a2) * 0.5;
      let dotL = Math.cos(am) * LX + Math.sin(am) * LY;

      if (pass === 0 || (pass === 1 && Math.abs(dotL) > 0.15)) {
        let rIn = pass === 0 ? R_HOOP_IN : (dotL > 0 ? R_HOOP_IN + 26 : R_HOOP_IN);
        let rOut = pass === 0 ? R_HOOP_OUT : (dotL > 0 ? R_HOOP_OUT : R_HOOP_IN + 28);
        let poly = [
          [CX + rIn * Math.cos(a1), CY + rIn * Math.sin(a1)],
          [CX + rIn * Math.cos(a2), CY + rIn * Math.sin(a2)],
          [CX + rOut * Math.cos(a2), CY + rOut * Math.sin(a2)],
          [CX + rOut * Math.cos(a1), CY + rOut * Math.sin(a1)]
        ];
        drawPolyShape(poly, 0.08);
      }
    }
  }
  brush.noFill();

  // Bright raking highlight arc along the right inner wall of the rim (facing incoming light)
  brush.set("cpencil", "#FAF7EE", 0.95);
  brush.arc(CX, CY, R_HOOP_IN + 3, -62, 92);
  brush.set("rotring", "#FFFFFF", 0.45);
  brush.arc(CX, CY, R_HOOP_IN + 1.5, -48, 78);

  // Concentric rim crease lines & lapped hide seam
  brush.set("rotring", "#2A2825", 0.36);
  brush.arc(CX, CY, R_HOOP_IN, 0, 360);
  brush.arc(CX, CY, R_HOOP_OUT, 0, 360);
  brush.set("HB", "#4A443D", 0.30);
  brush.arc(CX, CY, R_HOOP_IN + 22, 0, 360);
  brush.arc(CX, CY, R_HOOP_OUT - 10, 0, 360);

  // Radial pleated skin folds wrapped over the wooden hoop
  const foldDark = [];
  const foldLight = [];
  for (let i = 0; i < 220; i++) {
    let a = (i / 220) * Math.PI * 2 + random(-0.008, 0.008);
    let r1 = R_HOOP_IN + random(1, 10);
    let r2 = R_HOOP_OUT - random(2, 12);
    let aOff = random(-0.012, 0.012);
    let p1 = [CX + r1 * Math.cos(a), CY + r1 * Math.sin(a)];
    let p2 = [CX + r2 * Math.cos(a + aOff), CY + r2 * Math.sin(a + aOff)];
    foldDark.push([p1[0], p1[1], p2[0], p2[1]]);
    let p1L = [CX + r1 * Math.cos(a - 0.004), CY + r1 * Math.sin(a - 0.004)];
    let p2L = [CX + r2 * Math.cos(a + aOff - 0.004), CY + r2 * Math.sin(a + aOff - 0.004)];
    foldLight.push([p1L[0], p1L[1], p2L[0], p2L[1]]);
  }
  brush.set("2H", "#45403A", 0.28);
  for (let l of foldDark) brush.line(l[0], l[1], l[2], l[3]);
  brush.set("2H", "#EBE6DC", 0.24);
  for (let l of foldLight) brush.line(l[0], l[1], l[2], l[3]);

  // --- B. Ring of 40 Tarnished Brass Tacks & Verdigris Halos around the Rim ---
  const tackPositions = [];
  for (let k = 0; k < 40; k++) {
    let deg = k * 9;
    // Skip angles directly under the 8 tension lug claws (multiples of 45 deg)
    let distToLug = Math.min(deg % 45, 45 - (deg % 45));
    if (distToLug < 5) continue;
    let rad = deg * Math.PI / 180;
    let rTack = R_HOOP_IN + 34 + random(-1.5, 1.5);
    tackPositions.push([CX + rTack * Math.cos(rad), CY + rTack * Math.sin(rad)]);
  }

  // Verdigris copper-patina stain halos around each brass tack
  brush.noStroke();
  brush.fill("#5B7069", 55);
  for (let [tx, ty] of tackPositions) {
    brush.circle(tx, ty, 7.2, 0.25);
  }
  // Raking cast shadow of each domed tack
  brush.fill("#1E2024", 130);
  for (let [tx, ty] of tackPositions) {
    let shPoly = [
      [tx + PX * 4.2, ty + PY * 4.2],
      [tx - PX * 4.2, ty - PY * 4.2],
      [tx + LX * 15 - PX * 2.2, ty + LY * 15 - PY * 2.2],
      [tx + LX * 15 + PX * 2.2, ty + LY * 15 + PY * 2.2]
    ];
    drawPolyShape(shPoly, 0.2);
  }
  // Tarnished brass tack dome body
  brush.wash("#6E6345", 210);
  for (let [tx, ty] of tackPositions) {
    brush.circle(tx, ty, 4.6, 0.12);
  }
  brush.noWash();
  brush.noFill();

  // Tack outlines, antique brass bevels, and pinpoint highlights
  brush.set("rotring", "#1B1915", 0.32);
  for (let [tx, ty] of tackPositions) {
    brush.circle(tx, ty, 4.6, 0.1);
  }
  brush.set("cpencil", "#C4B586", 0.55);
  for (let [tx, ty] of tackPositions) {
    brush.line(tx - LX * 2.4, ty - LY * 2.4, tx - LX * 1.2 + PX * 1.8, ty - LY * 1.2 + PY * 1.8);
  }
  brush.set("rotring", "#FFFDF5", 0.55);
  for (let [tx, ty] of tackPositions) {
    brush.line(tx - LX * 2.2, ty - LY * 2.2, tx - LX * 1.5 - PX * 0.8, ty - LY * 1.5 - PY * 0.8);
  }

  // --- C. 8 Tarnished Brass Tension Lugs (4 Major Corner Lugs + 4 Edge Brackets) ---
  function drawBrassLug(degAngle, isCorner) {
    let rad = degAngle * Math.PI / 180;
    let ux = Math.cos(rad), uy = Math.sin(rad); // Radial outward unit vector
    let vx = -uy, vy = ux;                      // Tangential unit vector

    let rClawTip = R_HOOP_IN - 7;
    let rCollar = R_HOOP_OUT - 4;
    let rOuter = isCorner ? 720 : 615;
    let halfW = isCorner ? 24 : 18;

    function toWorld(r, t) {
      return [CX + ux * r + vx * t, CY + uy * r + vy * t];
    }

    // 1. Long raking shadow cast by the raised brass claw & lug onto the skin and rim
    brush.noStroke();
    brush.fill("#181B20", 145);
    let shLen = isCorner ? 34 : 24;
    let clawShadow = [
      toWorld(rClawTip, -halfW * 0.88),
      toWorld(rClawTip, halfW * 0.88),
      [toWorld(rOuter, halfW * 1.15)[0] + LX * shLen, toWorld(rOuter, halfW * 1.15)[1] + LY * shLen],
      [toWorld(rCollar, halfW * 1.1)[0] + LX * shLen, toWorld(rCollar, halfW * 1.1)[1] + LY * shLen],
      [toWorld(rClawTip, -halfW * 0.88)[0] + LX * shLen * 0.85, toWorld(rClawTip, -halfW * 0.88)[1] + LY * shLen * 0.85]
    ];
    drawPolyShape(clawShadow, 0.15);

    // 2. Dark leather pad underneath the brass claw hook
    brush.wash("#2A231E", 220);
    drawPolyShape([
      toWorld(rClawTip - 3, -halfW * 0.92),
      toWorld(rClawTip - 3, halfW * 0.92),
      toWorld(rCollar + 4, halfW * 1.04),
      toWorld(rCollar + 4, -halfW * 1.04)
    ], 0.1);

    // 3. Base oxidized bronze-brass body of claw hook & tension rod casing
    brush.wash("#4F4733", 235);
    drawPolyShape([
      toWorld(rClawTip, -halfW * 0.78),
      toWorld(rClawTip, halfW * 0.78),
      toWorld(rCollar, halfW * 0.98),
      toWorld(rOuter, halfW * 0.85),
      toWorld(rOuter, -halfW * 0.85),
      toWorld(rCollar, -halfW * 0.98)
    ], 0.12);

    // 4. Hexagonal collar flange at rCollar
    brush.wash("#6E6346", 230);
    drawPolyShape([
      toWorld(rCollar - 8, -halfW * 1.22),
      toWorld(rCollar - 8, halfW * 1.22),
      toWorld(rCollar + 18, halfW * 1.22),
      toWorld(rCollar + 18, -halfW * 1.22)
    ], 0.08);
    brush.noWash();

    // 5. Cool verdigris patina in the recessed crevices of the brass lug
    brush.fill("#587069", 95);
    drawPolyShape([
      toWorld(rCollar - 6, -halfW * 0.95),
      toWorld(rCollar - 6, -halfW * 0.35),
      toWorld(rOuter, -halfW * 0.35),
      toWorld(rOuter, -halfW * 0.82)
    ], 0.1);
    drawPolyShape([
      toWorld(rClawTip + 6, halfW * 0.3),
      toWorld(rClawTip + 6, halfW * 0.75),
      toWorld(rCollar - 8, halfW * 0.85),
      toWorld(rCollar - 8, halfW * 0.3)
    ], 0.1);
    brush.noFill();

    // 6. Lit antique brass plane on the windward side of the lug & central rib
    let tangentDotL = vx * LX + vy * LY;
    let litSide = tangentDotL < 0 ? 1 : -1;

    brush.set("marker", "#9E916B", 0.95);
    for (let s = 0.1; s <= 0.75; s += 0.16) {
      let p1 = toWorld(rClawTip + 3, litSide * halfW * s);
      let p2 = toWorld(rOuter, litSide * halfW * s * 0.9);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Raised central reinforcement spine of the claw hook
    brush.set("marker", "#B8AA82", 0.85);
    let c1 = toWorld(rClawTip + 2, 0);
    let c2 = toWorld(rOuter, 0);
    brush.line(c1[0], c1[1], c2[0], c2[1]);

    // 7. Machined threads, knurling & metallic cross-hatching on the tension rod and collar
    brush.set("rotring", "#1E1C17", 0.34);
    // Outer contour lines
    let pTL = toWorld(rClawTip, -halfW * 0.78);
    let pTR = toWorld(rClawTip, halfW * 0.78);
    let pCL = toWorld(rCollar, -halfW * 0.98);
    let pCR = toWorld(rCollar, halfW * 0.98);
    let pOL = toWorld(rOuter, -halfW * 0.85);
    let pOR = toWorld(rOuter, halfW * 0.85);
    brush.line(pTL[0], pTL[1], pTR[0], pTR[1]);
    brush.line(pTL[0], pTL[1], pCL[0], pCL[1]);
    brush.line(pTR[0], pTR[1], pCR[0], pCR[1]);
    brush.line(pCL[0], pCL[1], pOL[0], pOL[1]);
    brush.line(pCR[0], pCR[1], pOR[0], pOR[1]);

    // Transverse machined thread & bevel rings along the tension rod
    for (let r = rClawTip + 6; r < rOuter; r += 5.5) {
      let wFactor = (r >= rCollar - 8 && r <= rCollar + 18) ? 1.22 : (r > rCollar + 18 ? 0.62 : 0.86);
      let q1 = toWorld(r, -halfW * wFactor);
      let q2 = toWorld(r, halfW * wFactor);
      brush.line(q1[0], q1[1], q2[0], q2[1]);
    }

    // 8. Sharp raking specular glints on the tarnished brass bevels
    brush.set("cpencil", "#EAE1C5", 0.65);
    let g1 = toWorld(rClawTip + 2, litSide * halfW * 0.18);
    let g2 = toWorld(rOuter, litSide * halfW * 0.18);
    brush.line(g1[0], g1[1], g2[0], g2[1]);

    brush.set("rotring", "#FFFDF6", 0.50);
    let b1 = toWorld(rClawTip + 1, -halfW * 0.55);
    let b2 = toWorld(rClawTip + 1, halfW * 0.55);
    brush.line(b1[0], b1[1], b2[0], b2[1]);
    let f1 = toWorld(rCollar - 8, -halfW * 1.15);
    let f2 = toWorld(rCollar - 8, halfW * 1.15);
    brush.line(f1[0], f1[1], f2[0], f2[1]);
  }

  // Render the 4 cropped corner lugs and 4 cardinal edge brackets
  for (let deg of [45, 135, 225, 315]) {
    drawBrassLug(deg, true);
  }
  for (let deg of [0, 90, 180, 270]) {
    drawBrassLug(deg, false);
  }

  noLoop();
}

// =============================================================================
// HYPERREAL SPRITE SHEET: SCUFFED CANVAS SNEAKER TOE & 9-FRAME BOW SEQUENCE
// Medium: Layered Alcohol Marker, Colored Pencil Grain & Rotring Fine-Liner
// Ground: Flat Chroma-Magenta (#D1086A) with Cyan Registration Ticks (#00F0FF)
// =============================================================================

const PAL = {
  chromaBg: "#D1086A",
  chromaDark: "#9E044E",
  chromaShadow: "#3B031F",
  cyan: "#00F0FF",
  cyanDim: "#00A8B8",
  techWhite: "#FFF5FA",
  techInk: "#1E0D16",

  // Muted Earth Tones (Sneaker Canvas, Rubber, Eyelets, Grime)
  canvasBase: "#786D54",
  canvasLight: "#968A70",
  canvasBleach: "#B2A68C",
  canvasMid: "#635943",
  canvasDark: "#483F2D",
  canvasDeep: "#2B2419",
  tongueBase: "#887C62",
