async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  randomSeed(73109);
  noiseSeed(73109);

  // Register custom alcohol markers and technical fine-liners
  brush.add("alc_chisel", {
    type: "marker",
    weight: 3.4,
    scatter: 0.04,
    opacity: 44,
    spacing: 0.22,
    pressure: [0.92, 1.0, 0.92],
    rotate: "natural",
    markerTip: true,
    noise: 0.2
  });

  brush.add("alc_soft", {
    type: "default",
    weight: 2.6,
    scatter: 0.18,
    sharpness: 0.32,
    grain: 7,
    opacity: 38,
    spacing: 0.18,
    pressure: [0.65, 1.15, 0.65],
    rotate: "natural",
