  background(PAL.chromaBg);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Flat Chroma-Magenta Ground Wash
  brush.noStroke();
  brush.noFill();
  let bgPoly = new brush.Polygon([[0, 0], [1200, 0], [1200, 1200], [0, 1200]]);
  bgPoly.wash(PAL.chromaBg, 255);
  brush.noWash();

  // Grid Layout Parameters (3x3 Equal Cells of 316x316 with 42px Gutters)
  const cellSize = 316;
  const gutter = 42;
  const startX = 84;
  const startY = 92;

  // 2. Render Top Header, Marker Swatch Calibration Strip & Bottom Footer
  drawSheetChrome(startX, startY, cellSize, gutter);

  // 3. Render Each of the 9 Sprite Cells
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) {
      let idx = row * 3 + col;
      let x0 = startX + col * (cellSize + gutter);
      let y0 = startY + row * (cellSize + gutter);
      let cx = x0 + cellSize * 0.5;
      let cy = y0 + cellSize * 0.5;

      // Seed per-cell micro-variation
      randomSeed(41000 + idx * 917);
      noiseSeed(41000 + idx * 917);

      // Clip interior of cell so sprite marks stay strictly inside the cell boundary
      brush.clip([x0 + 1, y0 + 1, x0 + cellSize - 1, y0 + cellSize - 1]);
      drawSneakerCell(cx, cy, idx, FRAME_META[idx]);
      brush.noClip();

      // Gutter Registration Ticks & Frame Metadata
      drawCellRegistration(x0, y0, cellSize, gutter, row, col, idx, FRAME_META[idx]);
    }
  }

  noLoop();
}

// =============================================================================
// TECHNICAL SPRITE SHEET CHROME, GUTTER REGISTRATION & VECTOR TYPOGRAPHY
// =============================================================================

function drawTechText(str, x, y, h, col, weight = 0.72, tracking = 0.36) {
  let w = h * 0.62;
  let step = w + h * tracking;
  brush.set("fineliner", col, weight);
  let up = String(str).toUpperCase();
  for (let i = 0; i < up.length; i++) {
    let ch = up[i];
    if (ch === " ") continue;
    let paths = GLYPHS[ch];
    if (!paths) continue;
    let gx = x + i * step;
    for (let p = 0; p < paths.length; p++) {
      let strokePts = paths[p];
      for (let k = 0; k < strokePts.length - 1; k++) {
        let x1 = gx + strokePts[k][0] * w;
        let y1 = y + strokePts[k][1] * h;
        let x2 = gx + strokePts[k + 1][0] * w;
        let y2 = y + strokePts[k + 1][1] * h;
        brush.line(x1, y1, x2, y2);
      }
    }
  }
}

function drawCrosshair(x, y, r, col, weight = 0.75, circleR = 0) {
  brush.set("fineliner", col, weight);
  brush.line(x - r, y, x - 2, y);
  brush.line(x + 2, y, x + r, y);
  brush.line(x, y - r, x, y - 2);
  brush.line(x, y + 2, x, y + r);
  if (circleR > 0) {
    brush.arc(x, y, circleR, 0, 360);
  }
}

function drawSheetChrome(startX, startY, cellSize, gutter) {
  const totalW = 3 * cellSize + 2 * gutter; // 1032
  const rightEdge = startX + totalW;        // 1116
  const bottomEdge = startY + totalW;       // 1124

  // Outer technical sheet trim lines & corner targets
  drawCrosshair(42, 42, 14, PAL.cyan, 0.85, 7);
  drawCrosshair(1158, 42, 14, PAL.cyan, 0.85, 7);
  drawCrosshair(42, 1158, 14, PAL.cyan, 0.85, 7);
  drawCrosshair(1158, 1158, 14, PAL.cyan, 0.85, 7);

  brush.set("fineliner", PAL.cyan, 0.7);
  brush.line(startX, 24, rightEdge, 24);
  brush.line(startX, 64, rightEdge, 64);
  brush.line(startX, 1154, rightEdge, 1154);

  // Header Technical Metadata (Top Left)
  drawTechText("SHEET // VAMP_LACE_BOW_SEQ_09", startX, 31, 9, PAL.techWhite, 0.85, 0.35);
  drawTechText("MEDIUM: COPIC_ALC_MARKER + ROTRING_0.1 // KEY: #D1086A", startX, 46, 7.5, PAL.cyan, 0.7, 0.32);

  // Alcohol Marker Calibration Swatch Strip (Top Right)
  const swatches = [
    { col: PAL.rubberBase, code: "W2" },
    { col: PAL.canvasLight, code: "E84" },
    { col: PAL.canvasBase, code: "YG95" },
    { col: PAL.canvasDark, code: "E77" },
    { col: PAL.foxingStripe, code: "E09" },
    { col: PAL.laceBase, code: "W0" },
    { col: PAL.laceShade2, code: "W4" },
    { col: PAL.laceInk, code: "100" }
  ];
  let swW = 32;
  let swH = 16;
  let swStart = rightEdge - swatches.length * (swW + 8) + 8;
  for (let i = 0; i < swatches.length; i++) {
    let sx = swStart + i * (swW + 8);
    let sy = 30;
    let sp = new brush.Polygon([[sx, sy], [sx + swW, sy], [sx + swW, sy + swH], [sx, sy + swH]]);
    sp.wash(swatches[i].col, 235);
    brush.noWash();

    // Alcohol marker chisel streak across swatch
    brush.set("alc_chisel", swatches[i].col, 1.1);
    brush.line(sx + 2, sy + 8, sx + swW - 2, sy + 8);

    // Cyan registration box around swatch
    brush.set("fineliner", PAL.cyan, 0.6);
    brush.line(sx, sy, sx + swW, sy);
    brush.line(sx + swW, sy, sx + swW, sy + swH);
    brush.line(sx + swW, sy + swH, sx, sy + swH);
    brush.line(sx, sy + swH, sx, sy);

    drawTechText(swatches[i].code, sx + 4, sy + swH + 4, 6.2, PAL.cyan, 0.65, 0.3);
  }

  // Left & Right Outer Margin Millimeter Rulers
  brush.set("fineliner", PAL.cyanDim, 0.55);
  for (let y = startY; y <= bottomEdge; y += 12) {
    let len = (y - startY) % 48 === 0 ? 10 : 4;
    brush.line(startX - 18, y, startX - 18 + len, y);
    brush.line(rightEdge + 18 - len, y, rightEdge + 18, y);
  }

  // Footer Timing Track & Scale Bar
  drawTechText("SCALE 1:1 // 3X3_RIGID_CELL_316PX // CAT_REF: SNK_TOE_884B", startX, 1164, 7.5, PAL.cyan, 0.7, 0.32);
  drawTechText("TIMING_TRACK: 12FPS_STEPPED", rightEdge - 245, 1164, 7.5, PAL.techWhite, 0.75, 0.32);

  // Center bottom registration bullseye
  drawCrosshair(600, 1154, 14, PAL.cyan, 0.8, 5);
}

function drawCellRegistration(x0, y0, s, g, row, col, idx, meta) {
  let x1 = x0 + s;
  let y1 = y0 + s;
  let mx = x0 + s * 0.5;
  let my = y0 + s * 0.5;

  // 1. Thin Cyan Cell Border & Corner L-Ticks
  brush.set("fineliner", PAL.cyanDim, 0.5);
  brush.line(x0, y0, x1, y0);
  brush.line(x1, y0, x1, y1);
  brush.line(x1, y1, x0, y1);
  brush.line(x0, y1, x0, y0);

  // Crisp brighter cyan corner brackets & midpoint ticks
  const tk = 10;
  brush.set("fineliner", PAL.cyan, 0.85);
  // Top-left
  brush.line(x0 - 3, y0, x0 + tk, y0);
  brush.line(x0, y0 - 3, x0, y0 + tk);
  // Top-right
  brush.line(x1 - tk, y0, x1 + 3, y0);
  brush.line(x1, y0 - 3, x1, y0 + tk);
  // Bottom-left
  brush.line(x0 - 3, y1, x0 + tk, y1);
  brush.line(x0, y1 - tk, x0, y1 + 3);
  // Bottom-right
  brush.line(x1 - tk, y1, x1 + 3, y1);
  brush.line(x1, y1 - tk, x1, y1 + 3);

  // Midpoint edge registration ticks
  brush.line(mx, y0 - 5, mx, y0 + 5);
  brush.line(mx, y1 - 5, mx, y1 + 5);
  brush.line(x0 - 5, my, x0 + 5, my);
  brush.line(x1 - 5, my, x1 + 5, my);

  // Fine millimeter sub-ticks along top-left & bottom-right cell edges
  brush.set("fineliner", PAL.cyanDim, 0.45);
  for (let d = 24; d < s - 16; d += 16) {
    if (abs(d - s * 0.5) < 12) continue;
    brush.line(x0 + d, y0, x0 + d, y0 + 3.5);
    brush.line(x0, y0 + d, x0 + 3.5, y0 + d);
  }

  // Gutter Intersection Crosshair (between cells)
  if (col < 2 && row < 2) {
    drawCrosshair(x1 + g * 0.5, y1 + g * 0.5, 9, PAL.cyan, 0.75, 3.5);
  }

  // 2. Top Gutter Labels (Frame ID & Knot Stage)
  drawTechText("[" + meta.id + "]", x0 + 2, y0 - 13, 7.5, PAL.techWhite, 0.82, 0.32);
  drawTechText(meta.stage, x0 + 62, y0 - 12.5, 6.8, PAL.cyan, 0.7, 0.3);

  // Mini 9-box sequence indicator at top-right of cell
  let bxStart = x1 - 9 * 6.5;
  let by = y0 - 11;
  for (let k = 0; k < 9; k++) {
    let bx = bxStart + k * 6.5;
    if (k === idx) {
      let fp = new brush.Polygon([[bx, by], [bx + 4.5, by], [bx + 4.5, by + 6], [bx, by + 6]]);
      fp.wash(PAL.cyan, 230);
      brush.noWash();
    }
    brush.set("fineliner", k <= idx ? PAL.cyan : PAL.cyanDim, 0.55);
    brush.line(bx, by, bx + 4.5, by);
    brush.line(bx + 4.5, by, bx + 4.5, by + 6);
    brush.line(bx + 4.5, by + 6, bx, by + 6);
    brush.line(bx, by + 6, bx, by);
  }

  // 3. Bottom Gutter Labels (Tension Readout & Aglet Coordinates)
  let tnsStr = "TNS:" + nf(meta.tns, 1, 2) + "N";
  drawTechText(tnsStr, x0 + 2, y1 + 6, 6.2, PAL.cyan, 0.65, 0.3);

  // Tension bar gauge
  let barX = x0 + 68;
  let barY = y1 + 7;
  let barW = 44;
  brush.set("fineliner", PAL.cyanDim, 0.55);
  brush.line(barX, barY, barX + barW, barY);
  brush.line(barX, barY + 4, barX + barW, barY + 4);
  brush.set("fineliner", PAL.cyan, 1.1);
  brush.line(barX, barY + 2, barX + barW * meta.tns, barY + 2);

  // Aglet coordinate readout
  drawTechText("AG:" + meta.agL, x1 - 118, y1 + 6, 6.0, PAL.techWhite, 0.6, 0.28);

  // Interior cell origin micro-crosshair near top-left corner of cell
  drawCrosshair(x0 + 18, y0 + 18, 5, PAL.cyanDim, 0.55);
  drawTechText("0" + (idx + 1), x0 + 26, y0 + 14.5, 6.5, PAL.cyan, 0.65, 0.3);
}

// =============================================================================
// SINGLE CELL RENDERER: SCUFFED CANVAS SNEAKER TOE + FRAME-SPECIFIC LACE BOW
// =============================================================================

function drawSneakerCell(cx, cy, idx, meta) {
  // Subtle frame-to-frame physical tug offset & throat compression
  const sc = 1.08;
  const ox = cx + random(-0.8, 0.8);
  const oy = cy + 12 + meta.dy;
  const pinch = meta.pinch; // 0..1 pulls eyestays slightly together when cinched

  // Helper to transform local shoe coordinates (lx, ly) into canvas coords
  const P = (lx, ly) => [ox + lx * sc, oy + ly * sc];

  // ---------------------------------------------------------------------------
  // 1. GROUND CAST SHADOW ON CHROMA-MAGENTA
  // ---------------------------------------------------------------------------
  let shadowPts = [
    P(-78, 30), P(-86, 68), P(-76, 114), P(-44, 142),
    P(4, 134), P(44, 96), P(58, 56), P(74, 4), P(58, -42), P(10, -56), P(-42, -16)
  ];
  let shPoly = new brush.Polygon(shadowPts);
  shPoly.wash(PAL.chromaShadow, 135);
  brush.noWash();

  // Tighter dark contact shadow directly under sole rim
  brush.set("alc_chisel", "#220212", 1.3);
  brush.spline([
    P(-77, 42), P(-81, 82), P(-68, 120), P(-38, 139), P(2, 128), P(38, 92), P(52, 54)
  ], 0.5);

  // ---------------------------------------------------------------------------
  // 2. CANVAS UPPER BODY (QUARTERS, VAMP & DARK THROAT INTERIOR)
  // ---------------------------------------------------------------------------
  // Main canvas upper silhouette
  let canvasPts = [
    P(-4, -58),   // lateral collar top
    P(-36, -24),  // lateral upper quarter
    P(-66, 18),   // lateral mid quarter
    P(-72, 50),   // lateral toe seam
    P(-22, 74),   // front vamp center under toe cap
    P(34, 66),    // medial toe seam
    P(54, 28),    // medial mid quarter
    P(68, -12),   // medial collar
    P(48, -48),   // heel/throat back
    P(18, -56)
  ];
  let canvasPoly = new brush.Polygon(canvasPts);
  canvasPoly.wash(PAL.canvasBase, 245);
  brush.noWash();

  // Subtle organic watercolor/marker stain bleed on weathered canvas
  brush.noStroke();
  let stainPts = [
    P(-58, 14), P(-64, 48), P(-18, 62), P(32, 54), P(46, 16), P(8, -18)
  ];
  let stainPoly = new brush.Polygon(stainPts);
  stainPoly.fill(PAL.canvasDark, 52, 0.22, 0.65);
  brush.noFill();

  // Layered Alcohol Marker directional strokes across the canvas vamp & quarters
  // Medial (right) shaded slope
  brush.set("alc_chisel", PAL.canvasMid, 1.35);
  for (let t = 0; t <= 1; t += 0.16) {
    let yA = lerp(-36, 42, t);
    let xA = lerp(38, 12, t);
    let xB = lerp(66, 36, t);
    let yB = lerp(-8, 62, t);
    brush.spline([P(xA, yA), P((xA + xB) * 0.5 + 3, (yA + yB) * 0.5 + 2), P(xB, yB)], 0.4);
  }

  // Lateral (left) lit canvas slope with warm khaki-olive highlights
  brush.set("alc_chisel", PAL.canvasLight, 1.25);
  for (let t = 0; t <= 1; t += 0.18) {
    let xA = lerp(-34, -64, t);
    let yA = lerp(-18, 22, t);
    let xB = lerp(-12, -48, t);
    let yB = lerp(16, 54, t);
    brush.spline([P(xA, yA), P((xA + xB) * 0.5 - 2, (yA + yB) * 0.5), P(xB, yB)], 0.4);
  }

  // Deep flexion creases across the vamp (behind the rubber toe cap)
  // Crease 1 (main toe-bend valley)
  brush.set("alc_soft", PAL.canvasDark, 1.1);
  brush.spline([P(-60, 34), P(-32, 30), P(-2, 38), P(28, 48)], 0.5);
  brush.set("alc_soft", PAL.canvasDeep, 0.7);
  brush.spline([P(-54, 35), P(-28, 31), P(2, 39), P(22, 47)], 0.5);
  // Bleached sun-worn ridge just above Crease 1
  brush.set("alc_soft", PAL.canvasBleach, 0.9);
  brush.spline([P(-56, 29), P(-28, 25), P(2, 33), P(25, 42)], 0.5);

  // Crease 2 (secondary upper vamp crease)
  brush.set("alc_soft", PAL.canvasDark, 0.9);
  brush.spline([P(-46, 16), P(-22, 18), P(6, 28)], 0.5);
  brush.set("alc_soft", PAL.canvasBleach, 0.75);
  brush.spline([P(-44, 12), P(-20, 14), P(6, 24)], 0.5);

  // Woven Canvas Duck Cross-Hatching Texture
  brush.hatchStyle("2H", PAL.canvasDark, 0.55);
  canvasPoly.hatch(5.5, 32, { rand: 0.08 });
  brush.hatchStyle("cpencil", PAL.canvasBleach, 0.45);
  canvasPoly.hatch(6.5, 122, { rand: 0.08 });
  brush.noHatch();

  // Dark Interior Throat Cavity (behind tongue)
  let throatPts = [
    P(2, -52), P(44, -44), P(58, -14), P(36, 2), P(-6, -14), P(-12, -38)
  ];
  let throatPoly = new brush.Polygon(throatPts);
  throatPoly.wash(PAL.canvasDeep, 245);
  brush.noWash();

  // ---------------------------------------------------------------------------
  // 3. PADDED CANVAS TONGUE & WOVEN TONGUE LABEL
  // ---------------------------------------------------------------------------
  let tonguePts = [
    P(-18, 34),   // base left under lower lace
    P(-4, -22),   // mid-left edge
    P(8, -50),    // top-left tongue corner
    P(30, -48),   // top crest center
    P(48, -32),   // top-right tongue corner
    P(30, 8),     // mid-right edge
    P(12, 44)     // base right under lower lace
  ];
  let tonguePoly = new brush.Polygon(tonguePts);
  tonguePoly.wash(PAL.tongueBase, 245);
  brush.noWash();

  // Tongue longitudinal cylindrical shading
  brush.set("alc_chisel", PAL.canvasBleach, 1.2);
  brush.spline([P(18, -46), P(8, -14), P(-2, 26)], 0.4);
  brush.set("alc_soft", PAL.canvasDark, 1.15);
  brush.spline([P(-4, -20), P(-12, 8), P(-16, 32)], 0.4);
  brush.spline([P(42, -28), P(28, 4), P(12, 38)], 0.4);

  // Woven specification tag stitched onto tongue crest
  let tagPts = [P(10, -47), P(41, -35), P(35, -21), P(4, -33)];
  let tagPoly = new brush.Polygon(tagPts);
  tagPoly.wash(PAL.tongueTag, 240);
  brush.noWash();
  brush.set("fineliner", PAL.canvasDeep, 0.65);
  tagPoly.draw("fineliner", PAL.canvasDeep, 0.65);
  // Tiny horizontal text lines inside tongue tag
  brush.line(...P(11, -42), ...P(36, -32));
  brush.line(...P(9, -38), ...P(33, -29));
  brush.line(...P(8, -34), ...P(26, -27));

  // Tongue perimeter contour
  brush.set("fineliner", PAL.canvasDeep, 0.8);
  brush.spline([P(-4, -22), P(8, -50), P(30, -48), P(48, -32), P(30, 8)], 0.45);

  // ---------------------------------------------------------------------------
  // 4. REINFORCED EYESTAY PANELS (FLANKING THE TONGUE)
  // ---------------------------------------------------------------------------
  let pL = pinch * 3.2; // inward pinch shift when laces cinch
  // Left (Lateral) Eyestay Flap
  let leftStayPts = [
    P(-38, 30), P(-22 + pL, 36), P(2 + pL, -12), P(8 + pL * 0.5, -42),
    P(-6, -50), P(-20, -18)
  ];
  let leftStayPoly = new brush.Polygon(leftStayPts);
  leftStayPoly.wash(PAL.canvasMid, 240);
  brush.noWash();

  // Right (Medial) Eyestay Flap
  let rightStayPts = [
    P(6 - pL, 48), P(24, 52), P(56, -4), P(62, -26),
    P(48 - pL * 0.5, -28), P(32 - pL, 4)
  ];
  let rightStayPoly = new brush.Polygon(rightStayPts);
  rightStayPoly.wash(PAL.canvasDark, 240);
  brush.noWash();

  // Eyestay highlight bevel & double-row fine-liner stitching
  brush.set("alc_soft", PAL.canvasLight, 0.85);
  brush.spline([P(-22 + pL, 34), P(-8 + pL, 10), P(2 + pL, -14), P(6, -38)], 0.4);
  brush.spline([P(8 - pL, 46), P(22 - pL, 22), P(34 - pL, 0), P(48, -24)], 0.4);

  brush.set("fineliner", PAL.canvasDeep, 0.85);
  brush.spline([P(-22 + pL, 36), P(-8 + pL, 10), P(2 + pL, -12), P(8, -42)], 0.4);
  brush.spline([P(6 - pL, 48), P(20 - pL, 24), P(32 - pL, 4), P(48, -28)], 0.4);

  // Dashed seam stitching along outer eyestay curves & quarter panel
  drawStitchedCurve([P(-38, 30), P(-26, 4), P(-16, -20), P(-6, -48)], PAL.canvasDeep, PAL.canvasBleach);
  drawStitchedCurve([P(-35, 31), P(-23, 5), P(-13, -19), P(-3, -47)], PAL.canvasDeep, PAL.canvasBleach);
  drawStitchedCurve([P(24, 52), P(38, 26), P(52, 0), P(62, -26)], PAL.canvasDeep, PAL.canvasBleach);
  drawStitchedCurve([P(21, 50), P(35, 24), P(49, -2), P(59, -27)], PAL.canvasDeep, PAL.canvasBleach);

  // Quarter panel curved side seams
  drawStitchedCurve([P(-36, 20), P(-52, 22), P(-68, 32)], PAL.canvasDeep, PAL.canvasLight);
  drawStitchedCurve([P(34, 34), P(46, 38), P(52, 48)], PAL.canvasDeep, PAL.canvasLight);

  // ---------------------------------------------------------------------------
  // 5. DOMED RUBBER TOE CAP (WARM PUTTY-IVORY WITH SPECULAR SHINE & SCUFFS)
  // ---------------------------------------------------------------------------
  let toeCapPts = [
    P(-72, 48),   // lateral rear corner
    P(-48, 42),   // lateral arch
    P(-16, 46),   // top crest of rubber toe cap
    P(14, 58),    // medial arch
    P(34, 72),    // medial rear corner
    P(18, 98),    // medial front lower edge
    P(-12, 118),  // front-right lower edge
    P(-44, 122),  // front tip lower edge
    P(-68, 104),  // front-left lower edge
    P(-76, 76)    // lateral front lower edge
  ];
  let toeCapPoly = new brush.Polygon(toeCapPts);
  toeCapPoly.wash(PAL.rubberBase, 250);
  brush.noWash();

  // Glue yellowing stain along the canvas/rubber toe cap seam
  brush.set("alc_soft", PAL.glueStain, 0.95);
  brush.spline([P(-70, 47), P(-46, 41), P(-16, 45), P(14, 57), P(32, 71)], 0.5);

  // 3D Domed Alcohol Marker Shading on Toe Cap
  // Shaded medial & lower-front slope
  brush.set("alc_chisel", PAL.rubberMid, 1.45);
  brush.spline([P(-10, 52), P(12, 64), P(28, 76)], 0.45);
  brush.spline([P(-24, 78), P(2, 84), P(22, 88)], 0.45);
  brush.spline([P(-58, 96), P(-32, 110), P(-4, 108), P(20, 92)], 0.5);

  brush.set("alc_soft", PAL.rubberDark, 1.2);
  brush.spline([P(2, 68), P(18, 80), P(24, 92)], 0.45);
  brush.spline([P(-46, 114), P(-18, 114), P(10, 100)], 0.5);

  // Bright Paper-Reserve / White Marker Specular Dome Highlight (Upper-Left of Toe Cap)
  let hiPts = [
    P(-60, 56), P(-36, 52), P(-18, 60), P(-26, 76), P(-52, 82), P(-66, 72)
  ];
  let hiPoly = new brush.Polygon(hiPts);
  hiPoly.wash(PAL.rubberLight, 225);
  brush.noWash();

  brush.set("aglet_shine", PAL.lacePure, 1.35);
  brush.spline([P(-56, 62), P(-38, 58), P(-22, 64)], 0.5);
  brush.set("aglet_shine", PAL.lacePure, 0.85);
  brush.spline([P(-52, 68), P(-36, 65), P(-25, 70)], 0.5);

  // Double stitching along rear seam of rubber toe cap
  drawStitchedCurve([P(-71, 48), P(-48, 42), P(-16, 46), P(14, 58), P(33, 72)], PAL.canvasDeep, PAL.rubberLight);
  drawStitchedCurve([P(-72, 51), P(-48, 45), P(-16, 49), P(13, 61), P(31, 75)], PAL.canvasDeep, PAL.rubberLight);

  // Scuff marks & asphalt scratches on the rubber toe cap
  brush.set("alc_soft", PAL.rubberScuff, 0.75);
  brush.line(...P(-48, 86), ...P(-30, 78));
  brush.line(...P(-42, 92), ...P(-22, 85));
  brush.set("fineliner", PAL.rubberScuff, 0.65);
  brush.line(...P(-50, 88), ...P(-28, 79));
  brush.line(...P(-12, 94), ...P(4, 88));
  brush.line(...P(-62, 74), ...P(-50, 69));

  // ---------------------------------------------------------------------------
  // 6. VULCANIZED RUBBER FOXING TAPE, RACING STRIPE & TEXTURED TOE BUMPER
  // ---------------------------------------------------------------------------
  let foxingPts = [
    P(-74, 32),   // lateral rear foxing top
    P(-76, 66),   // lateral mid foxing top
    P(-68, 98),   // lateral toe cap base
    P(-42, 116),  // front tip top of bumper
    P(-8, 112),   // front-right top of bumper
    P(22, 92),    // medial toe cap base
    P(42, 66),    // medial mid foxing top
    P(54, 34),    // medial rear foxing top
    P(48, 54),    // medial rear sole bottom
    P(32, 86),    // medial mid sole bottom
    P(4, 118),    // front-right sole bottom
    P(-38, 136),  // front toe tip bottom
    P(-68, 118),  // front-left sole bottom
    P(-80, 82),   // lateral mid sole bottom
    P(-78, 48)    // lateral rear sole bottom
  ];
  let foxingPoly = new brush.Polygon(foxingPts);
  foxingPoly.wash(PAL.rubberMid, 250);
  brush.noWash();

  // Lighter upper bevel on the foxing tape
  brush.set("alc_chisel", PAL.rubberBase, 1.15);
  brush.spline([P(-75, 42), P(-74, 72), P(-64, 102), P(-38, 119), P(-6, 114), P(24, 94), P(44, 66)], 0.5);

  // Darker lower sole edge & medial shadow
  brush.set("alc_chisel", PAL.rubberDark, 1.3);
  brush.spline([P(-78, 54), P(-79, 84), P(-66, 116), P(-38, 134), P(2, 116), P(32, 84), P(48, 52)], 0.5);

  // Classic Burnt-Umber / Terracotta Foxing Pinstripe along top rim of rubber sidewall
  brush.set("alc_soft", PAL.foxingStripe, 0.95);
  brush.spline([P(-74, 35), P(-76, 68), P(-67, 100), P(-41, 117), P(-8, 113), P(22, 93), P(42, 67), P(53, 37)], 0.5);
  brush.set("fineliner", PAL.foxingStripe, 0.9);
  brush.spline([P(-74, 35), P(-76, 68), P(-67, 100), P(-41, 117), P(-8, 113), P(22, 93), P(42, 67), P(53, 37)], 0.5);

  // Raised Textured Rubber Toe Bumper Crescent (with diamond waffle ribs)
  let bumperTop = [P(-72, 82), P(-62, 104), P(-38, 120), P(-8, 115), P(18, 97)];
  let bumperBot = [P(-74, 94), P(-65, 116), P(-38, 134), P(-4, 122), P(18, 104)];

  // Draw 3 moulded horizontal bumper ridges
  brush.set("fineliner", PAL.rubberDark, 0.68);
  for (let r = 0.25; r <= 0.85; r += 0.3) {
    let ridgePts = [];
    for (let i = 0; i < bumperTop.length; i++) {
      ridgePts.push([
        lerp(bumperTop[i][0], bumperBot[i][0], r),
        lerp(bumperTop[i][1], bumperBot[i][1], r)
      ]);
    }
    brush.spline(ridgePts, 0.5);
  }

  // Draw vertical/radial moulded ribs across the front bumper crescent
  let ribSteps = 22;
  for (let i = 0; i <= ribSteps; i++) {
    let t = i / ribSteps;
    let pT = samplePolyline(bumperTop, t);
    let pB = samplePolyline(bumperBot, t);
    brush.set("fineliner", i % 2 === 0 ? PAL.rubberDark : PAL.rubberScuff, 0.55);
    brush.line(pT[0], pT[1], pB[0], pB[1]);
  }

  // Heavy asphalt scuff & grime smudges on the foxing edge
  brush.set("alc_soft", PAL.rubberScuff, 1.0);
  brush.spline([P(-76, 64), P(-72, 88), P(-58, 108)], 0.4);
  brush.spline([P(-24, 126), P(-4, 118), P(14, 104)], 0.4);

  // Fine-liner crisp outer contour of the sneaker sole & upper
  brush.set("fineliner", PAL.laceInk, 0.95);
  brush.spline([
    P(-4, -58), P(-36, -24), P(-66, 18), P(-74, 34),
    P(-80, 82), P(-68, 118), P(-38, 136), P(4, 118),
    P(32, 86), P(48, 54), P(54, 34), P(68, -12), P(48, -48)
  ], 0.45);

  // Medial sidewall ventilation eyelets (2 small grommets on the arch)
  drawEyelet(...P(45, 44), 3.6, 2.2, 55);
  drawEyelet(...P(51, 28), 3.6, 2.2, 55);

  // Fine spray spatter of dried earth/dust across toe and vamp
  brush.set("spray", PAL.canvasDark, 0.65);
  brush.line(...P(-52, 64), ...P(-10, 92));
  brush.set("spray", PAL.rubberScuff, 0.55);
  brush.line(...P(-66, 86), ...P(-28, 118));

  // ---------------------------------------------------------------------------
  // 7. GRUBBY METAL EYELETS & LOWER CRISS-CROSS LACES (PAIRS 1, 2, 3)
  // ---------------------------------------------------------------------------
  const E1L = P(-23 + pL * 0.4, 28);
  const E1R = P(10 - pL * 0.4, 42);
  const E2L = P(-13 + pL * 0.7, 6);
  const E2R = P(22 - pL * 0.7, 20);
  const E3L = P(-4 + pL, -16);
  const E3R = P(34 - pL, -2);
  const E4L = P(3, -38);
  const E4R = P(45, -22);

  // Draw the 4 pairs of grubby metal eyelets first (laces will emerge out of their centers)
  drawEyelet(E1L[0], E1L[1], 5.6, 3.8, -22);
  drawEyelet(E1R[0], E1R[1], 5.6, 3.8, 28);
  drawEyelet(E2L[0], E2L[1], 5.8, 4.0, -20);
  drawEyelet(E2R[0], E2R[1], 5.8, 4.0, 26);
  drawEyelet(E3L[0], E3L[1], 6.2, 4.2, -18);
  drawEyelet(E3R[0], E3R[1], 6.2, 4.2, 24);
  drawEyelet(E4L[0], E4L[1], 5.2, 3.4, -16);
  drawEyelet(E4R[0], E4R[1], 5.2, 3.4, 22);

  // Lower Criss-Cross Shoelaces (woven tightly between Pair 1 -> Pair 2 -> Pair 3)
  // 1) Bottom bar E1L -> E1R
  drawLaceRibbon([
    [E1L[0], E1L[1], 3.6],
    [(E1L[0] + E1R[0]) * 0.5 - 1, (E1L[1] + E1R[1]) * 0.5 - 2, 5.4],
    [E1R[0], E1R[1], 3.6]
  ], { shadowOffset: [2, 4], dirtyEnds: true, frayCount: 4 });

  // 2) Cross E1L -> E2R (under)
  drawLaceRibbon([
    [E1L[0], E1L[1], 3.5],
    [(E1L[0] + E2R[0]) * 0.5, (E1L[1] + E2R[1]) * 0.5 - 2, 5.2],
    [E2R[0], E2R[1], 3.5]
  ], { shadowOffset: [2.5, 4.5], dirtyEnds: true, frayCount: 4 });

  // 3) Cross E1R -> E2L (over)
  drawLaceRibbon([
    [E1R[0], E1R[1], 3.5],
    [(E1R[0] + E2L[0]) * 0.5, (E1R[1] + E2L[1]) * 0.5 - 3, 5.4],
    [E2L[0], E2L[1], 3.5]
  ], { shadowOffset: [3, 5], dirtyEnds: true, frayCount: 5 });

  // 4) Cross E2L -> E3R (under)
  drawLaceRibbon([
    [E2L[0], E2L[1], 3.5],
    [(E2L[0] + E3R[0]) * 0.5, (E2L[1] + E3R[1]) * 0.5 - 2, 5.3],
    [E3R[0], E3R[1], 3.6]
  ], { shadowOffset: [2.5, 4.5], dirtyEnds: true, frayCount: 4 });

  // 5) Cross E2R -> E3L (over)
  drawLaceRibbon([
    [E2R[0], E2R[1], 3.5],
    [(E2R[0] + E3L[0]) * 0.5, (E2R[1] + E3L[1]) * 0.5 - 3, 5.5],
    [E3L[0], E3L[1], 3.6]
  ], { shadowOffset: [3, 5], dirtyEnds: true, frayCount: 5 });

  // ---------------------------------------------------------------------------
  // 8. ANIMATED 9-FRAME SHOELACE BOW SEQUENCE (FROM TOP EYELETS E3L & E3R)
  // ---------------------------------------------------------------------------
  drawAnimatedLaceFrame(idx, P, E3L, E3R);
}

// =============================================================================
// FRAME-BY-FRAME SHOELACE KNOT & BOW CHOREOGRAPHY (FRAMES 0..8)
// =============================================================================

function drawAnimatedLaceFrame(idx, P, EL, ER) {
  const KC = [(EL[0] + ER[0]) * 0.5, (EL[1] + ER[1]) * 0.5 - 4];

  if (idx === 0) {
    // F_01: OPEN_DRAPE — Loose laces sweep out wide to left and right
    let leftStrand = [
      [EL[0], EL[1], 3.6],
      [...P(-36, -54), 5.6],
      [...P(-78, -68), 5.2],
      [...P(-106, -34), 4.6],
      [...P(-112, 12), 4.0]
    ];
    let rightStrand = [
      [ER[0], ER[1], 3.6],
      [...P(68, -42), 5.6],
      [...P(102, -46), 5.2],
      [...P(116, -6), 4.6],
      [...P(108, 36), 4.0]
    ];
    drawLaceRibbon(leftStrand, { shadowOffset: [5, 8], dirtyEnds: true, twist: 1.5 });
    drawLaceRibbon(rightStrand, { shadowOffset: [5, 8], dirtyEnds: true, twist: 1.5 });
    drawAgletFromStrand(leftStrand, 108);
    drawAgletFromStrand(rightStrand, 102);

    // Subtle cyan trajectory ticks indicating upward lift
    drawMotionArc(P(-92, -48), 28, -145, -75);
    drawMotionArc(P(96, -34), 28, -35, -105);

  } else if (idx === 1) {
    // F_02: OVER_CROSS — Laces rise into a tall X crossover above the tongue
    let leftStrand = [
      [EL[0], EL[1], 3.6],
      [...P(-4, -38), 5.4],
      [...P(18, -56), 5.2],
      [...P(58, -88), 5.0],
      [...P(92, -100), 4.0]
    ];
    let rightStrand = [
      [ER[0], ER[1], 3.6],
      [...P(32, -32), 5.4],
      [...P(14, -56), 5.6],
      [...P(-34, -86), 5.0],
      [...P(-74, -96), 4.0]
    ];
    drawLaceRibbon(leftStrand, { shadowOffset: [5, 9], dirtyEnds: true, twist: 1.2 });
    drawLaceRibbon(rightStrand, { shadowOffset: [6, 10], dirtyEnds: true, twist: 1.2 });
    drawAgletFromStrand(leftStrand, -14);
    drawAgletFromStrand(rightStrand, -166);
    drawMotionArc(P(16, -72), 24, -150, -30);

  } else if (idx === 2) {
    // F_03: UNDER_TUCK — Right strand wraps over X-bridge and dives under toward viewer
    let leftStrand = [
      [EL[0], EL[1], 3.6],
      [...P(4, -34), 5.0],
      [...P(24, -44), 4.8],
      [...P(64, -58), 5.2],
      [...P(96, -42), 4.0]
    ];
    let rightBase = [
      [ER[0], ER[1], 3.6],
      [...P(28, -26), 5.0],
      [...P(14, -46), 4.4]
    ];
    let rightTuck = [
      [...P(14, -46), 3.8],
      [...P(4, -24), 5.6],
      [...P(-14, -4), 5.4],
      [...P(-32, 12), 4.2]
    ];
    drawLaceRibbon(leftStrand, { shadowOffset: [5, 8], dirtyEnds: true });
    drawLaceRibbon(rightBase, { shadowOffset: [4, 7], dirtyEnds: true });
    drawKnotWrap(P(15, -42), 11, 7, -15);
    drawLaceRibbon(rightTuck, { shadowOffset: [4, 6], dirtyEnds: false });
    drawAgletFromStrand(leftStrand, 24);
    drawAgletFromStrand(rightTuck, 136);
    drawMotionArc(P(-16, -8), 22, -60, 45);

  } else if (idx === 3) {
    // F_04: BASE_CINCH — Starter half-hitch pulled taut between top eyelets
    let bridge = [
      [EL[0], EL[1], 3.6],
      [KC[0], KC[1], 4.8],
      [ER[0], ER[1], 3.6]
    ];
    let leftPull = [
      [KC[0] - 3, KC[1], 3.8],
      [...P(-28, -22), 5.4],
      [...P(-68, -28), 5.2],
      [...P(-98, -28), 4.0]
    ];
    let rightPull = [
      [KC[0] + 3, KC[1], 3.8],
      [...P(54, -14), 5.4],
      [...P(86, -16), 5.2],
      [...P(108, -12), 4.0]
    ];
    drawLaceRibbon(bridge, { shadowOffset: [2, 3], dirtyEnds: true });
    drawLaceRibbon(leftPull, { shadowOffset: [5, 8], dirtyEnds: false, twist: 0.8 });
    drawLaceRibbon(rightPull, { shadowOffset: [5, 8], dirtyEnds: false, twist: 0.8 });
    drawKnotWrap(KC, 13, 8, 12);
    drawAgletFromStrand(leftPull, -176);
    drawAgletFromStrand(rightPull, 6);

    // High-tension cyan force vectors
    brush.set("fineliner", PAL.cyan, 0.7);
    brush.line(...P(-82, -38), ...P(-108, -38));
    brush.line(...P(72, -26), ...P(98, -26));

  } else if (idx === 4) {
    // F_05: LEFT_BIGHT — First standing "bunny ear" loop formed on left; right strand sweeps up
    drawLaceRibbon([[EL[0], EL[1], 3.6], [KC[0], KC[1], 4.8], [ER[0], ER[1], 3.6]], { shadowOffset: [2, 3] });

    // Left standing loop (back leg then front leg)
    let loopBack = [
      [KC[0] - 2, KC[1] - 2, 3.6],
      [...P(-4, -58), 5.4],
      [...P(-22, -104), 5.2]
    ];
    let loopFront = [
      [...P(-22, -104), 5.2],
      [...P(-34, -92), 5.6],
