// =============================================================================
// HYPERREAL COMPONENT PRIMITIVES: LACE RIBBONS, AGLETS, EYELETS & STITCHING
// =============================================================================

function drawLaceRibbon(ctrlPts, opts = {}) {
  const steps = 26;
  const shOff = opts.shadowOffset || [3, 5];
  const darken = opts.darken || false;
  const twist = opts.twist || 0.0;
  const frayCount = opts.frayCount !== undefined ? opts.frayCount : 8;

  let spine = [];
  let leftEdge = [];
  let rightEdge = [];
  let shadowPolyPts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = sampleRibbonPoint(ctrlPts, t);
    let ptNext = sampleRibbonPoint(ctrlPts, min(1, t + 0.02));
    let ptPrev = sampleRibbonPoint(ctrlPts, max(0, t - 0.02));
    let dx = ptNext[0] - ptPrev[0];
    let dy = ptNext[1] - ptPrev[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    let hw = pt[2];
    if (twist > 0) {
      hw *= 0.68 + 0.32 * abs(cos(t * 180 * twist));
    }

    let lx = pt[0] + nx * hw;
    let ly = pt[1] + ny * hw;
    let rx = pt[0] - nx * hw;
    let ry = pt[1] - ny * hw;

    spine.push([pt[0], pt[1], hw, nx, ny]);
    leftEdge.push([lx, ly]);
    rightEdge.push([rx, ry]);
  }

  // Build closed polygon for ribbon & shadow
  let ribbonPolyPts = [];
  for (let i = 0; i < leftEdge.length; i++) {
    ribbonPolyPts.push(leftEdge[i]);
    shadowPolyPts.push([leftEdge[i][0] + shOff[0], leftEdge[i][1] + shOff[1]]);
  }
  for (let i = rightEdge.length - 1; i >= 0; i--) {
    ribbonPolyPts.push(rightEdge[i]);
    shadowPolyPts.push([rightEdge[i][0] + shOff[0], rightEdge[i][1] + shOff[1]]);
  }

  // 1. Cast Shadow Wash
  let shPoly = new brush.Polygon(shadowPolyPts);
  shPoly.wash(PAL.canvasDeep, 95);

  // 2. Woven Cotton Base Wash
  let rbPoly = new brush.Polygon(ribbonPolyPts);
  rbPoly.wash(darken ? PAL.laceShade1 : PAL.laceBase, 250);
  brush.noWash();

  // 3. Alcohol Marker Dimensional Shading along Lower/Right Edge & Pinch Ends
  let shadeSpine = [];
  let hiSpine = [];
  for (let i = 0; i < spine.length; i++) {
    let s = spine[i];
    shadeSpine.push([s[0] - s[3] * s[2] * 0.45, s[1] - s[4] * s[2] * 0.45]);
    hiSpine.push([s[0] + s[3] * s[2] * 0.35, s[1] + s[4] * s[2] * 0.35]);
  }
  brush.set("alc_soft", darken ? PAL.laceShade2 : PAL.laceShade1, 0.95);
  brush.spline(shadeSpine, 0.45);

  if (!darken) {
    brush.set("aglet_shine", PAL.lacePure, 1.05);
    brush.spline(hiSpine, 0.45);
  }

  // Dirty eyelet grime smudges at start/end of lace segment
  if (opts.dirtyEnds) {
    brush.set("alc_soft", PAL.laceDirty, 0.85);
    let s0 = spine[0];
    let s1 = spine[spine.length - 1];
    brush.circle(s0[0], s0[1], 3.2, 0.2);
    brush.circle(s1[0], s1[1], 3.2, 0.2);
  }

  // 4. Braided Cotton Herringbone Weave Texture
  brush.set("fineliner", darken ? PAL.laceDirty : PAL.laceShade2, 0.52);
  for (let i = 1; i < spine.length - 1; i += 2) {
    let sPrev = spine[i - 1];
    let sCurr = spine[i];
    let lP = leftEdge[i - 1];
    let rP = rightEdge[i - 1];
    brush.line(lP[0], lP[1], sCurr[0], sCurr[1]);
    brush.line(rP[0], rP[1], sCurr[0], sCurr[1]);
  }

  // 5. Crisp Fine-Liner Contour Edges
  brush.set("fineliner", PAL.laceInk, 0.78);
  brush.spline(leftEdge, 0.45);
  brush.spline(rightEdge, 0.45);

  // 6. Micro-Frayed Cotton Fuzz Whiskers Sprouting from Ribbon Edges
  for (let f = 0; f < frayCount; f++) {
    let idx = floor(random(2, spine.length - 2));
    let side = random() < 0.5 ? leftEdge[idx] : rightEdge[idx];
    let ang = random(0, 360);
    let len = random(3.0, 6.8);
    brush.set("fineliner", random() < 0.65 ? PAL.lacePure : PAL.laceInk, 0.45);
    brush.line(side[0], side[1], side[0] + cos(ang) * len, side[1] + sin(ang) * len);
  }
}

function drawKnotWrap(center, w, h, angleDeg) {
  let cx = center[0];
  let cy = center[1];
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  const K = (dx, dy) => [cx + dx * ca - dy * sa, cy + dx * sa + dy * ca];

  let pts = [
    K(-w * 0.5, -h * 0.42),
    K(w * 0.5, -h * 0.45),
    K(w * 0.58, h * 0.42),
    K(-w * 0.55, h * 0.45)
  ];

  // Drop shadow under knot barrel
  let sh = new brush.Polygon(pts.map(p => [p[0] + 2.5, p[1] + 4]));
  sh.wash(PAL.canvasDeep, 150);

  // Knot cotton base
  let kp = new brush.Polygon(pts);
  kp.wash(PAL.laceBase, 252);
  brush.noWash();

  // Deep pinch folds & alcohol marker shading
  brush.set("alc_soft", PAL.laceShade2, 1.0);
  brush.line(...K(-w * 0.45, h * 0.25), ...K(w * 0.45, h * 0.25));
  brush.set("alc_soft", PAL.laceDirty, 0.8);
  brush.line(...K(-w * 0.35, -h * 0.1), ...K(w * 0.35, h * 0.15));

  // Specular ridge across top of knot
  brush.set("aglet_shine", PAL.lacePure, 1.0);
  brush.line(...K(-w * 0.38, -h * 0.22), ...K(w * 0.38, -h * 0.22));

  // Braided weave & dark crease lines
  brush.set("fineliner", PAL.laceInk, 0.82);
  kp.draw("fineliner", PAL.laceInk, 0.82);
  brush.line(...K(-w * 0.4, 0), ...K(w * 0.4, 0.08 * h));
  brush.line(...K(-w * 0.2, -h * 0.42), ...K(w * 0.2, h * 0.42));
}

function drawAgletFromStrand(strandPts, angleDeg) {
  let last = strandPts[strandPts.length - 1];
  drawAglet(last[0], last[1], angleDeg, 22, 6.2);
}

function drawAglet(x, y, angleDeg, len = 22, width = 6.2) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  let nx = -sa;
  let ny = ca;
  let hw0 = width * 0.5;
  let hw1 = width * 0.44;

  const A = (u, v) => [x + u * ca + v * nx, y + u * sa + v * ny];

  let polyPts = [
    A(0, -hw0),
    A(len, -hw1),
    A(len, hw1),
    A(0, hw0)
  ];

  // 1. Cast Shadow
  let shPoly = new brush.Polygon(polyPts.map(p => [p[0] + 3.5, p[1] + 5.5]));
  shPoly.wash(PAL.chromaShadow, 145);

  // 2. Plastic Acetate Tube Base Wash
  let agPoly = new brush.Polygon(polyPts);
  agPoly.wash(PAL.agletBase, 248);
  brush.noWash();

  // 3. Cylindrical Marker Shading on Lower Half of Aglet
  brush.set("alc_soft", PAL.agletShade, 0.95);
  brush.line(...A(1, hw0 * 0.45), ...A(len - 1, hw1 * 0.45));

  // 4. Metal/Plastic Neck Crimp Rings
  brush.set("fineliner", PAL.agletCrimp, 0.78);
  brush.line(...A(3.2, -hw0), ...A(3.2, hw0));
  brush.line(...A(5.8, -hw0 * 0.98), ...A(5.8, hw0 * 0.98));

  // 5. Crisp Fine-Liner Tube Outline
  brush.set("fineliner", PAL.laceInk, 0.85);
  agPoly.draw("fineliner", PAL.laceInk, 0.85);

  // 6. HYPERREAL AGLET PLASTIC SHINE (Razor-sharp white specular streak + dot)
  brush.set("aglet_shine", PAL.lacePure, 1.35);
  brush.line(...A(2.5, -hw0 * 0.48), ...A(len - 4.5, -hw1 * 0.48));
  brush.line(...A(len - 2.8, -hw1 * 0.48), ...A(len - 1.4, -hw1 * 0.48));

  // Subtle cyan secondary rim reflection on plastic cylinder
  brush.set("fineliner", PAL.cyan, 0.5);
  brush.line(...A(4, hw0 * 0.72), ...A(len - 3, hw1 * 0.72));

  // 7. Frayed White Cotton Tuft Bursting from Open Tip of Aglet
  const numThreads = 14;
  for (let i = 0; i < numThreads; i++) {
    let frac = (i / (numThreads - 1)) - 0.5;
    let basePt = A(len, frac * hw1 * 1.4);
    let splayAngle = angleDeg + frac * 54 + random(-8, 8);
    let tLen = random(5.0, 10.5);
    let endX = basePt[0] + cos(splayAngle) * tLen;
    let endY = basePt[1] + sin(splayAngle) * tLen;

    let col = i % 3 === 0 ? PAL.laceInk : (i % 2 === 0 ? PAL.lacePure : PAL.laceBase);
    brush.set(col === PAL.lacePure ? "aglet_shine" : "fineliner", col, col === PAL.lacePure ? 0.75 : 0.55);
    brush.line(basePt[0], basePt[1], endX, endY);
  }
}

function drawEyelet(x, y, rx, ry, rotDeg) {
  let ca = cos(rotDeg);
  let sa = sin(rotDeg);
  const E = (rScale, ang) => {
    let lx = cos(ang) * rx * rScale;
    let ly = sin(ang) * ry * rScale;
    return [x + lx * ca - ly * sa, y + lx * sa + ly * ca];
  };

  let grimePts = [];
  let outerPts = [];
  let innerPts = [];
  for (let a = 0; a < 360; a += 30) {
    grimePts.push(E(1.42, a));
    outerPts.push(E(1.0, a));
    innerPts.push(E(0.52, a));
  }

  // 1. Grubby Oxidized Halo Staining the Surrounding Canvas
  let gPoly = new brush.Polygon(grimePts);
  gPoly.wash(PAL.eyeletGrime, 130);

  // 2. Metallic Flange Base
  let oPoly = new brush.Polygon(outerPts);
  oPoly.wash(PAL.eyeletBase, 248);

  // 3. Dark Recessed Grommet Hole
  let iPoly = new brush.Polygon(innerPts);
  iPoly.wash(PAL.eyeletHole, 252);
  brush.noWash();

  // 4. Shaded Lower-Right Rim & Specular Upper-Left Rim
  brush.set("fineliner", PAL.eyeletDark, 0.9);
  oPoly.draw("fineliner", PAL.eyeletDark, 0.85);
  iPoly.draw("fineliner", PAL.laceInk, 0.75);

  // Specular metal glint on upper-left arc of flange
  let glintPts = [E(0.76, 165), E(0.76, 215), E(0.76, 265), E(0.76, 305)];
  brush.set("aglet_shine", PAL.lacePure, 1.0);
  brush.spline(glintPts, 0.5);
}

function drawStitchedCurve(pts, inkCol, threadCol) {
  let totalSteps = 18;
  for (let i = 0; i < totalSteps; i++) {
    let t0 = i / totalSteps;
    let t1 = (i + 0.58) / totalSteps;
    let p0 = samplePolyline(pts, t0);
    let p1 = samplePolyline(pts, t1);
    brush.set("fineliner", inkCol, 0.62);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.set("fineliner", threadCol, 0.45);
    brush.line(p0[0] + 0.4, p0[1] - 0.4, p1[0] + 0.4, p1[1] - 0.4);
  }
}

function drawMotionArc(center, r, startAng, endAng) {
  brush.set("fineliner", PAL.cyan, 0.65);
  let steps = 8;
  for (let i = 0; i < steps; i += 2) {
    let a0 = lerp(startAng, endAng, i / steps);
    let a1 = lerp(startAng, endAng, (i + 1) / steps);
    brush.line(
      center[0] + cos(a0) * r, center[1] + sin(a0) * r,
      center[0] + cos(a1) * r, center[1] + sin(a1) * r
    );
  }
  // Tiny arrowhead at endAng
  let tipX = center[0] + cos(endAng) * r;
  let tipY = center[1] + sin(endAng) * r;
  let dir = endAng + (endAng > startAng ? 90 : -90);
  brush.line(tipX, tipY, tipX + cos(dir - 150) * 4.5, tipY + sin(dir - 150) * 4.5);
  brush.line(tipX, tipY, tipX + cos(dir + 150) * 4.5, tipY + sin(dir + 150) * 4.5);
}

// =============================================================================
// GEOMETRY INTERPOLATION HELPERS
// =============================================================================

function samplePolyline(pts, t) {
  let n = pts.length - 1;
  let f = constrain(t, 0, 1) * n;
  let i = min(floor(f), n - 1);
  let u = f - i;
  return [
    lerp(pts[i][0], pts[i + 1][0], u),
    lerp(pts[i][1], pts[i + 1][1], u)
  ];
}

function sampleRibbonPoint(ctrlPts, t) {
  let n = ctrlPts.length - 1;
  let f = constrain(t, 0, 1) * n;
  let i = min(floor(f), n - 1);
  let u = f - i;

  let p0 = ctrlPts[max(0, i - 1)];
  let p1 = ctrlPts[i];
  let p2 = ctrlPts[min(n, i + 1)];
  let p3 = ctrlPts[min(n, i + 2)];

  // Catmull-Rom spline interpolation for smooth shoelace curves
  let u2 = u * u;
  let u3 = u2 * u;
  let c0 = -0.5 * u3 + u2 - 0.5 * u;
  let c1 = 1.5 * u3 - 2.5 * u2 + 1.0;
  let c2 = -1.5 * u3 + 2.0 * u2 + 0.5 * u;
  let c3 = 0.5 * u3 - 0.5 * u2;

  return [
    c0 * p0[0] + c1 * p1[0] + c2 * p2[0] + c3 * p3[0],
    c0 * p0[1] + c1 * p1[1] + c2 * p2[1] + c3 * p3[1],
    lerp(p1[2], p2[2], u)
  ];
}

// Hyperrealistic Coloured Pencil on Toned Buff Paper:
// Three Marzipan Piglets in a Crinkled Glassine Bonbon Cup

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(8317);

  // Custom coloured pencil & sugar grain brushes
  brush.add("prismacolor_soft", {
    type: "default",
    weight: 0.75,
    scatter: 0.32,
    sharpness: 0.35,
    grain: 14,
    opacity: 145,
    spacing: 0.14,
    pressure: [0.4, 1.15, 0.35],
    rotate: "natural",
    noise: 0.55
  });

  brush.add("polychromos_fine", {
    type: "default",
    weight: 0.32,
    scatter: 0.12,
    sharpness: 0.72,
    grain: 9,
    opacity: 185,
    spacing: 0.1,
    pressure: [0.25, 1.0, 0.2],
    rotate: "natural",
    noise: 0.3
  });

  brush.add("sugar_grain", {
    type: "default",
    weight: 0.26,
    scatter: 0.18,
    sharpness: 0.85,
    grain: 18,
    opacity: 235,
    spacing: 0.15,
    pressure: [0.8, 1.2, 0.7],
    rotate: "random",
    noise: 0.2
  });

  background("#e1d9c6");
}

// Smooth minimum / maximum helpers for 3D marzipan sculpting
function smin(a, b, k) {
  let h = Math.max(k - Math.abs(a - b), 0.0) / k;
  return Math.min(a, b) - h * h * k * 0.25;
}

function smax(a, b, k) {
  return -smin(-a, -b, k);
}

function clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function mixNum(a, b, t) {
  return a + (b - a) * t;
}

function mixHex(c1, c2, t) {
  t = clamp01(t);
  let r1 = parseInt(c1.slice(1, 3), 16),
      g1 = parseInt(c1.slice(3, 5), 16),
      b1 = parseInt(c1.slice(5, 7), 16);
  let r2 = parseInt(c2.slice(1, 3), 16),
      g2 = parseInt(c2.slice(3, 5), 16),
      b2 = parseInt(c2.slice(5, 7), 16);
  let r = Math.round(r1 + (r2 - r1) * t);
  let g = Math.round(g1 + (g2 - g1) * t);
  let b = Math.round(b1 + (b2 - b1) * t);
  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

function ellipDist(x, y, z, rx, ry, rz) {
  let kx = x / rx, ky = y / ry, kz = z / rz;
  let k0 = Math.sqrt(kx * kx + ky * ky + kz * kz);
  if (k0 < 0.0001) return -Math.min(rx, ry, rz);
  let k1 = Math.sqrt((kx / rx) * (kx / rx) + (ky / ry) * (ky / ry) + (kz / rz) * (kz / rz));
  return (k0 * (k0 - 1.0)) / k1;
}

function capsuleDist(px, py, pz, ax, ay, az, bx, by, bz, r1, r2) {
  let pax = px - ax, pay = py - ay, paz = pz - az;
  let bax = bx - ax, bay = by - ay, baz = bz - az;
  let baba = bax * bax + bay * bay + baz * baz;
  let h = clamp01((pax * bax + pay * bay + paz * baz) / baba);
  let dx = pax - bax * h, dy = pay - bay * h, dz = paz - baz * h;
  let r = r1 + (r2 - r1) * h;
  return Math.sqrt(dx * dx + dy * dy + dz * dz) - r;
}

// Piglet configurations in 3D tabletop world coordinates
const PIGLETS = [
  {
    // Left piglet: angled front-right, showing flank, curly tail, thumbprint dimple, and snout
    id: 0,
    cx: -146, cy: -2, cz: -14,
    yaw: 42, pitch: 3, roll: 9,
    scale: 1.02,
    dimpleSide: -1
  },
  {
    // Right piglet: angled front-left, huddling close, snout slightly raised
    id: 1,
    cx: 138, cy: 8, cz: -18,
    yaw: -39, pitch: 7, roll: -8,
    scale: 1.0,
    dimpleSide: 1
  },
  {
    // Front-center piglet: nestled closest to viewer, snout facing forward
    id: 2,
    cx: -2, cy: -22, cz: 72,
    yaw: -7, pitch: -4, roll: -3,
    scale: 1.04,
    dimpleSide: -1
  }
];

// Precompute rotation matrices for each piglet
for (let p of PIGLETS) {
  let yr = (p.yaw * Math.PI) / 180;
  let pr = (p.pitch * Math.PI) / 180;
  let rr = (p.roll * Math.PI) / 180;
  p.cyaw = Math.cos(yr); p.syaw = Math.sin(yr);
  p.cpit = Math.cos(pr); p.spit = Math.sin(pr);
  p.crol = Math.cos(rr); p.srol = Math.sin(rr);
}

// Transform world point (wx, wy, wz) into piglet's local frame (u=forward, v=right, w=up)
function worldToPiglet(wx, wy, wz, p) {
  let x = (wx - p.cx) / p.scale;
  let y = (wy - p.cy) / p.scale;
  let z = (wz - p.cz) / p.scale;

  // Yaw around Y
  let x1 = x * p.cyaw - z * p.syaw;
  let z1 = x * p.syaw + z * p.cyaw;
  let y1 = y;

  // Pitch around X
  let y2 = y1 * p.cpit - z1 * p.spit;
  let z2 = y1 * p.spit + z1 * p.cpit;
  let x2 = x1;

  // Roll around Z
  let x3 = x2 * p.crol - y2 * p.srol;
  let y3 = x2 * p.srol + y2 * p.crol;
  let z3 = z2;

  // u = forward along spine (+z3), v = lateral (+x3), w = vertical (+y3)
  return { u: z3, v: x3, w: y3 };
}

// Transform local vector (du, dv, dw) back to world space
function pigletVecToWorld(du, dv, dw, p) {
  let x3 = dv, y3 = dw, z3 = du;
  let x2 = x3 * p.crol + y3 * p.srol;
  let y2 = -x3 * p.srol + y3 * p.crol;
  let z2 = z3;

  let y1 = y2 * p.cpit + z2 * p.spit;
  let z1 = -y2 * p.spit + z2 * p.cpit;
  let x1 = x2;

  let x = x1 * p.cyaw + z1 * p.syaw;
  let z = -x1 * p.syaw + z1 * p.cyaw;
  let y = y1;
  return { x, y, z };
}

// Detailed 3D SDF of a single handcrafted marzipan piglet
function evalSinglePiglet(u, v, w, p, detailed) {
  let absV = Math.abs(v);

  // 1. Plump marzipan body with subtle hand-rolled asymmetry
  let bodyW = w + 6 - (u < 0 ? 0.04 * u : 0);
  let dBody = ellipDist(u + 14, v, bodyW, 96, 74, 65);
  // Slight flattening where belly sits in the cup
  dBody = smax(dBody, -(w + 62), 14);
  // Subtle rump crease
  if (u < -75) {
    let rumpCrease = Math.exp(-((v * v) / 90)) * Math.exp(-((u + 105) * (u + 105)) / 180) * 2.5;
    dBody += rumpCrease;
  }

  // 2. Plump head
  let dHead = ellipDist(u - 70, v, w - 10, 58, 54, 51);
  let d = smin(dBody, dHead, 20);

  // Jowl / neck roll crease where head joins torso (sugar collects here)
  let neckDist = Math.abs(u - 36);
  if (neckDist < 22) {
    let neckIndent = Math.exp(-(neckDist * neckDist) / 95) * (1.8 + 1.4 * clamp01((25 - w) / 50));
    d += neckIndent;
  }

  // 3. Prominent flat-ended cylindrical snout
  let dSnoutTube = capsuleDist(u, v, w, 86, 0, 8, 137, 0, 3, 38, 30);
  // Flat snout front plane
  let snoutCap = u - 142 + 0.004 * (v * v + (w - 3) * (w - 3));
  let dSnout = smax(dSnoutTube, snoutCap, 7.5);
  d = smin(d, dSnout, 15);

  // Subtle raised marzipan rim around snout disc
  let rSnout = Math.sqrt((v / 1.12) * (v / 1.12) + (w - 3) * (w - 3));
  if (u > 125 && Math.abs(rSnout - 24.5) < 8) {
    let rimBump = Math.exp(-Math.pow(rSnout - 24.5, 2) / 14) * Math.exp(-Math.pow(u - 138, 2) / 28) * 1.6;
    d -= rimBump;
  }

  // 4. Pinched marzipan leaf-shaped ears folded slightly forward
  let eu = u - 68, ev = absV - 34, ew = w - 52;
  // Rotate ear coordinates to flare out and tilt forward
  let earU = eu * 0.82 + ew * 0.57;
  let earV = ev * 0.86 - ew * 0.51;
  let earW = -eu * 0.45 + ev * 0.38 + ew * 0.81;
  let dEar = ellipDist(earU - 8, earV - 6, earW, 24, 18, 9.5);
  // Pinched hollow inside the front of each ear
  let dEarHollow = ellipDist(earU - 10, earV - 5, earW + 6.5, 14, 10, 6);
  dEar = smax(dEar, -dEarHollow, 4.5);
  d = smin(d, dEar, 11);

  // 5. Stubby front trotters tucked forward
  let dFrontLeg = capsuleDist(u, absV, w, 46, 35, -36, 86, 31, -50, 20, 14);
  // Tiny cleft notch at trotter tip
  if (u > 78 && w < -36) {
    let cleft = Math.exp(-Math.pow(absV - 31, 2) / 8) * Math.exp(-Math.pow(u - 88, 2) / 18) * 2.4;
    dFrontLeg += cleft;
  }
  d = smin(d, dFrontLeg, 13);

  // 6. Plump hind haunches & feet
  let dHindLeg = capsuleDist(u, absV, w, -52, 46, -28, -22, 48, -48, 25, 16);
  d = smin(d, dHindLeg, 16);

  // 7. Curly marzipan tail at rump
  if (u < -85) {
    let tu = u + 107, tv = v - 4 * p.dimpleSide, tw = w - 6;
    let rTail = Math.sqrt(tv * tv + tw * tw) - 11.5;
    let dTail = Math.sqrt(tu * tu + rTail * rTail) - 6.0;
    let dTailTip = ellipDist(u + 112, v - 12 * p.dimpleSide, w + 2, 7, 7, 7);
    dTail = smin(dTail, dTailTip, 5);
    d = smin(d, dTail, 8);
  }

  // 8. Toothpick-pricked nostrils, eye sockets, mouth crease, and thumbprint dimples
  let dimpleFactor = 0;
  let orificeFactor = 0;

  // Toothpick-pricked nostrils on the flat snout face
  if (u > 124) {
    let nv = absV - 10.2;
    let nw = w - 5.5;
    let nr2 = nv * nv + nw * nw;
    let nu = u - 140.5;
    // Pushed-up paste rim around toothpick hole
    if (nr2 < 65) {
      let nr = Math.sqrt(nr2);
      let craterRim = Math.exp(-Math.pow(nr - 5.2, 2) / 4.2) * Math.exp(-(nu * nu) / 18) * 1.45;
      d -= craterRim;
      // Deep conical toothpick prick
      let dPrick = Math.sqrt(nr2 * 1.35 + (nu + 3.5) * (nu + 3.5) * 0.25) - 4.4;
      if (dPrick < 3.5) {
        orificeFactor = Math.max(orificeFactor, clamp01(1.0 - dPrick / 3.8));
      }
      d = smax(d, -dPrick, 2.2);
    }

    // Smiling mouth crease under the snout
    let mw = w + 13.5 - 0.018 * v * v;
    let mu = u - 126;
    if (absV < 20 && Math.abs(mw) < 10 && Math.abs(mu) < 12) {
      let mouthIndent = Math.exp(-(mw * mw) / 10) * Math.exp(-(mu * mu) / 28) * Math.exp(-(v * v) / 220) * 3.6;
      d += mouthIndent;
      orificeFactor = Math.max(orificeFactor, clamp01(mouthIndent / 4.0) * 0.55);
    }
  }

  // Deep toothpick/sugar-bead eyes in shallow brow sockets
  if (u > 72 && u < 118 && w > 8) {
    let eu2 = u - 96;
    let ev2 = absV - 25.5;
    let ew2 = w - 26.5;
    let er2 = eu2 * eu2 + ev2 * ev2 + ew2 * ew2;
    if (er2 < 160) {
      // Soft eye socket depression
      d += Math.exp(-er2 / 48) * 2.8;
      // Sharp toothpick eye hole
      let dEyeHole = Math.sqrt(eu2 * eu2 + ev2 * ev2 * 0.9 + ew2 * ew2) - 4.1;
      if (dEyeHole < 3.2) {
        orificeFactor = Math.max(orificeFactor, clamp01(1.1 - dEyeHole / 3.2));
      }
      d = smax(d, -dEyeHole, 1.8);
    }
  }

  // Confectioner's thumbprint dimples (flank & shoulder/brow)
  // Primary flank thumbprint
  let du1 = (u + 4) * 0.88 + (w - 14) * 0.47;
  let dw1 = -(u + 4) * 0.47 + (w - 14) * 0.88;
  let dv1 = v - p.dimpleSide * 66;
  let rDimple1 = (du1 * du1) / (27 * 27) + (dw1 * dw1) / (19 * 19) + (dv1 * dv1) / (26 * 26);
  if (rDimple1 < 2.2) {
    let df1 = Math.exp(-rDimple1 * 1.45);
    // Subtle raised rim around thumbprint edge
    let rim1 = Math.exp(-Math.pow(rDimple1 - 0.95, 2) / 0.18) * 1.1;
    d += df1 * 6.2 - rim1;
    dimpleFactor = Math.max(dimpleFactor, df1);
    if (detailed && rDimple1 < 1.15) {
      // Concentric dermatoglyphic fingerprint micro-ridges inside the thumbprint
      let ridgeDist = Math.sqrt(du1 * du1 * 0.7 + dw1 * dw1 * 1.3);
      d += Math.sin(ridgeDist * 2.35) * 0.28 * df1;
    }
  }

  // Secondary smaller thumbprint dimple on opposite cheek/shoulder or hip
  let du2 = u - 46;
  let dw2 = w - 34;
  let dv2 = v - p.dimpleSide * 32;
  let rDimple2 = (du2 * du2) / (18 * 18) + (dw2 * dw2) / (15 * 15) + (dv2 * dv2) / (20 * 20);
  if (rDimple2 < 2.0) {
    let df2 = Math.exp(-rDimple2 * 1.5);
    d += df2 * 4.2;
    dimpleFactor = Math.max(dimpleFactor, df2 * 0.85);
    if (detailed && rDimple2 < 1.1) {
      let ridgeDist2 = Math.sqrt(du2 * du2 + dw2 * dw2 * 1.4);
      d += Math.sin(ridgeDist2 * 2.5) * 0.22 * df2;
    }
  }

  // Third thumbprint dimple on upper forehead/crown (visible especially on center piglet)
  let du3 = u - 74;
  let dv3 = v + p.dimpleSide * 10;
  let dw3 = w - 52;
  let rDimple3 = (du3 * du3) / (19 * 19) + (dv3 * dv3) / (15 * 15) + (dw3 * dw3) / (16 * 16);
  if (rDimple3 < 1.8) {
    let df3 = Math.exp(-rDimple3 * 1.5);
    d += df3 * 3.8;
    dimpleFactor = Math.max(dimpleFactor, df3 * 0.75);
    if (detailed && rDimple3 < 1.0) {
      let ridgeDist3 = Math.sqrt(du3 * du3 + dv3 * dv3 * 1.3);
      d += Math.sin(ridgeDist3 * 2.4) * 0.2 * df3;
    }
  }

  // Fine almond-paste surface micro-granularity
  if (detailed) {
    let pasteGrain =
      Math.sin(u * 0.37 + v * 0.29) *
      Math.cos(v * 0.41 - w * 0.33) *
      Math.sin(w * 0.39 + u * 0.23);
    d += pasteGrain * 0.22;
  }

  return {
    d: d * p.scale,
    u, v, w,
    dimpleFactor,
    orificeFactor
  };
}

// Scene SDF evaluating all 3 piglets and tracking soft huddling proximity
function evalScene(wx, wy, wz, detailed) {
  let bestD = 1e9;
  let secondD = 1e9;
  let bestPig = null;
  let bestRes = null;

  for (let i = 0; i < 3; i++) {
    let p = PIGLETS[i];
    // Fast bounding sphere check (radius ~ 170)
    let dx = wx - p.cx, dy = wy - p.cy, dz = wz - p.cz;
    let distSq = dx * dx + dy * dy + dz * dz;
    if (distSq > 210 * 210) {
      let approxD = Math.sqrt(distSq) - 155;
      if (approxD < bestD) {
        secondD = bestD;
        bestD = approxD;
      } else if (approxD < secondD) {
        secondD = approxD;
      }
      continue;
    }

    let loc = worldToPiglet(wx, wy, wz, p);
    let res = evalSinglePiglet(loc.u, loc.v, loc.w, p, detailed);
    if (res.d < bestD) {
      secondD = bestD;
      bestD = res.d;
      bestPig = p;
      bestRes = res;
    } else if (res.d < secondD) {
      secondD = res.d;
    }
  }

  // Soft compression crease where piglets press against each other
  let huddleProximity = clamp01(1.0 - (secondD - bestD) / 38.0);
  return {
    d: bestD,
    pig: bestPig,
    res: bestRes,
    huddleProximity
  };
}

function calcNormal(wx, wy, wz) {
  let e = 0.65;
  let dx = evalScene(wx + e, wy, wz, true).d - evalScene(wx - e, wy, wz, true).d;
  let dy = evalScene(wx, wy + e, wz, true).d - evalScene(wx, wy - e, wz, true).d;
  let dz = evalScene(wx, wy, wz + e, true).d - evalScene(wx, wy, wz - e, true).d;
  let len = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1;
  return { nx: dx / len, ny: dy / len, nz: dz / len };
}

// Compute the marzipan colour (shell pink, almond cream, carmine blush, cool shadow)
function shadeMarzipanPoint(cell) {
  let { u, v, w, nx, ny, nz, dimple, orifice, huddle, pigId, wy } = cell;

  // Carmine blush: concentrated at snout disc, around nostrils, mouth, ear tips, and subtle cheek blush
  let snoutBlush = clamp01((u - 98) / 44) * Math.exp(-((w - 4) * (w - 4)) / 950);
  let nostrilRimBlush = Math.exp(-((u - 140) * (u - 140) + (Math.abs(v) - 10) * (Math.abs(v) - 10) + (w - 6) * (w - 6)) / 120);
  let earTipBlush = clamp01((w - 42) / 32) * clamp01((u - 50) / 45) * 0.68;
  let cheekBlush = Math.exp(-((u - 78) * (u - 78)) / 420) * Math.exp(-((Math.abs(v) - 42) * (Math.abs(v) - 42)) / 240) * 0.48;
  let tailBlush = clamp01((-u - 92) / 28) * 0.42;
  let carmine = clamp01(snoutBlush * 0.92 + nostrilRimBlush * 0.55 + earTipBlush + cheekBlush + tailBlush);

  // Shell pink vs Almond cream distribution:
  // Upper backs, bellies, brow bridges, and flanks blend shell pink with warm-cool almond paste cream
  let nVar = noise(u * 0.025 + pigId * 10, v * 0.025, w * 0.025);
  let pinkWeight = clamp01(0.48 + 0.35 * clamp01((u + 20) / 130) + 0.25 * (nVar - 0.5) + dimple * 0.22);

  // Base local paste colour
  let almondCream = "#efe5d2";
  let shellPink = "#f3cbd3";
  let carmineBlush = "#c84663";
  let deepCarmine = "#9b2441";

  let baseCol = mixHex(almondCream, shellPink, pinkWeight);
  if (carmine > 0.01) {
    let cCol = mixHex(carmineBlush, deepCarmine, clamp01((carmine - 0.55) * 1.8));
    baseCol = mixHex(baseCol, cCol, carmine * 0.85);
  }

  // Diffuse warm overhead/top-left lighting with no hard shadows
  let lx = -0.34, ly = 0.76, lz = 0.55;
  let ndotl = nx * lx + ny * ly + nz * lz;
  // Wrap lighting for translucent waxy marzipan subsurface scatter
  let diff = clamp01((ndotl + 0.55) / 1.55);

  // Ambient occlusion in huddling crevices, neck folds, dimples, and bottom cup contact
  let neckCreaseAO = Math.exp(-((u - 36) * (u - 36)) / 90) * 0.25;
  let bottomCupAO = clamp01((-wy - 22) / 55) * 0.38;
  let ao = clamp01(1.0 - huddle * 0.42 - dimple * 0.26 - neckCreaseAO - bottomCupAO);

  // Subsurface warm pink-amber glow in compressed creases between piglets
  if (huddle > 0.08 || dimple > 0.1) {
    let sssCol = "#d97a8e";
    baseCol = mixHex(baseCol, sssCol, clamp01(huddle * 0.35 + dimple * 0.22));
  }

  // Cool shadow toning (cool lavender-taupe and sage-reflected bounce light)
  let shadowFactor = clamp01((1.0 - diff * 0.78) * (1.25 - ao * 0.55));
  let coolShadow = mixHex("#b7a1aa", "#8e7984", clamp01(shadowFactor * 1.2));
  // Subtle cool pistachio bounce light on outer flanks facing background
  let pistachioBounce = clamp01((Math.abs(nx) * 0.6 + (ny < 0 ? -ny * 0.4 : 0)) * (1.0 - huddle));
  if (pistachioBounce > 0.15) {
    coolShadow = mixHex(coolShadow, "#a8b8ae", pistachioBounce * 0.32);
  }

  let shadedCol = mixHex(baseCol, coolShadow, shadowFactor * 0.68);

  // Warm diffuse top light and matte, slightly greasy almond-oil sheen
  let hx = -0.18, hy = 0.62, hz = 0.76;
  let ndoth = clamp01(nx * hx + ny * hy + nz * hz);
  // Broad satin-greasy sheen on snout rim, forehead, rump crown, and thumbprint rims
  let greasySheen = Math.pow(ndoth, 5.5) * 0.52 + Math.pow(ndoth, 16) * 0.28;
  let warmLightCol = mixHex("#f9f3e6", "#ffffff", clamp01(greasySheen * 1.4));
  shadedCol = mixHex(shadedCol, warmLightCol, clamp01(diff * 0.28 + greasySheen * ao));

  // Deep toothpick-pricked nostrils & eyes
  if (orifice > 0.05) {
    let isEye = u < 116 && w > 12;
    let holeCol = isEye
      ? mixHex("#5a2736", "#230e16", clamp01(orifice * 1.35))
      : mixHex("#8f243e", "#380d1a", clamp01(orifice * 1.25));
    shadedCol = mixHex(shadedCol, holeCol, clamp01(orifice * 1.15));
  }

  return {
    col: shadedCol,
    carmine,
    diff,
    ao,
    greasySheen
  };
}

// Generate the 3D geometry of the crinkled glassine bonbon cup
function buildGlassineCup() {
  let cx = 600;
  let baseCy = 768, baseRx = 310, baseRy = 88;
  let rimCy = 676, rimRx = 468, rimRy = 148;
  let numPleats = 40; // 80 alternating ridge/valley vertices
  let totalV = numPleats * 2;
  let pts = [];

  for (let i = 0; i <= totalV; i++) {
    let idx = i % totalV;
    let ang = (idx / totalV) * 360;
    let rad = (ang * Math.PI) / 180;
    let isPeak = idx % 2 === 0;

    // Front pleats splay outward & downward slightly under the piglets' weight
    let frontness = clamp01((Math.sin(rad) + 0.15) / 1.15);
    let crinkleN = noise(idx * 0.42, 12.3) - 0.5;
    let crinkleM = noise(idx * 0.71, 45.7) - 0.5;

    let rRimMult = (isPeak ? 1.035 : 0.915) + crinkleN * 0.045 + frontness * (isPeak ? 0.04 : 0.015);
    let rMidMult = (isPeak ? 0.985 : 0.895) + crinkleM * 0.04;
    let rBaseMult = (isPeak ? 0.96 : 0.91) + crinkleN * 0.02;

    let angJitter = (noise(idx * 0.9, 8.1) - 0.5) * 1.8;
    let aRad = ((ang + angJitter) * Math.PI) / 180;

    let bx = cx + Math.cos(aRad) * baseRx * rBaseMult;
    let by = baseCy + Math.sin(aRad) * baseRy * rBaseMult;

    let frontDip = frontness * (28 + (isPeak ? 14 : 4) + crinkleM * 16);
    let rx = cx + Math.cos(aRad) * rimRx * rRimMult;
    let ry = rimCy + Math.sin(aRad) * rimRy * rRimMult + frontDip;

    // Mid-wall crinkle vertex where the glassine paper buckles slightly
    let mx = mixNum(bx, rx, 0.54) + (isPeak ? 4 : -4) * Math.cos(aRad) + crinkleM * 9;
    let my = mixNum(by, ry, 0.54) + frontness * 8 + crinkleN * 7;

    pts.push({
      idx,
      ang,
      isPeak,
      frontness,
      bx, by,
      mx, my,
      rx, ry,
      crinkleN,
      crinkleM
    });
  }
  return pts;
}

// Render a section of the crinkled glassine bonbon cup (either back wall or front overlapping wall)
function drawGlassineSection(cupPts, isFront) {
  let totalPanels = cupPts.length - 1;

  // 1. Translucent paper facet washes
  brush.noStroke();
  for (let i = 0; i < totalPanels; i++) {
    let p0 = cupPts[i];
    let p1 = cupPts[i + 1];
    let midAng = ((p0.ang + p1.ang) * 0.5) % 360;
    let panelInFront = midAng >= 2 && midAng <= 178;
    if (panelInFront !== isFront) continue;

    // Alternating pleat orientation determines light reflection vs translucent shadow
    let facingLeft = p0.isPeak;
    let nx = p1.ry - p0.ry;
    let lightAmt = clamp01(0.5 + (facingLeft ? 0.28 : -0.24) + (nx * 0.008) + p0.crinkleN * 0.15);

    // Subtle warm-pink marzipan glow transmitted through the middle of the cup wall
    let pinkTransmit = isFront
      ? clamp01(1.0 - Math.abs(midAng - 90) / 72) * 0.35
      : clamp01(1.0 - Math.abs(midAng - 270) / 75) * 0.18;

    let shadowTone = mixHex("#a8b7b8", "#cbb6b9", pinkTransmit);
    let midTone = mixHex("#dce3e2", "#e8dcd8", pinkTransmit * 0.7);
    let highTone = "#f6f9f9";

    let upperCol = lightAmt > 0.52
      ? mixHex(midTone, highTone, (lightAmt - 0.52) * 2.0)
      : mixHex(shadowTone, midTone, lightAmt * 1.9);

    let lowerCol = mixHex(shadowTone, midTone, clamp01(lightAmt * 1.4));

    brush.fillBleed(0.06, "in");
    brush.fillTexture(0.28, 0.18);

    // Upper facet of pleat (rim to mid-buckle)
    brush.fill(upperCol, isFront ? (lightAmt > 0.55 ? 135 : 108) : 145);
    brush.beginShape(0.05);
    brush.vertex(p0.rx, p0.ry);
    brush.vertex(p1.rx, p1.ry);
    brush.vertex(p1.mx, p1.my);
    brush.vertex(p0.mx, p0.my);
    brush.endShape(true);

    // Lower facet of pleat (mid-buckle to base)
    brush.fill(lowerCol, isFront ? 120 : 155);
    brush.beginShape(0.05);
    brush.vertex(p0.mx, p0.my);
    brush.vertex(p1.mx, p1.my);
    brush.vertex(p1.bx, p1.by);
    brush.vertex(p0.bx, p0.by);
    brush.endShape(true);
  }
  brush.noFill();

  // 2. Burnished coloured pencil shading & crisp crinkle folds on each pleat
  for (let i = 0; i < totalPanels; i++) {
    let p0 = cupPts[i];
    let p1 = cupPts[i + 1];
    let midAng = ((p0.ang + p1.ang) * 0.5) % 360;
    let panelInFront = midAng >= 2 && midAng <= 178;
    if (panelInFront !== isFront) continue;

    let facingLeft = p0.isPeak;
    let lightAmt = clamp01(0.5 + (facingLeft ? 0.3 : -0.25) + p0.crinkleN * 0.15);
    let pinkTransmit = isFront ? clamp01(1.0 - Math.abs(midAng - 90) / 72) * 0.32 : 0.1;

    let facetCol = lightAmt > 0.52
      ? mixHex("#e5ecec", "#ffffff", (lightAmt - 0.52) * 2.0)
      : mixHex(mixHex("#96a7a9", "#bfa9ad", pinkTransmit), "#d6dede", lightAmt * 1.9);

    // Fine longitudinal coloured pencil strokes along the accordion pleat
    let steps = isFront ? 9 : 6;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let rx = mixNum(p0.rx, p1.rx, t);
      let ry = mixNum(p0.ry, p1.ry, t);
      let mx = mixNum(p0.mx, p1.mx, t);
      let my = mixNum(p0.my, p1.my, t);
      let bx = mixNum(p0.bx, p1.bx, t);
      let by = mixNum(p0.by, p1.by, t);

      brush.set("prismacolor_soft", facetCol, isFront ? 0.65 : 0.55);
      brush.line(rx, ry, mx, my);
      let lowerStrokeCol = mixHex(facetCol, "#98a8aa", 0.25);
      brush.set("prismacolor_soft", lowerStrokeCol, isFront ? 0.6 : 0.5);
      brush.line(mx, my, bx, by);
    }

    // Diagonal crinkle buckle creases across the pleat
    let crinkleCol = facingLeft ? "#ffffff" : "#899b9e";
    brush.set("polychromos_fine", crinkleCol, 0.52);
    brush.line(p0.mx, p0.my, p1.rx * 0.35 + p1.mx * 0.65, p1.ry * 0.35 + p1.my * 0.65);
    brush.line(p0.mx, p0.my, p1.mx, p1.my);
    if (random() < 0.7) {
      let kCol = facingLeft ? "#97a8ab" : "#f7fafa";
      brush.set("polychromos_fine", kCol, 0.42);
      brush.line(
        mixNum(p0.rx, p0.mx, 0.45),
        mixNum(p0.ry, p0.my, 0.45),
        mixNum(p1.rx, p1.mx, 0.72),
        mixNum(p1.ry, p1.my, 0.72)
      );
    }

    // Crisp accordion fold ridge & valley lines
    if (p0.isPeak) {
      // Sharp white/ice-blue burnished ridge highlight
      brush.set("polychromos_fine", "#ffffff", isFront ? 0.78 : 0.62);
      brush.line(p0.rx, p0.ry, p0.mx, p0.my);
      brush.set("polychromos_fine", "#edf4f5", isFront ? 0.65 : 0.5);
      brush.line(p0.mx, p0.my, p0.bx, p0.by);
    } else {
      // Crisp cool grey-sage valley crease
      let valleyCol = mixHex("#7f9195", "#a99297", pinkTransmit);
      brush.set("polychromos_fine", valleyCol, isFront ? 0.62 : 0.5);
      brush.line(p0.rx, p0.ry, p0.mx, p0.my);
      brush.line(p0.mx, p0.my, p0.bx, p0.by);
    }

    // Rim edge crinkle highlight and shadow double-line
    brush.set("polychromos_fine", "#ffffff", isFront ? 0.85 : 0.65);
    brush.line(p0.rx, p0.ry, p1.rx, p1.ry);
    brush.set("polychromos_fine", "#8da0a3", isFront ? 0.45 : 0.38);
    brush.line(p0.rx, p0.ry + 2.2, p1.rx, p1.ry + 2.2);
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. TONED BUFF PAPER & SOFT UNFOCUSED PISTACHIO GREEN BACKGROUND
  // =========================================================================
  brush.noStroke();
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.38, 0.14);

  // Soft unfocused pistachio green washes in the upper background (y: 0..680)
  const bgWasheBands = [
    { y: -40, h: 210, col: "#85a392", op: 95 },
    { y: 110, h: 220, col: "#96b3a2", op: 92 },
    { y: 250, h: 220, col: "#a7c2b1", op: 88 },
    { y: 390, h: 210, col: "#bbd1c2", op: 82 },
    { y: 510, h: 170, col: "#ceddd1", op: 72 },
    // Tabletop plane (cool toned buff & pale sage-alabaster)
    { y: 640, h: 220, col: "#dad7c9", op: 65 },
    { y: 810, h: 240, col: "#d1cfc2", op: 75 },
    { y: 990, h: 250, col: "#c4c4b8", op: 85 }
  ];

  for (let b of bgWasheBands) {
    brush.fill(b.col, b.op);
    brush.rect(-40, b.y, 1280, b.h, "corner");
  }

  // Soft out-of-focus pistachio bokeh & diffuse light clouds behind the piglets
  const bokehClouds = [
    { x: 600, y: 470, r: 390, col: "#dfeae0", op: 70 },
    { x: 310, y: 260, r: 310, col: "#8ba998", op: 58 },
    { x: 920, y: 230, r: 340, col: "#7e9d8c", op: 62 },
    { x: 180, y: 520, r: 260, col: "#acc5b6", op: 55 },
    { x: 1020, y: 510, r: 280, col: "#9fb9a9", op: 55 },
    // Diffuse tabletop shadow beneath the bonbon cup
    { x: 605, y: 815, r: 440, col: "#9ea9a0", op: 62 },
    { x: 600, y: 795, r: 330, col: "#88948b", op: 68 }
  ];

  for (let c of bokehClouds) {
    brush.fill(c.col, c.op);
    brush.circle(c.x, c.y, c.r, 0.35);
  }
  brush.noFill();

  // Burnished coloured pencil grain across the unfocused pistachio background & tabletop
  for (let i = 0; i < 1100; i++) {
    let x = random(-30, 1230);
    let y = random(-20, 1220);
    let n = noise(x * 0.003, y * 0.003);
    let len = random(45, 115);
    let ang = (n - 0.5) * 14 + (y > 630 ? random(-3, 3) : random(-8, 8));
    let dx = Math.cos((ang * Math.PI) / 180) * len * 0.5;
    let dy = Math.sin((ang * Math.PI) / 180) * len * 0.5;

    let col;
    if (y < 610) {
      let t = clamp01(y / 610);
      let c1 = mixHex("#7f9f8d", "#b5cbbd", t);
      let c2 = mixHex("#9ab7a6", "#dce5dc", t);
      col = mixHex(c1, c2, n);
    } else {
      let t = clamp01((y - 610) / 590);
      // Check if inside soft shadow under cup
      let cupDist = Math.pow((x - 600) / 470, 2) + Math.pow((y - 795) / 145, 2);
      if (cupDist < 1.15) {
        col = mixHex("#839188", "#b4beb5", clamp01(cupDist));
      } else {
        let c1 = mixHex("#d7d6c8", "#bfc1b5", t);
        let c2 = mixHex("#e7e2d3", "#d2d0c3", t);
        col = mixHex(c1, c2, n);
      }
    }

    brush.set(i % 3 === 0 ? "cpencil" : "prismacolor_soft", col, random(0.55, 1.05));
    brush.line(x - dx, y - dy, x + dx, y + dy);
  }

  // =========================================================================
  // 2. BACK WALL & INTERIOR FLOOR OF THE CRINKLED GLASSINE BONBON CUP
  // =========================================================================
  const cupPts = buildGlassineCup();

  // Soft contact shadow directly under the crinkled cup base
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fill("#748179", 85);
  brush.beginShape(0.2);
  for (let i = 0; i < cupPts.length; i += 2) {
    let p = cupPts[i];
    brush.vertex(p.bx + 4, p.by + 16);
  }
  brush.endShape(true);

  // Cup interior base floor
  brush.fillBleed(0.12, "in");
  brush.fill("#d4ccc0", 165);
  brush.beginShape(0.15);
  for (let i = 0; i < cupPts.length; i += 2) {
    let p = cupPts[i];
    brush.vertex(p.bx, p.by);
  }
  brush.endShape(true);
  brush.noFill();

  // Draw the back half of the pleated glassine cup (behind the piglets)
  drawGlassineSection(cupPts, false);

  // =========================================================================
  // 3. RAYMARCH & SAMPLE THE THREE 3D MARZIPAN PIGLETS
  // =========================================================================
  // Screen bounding box for the 3 piglets: x in [170, 1030], y in [360, 820]
  const xMin = 170, xMax = 1030;
  const yMin = 360, yMax = 820;
  const step = 3; // 3px high-density sampling grid
  const cols = Math.floor((xMax - xMin) / step);
  const rows = Math.floor((yMax - yMin) / step);
  const grid = new Array(cols * rows).fill(null);
  const hitCells = [];

  // Camera setup: tabletop perspective looking down at 15.5 degrees
  const camPitch = (15.5 * Math.PI) / 180;
  const cosCam = Math.cos(camPitch), sinCam = Math.sin(camPitch);
  const screenCx = 600, screenCy = 638;
  const focal = 1750;

  for (let r = 0; r < rows; r++) {
    let sy = yMin + r * step;
    for (let c = 0; c < cols; c++) {
      let sx = xMin + c * step;

      // Construct camera ray in world coordinates
      let rxCam = (sx - screenCx) / focal;
      let ryCam = -(sy - screenCy) / focal;
      let rzCam = -1.0;
      let rLen = Math.sqrt(rxCam * rxCam + ryCam * ryCam + rzCam * rzCam);
      rxCam /= rLen; ryCam /= rLen; rzCam /= rLen;

      // Rotate ray by tabletop camera pitch
      let rdx = rxCam;
      let rdy = ryCam * cosCam - rzCam * sinCam;
      let rdz = ryCam * sinCam + rzCam * cosCam;

      // Camera origin at distance 1750 along +camZ
      let rox = 0;
      let roy = 1750 * sinCam;
      let roz = 1750 * cosCam;

      // Raymarch interval where piglets reside (t in [1480, 1980])
      let t = 1480;
      let hit = false;
      let lastEval = null;
      for (let iter = 0; iter < 26; iter++) {
        let wx = rox + rdx * t;
        let wy = roy + rdy * t;
        let wz = roz + rdz * t;
        let ev = evalScene(wx, wy, wz, false);
        if (ev.d < 0.75) {
          hit = true;
          // Refine hit with detailed surface grain & fingerprint ridges
          lastEval = evalScene(wx, wy, wz, true);
          break;
        }
        t += Math.max(ev.d * 0.88, 1.2);
        if (t > 1980) break;
      }

      if (hit && lastEval && lastEval.pig) {
        let wx = rox + rdx * t;
        let wy = roy + rdy * t;
        let wz = roz + rdz * t;
        let nrm = calcNormal(wx, wy, wz);
        let p = lastEval.pig;
        let res = lastEval.res;

        // Compute 3D cross-contour tangent vector for form-following pencil strokes
        // Local spine direction (1, 0, 0) in world space:
        let spineW = pigletVecToWorld(1, 0, 0, p);
        // Cross product of surface normal and spine gives cross-contour tangent!
        let tx = nrm.ny * spineW.z - nrm.nz * spineW.y;
        let ty = nrm.nz * spineW.x - nrm.nx * spineW.z;
        let tz = nrm.nx * spineW.y - nrm.ny * spineW.x;
        // Project tangent onto screen plane
        let stx = tx;
        let sty = -(ty * cosCam + tz * sinCam);
        let stLen = Math.sqrt(stx * stx + sty * sty) || 1;
        stx /= stLen; sty /= stLen;

        let cell = {
          c, r,
          sx, sy,
          wx, wy, wz,
          pigId: p.id,
          u: res.u, v: res.v, w: res.w,
          nx: nrm.nx, ny: nrm.ny, nz: nrm.nz,
          stx, sty,
          dimple: res.dimpleFactor,
          orifice: res.orificeFactor,
          huddle: lastEval.huddleProximity
        };

        let shaded = shadeMarzipanPoint(cell);
        cell.col = shaded.col;
        cell.carmine = shaded.carmine;
        cell.diff = shaded.diff;
        cell.ao = shaded.ao;
        cell.greasySheen = shaded.greasySheen;

        // Icing-sugar accumulation factor: settles in neck creases, huddling valleys,
        // thumbprint dimples, upper backs/heads, and around ear folds
        let neckSugar = Math.exp(-((res.u - 36) * (res.u - 36)) / 85) * 0.78;
        let earCreaseSugar = Math.exp(-((res.u - 62) * (res.u - 62)) / 90) * clamp01((res.w - 30) / 28) * 0.65;
        let topCrownSugar = clamp01(nrm.ny - 0.15) * 0.42;
        cell.sugar = clamp01(
          neckSugar +
          earCreaseSugar +
          cell.huddle * 0.82 +
          cell.dimple * 0.72 +
          topCrownSugar * (0.4 + 0.6 * noise(sx * 0.018, sy * 0.018))
        );

        grid[r * cols + c] = cell;
        hitCells.push(cell);
      }
    }
  }

  // Soft shadow cast by the three piglets onto the interior of the glassine cup
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  for (let p of PIGLETS) {
    let sx = screenCx + p.cx * 0.96;
    let sy = screenCy - (p.cy * cosCam + p.cz * sinCam) + 52;
    brush.fill("#9c8d8f", 75);
    brush.circle(sx, sy, 128, 0.25);
  }
  brush.noFill();

  // =========================================================================
  // 4. UNDERPAINTING THE MARZIPAN PIGLETS (SOFT TRANSLUCENT WASHES)
  // =========================================================================
  brush.noStroke();
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.32, 0.12);

  // Batch soft tonal patches across the piglet forms so the buff paper is sealed with warm/cool pastel glow
  const patchStep = 5;
  for (let r = 0; r < rows - patchStep; r += patchStep) {
    for (let c = 0; c < cols - patchStep; c += patchStep) {
      let cell = grid[(r + 2) * cols + (c + 2)];
      if (!cell) continue;
      let x0 = xMin + c * step - 4;
      let y0 = yMin + r * step - 4;
      let w0 = patchStep * step + 8;
      brush.fill(cell.col, 130);
      brush.rect(x0, y0, w0, w0, "corner");
    }
  }
  brush.noFill();

  // =========================================================================
  // 5. DENSE BURNISHED COLOURED PENCIL LAYERING ON THE THREE PIGLETS
  // =========================================================================
  // Pass A: Broad waxy coloured-pencil burnishing along 3D cross-contours
  for (let i = 0; i < hitCells.length; i++) {
    let cell = hitCells[i];
    if ((cell.c + cell.r) % 2 !== 0) continue;

    let jitterX = random(-1.8, 1.8);
    let jitterY = random(-1.8, 1.8);
    let sx = cell.sx + jitterX;
    let sy = cell.sy + jitterY;

    // Cross-contour stroke direction
    let len = random(11, 21);
    let dx = cell.stx * len * 0.5;
    let dy = cell.sty * len * 0.5;

    // Slight tonal weave for authentic burnished coloured-pencil richness
    let strokeCol = cell.col;
    let rnd = random();
    if (rnd < 0.28) {
      strokeCol = mixHex(strokeCol, "#f6efe0", 0.22); // Almond cream weave
    } else if (rnd < 0.52) {
      strokeCol = mixHex(strokeCol, "#f2c6d0", 0.22); // Shell pink weave
    } else if (cell.carmine > 0.2 && rnd < 0.78) {
      strokeCol = mixHex(strokeCol, "#c43b59", 0.28); // Carmine blush weave
    }

    brush.set("prismacolor_soft", strokeCol, random(0.62, 0.95));
    brush.line(sx - dx, sy - dy, sx + dx, sy + dy);
  }

  // Pass B: Orthogonal longitudinal burnishing & slightly greasy marzipan sheen
  for (let i = 0; i < hitCells.length; i++) {
    let cell = hitCells[i];
    if ((cell.c * 3 + cell.r) % 3 !== 0) continue;

    let sx = cell.sx + random(-1.4, 1.4);
    let sy = cell.sy + random(-1.4, 1.4);

    // Longitudinal direction (perpendicular to cross-contour)
    let ltx = -cell.sty;
    let lty = cell.stx;
    let len = random(8, 15);
    let dx = ltx * len * 0.5;
    let dy = lty * len * 0.5;

    let col = cell.col;
    if (cell.greasySheen > 0.14 && cell.ao > 0.65) {
      col = mixHex(col, "#fffdf8", clamp01(cell.greasySheen * 1.35));
    }

    brush.set("cpencil", col, random(0.45, 0.75));
    brush.line(sx - dx, sy - dy, sx + dx, sy + dy);
  }

  // Pass C: Ultra-fine polychromos detailing — thumbprint fingerprint ridges,
  // carmine snout stippling, toothpick-pricked nostrils & eyes, and silhouette edges
  for (let i = 0; i < hitCells.length; i++) {
    let cell = hitCells[i];

    // 1. Concentric fingerprint ridges inside thumbprint dimples
    if (cell.dimple > 0.18) {
      let len = random(6, 11);
      let dx = cell.stx * len * 0.5;
      let dy = cell.sty * len * 0.5;
      let ridgePhase = Math.sin(cell.u * 1.6 + cell.w * 1.9);
      let ridgeCol = ridgePhase > 0
        ? mixHex(cell.col, "#faf3e8", 0.35) // Greasy ridge crest
        : mixHex(cell.col, "#987c87", 0.38); // Dimple furrow shadow
      brush.set("polychromos_fine", ridgeCol, 0.52);
      brush.line(cell.sx - dx, cell.sy - dy, cell.sx + dx, cell.sy + dy);
    }

    // 2. Carmine blush micro-hatching on snouts, nostrils, and ear tips
    if (cell.carmine > 0.22 && random() < 0.65) {
      let ang = random(0, 360);
      let len = random(4.5, 9.5);
      let dx = Math.cos((ang * Math.PI) / 180) * len * 0.5;
      let dy = Math.sin((ang * Math.PI) / 180) * len * 0.5;
      let blushCol = mixHex("#d65c76", "#9e203d", clamp01(cell.carmine * 1.1));
      brush.set("polychromos_fine", blushCol, random(0.38, 0.62));
      brush.line(cell.sx - dx, cell.sy - dy, cell.sx + dx, cell.sy + dy);
    }

    // 3. Toothpick-pricked nostrils, eyes & smiling mouth crease
    if (cell.orifice > 0.08) {
      let isEye = cell.u < 116 && cell.w > 12;
      let holeCol = isEye
        ? mixHex("#451a27", "#1c0910", clamp01(cell.orifice * 1.4))
        : mixHex("#7c1b33", "#2b0812", clamp01(cell.orifice * 1.3));
      brush.set("polychromos_fine", holeCol, random(0.55, 0.85));
      let len = random(3, 6.5);
      brush.line(cell.sx - len * 0.4, cell.sy - len * 0.3, cell.sx + len * 0.4, cell.sy + len * 0.3);

      // Tiny greasy specular highlight on the pushed-up marzipan rim right outside the prick hole
      if (cell.orifice > 0.12 && cell.orifice < 0.38 && cell.ny > -0.1) {
        brush.set("polychromos_fine", "#fff9f5", 0.58);
        brush.line(cell.sx - 2, cell.sy - 1.5, cell.sx + 2, cell.sy - 0.5);
      }
    }

    // 4. Huddling crevices & form-defining edge contours
    let isEdge =
      cell.c > 0 && cell.c < cols - 1 && cell.r > 0 && cell.r < rows - 1 &&
      (!grid[cell.r * cols + (cell.c - 1)] ||
       !grid[cell.r * cols + (cell.c + 1)] ||
       !grid[(cell.r - 1) * cols + cell.c] ||
       !grid[(cell.r + 1) * cols + cell.c] ||
       grid[cell.r * cols + (cell.c + 1)].pigId !== cell.pigId ||
       grid[(cell.r + 1) * cols + cell.c].pigId !== cell.pigId);

    if (isEdge) {
      let rimLight = cell.ny > 0.15;
      let edgeCol = rimLight
        ? mixHex(cell.col, "#fffdf7", 0.45)
        : mixHex(cell.col, "#7d646f", 0.52);
      brush.set("polychromos_fine", edgeCol, 0.58);
      brush.line(
        cell.sx - cell.sty * 4,
        cell.sy + cell.stx * 4,
        cell.sx + cell.sty * 4,
        cell.sy - cell.stx * 4
      );
    }
  }

  // =========================================================================
  // 6. FRONT OVERLAPPING PLEATS OF THE CRINKLED GLASSINE BONBON CUP
  // =========================================================================
  drawGlassineSection(cupPts, true);

  // =========================================================================
  // 7. FAINT SPRAYED ICING-SUGAR DUST & VISIBLE INDIVIDUAL SUGAR GRAINS
  // =========================================================================
  // A. Soft sprayed icing-sugar dust settling in the creases, dimples, and cup folds
  for (let i = 0; i < hitCells.length; i++) {
    let cell = hitCells[i];
    if (cell.sugar > 0.42 && random() < cell.sugar * 0.28) {
      let sprayCol = random() < 0.7 ? "#ffffff" : "#eef4f6";
      brush.set("spray", sprayCol, random(0.35, 0.72));
      brush.line(
        cell.sx + random(-4, 4),
        cell.sy + random(-3, 3),
        cell.sx + random(-4, 4) + 1.5,
        cell.sy + random(-3, 3) + 1.5
      );
    }
  }

  // Sprayed sugar dust in the crinkled valleys of the front glassine cup
  for (let i = 0; i < cupPts.length - 1; i++) {
    let p = cupPts[i];
    if (!p.isPeak && p.frontness > 0.2) {
      for (let k = 0; k < 4; k++) {
        let t = random(0.15, 0.92);
        let sx = mixNum(p.rx, p.bx, t) + random(-6, 6);
        let sy = mixNum(p.ry, p.by, t) + random(-4, 4);
        brush.set("spray", "#ffffff", random(0.35, 0.65));
        brush.line(sx, sy, sx + 2, sy + 1);
      }
    }
  }

  // B. Every grain of sugar visible: thousands of crisp crystalline sugar flecks
  // 1) Concentrated in piglet creases (neck folds, between huddled bodies, thumbprint dimples, snouts)
  for (let i = 0; i < hitCells.length; i++) {
    let cell = hitCells[i];
    let prob = Math.pow(cell.sugar, 1.65) * 0.48 + 0.018;
    if (random() < prob) {
      let gx = cell.sx + random(-2.2, 2.2);
      let gy = cell.sy + random(-2.2, 2.2);
      let gLen = random(1.1, 2.6);
      let gAng = random(0, 180);
      let dx = Math.cos((gAng * Math.PI) / 180) * gLen * 0.5;
      let dy = Math.sin((gAng * Math.PI) / 180) * gLen * 0.5;

      // Tiny cool-shadowed underside of larger sugar crystals for hyperreal relief
      if (gLen > 1.85 && random() < 0.55) {
        brush.set("polychromos_fine", "#b4bfc4", 0.35);
        brush.line(gx - dx, gy - dy + 1.1, gx + dx, gy + dy + 1.1);
      }

      let grainCol = random() < 0.78 ? "#ffffff" : (random() < 0.5 ? "#f4f9fa" : "#faf5eb");
      brush.set("sugar_grain", grainCol, random(0.42, 0.88));
      brush.line(gx - dx, gy - dy, gx + dx, gy + dy);
    }
  }

  // 2) Sugar grains settled in the crinkled glassine pleats and scattered on the tabletop
  for (let i = 0; i < 950; i++) {
    let gx, gy;
    if (i < 550) {
      // Settled in the glassine cup folds & rim
      let p = cupPts[Math.floor(random(cupPts.length))];
      let t = random(0.05, 0.95);
      gx = mixNum(p.rx, p.bx, t) + random(-14, 14);
      gy = mixNum(p.ry, p.by, t) + random(-8, 8);
    } else {
      // Dusted across the foreground tabletop around the bonbon cup
      let ang = random(5, 175) * (Math.PI / 180);
      let radX = random(310, 560);
      let radY = random(110, 250);
      gx = 600 + Math.cos(ang) * radX + random(-35, 35);
      gy = 745 + Math.sin(ang) * radY + random(-20, 45);
    }

    let gLen = random(1.2, 2.8);
    let gAng = random(0, 180);
    let dx = Math.cos((gAng * Math.PI) / 180) * gLen * 0.5;
    let dy = Math.sin((gAng * Math.PI) / 180) * gLen * 0.5;

    if (gLen > 1.9) {
      brush.set("polychromos_fine", "#9faab0", 0.34);
      brush.line(gx - dx, gy - dy + 1.2, gx + dx, gy + dy + 1.2);
    }
    let grainCol = random() < 0.8 ? "#ffffff" : "#eef5f7";
    brush.set("sugar_grain", grainCol, random(0.45, 0.85));
    brush.line(gx - dx, gy - dy, gx + dx, gy + dy);
  }

  noLoop();
}

