// Piecewise-triangular barycentric interpolation across a crumpled grid
// Guarantees graphics & text fold sharply across exact facet creases
function projectGrid(grid, u, v, diagFlip = false) {
  let rows = grid.length - 1;
  let cols = grid[0].length - 1;
  let cu = constrain(u, 0, 1) * cols;
  let cv = constrain(v, 0, 1) * rows;
  let ci = min(floor(cu), cols - 1);
  let ri = min(floor(cv), rows - 1);
  let lu = cu - ci;
  let lv = cv - ri;

  let p00 = grid[ri][ci];
  let p10 = grid[ri][ci + 1];
  let p01 = grid[ri + 1][ci];
  let p11 = grid[ri + 1][ci + 1];

  // Alternate diagonal split to match our physical crease triangulation
  let splitA = ((ci + ri) % 2 === 0) !== diagFlip;
  let x, y;
  if (splitA) {
    // Diagonal p00 -> p11
    if (lu >= lv) {
      x = p00[0] + lu * (p10[0] - p00[0]) + lv * (p11[0] - p10[0]);
      y = p00[1] + lu * (p10[1] - p00[1]) + lv * (p11[1] - p10[1]);
    } else {
      x = p00[0] + lv * (p01[0] - p00[0]) + lu * (p11[0] - p01[0]);
      y = p00[1] + lv * (p01[1] - p00[1]) + lu * (p11[1] - p01[1]);
    }
  } else {
    // Diagonal p10 -> p01
    if (lu + lv <= 1) {
      x = p00[0] + lu * (p10[0] - p00[0]) + lv * (p01[0] - p00[0]);
      y = p00[1] + lu * (p10[1] - p00[1]) + lv * (p01[1] - p00[1]);
    } else {
      x = p11[0] + (1 - lu) * (p01[0] - p11[0]) + (1 - lv) * (p10[0] - p11[0]);
      y = p11[1] + (1 - lu) * (p01[1] - p11[1]) + (1 - lv) * (p10[1] - p11[1]);
    }
  }
  return [x, y];
}

// Stencil fatigue factor: returns 0 (crisp) to 1 (faded/tired on right & top-right edge)
function stencilFatigue(x, y) {
  let fx = constrain(map(x, 660, 860, 0, 0.85), 0, 0.95);
  let fy = constrain(map(y, 480, 180, 0, 0.35), 0, 0.45);
  let n = noise(x * 0.012, y * 0.012) * 0.25;
  return constrain(fx + fy * 0.5 + n - 0.1, 0, 0.95);
}

