    [[834, 476], [802, 608]],
    [[802, 608], [836, 722]],
    [[836, 722], [826, 890]],
    [[634, 988], [738, 940]],
    [[738, 940], [826, 890]],
    // Internal major crease echoes
    [[628, 538], [602, 672]],
    [[602, 672], [642, 788]],
    [[642, 788], [634, 988]],
    [[602, 672], [716, 646]],
    [[716, 646], [802, 608]],
    [[642, 788], [744, 770]]
  ];

  for (let s of echoSegs) {
    drawBrokenLine(
      s[0][0] + dx, s[0][1] + dy,
      s[1][0] + dx, s[1][1] + dy,
      colA, 0.55 * passWeight, 0.65
    );
    // Secondary faint micro-echo
    drawBrokenLine(
      s[0][0] + dx * 0.5, s[0][1] + dy * 0.5,
      s[1][0] + dx * 0.5, s[1][1] + dy * 0.5,
      colB, 0.32 * passWeight, 0.45
    );
  }

  // Echo of the bent straw & cow logo
  if (passWeight > 0.8) {
    drawBentStripedStraw(dx, dy, true);
    drawFrontPanelGraphics(dx, dy, true);
    drawRoofAndRightGraphics(dx, dy, true);
  }
}

function drawBrokenLine(x1, y1, x2, y2, col, weight, density = 0.75) {
  let distTotal = dist(x1, y1, x2, y2);
  let steps = max(2, floor(distTotal / 10));
  for (let i = 0; i < steps; i++) {
    if (random() < density) {
      let t1 = i / steps;
      let t2 = (i + random(0.45, 0.95)) / steps;
      let ax = lerp(x1, x2, t1);
      let ay = lerp(y1, y2, t1);
      let bx = lerp(x1, x2, min(1, t2));
      let by = lerp(y1, y2, min(1, t2));
      brush.set("ditto_etch", col, weight * random(0.7, 1.2));
      brush.line(ax, ay, bx, by);
    }
  }
}

// ============================================================================
// 4. CARTON WATERCOLOR / ALCOHOL SOLVENT UNDERPAINTING
// ============================================================================
function getCartonFacets() {
  let facets = [];

  // Helper to push triangle with tonal metadata
  const addTri = (p1, p2, p3, tone, angle1, angle2, group) => {
    facets.push({ pts: [p1, p2, p3], tone, angle1, angle2, group });
  };

  // Top Seal Fin facets (4 triangles)
  addTri(finGrid[0][0], finGrid[0][1], finGrid[1][1], 0.18, 86, 12, "fin");
  addTri(finGrid[0][0], finGrid[1][1], finGrid[1][0], 0.25, 86, -15, "fin");
  addTri(finGrid[0][1], finGrid[0][2], finGrid[1][2], 0.14, 84, 8, "fin");
  addTri(finGrid[0][1], finGrid[1][2], finGrid[1][1], 0.22, 84, -12, "fin");

  // Left-Front Slanted Gable Roof facets (8 triangles)
  // Row 0..1
  addTri(roofGrid[0][0], roofGrid[0][1], roofGrid[1][1], 0.12, -32, 55, "roof");
  addTri(roofGrid[0][0], roofGrid[1][1], roofGrid[1][0], 0.24, -35, 48, "roof");
  addTri(roofGrid[0][1], roofGrid[0][2], roofGrid[1][1], 0.08, -28, 60, "roof");
  addTri(roofGrid[0][2], roofGrid[1][2], roofGrid[1][1], 0.19, -30, 52, "roof");
  // Row 1..2
  addTri(roofGrid[1][0], roofGrid[1][1], roofGrid[2][0], 0.16, -34, 42, "roof");
  addTri(roofGrid[1][1], roofGrid[2][1], roofGrid[2][0], 0.34, -26, 62, "roof");
  addTri(roofGrid[1][1], roofGrid[1][2], roofGrid[2][2], 0.10, -32, 50, "roof");
  addTri(roofGrid[1][1], roofGrid[2][2], roofGrid[2][1], 0.28, -24, 58, "roof");

  // Front-Left Crumpled Body (12 triangles across 3x4 grid)
  // Row 0..1 (under eave down to upper buckle)
  addTri(frontGrid[0][0], frontGrid[0][1], frontGrid[1][1], 0.44, 14, -68, "front");
  addTri(frontGrid[0][0], frontGrid[1][1], frontGrid[1][0], 0.62, 22, -55, "front");
  addTri(frontGrid[0][1], frontGrid[1][2], frontGrid[1][1], 0.30, 12, 78, "front");
  addTri(frontGrid[0][1], frontGrid[0][2], frontGrid[1][2], 0.48, 16, -72, "front");

  // Row 1..2 (the deep crushed waist!)
