  addTri(frontGrid[2][0], frontGrid[3][1], frontGrid[3][0], 0.54, 20, -62, "front");
  addTri(frontGrid[2][1], frontGrid[3][2], frontGrid[3][1], 0.66, 18, 75, "front");
  addTri(frontGrid[2][1], frontGrid[2][2], frontGrid[3][2], 0.42, 12, -68, "front");

  // Front-Right Crumpled Body (12 triangles under the spout)
