  addTri(rightGrid[0][0], rightGrid[1][1], rightGrid[1][0], 0.72, -18, 70, "right");
  addTri(rightGrid[0][1], rightGrid[1][2], rightGrid[1][1], 0.58, -28, 54, "right");
  addTri(rightGrid[0][1], rightGrid[0][2], rightGrid[1][2], 0.78, -32, 48, "right");

  // Row 1..2 (right buckled waist)
