function drawCartonUnderpainting() {
  let facets = getCartonFacets();
  brush.noStroke();

  // Group facets into tonal buckets for optimal p5.brush fill caching
  let buckets = [
    { maxT: 0.20, col: PAL.GHOST, alpha: 35, bleed: 0.12 },
    { maxT: 0.36, col: PAL.LILAC_FAINT, alpha: 52, bleed: 0.15 },
    { maxT: 0.55, col: PAL.LILAC, alpha: 65, bleed: 0.16 },
    { maxT: 0.72, col: PAL.VIOLET_SOFT, alpha: 78, bleed: 0.18 },
    { maxT: 0.82, col: PAL.VIOLET_MID, alpha: 92, bleed: 0.20 },
    { maxT: 1.00, col: PAL.VIOLET_DARK, alpha: 110, bleed: 0.22 }
  ];

  for (let b of buckets) {
    for (let f of facets) {
      if (f.tone <= b.maxT && !f.painted) {
        f.painted = true;
        // Shrink triangle slightly toward centroid so waxy white ridges breathe
        let cx = (f.pts[0][0] + f.pts[1][0] + f.pts[2][0]) / 3;
        let cy = (f.pts[0][1] + f.pts[1][1] + f.pts[2][1]) / 3;
        let fade = 1 - stencilFatigue(cx, cy) * 0.55;
        let shrunk = f.pts.map(p => [lerp(p[0], cx, 0.04), lerp(p[1], cy, 0.04)]);
        let poly = new brush.Polygon(shrunk);
        poly.fill(b.col, b.alpha * fade, b.bleed, 0.48);
      }
    }
  }
}

// ============================================================================
// 5. HYPERREAL FACET CROSS-HATCHING & FORM MODELING
// ============================================================================
function drawCartonFormModeling() {
  let facets = getCartonFacets();

  for (let f of facets) {
    let cx = (f.pts[0][0] + f.pts[1][0] + f.pts[2][0]) / 3;
    let cy = (f.pts[0][1] + f.pts[1][1] + f.pts[2][1]) / 3;
    let fatigue = stencilFatigue(cx, cy);
    let poly = new brush.Polygon(f.pts);

    // Primary directional form hatching on all shaded facets
    if (f.tone > 0.14) {
      let spacing = map(f.tone, 0.14, 0.9, 9.5, 3.0) * (1 + fatigue * 0.5);
      let col = f.tone > 0.65 ? PAL.VIOLET_DARK : (f.tone > 0.38 ? PAL.VIOLET_MID : PAL.LILAC);
      let w = map(f.tone, 0.14, 0.9, 0.35, 0.68) * (1 - fatigue * 0.35);
      let bName = fatigue > 0.55 ? "ditto_dry" : "ditto_etch";

      brush.hatchStyle(bName, col, w);
      poly.hatch(spacing, f.angle1, { rand: 0.05 + fatigue * 0.08, gradient: 0.28 });
    }

    // Secondary cross-hatching for mid-to-deep crumpled valleys
    if (f.tone > 0.42) {
      let spacing2 = map(f.tone, 0.42, 0.9, 8.5, 3.4) * (1 + fatigue * 0.4);
      let col2 = f.tone > 0.72 ? PAL.METHYL_DEEP : PAL.VIOLET_RICH;
      let w2 = map(f.tone, 0.42, 0.9, 0.38, 0.65) * (1 - fatigue * 0.3);

      brush.hatchStyle("ditto_fine", col2, w2);
      poly.hatch(spacing2, f.angle2, { rand: 0.04, gradient: 0.35 });
    }

    // Tertiary deep core etching in the darkest folds
    if (f.tone > 0.74) {
      brush.hatchStyle("ditto_etch", PAL.METHYL_BLACK, 0.55);
      poly.hatch(3.8, (f.angle1 + f.angle2) * 0.5, { rand: 0.03, gradient: 0.4 });
    }
  }
  brush.noHatch();
}

