// ============================================================================
// 7. PRINTED GRAPHICS, TYPOGRAPHY & THE COW LOGO (3D WARPED)
// ============================================================================
function drawWarpedPolyline(grid, uvPts, col, weight, closed = false, dx = 0, dy = 0, isEcho = false) {
  let dense = [];
  let total = closed ? uvPts.length : uvPts.length - 1;
  for (let i = 0; i < total; i++) {
    let a = uvPts[i];
    let b = uvPts[(i + 1) % uvPts.length];
    let d = dist(a[0], a[1], b[0], b[1]);
    let steps = max(2, ceil(d * 28));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let u = lerp(a[0], b[0], t);
      let v = lerp(a[1], b[1], t);
      let p = projectGrid(grid, u, v);
      dense.push([p[0] + dx, p[1] + dy]);
    }
  }
  let last = uvPts[closed ? 0 : uvPts.length - 1];
  let pLast = projectGrid(grid, last[0], last[1]);
  dense.push([pLast[0] + dx, pLast[1] + dy]);

  for (let i = 0; i < dense.length - 1; i++) {
    let p1 = dense[i];
    let p2 = dense[i + 1];
    let fat = stencilFatigue(p1[0] - dx, p1[1] - dy);
    if (isEcho && random() > 0.55) continue;
    if (!isEcho && random() < fat * 0.65) continue;

    let bName = (fat > 0.45 || isEcho) ? "ditto_dry" : "ditto_fine";
    let w = weight * (1 - fat * 0.4);
    brush.set(bName, col, max(0.2, w));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawWarpedText(grid, textStr, uCenter, vCenter, charW, charH, spacing, col, weight, dx = 0, dy = 0, isEcho = false) {
  let n = textStr.length;
  let totalW = n * charW + max(0, n - 1) * spacing;
  let startU = uCenter - totalW / 2;

  for (let i = 0; i < n; i++) {
    let ch = textStr[i];
    let strokes = FONT[ch];
    let u0 = startU + i * (charW + spacing);
    let v0 = vCenter - charH / 2;
    if (!strokes) continue;

    for (let poly of strokes) {
      let uvPts = poly.map(pt => [u0 + pt[0] * charW, v0 + pt[1] * charH]);
      drawWarpedPolyline(grid, uvPts, col, weight, false, dx, dy, isEcho);
    }
  }
}

function drawFrontPanelGraphics(dx = 0, dy = 0, isEcho = false) {
  let cDark = isEcho ? PAL.LILAC_FAINT : PAL.VIOLET_DARK;
  let cRich = isEcho ? PAL.GHOST : PAL.VIOLET_RICH;
  let cMid = isEcho ? PAL.GHOST : PAL.VIOLET_MID;
  let cDeep = isEcho ? PAL.LILAC : PAL.METHYL_DEEP;
  let wScale = isEcho ? 0.55 : 1.0;

  // 1. Top & Bottom Institutional Border Bands on Front Panel
  drawWarpedPolyline(frontGrid, [[0.06, 0.055], [0.94, 0.055]], cDark, 1.15 * wScale, false, dx, dy, isEcho);
  drawWarpedPolyline(frontGrid, [[0.06, 0.075], [0.94, 0.075]], cMid, 0.65 * wScale, false, dx, dy, isEcho);
  drawWarpedPolyline(frontGrid, [[0.06, 0.945], [0.94, 0.945]], cDark, 1.15 * wScale, false, dx, dy, isEcho);
  drawWarpedPolyline(frontGrid, [[0.06, 0.925], [0.94, 0.925]], cMid, 0.65 * wScale, false, dx, dy, isEcho);

  // Vertical side frame lines
  drawWarpedPolyline(frontGrid, [[0.06, 0.055], [0.06, 0.945]], cMid, 0.7 * wScale, false, dx, dy, isEcho);
  drawWarpedPolyline(frontGrid, [[0.94, 0.055], [0.94, 0.945]], cMid, 0.7 * wScale, false, dx, dy, isEcho);

  // 2. Institutional Dairy Typography
  drawWarpedText(frontGrid, "CLOVERVALE", 0.50, 0.135, 0.058, 0.055, 0.018, cDeep, 1.1 * wScale, dx, dy, isEcho);
  drawWarpedText(frontGrid, "GRADE A", 0.50, 0.205, 0.045, 0.036, 0.016, cRich, 0.78 * wScale, dx, dy, isEcho);

  // Lower ribbon banner around v = 0.77..0.83
  let bannerFrame = [[0.11, 0.755], [0.89, 0.755], [0.86, 0.825], [0.14, 0.825]];
  drawWarpedPolyline(frontGrid, bannerFrame, cDark, 0.9 * wScale, true, dx, dy, isEcho);
  drawWarpedText(frontGrid, "HOMOGENIZED", 0.50, 0.79, 0.046, 0.038, 0.014, cDeep, 0.95 * wScale, dx, dy, isEcho);

  if (!isEcho) {
    drawWarpedText(frontGrid, "VITAMIN D MILK", 0.50, 0.865, 0.036, 0.028, 0.012, cRich, 0.72, dx, dy, false);
    drawWarpedText(frontGrid, "HALF PINT", 0.50, 0.903, 0.030, 0.022, 0.012, cMid, 0.58, dx, dy, false);
  }

  // 3. THE PRINTED COW LOGO MEDALLION (centered at u = 0.50, v = 0.49)
  let cu = 0.50, cv = 0.485;
  let ru = 0.33, rv = 0.225;

  // Outer & Inner Medallion Rings
  let ringOuter = [], ringInner = [], ringScallop = [];
  for (let a = 0; a < 360; a += 8) {
    ringOuter.push([cu + cos(a) * ru, cv + sin(a) * rv]);
    ringInner.push([cu + cos(a) * (ru * 0.86), cv + sin(a) * (rv * 0.86)]);
    let sr = 0.93 + 0.035 * sin(a * 18);
    ringScallop.push([cu + cos(a) * (ru * sr), cv + sin(a) * (rv * sr)]);
  }
  drawWarpedPolyline(frontGrid, ringOuter, cDeep, 1.15 * wScale, true, dx, dy, isEcho);
  drawWarpedPolyline(frontGrid, ringInner, cDark, 0.8 * wScale, true, dx, dy, isEcho);
  if (!isEcho) {
    drawWarpedPolyline(frontGrid, ringScallop, cMid, 0.45, true, dx, dy, false);
  }

  // Woodcut radial engraving background lines behind the cow inside the medallion
  if (!isEcho) {
    for (let i = -11; i <= 11; i++) {
      let vLine = cv + i * 0.015;
      let dyNorm = (vLine - cv) / (rv * 0.84);
      if (abs(dyNorm) >= 0.98) continue;
      let halfSpan = sqrt(1 - dyNorm * dyNorm) * (ru * 0.84);
      // Left and right background segments outside the cow head silhouette
      drawWarpedPolyline(frontGrid, [[cu - halfSpan, vLine], [cu - 0.11, vLine]], PAL.LILAC, 0.38, false, dx, dy, false);
      drawWarpedPolyline(frontGrid, [[cu + 0.11, vLine], [cu + halfSpan, vLine]], PAL.LILAC, 0.38, false, dx, dy, false);
    }
  }

  // COW ANATOMY IN (u, v) MEDALLION SPACE
  // Curved Horns at crown
  let leftHorn = [[0.42, 0.35], [0.35, 0.30], [0.32, 0.32], [0.38, 0.375]];
  let rightHorn = [[0.58, 0.35], [0.65, 0.30], [0.68, 0.32], [0.62, 0.375]];
  drawWarpedPolyline(frontGrid, leftHorn, cDeep, 0.85 * wScale, false, dx, dy, isEcho);
  drawWarpedPolyline(frontGrid, rightHorn, cDeep, 0.85 * wScale, false, dx, dy, isEcho);

  // Expressive horizontal Dairy Cow Ears (breaking across inner medallion ring)
  let leftEar = [[0.39, 0.385], [0.24, 0.375], [0.19, 0.405], [0.25, 0.44], [0.38, 0.43]];
  let leftEarInner = [[0.36, 0.40], [0.25, 0.398], [0.27, 0.422]];
  let rightEar = [[0.61, 0.385], [0.76, 0.375], [0.81, 0.405], [0.75, 0.44], [0.62, 0.43]];
  let rightEarInner = [[0.64, 0.40], [0.75, 0.398], [0.73, 0.422]];
  drawWarpedPolyline(frontGrid, leftEar, cDeep, 0.95 * wScale, false, dx, dy, isEcho);
  drawWarpedPolyline(frontGrid, rightEar, cDeep, 0.95 * wScale, false, dx, dy, isEcho);
  if (!isEcho) {
    drawWarpedPolyline(frontGrid, leftEarInner, cRich, 0.55, false, dx, dy, false);
    drawWarpedPolyline(frontGrid, rightEarInner, cRich, 0.55, false, dx, dy, false);
  }

  // Crown, Cheekbones, Jaw & Broad Snout/Muzzle
  let headCrown = [[0.38, 0.375], [0.44, 0.345], [0.50, 0.352], [0.56, 0.345], [0.62, 0.375]];
  let leftCheek = [[0.38, 0.43], [0.36, 0.48], [0.39, 0.53], [0.37, 0.575]];
  let rightCheek = [[0.62, 0.43], [0.64, 0.48], [0.61, 0.53], [0.63, 0.575]];
  let muzzleOutline = [
    [0.37, 0.545], [0.43, 0.528], [0.57, 0.528], [0.63, 0.545],
    [0.64, 0.595], [0.58, 0.628], [0.42, 0.628], [0.36, 0.595]
  ];
  let lowerLip = [[0.41, 0.628], [0.45, 0.652], [0.55, 0.652], [0.59, 0.628]];

  drawWarpedPolyline(frontGrid, headCrown, cDeep, 1.0 * wScale, false, dx, dy, isEcho);
  drawWarpedPolyline(frontGrid, leftCheek, cDeep, 0.95 * wScale, false, dx, dy, isEcho);
