// ============================================================================
// 8. WAXY CARDBOARD CREASES, CRAZING & SPECULAR RIDGES
// ============================================================================
function drawWaxyCrease(p1, p2, intensity = 1.0, highlightSide = 1) {
  let d = dist(p1[0], p1[1], p2[0], p2[1]);
  let ang = atan2(p2[1] - p1[1], p2[0] - p1[0]);
  let nx = -sin(ang) * highlightSide;
  let ny = cos(ang) * highlightSide;
  let fat = stencilFatigue((p1[0] + p2[0]) * 0.5, (p1[1] + p2[1]) * 0.5);

  // 1. Clean paper-white specular wax highlight ridge alongside the crease
  brush.set("ditto_fine", PAL.PAPER_HIGHLIGHT, 1.35 * intensity);
  brush.line(p1[0] + nx * 2.2, p1[1] + ny * 2.2, p2[0] + nx * 2.2, p2[1] + ny * 2.2);

  // 2. Soft parallel bevel shadow
  brush.set("ditto_etch", PAL.VIOLET_MID, 0.65 * intensity * (1 - fat * 0.4));
  brush.line(p1[0] - nx * 2.0, p1[1] - ny * 2.0, p2[0] - nx * 2.0, p2[1] - ny * 2.0);

  // 3. Sharp dark core crease valley
  let coreCol = intensity > 0.85 ? PAL.METHYL_DEEP : PAL.VIOLET_DARK;
  let coreBrush = fat > 0.5 ? "ditto_dry" : "ditto_fine";
  brush.set(coreBrush, coreCol, 0.95 * intensity * (1 - fat * 0.35));
  brush.line(p1[0], p1[1], p2[0], p2[1]);

  // 4. Micro wax-coating crazing (tiny feather ticks crossing the folded ridge)
  let numTicks = floor(d / 11);
  for (let i = 1; i < numTicks; i++) {
    if (random() < 0.65 * (1 - fat * 0.5)) {
      let t = i / numTicks + random(-0.02, 0.02);
      let tx = lerp(p1[0], p2[0], t);
      let ty = lerp(p1[1], p2[1], t);
      let tLen = random(3.5, 9.5) * intensity;
      let tAng = ang + random(65, 115);
      brush.set("ditto_etch", PAL.VIOLET_SOFT, random(0.28, 0.48));
      brush.line(
        tx - cos(tAng) * tLen * 0.4, ty - sin(tAng) * tLen * 0.4,
        tx + cos(tAng) * tLen * 0.6, ty + sin(tAng) * tLen * 0.6
      );
    }
  }
}

