// ============================================================================
// 9. THE BENT STRIPED STRAW (3D CYLINDER + CORRUGATED BELLOWS)
// ============================================================================
function drawBentStripedStraw(dx = 0, dy = 0, isEcho = false) {
  // Straw centerline anchors:
  // A: Inside dark spout mouth -> B: Bottom of flex-neck -> C: Top of flex-neck -> D: Drinking tip
  let A = [708 + dx, 466 + dy];
  let B = [648 + dx, 232 + dy];
  let C = [568 + dx, 186 + dy];
  let D = [408 + dx, 244 + dy];
  let R = 17.5; // Straw radius

  // Unit normals for lower shaft (A->B) and upper shaft (C->D)
  let ang1 = atan2(B[1] - A[1], B[0] - A[0]); // ~ -104 deg
  let nx1 = cos(ang1 + 90), ny1 = sin(ang1 + 90); // points right-up

  let ang2 = atan2(D[1] - C[1], D[0] - C[0]); // ~ 160 deg
  let nx2 = cos(ang2 - 90), ny2 = sin(ang2 - 90); // points up-left (top edge of upper shaft)

  if (!isEcho) {
    // 1. Opaque paper wash mask so the straw cleanly occludes the carton fin behind it
    let maskPoly = [
      [A[0] - nx1 * R, A[1] - ny1 * R],
      [B[0] - nx1 * R, B[1] - ny1 * R],
      [602, 198],
      [C[0] - nx2 * R, C[1] - ny2 * R],
      [D[0] - nx2 * R, D[1] - ny2 * R],
      [D[0] + nx2 * R, D[1] + ny2 * R],
      [C[0] + nx2 * R, C[1] + ny2 * R],
      [626, 166],
      [B[0] + nx1 * R, B[1] + ny1 * R],
      [A[0] + nx1 * R, A[1] + ny1 * R]
    ];
    brush.noStroke();
    let pMask = new brush.Polygon(maskPoly);
    pMask.wash(PAL.PAPER, 255);

    // Subtle translucent plastic shadow along the underside of both shafts
    let shadeLower = [
      [A[0] + nx1 * 2, A[1] + ny1 * 2],
      [B[0] + nx1 * 2, B[1] + ny1 * 2],
      [B[0] + nx1 * R, B[1] + ny1 * R],
      [A[0] + nx1 * R, A[1] + ny1 * R]
    ];
    let shadeUpper = [
      [C[0] - nx2 * 2, C[1] - ny2 * 2],
      [D[0] - nx2 * 2, D[1] - ny2 * 2],
      [D[0] - nx2 * R, D[1] - ny2 * R],
      [C[0] - nx2 * R, C[1] - ny2 * R]
    ];
    new brush.Polygon(shadeLower).fill(PAL.LILAC_FAINT, 62, 0.12, 0.35);
    new brush.Polygon(shadeUpper).fill(PAL.LILAC, 68, 0.12, 0.35);

    // Faint ghost of carton fin edge seen through the translucent straw!
    brush.set("ditto_etch", PAL.LILAC_FAINT, 0.45);
    brush.line(652, 310, 684, 306);
    brush.line(654, 355, 686, 351);
  }

  let cOutline = isEcho ? PAL.LILAC_FAINT : PAL.VIOLET_DARK;
  let cStripe = isEcho ? PAL.GHOST : PAL.VIOLET_RICH;
  let cDeep = isEcho ? PAL.LILAC : PAL.METHYL_DEEP;
  let wMult = isEcho ? 0.5 : 1.0;

  // 2. Lower Straight Shaft (A -> B): Helical Candy Stripes & Cross-Contour Shading
  let steps1 = 44;
  for (let s = 0; s < steps1; s++) {
    let t = s / steps1;
    let cx = lerp(A[0], B[0], t);
    let cy = lerp(A[1], B[1], t);

    // Cylindrical cross-contour shading ticks on shadow side
    if (!isEcho) {
      brush.set("ditto_etch", PAL.VIOLET_MID, 0.38);
      brush.line(cx + nx1 * 3, cy + ny1 * 3, cx + nx1 * (R - 1.5), cy + ny1 * (R - 1.5));
    }
  }

  // Spiral candy stripes wrapping across Lower Shaft (A -> B)
  // A stripe wrapping around a cylinder projects as a sine wave across the width!
  for (let band = 0; band < 2; band++) {
    let offset = band * 18;
    let stripePts1 = [], stripePts2 = [];
    for (let s = 0; s <= 90; s++) {
      let t = s / 90;
      let cx = lerp(A[0], B[0], t);
      let cy = lerp(A[1], B[1], t);
      let phase1 = t * 760 + offset;
      let phase2 = phase1 + 38; // width of stripe

      // Only draw on the front-facing half of the cylinder (cos(phase) > 0)
      if (cos(phase1) > 0) {
        let off1 = sin(phase1) * (R - 1);
        stripePts1.push([cx + nx1 * off1, cy + ny1 * off1]);
      } else if (stripePts1.length > 1) {
        drawSimplePolyline(stripePts1, cStripe, 0.85 * wMult, isEcho);
        stripePts1 = [];
      }

      if (cos(phase2) > 0) {
        let off2 = sin(phase2) * (R - 1);
        stripePts2.push([cx + nx1 * off2, cy + ny1 * off2]);
      } else if (stripePts2.length > 1) {
        drawSimplePolyline(stripePts2, cStripe, 0.85 * wMult, isEcho);
        stripePts2 = [];
      }
    }
    if (stripePts1.length > 1) drawSimplePolyline(stripePts1, cStripe, 0.85 * wMult, isEcho);
    if (stripePts2.length > 1) drawSimplePolyline(stripePts2, cStripe, 0.85 * wMult, isEcho);

    // Fill the stripe ribbon with tight hatch lines
    if (!isEcho) {
      for (let s = 0; s <= 110; s++) {
        let t = s / 110;
        let phaseMid = t * 760 + offset + 19;
        if (cos(phaseMid) > 0.1) {
          let cx = lerp(A[0], B[0], t);
          let cy = lerp(A[1], B[1], t);
          let oA = sin(phaseMid - 17) * (R - 1.2);
          let oB = sin(phaseMid + 17) * (R - 1.2);
          let colS = sin(phaseMid) > 0.2 ? PAL.VIOLET_DARK : PAL.VIOLET_MID;
          brush.set("ditto_fine", colS, 0.65);
          brush.line(cx + nx1 * oA, cy + ny1 * oA, cx + nx1 * oB, cy + ny1 * oB);
        }
      }
    }
  }

  // 3. Upper Straight Shaft (C -> D): Helical Candy Stripes & Shading
  let steps2 = 36;
  for (let s = 0; s < steps2; s++) {
    let t = s / steps2;
    let cx = lerp(C[0], D[0], t);
    let cy = lerp(C[1], D[1], t);
    if (!isEcho) {
      brush.set("ditto_etch", PAL.VIOLET_MID, 0.4);
      brush.line(cx - nx2 * 2, cy - ny2 * 2, cx - nx2 * (R - 1.5), cy - ny2 * (R - 1.5));
    }
  }

  // Spiral stripes on Upper Shaft (C -> D)
  for (let s = 0; s <= 85; s++) {
    let t = s / 85;
    let phaseMid = t * 540 + 45;
    if (cos(phaseMid) > 0.08) {
      let cx = lerp(C[0], D[0], t);
      let cy = lerp(C[1], D[1], t);
      let oA = sin(phaseMid - 18) * (R - 1.2);
      let oB = sin(phaseMid + 18) * (R - 1.2);
      let colS = isEcho ? PAL.GHOST : (oA < 0 ? PAL.VIOLET_DARK : PAL.VIOLET_RICH);
      brush.set(isEcho ? "ditto_dry" : "ditto_fine", colS, 0.65 * wMult);
      brush.line(cx + nx2 * oA, cy + ny2 * oA, cx + nx2 * oB, cy + ny2 * oB);
    }
  }

  // 4. Corrugated Accordion Flex-Neck Bellows (between B and C)
  // Arc pivot around P_PIV = [598 + dx, 232 + dy] from angle -12 deg to -126 deg
  let P_PIV = [598 + dx, 234 + dy];
  let rCenter = 51;
  let numRings = 10;
  for (let i = 0; i < numRings; i++) {
    let t0 = i / numRings;
    let tMid = (i + 0.5) / numRings;
    let t1 = (i + 1) / numRings;

    let a0 = lerp(-6, -122, t0);
    let aMid = lerp(-6, -122, tMid);
    let a1 = lerp(-6, -122, t1);

    let rIn = rCenter - R + 2;
    let rOutValley = rCenter + R - 3;
    let rOutPeak = rCenter + R + 4.5;

    let in0 = [P_PIV[0] + cos(a0) * rIn, P_PIV[1] + sin(a0) * rIn];
    let inMid = [P_PIV[0] + cos(aMid) * (rIn - 2.5), P_PIV[1] + sin(aMid) * (rIn - 2.5)];
    let in1 = [P_PIV[0] + cos(a1) * rIn, P_PIV[1] + sin(a1) * rIn];

    let out0 = [P_PIV[0] + cos(a0) * rOutValley, P_PIV[1] + sin(a0) * rOutValley];
    let outPeak = [P_PIV[0] + cos(aMid) * rOutPeak, P_PIV[1] + sin(aMid) * rOutPeak];
    let out1 = [P_PIV[0] + cos(a1) * rOutValley, P_PIV[1] + sin(a1) * rOutValley];

    // Outer zigzag bellow peak & valley
    brush.set(isEcho ? "ditto_dry" : "ditto_fine", cDeep, 0.9 * wMult);
    brush.line(out0[0], out0[1], outPeak[0], outPeak[1]);
    brush.line(outPeak[0], outPeak[1], out1[0], out1[1]);

    // Inner pinched accordion folds
    brush.set(isEcho ? "ditto_dry" : "ditto_fine", cDeep, 0.95 * wMult);
    brush.line(in0[0], in0[1], inMid[0], inMid[1]);
    brush.line(inMid[0], inMid[1], in1[0], in1[1]);

    // Sharp V-ridge ring lines across the tube
    brush.set("ditto_etch", cOutline, 0.65 * wMult);
    brush.line(in0[0], in0[1], out0[0], out0[1]);
    brush.set("ditto_fine", cDeep, 0.78 * wMult);
    brush.line(inMid[0], inMid[1], outPeak[0], outPeak[1]);

    // Dark recessed crease shading on the back slope of each accordion ring
    if (!isEcho) {
      for (let k = 0.15; k <= 0.85; k += 0.18) {
        let pV0 = [lerp(inMid[0], outPeak[0], k), lerp(inMid[1], outPeak[1], k)];
        let pV1 = [lerp(in1[0], out1[0], k), lerp(in1[1], out1[1], k)];
        brush.set("ditto_etch", i % 3 === 1 ? PAL.VIOLET_DARK : PAL.VIOLET_MID, 0.52);
        brush.line(pV0[0], pV0[1], pV1[0], pV1[1]);
      }
      // Specular white highlight along the top-left of each bellow peak
      brush.set("ditto_fine", PAL.PAPER_HIGHLIGHT, 1.1);
      brush.line(
        lerp(in0[0], out0[0], 0.75), lerp(in0[1], out0[1], 0.75),
        lerp(inMid[0], outPeak[0], 0.78), lerp(inMid[1], outPeak[1], 0.78)
      );
    }
  }

  // 5. Outer Cylinder Contours & Specular Highlights
  // Lower shaft edges
  brush.set(isEcho ? "ditto_dry" : "ditto_fine", cOutline, 0.95 * wMult);
  brush.line(A[0] - nx1 * R, A[1] - ny1 * R, B[0] - nx1 * R, B[1] - ny1 * R);
  brush.set(isEcho ? "ditto_dry" : "ditto_fine", cDeep, 1.1 * wMult);
  brush.line(A[0] + nx1 * R, A[1] + ny1 * R, B[0] + nx1 * R, B[1] + ny1 * R);

  // Upper shaft edges
  brush.set(isEcho ? "ditto_dry" : "ditto_fine", cOutline, 0.95 * wMult);
  brush.line(C[0] + nx2 * R, C[1] + ny2 * R, D[0] + nx2 * R, D[1] + ny2 * R);
  brush.set(isEcho ? "ditto_dry" : "ditto_fine", cDeep, 1.1 * wMult);
  brush.line(C[0] - nx2 * R, C[1] - ny2 * R, D[0] - nx2 * R, D[1] - ny2 * R);

  if (!isEcho) {
    // Clean specular highlight ribbon running down the lit side of the plastic straw
    brush.set("ditto_fine", PAL.PAPER_HIGHLIGHT, 1.5);
    brush.line(A[0] - nx1 * (R * 0.55), A[1] - ny1 * (R * 0.55), B[0] - nx1 * (R * 0.55), B[1] - ny1 * (R * 0.55));
    brush.line(C[0] + nx2 * (R * 0.55), C[1] + ny2 * (R * 0.55), D[0] + nx2 * (R * 0.55), D[1] + ny2 * (R * 0.55));

    // 6. Open Elliptical Drinking Tip at D = [408, 244]
    let tipOuter = [], tipInner = [];
    let tx = cos(ang2), ty = sin(ang2);
    for (let a = 0; a < 360; a += 15) {
      let ca = cos(a), sa = sin(a);
      tipOuter.push([
        D[0] + tx * ca * 7.5 + nx2 * sa * R,
        D[1] + ty * ca * 7.5 + ny2 * sa * R
      ]);
      tipInner.push([
        D[0] + tx * ca * 5.8 + nx2 * sa * (R - 2.5),
        D[1] + ty * ca * 5.8 + ny2 * sa * (R - 2.5)
      ]);
    }
    let pTipIn = new brush.Polygon(tipInner);
    pTipIn.fill(PAL.VIOLET_DARK, 110, 0.1, 0.4);
    brush.hatchStyle("ditto_etch", PAL.METHYL_DEEP, 0.65);
    pTipIn.hatch(2.2, 25, { rand: 0.03 });
    brush.noHatch();

    drawSimplePolyline([...tipOuter, tipOuter[0]], PAL.METHYL_DEEP, 1.0, false);

    // Tiny glistening droplet of milk clinging to the lower rim of the straw tip!
    let dropTip = [
      [D[0] - nx2 * R, D[1] - ny2 * R],
      [D[0] - nx2 * R - 6, D[1] - ny2 * R + 12],
      [D[0] - nx2 * R, D[1] - ny2 * R + 19],
      [D[0] - nx2 * R + 7, D[1] - ny2 * R + 12]
    ];
    let pDropTip = new brush.Polygon(dropTip);
    pDropTip.wash(PAL.PAPER_HIGHLIGHT, 255);
    drawSimplePolyline([...dropTip, dropTip[0]], PAL.VIOLET_DARK, 0.85, false);
    brush.set("ditto_fine", PAL.METHYL_DEEP, 1.1);
    brush.line(dropTip[1][0], dropTip[1][1], dropTip[2][0], dropTip[2][1]);
    brush.line(dropTip[2][0], dropTip[2][1], dropTip[3][0], dropTip[3][1]);

    // 7. Re-draw the foreground spout lip overlapping the base of the straw at A
    brush.set("ditto_fine", PAL.PAPER_HIGHLIGHT, 1.4);
    brush.line(642, 494, 750, 513);
    brush.set("ditto_fine", PAL.METHYL_BLACK, 1.25);
    brush.line(642, 496, 750, 515);
  }
}

function drawSimplePolyline(pts, col, weight, isEcho = false) {
  for (let i = 0; i < pts.length - 1; i++) {
    if (isEcho && random() > 0.6) continue;
    brush.set(isEcho ? "ditto_dry" : "ditto_fine", col, weight);
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
}

