function initCurtainWallPanes() {
  panes = [];
  for (let r = 0; r < yTransoms.length - 1; r++) {
    let y1 = yTransoms[r];
    let y2 = yTransoms[r + 1];
    let isSpandrel = (r === 1 || r === 3 || r === 5);
    let padY = 8;

    for (let c = 0; c < xMullions.length - 1; c++) {
      let x1 = xMullions[c];
      let x2 = xMullions[c + 1];
      let isMajorLeft = (c === 2 || c === 3);
      let isMajorRight = (c + 1 === 2 || c + 1 === 3);
      let leftHalf = (c === 0) ? 11 : (isMajorLeft ? 12 : 9);
      let rightHalf = (c + 1 === xMullions.length - 1) ? 11 : (isMajorRight ? 12 : 9);

      let px = x1 + leftHalf;
      let py = y1 + padY;
      let pw = (x2 - rightHalf) - px;
      let ph = (y2 - padY) - py;

      // Subtle, realistic float-glass bowing & mounting tilt per individual IGU pane
      let bowSign = ((c + r) % 2 === 0) ? 1 : -1;
      let bowMag = random(0.14, 0.30) * bowSign;
      // Enhance distortion slightly on focal panes for dramatic mosaic stepping
      if (r === 2 && (c === 1 || c === 2 || c === 3)) bowMag *= 1.18;

      panes.push({
        col: c,
        row: r,
        x: px,
        y: py,
        w: pw,
        h: ph,
        cx: px + pw * 0.5,
        cy: py + ph * 0.5,
        isSpandrel: isSpandrel,
        shiftX: random(-26, 26),
        shiftY: random(-22, 22),
        rot: random(-2.2, 2.2), // degrees
        bow: bowMag,
        wavePhase: random(0, 360),
        rollerAmp: random(2.2, 5.2),
        tintMode: (c * 3 + r * 5) % 4,
        chiselAngle: -14 + random(-3, 3)
      });
    }
  }
}

// Maps a reflection-world coordinate (wx, wy) into warped pane coordinates
function worldToPane(wx, wy, pane) {
  let dx = wx - pane.cx + pane.shiftX;
  let dy = wy - pane.cy + pane.shiftY;

  let cosA = cos(pane.rot);
  let sinA = sin(pane.rot);
  let rx = dx * cosA - dy * sinA;
  let ry = dx * sinA + dy * cosA;

  let nx = rx / (pane.w * 0.55);
  let ny = ry / (pane.h * 0.55);
  let r2 = constrain(nx * nx + ny * ny, 0, 2.4);

  // Pillow/barrel IGU pressure deflection + horizontal tempering roller wave
  let bowFactor = 1.0 + pane.bow * (r2 - 0.62) * 0.30;
  let waveX = cos((wy * 1.45) + pane.wavePhase) * (pane.rollerAmp * 0.55);
  let waveY = sin((wx * 1.25) + pane.wavePhase) * pane.rollerAmp;

  return [
    pane.cx + rx * bowFactor + waveX,
    pane.cy + ry * bowFactor + waveY
  ];
}

// Sutherland-Hodgman polygon clipper to rectangle [rx, ry, rx+rw, ry+rh]
function clipPolyToRect(pts, rx, ry, rw, rh) {
  if (!pts || pts.length < 3) return [];
  let xMin = rx, xMax = rx + rw, yMin = ry, yMax = ry + rh;

  function clipEdge(poly, edge) {
    let out = [];
    let n = poly.length;
    if (n === 0) return out;
    for (let i = 0; i < n; i++) {
      let cur = poly[i];
      let prev = poly[(i + n - 1) % n];
      let curIn = isInside(cur, edge);
      let prevIn = isInside(prev, edge);
      if (curIn) {
        if (!prevIn) out.push(intersect(prev, cur, edge));
        out.push(cur);
      } else if (prevIn) {
        out.push(intersect(prev, cur, edge));
      }
    }
    return out;
  }

  function isInside(p, edge) {
    if (edge === 0) return p[0] >= xMin;
    if (edge === 1) return p[0] <= xMax;
    if (edge === 2) return p[1] >= yMin;
    return p[1] <= yMax;
  }

  function intersect(p1, p2, edge) {
    let x1 = p1[0], y1 = p1[1], x2 = p2[0], y2 = p2[1];
    let dx = x2 - x1, dy = y2 - y1;
    if (edge === 0) {
      let t = ( Math.abs(dx) < 1e-6 ) ? 0 : (xMin - x1) / dx;
      return [xMin, y1 + t * dy];
    }
    if (edge === 1) {
      let t = ( Math.abs(dx) < 1e-6 ) ? 0 : (xMax - x1) / dx;
      return [xMax, y1 + t * dy];
    }
    if (edge === 2) {
      let t = ( Math.abs(dy) < 1e-6 ) ? 0 : (yMin - y1) / dy;
      return [x1 + t * dx, yMin];
    }
    let t = ( Math.abs(dy) < 1e-6 ) ? 0 : (yMax - y1) / dy;
    return [x1 + t * dx, yMax];
  }

  let res = pts;
  for (let e = 0; e < 4; e++) {
    res = clipEdge(res, e);
    if (res.length < 3) return [];
  }

  // Deduplicate close vertices
  let clean = [];
  for (let i = 0; i < res.length; i++) {
    let p = res[i];
    let prev = clean.length > 0 ? clean[clean.length - 1] : res[res.length - 1];
    if ( Math.hypot(p[0] - prev[0], p[1] - prev[1]) > 0.6 ) {
      clean.push(p);
    }
  }
  if (clean.length < 3) return [];

  // Check area
  let area = 0;
  for (let i = 0; i < clean.length; i++) {
    let j = (i + 1) % clean.length;
    area += clean[i][0] * clean[j][1] - clean[j][0] * clean[i][1];
  }
  if (Math.abs(area) * 0.5 < 3.0) return [];
  return clean;
}

// Subdivide polygon edges so warped curves stay smooth
function subdividePoly(pts, maxLen = 22) {
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    let d = Math.hypot(p2[0] - p1[0], p2[1] - p1[1]);
    let steps = Math.max(1, Math.ceil(d / maxLen));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      out.push([p1[0] + (p2[0] - p1[0]) * t, p1[1] + (p2[1] - p1[1]) * t]);
    }
  }
  return out;
}

// Draw a reflection-world polygon warped and clipped to a pane
function drawWarpedPoly(worldPts, pane, opts = {}) {
  let sub = subdividePoly(worldPts, opts.step || 22);
  let warped = sub.map(pt => worldToPane(pt[0], pt[1], pane));
  let clipBox = opts.clipBox || [pane.x, pane.y, pane.w, pane.h];
  let clipped = clipPolyToRect(warped, clipBox[0], clipBox[1], clipBox[2], clipBox[3]);
  if (clipped.length < 3) return null;

  let poly = new brush.Polygon(clipped);
  if (opts.washCol) {
    poly.wash(opts.washCol, opts.washOp !== undefined ? opts.washOp : 190);
  }
  if (opts.hatchBrush) {
    brush.set(opts.hatchBrush, opts.hatchCol || PAL.b28, opts.hatchWeight || 1);
    brush.hatchStyle(opts.hatchBrush, opts.hatchCol || PAL.b28, opts.hatchWeight || 1);
    poly.hatch(opts.hatchDist || 9, opts.hatchAngle !== undefined ? opts.hatchAngle : pane.chiselAngle, opts.hatchOpts || { rand: 0.02 });
    brush.noHatch();
  }
  if (opts.strokeBrush) {
    brush.set(opts.strokeBrush, opts.strokeCol || PAL.b99, opts.strokeWeight || 0.7);
    poly.draw(opts.strokeBrush, opts.strokeCol || PAL.b99, opts.strokeWeight || 0.7);
  }
  return clipped;
}

// Draw a screen-space polygon clipped to a box
function drawScreenPolyClipped(screenPts, clipBox, opts = {}) {
  let clipped = clipPolyToRect(screenPts, clipBox[0], clipBox[1], clipBox[2], clipBox[3]);
  if (clipped.length < 3) return null;
  let poly = new brush.Polygon(clipped);
  if (opts.washCol) {
    poly.wash(opts.washCol, opts.washOp !== undefined ? opts.washOp : 190);
  }
  if (opts.hatchBrush) {
    brush.set(opts.hatchBrush, opts.hatchCol || PAL.b28, opts.hatchWeight || 1);
    brush.hatchStyle(opts.hatchBrush, opts.hatchCol || PAL.b28, opts.hatchWeight || 1);
    poly.hatch(opts.hatchDist || 8, opts.hatchAngle !== undefined ? opts.hatchAngle : -15, opts.hatchOpts || { rand: 0.02 });
    brush.noHatch();
  }
  if (opts.strokeBrush) {
    brush.set(opts.strokeBrush, opts.strokeCol || PAL.b99, opts.strokeWeight || 0.7);
    poly.draw(opts.strokeBrush, opts.strokeCol || PAL.b99, opts.strokeWeight || 0.7);
  }
  return clipped;
}

// Liang-Barsky segment clipper
function clipSegmentToRect(x1, y1, x2, y2, rx, ry, rw, rh) {
  let t0 = 0.0, t1 = 1.0;
  let dx = x2 - x1, dy = y2 - y1;
  let p = [-dx, dx, -dy, dy];
  let q = [x1 - rx, (rx + rw) - x1, y1 - ry, (ry + rh) - y1];
  for (let i = 0; i < 4; i++) {
    if (Math.abs(p[i]) < 1e-7) {
      if (q[i] < 0) return null;
    } else {
      let r = q[i] / p[i];
      if (p[i] < 0) {
        if (r > t1) return null;
        if (r > t0) t0 = r;
      } else {
        if (r < t0) return null;
        if (r < t1) t1 = r;
      }
    }
  }
  if (t0 >= t1) return null;
  return [x1 + t0 * dx, y1 + t0 * dy, x1 + t1 * dx, y1 + t1 * dy];
}

// Draw a reflection-world line warped into curves and clipped to pane
function drawWarpedLine(wx1, wy1, wx2, wy2, pane, brushName, col, weight = 0.7, clipBox = null) {
  let box = clipBox || [pane.x, pane.y, pane.w, pane.h];
  let d = Math.hypot(wx2 - wx1, wy2 - wy1);
  let steps = Math.max(1, Math.ceil(d / 16));
  brush.set(brushName, col, weight);
  for (let s = 0; s < steps; s++) {
    let tA = s / steps;
    let tB = (s + 1) / steps;
    let pA = worldToPane(wx1 + (wx2 - wx1) * tA, wy1 + (wy2 - wy1) * tA, pane);
    let pB = worldToPane(wx1 + (wx2 - wx1) * tB, wy1 + (wy2 - wy1) * tB, pane);
    let seg = clipSegmentToRect(pA[0], pA[1], pB[0], pB[1], box[0], box[1], box[2], box[3]);
    if (seg && Math.hypot(seg[2] - seg[0], seg[3] - seg[1]) > 0.5) {
      brush.line(seg[0], seg[1], seg[2], seg[3]);
    }
  }
}

function drawClippedLine(x1, y1, x2, y2, box, brushName, col, weight = 0.7) {
  let seg = clipSegmentToRect(x1, y1, x2, y2, box[0], box[1], box[2], box[3]);
  if (seg && Math.hypot(seg[2] - seg[0], seg[3] - seg[1]) > 0.5) {
    brush.set(brushName, col, weight);
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#d8e4ec");

  // 1. Base metallic dark ground for mullion channels and curtain wall frame
  let fullRect = new brush.Polygon([[0, 0], [1200, 0], [1200, 1200], [0, 1200]]);
  fullRect.wash(PAL.c7, 240);

  // 2. Render all 30 curtain wall panes with warped sky, crane, neighbouring towers & interior depth
  for (let i = 0; i < panes.length; i++) {
    let pane = panes[i];
    let box = [pane.x, pane.y, pane.w, pane.h];
    renderPaneReflection(pane, box);
  }

  // 3. Render Squeegee Streaks, Wet Soap Film & Water Beads on focal panes
  // Pane (Col 2, Row 2) is actively being squeegeed; Pane (Col 1, Row 2) is freshly wiped
  let paneActive = panes.find(p => p.col === 2 && p.row === 2);
  let paneFresh  = panes.find(p => p.col === 1 && p.row === 2);
  let paneRight  = panes.find(p => p.col === 3 && p.row === 2);
  let paneBelow  = panes.find(p => p.col === 2 && p.row === 3);

  if (paneActive) renderActiveSqueegeePane(paneActive);
  if (paneFresh)  renderFreshWipedPane(paneFresh);
  if (paneRight)  renderPreWetSplashPane(paneRight);
  if (paneBelow)  renderDripRunoffOnSpandrel(paneBelow);

  // 4. Render Ghosted Double-Reflection of the Gondola & Worker's Orange Harness inside the Glass
  renderGondolaGlassReflection();

  // 5. Render the Rigid Architectural Grid of Mullions & Transoms
  brush.noClip();
  renderCurtainWallMullions();

  // 6. Render the Suspended Gondola, Wire Ropes, Squeegee & Worker with Vivid Orange Harness
  renderSuspensionCables();
  renderGondolaAndWorker();

  // 7. Final Fine-Liner Architectural Polish & Specular Glints
  renderFinalAccents();

  noLoop();
}

// =============================================================================
// PANE REFLECTION ENGINE (SKY, INTERIOR GHOSTING, NEIGHBOURING TOWERS, CRANE)
// =============================================================================
function renderPaneReflection(pane, clipBox) {
  let isSpandrel = pane.isSpandrel;

  // --- A. Base Sky Gradient Bands (Cool Alcohol Marker Washes + Chisel Streaks) ---
  let skyBands = isSpandrel ? [
    { y1: -80,  y2: 200,  col: PAL.bg99, hatch: PAL.b99 },
    { y1: 195,  y2: 420,  col: PAL.bg78, hatch: PAL.b97 },
    { y1: 415,  y2: 680,  col: PAL.bg75, hatch: PAL.bg78 },
    { y1: 675,  y2: 940,  col: PAL.bg49, hatch: PAL.bg75 },
    { y1: 935,  y2: 1280, col: PAL.b39,  hatch: PAL.bg49 }
  ] : [
    { y1: -80,  y2: 140,  col: PAL.b97,  hatch: PAL.b99 },
    { y1: 135,  y2: 280,  col: PAL.b39,  hatch: PAL.b97 },
    { y1: 275,  y2: 430,  col: PAL.b28,  hatch: PAL.b39 },
    { y1: 425,  y2: 590,  col: PAL.bg49, hatch: PAL.b24 },
    { y1: 585,  y2: 760,  col: PAL.bg15, hatch: PAL.bg49 },
    { y1: 755,  y2: 940,  col: PAL.bg13, hatch: PAL.bg15 },
    { y1: 935,  y2: 1100, col: PAL.b12,  hatch: PAL.bg13 },
    { y1: 1095, y2: 1280, col: PAL.bg11, hatch: PAL.b12 }
  ];

  // Base pane under-wash
  drawScreenPolyClipped(
    [[clipBox[0], clipBox[1]], [clipBox[0] + clipBox[2], clipBox[1]], [clipBox[0] + clipBox[2], clipBox[1] + clipBox[3]], [clipBox[0], clipBox[1] + clipBox[3]]],
    clipBox,
    { washCol: isSpandrel ? PAL.bg99 : PAL.b28, washOp: 245 }
  );

  for (let b = 0; b < skyBands.length; b++) {
    let sb = skyBands[b];
    let worldQuad = [[-80, sb.y1], [1280, sb.y1], [1280, sb.y2], [-80, sb.y2]];
    drawWarpedPoly(worldQuad, pane, {
      clipBox: clipBox,
      washCol: sb.col,
      washOp: isSpandrel ? 215 : 205,
      hatchBrush: "copic_wide",
      hatchCol: sb.hatch,
      hatchWeight: 0.9,
      hatchDist: 13,
      hatchAngle: pane.chiselAngle
    });
  }

  // Slight individual pane tint variation (architectural glass batch shift)
  if (pane.tintMode === 0) {
    drawScreenPolyClipped(
      [[clipBox[0], clipBox[1]], [clipBox[0] + clipBox[2], clipBox[1]], [clipBox[0] + clipBox[2], clipBox[1] + clipBox[3]], [clipBox[0], clipBox[1] + clipBox[3]]],
      clipBox,
      { washCol: PAL.bg15, washOp: isSpandrel ? 30 : 38 }
    );
  } else if (pane.tintMode === 2) {
    drawScreenPolyClipped(
      [[clipBox[0], clipBox[1]], [clipBox[0] + clipBox[2], clipBox[1]], [clipBox[0] + clipBox[2], clipBox[1] + clipBox[3]], [clipBox[0], clipBox[1] + clipBox[3]]],
      clipBox,
      { washCol: PAL.b97, washOp: isSpandrel ? 45 : 32 }
    );
  }

  // --- B. Subtle Interior Ghosting (Un-warped ceiling soffits, light troffers & blinds behind glass) ---
  if (!isSpandrel) {
    renderInteriorGhosting(pane, clipBox);
  } else {
    // Spandrel shadow-box horizontal I-beam flange hint behind dark glass
    let flangeY1 = pane.y + pane.h * 0.34;
    let flangeY2 = pane.y + pane.h * 0.66;
    drawClippedLine(pane.x, flangeY1, pane.x + pane.w, flangeY1, clipBox, "copic_fine", PAL.b99, 0.9);
    drawClippedLine(pane.x, flangeY2, pane.x + pane.w, flangeY2, clipBox, "copic_fine", PAL.bg49, 0.5);
  }

  // --- C. Warped Cloud Strata in the Sky ---
  renderWarpedClouds(pane, clipBox, isSpandrel);

  // --- D. Warped Distant Left Tower & Main Neighbouring Skyscraper ---
  renderReflectedTowers(pane, clipBox, isSpandrel);

  // --- E. Warped Construction Crane in Upper/Mid Sky ---
  renderReflectedCrane(pane, clipBox, isSpandrel);

  // --- F. Bowed Glass Specular Sheen & Perimeter Gasket Shadow ---
  renderGlassCushionSheen(pane, clipBox, isSpandrel);
}

function renderInteriorGhosting(pane, clipBox) {
  // Top ceiling plenum soffit in vision glass
  let soffitH = Math.min(44, pane.h * 0.22);
  drawScreenPolyClipped(
    [[pane.x, pane.y], [pane.x + pane.w, pane.y], [pane.x + pane.w, pane.y + soffitH], [pane.x, pane.y + soffitH]],
    clipBox,
    { washCol: PAL.bg99, washOp: 42 }
  );

  // Perspective recessed fluorescent ceiling troffers receding toward center (600, 560)
  let vpX = 600, vpY = 560;
  for (let k = 0; k < 2; k++) {
    let lx1 = pane.x + pane.w * (0.18 + k * 0.44);
    let lx2 = lx1 + pane.w * 0.20;
    let ly1 = pane.y + 8;
    let dir1X = (vpX - lx1) * 0.14, dir1Y = Math.max(12, Math.abs(vpY - ly1) * 0.08);
    let dir2X = (vpX - lx2) * 0.14;
    let trofferPts = [
      [lx1, ly1],
      [lx2, ly1],
      [lx2 + dir2X, ly1 + dir1Y],
      [lx1 + dir1X, ly1 + dir1Y]
    ];
    drawScreenPolyClipped(trofferPts, clipBox, {
      washCol: PAL.bg10,
      washOp: 48
    });
  }

  // Occasional subtle Venetian blind slats in upper/side panes
  if ((pane.col === 0 && pane.row === 2) || (pane.col === 4 && pane.row === 2) || (pane.col === 0 && pane.row === 4)) {
    let blindH = (pane.col === 0 && pane.row === 2) ? pane.h * 0.42 : pane.h * 0.58;
    for (let by = pane.y + 6; by < pane.y + blindH; by += 7) {
      drawClippedLine(pane.x + 4, by, pane.x + pane.w - 4, by, clipBox, "liner_005", PAL.c1, 0.45);
    }
  }
}

