function renderReflectedTowers(pane, clipBox, isSpandrel) {
  // --- 1. Distant Left Stepped High-Rise (wx: -40 .. 205, wy: 540 .. 1250) ---
  let leftTowerSun = [[-40, 540], [95, 540], [95, 1250], [-40, 1250]];
  let leftTowerShade = [[95, 540], [205, 565], [205, 1250], [95, 1250]];

  drawWarpedPoly(leftTowerSun, pane, {
    clipBox: clipBox,
    washCol: isSpandrel ? PAL.bg75 : PAL.b12,
    washOp: 185,
    hatchBrush: "copic_med",
    hatchCol: isSpandrel ? PAL.bg49 : PAL.bg13,
    hatchWeight: 0.7,
    hatchDist: 9,
    hatchAngle: 90
