  // --- 2. Monumental Neighbouring Skyscraper (Stepped Modernist Tower) ---
  // Tier 1 Upper Tower Core (wx: 685 .. 1250, wy: 185 .. 1250)
  // Sunlit West Return Facade: wx 685 .. 825
  // Shaded North Main Facade: wx 825 .. 1250
  let t1Sun = [[685, 198], [825, 178], [825, 1250], [685, 1250]];
  let t1Shade = [[825, 178], [1250, 215], [1250, 1250], [825, 1250]];

  // Mechanical Penthouse Crown (wx: 715 .. 1160, wy: 142 .. 198)
  let crownSun = [[715, 152], [825, 138], [825, 182], [715, 198]];
  let crownShade = [[825, 138], [1160, 168], [1160, 210], [825, 182]];

  // Tier 2 Mid-Level Setback Wing (wx: 435 .. 685, wy: 455 .. 1250)
  let t2Sun = [[435, 472], [545, 452], [545, 1250], [435, 1250]];
  let t2Shade = [[545, 452], [685, 468], [685, 1250], [545, 1250]];

  // Tier 3 Lower Podium Wing (wx: 245 .. 435, wy: 775 .. 1250)
  let t3Sun = [[245, 790], [330, 772], [330, 1250], [245, 1250]];
  let t3Shade = [[330, 772], [435, 786], [435, 1250], [330, 1250]];

  // Draw Crown
  drawWarpedPoly(crownSun, pane, {
    clipBox: clipBox,
    washCol: isSpandrel ? PAL.bg15 : PAL.c00,
    washOp: 215,
    strokeBrush: "liner_02",
