    clipBox: clipBox,
    washCol: isSpandrel ? PAL.b99 : PAL.bg78,
    washOp: 225,
    hatchBrush: "copic_fine",
    hatchCol: PAL.b99,
    hatchWeight: 0.6,
    hatchDist: 6,
    hatchAngle: 4
  });

  // Draw Tier 1
  let cT1Sun = drawWarpedPoly(t1Sun, pane, {
    clipBox: clipBox,
    washCol: isSpandrel ? PAL.bg49 : PAL.bg11,
    washOp: 220,
    hatchBrush: "copic_med",
    hatchCol: isSpandrel ? PAL.bg15 : PAL.wht,
    hatchWeight: 0.8,
    hatchDist: 10,
    hatchAngle: 88
  });

  let cT1Shade = drawWarpedPoly(t1Shade, pane, {
    clipBox: clipBox,
    washCol: isSpandrel ? PAL.b99 : PAL.bg78,
    washOp: 235,
    hatchBrush: "copic_wide",
    hatchCol: isSpandrel ? PAL.ink : PAL.b97,
    hatchWeight: 0.9,
    hatchDist: 11,
    hatchAngle: 90
  });

  // Draw Tier 2
  let cT2Sun = drawWarpedPoly(t2Sun, pane, {
    clipBox: clipBox,
    washCol: isSpandrel ? PAL.bg49 : PAL.bg13,
    washOp: 220,
    hatchBrush: "copic_med",
