    hatchWeight: 0.75,
    hatchDist: 9,
    hatchAngle: 88
  });

  let cT2Shade = drawWarpedPoly(t2Shade, pane, {
    clipBox: clipBox,
    washCol: isSpandrel ? PAL.bg99 : PAL.bg75,
    washOp: 230,
    hatchBrush: "copic_med",
    hatchCol: PAL.b97,
    hatchWeight: 0.8,
