      let yR = wy + 34;
      drawWarpedLine(825, wy, 1235, yR, pane, "liner_02", PAL.b99, 0.75, clipBox);
      // Glinting sky reflection strips inside dark tower windows
      if (wy % 56 === 22) {
        let wxA = 840 + ((wy * 3) % 140);
        let wxB = wxA + 85;
        let tA = (wxA - 825) / 410;
        let tB = (wxB - 825) / 410;
        let wyA = wy + tA * 34;
        let wyB = wy + tB * 34;
        drawWarpedPoly([[wxA, wyA + 5], [wxB, wyB + 5], [wxB, wyB + 19], [wxA, wyA + 19]], pane, {
