      drawWarpedLine(435, wy, 545, yMid, pane, "liner_02", PAL.b39, 0.6, clipBox);
      drawWarpedLine(545, yMid, 685, yRight, pane, "liner_02", PAL.b99, 0.7, clipBox);

      if ((Math.floor(wy / 26) + pane.row) % 2 === 0) {
        drawWarpedPoly([[442, wy + 4], [538, yMid + 4], [538, yMid + 16], [442, wy + 16]], pane, {
          clipBox: clipBox,
          washCol: isSpandrel ? PAL.bg13 : PAL.wht,
          washOp: 160
        });
      }
    }
    for (let wx = 462; wx < 680; wx += 28) {
      drawWarpedLine(wx, 458, wx, 1240, pane, "liner_005", PAL.b97, 0.5, clipBox);
    }
    drawWarpedLine(545, 452, 545, 1240, pane, "liner_05", PAL.bg10, 0.8, clipBox);
    drawWarpedLine(435, 472, 435, 1240, pane, "liner_05", PAL.b99, 0.8, clipBox);
  }

  if (cT3Sun || cT3Shade) {
    for (let wy = 795; wy <= 1220; wy += 26) {
      drawWarpedLine(245, wy, 330, wy - 14, pane, "liner_02", PAL.b39, 0.55, clipBox);
      drawWarpedLine(330, wy - 14, 435, wy - 2, pane, "liner_02", PAL.b99, 0.65, clipBox);
    }
    drawWarpedLine(330, 772, 330, 1240, pane, "liner_02", PAL.bg10, 0.7, clipBox);
    drawWarpedLine(245, 790, 245, 1240, pane, "liner_02", PAL.b99, 0.7, clipBox);
  }
}

function renderReflectedCrane(pane, clipBox, isSpandrel) {
  // Crane lives in world Y: 40 .. 460, world X: 45 .. 1060
  if (pane.row > 2) return;

  let metalDark = isSpandrel ? PAL.ink : PAL.b99;
  let metalMid  = isSpandrel ? PAL.bg78 : PAL.b39;
