  // 1. Vertical Mast Tower rising from building roof (wx: 748..778, wy: 52..195)
  drawWarpedLine(748, 52, 748, 195, pane, "liner_05", metalDark, 0.85, clipBox);
  drawWarpedLine(778, 52, 778, 195, pane, "liner_05", metalMid, 0.8, clipBox);
  drawWarpedLine(750, 52, 750, 195, pane, "liner_02", metalLit, 0.65, clipBox);
  for (let wy = 65; wy < 190; wy += 20) {
    drawWarpedLine(748, wy, 778, wy, pane, "liner_02", metalDark, 0.6, clipBox);
    drawWarpedLine(748, wy, 778, wy + 20, pane, "liner_005", metalMid, 0.55, clipBox);
    drawWarpedLine(778, wy, 748, wy + 20, pane, "liner_005", metalMid, 0.55, clipBox);
  }

  // 2. Operator Slewing Cab at (wx: 732..792, wy: 112..140)
  drawWarpedPoly([[732, 112], [792, 112], [792, 140], [732, 140]], pane, {
    clipBox: clipBox,
    washCol: metalLit,
    washOp: 220,
    strokeBrush: "liner_02",
