  });
  // Cab dark windshield
  drawWarpedPoly([[736, 116], [762, 116], [762, 132], [736, 132]], pane, {
    clipBox: clipBox,
    washCol: PAL.b99,
    washOp: 230
  });

  // 3. Long Lattice Main Jib reaching left across the sky: (748, 132) -> (55, 84)
  let jibStartX = 748, jibStartY = 132;
