function renderActiveSqueegeePane(pane) {
  let box = [pane.x, pane.y, pane.w, pane.h];

  // 1. Milky-Cyan & Frothy White Soap Film covering upper/right/lower areas of the pane
  let soapRegion = [
    [pane.x + 8, pane.y + 6],
    [pane.x + pane.w - 6, pane.y + 6],
    [pane.x + pane.w - 6, pane.y + pane.h - 8],
    [pane.x + 8, pane.y + pane.h - 8]
  ];
  drawScreenPolyClipped(soapRegion, box, {
    washCol: PAL.bg10,
    washOp: 135,
    hatchBrush: "copic_wide",
    hatchCol: PAL.wht,
    hatchWeight: 1.0,
    hatchDist: 10,
    hatchAngle: -24
  });

  // Swirling Figure-8 T-Bar Scrubber Foam Arcs
  brush.clip(box);
  for (let rowY = pane.y + 32; rowY < pane.y + pane.h - 35; rowY += 34) {
    let pts = [];
    for (let s = 0; s <= 14; s++) {
      let t = s / 14;
      let sx = lerp(pane.x + 16, pane.x + pane.w - 16, t);
      let sy = rowY + sin(t * 360 + rowY) * 16;
      pts.push([sx, sy]);
    }
    brush.set("soap_foam", PAL.wht, 1.3);
    brush.spline(pts, 0.5);
    brush.set("soap_foam", PAL.bg13, 0.85);
    brush.spline(pts.map(p => [p[0], p[1] + 5]), 0.5);
  }

  // Fine soap bubble stipple
  brush.set("water_spray", PAL.wht, 1.1);
  for (let i = 0; i < 18; i++) {
    let sx = random(pane.x + 20, pane.x + pane.w - 20);
    let sy = random(pane.y + 20, pane.y + pane.h - 30);
    brush.line(sx, sy, sx + random(-25, 25), sy + random(-15, 15));
  }
  brush.noClip();

  // 2. Carve Razor-Sharp Squeegee Cleared Swipes through the Soap Film!
  // Inside these polygons, we re-render the crystal-clear, extra-vivid dark reflection
  let swipe1 = [
    [pane.x + 14, pane.y + 14],
    [pane.x + 96, pane.y + 14],
    [pane.x + 92, pane.y + pane.h - 18],
    [pane.x + 14, pane.y + pane.h - 18]
  ];

  // Swipe 2 leads directly down to the washer's squeegee blade at (x ~ 535, y ~ 438)
  let swipe2 = [
    [pane.x + 82, pane.y + 18],
    [pane.x + 172, pane.y + 26],
    [pane.x + 128, pane.y + 158],
    [pane.x + 38, pane.y + 122]
  ];

  let swipes = [swipe1, swipe2];
  for (let s = 0; s < swipes.length; s++) {
    let sw = swipes[s];
    let swBox = getBoundingBox(sw, box);
    // Crisp dark wet-glass reflection inside the wiped path
    drawScreenPolyClipped(sw, box, {
      washCol: PAL.b97,
      washOp: 225,
      hatchBrush: "copic_med",
      hatchCol: PAL.b39,
      hatchWeight: 0.85,
      hatchDist: 9,
      hatchAngle: pane.chiselAngle
    });

    // Re-draw reflected tower & sky bands inside the cleared swipe bounding box
    drawWarpedPoly([[-80, 425], [1280, 425], [1280, 595], [-80, 595]], pane, {
      clipBox: swBox,
      washCol: PAL.bg49,
      washOp: 185
    });
    drawWarpedPoly([[435, 472], [545, 452], [545, 1250], [435, 1250]], pane, {
      clipBox: swBox,
      washCol: PAL.bg13,
      washOp: 230
    });
    drawWarpedPoly([[545, 452], [685, 468], [685, 1250], [545, 1250]], pane, {
      clipBox: swBox,
      washCol: PAL.b99,
      washOp: 240
    });
    for (let wy = 475; wy <= 660; wy += 26) {
      drawWarpedLine(435, wy, 545, wy - 18, pane, "liner_02", PAL.b39, 0.65, swBox);
      drawWarpedLine(545, wy - 18, 685, wy - 4, pane, "liner_02", PAL.b99, 0.75, swBox);
    }
  }

  // 3. Glistening Water Bead Ridges & Foam Accumulation along Squeegee Boundaries
  // Right edge of vertical swipe 1
  drawClippedLine(pane.x + 96, pane.y + 14, pane.x + 92, pane.y + pane.h - 18, box, "liner_05", PAL.b99, 0.85);
  drawClippedLine(pane.x + 98, pane.y + 14, pane.x + 94, pane.y + pane.h - 18, box, "gel_white", PAL.wht, 1.15);
  drawClippedLine(pane.x + 101, pane.y + 18, pane.x + 97, pane.y + pane.h - 22, box, "soap_foam", PAL.bg10, 1.1);

  // Top & right edge of angled swipe 2
  drawClippedLine(pane.x + 82, pane.y + 18, pane.x + 172, pane.y + 26, box, "gel_white", PAL.wht, 1.0);
  drawClippedLine(pane.x + 172, pane.y + 26, pane.x + 128, pane.y + 158, box, "liner_05", PAL.b99, 0.85);
  drawClippedLine(pane.x + 174, pane.y + 26, pane.x + 130, pane.y + 158, box, "gel_white", PAL.wht, 1.2);
  drawClippedLine(pane.x + 177, pane.y + 30, pane.x + 133, pane.y + 158, box, "soap_foam", PAL.wht, 1.3);

  // Thick frothy foam ridge pushed ahead of the active squeegee blade at (pane.x + 38..128, pane.y + 122..158)
  drawClippedLine(pane.x + 36, pane.y + 122, pane.x + 130, pane.y + 158, box, "soap_foam", PAL.wht, 1.9);
  drawClippedLine(pane.x + 36, pane.y + 125, pane.x + 130, pane.y + 161, box, "gel_white", PAL.wht, 1.3);

  // Vertical water rivulets dripping down from the squeegee blade corner
  let dripXs = [pane.x + 42, pane.x + 76, pane.x + 126, pane.x + 158];
  for (let d = 0; d < dripXs.length; d++) {
    let dx = dripXs[d];
    let dyStart = (d < 3) ? pane.y + 135 + d * 10 : pane.y + 95;
    let dyEnd = pane.y + pane.h - 4;
    drawClippedLine(dx, dyStart, dx + 2, dyEnd, box, "liner_02", PAL.b99, 0.6);
    drawClippedLine(dx + 1.5, dyStart, dx + 3.5, dyEnd, box, "gel_white", PAL.wht, 0.85);
  }

  // Pooled white/cyan soap suds along the bottom rubber glazing sill
  drawClippedLine(pane.x + 6, pane.y + pane.h - 5, pane.x + pane.w - 6, pane.y + pane.h - 5, box, "soap_foam", PAL.wht, 1.7);
  drawClippedLine(pane.x + 10, pane.y + pane.h - 3, pane.x + pane.w - 10, pane.y + pane.h - 3, box, "gel_white", PAL.bg10, 1.1);
}

