function getBoundingBox(pts, fallbackBox) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let i = 0; i < pts.length; i++) {
    minX = Math.min(minX, pts[i][0]);
    minY = Math.min(minY, pts[i][1]);
    maxX = Math.max(maxX, pts[i][0]);
    maxY = Math.max(maxY, pts[i][1]);
  }
  let x1 = Math.max(fallbackBox[0], minX);
  let y1 = Math.max(fallbackBox[1], minY);
  let x2 = Math.min(fallbackBox[0] + fallbackBox[2], maxX);
  let y2 = Math.min(fallbackBox[1] + fallbackBox[3], maxY);
  return [x1, y1, Math.max(1, x2 - x1), Math.max(1, y2 - y1)];
}

