// =============================================================================
// RIGID ARCHITECTURAL GRID OF MULLIONS & TRANSOMS (MARKER & RULED FINE-LINER)
// =============================================================================
function renderCurtainWallMullions() {
  // 1. Cast Shadow of Mullions & Transoms onto Glass Panes (gives deep 3D relief)
  for (let i = 0; i < panes.length; i++) {
    let p = panes[i];
    let shadowW = 9;
    let shadowH = 8;
    // Left mullion cast shadow on glass
    let sLeft = new brush.Polygon([
      [p.x, p.y],
      [p.x + shadowW, p.y],
      [p.x + shadowW, p.y + p.h],
      [p.x, p.y + p.h]
    ]);
    sLeft.wash(PAL.b99, 115);

    // Top transom cast shadow on glass
    let sTop = new brush.Polygon([
      [p.x, p.y],
      [p.x + p.w, p.y],
      [p.x + p.w, p.y + shadowH],
      [p.x, p.y + shadowH]
    ]);
    sTop.wash(PAL.b99, 125);
  }

  // 2. Horizontal Transoms (Extruded Anodized Aluminum Channels + Rubber Gaskets)
  for (let r = 0; r < yTransoms.length; r++) {
    let yc = yTransoms[r];
    let halfH = 8;
    let y1 = yc - halfH;
    let y2 = yc + halfH;

    // Dark EPDM rubber gasket strips top & bottom
    let gasketTop = new brush.Polygon([[0, y1 - 2.5], [1200, y1 - 2.5], [1200, y1 + 1], [0, y1 + 1]]);
    gasketTop.wash(PAL.ink, 240);
    let gasketBot = new brush.Polygon([[0, y2 - 1], [1200, y2 - 1], [1200, y2 + 2.5], [0, y2 + 2.5]]);
    gasketBot.wash(PAL.ink, 245);

    // Upper sunlit anodized face
    let faceTop = new brush.Polygon([[0, y1 + 1], [1200, y1 + 1], [1200, yc], [0, yc]]);
    faceTop.wash(PAL.c2, 235);

    // Lower shaded anodized face
    let faceBot = new brush.Polygon([[0, yc], [1200, yc], [1200, y2 - 1], [0, y2 - 1]]);
    faceBot.wash(PAL.c5, 240);

    // Ruled fine-liner extrusion lines & specular top bevel
    brush.set("gel_white", PAL.wht, 0.9);
    brush.line(0, y1 + 2, 1200, y1 + 2);
    brush.set("liner_02", PAL.ink, 0.75);
    brush.line(0, yc, 1200, yc);
    brush.line(0, y1, 1200, y1);
    brush.line(0, y2, 1200, y2);
  }

  // 3. Vertical Structural Mullions (Continuous Vertical Extrusions Slicing the Scene)
  for (let c = 0; c < xMullions.length; c++) {
    let xc = xMullions[c];
    let isMajor = (c === 0 || c === 2 || c === 3 || c === xMullions.length - 1);
    let halfW = isMajor ? 12 : 9;
    let x1 = xc - halfW;
    let x2 = xc + halfW;

    // EPDM rubber gaskets left & right
    let gLeft = new brush.Polygon([[x1 - 2.5, 0], [x1 + 1, 0], [x1 + 1, 1200], [x1 - 2.5, 1200]]);
    gLeft.wash(PAL.ink, 245);
    let gRight = new brush.Polygon([[x2 - 1, 0], [x2 + 2.5, 0], [x2 + 2.5, 1200], [x2 - 1, 1200]]);
    gRight.wash(PAL.ink, 245);

    // Left sunlit silver-grey aluminum bevel
    let mLeft = new brush.Polygon([[x1 + 1, 0], [xc - 2, 0], [xc - 2, 1200], [x1 + 1, 1200]]);
