// Hyperrealistic Graphite & White Charcoal on Mid-Grey Paper:
// Overhead view of a wet blue-grey slate roof just after hail

const ROOF_ANGLE = -13.5;
let cosR, sinR;

// Helper to guarantee a valid stroke state is always restored after noStroke() operations
function safeResetBrush() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set("HB", "#2b3036", 1);
}

// Convert roof-space coordinates (u along course, v down pitch) to world canvas (x, y)
function roofToWorld(u, v) {
  return {
    x: 600 + u * cosR - v * sinR,
    y: 600 + u * sinR + v * cosR
  };
}

// Convert world canvas (x, y) to roof-space (u, v)
function worldToRoof(x, y) {
  let dx = x - 600;
  let dy = y - 600;
  return {
    u: dx * cosR + dy * sinR,
    v: -dx * sinR + dy * cosR
  };
}

// Deterministic hash in [0, 1]
function hash2(a, b) {
  let n = Math.sin(a * 127.1 + b * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}

// Evaluate irregular lobate radius for a hailstone at angle theta (in degrees)
function hailRadiusAt(h, thetaDeg) {
  let rad = thetaDeg * (Math.PI / 180);
  let r = h.r;
  // Elliptical aspect + multi-harmonic knobby ice-lobe perturbations
  let ex = Math.cos(rad) * h.stretchX;
  let ey = Math.sin(rad) * h.stretchY;
  let base = r / Math.sqrt(ex * ex + ey * ey);
  let lobe1 = Math.sin(rad * 2 + h.p1) * h.a1;
  let lobe2 = Math.cos(rad * 3 + h.p2) * h.a2;
  let lobe3 = Math.sin(rad * h.nLobes + h.p3) * h.a3;
  let lobe4 = Math.cos(rad * (h.nLobes + 3) + h.p4) * (h.a3 * 0.45);
  return base * (1 + lobe1 + lobe2 + lobe3 + lobe4);
}

// Generate polygon vertices for a hailstone layer
function getHailPolygon(h, scaleR = 1.0, offsetX = 0, offsetY = 0, steps = 28, aspectY = 1.0, rotDeg = 0) {
  let pts = [];
  let cRot = Math.cos(rotDeg * Math.PI / 180);
  let sRot = Math.sin(rotDeg * Math.PI / 180);
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let rad = ang * (Math.PI / 180);
    let rr = hailRadiusAt(h, ang) * scaleR;
    let lx = Math.cos(rad) * rr;
    let ly = Math.sin(rad) * rr * aspectY;
    let rx = lx * cRot - ly * sRot;
    let ry = lx * sRot + ly * cRot;
    pts.push([h.x + offsetX + rx, h.y + offsetY + ry]);
  }
  return pts;
}

// Draw a washed polygon using brush.beginShape
function drawWashedPoly(pts, col, opacity, curvature = 0.35) {
  brush.noStroke();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  safeResetBrush();
}

// Draw a watercolor/bleed-filled polygon for soft smudged effects
function drawFilledPoly(pts, col, opacity, bleed = 0.12, tex = 0.35, border = 0.15, curvature = 0.4) {
  brush.noStroke();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  safeResetBrush();
}

