function draw() {
  translate(-width / 2, -height / 2);

  // 1. Mid-grey toned paper ground (cool pewter-slate paper with subtle warm earth fiber undertone)
  background("#6d7276");
  drawPaperGround();

  // 2. Construct & render overlapping wet slate roof courses
  const courseH = 212;
  const tileW = 336;
  let tiles = buildSlateRoof(courseH, tileW);
  drawSlateRoof(tiles, courseH, tileW);

  // 3. Render crustose lichen spots & muted earth mineral weathering on the slates
  drawLichenAndWeathering(tiles, courseH, tileW);

  // 4. Render wet slate sheen, water rivulets, and overlap step menisci
  drawWetRivuletsAndStepMenisci(tiles, courseH, tileW);

  // 5. Generate scattered hailstones (split strata stones, intact stones, graupel pellets, shards & beads)
  let hailData = generateHailField(courseH, tileW);

  // 6. Batch render dark meltwater pools & cast shadows first so stones sit seamlessly in their wet aprons
  drawAllMeltwaterAndShadows(hailData);

  // 7. Render micro water beads & ice spall fragments
  drawBeadsAndShards(hailData.beads, hailData.shards);

  // 8. Render small and medium/large intact hailstones (cloudy smudged cores + crisp outer shells)
  for (let s of hailData.smallStones) {
    drawIntactHailstone(s, false);
  }
  for (let m of hailData.intactStones) {
    drawIntactHailstone(m, true);
  }

  // 9. Render the hero split/fractured hailstones showing onion-ring frozen strata
  for (let sp of hailData.splitStones) {
    drawSplitHailstone(sp);
  }

  // 10. Final crisp white-charcoal specular pass & fine graphite surface grain unifying the piece
  drawFinalAtmosphericGrain();

  noLoop();
}

// ============================================================================
// LAYER 1: TONED PAPER GROUND
// ============================================================================
function drawPaperGround() {
  // Subtle large tonal washes to give depth across the roof (brighter top-left, deeper bottom-right)
  drawWashedPoly([[0, 0], [850, 0], [550, 550], [0, 750]], "#787e83", 45, 0.2);
  drawWashedPoly([[450, 450], [1200, 250], [1200, 1200], [150, 1200]], "#595e63", 55, 0.2);
  drawWashedPoly([[150, 100], [950, 200], [850, 900], [200, 800]], "#716d66", 25, 0.3); // muted earth paper warmth

  // Fine cotton rag paper tooth using diagonal graphite hatch & spray
  brush.hatchStyle("2H", "#62676b", 0.65);
  brush.hatch(11, 32, { rand: 0.12 });
  brush.noStroke();
  brush.rect(0, 0, 1200, 1200);
  safeResetBrush();

  brush.set("spray", "#585c60", 0.9);
  for (let i = 0; i < 45; i++) {
    let y = map(i, 0, 44, 15, 1185);
    brush.line(0, y + random(-8, 8), 1200, y + random(-8, 8));
  }
  brush.set("spray", "#83888d", 0.8);
  for (let i = 0; i < 35; i++) {
    let x = map(i, 0, 34, 20, 1180);
    brush.line(x + random(-8, 8), 0, x + random(-8, 8), 1200);
  }
}

// ============================================================================
// LAYER 2: OVERLAPPING WET SLATE ROOF TILES
// ============================================================================
function buildSlateRoof(courseH, tileW) {
  let tiles = [];
  const slatePalette = [
    "#5f666d", "#585f66", "#646a70", "#5b6064",
    "#626566", "#555c63", "#676b6e", "#5d6265"
  ];
  const earthWashPalette = [
    "#696259", "#726b61", "#5e5850", "#6d675f"
  ];

  for (let r = -4; r <= 4; r++) {
    let vTop = r * courseH;
    let vBot = (r + 1) * courseH;
    let stagger = (Math.abs(r) % 2 === 1) ? tileW * 0.5 : 0;

    for (let c = -3; c <= 3; c++) {
      let h = hash2(r, c);
      let h2 = hash2(r + 13, c - 7);
      let gapW = 4.5 + h * 3.5;
      let uLeft = c * tileW + stagger + gapW * 0.5;
      let uRight = (c + 1) * tileW + stagger - gapW * 0.5;

      // Build slightly irregular hand-dressed bottom edge in (u, v) space
      let botEdgeUV = [];
      let steps = 10;
      let vShift = (h - 0.5) * 5.5;
      for (let s = 0; s <= steps; s++) {
        let t = s / steps;
        let u = lerp(uLeft, uRight, t);
        let cornerChip = 0;
        if (s === 0 && h > 0.55) cornerChip = -7 - h * 9;
        if (s === steps && h2 > 0.6) cornerChip = -6 - h2 * 10;
        let waviness = (noise(r * 3.1 + t * 2.5, c * 4.7) - 0.5) * 6.5;
        botEdgeUV.push({ u: u, v: vBot + vShift + waviness + cornerChip });
      }

      tiles.push({
        r, c,
        uLeft, uRight,
        vTop, vBot: vBot + vShift,
        gapW,
        botEdgeUV,
        baseCol: slatePalette[Math.floor(h * slatePalette.length)],
        earthCol: earthWashPalette[Math.floor(h2 * earthWashPalette.length)],
        hasEarthStain: h2 > 0.38,
        cleavageDeg: ROOF_ANGLE + 14 + (h - 0.5) * 12,
        seed: h * 1000 + h2 * 100
      });
    }
  }
  return tiles;
}

function drawSlateRoof(tiles, courseH, tileW) {
  // Sort tiles from top course (lowest r) to bottom course (highest r) so overlaps layer naturally
  tiles.sort((a, b) => a.r - b.r);

  for (let tile of tiles) {
    let pTL = roofToWorld(tile.uLeft, tile.vTop);
    let pTR = roofToWorld(tile.uRight, tile.vTop);
    let polyWorld = [
      [pTL.x, pTL.y],
      [pTR.x, pTR.y]
    ];
    for (let i = tile.botEdgeUV.length - 1; i >= 0; i--) {
      let pw = roofToWorld(tile.botEdgeUV[i].u, tile.botEdgeUV[i].v);
      polyWorld.push([pw.x, pw.y]);
    }

    // Check if tile intersects canvas bounds
    let minX = 9999, maxX = -9999, minY = 9999, maxY = -9999;
    for (let pt of polyWorld) {
      if (pt[0] < minX) minX = pt[0];
      if (pt[0] > maxX) maxX = pt[0];
      if (pt[1] < minY) minY = pt[1];
      if (pt[1] > maxY) maxY = pt[1];
    }
    if (maxX < -60 || minX > 1260 || maxY < -60 || minY > 1260) continue;

    // 1. Base slate tile tone wash
    drawWashedPoly(polyWorld, tile.baseCol, 95, 0.08);

    // 2. Subtle muted-earth iron staining wash on select tiles
    if (tile.hasEarthStain) {
      let uMid = (tile.uLeft + tile.uRight) * 0.5 + random(-40, 40);
      let vMid = (tile.vTop + tile.vBot) * 0.5 + random(-30, 30);
      let stainPts = [];
      for (let a = 0; a < 8; a++) {
        let ang = (a / 8) * Math.PI * 2;
        let su = uMid + Math.cos(ang) * random(55, 125);
        let sv = vMid + Math.sin(ang) * random(35, 75);
        let wp = roofToWorld(su, sv);
        stainPts.push([wp.x, wp.y]);
      }
      drawWashedPoly(stainPts, tile.earthCol, 42, 0.35);
    }

    // 3. Dark wet dampness zone near the top of the tile (under the upper course overlap)
    let pWetBL = roofToWorld(tile.uLeft, tile.vTop + 42);
    let pWetBR = roofToWorld(tile.uRight, tile.vTop + 48);
    drawWashedPoly([[pTL.x, pTL.y], [pTR.x, pTR.y], [pWetBR.x, pWetBR.y], [pWetBL.x, pWetBL.y]], "#353b42", 110, 0.1);

    // 4. Fine cleavage lines & geological foliation across the slate face
    drawTileCleavage(tile);

    // 5. Vertical keyway joint (perpend crevice on the left side of the tile)
    drawVerticalJoint(tile);

    // 6. Riven bottom overlap step, cast shadow onto lower course, and flaky hand-split bevel
    drawBottomSlateStep(tile);
  }
}

function drawTileCleavage(tile) {
  // Subtle directional graphite hatch across the tile
  let pTL = roofToWorld(tile.uLeft + 4, tile.vTop + 6);
  let pTR = roofToWorld(tile.uRight - 4, tile.vTop + 6);
  let pBR = roofToWorld(tile.uRight - 4, tile.vBot - 6);
  let pBL = roofToWorld(tile.uLeft + 4, tile.vBot - 6);

  brush.hatchStyle("2H", "#474d54", 0.55);
  brush.hatch(9.5, tile.cleavageDeg, { rand: 0.14 });
  brush.noStroke();
  brush.beginShape(0.05);
  brush.vertex(pTL.x, pTL.y);
  brush.vertex(pTR.x, pTR.y);
  brush.vertex(pBR.x, pBR.y);
  brush.vertex(pBL.x, pBL.y);
  brush.endShape(true);
  safeResetBrush();

  // Individual fine cleavage striations (paired dark micro-step + pale pewter highlight)
  let numLines = 26;
  for (let i = 0; i < numLines; i++) {
    let vStart = lerp(tile.vTop + 10, tile.vBot - 12, i / numLines) + random(-5, 5);
    let u1 = tile.uLeft + random(4, 90);
    let u2 = u1 + random(65, 220);
    if (u2 > tile.uRight - 4) u2 = tile.uRight - 4;
    if (u2 - u1 < 25) continue;

    let slopeV = (u2 - u1) * Math.tan((tile.cleavageDeg - ROOF_ANGLE) * Math.PI / 180) * 0.32;
    let vEnd = constrain(vStart + slopeV, tile.vTop + 6, tile.vBot - 6);

    let midU = (u1 + u2) * 0.5;
    let midV = (vStart + vEnd) * 0.5 + random(-3.5, 3.5);

    let w1 = roofToWorld(u1, vStart);
    let wMid = roofToWorld(midU, midV);
    let w2 = roofToWorld(u2, vEnd);

    // Dark cleavage line
    brush.set("slate_grain", (i % 3 === 0) ? "#2d333a" : "#3e454d", random(0.55, 1.05));
    brush.spline([[w1.x, w1.y, 0.3], [wMid.x, wMid.y, 0.9], [w2.x, w2.y, 0.3]], 0.35);

    // Every few cleavage lines, add a crisp pale pewter laminar edge highlight right alongside it
    if (i % 3 === 0) {
      brush.set("2H", "#949ca4", random(0.45, 0.75));
      brush.spline([[w1.x, w1.y + 1.2, 0.2], [wMid.x, wMid.y + 1.4, 0.85], [w2.x, w2.y + 1.2, 0.2]], 0.35);
    }
  }

  // 2 prominent stepped laminar flake ledges per tile
  for (let k = 0; k < 2; k++) {
    let uA = tile.uLeft + random(15, 70);
    let uB = tile.uRight - random(15, 70);
    let vA = lerp(tile.vTop + 35, tile.vBot - 25, (k + 0.35) / 2.2) + random(-12, 12);
    let vB = constrain(vA + random(-18, 22), tile.vTop + 20, tile.vBot - 15);
    let ptsDark = [];
    let ptsLight = [];
    for (let s = 0; s <= 5; s++) {
      let t = s / 5;
      let u = lerp(uA, uB, t);
      let v = lerp(vA, vB, t) + (noise(tile.seed + s * 0.8, k * 3) - 0.5) * 9;
      let wd = roofToWorld(u, v);
      let wl = roofToWorld(u, v + 1.7);
      ptsDark.push([wd.x, wd.y, 0.4 + Math.sin(t * Math.PI) * 0.7]);
      ptsLight.push([wl.x, wl.y, 0.4 + Math.sin(t * Math.PI) * 0.7]);
    }
    brush.set("graphite_edge", "#22272d", 0.85);
    brush.spline(ptsDark, 0.4);
    brush.set("cpencil", "#a8b1b9", 0.55);
    brush.spline(ptsLight, 0.4);
  }
}

function drawVerticalJoint(tile) {
  let gap = tile.gapW;
  let jTL = roofToWorld(tile.uLeft - gap, tile.vTop);
  let jTR = roofToWorld(tile.uLeft, tile.vTop);
  let jBR = roofToWorld(tile.uLeft, tile.vBot);
  let jBL = roofToWorld(tile.uLeft - gap, tile.vBot);

  // Dark wet keyway gap between adjacent tiles
  drawWashedPoly([[jTL.x, jTL.y], [jTR.x, jTR.y], [jBR.x, jBR.y], [jBL.x, jBL.y]], "#14181d", 215, 0.05);

  // Wet darkened margin on either side of the vertical joint
  let wL = roofToWorld(tile.uLeft + 9, tile.vTop);
  let wBL = roofToWorld(tile.uLeft + 11, tile.vBot);
  drawWashedPoly([[jTR.x, jTR.y], [wL.x, wL.y], [wBL.x, wBL.y], [jBR.x, jBR.y]], "#2a3037", 95, 0.1);

  // Crisp graphite shadow edge & wet white meniscus glint in the vertical slot
  brush.set("graphite_edge", "#0e1115", 1.1);
  brush.line(jTL.x, jTL.y, jBL.x, jBL.y);
  brush.set("2B", "#1d2229", 0.9);
  brush.line(jTR.x, jTR.y, jBR.x, jBR.y);

  // Broken specular water thread along the joint lip
  brush.set("razor_white", "#dde5ec", 0.65);
  for (let s = 0; s < 3; s++) {
    let v1 = lerp(tile.vTop + 18, tile.vBot - 25, s / 3) + random(2, 14);
    let v2 = v1 + random(14, 34);
    if (v2 < tile.vBot - 8) {
      let p1 = roofToWorld(tile.uLeft + 0.8, v1);
      let p2 = roofToWorld(tile.uLeft + 0.8, v2);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }
}

function drawBottomSlateStep(tile) {
  let edge = tile.botEdgeUV;

  // 1. Deep cast shadow & pooled meltwater under the slate's bottom overlap lip
  let shadowPoly = [];
  let wetApronPoly = [];
  for (let i = 0; i < edge.length; i++) {
    let p = roofToWorld(edge[i].u, edge[i].v);
    shadowPoly.push([p.x, p.y]);
    wetApronPoly.push([p.x, p.y]);
  }
  for (let i = edge.length - 1; i >= 0; i--) {
    let shDepth = 10 + (noise(tile.r * 2 + i * 0.4, tile.c * 3) * 7);
    let wetDepth = shDepth + 12 + random(0, 8);
    let pSh = roofToWorld(edge[i].u + 2, edge[i].v + shDepth);
    let pWet = roofToWorld(edge[i].u + 3, edge[i].v + wetDepth);
    shadowPoly.push([pSh.x, pSh.y]);
    wetApronPoly.push([pWet.x, pWet.y]);
  }

  drawWashedPoly(wetApronPoly, "#2a3037", 110, 0.25);
  drawWashedPoly(shadowPoly, "#12161b", 210, 0.2);

  // 2. Hand-split bevel (riven laminar steps along the bottom edge of the upper slate)
  let bevelPoly = [];
  for (let i = 0; i < edge.length; i++) {
    let bevH = 7 + (noise(tile.seed + i * 0.6) * 8);
    let pTop = roofToWorld(edge[i].u, edge[i].v - bevH);
    bevelPoly.push([pTop.x, pTop.y]);
  }
  for (let i = edge.length - 1; i >= 0; i--) {
    let pBot = roofToWorld(edge[i].u, edge[i].v);
    bevelPoly.push([pBot.x, pBot.y]);
  }
  drawWashedPoly(bevelPoly, "#434951", 150, 0.2);

  // Draw the stepped flaky slate contours along the bottom lip
  let ptsBot = [];
  let ptsMid = [];
  let ptsTop = [];
  for (let i = 0; i < edge.length; i++) {
    let p0 = roofToWorld(edge[i].u, edge[i].v);
    let p1 = roofToWorld(edge[i].u, edge[i].v - 3.5 - (i % 2) * 2);
    let p2 = roofToWorld(edge[i].u, edge[i].v - 7.5 - ((i + 1) % 3) * 2.5);
    ptsBot.push([p0.x, p0.y, 0.9]);
    ptsMid.push([p1.x, p1.y, 0.75]);
    ptsTop.push([p2.x, p2.y, 0.6]);
  }

  brush.set("charcoal", "#101318", 0.85);
  brush.spline(ptsBot, 0.25);

  brush.set("2B", "#272c33", 0.85);
  brush.spline(ptsMid, 0.3);

  brush.set("HB", "#7e8790", 0.7);
  brush.spline(ptsTop, 0.3);

  // Light pewter highlight along the chipped bevel ledges
  for (let i = 0; i < edge.length - 1; i++) {
    if ((i + tile.c) % 2 === 0) {
      let pA = roofToWorld(edge[i].u, edge[i].v - 2.2);
      let pB = roofToWorld(edge[i + 1].u, edge[i + 1].v - 2.2);
      brush.set("cpencil", "#abb4bd", 0.65);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }
}

// ============================================================================
// LAYER 3: CRUSTOSE LICHEN SPOTS & MUTED EARTH WEATHERING
// ============================================================================
function drawLichenAndWeathering(tiles, courseH, tileW) {
  // Muted earth tones for crustose roof lichens (sage-ochre, dry bone-taupe, raw umber, pewter-earth)
  const lichenRims = ["#9e9989", "#aba595", "#8c8778", "#968e7e"];
  const lichenCores = ["#777164", "#686256", "#827c6e", "#5d584d"];
  const sporeDark = "#38342d";

  for (let tile of tiles) {
    let numColonies = Math.floor(hash2(tile.r * 7, tile.c * 11) * 3.2);
    for (let k = 0; k < numColonies; k++) {
      let u = lerp(tile.uLeft + 35, tile.uRight - 35, hash2(tile.seed + k, 19));
      let v = lerp(tile.vTop + 45, tile.vBot - 30, hash2(tile.seed + k, 37));
      let center = roofToWorld(u, v);
      if (center.x < -30 || center.x > 1230 || center.y < -30 || center.y > 1230) continue;

      let baseR = 9 + hash2(tile.seed, k * 23) * 22;
      let rimCol = lichenRims[(k + Math.abs(tile.r)) % lichenRims.length];
      let coreCol = lichenCores[(k + Math.abs(tile.c)) % lichenCores.length];

      // Scalloped crustose colony polygon
      let ptsOuter = [];
      let ptsInner = [];
      let lobes = 14;
      for (let i = 0; i < lobes; i++) {
        let ang = (i / lobes) * Math.PI * 2;
        let n = 0.72 + noise(center.x * 0.03 + Math.cos(ang), center.y * 0.03 + Math.sin(ang)) * 0.55;
        let rx = Math.cos(ang) * baseR * n * 1.15;
        let ry = Math.sin(ang) * baseR * n * 0.88;
        ptsOuter.push([center.x + rx, center.y + ry]);
        ptsInner.push([center.x + rx * 0.62, center.y + ry * 0.62]);
      }

      drawWashedPoly(ptsOuter, rimCol, 135, 0.45);
      drawWashedPoly(ptsInner, coreCol, 145, 0.4);

      // Stippled areoles & crusty rim texture in pencil
      brush.set("cpencil", "#b5b0a0", 0.55);
      for (let i = 0; i < lobes; i++) {
        let p1 = ptsOuter[i];
        let p2 = ptsOuter[(i + 1) % lobes];
        if (i % 2 === 0) {
          brush.line(p1[0], p1[1], p2[0], p2[1]);
        }
        // Small satellite crustose flecks around the main thallus
        if (i % 3 === 0) {
          let sx = p1[0] + (p1[0] - center.x) * random(0.18, 0.42);
          let sy = p1[1] + (p1[1] - center.y) * random(0.18, 0.42);
          brush.circle(sx, sy, random(1.2, 2.8), 0.35);
        }
      }

      // Tiny dark apothecia fruiting bodies in the center of the lichen patch
      brush.set("2B", sporeDark, 0.65);
      let numSpores = Math.floor(baseR * 0.55);
      for (let s = 0; s < numSpores; s++) {
        let sa = random(360);
        let sr = random(0, baseR * 0.5);
        let sx = center.x + cos(sa) * sr;
        let sy = center.y + sin(sa) * sr * 0.85;
        brush.line(sx, sy, sx + random(-1.5, 1.5), sy + random(-1.5, 1.5));
      }
    }
  }
}

// ============================================================================
// LAYER 4: WET RIVULETS & SLATE STEP MENISCI
// ============================================================================
function drawWetRivuletsAndStepMenisci(tiles, courseH, tileW) {
  for (let tile of tiles) {
    // 1–2 wet meltwater trickle streaks running down the pitch of each slate
    let numTrickles = 1 + Math.floor(hash2(tile.r * 3, tile.c * 5) * 2);
    for (let t = 0; t < numTrickles; t++) {
      let uStart = lerp(tile.uLeft + 30, tile.uRight - 30, hash2(tile.seed + t * 17, 91));
      let v1 = tile.vTop + random(5, 35);
      let v2 = tile.vBot - random(2, 25);
      let wPts = [];
      let steps = 6;
      for (let s = 0; s <= steps; s++) {
        let frac = s / steps;
        let u = uStart + (noise(tile.seed + s * 0.5, t * 9) - 0.5) * 18;
        let v = lerp(v1, v2, frac);
        let pw = roofToWorld(u, v);
        wPts.push(pw);
      }

      // Build narrow wet dark ribbon polygon
      let ribbon = [];
      for (let s = 0; s <= steps; s++) {
        ribbon.push([wPts[s].x - 4.5, wPts[s].y]);
      }
      for (let s = steps; s >= 0; s--) {
        ribbon.push([wPts[s].x + 4.5, wPts[s].y]);
      }
      drawWashedPoly(ribbon, "#282e35", 75, 0.35);

      // Hairline specular white meniscus glint along the wet trickle edge
      brush.set("razor_white", "#dce4ec", 0.55);
      for (let s = 0; s < steps; s++) {
        if (s % 2 === 0) {
          brush.line(wPts[s].x - 3.8, wPts[s].y, wPts[s + 1].x - 3.8, wPts[s + 1].y);
        }
      }
    }

    // Crisp white charcoal meniscus highlights where meltwater clings to the bottom slate step
    let edge = tile.botEdgeUV;
    for (let i = 0; i < edge.length - 1; i++) {
      let h = hash2(tile.r * 19 + i, tile.c * 29);
      if (h > 0.32) {
        let pA = roofToWorld(edge[i].u + 2, edge[i].v + 1.2);
        let pB = roofToWorld(edge[i + 1].u - 2, edge[i + 1].v + 1.2);
        if (pA.x > -20 && pA.x < 1220 && pA.y > -20 && pA.y < 1220) {
          brush.set("razor_white", "#f2f7fb", random(0.65, 1.1));
          brush.line(pA.x, pA.y, pB.x, pB.y);
        }
      }
      // Secondary wet puddle meniscus line below the shadow lip
      if (h > 0.58) {
        let pC = roofToWorld(edge[i].u + 4, edge[i].v + 9.5);
        let pD = roofToWorld(edge[i + 1].u - 4, edge[i + 1].v + 10.2);
        if (pC.x > -20 && pC.x < 1220 && pC.y > -20 && pC.y < 1220) {
          brush.set("razor_white", "#d5dfe7", 0.55);
          brush.line(pC.x, pC.y, pD.x, pD.y);
        }
      }
    }
  }
}

// ============================================================================
// LAYER 5: GENERATE HAILSTONE FIELD (PERCUSSIVE SCATTERED RHYTHM)
// ============================================================================
function makeHailstoneProps(x, y, r, isSplit = false) {
  return {
    x, y, r,
    isSplit,
    stretchX: random(0.9, 1.12),
    stretchY: random(0.88, 1.08),
    a1: random(0.03, 0.08),
    a2: random(0.02, 0.065),
    a3: random(0.015, 0.045),
    p1: random(0, Math.PI * 2),
    p2: random(0, Math.PI * 2),
    p3: random(0, Math.PI * 2),
    p4: random(0, Math.PI * 2),
    nLobes: Math.floor(random(5, 9)),
    coreScale: random(0.44, 0.66),
    coreOffX: random(-r * 0.08, r * 0.08),
    coreOffY: random(-r * 0.08, r * 0.08),
    fractureRot: random(-35, 35),
    fractureTilt: random(0.76, 0.92),
    numRings: Math.floor(random(5, 8)),
    hasCompanionCap: random() > 0.35,
    capAngle: random(20, 150) * (random() > 0.5 ? 1 : -1)
  };
}

function generateHailField(courseH, tileW) {
  let allPlaced = [];
  let splitStones = [];
  let intactStones = [];
  let smallStones = [];
  let shards = [];
  let beads = [];

  function canPlace(x, y, r, pad = 14) {
    if (x < r + 25 || x > 1200 - r - 25 || y < r + 25 || y > 1200 - r - 25) return false;
    for (let o of allPlaced) {
      let d = dist(x, y, o.x, o.y);
      if (d < r + o.r + pad) return false;
    }
    return true;
  }

  // 1. Curated Hero Split Hailstones (6 fractured stones showing concentric onion-ring strata)
  const heroSplitAnchors = [
    { x: 345, y: 310, r: 44 },
    { x: 825, y: 265, r: 37 },
    { x: 560, y: 585, r: 48 },
    { x: 245, y: 790, r: 39 },
    { x: 885, y: 735, r: 43 },
    { x: 640, y: 975, r: 34 }
  ];

  for (let anchor of heroSplitAnchors) {
    let sx = anchor.x + random(-18, 18);
    let sy = anchor.y + random(-18, 18);
    let sp = makeHailstoneProps(sx, sy, anchor.r, true);
    splitStones.push(sp);
    allPlaced.push({ x: sx, y: sy, r: anchor.r * 1.35 });

    // Generate percussive burst of angular ice shards & meltwater droplets around each split stone
    let numShards = Math.floor(random(10, 16));
    for (let k = 0; k < numShards; k++) {
      let ang = random(360);
      let d = anchor.r * random(1.18, 2.45);
      let shX = sx + cos(ang) * d;
      let shY = sy + sin(ang) * d;
      if (shX > 15 && shX < 1185 && shY > 15 && shY < 1185) {
        shards.push({
          x: shX,
          y: shY,
          r: random(2.4, 6.2),
          rot: ang + random(-30, 30)
        });
      }
    }
  }

  // 2. Medium & Large Intact Hailstones (32 stones, some caught near slate overlap steps, some on open faces)
  let attempts = 0;
  while (intactStones.length < 32 && attempts < 600) {
    attempts++;
    let r = random(14, 34);
    let x, y;
    // 45% chance to lodge just above/below a slate overlap step for authentic roof physics
    if (random() < 0.45) {
      let row = Math.floor(random(-2, 3));
      let u = random(-520, 520);
      let v = row * courseH + (random() < 0.65 ? -r * 0.85 - random(2, 10) : r * 0.95 + random(6, 18));
      let wp = roofToWorld(u, v);
      x = wp.x;
      y = wp.y;
    } else {
      x = random(55, 1145);
      y = random(55, 1145);
    }

    if (canPlace(x, y, r, 12)) {
      let st = makeHailstoneProps(x, y, r, false);
      intactStones.push(st);
      allPlaced.push({ x, y, r });
    }
  }

  // 3. Small Hailstones & Graupel Pellets (64 stones scattered & clustered along joints/steps)
  attempts = 0;
  while (smallStones.length < 64 && attempts < 900) {
    attempts++;
    let r = random(5.5, 13.0);
    let x, y;
    if (random() < 0.55) {
      // Cluster near slate steps or near larger stones
      let row = Math.floor(random(-3, 4));
      let u = random(-560, 560);
      let v = row * courseH + random(-24, 28);
      let wp = roofToWorld(u, v);
      x = wp.x;
      y = wp.y;
    } else {
      x = random(30, 1170);
      y = random(30, 1170);
    }

    if (canPlace(x, y, r, 6)) {
      let sm = makeHailstoneProps(x, y, r, false);
      smallStones.push(sm);
      allPlaced.push({ x, y, r });
    }
  }

  // 4. Meltwater Beads & Tiny Ice Pellets (130 micro beads across the wet slates and around stones)
  for (let i = 0; i < 130; i++) {
    let bx, by;
    if (i < 75 && allPlaced.length > 0) {
      // Bead near an existing hailstone's wet apron
      let ref = allPlaced[i % allPlaced.length];
      let ang = random(360);
      let distFromStone = ref.r * random(1.12, 1.85);
      bx = ref.x + cos(ang) * distFromStone;
      by = ref.y + sin(ang) * distFromStone;
    } else {
      bx = random(25, 1175);
      by = random(25, 1175);
    }
    if (bx > 15 && bx < 1185 && by > 15 && by < 1185) {
      beads.push({
        x: bx,
        y: by,
        r: random(1.8, 4.8)
      });
    }
  }

  // Sort stones top-to-bottom slightly so overlapping shadows behave naturally
  intactStones.sort((a, b) => a.y - b.y);
  smallStones.sort((a, b) => a.y - b.y);

  return { splitStones, intactStones, smallStones, shards, beads };
}

// ============================================================================
// LAYER 6: MELTWATER APRONS, CAST SHADOWS & REFRACTED CAUSTICS
// ============================================================================
function drawAllMeltwaterAndShadows(hailData) {
  // Light comes from upper-left (-52 deg), so shadows cast toward lower-right (+0.62, +0.78)
  const lx = 0.64;
  const ly = 0.76;

  let allMain = [
    ...hailData.smallStones,
    ...hailData.intactStones,
    ...hailData.splitStones
  ];

  // Pass 1: Dark wet meltwater puddles surrounding and streaming slightly down-pitch from each stone
  for (let h of allMain) {
    let r = h.r;
    let puddlePts = [];
    let steps = 20;
    for (let i = 0; i < steps; i++) {
      let ang = (i / steps) * 360;
      let rad = ang * Math.PI / 180;
      let baseR = hailRadiusAt(h, ang);
      // Elongate puddle slightly in shadow/down-pitch direction
      let dirDot = Math.cos(rad) * lx + Math.sin(rad) * ly;
      let stretch = 1.24 + Math.max(0, dirDot) * 0.42 + (noise(h.x * 0.05 + i * 0.4, h.y * 0.05) - 0.5) * 0.25;
      puddlePts.push([
        h.x + Math.cos(rad) * baseR * stretch,
        h.y + Math.sin(rad) * baseR * stretch
      ]);
    }
    drawWashedPoly(puddlePts, "#23282f", r > 16 ? 150 : 125, 0.35);

    // If split stone has a companion broken cap, give the cap its own wet puddle too
    if (h.isSplit && h.hasCompanionCap) {
      let capX = h.x + cos(h.capAngle) * h.r * 1.48;
      let capY = h.y + sin(h.capAngle) * h.r * 1.48;
      let capPuddle = [];
      for (let i = 0; i < 14; i++) {
        let a = (i / 14) * Math.PI * 2;
        let cr = h.r * 0.58 * (1 + 0.2 * Math.sin(a * 3));
        capPuddle.push([capX + Math.cos(a) * cr + lx * 5, capY + Math.sin(a) * cr + ly * 5]);
      }
      drawWashedPoly(capPuddle, "#23282f", 140, 0.35);
    }
  }

  // Pass 2: Cast shadows & bright refracted lens caustics inside the shadows
  for (let h of allMain) {
    let r = h.r;
    let shOffX = lx * r * 0.52;
    let shOffY = ly * r * 0.52;
    let shPts = getHailPolygon(h, 0.98, shOffX, shOffY, 20);
    drawWashedPoly(shPts, "#11151a", 215, 0.3);

    // Deeper contact occlusion shadow right under the lower-right rim of the stone
    let occPts = getHailPolygon(h, 0.88, lx * r * 0.24, ly * r * 0.24, 18);
    drawWashedPoly(occPts, "#0a0d10", 230, 0.3);

    // Refracted caustic heart inside the cast shadow (the ice sphere focuses sky light into its shadow!)
    if (r >= 9) {
      let cOffX = lx * r * 0.62;
      let cOffY = ly * r * 0.62;
      let causticOuter = getHailPolygon(h, 0.42, cOffX, cOffY, 14);
      drawWashedPoly(causticOuter, "#8e98a2", 125, 0.4);

      if (r >= 15) {
        let causticCore = getHailPolygon(h, 0.24, cOffX + lx * 2, cOffY + ly * 2, 12);
        drawWashedPoly(causticCore, "#ced7df", 155, 0.4);
      }
    }

    // Crisp white charcoal meniscus glints around the outer edge of the meltwater puddle
    brush.set("razor_white", "#e6eef5", r > 18 ? 0.8 : 0.55);
    let numArcs = r > 18 ? 5 : 3;
    for (let a = 0; a < numArcs; a++) {
      let startAng = (a / numArcs) * 360 + random(-20, 20);
      let span = random(18, 42);
      let a1 = startAng * Math.PI / 180;
      let a2 = (startAng + span * 0.5) * Math.PI / 180;
      let a3 = (startAng + span) * Math.PI / 180;

      let getPuddlePt = (rad) => {
        let dirDot = Math.cos(rad) * lx + Math.sin(rad) * ly;
        let rr = hailRadiusAt(h, rad * 180 / Math.PI) * (1.25 + Math.max(0, dirDot) * 0.4);
        return [h.x + Math.cos(rad) * rr, h.y + Math.sin(rad) * rr];
      };
      let p1 = getPuddlePt(a1);
      let p2 = getPuddlePt(a2);
      let p3 = getPuddlePt(a3);
      brush.spline([[p1[0], p1[1], 0.3], [p2[0], p2[1], 1.0], [p3[0], p3[1], 0.3]], 0.35);
    }
  }
}

// ============================================================================
// LAYER 7: MELTWATER BEADS & ICE SPALL SHARDS
// ============================================================================
function drawBeadsAndShards(beads, shards) {
  const lx = 0.64;
  const ly = 0.76;

  // 1. Meltwater droplets beading on the wet slate
  for (let b of beads) {
    let r = b.r;
    // Tiny dark shadow on bottom-right
    brush.noStroke();
    brush.wash("#14181e", 190);
    brush.circle(b.x + lx * r * 0.45, b.y + ly * r * 0.45, r * 0.95, 0.2);

    // Dark upper-left refraction crescent inside the water bead
    brush.wash("#2b323a", 165);
    brush.circle(b.x - lx * r * 0.15, b.y - ly * r * 0.15, r * 0.85, 0.15);

    // Luminous lower-right caustic bounce inside the water bead
    brush.wash("#aeb8c2", 150);
    brush.circle(b.x + lx * r * 0.22, b.y + ly * r * 0.22, r * 0.55, 0.15);
    safeResetBrush();

    // Crisp graphite contour
    brush.set("graphite_edge", "#1b2027", 0.55);
    brush.arc(b.x, b.y, r, -20, 160);

    // Razor-sharp white specular pinpoint on upper-left of bead
    brush.set("razor_white", "#ffffff", r > 3.0 ? 0.95 : 0.65);
    let hx = b.x - lx * r * 0.38;
    let hy = b.y - ly * r * 0.38;
    brush.line(hx - 0.7, hy + 0.5, hx + 0.8, hy - 0.6);
  }

  // 2. Angular ice spall shards around fractured hailstones
  for (let sh of shards) {
    let r = sh.r;
    let rot = sh.rot * Math.PI / 180;
    let p1 = [sh.x + Math.cos(rot) * r * 1.4, sh.y + Math.sin(rot) * r * 1.4];
    let p2 = [sh.x + Math.cos(rot + 2.1) * r * 0.9, sh.y + Math.sin(rot + 2.1) * r * 0.9];
    let p3 = [sh.x + Math.cos(rot + 3.6) * r * 1.2, sh.y + Math.sin(rot + 3.6) * r * 1.2];
    let p4 = [sh.x + Math.cos(rot + 5.0) * r * 0.75, sh.y + Math.sin(rot + 5.0) * r * 0.75];

    // Wet shadow under shard
    drawWashedPoly([
      [p1[0] + 2.5, p1[1] + 3],
      [p2[0] + 2.5, p2[1] + 3],
      [p3[0] + 2.5, p3[1] + 3],
      [p4[0] + 2.5, p4[1] + 3]
    ], "#13171d", 195, 0.05);

    // Translucent ice shard body
    drawWashedPoly([p1, p2, p3, p4], "#b4bfc8", 160, 0.05);

    // Sharp crystalline bevel edges in dark graphite & pure white charcoal
    brush.set("graphite_edge", "#252b32", 0.65);
    brush.line(p2[0], p2[1], p3[0], p3[1]);
    brush.line(p3[0], p3[1], p4[0], p4[1]);

    brush.set("razor_white", "#ffffff", 0.85);
    brush.line(p4[0], p4[1], p1[0], p1[1]);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.line(sh.x, sh.y, p1[0], p1[1]);
  }
}

// ============================================================================
// LAYER 8: INTACT HAILSTONES (CLOUDY SMUDGED CORES & CRISP CLEAR SHELLS)
// ============================================================================
function drawIntactHailstone(h, isDetailed = true) {
  let r = h.r;
  const lx = 0.64;
  const ly = 0.76;

  // 1. Translucent outer ice glaze shell (preserves mid-grey paper/slate tone with icy pewter glaze)
  let outerPts = getHailPolygon(h, 1.0, 0, 0, isDetailed ? 28 : 18);
  drawWashedPoly(outerPts, "#778088", 155, 0.35);

  // 2. Dark internal refraction zone on the upper-left inside the clear shell
  // (A clear ice sphere acts as a lens, inverting the dark wet slate behind it into the upper-left crescent)
  let darkRefractPts = getHailPolygon(h, 0.82, -lx * r * 0.14, -ly * r * 0.14, isDetailed ? 22 : 14);
  drawWashedPoly(darkRefractPts, "#363e47", 150, 0.35);

  // 3. Luminous internal bounce-light crescent along the lower-right rim of the clear shell
  let bouncePts = getHailPolygon(h, 0.84, lx * r * 0.13, ly * r * 0.13, isDetailed ? 22 : 14);
  drawWashedPoly(bouncePts, "#b5c0c9", 130, 0.35);

  // 4. Secondary faint internal growth ring for medium/large stones
  if (isDetailed && r > 17) {
    let ringPts = getHailPolygon(h, h.coreScale * 1.24, h.coreOffX * 0.5, h.coreOffY * 0.5, 22);
    drawWashedPoly(ringPts, "#cad3db", 95, 0.35);
    let ringGapPts = getHailPolygon(h, h.coreScale * 1.10, h.coreOffX * 0.7, h.coreOffY * 0.7, 20);
    drawWashedPoly(ringGapPts, "#4f5862", 110, 0.35);
  }

  // 5. Cloudy Opaque Rime Ice Core (Smudged soft in layered white charcoal & blended stump)
  let coreR = h.coreScale;
  let coreOuter = getHailPolygon(h, coreR, h.coreOffX, h.coreOffY, isDetailed ? 22 : 14);
  if (isDetailed) {
    drawFilledPoly(coreOuter, "#d4dde5", 160, 0.18, 0.3, 0.1, 0.4);
  } else {
    drawWashedPoly(coreOuter, "#d0d9e2", 170, 0.4);
  }

  let coreMid = getHailPolygon(h, coreR * 0.72, h.coreOffX - lx * r * 0.04, h.coreOffY - ly * r * 0.04, isDetailed ? 18 : 12);
  drawWashedPoly(coreMid, "#e7eff5", 195, 0.4);

  let coreHeart = getHailPolygon(h, coreR * 0.42, h.coreOffX - lx * r * 0.07, h.coreOffY - ly * r * 0.07, 12);
  drawWashedPoly(coreHeart, "#f7fbfe", 215, 0.4);

  // Soft smudged stump & white charcoal radial air-bubble texture in the cloudy core
  if (isDetailed) {
    brush.set("smudge_stump", "#eef4f9", 0.9);
    brush.circle(h.x + h.coreOffX, h.y + h.coreOffY, r * coreR * 0.65, 0.3);

    brush.set("cpencil", "#f2f7fb", 0.6);
    let numStreaks = Math.floor(r * 0.65);
    for (let s = 0; s < numStreaks; s++) {
      let ang = random(360);
      let r1 = random(0.1, coreR * 0.45) * r;
      let r2 = random(coreR * 0.55, coreR * 1.05) * r;
      brush.line(
        h.x + h.coreOffX + cos(ang) * r1,
        h.y + h.coreOffY + sin(ang) * r1,
        h.x + h.coreOffX + cos(ang) * r2,
        h.y + h.coreOffY + sin(ang) * r2
      );
    }
  }

  // 6. Crisp Graphite Contour & Internal Refraction Shading on the Clear Shell
  brush.set("graphite_edge", "#1c2128", isDetailed ? 0.85 : 0.65);
  let steps = outerPts.length;
  for (let i = 0; i < steps; i++) {
    let p1 = outerPts[i];
    let p2 = outerPts[(i + 1) % steps];
    let ang = (i / steps) * 360;
    // Emphasize the dark rim on upper-left against the bright highlight and lower-right against shadow
    if ((ang > 165 && ang < 310) || (ang > -25 && ang < 95)) {
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Subtle curved graphite hatching on the shadow-side of the dome
  if (isDetailed && r > 15) {
    brush.set("2H", "#39414a", 0.55);
    for (let k = 0; k < 5; k++) {
      let frac = map(k, 0, 4, 0.68, 0.92);
      let aStart = 195 + k * 6;
      let aEnd = 285 - k * 6;
      let aMid = (aStart + aEnd) * 0.5;
      let pA = [h.x + cos(aStart) * hailRadiusAt(h, aStart) * frac, h.y + sin(aStart) * hailRadiusAt(h, aStart) * frac, 0.3];
      let pM = [h.x + cos(aMid) * hailRadiusAt(h, aMid) * frac, h.y + sin(aMid) * hailRadiusAt(h, aMid) * frac, 0.9];
      let pB = [h.x + cos(aEnd) * hailRadiusAt(h, aEnd) * frac, h.y + sin(aEnd) * hailRadiusAt(h, aEnd) * frac, 0.3];
      brush.spline([pA, pM, pB], 0.35);
    }
  }

  // 7. Crisp Eraser-White Highlights on the Clear Outer Shell
  // Primary upper-left specular reflection arc (cut sharp right over the dark internal refraction crescent)
  let hlAngs = [205, 222, 240, 258];
  let hlPtsOuter = [];
  let hlPtsInner = [];
  for (let a of hlAngs) {
    let rr = hailRadiusAt(h, a);
    hlPtsOuter.push([h.x + cos(a) * rr * 0.87, h.y + sin(a) * rr * 0.87, 1.0]);
    hlPtsInner.push([h.x + cos(a) * rr * 0.78, h.y + sin(a) * rr * 0.78, 0.85]);
  }

  // Sharp dark contrast line hugging the inner edge of the specular highlight
  brush.set("graphite_edge", "#222830", isDetailed ? 0.8 : 0.55);
  brush.spline(hlPtsInner, 0.35);

  // Blinding white charcoal / eraser cut for the specular highlight
  brush.set("razor_white", "#ffffff", isDetailed ? 1.35 : 0.9);
  brush.spline(hlPtsOuter, 0.35);
  if (isDetailed) {
    brush.set("razor_white", "#ffffff", 1.05);
    brush.spline(hlPtsInner, 0.35);
  }

  // Secondary crisp white rim reflection along the bottom-right internal caustic edge
  let rimAngs = [20, 42, 64];
  let rimPts = [];
  for (let a of rimAngs) {
    let rr = hailRadiusAt(h, a);
    rimPts.push([h.x + cos(a) * rr * 0.93, h.y + sin(a) * rr * 0.93, 0.85]);
  }
  brush.set("razor_white", "#eff6fc", isDetailed ? 0.95 : 0.65);
  brush.spline(rimPts, 0.35);

  // Pinpoint specular glints on knobby surface lobes
  if (isDetailed) {
    brush.set("razor_white", "#ffffff", 1.1);
    for (let g = 0; g < 4; g++) {
      let ga = 185 + g * 28 + random(-6, 6);
      let gr = hailRadiusAt(h, ga) * random(0.62, 0.92);
      let gx = h.x + cos(ga) * gr;
      let gy = h.y + sin(ga) * gr;
      brush.line(gx - 1.2, gy + 0.8, gx + 1.4, gy - 0.9);
    }
  }
}

// ============================================================================
// LAYER 9: SPLIT / FRACTURED HAILSTONES (ONION-RING FROZEN STRATA)
// ============================================================================
function drawSplitHailstone(h) {
  let r = h.r;
  const lx = 0.64;
  const ly = 0.76;

  // 0. If this split hailstone has a broken companion cap/wedge lying nearby, render it first!
  if (h.hasCompanionCap) {
    drawBrokenCompanionCap(h);
  }

  // 1. Draw the 3D lower/outer hemisphere dome underneath the tilted flat fracture plane
  let domeShiftX = lx * r * 0.16;
  let domeShiftY = ly * r * 0.16;
  let domePts = getHailPolygon(h, 1.02, domeShiftX, domeShiftY, 30);
  drawWashedPoly(domePts, "#555e67", 175, 0.35);

  // Internal luminous bounce in the lower dome wall
  let domeBounce = getHailPolygon(h, 0.92, domeShiftX + lx * 3, domeShiftY + ly * 3, 26);
  drawWashedPoly(domeBounce, "#98a4af", 130, 0.35);

  // Crisp dark outer dome contour
  brush.set("graphite_edge", "#181d23", 0.95);
  for (let i = 0; i < domePts.length; i++) {
    let p1 = domePts[i];
    let p2 = domePts[(i + 1) % domePts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. THE CLEAVED CROSS-SECTION FACE: Concentric Onion-Ring Frozen Strata
  // Alternating Clear Glaze Ice rings (dark translucent slate/pewter) and Opaque Rime rings (frost white)
  let numRings = h.numRings; // 5 to 7 concentric growth layers
  let tilt = h.fractureTilt;
  let rot = h.fractureRot;

  for (let k = numRings; k >= 1; k--) {
    let tOuter = k / numRings;
    let isClearGlaze = ((numRings - k) % 2 === 0); // Outermost shell is always clear glaze ice!

    let ringPts = getHailPolygon(
      h,
      tOuter,
      h.coreOffX * (1 - tOuter),
      h.coreOffY * (1 - tOuter),
      32,
      tilt,
      rot
    );

    if (isClearGlaze) {
      // Clear Glaze Ice Stratum: dark pewter-slate showing through translucent ice
      let glazeCol = (k === numRings) ? "#3b434c" : "#2f3740";
      drawWashedPoly(ringPts, glazeCol, 195, 0.32);

      // Fine radial crystalline needles inside the clear glaze ring
      let tInner = (k - 1) / numRings;
      let innerPts = getHailPolygon(
        h,
        tInner,
        h.coreOffX * (1 - tInner),
        h.coreOffY * (1 - tInner),
        32,
        tilt,
        rot
      );

      for (let i = 0; i < 32; i++) {
        let pOut = ringPts[i];
        let pIn = innerPts[i];
        brush.set("2H", (i % 2 === 0) ? "#1f252c" : "#6c7680", 0.55);
        brush.line(pOut[0], pOut[1], pIn[0], pIn[1]);
      }

      // Delicate graphite ring boundary
      brush.set("graphite_edge", "#1c2128", 0.7);
      for (let i = 0; i < ringPts.length; i++) {
        let p1 = ringPts[i];
        let p2 = ringPts[(i + 1) % ringPts.length];
        if (i % 2 === 0 || k === numRings) {
          brush.line(p1[0], p1[1], p2[0], p2[1]);
        }
      }
    } else {
      // Opaque White Rime Ice Stratum: milky frost white smudged soft with air bubbles
      let rimeCol = (k <= 2) ? "#eef4f9" : "#d8e1e9";
      drawWashedPoly(ringPts, rimeCol, 210, 0.32);

      // Stippled & circumferential white charcoal texture along the rime band
      brush.set("cpencil", "#f7fbff", 0.75);
      for (let i = 0; i < ringPts.length; i++) {
        let p1 = ringPts[i];
        let p2 = ringPts[(i + 1) % ringPts.length];
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // 3. Central Graupel Embryo Core (The dense, smudged snow-pellet nucleus at the heart of the onion rings)
  let cx = h.x + h.coreOffX;
  let cy = h.y + h.coreOffY;
  let embryoR = (1.15 / numRings);
  let embryoPts = getHailPolygon(h, embryoR, h.coreOffX, h.coreOffY, 18, tilt, rot);

  // Dark ring immediately hugging the embryo core for high-contrast strata definition
  let embryoHalo = getHailPolygon(h, embryoR * 1.28, h.coreOffX, h.coreOffY, 20, tilt, rot);
  drawWashedPoly(embryoHalo, "#252b33", 200, 0.35);

  // Smudged soft opaque white embryo core
  drawFilledPoly(embryoPts, "#f2f7fb", 220, 0.15, 0.25, 0.1, 0.4);
  brush.set("smudge_stump", "#ffffff", 0.85);
  brush.circle(cx, cy, r * embryoR * 0.7, 0.25);

  // Subtle dimple shadow on one side of the cleaved embryo core + bright white center highlight
  brush.set("2B", "#49525c", 0.6);
  brush.arc(cx, cy, r * embryoR * 0.55, 190, 320);
  brush.set("razor_white", "#ffffff", 1.15);
  brush.circle(cx - 1.5, cy - 1.5, r * embryoR * 0.32, 0.2);

  // 4. Conchoidal Fracture Steps & Radial Stress Cracks Across the Split Face
  let rimPts = getHailPolygon(h, 1.0, 0, 0, 36, tilt, rot);
  let numCracks = 11;
  for (let c = 0; c < numCracks; c++) {
    let idx = Math.floor((c / numCracks) * rimPts.length);
    let pRim = rimPts[idx];
    let startFrac = random(0.12, 0.38);
    let sx = lerp(cx, pRim[0], startFrac);
    let sy = lerp(cy, pRim[1], startFrac);
    let mx = lerp(sx, pRim[0], 0.5) + random(-3.5, 3.5);
    let my = lerp(sy, pRim[1], 0.5) + random(-3.5, 3.5);

    // Engraved fracture bevel: sharp dark line right beside razor-white highlight
    brush.set("graphite_edge", "#1a1f26", 0.75);
    brush.spline([[sx, sy, 0.3], [mx, my, 0.9], [pRim[0], pRim[1], 0.7]], 0.25);

    brush.set("razor_white", "#ffffff", (c % 2 === 0) ? 1.05 : 0.7);
    brush.spline([[sx + 1.1, sy - 0.8, 0.3], [mx + 1.1, my - 0.8, 0.95], [pRim[0] + 1.1, pRim[1] - 0.8, 0.8]], 0.25);
  }

  // 5. Crisp Eraser-White Highlights Cut Along the Cleaved Outer Shell Rim
  for (let i = 0; i < rimPts.length; i++) {
    let p1 = rimPts[i];
    let p2 = rimPts[(i + 1) % rimPts.length];
    let ang = (i / rimPts.length) * 360;

    // Brightest razor-sharp white cuts along the upper-left fracture lip and lower-right crystalline edge
    if ((ang > 165 && ang < 315) || (ang > 10 && ang < 95)) {
      brush.set("razor_white", "#ffffff", 1.35);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    } else {
      brush.set("cpencil", "#dce5ed", 0.75);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Extra specular facet glints on the outer shell bevel below the fracture plane
  brush.set("razor_white", "#ffffff", 1.1);
  for (let i = 1; i < 8; i++) {
    let pD = domePts[i];
    let pR = rimPts[i];
    brush.line(pR[0], pR[1], lerp(pR[0], pD[0], 0.7), lerp(pR[1], pD[1], 0.7));
  }
}

function drawBrokenCompanionCap(h) {
  let capX = h.x + cos(h.capAngle) * h.r * 1.48;
  let capY = h.y + sin(h.capAngle) * h.r * 1.48;
  let cr = h.r * 0.52;
  let rot = (h.capAngle + 90) * Math.PI / 180;

  // Build crescent-wedge polygon for the broken-off cap fragment
  let outerArc = [];
  let innerChord = [];
  for (let i = 0; i <= 10; i++) {
    let t = (i / 10) * Math.PI - Math.PI * 0.5;
    let ox = capX + Math.cos(t + rot) * cr;
    let oy = capY + Math.sin(t + rot) * cr * 0.85;
    outerArc.push([ox, oy]);

    let ix = capX + Math.cos(t + rot) * cr * 0.28 + Math.sin(t * 3) * 2.5;
    let iy = capY + Math.sin(t + rot) * cr * 0.28 + Math.cos(t * 3) * 2.5;
    innerChord.push([ix, iy]);
  }

  // Cast shadow of broken cap
  let shPoly = [];
  for (let p of outerArc) shPoly.push([p[0] + 6, p[1] + 7]);
  for (let i = innerChord.length - 1; i >= 0; i--) shPoly.push([innerChord[i][0] + 6, innerChord[i][1] + 7]);
  drawWashedPoly(shPoly, "#101419", 210, 0.25);

  // Outer clear glaze shell of broken cap
  let capPoly = [...outerArc];
  for (let i = innerChord.length - 1; i >= 0; i--) capPoly.push(innerChord[i]);
  drawWashedPoly(capPoly, "#424b55", 190, 0.25);

  // Inner white rime stratum band exposed inside the broken cap
  let rimePoly = [];
  for (let i = 1; i < outerArc.length - 1; i++) {
    rimePoly.push([
      lerp(outerArc[i][0], innerChord[i][0], 0.38),
      lerp(outerArc[i][1], innerChord[i][1], 0.38)
    ]);
  }
  for (let i = innerChord.length - 2; i >= 1; i--) {
    rimePoly.push([
      lerp(outerArc[i][0], innerChord[i][0], 0.78),
      lerp(outerArc[i][1], innerChord[i][1], 0.78)
    ]);
  }
  drawWashedPoly(rimePoly, "#e4edf4", 205, 0.25);

  // Crisp graphite & razor-white fracture edges on the broken cap
  brush.set("graphite_edge", "#1a2027", 0.8);
  for (let i = 0; i < outerArc.length - 1; i++) {
    brush.line(outerArc[i][0], outerArc[i][1], outerArc[i + 1][0], outerArc[i + 1][1]);
  }
  brush.set("razor_white", "#ffffff", 1.15);
  for (let i = 0; i < innerChord.length - 1; i++) {
    brush.line(innerChord[i][0], innerChord[i][1], innerChord[i + 1][0], innerChord[i + 1][1]);
  }
  for (let i = 1; i < 6; i++) {
    brush.line(outerArc[i][0], outerArc[i][1], outerArc[i + 1][0], outerArc[i + 1][1]);
  }
}

// ============================================================================
// LAYER 10: FINAL ATMOSPHERIC GRAPHITE & FROST GRAIN
// ============================================================================
function drawFinalAtmosphericGrain() {
  // Fine frost/graphite stipple and subtle directional pencil strokes to unify the drawing surface
  brush.set("spray", "#dce4ec", 0.55);
  for (let i = 0; i < 18; i++) {
    let x1 = random(50, 1150);
    let y1 = random(50, 1150);
    brush.line(x1, y1, x1 + random(-45, 45), y1 + random(-45, 45));
  }

  brush.set("spray", "#242930", 0.5);
  for (let i = 0; i < 18; i++) {
    let x1 = random(50, 1150);
    let y1 = random(50, 1150);
    brush.line(x1, y1, x1 + random(-45, 45), y1 + random(-45, 45));
  }
}

// Hyperreal Lacquered Bento Box Half-Wrapped in Crumpled Chiyogami Paper
// Rendered with p5.js v2 + p5.brush in WEBGL

let NU = 42;
let NV = 44;
let paperGrid = [];
let paperTris = [];
let creaseRidges = [];
let lapelGrid = [];
let lapelTris = [];

// 3D -> 2D Axonometric projection parameters (seen from slightly above, cropped tight)
const ORIGIN_X = 605;
const ORIGIN_Y = 655;
const EX_X = 0.9063, EX_Y = 0.4226;   // +25 deg
const EY_X = -0.8746, EY_Y = 0.4848;  // +151 deg
const EZ_X = 0.0, EZ_Y = -0.89;

// Bento Box 3D bounds
const BOX_X0 = -350, BOX_X1 = 440;
const BOX_Y0 = -340, BOX_Y1 = 330;
const BOX_Z0 = 0,    BOX_Z1 = 285;
const LID_Z0 = 205,  LID_Z1 = 285;

// Light direction (normalized, upper-left warm raking light)
const LIGHT_DIR = normalize3([-0.52, 0.34, 0.78]);

function project3D(X, Y, Z) {
  return [
    ORIGIN_X + X * EX_X + Y * EY_X + Z * EZ_X,
    ORIGIN_Y + X * EX_Y + Y * EY_Y + Z * EZ_Y
  ];
}

function normalize3(v) {
  let m = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / m, v[1] / m, v[2] / m];
}

function cross3(a, b) {
  return [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0]
  ];
}

function sub3(a, b) {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}

function dot3(a, b) {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

// Color manipulation utilities
function hexToRgb(hex) {
  let c = hex.replace("#", "");
  if (c.length === 3) c = c[0] + c[0] + c[1] + c[1] + c[2] + c[2];
  let num = parseInt(c, 16);
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

function rgbToHex(r, g, b) {
  r = Math.max(0, Math.min(255, Math.round(r)));
  g = Math.max(0, Math.min(255, Math.round(g)));
  b = Math.max(0, Math.min(255, Math.round(b)));
  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

function mixHex(hex1, hex2, t) {
  t = Math.max(0, Math.min(1, t));
  let a = hexToRgb(hex1);
  let b = hexToRgb(hex2);
  return rgbToHex(
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  );
}

// Modulates any paper pigment color by local facet 3D light and indigo-grey valley depth
function shadePaperColor(baseHex, light, valley) {
  let c = baseHex;
  // Shadowed valleys in indigo-grey
  let valleyFactor = Math.max(0, Math.min(1, valley * 0.72 + (1 - light) * 0.48));
  if (valleyFactor > 0.05) {
    let indigoGrey = valleyFactor > 0.55 ? "#233147" : "#43536b";
    c = mixHex(c, indigoGrey, Math.min(0.82, valleyFactor * 0.85));
  }
  // Warm sheen on lit ridges
  if (light > 0.68) {
    let ridgeGlow = (light - 0.68) / 0.32;
    c = mixHex(c, "#fff7e2", Math.min(0.45, ridgeGlow * 0.38));
  }
  return c;
}

// Safe polygon helper for p5.brush (avoids brush.polygon for fills/hatches)
function drawPolyShape(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]) > 0.75) {
      clean.push(pts[i]);
    }
  }
  if (clean.length > 2) {
    let first = clean[0];
    let last = clean[clean.length - 1];
    if (Math.hypot(first[0] - last[0], first[1] - last[1]) < 0.75) {
      clean.pop();
    }
  }
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(true);
}

// Safe spline helper for p5.brush (prevents duplicate points / zero-length segments)
function safeSpline(pts, curvature = 0.45) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]) > 1.2) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curvature);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7492);
  noiseSeed(7492);
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#241510");

  // Always keep a valid stroke brush active by default
  brush.set("HB", "#241510", 1);

  // 1. Construct the 3D crumpled Chiyogami paper mesh & lapel fold
  buildChiyogamiMesh();
  buildLapelMesh();

  // 2. Render warm tabletop surface and deep ambient shadows
  drawTabletopAndShadows();

  // 3. Render the exposed glossy Urushi lacquered bento box (left/upper-left half)
  drawLacquerBentoBox();

  // 4. Render cast shadows from the crumpled paper onto the lacquer box & table
  drawPaperCastShadows();

  // 5. Render opaque gouache-like watercolor base layers of the Chiyogami paper
  drawChiyogamiBaseGouache();

  // 6. Render shadowed valleys in indigo-grey (washes + fine dry-media hatching)
  drawIndigoGreyValleys();

  // 7. Render the printed Chiyogami motifs bending & breaking over every crease:
  //    - Seigaiha waves
  //    - Leaf green pine fans, bamboo & plum branches
  //    - Vermilion cranes
  //    - Five-petaled plum blossoms
  drawSeigaihaWaves();
  drawLeafGreenFoliage();
  drawVermilionCranes();
  drawPlumBlossoms();

  // 8. Render soft sheen on every fold ridge & crisp crease breaks
  drawFoldRidgesAndSheen();

  // 9. Render the folded-back lapel flap, fibrous deckled paper edges, silk cord & gold specks
  drawFoldedLapelFlap();
  drawFibrousPaperEdges();
  drawBraidedSilkCord();
  drawMetallicGoldSpecks();

  noLoop();
}

// =============================================================================
// 1. 3D CRUMPLED CHIYOGAMI MESH GENERATION & UV PROJECTION
// =============================================================================

function buildChiyogamiMesh() {
  // Define sharp origami/crumple ridge & valley lines in (u, v) space
  // Positive amp = convex ridge catching light; Negative amp = shadowed indigo-grey valley
  creaseRidges = [
    // Major wrap & corner diagonal creases
    { u0: 0.05, v0: 0.12, u1: 0.56, v1: 0.55, amp: 24,  width: 0.085, pinch: 0.012 },
    { u0: 0.14, v0: 0.05, u1: 0.58, v1: 0.34, amp: -19, width: 0.075, pinch: -0.008 },
    { u0: 0.02, v0: 0.34, u1: 0.55, v1: 0.58, amp: -22, width: 0.080, pinch: -0.010 },
    { u0: 0.00, v0: 0.46, u1: 0.52, v1: 0.78, amp: 26,  width: 0.090, pinch: 0.014 },
    { u0: 0.22, v0: 0.20, u1: 0.88, v1: 0.46, amp: 21,  width: 0.075, pinch: 0.011 },
    { u0: 0.32, v0: 0.04, u1: 0.78, v1: 0.28, amp: -18, width: 0.070, pinch: -0.009 },
    // Corner gusset radial folds emanating from (u=0.56, v=0.55)
    { u0: 0.56, v0: 0.55, u1: 0.98, v1: 0.62, amp: 34,  width: 0.085, pinch: 0.016 },
    { u0: 0.56, v0: 0.55, u1: 0.95, v1: 0.84, amp: -32, width: 0.080, pinch: -0.015 },
    { u0: 0.56, v0: 0.55, u1: 0.82, v1: 0.98, amp: 36,  width: 0.090, pinch: 0.018 },
    { u0: 0.56, v0: 0.55, u1: 0.60, v1: 0.99, amp: -28, width: 0.075, pinch: -0.012 },
    { u0: 0.44, v0: 0.56, u1: 0.48, v1: 0.98, amp: 25,  width: 0.080, pinch: 0.012 },
    { u0: 0.25, v0: 0.56, u1: 0.18, v1: 0.96, amp: -24, width: 0.085, pinch: -0.011 },
    { u0: 0.10, v0: 0.56, u1: 0.04, v1: 0.92, amp: 22,  width: 0.075, pinch: 0.010 },
    // Cross-creases & secondary crumple facets across top, walls, and apron
    { u0: 0.08, v0: 0.28, u1: 0.44, v1: 0.14, amp: 16,  width: 0.060, pinch: 0.008 },
    { u0: 0.18, v0: 0.48, u1: 0.52, v1: 0.36, amp: -17, width: 0.065, pinch: -0.008 },
    { u0: 0.58, v0: 0.16, u1: 0.96, v1: 0.34, amp: 24,  width: 0.080, pinch: 0.012 },
    { u0: 0.58, v0: 0.38, u1: 0.98, v1: 0.50, amp: -25, width: 0.075, pinch: -0.012 },
    { u0: 0.64, v0: 0.10, u1: 0.88, v1: 0.92, amp: 19,  width: 0.070, pinch: 0.010 },
    { u0: 0.12, v0: 0.72, u1: 0.86, v1: 0.78, amp: -21, width: 0.075, pinch: -0.011 },
    { u0: 0.05, v0: 0.84, u1: 0.68, v1: 0.94, amp: 23,  width: 0.080, pinch: 0.012 },
    { u0: 0.34, v0: 0.40, u1: 0.74, v1: 0.72, amp: 18,  width: 0.065, pinch: 0.009 },
    { u0: 0.28, v0: 0.64, u1: 0.64, v1: 0.44, amp: -16, width: 0.060, pinch: -0.008 }
  ];

  paperGrid = [];
  for (let iu = 0; iu <= NU; iu++) {
    paperGrid[iu] = [];
    let u = iu / NU;
    for (let iv = 0; iv <= NV; iv++) {
      let v = iv / NV;
      let pt = evalCrumpledPaper3D(u, v);
      let scr = project3D(pt.X, pt.Y, pt.Z);
      paperGrid[iu][iv] = {
        u, v,
        X: pt.X, Y: pt.Y, Z: pt.Z,
        x: scr[0], y: scr[1],
        ridgeVal: pt.ridgeVal,
        valleyVal: pt.valleyVal
      };
    }
  }

  // Triangulate the grid and compute exact 3D facet normals and lighting
  paperTris = [];
  for (let iu = 0; iu < NU; iu++) {
    for (let iv = 0; iv < NV; iv++) {
      let p00 = paperGrid[iu][iv];
      let p10 = paperGrid[iu + 1][iv];
      let p01 = paperGrid[iu][iv + 1];
      let p11 = paperGrid[iu + 1][iv + 1];

      // Alternate diagonal direction based on local crease alignment for organic origami facets
      let diagFlip = ((iu + iv) % 2 === 0);
      if (iu > NU * 0.52 && iv > NV * 0.52) diagFlip = true; // radial alignment in corner gusset

      if (diagFlip) {
        paperTris.push(makePaperTri(p00, p10, p11, iu, iv, 0));
        paperTris.push(makePaperTri(p00, p11, p01, iu, iv, 1));
      } else {
        paperTris.push(makePaperTri(p00, p10, p01, iu, iv, 0));
        paperTris.push(makePaperTri(p10, p11, p01, iu, iv, 1));
      }
    }
  }
}

function makePaperTri(A, B, C, iu, iv, halfIdx) {
  let v1 = sub3([B.X, B.Y, B.Z], [A.X, A.Y, A.Z]);
  let v2 = sub3([C.X, C.Y, C.Z], [A.X, A.Y, A.Z]);
  let n = normalize3(cross3(v1, v2));
  // Ensure normal points outward/upward toward viewer
  if (n[2] < 0 && (A.Z > 240 || (A.X < 420 && A.Y < 300))) {
    n = [-n[0], -n[1], -n[2]];
  }
  let dotL = dot3(n, LIGHT_DIR);
  let light = Math.max(0.08, Math.min(1.0, 0.48 + dotL * 0.52));

  let avgRidge = (A.ridgeVal + B.ridgeVal + C.ridgeVal) / 3;
  let avgValley = (A.valleyVal + B.valleyVal + C.valleyVal) / 3;

  // Deepen valley shadows in concave troughs and lower wall pleats
  if (avgValley > 0.1) {
    light = Math.max(0.06, light - avgValley * 0.36);
  }
  if (avgRidge > 0.15) {
    light = Math.min(1.0, light + avgRidge * 0.22);
  }

  let cu = (A.u + B.u + C.u) / 3;
  let cv = (A.v + B.v + C.v) / 3;

  return {
    A, B, C,
    iu, iv, halfIdx,
    n, light,
    ridge: avgRidge,
    valley: avgValley,
    cu, cv,
    pts2D: [[A.x, A.y], [B.x, B.y], [C.x, C.y]]
  };
}

// Evaluates the 3D position (X, Y, Z) of point (u, v) on the half-wrapped crumpled sheet
function evalCrumpledPaper3D(u, v) {
  // Sum contributions of sharp origami creases
  let dispN = 0;
  let pinchU = 0;
  let pinchV = 0;
  let ridgeVal = 0;
  let valleyVal = 0;

  for (let i = 0; i < creaseRidges.length; i++) {
    let cr = creaseRidges[i];
    let dx = cr.u1 - cr.u0;
    let dy = cr.v1 - cr.v0;
    let len2 = dx * dx + dy * dy;
    let t = Math.max(0, Math.min(1, ((u - cr.u0) * dx + (v - cr.v0) * dy) / len2));
    let projU = cr.u0 + t * dx;
    let projV = cr.v0 + t * dy;
    let dist = Math.hypot(u - projU, v - projV);

    if (dist < cr.width) {
      // Sharp tent-like origami profile (1 - dist/w)^1.35 * sin(t * PI)
      let endFade = Math.sin(t * 180); // angleMode is DEGREES
      let profile = Math.pow(1 - dist / cr.width, 1.45) * endFade;
      dispN += cr.amp * profile;

      // Tangential pinch toward the crease line (makes pattern bend sharply over the crease)
      let dirU = (projU - u) / (dist + 0.0001);
      let dirV = (projV - v) / (dist + 0.0001);
      let pinchStrength = Math.sin((dist / cr.width) * 180) * cr.pinch * endFade;
      pinchU += dirU * pinchStrength;
      pinchV += dirV * pinchStrength;

      if (cr.amp > 0) {
        ridgeVal = Math.max(ridgeVal, profile * (cr.amp / 32));
      } else {
        valleyVal = Math.max(valleyVal, profile * (-cr.amp / 30));
      }
    }
  }

  // Secondary fine crinkle facets
  let fineCrinkle = (noise(u * 14 + 3.1, v * 14 + 7.4) - 0.48) * 14;
  dispN += fineCrinkle;
  if (fineCrinkle > 2.5) ridgeVal = Math.max(ridgeVal, (fineCrinkle - 2.5) / 10);
  if (fineCrinkle < -2.5) valleyVal = Math.max(valleyVal, (-fineCrinkle - 2.5) / 10);

  let uu = Math.max(0, Math.min(1, u + pinchU));
  let vv = Math.max(0, Math.min(1, v + pinchV));

  // Unwrapped diagonal boundary on the left (u=0): paper curves & lifts dynamically
  let leftEdgeWave = Math.sin(vv * 320 - 25) * 42 + Math.cos(vv * 540 + 40) * 18;
  let xStart = -75 + (vv - 0.35) * 195 + leftEdgeWave;

  let uFold = 0.57; // Where paper bends over the right edge (X = BOX_X1)
  let vFold = 0.55; // Where paper bends over the front-left edge (Y = BOX_Y1)

  let X, Y, Z;
  let nx = 0, ny = 0, nz = 1;

  // Map (uu, vv) across Top lid, Front-Left vertical wall, Front-Right vertical wall, and Table Apron
  if (uu <= uFold && vv <= vFold) {
    // TOP OF BENTO BOX
    let tu = uu / uFold;
    let tv = vv / vFold;
    X = xStart + tu * (BOX_X1 - xStart);
    Y = (BOX_Y0 - 25) + tv * (BOX_Y1 - (BOX_Y0 - 25));
    // Slight lift near the unwrapped edge (tu -> 0) and lapel fold
    let edgeLift = Math.pow(1 - tu, 2.2) * (26 + 18 * Math.sin(tv * 280));
    Z = BOX_Z1 + 3 + edgeLift;
    nx = -0.15 * (1 - tu);
    ny = 0.05;
    nz = 0.98;
  } else if (uu <= uFold && vv > vFold) {
    // FRONT-LEFT SIDE WALL & FOREGROUND TABLE FLARE
    let tu = uu / uFold;
    let sv = (vv - vFold) / (1 - vFold); // 0 at top bevel, 1 at bottom apron edge
    X = xStart + tu * (BOX_X1 - xStart) + sv * 28 * (tu - 0.3);

    if (sv < 0.68) {
      // Hanging down the front-left vertical face of the bento box
      let wallT = sv / 0.68;
      Y = BOX_Y1 + 5 + Math.sin(wallT * 180) * 18 + Math.pow(wallT, 1.6) * 26;
      Z = BOX_Z1 * (1 - wallT);
      nx = 0.05;
      ny = 0.94;
      nz = 0.32;
    } else {
      // Billowing out onto the tabletop
      let apronT = (sv - 0.68) / 0.32;
      Y = BOX_Y1 + 31 + apronT * 185;
      Z = Math.max(2, (1 - apronT) * 14 + Math.max(0, dispN * 0.45));
      nx = 0.0;
      ny = 0.55;
      nz = 0.83;
    }
  } else if (uu > uFold && vv <= vFold) {
    // FRONT-RIGHT SIDE WALL & RIGHT TABLE FLARE
    let su = (uu - uFold) / (1 - uFold);
    let tv = vv / vFold;
    Y = (BOX_Y0 - 25) + tv * (BOX_Y1 - (BOX_Y0 - 25)) + su * 24 * (tv - 0.4);

    if (su < 0.68) {
      let wallT = su / 0.68;
      X = BOX_X1 + 5 + Math.sin(wallT * 180) * 18 + Math.pow(wallT, 1.6) * 28;
      Z = BOX_Z1 * (1 - wallT);
      nx = 0.94;
      ny = 0.04;
      nz = 0.32;
    } else {
      let apronT = (su - 0.68) / 0.32;
      X = BOX_X1 + 33 + apronT * 190;
      Z = Math.max(2, (1 - apronT) * 14 + Math.max(0, dispN * 0.45));
      nx = 0.55;
      ny = 0.0;
      nz = 0.83;
    }
  } else {
    // FRONT-CENTER / RIGHT CORNER GUSSET (Radial origami pleats gathering around corner)
    let su = (uu - uFold) / (1 - uFold);
    let sv = (vv - vFold) / (1 - vFold);
    let r = Math.hypot(su, sv) / 1.15;
    let ang = Math.atan2(sv, su) * (180 / Math.PI); // 0 to 90 deg

    // Pleat wave across the corner gusset
    let gussetPleat = Math.sin(ang * 5) * 26 * Math.min(1, r * 1.6);
    dispN += gussetPleat;
    if (gussetPleat > 4) ridgeVal = Math.max(ridgeVal, gussetPleat / 26);
    if (gussetPleat < -4) valleyVal = Math.max(valleyVal, -gussetPleat / 26);

    if (r < 0.68) {
      let wallT = r / 0.68;
      let flare = 6 + Math.sin(wallT * 180) * 22 + Math.pow(wallT, 1.5) * 38;
      X = BOX_X1 + Math.cos(ang * Math.PI / 180) * (flare + su * 45);
      Y = BOX_Y1 + Math.sin(ang * Math.PI / 180) * (flare + sv * 45);
      Z = BOX_Z1 * (1 - wallT);
      nx = 0.68;
      ny = 0.68;
      nz = 0.28;
    } else {
      let apronT = (r - 0.68) / 0.55;
      let distOut = 44 + apronT * 210;
      X = BOX_X1 + Math.cos(ang * Math.PI / 180) * distOut;
      Y = BOX_Y1 + Math.sin(ang * Math.PI / 180) * distOut;
      Z = Math.max(2, (1 - Math.min(1, apronT)) * 18 + Math.max(0, dispN * 0.55));
      nx = 0.42;
      ny = 0.42;
      nz = 0.80;
    }
  }

  // Apply normal displacement from creases
  X += nx * dispN;
  Y += ny * dispN;
  Z = Math.max(1, Z + nz * dispN);

  return { X, Y, Z, ridgeVal: Math.min(1, ridgeVal), valleyVal: Math.min(1, valleyVal) };
}

// Fast O(1) barycentric lookup of any (u, v) point on the crumpled 3D paper mesh
function mapUV(u, v) {
  // Micro-pleat fault lines: pattern slightly shifts & breaks across sharp tucked creases!
  let uShift = u;
  let vShift = v;
  if (u + v * 0.65 > 0.68 && u + v * 0.65 < 0.695) {
    uShift += 0.008;
    vShift -= 0.006;
  }

  let uc = Math.max(0, Math.min(0.9999, uShift));
  let vc = Math.max(0, Math.min(0.9999, vShift));

  let iu = Math.floor(uc * NU);
  let iv = Math.floor(vc * NV);
  let s = uc * NU - iu;
  let t = vc * NV - iv;

  let p00 = paperGrid[iu][iv];
  let p10 = paperGrid[iu + 1][iv];
  let p01 = paperGrid[iu][iv + 1];
  let p11 = paperGrid[iu + 1][iv + 1];

  let diagFlip = ((iu + iv) % 2 === 0);
  if (iu > NU * 0.52 && iv > NV * 0.52) diagFlip = true;

  let x, y, X, Y, Z, ridge, valley;
  let triIdxBase = (iu * NV + iv) * 2;
  let tri;

  if (diagFlip) {
    if (s >= t) {
      // Triangle (p00, p10, p11): weights (1-s, s-t, t)
      let w0 = 1 - s, w1 = s - t, w2 = t;
      x = p00.x * w0 + p10.x * w1 + p11.x * w2;
      y = p00.y * w0 + p10.y * w1 + p11.y * w2;
      X = p00.X * w0 + p10.X * w1 + p11.X * w2;
      Y = p00.Y * w0 + p10.Y * w1 + p11.Y * w2;
      Z = p00.Z * w0 + p10.Z * w1 + p11.Z * w2;
      tri = paperTris[triIdxBase];
    } else {
      // Triangle (p00, p11, p01): weights (1-t, s, t-s)
      let w0 = 1 - t, w1 = s, w2 = t - s;
      x = p00.x * w0 + p11.x * w1 + p01.x * w2;
      y = p00.y * w0 + p11.y * w1 + p01.y * w2;
      X = p00.X * w0 + p11.X * w1 + p01.X * w2;
      Y = p00.Y * w0 + p11.Y * w1 + p01.Y * w2;
      Z = p00.Z * w0 + p11.Z * w1 + p01.Z * w2;
      tri = paperTris[triIdxBase + 1];
    }
  } else {
    if (s + t <= 1) {
      // Triangle (p00, p10, p01): weights (1-s-t, s, t)
      let w0 = 1 - s - t, w1 = s, w2 = t;
      x = p00.x * w0 + p10.x * w1 + p01.x * w2;
      y = p00.y * w0 + p10.y * w1 + p01.y * w2;
      X = p00.X * w0 + p10.X * w1 + p01.X * w2;
      Y = p00.Y * w0 + p10.Y * w1 + p01.Y * w2;
      Z = p00.Z * w0 + p10.Z * w1 + p01.Z * w2;
      tri = paperTris[triIdxBase];
    } else {
      // Triangle (p10, p11, p01): weights (1-t, s+t-1, 1-s)
      let w0 = 1 - t, w1 = s + t - 1, w2 = 1 - s;
      x = p10.x * w0 + p11.x * w1 + p01.x * w2;
      y = p10.y * w0 + p11.y * w1 + p01.y * w2;
      X = p10.X * w0 + p11.X * w1 + p01.X * w2;
      Y = p10.Y * w0 + p11.Y * w1 + p01.Y * w2;
      Z = p10.Z * w0 + p11.Z * w1 + p01.Z * w2;
      tri = paperTris[triIdxBase + 1];
    }
  }

  return {
    x, y, X, Y, Z,
    light: tri ? tri.light : 0.6,
    ridge: tri ? tri.ridge : 0,
    valley: tri ? tri.valley : 0
  };
}

// Projects a polygon in (u,v) space onto the 3D creased mesh, subdividing edges so they bend over creases
function projectUVPoly(uvPts, maxStep = 0.016) {
  let out = [];
  for (let i = 0; i < uvPts.length; i++) {
    let a = uvPts[i];
    let b = uvPts[(i + 1) % uvPts.length];
    let dist = Math.hypot(b[0] - a[0], b[1] - a[1]);
    let steps = Math.max(1, Math.ceil(dist / maxStep));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let u = a[0] + (b[0] - a[0]) * t;
      let v = a[1] + (b[1] - a[1]) * t;
      if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        let m = mapUV(u, v);
        out.push([m.x, m.y]);
      }
    }
  }
  return out;
}

// Projects a curve in (u,v) space onto the 3D creased mesh, breaking slightly at sharp ridge creases
function drawProjectedUVCurve(uvPts, brushName, baseColor, weight, breakAtRidges = true) {
  if (!uvPts || uvPts.length < 2) return;
  let dense = [];
  for (let i = 0; i < uvPts.length - 1; i++) {
    let a = uvPts[i];
    let b = uvPts[i + 1];
    let dist = Math.hypot(b[0] - a[0], b[1] - a[1]);
    let steps = Math.max(1, Math.ceil(dist / 0.01));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      dense.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
    }
  }
  dense.push(uvPts[uvPts.length - 1]);

  let currentSeg = [];
  let segLightSum = 0;
  let segValleySum = 0;

  for (let i = 0; i < dense.length; i++) {
    let u = dense[i][0];
    let v = dense[i][1];
    if (u < 0 || u > 1 || v < 0 || v > 1) {
      if (currentSeg.length >= 2) {
        let n = currentSeg.length;
        let col = shadePaperColor(baseColor, segLightSum / n, segValleySum / n);
        brush.set(brushName, col, weight);
        safeSpline(currentSeg, 0.35);
      }
      currentSeg = [];
      segLightSum = 0;
      segValleySum = 0;
      continue;
    }

    let m = mapUV(u, v);
    // Break the printed motif slightly across razor-sharp convex fold ridges!
    if (breakAtRidges && m.ridge > 0.62 && currentSeg.length >= 3 && (i % 5 === 0)) {
      let n = currentSeg.length;
      let col = shadePaperColor(baseColor, segLightSum / n, segValleySum / n);
      brush.set(brushName, col, weight);
      safeSpline(currentSeg, 0.35);
      currentSeg = [];
      segLightSum = 0;
      segValleySum = 0;
      continue;
    }

    currentSeg.push([m.x, m.y]);
    segLightSum += m.light;
    segValleySum += m.valley;
  }

  if (currentSeg.length >= 2) {
    let n = currentSeg.length;
    let col = shadePaperColor(baseColor, segLightSum / n, segValleySum / n);
    brush.set(brushName, col, weight);
    safeSpline(currentSeg, 0.35);
  }
}

// =============================================================================
// 2. FOLDED-BACK LAPEL FLAP MESH (ON TOP OF THE BENTO BOX)
// =============================================================================

function buildLapelMesh() {
  // A triangular/trapezoidal flap of the chiyogami paper folded back over itself near the top-center
  let LNU = 12, LNV = 14;
  lapelGrid = [];
  for (let i = 0; i <= LNU; i++) {
    lapelGrid[i] = [];
    let s = i / LNU; // 0 at the fold hinge, 1 at the curled tip
    for (let j = 0; j <= LNV; j++) {
      let t = j / LNV; // along the diagonal hinge line
      // Hinge runs from (u=0.02, v=0.14) to (u=0.18, v=0.48)
      let hingeX = -45 + t * 145;
      let hingeY = -220 + t * 290;

      // Flap folds toward the right (+X, -Y) and curls upward at its tip (s -> 1)
      let span = (1 - Math.abs(t - 0.48) * 1.35);
      let reach = Math.max(12, span * 185) * s;

      let X = hingeX + reach * 0.88 + Math.sin(t * 240) * 14 * s;
      let Y = hingeY - reach * 0.32 + Math.cos(s * 180) * 10;
      let Z = BOX_Z1 + 14 + Math.sin(s * 155) * 34 + Math.pow(s, 2.4) * 28 + Math.sin(t * 360) * 8 * s;

      let scr = project3D(X, Y, Z);
      lapelGrid[i][j] = { s, t, X, Y, Z, x: scr[0], y: scr[1] };
    }
  }

  lapelTris = [];
  for (let i = 0; i < LNU; i++) {
    for (let j = 0; j < LNV; j++) {
      let A = lapelGrid[i][j];
      let B = lapelGrid[i + 1][j];
      let C = lapelGrid[i + 1][j + 1];
      let D = lapelGrid[i][j + 1];
      lapelTris.push({ A, B, C, s: (A.s + B.s + C.s) / 3, t: (A.t + B.t + C.t) / 3 });
      lapelTris.push({ A, B: C, C: D, s: (A.s + C.s + D.s) / 3, t: (A.t + C.t + D.t) / 3 });
    }
  }
}

// =============================================================================
// 3. TABLETOP SURFACE & DEEP CAST SHADOWS
// =============================================================================

function drawTabletopAndShadows() {
  // Warm roasted-chestnut & persimmon-ochre linen tabletop washes
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.75, 0.45);

  let bgPatches = [
    { pts: [[0, 0], [1200, 0], [1200, 550], [0, 650]], col: "#3c2419", op: 190 },
    { pts: [[0, 0], [720, 0], [520, 520], [0, 480]], col: "#593624", op: 165 },
    { pts: [[0, 480], [1200, 420], [1200, 1200], [0, 1200]], col: "#2a1912", op: 210 },
    { pts: [[0, 680], [650, 780], [580, 1200], [0, 1200]], col: "#472b1d", op: 170 }
  ];

  for (let p of bgPatches) {
    brush.fill(p.col, p.op);
    drawPolyShape(p.pts);
  }
  brush.noFill();

  // Woven linen / wood-grain warm dry-media texture across tabletop
  brush.hatchStyle("2B", "#69432e", 0.9);
  brush.hatch(9, 25, { rand: 0.12 });
  drawPolyShape([[0, 0], [1200, 0], [1200, 1200], [0, 1200]]);
  brush.noHatch();

  brush.hatchStyle("charcoal", "#1a0e0a", 0.8);
  brush.hatch(14, -32, { rand: 0.18 });
  drawPolyShape([[0, 520], [1200, 480], [1200, 1200], [0, 1200]]);
  brush.noHatch();

  // Restore active stroke
  brush.set("HB", "#3c2419", 1);
}

// =============================================================================
// 4. LACQUERED BENTO BOX (JUBAKO) — EXPOSED LEFT / UPPER-LEFT HALF
// =============================================================================

function drawLacquerBentoBox() {
  // Compute 2D projected vertices of the Bento Box lower body and slightly ajar top lid
  // Lower box body: Z from 0 to LID_Z0 (205)
  let bFL0 = project3D(BOX_X0, BOX_Y1, 0);
  let bFC0 = project3D(BOX_X1, BOX_Y1, 0);
  let bFR0 = project3D(BOX_X1, BOX_Y0, 0);
  let bBL0 = project3D(BOX_X0, BOX_Y0, 0);

  let bFL1 = project3D(BOX_X0, BOX_Y1, LID_Z0);
  let bFC1 = project3D(BOX_X1, BOX_Y1, LID_Z0);
  let bBL1 = project3D(BOX_X0, BOX_Y0, LID_Z0);
  let bFR1 = project3D(BOX_X1, BOX_Y0, LID_Z0);

  // Inner vermilion lip rising to Z = 228 inside the box rim
  let rimInset = 18;
  let iFL0 = project3D(BOX_X0 + rimInset, BOX_Y1 - rimInset, LID_Z0 - 4);
  let iFC0 = project3D(BOX_X1 - rimInset, BOX_Y1 - rimInset, LID_Z0 - 4);
  let iBL0 = project3D(BOX_X0 + rimInset, BOX_Y0 + rimInset, LID_Z0 - 4);
  let iFL1 = project3D(BOX_X0 + rimInset, BOX_Y1 - rimInset, LID_Z0 + 26);
  let iFC1 = project3D(BOX_X1 - rimInset, BOX_Y1 - rimInset, LID_Z0 + 26);
  let iBL1 = project3D(BOX_X0 + rimInset, BOX_Y0 + rimInset, LID_Z0 + 26);
  let iFR1 = project3D(BOX_X1 - rimInset, BOX_Y0 + rimInset, LID_Z0 + 26);

  // Deep ambient shadow under the bento box on the left/front-left table
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.3);
  brush.fill("#0c0709", 220);
  drawPolyShape([
    [bFL0[0] - 25, bFL0[1] + 8],
    [bFC0[0] + 20, bFC0[1] + 38],
    [bFC0[0] + 60, bFC0[1] - 10],
    [bFL0[0] + 10, bFL0[1] - 25]
  ]);
  brush.noFill();

  // --- A. LOWER BOX FRONT-LEFT WALL (Deep Roiro Black-Plum Urushi Lacquer) ---
  brush.wash("#140d12", 245);
  drawPolyShape([bFL0, bFC0, bFC1, bFL1]);
  brush.noWash();

  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.45, 0.35);
  brush.fill("#1e1318", 210);
  drawPolyShape([bFL0, bFC0, bFC1, bFL1]);

  // Warm wood-table reflection glow along the lower third of the lacquer wall
  brush.fill("#4a251aa0", 130);
  drawPolyShape([
    bFL0,
    bFC0,
    [bFC0[0] * 0.7 + bFC1[0] * 0.3, bFC0[1] * 0.7 + bFC1[1] * 0.3],
    [bFL0[0] * 0.7 + bFL1[0] * 0.3, bFL0[1] * 0.7 + bFL1[1] * 0.3]
  ]);
  brush.noFill();

  // --- B. EXPOSED INNER VERMILION/PERSIMMON LACQUER RIM (SHU-NURI) ---
  // Seen because the lid is slightly shifted back/right by a few millimeters
  brush.wash("#9e1c0e", 240);
  drawPolyShape([bFL1, bFC1, iFC1, iFL1]);
  brush.noWash();

  brush.fillBleed(0.04, "in");
  brush.fill("#d9351c", 220);
  drawPolyShape([iFL0, iFC0, iFC1, iFL1]);

  brush.fill("#f0552e", 190);
  drawPolyShape([iBL1, iFL1, iFC1, iFR1]);
  brush.noFill();

  // Gold maki-e line along the inner vermilion rim
  brush.set("pen", "#f3c752", 1.3);
  brush.line(iFL1[0], iFL1[1], iFC1[0], iFC1[1]);
  brush.line(iBL1[0], iBL1[1], iFL1[0], iFL1[1]);

  // --- C. TOP LACQUERED LID (Slightly shifted to reveal the vermilion lip) ---
  let lidShiftX = -10, lidShiftY = -16, lidLiftZ = 16;
  let lFL0 = project3D(BOX_X0 + lidShiftX, BOX_Y1 + lidShiftY, LID_Z0 + lidLiftZ);
  let lFC0 = project3D(BOX_X1 + lidShiftX, BOX_Y1 + lidShiftY, LID_Z0 + lidLiftZ);
  let lBL0 = project3D(BOX_X0 + lidShiftX, BOX_Y0 + lidShiftY, LID_Z0 + lidLiftZ);
  let lFR0 = project3D(BOX_X1 + lidShiftX, BOX_Y0 + lidShiftY, LID_Z0 + lidLiftZ);

  // Chamfered top surface of the lid (inset by 12 units for crisp bevel)
  let bev = 14;
  let lFL1 = project3D(BOX_X0 + lidShiftX + bev, BOX_Y1 + lidShiftY - bev, LID_Z1 + lidLiftZ);
  let lFC1 = project3D(BOX_X1 + lidShiftX - bev, BOX_Y1 + lidShiftY - bev, LID_Z1 + lidLiftZ);
  let lBL1 = project3D(BOX_X0 + lidShiftX + bev, BOX_Y0 + lidShiftY + bev, LID_Z1 + lidLiftZ);
  let lFR1 = project3D(BOX_X1 + lidShiftX - bev, BOX_Y0 + lidShiftY + bev, LID_Z1 + lidLiftZ);

  // Lid Front-Left Side Wall
  brush.noStroke();
  brush.wash("#191016", 248);
  drawPolyShape([lFL0, lFC0, lFC1, lFL1]);
  brush.noWash();

  // Lid Left-Back Bevel Edge
  brush.wash("#2b1922", 240);
  drawPolyShape([lBL0, lFL0, lFL1, lBL1]);
  brush.noWash();

  // Lid Top Mirror-Lacquer Plane
  brush.wash("#160e14", 250);
  drawPolyShape([lBL1, lFL1, lFC1, lFR1]);
  brush.noWash();

  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.35, 0.25);
  brush.fill("#22161f", 200);
  drawPolyShape([lBL1, lFL1, lFC1, lFR1]);

  // Glossy sky/window reflection band diagonally across the mirror-black lacquer lid
  let refA = [lBL1[0] * 0.72 + lFL1[0] * 0.28, lBL1[1] * 0.72 + lFL1[1] * 0.28];
  let refB = [lBL1[0] * 0.42 + lFL1[0] * 0.58, lBL1[1] * 0.42 + lFL1[1] * 0.58];
  let refC = [lBL1[0] * 0.35 + lFR1[0] * 0.65, lBL1[1] * 0.35 + lFR1[1] * 0.65];
  let refD = [lBL1[0] * 0.65 + lFR1[0] * 0.35, lBL1[1] * 0.65 + lFR1[1] * 0.35];

  brush.fill("#3c4659", 95);
  drawPolyShape([refA, refB, refC, refD]);

  // Warm reflection of the Chiyogami paper's persimmon & cream edge in the polished lacquer lid!
  let pRef1 = project3D(-115, -240, LID_Z1 + lidLiftZ);
  let pRef2 = project3D(-30, -240, LID_Z1 + lidLiftZ);
  let pRef3 = project3D(95, 260, LID_Z1 + lidLiftZ);
  let pRef4 = project3D(-15, 260, LID_Z1 + lidLiftZ);
  brush.fill("#b83b22", 85);
  drawPolyShape([pRef1, pRef2, pRef3, pRef4]);

  let pRef5 = project3D(-75, -180, LID_Z1 + lidLiftZ);
  let pRef6 = project3D(-10, -180, LID_Z1 + lidLiftZ);
  let pRef7 = project3D(75, 200, LID_Z1 + lidLiftZ);
  let pRef8 = project3D(10, 200, LID_Z1 + lidLiftZ);
  brush.fill("#f4dec0", 65);
  drawPolyShape([pRef5, pRef6, pRef7, pRef8]);
  brush.noFill();

  // Fine glossy specular streaks across the lacquer top and bevels
  brush.hatchStyle("2H", "#5d687d", 0.7);
  brush.hatch(5, -18, { rand: 0.03 });
  drawPolyShape([refA, refB, refC, refD]);
  brush.noHatch();

  // Negoro-nuri style warm vermilion rub-through along the sharp chamfered lacquer edges
  brush.set("cpencil", "#c9341c", 1.8);
  brush.line(lBL1[0], lBL1[1], lFL1[0], lFL1[1]);
  brush.line(lFL1[0], lFL1[1], lFC1[0], lFC1[1]);
  brush.line(lBL1[0], lBL1[1], lFR1[0], lFR1[1]);
  brush.line(lFL0[0], lFL0[1], lFL1[0], lFL1[1]);
  brush.line(bFL0[0], bFL0[1], bFL1[0], bFL1[1]);

  // Razor-sharp cream/gold specular highlight along the top-front chamfer ridge
  brush.set("pen", "#fdecd0", 1.15);
  brush.line(
    lBL1[0] * 0.15 + lFL1[0] * 0.85, lBL1[1] * 0.15 + lFL1[1] * 0.85,
    lFL1[0] * 0.35 + lFC1[0] * 0.65, lFL1[1] * 0.35 + lFC1[1] * 0.65
  );
  brush.set("2H", "#ffffff", 0.9);
  brush.line(
    lFL1[0], lFL1[1],
    lFL1[0] * 0.65 + lFC1[0] * 0.35, lFL1[1] * 0.65 + lFC1[1] * 0.35
  );

  // Subtle gold maki-e crest/fern motif on the exposed upper-left lacquer corner
  drawLacquerMakieCorner();
}

function drawLacquerMakieCorner() {
  // Delicate gold maki-e karakusa / plum spray on the dark lacquer lid (upper-left)
  let baseU = -230, baseV = 80, zTop = LID_Z1 + 16;
  let c0 = project3D(baseU, baseV, zTop);
  let c1 = project3D(baseU + 55, baseV - 65, zTop);
  let c2 = project3D(baseU + 110, baseV - 110, zTop);
  let c3 = project3D(baseU + 35, baseV - 140, zTop);

  brush.set("pen", "#b88628", 1.1);
  safeSpline([c0, c1, c2], 0.5);
  safeSpline([c1, c3], 0.4);

  let blossomCenters = [
    project3D(baseU + 50, baseV - 60, zTop),
    project3D(baseU + 105, baseV - 108, zTop),
    project3D(baseU + 35, baseV - 135, zTop)
  ];
  for (let bc of blossomCenters) {
    for (let a = 0; a < 360; a += 72) {
      let px = bc[0] + Math.cos(a * Math.PI / 180) * 9;
      let py = bc[1] + Math.sin(a * Math.PI / 180) * 6;
      brush.set("cpencil", "#d8a33a", 1.4);
      brush.line(bc[0], bc[1], px, py);
    }
    brush.set("pen", "#fce088", 1.0);
    brush.circle(bc[0], bc[1], 3.5, 0.2);
  }
}

// =============================================================================
// 5. CAST SHADOWS FROM CRUMPLED PAPER ONTO LACQUER BOX & TABLE
// =============================================================================

function drawPaperCastShadows() {
  // Shadow along the unwrapped left edge of the paper onto the glossy lacquer box
  let shadowBand = [];
  for (let iv = 0; iv <= NV; iv += 2) {
    let p = paperGrid[0][iv];
    shadowBand.push([p.x, p.y]);
  }
  for (let iv = NV; iv >= 0; iv -= 2) {
    let p = paperGrid[0][iv];
    // Cast shadow falls slightly left/down onto the box and table
    let offset = iv < NV * 0.55 ? [-26, 16] : [-34, 24];
    shadowBand.push([p.x + offset[0], p.y + offset[1]]);
  }

  brush.noStroke();
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.55, 0.4);
  brush.fill("#0b0c14", 185);
  drawPolyShape(shadowBand);

  // Deep shadow underneath the billowing bottom-right paper apron on the table
  let apronShadow = [];
  for (let iu = 0; iu <= NU; iu += 2) {
    let p = paperGrid[iu][NV];
    apronShadow.push([p.x, p.y]);
  }
  for (let iv = NV; iv >= 0; iv -= 2) {
    let p = paperGrid[NU][iv];
    apronShadow.push([p.x, p.y]);
  }
  for (let iv = 0; iv <= NV; iv += 4) {
    let p = paperGrid[NU][iv];
    apronShadow.push([p.x + 28, p.y + 34]);
  }
  for (let iu = NU; iu >= 0; iu -= 4) {
    let p = paperGrid[iu][NV];
    apronShadow.push([p.x + 16, p.y + 38]);
  }

  brush.fill("#120d12", 195);
  drawPolyShape(apronShadow);
  brush.noFill();

  brush.set("HB", "#120d12", 1);
}

// =============================================================================
// 6. OPAQUE GOUACHE-LIKE WATERCOLOR BASE LAYERS OF CHIYOGAMI PAPER
// =============================================================================

// Determines the Chiyogami woodblock ground zone at paper coordinate (u, v)
function getChiyogamiZone(u, v) {
  // Flowing diagonal katazome reserve bands across the paper
  let wave1 = u * 1.15 + v * 0.85 + 0.14 * Math.sin(v * 360 * 1.8) + 0.08 * Math.cos(u * 360 * 2.2);
  let m = (wave1 * 1.65) % 1.0;
  if (m < 0) m += 1.0;

  if (m < 0.34) return "cream";       // Warm cream ground (#fbf0d5)
  if (m < 0.62) return "persimmon";   // Saturated persimmon/vermilion ground (#de4122)
  if (m < 0.84) return "indigo";      // Deep indigo seigaiha wave ground (#182d4a)
  return "green";                     // Leaf green foliage reserve (#2c633a)
}

function drawChiyogamiBaseGouache() {
  // Group triangles into color/lighting buckets so brush.fill & brush.wash batch efficiently!
  let buckets = {};

  for (let i = 0; i < paperTris.length; i++) {
    let t = paperTris[i];
    let zone = getChiyogamiZone(t.cu, t.cv);
    let baseHex;
    if (zone === "cream") baseHex = "#faeed2";
    else if (zone === "persimmon") baseHex = "#de4322";
    else if (zone === "indigo") baseHex = "#1b3352";
    else baseHex = "#2e683c";

    // Quantize light & valley into 5 levels per zone (20 batches total)
    let lQuant = Math.round(t.light * 4) / 4;
    let vQuant = Math.round(t.valley * 3) / 3;
    let shadedHex = shadePaperColor(baseHex, lQuant, vQuant);
    let key = shadedHex;

    if (!buckets[key]) buckets[key] = [];
    buckets[key].push(t.pts2D);
  }

  // First pass: opaque gouache under-wash (brush.wash) so no dark background shows through
  brush.noStroke();
  for (let hex in buckets) {
    let tris = buckets[hex];
    brush.wash(hex, 245);
    for (let i = 0; i < tris.length; i++) {
      drawPolyShape(tris[i]);
    }
    brush.noWash();
  }

  // Second pass: textured watercolor/gouache pigment layer batched by color
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.68, 0.42);
  for (let hex in buckets) {
    let tris = buckets[hex];
    brush.fill(hex, 175);
    for (let i = 0; i < tris.length; i += 2) {
      drawPolyShape(tris[i]);
    }
    brush.noFill();
  }

  // Restore stroke state
  brush.set("HB", "#233147", 1);
}

// =============================================================================
// 7. SHADOWED VALLEYS IN INDIGO-GREY (WASHES + FINE CROSS-HATCHING)
// =============================================================================

function drawIndigoGreyValleys() {
  let midValleys = [];
  let deepValleys = [];

  for (let i = 0; i < paperTris.length; i++) {
    let t = paperTris[i];
    let vScore = t.valley * 0.75 + (1 - t.light) * 0.55;
    if (vScore > 0.58) {
      deepValleys.push(t);
    } else if (vScore > 0.36) {
      midValleys.push(t);
    }
  }

  brush.noStroke();
  brush.fillBleed(0.09, "out");
  brush.fillTexture(0.65, 0.48);

  // Mid indigo-grey valley washes
  brush.fill("#3d4e66", 125);
  for (let i = 0; i < midValleys.length; i++) {
    drawPolyShape(midValleys[i].pts2D);
  }
  brush.noFill();

  // Deep shadowed valley troughs in rich indigo-grey
  brush.fill("#1e2b3e", 160);
  for (let i = 0; i < deepValleys.length; i++) {
    drawPolyShape(deepValleys[i].pts2D);
  }
  brush.noFill();

  // Fine graphite/indigo-grey hatching inside shadowed valleys to model paper grain in raking shadow
  brush.hatchStyle("2B", "#26354a", 0.75);
  brush.hatch(6, 38, { rand: 0.08 });
  for (let i = 0; i < deepValleys.length; i++) {
    drawPolyShape(deepValleys[i].pts2D);
  }
  brush.noHatch();

  brush.set("HB", "#26354a", 1);
}

// =============================================================================
// 8. PRINTED MOTIFS: GOLD-FLECKED SEIGAIHA WAVES
// =============================================================================

function drawSeigaihaWaves() {
  // Concentric scalloped wave arches across the indigo, green, and border zones of (u, v)
  let cols = 11;
  let rows = 18;
  let du = 1.0 / cols;
  let dv = 1.0 / rows;
  let waveRadius = du * 0.62;

  // Batch wave arch fills first by color
  let indigoFillPolys = [];
  let greenFillPolys = [];
  let creamFillPolys = [];
  let persimmonFillPolys = [];

  for (let r = 0; r <= rows; r++) {
    let vc = r * dv;
    let uOffset = (r % 2 === 1) ? du * 0.5 : 0;
    for (let c = -1; c <= cols; c++) {
      let uc = c * du + uOffset;
      if (uc < -0.05 || uc > 1.05 || vc < -0.05 || vc > 1.05) continue;

      let zone = getChiyogamiZone(Math.max(0, Math.min(1, uc)), Math.max(0, Math.min(1, vc)));
      if (zone !== "indigo" && zone !== "green" && ((r + c) % 3 !== 0)) continue;

      // Build scalloped fan polygon in (u, v)
      let fanUV = [[uc, vc]];
      for (let a = 195; a <= 345; a += 25) {
        let u = uc + Math.cos(a * Math.PI / 180) * waveRadius;
        let v = vc + Math.sin(a * Math.PI / 180) * (waveRadius * 0.85);
        fanUV.push([u, v]);
      }
      let projPoly = projectUVPoly(fanUV, 0.025);
      if (projPoly.length >= 3) {
        let m = mapUV(Math.max(0, Math.min(1, uc)), Math.max(0, Math.min(1, vc)));
        let item = { poly: projPoly, light: m.light, valley: m.valley };
        if (zone === "indigo") indigoFillPolys.push(item);
        else if (zone === "green") greenFillPolys.push(item);
        else if ((r + c) % 2 === 0) creamFillPolys.push(item);
        else persimmonFillPolys.push(item);
      }
    }
  }

  // Render opaque gouache wave bodies
  brush.noStroke();
  for (let item of indigoFillPolys) {
    brush.wash(shadePaperColor("#18304f", item.light, item.valley), 215);
    drawPolyShape(item.poly);
    brush.noWash();
  }
  for (let item of greenFillPolys) {
    brush.wash(shadePaperColor("#285c35", item.light, item.valley), 215);
    drawPolyShape(item.poly);
    brush.noWash();
  }
  for (let item of creamFillPolys) {
    brush.wash(shadePaperColor("#faedd0", item.light, item.valley), 210);
    drawPolyShape(item.poly);
    brush.noWash();
  }
  for (let item of persimmonFillPolys) {
    brush.wash(shadePaperColor("#d93c1f", item.light, item.valley), 210);
    drawPolyShape(item.poly);
    brush.noWash();
  }

  // Now draw the crisp fine-pen concentric wave arches that bend and break over every crease!
  for (let r = 0; r <= rows; r++) {
    let vc = r * dv;
    let uOffset = (r % 2 === 1) ? du * 0.5 : 0;
    for (let c = -1; c <= cols; c++) {
      let uc = c * du + uOffset;
      if (uc < -0.02 || uc > 1.02 || vc < -0.02 || vc > 1.02) continue;

      let zone = getChiyogamiZone(Math.max(0, Math.min(1, uc)), Math.max(0, Math.min(1, vc)));
      if (zone !== "indigo" && zone !== "green" && ((r + c) % 3 !== 0)) continue;

      let strokeCols = zone === "indigo"
        ? ["#fcf1d6", "#e6b33d", "#fcf1d6", "#4f7ca6"]
        : zone === "green"
          ? ["#fcf1d6", "#87bd69", "#e6b33d", "#18304f"]
          : ["#18304f", "#d93c1f", "#c99224", "#18304f"];

      for (let ring = 1; ring <= 4; ring++) {
        let rad = waveRadius * (ring / 4.0);
        let arcUV = [];
        for (let a = 192; a <= 348; a += 16) {
          let u = uc + Math.cos(a * Math.PI / 180) * rad;
          let v = vc + Math.sin(a * Math.PI / 180) * (rad * 0.85);
          arcUV.push([u, v]);
        }
        let col = strokeCols[ring - 1];
        let w = (ring === 4) ? 1.15 : 0.85;
        drawProjectedUVCurve(arcUV, "rotring", col, w, true);
      }
    }
  }
}

// =============================================================================
// 9. PRINTED MOTIFS: SATURATED LEAF GREEN FOLIAGE, PINE FANS & PLUM BRANCHES
// =============================================================================

function drawLeafGreenFoliage() {
  // 1. Twisted dark-indigo & umber plum branches weaving across the paper in (u, v)
  let branches = [
    [[0.04, 0.18], [0.16, 0.24], [0.28, 0.21], [0.42, 0.29], [0.54, 0.25]],
    [[0.22, 0.22], [0.26, 0.34], [0.35, 0.42]],
    [[0.06, 0.52], [0.20, 0.58], [0.36, 0.54], [0.50, 0.64], [0.64, 0.60]],
    [[0.36, 0.54], [0.40, 0.72], [0.32, 0.86]],
    [[0.52, 0.14], [0.66, 0.22], [0.80, 0.18], [0.94, 0.28]],
    [[0.62, 0.42], [0.75, 0.52], [0.86, 0.68], [0.95, 0.82]],
    [[0.14, 0.78], [0.28, 0.84], [0.46, 0.82], [0.62, 0.92]]
  ];

  for (let br of branches) {
    drawProjectedUVCurve(br, "pen", "#182436", 2.4, true);
    // Gold/ochre lichen highlight along branch edge
    let offsetBr = br.map(p => [p[0] - 0.003, p[1] - 0.003]);
    drawProjectedUVCurve(offsetBr, "rotring", "#c7942a", 0.9, true);
  }

  // 2. Stylized Japanese Matsu (Pine Fans) and Bamboo Leaf clusters in saturated Leaf Green
  let pineClusters = [
    { u: 0.14, v: 0.14, ang: -25, sc: 0.055 },
    { u: 0.38, v: 0.16, ang: 15,  sc: 0.060 },
    { u: 0.24, v: 0.38, ang: -40, sc: 0.052 },
    { u: 0.48, v: 0.44, ang: 28,  sc: 0.058 },
    { u: 0.12, v: 0.64, ang: -15, sc: 0.056 },
    { u: 0.42, v: 0.68, ang: 35,  sc: 0.062 },
    { u: 0.68, v: 0.16, ang: -30, sc: 0.058 },
    { u: 0.84, v: 0.36, ang: 20,  sc: 0.060 },
    { u: 0.64, v: 0.54, ang: -22, sc: 0.055 },
    { u: 0.82, v: 0.62, ang: 40,  sc: 0.062 },
    { u: 0.54, v: 0.82, ang: -18, sc: 0.058 },
    { u: 0.78, v: 0.86, ang: 12,  sc: 0.060 },
    { u: 0.24, v: 0.88, ang: -32, sc: 0.055 }
  ];

  for (let idx = 0; idx < pineClusters.length; idx++) {
    let pc = pineClusters[idx];
    let m = mapUV(pc.u, pc.v);
    let fanUV = [[pc.u, pc.v]];
    for (let a = -75; a <= 75; a += 15) {
      let rad = pc.sc * (0.82 + 0.18 * Math.cos(a * 2 * Math.PI / 180));
      let theta = (pc.ang + a - 90) * Math.PI / 180;
      fanUV.push([pc.u + Math.cos(theta) * rad, pc.v + Math.sin(theta) * rad * 0.88]);
    }

    let projFan = projectUVPoly(fanUV, 0.015);
    if (projFan.length >= 3) {
      brush.noStroke();
      let baseGreen = (idx % 2 === 0) ? "#296338" : "#448246";
      brush.wash(shadePaperColor(baseGreen, m.light, m.valley), 235);
      drawPolyShape(projFan);
      brush.noWash();

      // Inner lighter leaf-green crown
      let innerUV = [[pc.u, pc.v]];
      for (let a = -65; a <= 65; a += 20) {
        let rad = pc.sc * 0.58;
        let theta = (pc.ang + a - 90) * Math.PI / 180;
        innerUV.push([pc.u + Math.cos(theta) * rad, pc.v + Math.sin(theta) * rad * 0.88]);
      }
      let projInner = projectUVPoly(innerUV, 0.015);
      brush.wash(shadePaperColor("#6ea657", m.light, m.valley), 220);
      drawPolyShape(projInner);
      brush.noWash();
    }

    // Fine pen pine needles & golden scallops
    drawProjectedUVCurve(fanUV.slice(1), "rotring", "#fcf2d8", 1.0, true);
    for (let a = -60; a <= 60; a += 24) {
      let theta = (pc.ang + a - 90) * Math.PI / 180;
      let u1 = pc.u + Math.cos(theta) * pc.sc * 0.92;
      let v1 = pc.v + Math.sin(theta) * pc.sc * 0.92 * 0.88;
      drawProjectedUVCurve([[pc.u, pc.v], [u1, v1]], "rotring", "#173822", 0.85, true);
    }
  }

  // 3. Pointed Sasa (Bamboo Leaves) in rich leaf-green pairs
  let leafSeeds = 32;
  for (let i = 0; i < leafSeeds; i++) {
    let lu = 0.06 + ((i * 0.29) % 0.88);
    let lv = 0.08 + ((i * 0.17 + 0.05) % 0.86);
    let baseAng = (i * 67) % 360;
    let m = mapUV(lu, lv);

    for (let leafIdx = 0; leafIdx < 3; leafIdx++) {
      let ang = (baseAng + (leafIdx - 1) * 38) * Math.PI / 180;
      let perp = ang + Math.PI / 2;
      let len = 0.042;
      let wid = 0.010;

      let lPolyUV = [
        [lu, lv],
        [lu + Math.cos(ang) * len * 0.35 + Math.cos(perp) * wid, lv + Math.sin(ang) * len * 0.35 + Math.sin(perp) * wid],
        [lu + Math.cos(ang) * len, lv + Math.sin(ang) * len],
        [lu + Math.cos(ang) * len * 0.35 - Math.cos(perp) * wid, lv + Math.sin(ang) * len * 0.35 - Math.sin(perp) * wid]
      ];
      let pLeaf = projectUVPoly(lPolyUV, 0.015);
      if (pLeaf.length >= 3) {
        brush.noStroke();
        let gCol = (leafIdx === 1) ? "#59944e" : "#2b6339";
        brush.wash(shadePaperColor(gCol, m.light, m.valley), 230);
        drawPolyShape(pLeaf);
        brush.noWash();
      }
      // Fine pen central vein and outline
      drawProjectedUVCurve([lPolyUV[0], lPolyUV[2]], "rotring", "#e8c04b", 0.8, true);
      drawProjectedUVCurve([lPolyUV[0], lPolyUV[1], lPolyUV[2], lPolyUV[3], lPolyUV[0]], "rotring", "#163020", 0.75, true);
    }
  }
}

