function drawSingleCraneUV(cu, cv, sc, angDeg, variant) {
  let rad = angDeg * Math.PI / 180;
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);

  // Helper to transform local crane coordinates (lx, ly in [-1, 1]) to paper (u, v)
  function toUV(lx, ly) {
    return [
      cu + (lx * cosA - ly * sinA) * sc,
      cv + (lx * sinA + ly * cosA) * sc * 0.92
    ];
  }

  let m = mapUV(Math.max(0, Math.min(1, cu)), Math.max(0, Math.min(1, cv)));

  let mainBodyCol = (variant === "vermilion") ? "#e03b1e" : "#fff5de";
  let wingTipCol  = (variant === "vermilion") ? "#fcf0d5" : "#e34222";
  let accentCol   = (variant === "vermilion") ? "#f46d3b" : "#f06230";

  // 1. Left Wing (swept back graceful fan)
  let leftWingUV = [
    toUV(-0.12, -0.05),
    toUV(-0.45, -0.42),
    toUV(-0.88, -0.68),
    toUV(-1.05, -0.45),
    toUV(-0.92, -0.12),
    toUV(-0.62, 0.14),
    toUV(-0.18, 0.16)
  ];
  // 2. Right Wing (arched high)
  let rightWingUV = [
    toUV(0.12, -0.05),
    toUV(0.48, -0.48),
    toUV(0.92, -0.72),
    toUV(1.08, -0.48),
    toUV(0.94, -0.14),
    toUV(0.60, 0.14),
    toUV(0.18, 0.16)
  ];
  // 3. Body & Tail Plumes
  let bodyUV = [
    toUV(0.0, -0.28),
    toUV(0.22, -0.04),
    toUV(0.18, 0.34),
    toUV(0.0, 0.52),
    toUV(-0.18, 0.34),
    toUV(-0.22, -0.04)
  ];
  // 4. Inner Wing Feather Layer
  let innerWingL = [
    toUV(-0.10, -0.02),
    toUV(-0.42, -0.32),
    toUV(-0.72, -0.36),
    toUV(-0.64, -0.04),
    toUV(-0.16, 0.10)
  ];
  let innerWingR = [
    toUV(0.10, -0.02),
    toUV(0.44, -0.35),
    toUV(0.75, -0.38),
    toUV(0.66, -0.04),
    toUV(0.16, 0.10)
  ];

  // Fill opaque gouache layers for wings and body
  brush.noStroke();
  let pLW = projectUVPoly(leftWingUV, 0.014);
  let pRW = projectUVPoly(rightWingUV, 0.014);
  let pB  = projectUVPoly(bodyUV, 0.014);
  let pIL = projectUVPoly(innerWingL, 0.014);
  let pIR = projectUVPoly(innerWingR, 0.014);

  brush.wash(shadePaperColor(wingTipCol, m.light, m.valley), 240);
  drawPolyShape(pLW);
  drawPolyShape(pRW);
  brush.noWash();

  brush.wash(shadePaperColor(mainBodyCol, m.light, m.valley), 245);
  drawPolyShape(pIL);
  drawPolyShape(pIR);
  drawPolyShape(pB);
  brush.noWash();

  // Indigo tail feather fan at rear of body
  let tailUV = [
    toUV(-0.16, 0.32),
    toUV(0.16, 0.32),
    toUV(0.24, 0.58),
    toUV(0.0, 0.66),
    toUV(-0.24, 0.58)
  ];
  brush.wash(shadePaperColor("#18273d", m.light, m.valley), 240);
  drawPolyShape(projectUVPoly(tailUV, 0.014));
  brush.noWash();

  // Slender curving neck, head, and red crown dot
  let neckCurve = [
    toUV(0.0, -0.22),
    toUV(-0.08, -0.52),
    toUV(0.04, -0.78),
    toUV(0.24, -0.92),
    toUV(0.46, -0.96)
  ];
  drawProjectedUVCurve(neckCurve, "pen", "#fff7e2", 3.2, false);
  drawProjectedUVCurve(neckCurve, "rotring", "#162336", 1.2, true);

  // Crimson Tancho crown dot on head
  let headPt = toUV(0.24, -0.92);
  if (headPt[0] >= 0 && headPt[0] <= 1 && headPt[1] >= 0 && headPt[1] <= 1) {
    let hm = mapUV(headPt[0], headPt[1]);
    brush.set("pen", shadePaperColor("#d92618", hm.light, hm.valley), 2.8);
    brush.circle(hm.x, hm.y, 4.5, 0.15);
  }

  // Fine pen feather outlines & individual wing primaries bending over every crease
  drawProjectedUVCurve([...leftWingUV, leftWingUV[0]], "rotring", "#182436", 1.05, true);
  drawProjectedUVCurve([...rightWingUV, rightWingUV[0]], "rotring", "#182436", 1.05, true);
  drawProjectedUVCurve([...bodyUV, bodyUV[0]], "rotring", "#182436", 1.0, true);

  // Individual primary and secondary feather lines inside both wings
  for (let f = 1; f <= 5; f++) {
    let tf = f / 6.0;
    let featherL = [
      toUV(-0.18 - tf * 0.25, 0.02 - tf * 0.12),
      toUV(-0.55 - tf * 0.42, -0.08 - tf * 0.48)
    ];
    let featherR = [
      toUV(0.18 + tf * 0.25, 0.02 - tf * 0.12),
      toUV(0.55 + tf * 0.42, -0.08 - tf * 0.48)
    ];
    drawProjectedUVCurve(featherL, "rotring", accentCol, 0.9, true);
    drawProjectedUVCurve(featherR, "rotring", accentCol, 0.9, true);
    drawProjectedUVCurve(featherL, "rotring", "#182436", 0.7, true);
    drawProjectedUVCurve(featherR, "rotring", "#182436", 0.7, true);
  }

  // Trailing slender legs in dark indigo
  let leg1 = [toUV(-0.06, 0.50), toUV(-0.14, 0.88)];
  let leg2 = [toUV(0.06, 0.50), toUV(0.02, 0.90)];
  drawProjectedUVCurve(leg1, "rotring", "#182436", 0.95, true);
  drawProjectedUVCurve(leg2, "rotring", "#182436", 0.95, true);
}

