function drawSingleUmeUV(bu, bv, sc, rotDeg, petalHex, innerHex) {
  let m = mapUV(Math.max(0, Math.min(1, bu)), Math.max(0, Math.min(1, bv)));

  // Draw 5 rounded plum petals around (bu, bv)
  for (let p = 0; p < 5; p++) {
    let baseAng = rotDeg + p * 72;
    let petalUV = [[bu, bv]];
    for (let a = -32; a <= 32; a += 16) {
      let theta = (baseAng + a) * Math.PI / 180;
      let r = sc * (0.45 + 0.55 * Math.cos((a / 34) * (Math.PI / 2)));
      let u = bu + Math.cos(theta) * r;
      let v = bv + Math.sin(theta) * r * 0.90;
      petalUV.push([u, v]);
    }

    let projPetal = projectUVPoly(petalUV, 0.012);
    if (projPetal.length >= 3) {
      brush.noStroke();
      brush.wash(shadePaperColor(petalHex, m.light, m.valley), 242);
      drawPolyShape(projPetal);
      brush.noWash();
    }

    // Inner Yae-ume layered petal ring
    let innerUV = [[bu, bv]];
    for (let a = -26; a <= 26; a += 13) {
      let theta = (baseAng + a) * Math.PI / 180;
      let r = sc * 0.52 * (0.45 + 0.55 * Math.cos((a / 28) * (Math.PI / 2)));
      innerUV.push([bu + Math.cos(theta) * r, bv + Math.sin(theta) * r * 0.90]);
    }
    let projInner = projectUVPoly(innerUV, 0.012);
    if (projInner.length >= 3) {
      brush.noStroke();
      brush.wash(shadePaperColor(innerHex, m.light, m.valley), 230);
      drawPolyShape(projInner);
      brush.noWash();
    }

    // Crisp fine pen contour around each petal
    drawProjectedUVCurve([...petalUV, petalUV[0]], "rotring", "#182436", 0.85, true);
  }

  // Radiating golden stamens and pollen dots at the center of the plum blossom
  for (let s = 0; s < 10; s++) {
    let theta = (rotDeg + s * 36) * Math.PI / 180;
    let u1 = bu + Math.cos(theta) * sc * 0.36;
    let v1 = bv + Math.sin(theta) * sc * 0.36 * 0.90;
    drawProjectedUVCurve([[bu, bv], [u1, v1]], "rotring", "#e8b331", 0.8, false);
    if (u1 >= 0 && u1 <= 1 && v1 >= 0 && v1 <= 1) {
      let pm = mapUV(u1, v1);
      brush.set("pen", shadePaperColor("#fce07c", pm.light, pm.valley), 1.6);
      brush.circle(pm.x, pm.y, 1.8, 0.1);
    }
  }
}

// =============================================================================
// 12. SOFT SHEEN ON EVERY FOLD RIDGE & INDIGO-GREY CREASE VALLEYS
// =============================================================================

function drawFoldRidgesAndSheen() {
  // 1. Along every crease ridge in creaseRidges, draw soft gouache/dry-brush sheen or deep valley line
  for (let i = 0; i < creaseRidges.length; i++) {
    let cr = creaseRidges[i];
    let steps = 28;
    let pts = [];
    let ptsLeft = [];
    let ptsRight = [];

    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let u = cr.u0 + (cr.u1 - cr.u0) * t;
      let v = cr.v0 + (cr.v1 - cr.v0) * t;
      if (u < 0 || u > 1 || v < 0 || v > 1) continue;

      let m = mapUV(u, v);
      pts.push([m.x, m.y]);
      ptsLeft.push([m.x - 2.8, m.y - 2.2]);
      ptsRight.push([m.x + 2.8, m.y + 2.2]);
    }

    if (pts.length < 3) continue;

    if (cr.amp > 0) {
      // CONVEX FOLD RIDGE: Soft luminous sheen catching the light + fibrous pigment scuffing
      brush.set("marker", "#fff5dc", 2.4);
      safeSpline(pts, 0.35);

      brush.set("cpencil", "#fff9eb", 1.8);
      safeSpline(ptsLeft, 0.35);

      brush.set("2H", "#ffffff", 1.1);
      safeSpline(pts, 0.35);

      // Shadowed back-slope immediately adjacent to the ridge crest
      brush.set("2B", "#495a73", 1.2);
      safeSpline(ptsRight, 0.35);
    } else {
      // CONCAVE VALLEY FOLD: Deep shadowed indigo-grey crease trough
      brush.set("marker", "#28374d", 2.6);
      safeSpline(pts, 0.35);

      brush.set("2B", "#1a2536", 1.5);
      safeSpline(pts, 0.35);

      // Subtle lit lip emerging out of the valley
      brush.set("cpencil", "#fae8c8", 1.1);
      safeSpline(ptsLeft, 0.35);
    }
  }

  // 2. Also highlight the main box-edge fold bevels (u = 0.57 and v = 0.55) where the paper bends 90 deg
  let topFrontEdge = [];
  for (let iu = 0; iu <= Math.floor(NU * 0.58); iu++) {
    let m = mapUV(iu / NU, 0.55);
    topFrontEdge.push([m.x, m.y]);
  }
  brush.set("marker", "#fff4d8", 2.8);
  safeSpline(topFrontEdge, 0.3);
  brush.set("cpencil", "#ffffff", 1.6);
  safeSpline(topFrontEdge, 0.3);

  let topRightEdge = [];
  for (let iv = 0; iv <= Math.floor(NV * 0.56); iv++) {
    let m = mapUV(0.57, iv / NV);
    topRightEdge.push([m.x, m.y]);
  }
  brush.set("marker", "#fae8c6", 2.5);
  safeSpline(topRightEdge, 0.3);
  brush.set("cpencil", "#fff9e8", 1.4);
  safeSpline(topRightEdge, 0.3);
}

// =============================================================================
// 13. FOLDED-BACK LAPEL FLAP & FIBROUS WASHI PAPER EDGES
// =============================================================================

function drawFoldedLapelFlap() {
  // 1. Cast shadow of the folded-back lapel flap onto the main Chiyogami paper underneath
  let flapShadow = [];
  let LNU = lapelGrid.length - 1;
  let LNV = lapelGrid[0].length - 1;
  for (let j = 0; j <= LNV; j++) {
    let p = lapelGrid[0][j];
    flapShadow.push([p.x, p.y]);
  }
  for (let j = LNV; j >= 0; j--) {
    let p = lapelGrid[LNU][j];
    flapShadow.push([p.x + 22, p.y + 28]);
  }
  brush.noStroke();
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.6, 0.4);
  brush.fill("#1d2a3d", 165);
  drawPolyShape(flapShadow);
  brush.noFill();

  // 2. Render the warm cream fibrous reverse side of the washi paper flap
  for (let i = 0; i < lapelTris.length; i++) {
    let lt = lapelTris[i];
    let poly = [[lt.A.x, lt.A.y], [lt.B.x, lt.B.y], [lt.C.x, lt.C.y]];
    // Faint translucent ghosting of the vermilion & indigo print through the back of the washi paper
    let ghost = Math.sin(lt.s * 300 + lt.t * 240);
    let baseCol = "#fbf0d6";
    if (ghost > 0.35) baseCol = "#f3d5be";
    else if (ghost < -0.45) baseCol = "#dce0e6";

    // Shade near the hinge fold, brighten on the arched curl
    let lightMod = 0.65 + 0.35 * Math.sin(lt.s * 160);
    let col = shadePaperColor(baseCol, lightMod, (1 - lightMod) * 0.4);
    brush.wash(col, 248);
    drawPolyShape(poly);
    brush.noWash();
  }

  // Subtle paper fiber hatching across the lapel reverse
  let lapelOutline = [];
  for (let j = 0; j <= LNV; j++) lapelOutline.push([lapelGrid[0][j].x, lapelGrid[0][j].y]);
  for (let i = 1; i <= LNU; i++) lapelOutline.push([lapelGrid[i][LNV].x, lapelGrid[i][LNV].y]);
  for (let j = LNV - 1; j >= 0; j--) lapelOutline.push([lapelGrid[LNU][j].x, lapelGrid[LNU][j].y]);
  for (let i = LNU - 1; i >= 1; i--) lapelOutline.push([lapelGrid[i][0].x, lapelGrid[i][0].y]);

  brush.hatchStyle("2H", "#e0cba8", 0.8);
  brush.hatch(5, 42, { rand: 0.1 });
  drawPolyShape(lapelOutline);
  brush.noHatch();

  // Bright sheen along the lapel hinge ridge
  let hingePts = [];
  for (let j = 0; j <= LNV; j++) hingePts.push([lapelGrid[0][j].x, lapelGrid[0][j].y]);
  brush.set("marker", "#fff8e6", 2.8);
  safeSpline(hingePts, 0.35);
  brush.set("cpencil", "#ffffff", 1.5);
  safeSpline(hingePts, 0.35);
}

function drawFibrousPaperEdges() {
  // Render hyperreal kozo (mulberry) paper fibers along all raw/deckled edges of the Chiyogami sheet!
  let edgePaths = [];

  // 1. Left unwrapped deckled edge (u = 0, v = 0..1)
  let leftEdge = [];
  for (let iv = 0; iv <= NV; iv++) leftEdge.push(paperGrid[0][iv]);
  edgePaths.push({ pts: leftEdge, nx: -1.0, ny: 0.25 });

  // 2. Lapel outer curled edge
  let lapelOuter = [];
  let LNU = lapelGrid.length - 1;
  let LNV = lapelGrid[0].length - 1;
  for (let j = 0; j <= LNV; j++) lapelOuter.push(lapelGrid[LNU][j]);
  edgePaths.push({ pts: lapelOuter, nx: 0.85, ny: -0.45 });

  // 3. Foreground bottom apron deckled edge (v = 1, u = 0..1)
  let bottomEdge = [];
  for (let iu = 0; iu <= NU; iu++) bottomEdge.push(paperGrid[iu][NV]);
  edgePaths.push({ pts: bottomEdge, nx: 0.25, ny: 0.95 });

  // 4. Back-top edge (v = 0, u = 0..1)
  let topEdge = [];
  for (let iu = 0; iu <= NU; iu++) topEdge.push(paperGrid[iu][0]);
  edgePaths.push({ pts: topEdge, nx: -0.35, ny: -0.90 });

  for (let ep of edgePaths) {
    let pts = ep.pts;
    let spine = pts.map(p => [p.x, p.y]);

    // Soft white-cream core along the raw edge thickness of the washi sheet
    brush.set("cpencil", "#fdf3dc", 2.0);
    safeSpline(spine, 0.35);
    brush.set("2H", "#ffffff", 1.1);
    safeSpline(spine, 0.35);

    // Hundreds of tiny individual mulberry fibers feathering out from the deckled edge
    for (let i = 0; i < pts.length - 1; i++) {
      let A = pts[i];
      let B = pts[i + 1];
      let subCount = 7;
      for (let k = 0; k < subCount; k++) {
        let t = k / subCount;
        let bx = A.x + (B.x - A.x) * t;
        let by = A.y + (B.y - A.y) * t;

        let fiberLen = random(4, 14);
        let jitterAng = random(-42, 42) * Math.PI / 180;
        let dx = ep.nx * Math.cos(jitterAng) - ep.ny * Math.sin(jitterAng);
        let dy = ep.nx * Math.sin(jitterAng) + ep.ny * Math.cos(jitterAng);

        let mx = bx + dx * fiberLen * 0.55 + random(-2, 2);
        let my = by + dy * fiberLen * 0.55 + random(-2, 2);
        let ex = bx + dx * fiberLen + random(-3, 3);
        let ey = by + dy * fiberLen + random(-3, 3);

        let fCol = (k % 3 === 0) ? "#fffaf0" : (k % 3 === 1) ? "#f3e0be" : "#b8c0cc";
        brush.set("2H", fCol, random(0.45, 0.85));
        safeSpline([[bx, by], [mx, my], [ex, ey]], 0.4);
      }
    }
  }
}

