// 14. BRAIDED SILK CORD (KUMIHIMO) & METALLIC GOLD SPECKS CATCHING THE LIGHT
// =============================================================================

function drawBraidedSilkCord() {
  // A festive persimmon, indigo & gold braided kumihimo cord emerging from beneath the paper wrap
  // and draping across the glossy dark lacquer corner and onto the table
  let cord3D = [
    [-35, 110, BOX_Z1 + 18],
    [-115, 145, BOX_Z1 + 17],
    [-205, 195, BOX_Z1 + 17],
    [-255, 275, BOX_Z1 + 16],
    [-275, 326, BOX_Z1 + 8],
    [-280, 336, 210],
    [-272, 344, 110],
    [-255, 355, 22],
    [-210, 395, 5],
    [-145, 435, 4]
  ];

  let cord2D = cord3D.map(p => project3D(p[0], p[1], p[2]));
  let cordShadow = cord2D.map(p => [p[0] - 6, p[1] + 9]);

  // Cast shadow of the silk cord on the lacquer box
  brush.set("marker", "#090609", 4.2);
  safeSpline(cordShadow, 0.45);

  // Base persimmon silk braid
  brush.set("marker", "#c93018", 4.0);
  safeSpline(cord2D, 0.45);

  brush.set("cpencil", "#f25b32", 2.6);
  safeSpline(cord2D, 0.45);

  // Diagonal braided chevron texture in indigo & metallic gold along the cord
  for (let i = 0; i < cord2D.length - 1; i++) {
    let A = cord2D[i];
    let B = cord2D[i + 1];
    let dist = Math.hypot(B[0] - A[0], B[1] - A[1]);
    let steps = Math.max(2, Math.floor(dist / 7));
    let tx = (B[0] - A[0]) / (dist || 1);
    let ty = (B[1] - A[1]) / (dist || 1);
    let nx = -ty, ny = tx;

    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let cx = A[0] + (B[0] - A[0]) * t;
      let cy = A[1] + (B[1] - A[1]) * t;
      let sign = (s % 2 === 0) ? 1 : -1;
      brush.set("rotring", (s % 3 === 0) ? "#f7ce52" : "#182942", 1.1);
      brush.line(
        cx - nx * 4 * sign - tx * 2, cy - ny * 4 * sign - ty * 2,
        cx + nx * 4 * sign + tx * 2, cy + ny * 4 * sign + ty * 2
      );
    }
  }
}

function drawMetallicGoldSpecks() {
  // Small metallic gold specks (sunago & kirikane gold leaf) catching the light across waves, creases & motifs
  let goldFlakes = [];

  // 1. Concentrate gold specks along lit fold ridges and wave crests
  for (let i = 0; i < 620; i++) {
    let u = random(0.01, 0.99);
    let v = random(0.01, 0.99);
    let m = mapUV(u, v);

    // Higher probability of gold specks on wave bands and sunlit ridges
    let zone = getChiyogamiZone(u, v);
    let keepProb = 0.42;
    if (zone === "indigo" || zone === "persimmon") keepProb += 0.25;
    if (m.ridge > 0.2) keepProb += 0.35;
    if (random() > keepProb) continue;

    goldFlakes.push({
      x: m.x + random(-3, 3),
      y: m.y + random(-3, 3),
      light: m.light,
      ridge: m.ridge,
      valley: m.valley,
      sz: random(1.8, 5.2)
    });
  }

  // 2. Extra dense clusters of gold leaf specks directly along the convex fold ridges
  for (let cr of creaseRidges) {
    if (cr.amp <= 0) continue;
    for (let s = 0; s < 16; s++) {
      let t = random(0.05, 0.95);
      let u = cr.u0 + (cr.u1 - cr.u0) * t + random(-0.02, 0.02);
      let v = cr.v0 + (cr.v1 - cr.v0) * t + random(-0.02, 0.02);
      if (u < 0 || u > 1 || v < 0 || v > 1) continue;
      let m = mapUV(u, v);
      goldFlakes.push({
        x: m.x,
        y: m.y,
        light: Math.min(1, m.light + 0.2),
        ridge: 0.85,
        valley: 0,
        sz: random(2.4, 5.8)
      });
    }
  }

  // Render gold specks in 3 passes: antique gold base -> warm burnished gold -> incandescent white-gold glints
  brush.noStroke();
  for (let gf of goldFlakes) {
    let ang = random(360) * Math.PI / 180;
    let r1 = gf.sz;
    let r2 = gf.sz * random(0.55, 0.95);
    let flakePoly = [
      [gf.x + Math.cos(ang) * r1, gf.y + Math.sin(ang) * r1],
      [gf.x + Math.cos(ang + 1.6) * r2, gf.y + Math.sin(ang + 1.6) * r2],
      [gf.x + Math.cos(ang + 3.1) * r1, gf.y + Math.sin(ang + 3.1) * r1],
      [gf.x + Math.cos(ang + 4.7) * r2, gf.y + Math.sin(ang + 4.7) * r2]
    ];

    let goldCol = "#b8821c";
    if (gf.valley > 0.35) goldCol = "#7d5918";
    else if (gf.light > 0.72 || gf.ridge > 0.4) goldCol = "#f5c842";
    else goldCol = "#daa028";

    brush.wash(goldCol, 240);
    drawPolyShape(flakePoly);
    brush.noWash();
  }

  // Crisp bright gold-leaf facets & specular pinpoints where specks catch the direct light
  for (let gf of goldFlakes) {
    if (gf.light > 0.64 || gf.ridge > 0.35) {
      brush.set("pen", "#ffe885", 1.35);
      brush.circle(gf.x, gf.y, gf.sz * 0.48, 0.2);

      if (gf.light > 0.78 || gf.ridge > 0.6) {
        brush.set("rotring", "#ffffff", 1.1);
        brush.line(gf.x - 1.5, gf.y, gf.x + 1.5, gf.y);
        brush.line(gf.x, gf.y - 1.5, gf.x, gf.y + 1.5);
      }
    } else {
      brush.set("rotring", "#9e6d14", 0.9);
      brush.circle(gf.x, gf.y, gf.sz * 0.42, 0.2);
    }
  }
}

