// Helper for drawing closed shapes with beginShape/vertex/endShape
function traceShape(pts, curvature = 0.25, closeShape = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

// Helper for dry pastel mass shapes
function pastelMass(pts, col, strength = 0.65, precision = 0.55, gradient = 0.35, curvature = 0.28) {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.mass("pastel_chalk", col, {
    precision: precision,
    strength: strength,
    gradient: gradient,
    outline: false
  });
  traceShape(pts, curvature, true);
  brush.noMass();
}

// Helper for soft pastel wash + bleed
function softPastelFill(pts, col, opacity = 65, bleed = 0.35, tex = 0.35, curvature = 0.3) {
  brush.noStroke();
  brush.noMass();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.08);
  traceShape(pts, curvature, true);
  brush.noFill();
}

// Helper for directional colored-pencil / pastel hatching inside an anatomical plane
function hatchPlane(pts, brushName, col, weight, dist, angle, randVal = 0.08, curvature = 0.25) {
  brush.noStroke();
  brush.noFill();
  brush.noMass();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, { rand: randVal, continuous: false, gradient: 0.25 });
  traceShape(pts, curvature, true);
  brush.noHatch();
}

// Helper for curved anatomical pencil strokes
function pencilCurve(x1, y1, cx, cy, x2, y2, brushName, col, weight, p1 = 0.4, p2 = 1.0, p3 = 0.3) {
  brush.set(brushName, col, weight);
  brush.spline([
    [x1, y1, p1],
    [cx, cy, p2],
    [x2, y2, p3]
  ], 0.5);
}

