    let ang = lerp(-115, -25, t) + random(-8, 8);
    let len = random(9, 16);
    brush.set("ultra_pencil", "#0f172a", 0.9);
    brush.line(lx, ly, lx + cos(ang) * len, ly + sin(ang) * len);
  }
  // Clumped white & icy-pink frost on Near Eye upper lashes
  for (let i = 0; i < 48; i++) {
    let t = random(0.05, 0.98);
    let lx = lerp(544, 644, t);
    let ly = lerp(446, 440, t) - sin(t * 180) * 13 + random(-2, 2);
    let ang = lerp(-115, -22, t) + random(-12, 12);
    let len = random(8, 17);
    let fcol = random(["#ffffff", "#ffffff", "#e0f2fe", "#ffe0e9"]);
    brush.set("frost_needle", fcol, random(0.85, 1.45));
    brush.line(lx, ly, lx + cos(ang) * len, ly + sin(ang) * len);
  }
  // Near Eye lower lashes with clinging frost
  for (let i = 0; i < 38; i++) {
    let t = random(0.08, 0.96);
    let lx = lerp(546, 642, t);
    let ly = lerp(452, 443, t) + sin(t * 180) * 6 + random(-1, 2);
    let ang = lerp(115, 42, t) + random(-14, 14);
    let len = random(7, 15);
    let fcol = random(["#ffffff", "#ffffff", "#bae6fd", "#ffd1dc"]);
    brush.set("frost_needle", fcol, random(0.75, 1.3));
    brush.line(lx, ly, lx + cos(ang) * len, ly + sin(ang) * len);
  }
  // Far Eye upper & lower frosted lashes (projecting out toward the left profile!)
  for (let i = 0; i < 32; i++) {
    let t = random(0, 0.9);
    let lx = lerp(402, 448, t);
    let ly = lerp(441, 442, t) - sin(t * 180) * 9;
    let ang = lerp(-162, -95, t) + random(-12, 12);
    let len = random(9, 17);
    let fcol = random(["#ffffff", "#ffffff", "#ffe4ec", "#e0f2fe"]);
    brush.set("frost_needle", fcol, random(0.85, 1.4));
    brush.line(lx, ly, lx + cos(ang) * len, ly + sin(ang) * len);
  }
  for (let i = 0; i < 24; i++) {
    let t = random(0, 0.85);
    let lx = lerp(404, 446, t);
    let ly = lerp(449, 448, t) + sin(t * 180) * 4;
    let ang = lerp(155, 95, t) + random(-12, 12);
    let len = random(7, 13);
    brush.set("frost_needle", random(["#ffffff", "#ffd6e0", "#e0f2fe"]), random(0.75, 1.25));
    brush.line(lx, ly, lx + cos(ang) * len, ly + sin(ang) * len);
  }

  // =========================================================================
  // 7. NOSE CONTOURS & CHAPPED, SUNBURNED LIPS
  // =========================================================================

  // Crisp 3/4 nasal profile contour & nostril cavity
  pencilCurve(455, 426, 412, 495, 372, 566, "color_pencil", "#ffded9", 1.15, 0.5, 1.2, 0.8);
  pencilCurve(372, 566, 385, 588, 428, 602, "color_pencil", "#b81d48", 1.2, 0.8, 1.1, 0.6);
  // Deep nostril opening
  pastelMass(
    [[436, 586], [464, 580], [476, 594], [445, 598]],
    "#1c061f", 0.95, 0.85, 0.1
  );
  pencilCurve(434, 588, 456, 578, 478, 594, "ultra_pencil", "#09020d", 1.6, 0.6, 1.3, 0.6);
  // Alar crease around nostril wing
  pencilCurve(482, 548, 502, 570, 488, 596, "color_pencil", "#3d0e3b", 1.3, 0.5, 1.2, 0.6);
  pencilCurve(480, 548, 498, 570, 485, 594, "ultra_pencil", "#ff7585", 0.85, 0.4, 1.0, 0.4);

  // --- CHAPPED, SUNBURNED LIPS (x: 402..546, y: 642..712) ---
  // Upper lip vermilion (darker sunburned carmine-red in angled shadow, rose-coral on left)
  pastelMass(
    [[404, 658], [428, 644], [448, 648], [485, 646], [542, 674], [482, 672], [412, 668]],
    "#8f1133", 0.85, 0.75, 0.25
  );
  pastelMass(
    [[404, 658], [428, 645], [462, 650], [455, 668], [410, 666]],
    "#d9234b", 0.85, 0.75, 0.3
  );
  // Right side of upper lip turning into plum-violet shadow
  pastelMass(
    [[480, 650], [542, 674], [512, 676], [472, 670]],
    "#4a1248", 0.8, 0.75, 0.3
  );

  // Lower lip vermilion (full, swollen, fiercely sunburned & wind-chapped)
  pastelMass(
    [[406, 672], [475, 672], [538, 675], [515, 706], [448, 712], [404, 692]],
    "#b8143a", 0.9, 0.75, 0.25
  );
  pastelMass(
    [[405, 674], [468, 674], [492, 696], [442, 708], [404, 690]],
    "#ff2e55", 0.85, 0.75, 0.3
  );
  // Sunburned blistered highlight on left-center swell of lower lip
  pastelMass(
    [[410, 676], [458, 677], [465, 694], [415, 695]],
    "#ff7588", 0.8, 0.8, 0.3
  );
  // Shadow side of lower lip (right corner)
  pastelMass(
    [[482, 674], [538, 675], [516, 704], [475, 704]],
    "#571248", 0.8, 0.75, 0.3
  );

  // Parted mouth line (exhausted, gasping thin summit air)
  pencilCurve(405, 666, 465, 672, 544, 675, "color_pencil", "#1f0419", 1.75, 0.7, 1.4, 0.8);
  pencilCurve(414, 668, 458, 672, 512, 674, "ultra_pencil", "#0a0108", 1.6, 0.6, 1.3, 0.6);

  // Chapped vertical lip fissures, raw sunburn cracks & peeling skin scales!
  const lipCracks = [
    // Lower lip fissures
    [414, 672, 412, 686, 414, 700],
    [426, 672, 424, 688, 427, 705],
    [439, 673, 438, 690, 442, 708],
    [454, 673, 455, 691, 458, 709],
    [469, 673, 472, 690, 476, 707],
    [485, 674, 489, 689, 493, 704],
    [502, 674, 506, 688, 509, 701],
    [518, 675, 521, 686, 523, 696],
    // Upper lip fissures
    [416, 648, 415, 658, 416, 667],
    [430, 645, 429, 656, 430, 668],
    [446, 648, 446, 658, 447, 669],
    [464, 648, 466, 659, 467, 670],
    [484, 650, 486, 660, 487, 671],
    [504, 656, 506, 664, 507, 672]
  ];
  for (let lc of lipCracks) {
    // Deep blood-carmine chapped crack
    pencilCurve(lc[0], lc[1], lc[2], lc[3], lc[4], lc[5], "ultra_pencil", "#3d041a", 1.15, 0.5, 1.2, 0.5);
    // Peeling pale-rose sunburned skin edge right next to the fissure
    pencilCurve(lc[0] + 2.2, lc[1] + 2, lc[2] + 2.5, lc[3], lc[4] + 2, lc[5] - 2, "ultra_pencil", "#ffd6e0", 0.9, 0.4, 1.1, 0.4);
  }
  // Extra blistered/chapped skin flakes along the lower vermilion border
  for (let i = 0; i < 28; i++) {
    let lx = random(408, 505);
    let ly = random(676, 706);
    let col = random(["#ffe4ec", "#ffb3c1", "#ff2a55", "#610826"]);
    brush.set("ultra_pencil", col, random(0.7, 1.1));
    brush.line(lx, ly, lx + random(-4, 5), ly + random(-3, 4));
  }

  // =========================================================================
  // 8. FROST-CLUNG STUBBLE, BEARD & FROZEN BREATH CONDENSATION
  // =========================================================================

  // --- A. COARSE WEATHERED STUBBLE (Mustache, Chin, Jawline, Lower Cheek) ---
  // 1. Mustache stubble (x: 404..548, y: 598..665)
  for (let i = 0; i < 260; i++) {
    let t = random(0, 1);
    let mx = lerp(404, 548, t) + random(-5, 5);
    let my = lerp(602, 652, random(0, 1)) + (t > 0.5 ? (t - 0.5) * 32 : 0);
    // Keep off the lip vermilion itself
    if (my > 644 && mx < 495) my -= 14;
    let ang = lerp(108, 62, t) + random(-14, 14);
    let len = random(7, 16);
    let scol;
    if (mx < 455) {
      scol = random(["#7a1236", "#d92b54", "#ff7588", "#4a0e2e"]);
    } else if (mx < 505) {
      scol = random(["#1e293b", "#4c1d95", "#9d174d", "#64748b"]);
    } else {
      scol = random(["#0f172a", "#1e3a8a", "#3b1d7a", "#31105e"]);
    }
    brush.set("ultra_pencil", scol, random(0.65, 1.1));
    brush.line(mx, my, mx + cos(ang) * len, my + sin(ang) * len);
  }

  // 2. Chin, Soul Patch & Mandible Stubble (x: 404..765, y: 600..835)
  for (let i = 0; i < 780; i++) {
    let zone = random();
    let sx, sy, ang;
    if (zone < 0.42) {
      // Chin & soul patch (x: 406..565, y: 706..825)
      sx = random(406, 565);
      sy = random(708, 822);
      if (sx < 430 && sy > 795) continue;
      ang = map(sx, 406, 565, 112, 65) + random(-18, 18);
    } else if (zone < 0.78) {
      // Mid-jaw & lower hollow (x: 530..685, y: 655..815)
      sx = random(530, 685);
      sy = random(655, 810);
      let maxY = map(sx, 530, 685, 818, 765);
      if (sy > maxY) sy = maxY - random(2, 25);
      ang = map(sx, 530, 685, 68, 35) + random(-18, 18);
    } else {
      // Sideburn & rear jaw angle (x: 655..765, y: 495..755)
      sx = random(655, 762);
      sy = random(500, 745);
      ang = map(sy, 500, 745, 95, 45) + random(-16, 16);
    }

    let len = random(7, 17);
    let scol;
    if (sx < 475) {
      // Alpenglow side
      scol = random(["#6e1133", "#c91e48", "#ff6b7b", "#ffb3a7", "#3d0c2e"]);
    } else if (sx < 595) {
      // Prussian-blue paper midtone zone
      scol = random(["#0f172a", "#1e3a8a", "#701a52", "#475569", "#60a5fa"]);
    } else {
      // Cobalt & violet shadow side
      scol = random(["#091026", "#1d4ed8", "#3b82f6", "#4c1d95", "#6d28d9"]);
    }
    brush.set("ultra_pencil", scol, random(0.6, 1.05));
    brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }

  // --- B. FROST CLINGING TO STUBBLE (Chalky Rime + Crisp White Ice Hairs) ---
  // Soft chalky frost buildup under nostrils, on mustache, soul patch, chin & windward jaw
  pastelMass(
    [[412, 602], [488, 600], [505, 642], [406, 644]],
    "#d8f3ff", 0.65, 0.7, 0.35
  );
  pastelMass(
    [[416, 610], [468, 608], [475, 638], [410, 638]],
    "#ffe0eb", 0.6, 0.75, 0.35
  );
  pastelMass(
    [[406, 728], [525, 735], [545, 808], [445, 820], [406, 780]],
    "#bae6fd", 0.6, 0.65, 0.4
  );
  pastelMass(
    [[410, 745], [495, 752], [508, 812], [420, 798]],
    "#ffffff", 0.65, 0.7, 0.35
  );

  // Hundreds of individual white & icy-cyan frost-encrusted stubble hairs
  // 1. Heavy frost on mustache & around mouth corners (from freezing breath!)
  for (let i = 0; i < 220; i++) {
    let t = random(0, 1);
    let fx = lerp(402, 545, t) + random(-5, 5);
    let fy = lerp(598, 650, random(0, 1)) + (t > 0.55 ? (t - 0.55) * 35 : 0);
    if (fy > 643 && fx < 495) fy -= 12;
    let ang = lerp(110, 60, t) + random(-18, 18);
    let len = random(6, 15);
    let fcol = fx < 465 ? random(["#ffffff", "#ffffff", "#ffe4ec", "#e0f2fe"]) : random(["#ffffff", "#bae6fd", "#93c5fd"]);
    brush.set("frost_needle", fcol, random(0.65, 1.25));
    brush.line(fx, fy, fx + cos(ang) * len, fy + sin(ang) * len);
  }

  // 2. Heavy frost on chin, soul patch, and lower jaw stubble
  for (let i = 0; i < 420; i++) {
    let fx = random(402, 665);
    let fy = random(708, 825);
    let maxY = fx < 540 ? 824 : map(fx, 540, 665, 820, 765);
    if (fy > maxY) fy = maxY - random(1, 20);
    if (fx > 545 && fy < 735 && random() < 0.45) continue; // taper frost density toward upper shadow cheek
    let ang = map(fx, 402, 665, 115, 45) + random(-20, 20);
    let len = random(6, 16);
    let fcol;
    if (fx < 485) {
      fcol = random(["#ffffff", "#ffffff", "#fff0f5", "#e0f7ff"]);
    } else if (fx < 575) {
      fcol = random(["#ffffff", "#e0f2fe", "#bae6fd", "#ffd6e0"]);
    } else {
      fcol = random(["#e0f2fe", "#7dd3fc", "#c4b5fd", "#ffffff"]);
    }
    brush.set("frost_needle", fcol, random(0.6, 1.2));
    brush.line(fx, fy, fx + cos(ang) * len, fy + sin(ang) * len);
  }

  // 3. Frost rim along the windward left parka hood & collar edge
  for (let i = 0; i < 110; i++) {
    let t = random(0, 1);
    let fx = lerp(310, 415, t) + random(-12, 12);
    let fy = lerp(960, 770, t) + random(-10, 10);
    let ang = random(-155, -45);
    let len = random(8, 19);
    brush.set("frost_needle", random(["#ffffff", "#ffe4ec", "#e0f2fe"]), random(0.7, 1.3));
    brush.line(fx, fy, fx + cos(ang) * len, fy + sin(ang) * len);
  }

  // --- C. FLEETING FROZEN BREATH VAPOR PLUME ---
  softPastelFill(
    [[245, 620], [345, 595], [412, 608], [408, 688], [315, 710], [215, 675]],
    "#ffccd8", 28, 0.5, 0.2, 0.35
  );
  softPastelFill(
    [[285, 635], [375, 610], [410, 665], [335, 685]],
    "#e0f2fe", 32, 0.5, 0.2, 0.35
  );
  pencilCurve(402, 605, 335, 612, 245, 645, "soft_blur", "#ffe4ec", 0.85, 0.8, 1.0, 0.3);
  pencilCurve(404, 672, 325, 678, 225, 695, "soft_blur", "#bae6fd", 0.8, 0.8, 1.0, 0.3);

  // =========================================================================
  // 9. ICE CRYSTALS AS TINY OPAQUE WHITE POINTS
  //    ("Ice crystals are tiny opaque white points")
  // =========================================================================

  // Helper to place a crisp, tiny opaque white crystalline point
  function drawIcePoint(x, y, sz = 1.6, col = "#ffffff") {
    brush.set("frost_needle", col, sz);
    brush.line(x, y, x + random(-1.8, 1.8), y + random(-1.8, 1.8));
    if (random() < 0.45) {
      // Micro cross-glint on larger ice crystals
      brush.set("ultra_pencil", "#ffffff", sz * 0.75);
      brush.line(x - 2.2, y, x + 2.2, y);
      brush.line(x, y - 2.2, x, y + 2.2);
    }
  }

  // 1. Dense ice crystal points on eyelashes & eyebrows
  for (let i = 0; i < 85; i++) {
    // Near eye lashes
    let t = random(0.04, 0.96);
    let isUpper = random() < 0.65;
    let ix = lerp(544, 644, t) + random(-4, 4);
    let iy = isUpper
      ? lerp(444, 438, t) - sin(t * 180) * 14 + random(-8, 3)
      : lerp(453, 444, t) + sin(t * 180) * 8 + random(-2, 7);
    drawIcePoint(ix, iy, random(1.2, 2.2), random(["#ffffff", "#ffffff", "#e8f8ff"]));
  }
  for (let i = 0; i < 45; i++) {
    // Far eye lashes
    let t = random(0, 0.9);
    let ix = lerp(395, 446, t) + random(-5, 3);
    let iy = lerp(438, 448, t) + random(-9, 8);
    drawIcePoint(ix, iy, random(1.1, 2.1), "#ffffff");
  }
  for (let i = 0; i < 95; i++) {
    // Eyebrows
    let isNear = random() < 0.72;
    let t = random(0, 1);
    let ix = isNear ? lerp(508, 675, t) : lerp(390, 456, t);
    let iy = (isNear ? lerp(398, 404, t) - sin(t * 175) * 18 : lerp(400, 398, t) - sin(t * 180) * 11) + random(-9, 8);
    drawIcePoint(ix + random(-4, 4), iy, random(1.1, 2.1), random(["#ffffff", "#ffffff", "#ffeef2"]));
  }

  // 2. Dense ice crystal points clinging to mustache, chapped lips, chin & jaw stubble
  for (let i = 0; i < 340; i++) {
    let r = random();
    let ix, iy;
    if (r < 0.35) {
      // Mustache & nostril rim
      ix = random(402, 542);
      iy = random(594, 650);
    } else if (r < 0.45) {
      // Chapped lower lip edge & mouth corners
      ix = random(404, 535);
      iy = random(668, 708);
    } else {
      // Chin, soul patch & jaw stubble
      ix = random(404, 675);
      iy = random(708, 825);
      let maxY = ix < 540 ? 825 : map(ix, 540, 675, 820, 760);
      if (iy > maxY) iy = maxY - random(2, 18);
    }
    let col = ix < 490 ? random(["#ffffff", "#ffffff", "#fff0f5"]) : random(["#ffffff", "#e0f7ff"]);
    drawIcePoint(ix, iy, random(1.0, 2.2), col);
  }

  // 3. Scattered ice crystal points on windward nose tip, cheekbone, beanie & collar, and diamond-dust in air
  for (let i = 0; i < 160; i++) {
    let zone = random();
    let ix, iy;
    if (zone < 0.3) {
      // Cheekbone & nose bridge
      ix = random(375, 625);
      iy = random(465, 585);
    } else if (zone < 0.6) {
      // Beanie edge & parka collar
      if (random() < 0.5) {
        ix = random(415, 760);
        iy = random(165, 275);
      } else {
        ix = random(285, 455);
        iy = random(765, 1080);
      }
    } else {
      // Diamond dust suspended in freezing air & breath plume on left
      ix = random(140, 420);
      iy = random(480, 780);
    }
    drawIcePoint(ix, iy, random(0.9, 1.9), random(["#ffffff", "#ffffff", "#e8f8ff", "#ffe8f0"]));
  }

  // Final micro-spray of crystalline white dust over the frost zones
  brush.set("ice_stipple", "#ffffff", 1.1);
  brush.line(412, 615, 488, 632);
  brush.line(415, 745, 515, 795);
  brush.line(525, 390, 645, 392);
  brush.line(548, 438, 638, 436);

  noLoop();
}
